{"assumptions":[],"created_at":"2026-10-27T05:50:44.875994+00:00","domain":"probability theory","id":"claim_002a50072797d4d4428f55f1af498a4f023917ec53d7729179ef825b73642f7d","kind":"theorem","schema_version":1,"statement":"[Proposition 55 (Second-order singular block profiles) of arXiv:2607.16724, 'Algebraic Transfer for Operator-Valued Gaussian Chaoses: Oriented Schatten Profiles and Si'] Assume \eqref{eq:group-growth}, let
\[
 \frac D4<\sigma\le\frac D2,\qquad
 c_x=\langle x\rangle^{-\sigma},\qquad
 \beta:=D-2\sigma,\qquad
 \gamma:=4\sigma-D,
\]
and set
\begin{equation}

 \omega_\sigma(R):=
 \begin{cases}
  R^\beta,&D/4<\sigma<D/2,\\
  \log(e+R),&\sigma=D/2.
 \end{cases}
\end{equation}
For $L,Q\in\Dya$, write
$R_+:=\max\{L,Q\}$ and $R_-:=\min\{L,Q\}$.  Then, for
$2\le r\le\infty$ and every $N\ge1$,
\begin{equation}

 \Prof_{2,r}(K_{2,N}^{L,Q}(c))
 \le C_{\Gamma,D,\sigma,r}
 \omega_\sigma(R_+)R_-^{D/r},
\end{equation}
where $R_-^{D/r}=1$ at $r=\infty$.  For $N\ge M\ge1$,
\begin{align}

 &\Prof_{2,r}\bigl(
 K_{2,N}^{L,Q}(c)-K_{2,M}^{L,Q}(c)
 \bigr)\notag\\
 &\qquad\le C_{\Gamma,D,\sigma,r}
 \omega_\sigma(R_+)R_-^{D/r}
 \min\left\{1,
 \left(\frac{R_+}{M}\right)^{\gamma/2}\right\}.
\end{align}","status":"unverified"}

