\begin{equation}
\Sigma=\int_{0}^{\infty}\exp\left\{\left(J_{G}(\theta^{*})+I_{d}/2\right)u\right\}\Gamma\left[\exp\left\{\left(J_{G}(\theta^{*})+I_{d}/2\right)u\right\}\right]^{t}du.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:41:54.369521+00:00","domain":"probability theory","id":"claim_003bbf8826fe291399fedbe5322f1bb69f67b77e27d43c1fb4a86d8621172e0d","kind":"concept","schema_version":1,"statement":"[Lemma lem:Young_with_blow_up of arXiv:2412.01645, 'Regularisation by Gaussian rough path lifts of fractional Brownian motions'] Let $s \in [0,1]$,  $\alpha, \beta \in (0,1)$ such that $\alpha+ \beta >1$ and let $\gamma \in (0, \beta)$. Then, for all $f \in \mathcal{C}^\alpha([s,1])$, $g \in \mathcal{C}^\beta_\gamma([s,1])$ and  $(u,t) \in [0,1]^2_{\leq}$, we have 
\begin{equs}
\big| \int_u^t f_{u,r} \, dg_r \big| \lesssim [f]_{\mathcal{C}^\alpha} [g]_{\mathcal{C}^\beta_\gamma} |t-u|^{\beta+\alpha -\gamma}.
\end{equs} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:05:28.235837+00:00","domain":"probability theory","id":"claim_0042f9abe77f1baef990090be47569ec3c0e55fb0c2fd86506a4aed7543c033a","kind":"concept","schema_version":1,"statement":"[Proposition prop: BDG of arXiv:2602.04429, 'Disordered systems and (subcritical) polynomial chaos\\ with heavy-tail disorder'] Let $(M_n)_{n \, \geqslant\, 1}$ be a martingale with respect to $(\mathcal{F}_n)_{n \, \geqslant\, 1}$ such that $M_0 = 0$. 
	Denote $\langle M \rangle$ its quadratic variation, \textit{i.e.}\ \(\langle M \rangle^2  = \sum_{n \, \geqslant\, 1} (M_n - M_{n-1})^2 \) and $M^* = \sup_{n \, \geqslant\, 1} |M_n|$. 
	Then, for any $p \, \geqslant\, 1$, there is a constant $C_p$ which depends only on $p$ (and is bounded by a constant uniformly in \(p\in [1,2]\)) such that 
	\begin{equation}
	\frac{1}{C_p} \, \mathds{E}\big[\langle M \rangle^{p/2}\big] \, \leqslant\, \mathds{E}\big[(M^*)^p\big] \, \leqslant\, C_p\, \mathds{E}\big[\langle M \rangle^{p/2}\big].
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

