{"assumptions":[],"created_at":"2026-10-27T15:46:00.392550+00:00","domain":"probability theory","id":"claim_00f0b0bd40a8e44895a0b6d7fb8d554a936fa2698ee40cd0949dc281ee7720c8","kind":"concept","schema_version":1,"statement":"[Proposition pr:mSHE-characterization of arXiv:2607.21443, 'The critical KPZ scale for the averaging process'] {parekh_moment_2025}}]
Let $(\ensuremath{\mathcal Z}_{s,t})_{s\le t}$ be a family of $\mathscr M(\mathbb{R}^2)$-valued random variables indexed by $-\infty <s\le t<\infty$ with $s,t \in \mathbb Q$, all defined on some complete probability space $(\Omega,\ensuremath{\mathcal F},\mathbb{P})$. Fix $\gamma >0$,  and suppose that the following conditions hold true:
\begin{enumerate}[(1)]
    \item $\ensuremath{\mathcal Z}_{s_j,t_j}$ are independent under $\mathbb{P}$ whenever $(s_j,t_j)$ are disjoint intervals.
    \item For all functions $f\in \ensuremath{\mathcal C}_c^\infty(\mathbb{R}^2)$, $\psi \in \ensuremath{\mathcal C}_c^\infty(\mathbb{R})$ with $\int_\mathbb{R}\psi=1$, and indices $s<t<u$, 
    \begin{equation}
    \begin{aligned}
    &\int_{\mathbb{R}^4} \varepsilon^{-1}\psi(\varepsilon^{-1}(y_1-y_2))\, f(x,z)\, \ensuremath{\mathcal Z}_{t,u}({\rm d} y_1,{\rm d} z)\ensuremath{\mathcal Z}_{s,t}({\rm d} x,{\rm d} y_2)\\
    &\qquad\xrightarrow[\varepsilon\to 0]{\mathbb{P}} \int_{\mathbb{R}^2} f(x,z)\,\ensuremath{\mathcal Z}_{s,u}({\rm d} x,{\rm d} z)\; \text{,}\;\;
    \end{aligned}
    \end{equation}
    where the above convergence holds in $\mathbb{P}$-probability.
    \item For all integers $k\ge 1$, functions $\phi,\psi \in \ensuremath{\mathcal C}_c^\infty(\mathbb{R})$, and indices $s<t$,
    \begin{equation}
    \begin{aligned}
&\mathbb{E}\bigg[\bigg(\int_{\mathbb{R}^2}\phi(x)\psi(y)\,\ensuremath{\mathcal Z}_{s,t}({\rm d} x,{\rm d} y)\bigg)^k\bigg]\\
&= \int_{\mathbb{R}^k} \prod_{j=1}^k \phi(x_j)\mathbf E_{(x_1,\ldots,x_k)}^{{\rm BM}^{\otimes k}}\bigg[\exp\bigg\{\gamma^2 \sum_{1\le i<j\le k} L_{t-s}^{W^i-W^j}\bigg\}\prod_{j=1}^k \psi(W_{t-s}^j)\bigg]{\rm d} x_1\cdots {\rm d} x_k\; \text{,}\;\;
\end{aligned}
    \end{equation}
    where, as before (see, e.g., the text above Proposition (pr:second-moment of the paper)), the expectation is with respect to a $k$-dimensional standard Brownian motion $\mathbf W=(W^1,\ldots,W^k)$ started at $\mathbf x\in \mathbb{R}^k$, while $L_t$ stands for the local time at the origin in the time interval $[0,t]$ for the process in the superscript.
\end{enumerate}

Then, there exists a $\ensuremath{\mathcal C}(\mathbb{R}_\uparrow^4)$-valued random element $\tilde \ensuremath{\mathcal Z}=(\tilde \ensuremath{\mathcal Z}_{s,t}(x,z))_{(s,t,x,z)\in \mathbb{R}_\uparrow^4}$, defined on the same probability space and satisfying, for every $\psi\in \ensuremath{\mathcal C}_c(\mathbb{R})$, $\phi\in \ensuremath{\mathcal C}_b(\mathbb{R})$, and $s<t$ in ${\mathbb Q}$, 
\begin{equation}
 \ensuremath{\mathcal Z}_{s,t}(\psi\otimes \phi)= \int_{\mathbb{R}^2}\psi(x)\phi(z)\,\tilde \ensuremath{\mathcal Z}_{s,t}(x,z)\,{\rm d} x{\rm d} z\; \text{,}\;\;\qquad \mathbb{P}\text{-a.s.}\; \text{.}
\end{equation}
Furthermore, on the same probability space, there exists a space-time white noise $\xi$ on $\mathbb{R}^2$, with the property that $(\tilde \ensuremath{\mathcal Z}_{s,t})_{s\le t}$ is the \textit{propagator} of the multiplicative ${\rm SHE}$ in (equation eq:mSHE of the paper), driven by $\xi$ and with noise coefficient $\gamma>0$. More precisely, for all $s,x \in \mathbb{R}$, 
\begin{equation}
(t,y)\in (s,\infty)\times \mathbb{R}\longmapsto \tilde \ensuremath{\mathcal Z}_{s,t}(x,y)
\end{equation}
is, $\mathbb{P}$-a.s., the It\^o--Walsh solution to the equation in (equation eq:mSHE of the paper) started from $s$ with initial datum $\delta_x$. Further,
$t\longmapsto \tilde \ensuremath{\mathcal Z}_{s,t}(x,{\,\cdot\,})$ may be realized as a process in $\ensuremath{\mathcal C}([s,\infty),\ensuremath{\mathcal M}_f(\mathbb{R}))$.

Consequently, for any finite collection of indices $s_1\le t_1, \ldots, s_m\le t_k$ in ${\mathbb Q}$, the finite-dimensional laws $(\ensuremath{\mathcal Z}_{s_1,t_1},\ldots, \ensuremath{\mathcal Z}_{s_m,t_m})$ are uniquely determined by the conditions in (it:SHE1 of the paper)--(it:SHE3 of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

