\noindent The next result shows the behavior of the tails of the product of random variables $T$ and $V$, which represent waiting times and velocities respectively in the critical case $\alpha=\beta$.
\begin{lemma}
    Let $V, T$ be independent, positive heavy-tailed random variables with the same index of stability $\alpha$. Then
\begin{equation}
    \mathbb{P}(VT > z) \sim \alpha z^{-\alpha}\log z, \quad \text{as } z \to \infty.
\end{equation}
\begin{proof}
By the definition of asymptotic equivalence, for any arbitrarily small $\epsilon > 0$, there exists a sufficiently large $M > 0$ such that for all $x \ge M$, we have
\begin{equation}
    (1-\epsilon)x^{-\alpha} \le \bar{F}_V(x) \le (1+\epsilon)x^{-\alpha}.
\end{equation}
Using the law of total probability and the conditioning on $T = x$, the tail of the product is given by
\begin{equation}
    H(t) = \mathbb{P}(T V > t) = \int_0^\infty \mathbb{P}(V > t/x) dF_T(x) = \int_0^\infty \bar{F}_V(t/x) dF_T(x).
\end{equation}
Assume $t$ is large enough such that $t > M^2$ (which implies $M < t/M$). We split the integral in Eq. \eqref{eqint} into three parts
\begin{equation}
    H(t) = \int_0^M \bar{F}_V(t/x) dF_T(x) + \int_M^{t/M} \bar{F}_V(t/x) dF_T(x) + \int_{t/M}^\infty \bar{F}_V(t/x) dF_T(x) = I_1(t) + I_2(t) + I_3(t).
\end{equation}
First, let us analyze $I_1(t)$. Since $x \in (0, M]$, thus we have $t/x \ge t/M \ge M$. Applying the upper bound from \eqref{eq:epsilon_bound}, we have
\begin{equation}
    I_1(t) \le \int_0^M (1+\epsilon)(t/x)^{-\alpha} \, dF_T(x) = (1+\epsilon)t^{-\alpha} \int_0^M x^\alpha \, dF_T(x).
\end{equation}
Because $\int_0^M x^\alpha \, dF_T(x)\le M^{\alpha}\int_0^M dF_T(x)\leq M^{\alpha}$, where $M^{\alpha}$ is a finite constant independent of $t$, thus $I_1(t) = \mathcal{O}(t^{-\alpha})$. For $I_3(t)$, we use the trivial bound that probability is not greater than $1$ and obtain
\begin{equation}
    I_3(t) = \int_{t/M}^\infty \mathbb{P}(V > t/x) \, dF_T(x) \le \int_{t/M}^\infty 1 \, dF_T(x) = \bar{F}_T(t/M).
\end{equation}
Since $t/M \ge M$, thus $\bar{F}_T(t/M) \sim (t/M)^{-\alpha} = M^\alpha t^{-\alpha}$. Therefore, $I_3(t) = \mathcal{O}(t^{-\alpha})$. \\
Since both $I_1(t)$ and $I_3(t)$ lack a logarithmic factor, they are negligible compared to $t^{-\alpha} \log(t)$ as $t \to \infty$. Now, we analyze $I_2(t)$. The integration limits ensure that both $x \ge M$ and $t/x \ge M$. We can therefore apply the bounds from \eqref{eq:epsilon_bound} to the integrand $\bar{F}_V(t/x)$
\begin{equation}
    (1-\epsilon) t^{-\alpha} \int_M^{t/M} x^\alpha \, dF_T(x) \le I_2(t) \le (1+\epsilon) t^{-\alpha} \int_M^{t/M} x^\alpha \, dF_T(x).
\end{equation}
Let $J(y) = \int_M^y x^\alpha \, dF_T(x)$ where $y = t/M$. Using integration by parts and noting that $dF_T(x) = -d\bar{F}_T(x)$, we have
\begin{equation}
\begin{aligned}
    J(y) &= -\int_M^y x^\alpha \, d\bar{F}_T(x) = -\left( \left[ x^\alpha \bar{F}_T(x) \right]_M^y - \int_M^y \bar{F}_T(x) \, d(x^\alpha) \right) \\
         &= M^\alpha \bar{F}_T(M) - y^\alpha \bar{F}_T(y) + \int_M^y \bar{F}_T(x) \alpha x^{\alp (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

