\end{equation}
Furthermore,
\begin{equation}
    \diam\Big(\ClCp{1}{p_0} \Big) \leq  \diam (\cT ) \leq \diam\Big( \ClCp{1}{p_0} \Big) + \bigO{\frac{n^{1/3}}{\sqrt{\epsilon n^{1/3}}} + (\log n)^6} 
