{"assumptions":[],"created_at":"2026-10-27T06:21:45.379659+00:00","domain":"probability theory","id":"claim_01afce7ee8ec1cf2ab0fadf75783082f934036c9ef8cac69e9fafcd8200f2b67","kind":"theorem","schema_version":1,"statement":"[Prop 21 (Metric distortion of rectified triangulation) of arXiv:2607.27535, 'Universal topological statistics on \\ triangulated singular spaces'] Let $\phi: K \rightarrow M$ be a $C^2$ triangulation of a compact set $M \subset \RR^D$ and let $\psi: \widetilde{K} \rightarrow M$ be its rectification. Then for every pair of points $x, y \in \widetilde{K}$, the following holds if $\alpha\beta < 1$:
    \begin{align} 
        \frac{\dist_{M} (\psi(x), \psi(y) )}{\dist_{\widetilde{K}} (x, y)} \in \bigg[ \frac{1-\alpha \beta}{1+\alpha \beta}, \>\> \frac{1+\alpha \beta}{1-\alpha \beta} \bigg]
    \end{align}
    where $\alpha, \beta$ are given as follows\footnote{Note that $\beta$ depends on simplices of $K$, not simplices of $\widetilde K$.}:
    \begin{align*}
        \alpha = \frac{\sup_{x \in K} \| \hess_x \phi \|_{\mathsf{op}}}{\inf_{x \in K} \sing_{\min}(\Diff_x \phi)}, \quad \beta = \sqrt{d}\cdot \max_{\sigma \in K}  \frac{\diam(\sigma)^2}{\sthick(\sigma)}
    \end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:17:42.306044+00:00","domain":"probability theory","id":"claim_01b2db2deaf4f735fe634c0612e155d8f95cedca0c40e1898f945722e0a665ee","kind":"definition","schema_version":1,"statement":"[Defn 71 (Elliptic H\"older spaces) of arXiv:2510.22155, 'Random walks in space-time random media in all spatial dimensions: the full subcritical fl'] For $\alpha\in(0,1)$ we define the space $C^{\alpha,\tau}(\mathbb R^d)$ to be the completion of $C_c^\infty(\mathbb R)$ with respect to the norm given by $$\|f\|_{C^{\alpha,\tau}(\mathbb R^d)}:= \sup_{x\in\mathbb R^d} \frac{|f(x)|}{w(x)} + \sup_{|x-y|\leq 1} \frac{|f(x)-f(   y)|}{w(x)|x-y|^{\alpha}}.$$
		For $\alpha<0$ we let $r=-\lfloor \alpha\rfloor$ and we define $C^{\alpha,\tau}(\mathbb R^d)$ to be the completion of $C_c^\infty(\mathbb R)$ with respect to the norm $$\|f\|_{C^{\alpha,\tau}(\mathbb R^d)}:= \sup_{x\in\mathbb R} \sup_{\lambda\in (0,1]} \sup_{\phi \in B_r} \frac{(f,S^\lambda_{x}\phi)_{L^2(\mathbb R)}}{w(x)\lambda^\alpha}$$ where the scaling operators $S^\lambda_{x}$ are defined by 
  \begin{align}
  S^\lambda_{x}\phi (y) = \lambda^{-d}\phi(\lambda^{-1}(x-y)),\end{align} 
  and where $B_r$ is the set of all smooth functions of {$C^r$ norm} less than 1 with support contained in the unit ball of $\mathbb R^d$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:37:08.321124+00:00","domain":"probability theory","id":"claim_01b448302728f36de2d1567fe8bdafe0c905ad899a5a7cc365895711bce08527","kind":"lemma","schema_version":1,"statement":"[Lemma lem:coefficient_bounds of arXiv:2608.31071, 'Global smooth solutions to the inhomogeneous Landau--Fermi--Dirac equation'] Suppose $g \in L^\infty_m(\mathbb R^3)$ for some $m \in (2,3) \cup(3,\infty)$. Then,
    \begin{equation*}
        \left\vertA[g](v)\right\vert \lesssim \left(\left\langle v \right\rangle^{-1} + \left\langle v \right\rangle^{2-m}\right) \left\|g\right\|_{L^\infty_m}.
    \end{equation*}
    Similarly, if $g\in L^\infty_m(\mathbb R^3)$ for some $m \in (1,3)\cup (3,\infty)$, then
    \begin{equation*}
        \left\vert\nabla a[g](v)\right\vert \lesssim \left(\left\langle v \right\rangle^{-2} + \left\langle v \right\rangle^{1 - m}\right)\left\|g\right\|_{L^\infty_m}.
    \end{equation*}
    If $m>5$, we have the improved estimate
    \begin{equation}
        A[g] \lesssim \left(\frac{\Pi(v)}{\left\langle v \right\rangle} + \frac{\mathrm{Id} - \Pi(v)}{\left\langle v \right\rangle^3}\right) \|g\|_{L^\infty_m}.
    \end{equation}
    The implicit constant above depends only on $m-5$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:54:53.447807+00:00","domain":"probability theory","id":"claim_01b58fecbb056afc02715376f6d8bb07443e5effacf1425e6d633d0549d9b4ad","kind":"theorem","schema_version":1,"statement":"[Theorem 18 of arXiv:2606.15843, 'Long-time behaviour of DLRA for SDEs'] Suppose Assumptions (H3) and (H7) hold. 
	For any initial condition $\zeta\in L^2(\Omega,V_r(\bb R^d))$ and $\xi\in L^2(\Omega,\bb R^r)$ and any $T\ge0$, there exists a constant $C(b,\sigma,T)$ such that 
    \begin{equation}
        \begin{aligned}
