{"assumptions":[],"created_at":"2026-10-27T13:54:12.220904+00:00","domain":"probability theory","id":"claim_0213f6ae83781ff21ae6bf7c2e8859be72b9be4532f50beef43ec0e42c775352","kind":"definition","schema_version":1,"statement":"[Definition eqn:Ppos of arXiv:2603.01322, 'Gibbs conditioning, atypical consensus and splitting Gibbs measures on random regular grap'] Given any countable discrete set $\mathcal{Z}$ and $\mu\in \P(\mathcal{Z})$, we say that $\mu$ lies {\em in the interior} (of $\P(\mathcal{Z})$) if $\mu(z)>0$ for all $z\in \mathcal{Z}$. Otherwise, we say that $\mu$ lies {\em on the boundary} (of $\P(\mathcal{Z})$). The collection of all probability measures in the interior and the collection of all probability measures on the boundary are denoted, respectively,  by
\begin{align}
    \Ppos(\mathcal{Z})&\coloneqq \pr{\mu\in \P(\mathcal{Z}):\mu(z)>0 \, \forall z\in \mathcal{Z}};\\
    \Pzero(\mathcal{Z})&\coloneqq \pr{\mu\in \P(\mathcal{Z}):\exists z_*\in \mathcal{Z}\text{ s.t. }\mu(z_*)=0}.
\end{align}
We also define analogous subsets of symmetric measures as follows:
\begin{align}
        \Psympos{\X}&\coloneqq \pr{\pi\in \Psym{\X}: \pi(x,z)>0 \, \forall x,z\in \X}; \\
        \Psymzero{\X}&\coloneqq \pr{\pi\in \Psym{\X}: \exists \, x,z\in \X \text{ such that } \pi(x,z)=0}. 
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:54:15.634613+00:00","domain":"probability theory","id":"claim_021458be9205737bd0aefb0431fb7be085cd2b10cf65a1a212969ae616efb94e","kind":"theorem","schema_version":1,"statement":"[Theorem 92 (Conditional fermionic Dol\'eans law and ideal transfer) of arXiv:2608.08756, 'Infinite-Dimensional L\'evy Area and Spectral Ancestry'] Assume that $\mathcal G_0$ reveals $R$.  Put
$E_m=\{V_T\le m\}\in\mathcal G_0$,
$M^{(m)}=\mathbf1_{E_m}M$, and $R^{(m)}=\mathbf1_{E_m}R$.
Let $\mathscr U^{x,(m)}$ denote
\eqref{eq:compact-fermionic-propagator} with $R$ replaced by $R^{(m)}$.
Then, for every $t\le T$ and $\lambda\in\mathbb R$,
\begin{equation}
 \mathbb E\!\left[
 Z_t^{\lambda,(m)}\otimes Z_t^{\lambda,(m)}\mid\mathcal G_0\right]
 =\mathscr U_{0,t}^{\lambda^2,(m)}(P_0)
 \quad\text{in }\mathcal S_1(\mathcal F_\wedge(H)),

\end{equation}
with trace at most $e^{\lambda^2m}$.  The local conditional covariance is
therefore
\begin{equation}
 C_t^{\lambda,\mathrm{loc}}
 =e^{\lambda^2\mathcal B_{R_t^c}}
  \prod_{0<s\le t}(I+\lambda^2\mathcal B_{\Delta R_s})(P_0).

\end{equation}
Its particle-two block gives the exact atomic defect
\begin{equation}
 4C_{\alpha_A,t}^{\mathrm{loc}}
 =\Lambda^2R_t-\sum_{0<s\le t}\Lambda^2\Delta R_s.

\end{equation}
Let $A$ be the chronological area of $M$ and $Q=R_T$.  For every $z\ge0$,
locally on the events $E_m$,
\begin{equation}
 \mathbb E\!\left[
 \exp\!\left(\sup_{t\le T}\mathfrak F_{A_t}(z)\right)
 \middle|\mathcal G_0\right]
 \le4\det\!\left(I+\frac z2Q\right).

\end{equation}
Consequently, if $0<p<1$ and $Q\in\mathcal S_{p,\infty}$, then for every
$0<r<2$,
\[
 \left(\mathbb E\!\left[
  \sup_{t\le T}\|A_t\|_{\mathcal S_{p,\infty}}^r
  \middle|\mathcal G_0\right]\right)^{1/r}
 \le C_{p,r}\|Q\|_{\mathcal S_{p,\infty}}.
\]
Little weak ideals transfer to little weak ideals; in particular
$Q\in\mathcal S_1$ implies
\begin{equation}
 \sup_{t\le T}n s_n(A_t)\longrightarrow0
 \qquad\text{almost surely}.

\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:51:33.329117+00:00","domain":"probability theory","id":"claim_021850a7cf2674ca6823da3af6a72a5dc4b3ca90f442e0ddb317655e40abc029","kind":"concept","schema_version":1,"statement":"[Thm comp-gl-models of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] Let $G$ be any compact Lie group. Then the functors 
