\begin{align}
\Gamma^L_{(x,s):(z,r)}\big|_{[s,T]} \in\Bigl\{\Gamma^{L,\theta-}_{(x,s)}\big|_{[s,T]}\,,\,\Gamma^{L,\theta+}_{(x,s)}\big|_{[s,T]}\Bigr\}
