& =-\frac{c_{q',p'}^{\mathcal Z/\vartheta}}{2\pi\i}\omega_{p'-q'}-\frac{c_{q',p'}^{\mathcal Z/\vartheta}}{2\pi\i}\left(\nabla \log \theta(t+u(p')-u(q'))-\nabla \log \theta(t)\right)\vec{\omega},
