{"assumptions":[],"created_at":"2026-10-27T18:44:24.713197+00:00","domain":"probability theory","id":"claim_0370cbba987346a136d15c3dab03fe3e208b6894c76222a1d5dfd304d469c19f","kind":"definition","schema_version":1,"statement":"[Definition ass:ft of arXiv:2604.20215, '\bf Edge Universality for Inhomogeneous Random Matrices II: Markov Chain Comparison and Cr'] There exist constants $ \alpha \in (0, 2]$, $c_0 > 0$, $\varepsilon,\delta > 0$, and $0 < \rho < 1$ such that the following assumptions are satisfied:
\begin{enumerate}
  \item (Normalization) Both  $f$ and $\widetilde{f}$ are probability densities
  \begin{equation}
    f(x),~\widetilde{f}(x)\ge 0, \quad \int_{\mathbb R^d} f(u)\,du \;= \int_{\mathbb R^d} \widetilde{f}(u)\,du=1;
  \end{equation}
  \item (Small-frequency control) For all $|\xi|\le \varepsilon$,
  \begin{equation}
    |\widehat f\!(\xi)|,~|\widehat {\tilde{f}}(\xi)| \le \exp(-c_0|\xi|^{\alpha}),\quad\Bigl|\widehat f\!(\xi)-\widehat {\tilde{f}}(\xi)\Bigr|\le C|\xi|^{\alpha+\delta}.
  \end{equation}
  \item (High-frequency contraction) For all $|\xi| > \varepsilon$,
  \begin{equation}
    |\widehat f(\xi)|,|\widehat{ \tilde{f}}(\xi)| \;\le\; \rho < 1;
  \end{equation}
  \item (Long-range decay) For some   constants $T, K > d$ and $C_T, C_{K} > 1$,
  \begin{equation}
      f(x),\tilde{f}(x)\le \frac{C_T}{(1+|x|)^{T}},
    \qquad |\widehat f(\xi)|, |\widehat {\tilde{f}}(\xi)| \;\le\; \frac{C_K}{(1+|\xi|)^{K}}
      \qquad  x,\xi \in \mathbb R^d.
  \end{equation}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:11:09.323465+00:00","domain":"probability theory","id":"claim_03711ad19e3818ccabdb8bf5b6cbaedc4fa8f29796a8b9c0a1082550f03d665b","kind":"definition","schema_version":1,"statement":"[Defn def-bp-basic of arXiv:2411.06301, 'Inverting the operation of conditioning a branching process on extinction'] We say that $X$ is \textbf{positive regular} if there exists $N\in\mathbbm N$ such that 
