    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:06:21.751381+00:00","domain":"probability theory","id":"claim_0379db9f2a8e67ce052f8e3150034610949a1f0fb44c5cb1a77240edc0889f33","kind":"lemma","schema_version":1,"statement":"[Lemma 49 of arXiv:2607.21374, 'Local structure at the maximum and sharp persistence asymptotics of rough fractional Brown'] Let \(F\subset(0,\infty)\cap\mathbb D\) be finite and nonempty, let
\(x\geq0\), and put
\begin{equation}
  \begin{aligned}
    Q_{F,x}
    &:=\mathcal L(G\mid G_s\geq-x,\ s\in F),\\
    g_{F,x}(t)&:=\EE_{Q_{F,x}}G_t,
    &\qquad
    Z_{F,x}(t)&:=G_t-g_{F,x}(t).
  \end{aligned}

\end{equation}
There are coefficients \(\lambda_{F,x}(s)\geq0\), \(s\in F\), such that
\begin{equation}
  g_{F,x}(t)
  =\sum_{s\in F}\lambda_{F,x}(s)K_H(t,s).

\end{equation}
Uniformly in \(F\) and \(x\geq0\),
\begin{equation}
  0\leq g_{F,x}(t)\leq g_{F,0}(t)\leq C_H|t|^H,
  \qquad t\in\mathbb R.

\end{equation}
For every \(0<a<R<\infty\), there is \(C_{H,a,R}<\infty\) such that
\begin{equation}
  |g_{F,x}(t)-g_{F,x}(s)|
  \leq C_{H,a,R}|t-s|^{2H},
  \qquad s,t\in[a,R].

\end{equation}
Consequently, for every \(R<\infty\),
\begin{equation}
  \lim_{\delta\downarrow0}\sup_{F,x}
  \sup_{\substack{s,t\in[0,R]\\|s-t|\leq\delta}}
  |g_{F,x}(t)-g_{F,x}(s)|=0,

\end{equation}
and, for every \(\varepsilon>0\),
\begin{equation}
  \lim_{\delta\downarrow0}\sup_{F,x}
  Q_{F,x}\left(
    \sup_{\substack{s,t\in[0,R]\\|s-t|\leq\delta}}
    |Z_{F,x}(t)-Z_{F,x}(s)|>\varepsilon
  \right)=0.

\end{equation}

For \(T>0\) and \(x>0\), these bounds pass to
\begin{equation}
  \mathbb P_{T,x}
  =\mathcal L(B\mid M_T\leq x)

\end{equation}
by dense finite-grid hard-wall approximation.  In particular, for every
\(A,R<\infty\), the laws of \(x-B\) on \(C([0,R])\), under
\(\mathbb P_{T,x}\) with \(T\geq R\) and \(0<x\leq A\), are tight uniformly
in \(T\) and \(x\).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:22:46.469090+00:00","domain":"probability theory","id":"claim_037fbef572c6e02260802148804880add6249ef4e7131610c5de5c2dc9997251","kind":"definition","schema_version":1,"statement":"[Definition 73 ($\gfour$-orthogonal projection onto the double-null tori $\doublenulltoritwoarg{\ubar}{u}$ and $\doublenulltoritwoarg{\ubar}{u}$-tangency) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] \hfill
	\begin{itemize}
		\item We define the $\doublenulltoritwoarg{\ubar}{u}$-projection tensorfield $\nulltorusproject$ as follows, where $\MagnitueofinnerproductofnewLandnewuL$ is the scalar function from \eqref{E:RECIPROCALOFNEGATIVENULLGEODESICVECTORFIELDINNERPRODUCT} and $\newL$, $\newuL$ are the vectorfields from \eqref{E:DOUBLENULLEIKONALFUNCTIONNORMALIZEDNULLVECTORFIELDS}:
			\begin{align}
				\nulltorusproject_\beta^\alpha & \eqdef \updelta_{\beta}^{\alpha}
				+
				\frac{1}{\MagnitueofinnerproductofnewLandnewuL}
				\newL^{\alpha} \newuL_{\beta}
				+
				\frac{1}{\MagnitueofinnerproductofnewLandnewuL}
				\newuL^{\alpha} \newL_{\beta}, 
				 \\
				& = \updelta_\beta^\alpha + \frac{1}{\MagnitueofinnerproductofLunitanduLunit} \Lunit^\alpha \uLunit_\beta + \frac{1}{\MagnitueofinnerproductofLunitanduLunit} \uLunit^\alpha \Lunit_\beta. 
			\end{align}
		\item Given any type $\binom{m}{n}$ spacetime tensorfield $\xi$, we define its $\gfour$-orthogonal projection onto $\doublenulltoritwoarg{\ubar}{u}$, denoted by $\nulltorusproject \xi$, as follows: 
			\begin{equation} 
				(\nulltorusproject \xi)_{\beta_1 \cdots \beta_n}^{\alpha_1\cdots\alpha_m} \eqdef \nulltorusproject_{\widetilde{\alpha}_1}^{\alpha_1} \cdots \nulltorusproject_{\widetilde{\alpha}_m}^{\alpha_m} \nulltorusproject^{\widetilde{\beta}_1}_{\beta_1} \cdots \nulltorusproject^{\widetilde{\beta}_n}_{\beta_n} \xi_{\widetilde{\beta}_1 \cdots \widetilde{\beta}_n}^{\widetilde{\alpha}_1 \cdots \widetilde{\alpha}_m}.
			\end{equation}
		\item Let $f$ be a scalar function. We define $\nullangrmD f$ to be the $\doublenulltoritwoarg{\ubar}{u}$-tangent one-form given by:
			\begin{align} 
				\nullangrmD f \eqdef \nulltorusproject \mathrm{d} f.
			\end{align}
			Note that $\nullangrmD f \cdot \nullgeop{x^A} = \nullgeop{x^A} f$ for $A = 2,3$.
	\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:52:17.581250+00:00","domain":"probability theory","id":"claim_0381994c94557e732ae0d9692d30267004d61c0b394a6f130b2ee7bc5933b606","kind":"concept","schema_version":1,"statement":"[Proposition eqn.412 of arXiv:2411.15485, '\bf\Large Stochastic Volterra Equations for Local Times of Spectrally Positive L\'evy Proc'] There exists a constant $\beta_0\geq 0$ such that for each $\beta \geq \beta_0$, we can always find two constants $n_0\geq 1$ and $T_0>0$ satisfying that 
