{"assumptions":[],"created_at":"2026-10-26T20:46:26.256251+00:00","domain":"probability theory","id":"claim_03cd209281fd111361a2100cc890781489aaf907db945aa1e1fb08f1f145d0ae","kind":"concept","schema_version":1,"statement":"[Prp 47 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] Let $(F,R,\mu)$ be in $\bbF^{\circ}$.
  Set $\g{c}{suffcond2,1}=\left[\mu(F)^{1/2}\g{c}{unihk,1}\right]^{2\kappa-1}$ and $\g{c}{suffcond2,2}=\left[\mu(F)^{1/2}\g{c}{c_1,1}\right]^{2\kappa-1}$.
\begin{itemize}
  \item [$\mathrm{(i)}$]If $F$ is compact, then it holds that
  \begin{align}
    \|P_th\|_{\Lip^{\kappa}}\lesssim \g{c}{unihk,1} t^{-2\kappa}\|h\|_{L^1(F,\mu)},
  \end{align}
  and
  \begin{align}
    \|P_th\|_{\Lip^{\kappa}}\lesssim \g{c}{suffcond2,1} t^{-(3\kappa-1)}\|h\|_{L^2(F,\mu)},
  \end{align}
  for any $t\in(0,1],\;\kappa\in [1/2,1],$ and $h\in L^2(F,\mu)$.

  \item [$\mathrm{(ii)}$]If $F$ is compact, and satisfies assumption $\rm{(A1)}$,
  then it holds that
  \begin{equation}
    \|P_th\|_{\Lip^{\kappa}}\lesssim\g{c}{c_1,1}t^{-\frac{2\kappa s_0+3\kappa-1}{1+s_0}}\|h\|_{L^1(F,\mu)},
  \end{equation}
  and
  \begin{equation}
    \|P_th\|_{\Lip^{\kappa}}\lesssim \g{c}{suffcond2,2} t^{-(3\kappa-1)}\|h\|_{L^2(F,\mu)},
  \end{equation}
  for any $t\in(0,1],\;\kappa\in [1/2,1],$ and $h\in L^2(F,\mu)$.
  \item [$\mathrm{(iii)}$]If $(F,R,\mu)$ satisfies assumption $\rm{(A2)}$,
  then it holds that
  \begin{equation}
    \|P_th\|_{\Lip^{\kappa}}\lesssim \g{c}{c_1,2}t^{-\frac{2[(1+s_0)\theta-s_1]\kappa+s_0\theta+s_1}{2(1+s_0)\theta}}\|h\|_{L^1(F,\mu)},
  \end{equation}
  and
  \begin{equation}
     \|P_th\|_{\Lip^{\kappa}}\lesssim  \g{c}{suffcond1,3} t^{-[\kappa-\frac{s_1}{2(1+s_0)\theta}(2\kappa-1)]}\|h\|_{L^2(F,\mu)},
  \end{equation}
  for any $t\in(0,1],\;\kappa\in [1/2,1],$ and $h\in L^2(F,\mu)$.
  \item [$\mathrm{(iv)}$]If $(F,R,\mu)$ satisfies assumption $\rm{(A3)}$,
  then it holds that
  \begin{equation}
    \|P_th\|_{\Lip^{\kappa}}\lesssim \g{c}{c_1,3}t^{-\frac{2[(1+s_0)\Theta-s_1]\kappa+s_0\Theta+s_1}{2(1+s_0)\Theta}}\|h\|_{L^1(F,\mu)},
  \end{equation}
  and
  \begin{equation}
     \|P_th\|_{\Lip^{\kappa}}\lesssim  \g{c}{suffcond1,4}t^{-[\kappa-\frac{s_1}{2(1+s_0)\Theta}(2\kappa-1)]} \|h\|_{L^2(F,\mu)},
  \end{equation}
  for any $t\in(0,1],\;\kappa\in [1/2,1],$ and $h\in L^2(F,\mu)$. Here, $\Theta=\frac{1+s_0-s_1}{1-(s_0-s_1)(2+s_0)}$.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:12:46.885661+00:00","domain":"probability theory","id":"claim_03ce685f7e94da9e0f2315ed2e507340b94a3bd4bd74c9877d56547918e83eaf","kind":"concept","schema_version":1,"statement":"[Lemma projprok of arXiv:2608.09856, '\bf Mass erasure on measured $\bbR$-trees,\\ applications to L\'evy forests'] Let $(T, d, \rho, \mu)$ be a rooted finitely measured Polish $\mathbb{R}$-tree. Let $\rho \! \in \!  \mathtt{t}_0\! \subseteq \!  \mathtt{t} \! \subseteq\! T $ be closed subtrees. Then, \vspace{-1.5mm}
