{"assumptions":[],"created_at":"2026-10-27T05:47:53.344145+00:00","domain":"probability theory","id":"claim_0421949bebafcf679e4049d7f75dd42c9278f2b967007b9637eedc8bafda9f06","kind":"concept","schema_version":1,"statement":"[Theorem 27 (Du, 2025) of arXiv:2607.14948, 'Graph alignment in sparse inhomogeneous models via self-overlap'] Fix $\lambda_1, \lambda_2 > 0$, $\beta \in (0, 1)$. Let $G^\uparrow \sim \mc{G}(n, \frac{\lambda_1}{n^\beta})$ and $s \sim \lambda_2n^{-\left(\frac{1-\beta}{2}\right)}$, and consider a correlated inhomogeneous graph system $(G, H)$ obtained by subsampling $G^\uparrow$ with parameter $s$. In particular,

    \begin{equation}
        I \sim \mc{G}(n, \frac{\lambda_1 \lambda_2^2}{n}); \qquad U \sim \mc{G}(n, \frac{\lambda_1 \lambda_2 (2-o(1))}{n^{\frac{1+\beta}{2}}})
    \end{equation}

    Then, for any $\eps > 0$: 

    \begin{itemize}
        \item there exists an estimator recovering $\sigma^*$ on at least $|V_{\geq (\beta^{-1} + \eps)}|(1 - o_\Proba(1))$ vertices;
        \item any estimator must be wrong on at least $|V_{\leq (\beta^{-1} - \eps)}|(1 - o_\Proba(1))$ vertices.
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:39:11.682743+00:00","domain":"probability theory","id":"claim_0428e67281e9866f7b498368588da93260b7253add56f9b4acb99efd779c5af2","kind":"theorem","schema_version":1,"statement":"[Proposition 58 (Dimension-free Hilbert resolvent estimate) of arXiv:2608.04993, '2608.04993'] For every $P\in\Smax$, up to indistinguishability,
\begin{align}
 D_t^\eps&=\int_0^t e^{-(t-r)/\eps}\,\dd X_r,
 \\
 J_t^\eps&=\int_0^tY_r^\eps\otimes\dd X_r.

\end{align}
Let
$J_t^P:=\int_0^tX_r\otimes\dd X_r\in\mathcal S_2(H)$.  Then
\begin{align}
 J^\eps-J^P&=-\int_0^\cdot D_r^\eps\otimes\dd X_r,
 \\
 Q^\eps-\qv{M^P}
 &=\int_0^\cdot D_r^\eps\otimes\dd X_r
  +\left(\int_0^\cdot D_r^\eps\otimes\dd X_r\right)^*.

\end{align}
For every $q\ge2$,
\begin{equation}
 \sup_{P\in\Smax}
 \left(\|J^\eps-J^P\|_{\mathbb S^q(P;\mathcal S_2)}
 +\|Q^\eps-\qv{M^P}\|_{\mathbb S^q(P;\mathcal S_2)}\right)
 \le Cq\sqrt\eps,
\end{equation}
where $C=C(\Lambda,B,T)$ is independent of $H,P,q,\eps$.
Furthermore
\begin{align}
 \sup_{t\le T}\|D_t^\eps\|_{\mathcal L_{\Smax}^q}
 &\le C(\sqrt{q\eps}+B\eps),
 \\
 \sup_{P\in\Smax}
 \left\|\left(\int_0^T\|D_r^\eps\|_H^2\,\dd r\right)^{1/2}\right\|_{L^q(P)}
 &\le C\sqrt{q\eps}.

\end{align}
For every $0<\beta_0<1/2$,
\begin{align}
 \sup_{P\in\Smax}
 \bigl\|\|D^\eps\|_{\infty;H}\bigr\|_{L^q(P)}
 &\le C_{\beta_0}\sqrt q\,\eps^{\beta_0},
 \\
 \sup_{P\in\Smax}
 \bigl\|\|D^\eps\|_{\infty;H}^2\bigr\|_{L^q(P)}
 &\le C_{\beta_0}q\,\eps^{2\beta_0}.

\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:49:17.489689+00:00","domain":"probability theory","id":"claim_042a6ef03845966a740a9037405e9796539f5f7f2cd8cff83ca9409ae9440b71","kind":"concept","schema_version":1,"statement":"[Theorem 3 (Model estimates) of arXiv:2605.28677, 'Weak universality for stochastic reaction-diffusion models\\ with long-range correlated no'] Let the random field $\zeta$ satisfy Assumption~\ref{ass_zeta} and denote its rescaling for $\ve>0$ as in \eqref{rescaled_noise} by $\xi_\ve$.
Let $\kk\geq3$ be an odd integer satisfying \eqref{subcritical}.
Then there exist (unique, deterministic, $\ve$-dependent) $c^{(k)}$ for $k<\kk$ satisfying

\begin{equation}
c^{(k)}_\beta\neq0
\quad\implies\quad 
|\beta|<2+k\alpha \, , \quad
\sum_\n\beta(\n)=0 \, , \quad
\sum_{k\geq\kk}\beta(k)\geq2 \, ,
\end{equation}

such that the following holds almost surely. 

For all $x\in\RR^{1+d}$ and $\beta$ there exist smooth $\Pi^\ve_{x\beta}$ and $\Pi^{-,\ve}_{x\beta}$ satisfying \eqref{model_poly} and the first two items of \eqref{model_pop}, 
$\Pi^{-,\ve}_{x\beta}$ is given by \eqref{hierarchy}, and $\Pi^\ve_{x\beta}$ satisfies \eqref{pde_Pi} for $[\beta]\geq0$. 
For $\kappa>0$ sufficiently small (depending on $\beta$) and for all $1\leq p<\infty$ 
\begin{equation}
\begin{aligned}
\EE^{ \frac{1}{p}} \big|
\Pi^\ve_{x \beta t} (x)\big|^{p} 
\lesssim \ve^{\kappa\sum_{k>\kk}\beta(k)} \big(\sqrt[4]{t} \big)^{|\beta|-\kappa\sum_{k>\kk}\beta(k)} \, ,
\end{aligned}
\end{equation}
where the implicit constant only depends on $\alpha$, $ \beta$, $\kappa$, and $p$, 
but is independent of $\ve>0$, $x\in\RR^{1+d}$, and $t>0$.

For all $x,y\in\RR^{1+d}$ and all $\beta,\gamma$ 
there exists $(\Gamma^\ve_{xy})_\beta^\gamma$ satisfying \eqref{model_recentre}, \eqref{model_gamma_props}, \eqref{model_gamma_def}, and the last item of \eqref{model_pop}. 
For $\kappa>0$ sufficiently small (depending on $\beta$) and for all $1\leq p<\infty$ 
\begin{equation}
\begin{aligned}
\EE^{ \frac{1}{p}} \big|
\big(\Gamma^\ve_{xy} \big)_{ \beta}^{\gamma} \big|^{p} 
\lesssim \ve^{\kappa \sum_{k>\kk}(\beta(k)-\gamma(k))} |x-y|^{|\beta|-|\gamma|-\kappa\sum_{k>\kk}(\beta(k)-\gamma(k))} \, ,
\end{aligned}
\end{equation}
where the implicit constant only depends on $\alpha$, $ \beta$, $\kappa$, and $p$,
but is independent of $ \ve>0$, $x, y\in\RR^{1+d}$, and $\gamma$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:57:20.584755+00:00","domain":"probability theory","id":"claim_042abe27dbcf2bf24323d72566e745149ed04d2e3c00665c76540615ee632b18","kind":"concept","schema_version":1,"statement":"[Proposition prop:random1 of arXiv:2411.09716, 'Stable Tables'] The probability $f^*(n)$ that a given person is unmatched in a table with $n$ people under random matching is
