    \item[\textup{(b)}] \(\G\) is non-anticipative in the sense that 
	\[
	v, v' \in \N \text{ with } v = v' \text{ a.e.\ on } [0, t], \, w, w' \in \Omega \text{ with } w = w' \text{ on } [0, t] \implies \G_t (v, w) = \G_t (v', w').
	\] 
