{"assumptions":[],"created_at":"2026-10-27T20:31:14.338798+00:00","domain":"probability theory","id":"claim_0518e6371eaff81facb693f42cb224cc6ad7b7c9df107c32ac828043849d2f97","kind":"concept","schema_version":1,"statement":"[Theorem MZ2016 recentered maximum until the log T term of arXiv:2606.19207, 'Extrema of cooling branching Brownian motion and related Gaussian fields'] Let $M_{\mathbf{T}}$ denote the maximal displacement at time $\mathbf{T}$ of the branching Brownian motion with the same variance profile $\sigma(t)=\widetilde{\sigma}(t/\mathbf{T})$ as in Lemma (lemma: macro BBM, lower bound of the paper). Set
	\begin{equation}
		\begin{aligned}
			m_{\mathbf{T}}
			&:=\sqrt{2}\int_0^{\mathbf{T}}\sigma(t)\,\text{d} t
			-(\sqrt{2})^{-1/3}\alpha_1 2^{-1/3}
			\int_0^{\mathbf{T}}
			\lvert\sigma'(t)\rvert^{2/3}
			\lvert\sigma(t)\rvert^{1/3}\,\text{d} t -\frac{\sigma(\mathbf{T})}{\sqrt{2}}\log \mathbf{T},
		\end{aligned}
	\end{equation}
	where $-\alpha_1$ is the largest zero of the Airy function $\mathrm{Ai}$, as in (equation eqA: Airy eigenvalues of the paper). Then there exists $C>0$ such that
	\begin{equation}
		\lvert M_{\mathbf{T}}-m_{\mathbf{T}}\rvert
	\end{equation}
	converges in law as $T\to\infty$ and there is $C>0$ such that
	\begin{equation}
		\mathbb{P}\Bigl(
		\lvert M_{\mathbf{T}}-m_{\mathbf{T}}\rvert\le K
		\Bigr)
		\ge CK\exp\Bigl\{-\frac{K}{\sigma(0)}\Bigr\},
	\end{equation}
	uniformly for all $k\in[1,\mathbf{T}^{1/3}]$ when $\mathbf{T}$ is large. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:43:44.249556+00:00","domain":"probability theory","id":"claim_05193a9b5dbd225a2ed2ea5526c6b89b58c2cf49dbff4faaa0e5d4e370ddabd7","kind":"concept","schema_version":1,"statement":"[Proposition 31 of arXiv:2604.15191, 'Quantitative Stability of Many-Marginal Schr\"odinger Bridge'] Let $k\in\mb N$ and $\alpha\in(0, 1)$. The Holder space $\m C^{k, \alpha}(\mb T^d)$ has the following properties.
\begin{itemize}
\item For any $f, g\in\m C^{k, \alpha}(\mb T^d)$, we have $fg\in\m C^{k,\alpha}(\mb T^d)$. Moreover, we have the estimate
\begin{align*}
\|fg\|_{\m C^{k,\alpha}} \leq C_1(k, \alpha, d)\|f\|_{\m C^{k,\alpha}}\|g\|_{\m C^{k,\alpha}}.
\end{align*}

\item For any $f\in\m C^{k,\alpha}(\mb T^d)$ and $g\in\m C^{k,\alpha}(\mb T^d; \mb T^d)$, we have
\begin{align*}
\|f\circ g\|_{\m C^{k,\alpha}} \leq 
\begin{cases}
C_2\big(\alpha, d, \lip(g)\big) \|f\|_{\m C^{k,\alpha}},\qquad\qquad & k=0\\
C_2'\big(k,\alpha,d,\|g\|_{\m C^{k,\alpha}}\big)\|f\|_{\m C^{k,\alpha}},\qquad\qquad & k \geq 1
\end{cases}
\quad.
\end{align*}

\item Let $A(x)$ be a symmetric matrix-valued function on $\mb T^d$, such that $A(x) \geq \lambda I_d$ is uniformly positive definite for all $x\in\mb T^d$. Define the Holder norm of $A(x)$ by
\begin{align*}
\|A\|_{\m C^{k,\alpha}} \coloneqq
\max_{|\beta| \leq k} \sup_{x\in\mb T^d}\matnorm{A(x)}_{\rm op} + \max_{\|\beta\| = k}\sup_{x\neq y} \frac{\matnorm{D^\beta A(x) - D^\beta A(y)}_{\rm op}}{|x-y|^\alpha}.
\end{align*}
Then, we have
\begin{align*}
\|A^{-1}\|_{\m C^{k,\alpha}} \leq C_3(k,\alpha, d, \lambda, \|A\|_{\m C^{k,\alpha}}).
\end{align*}
\myqed
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:29:23.370878+00:00","domain":"probability theory","id":"claim_051b5e6621b39512359706731b11de181c931ec836f14be09a1cdf0d5444349b","kind":"concept","schema_version":1,"statement":"[Proposition 5 of arXiv:2512.08595, 'Small time asymptotics of spectral heat content of isotropic processes'] Assume that $\varphi$ is regularly varying at infinity with index $\beta\in (0,1)$ and $X_t=Y_{E_t}$, where $Y$ is a $d$-dimensional isotropic $\alpha$-stable L\'evy process with $\alpha\in (1,2]$ and independent of $S$. Then,
