{"assumptions":[],"created_at":"2026-10-27T15:21:28.734075+00:00","domain":"probability theory","id":"claim_052df832bb1278e18e56f332d405e0102c661b0a48beb774ad83e01f63b1db85","kind":"concept","schema_version":1,"statement":"[Lemma l:mm' of arXiv:2605.03718, 'Potential Hessian Ascent III:\\ Sampling the Sherrington--Kirkpatrick Model at $\beta < 1/'] Consider a product distribution $\mu_h$ on $\{0,1\}^n$. Let $f(p) = p(1-p)$.
    For $k\in [0,n]$, let $t(k)$ be such that $\mathop{{}\mathbb{E}}_{\mu_{h+t(k)\mathds{1}}}$ be such that $\mathop{{}\mathbb{E}}_{\mu_{h+t(k)\mathds{1}}} \left\Vert {\sigma}\right\Vert_1 = k$, $q_i^{(k)} = \mu_{h+t(k)\mathds{1}}(\sigma_i=1)$, and $n^{(k)} = \sumo in f(q_i^{(k)})$. (When $k=0$ or $n$, set $t=-\infty$, $t=\infty$, respectively.) For $k\in \{0,\ldots n\}$, let $p_i^{(k)} = \mu_h (\sigma_i = 1|\left\Vert {\sigma}\right\Vert_1=k)$ and $m^{(k)} = \sumo in f(p_i^{(k)})$; 
    let $p_i^{(\leqslant k)} = \mu_h(\sigma_i = 1 | \left\Vert {\sigma}\right\Vert_1\leqslant k)$ and $m^{(\leqslant k)} = \sumo in f(p_i^{(\leqslant k)})$. 


    Then the following hold.
\begin{enumerate}
    \item 
    We have for $k<l$ that 
    \begin{align*}
     |m^{(k)}-m^{(l)}| \leqslant \sumo in \ab{f(p_i^{(k)}) - f(p_i^{(l)})} &\leqslant 
     \sumo in \pa{\max_{p\in [p_i^{(k)}, p_i^{(l)}]} f(p) - \min_{p\in [p_i^{(k)}, p_i^{(l)}]}f(p)}\leqslant 
     l-k\\
     |n^{(k)} - n^{(l)}| \leqslant \sumo in \ab{f(q_i^{(k)}) - f(q_i^{(l)})} &\leqslant 
     \sumo in \pa{\max_{p\in [q_i^{(k)}, q_i^{(l)}]} f(p) - \min_{p\in [q_i^{(k)}, q_i^{(l)}]}f(p)}\leqslant 
     l-k.
    \end{align*}
    \item 
    Let $\overline k = \mathop{{}\mathbb{E}}_{\mu_h} \left\Vert {\sigma}\right\Vert_1$. 
    We have 
    \begin{align*}
        |m^{(k)}-n^{(k)}| \leqslant \sumo in \ab{f(p_i^{(k)}) - f(q_i^{(k)})} &= O(\sqrt {n^{(k)}}) = O(\sqrt {m^{(k)}})\\
        |m^{(\leqslant k)}-m^{(k\wedge \left\lfloor\overline k\right\rfloor)}| \leqslant \sumo in \ab{f(p_i^{(\leqslant k)}) - f(p_i^{(k\wedge \left\lfloor\overline k\right\rfloor)})} &= O(\sqrt {n^{(k\wedge \left\lfloor\overline k\right\rfloor)}}) = O(\sqrt {m^{(\leqslant k)}})
    \end{align*} 
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

