\end{align}
and $\hat \mu_D^N$, the joint empirical measure of all $\theta_{l,i}$, converges to some $\mu_D$ with analytic density
\begin{align}
\mu_D
=
\lim_{N\uparrow\infty}
\hat \mu_D^N
=
\lim_{N\uparrow\infty}
\frac{1}{M(N)}
\sum_{i=1}^{M(N)}
        \delta_{\{\theta_{l,i}\}},
\end{align}
where $\delta_{\{\theta_{l,i}\}}$ denotes the Dirac measure centered on the point $(\theta_{1,i}, \ldots, \theta_{L,i})$. 
Then, the $L$-fold coupled HCIZ integral of rank $M(N)>1$ factors into $M(N)$ coupled rank-one integrals as
\begin{align}
