{"assumptions":[],"created_at":"2026-10-27T14:49:05.473067+00:00","domain":"probability theory","id":"claim_0589f642e68055171f390256f812f9491311b758df566fbf4f6fdb27bdc23443","kind":"concept","schema_version":1,"statement":"[Thm Kolmogorov of arXiv:2601.19145, 'Stochastic Persistence in Infinite Dimensions'] Let $(X_t)_{t\in[0, T]}$ be a stochastic process on $\mathbb{R}^n$ for some $T > 0$. Suppose there exist constants $\alpha, \beta, \gamma, K, C > 0$ such that:
    \begin{itemize}
        \item $\mathbb{E}[|X_t - X_s|^\alpha] \leq K|t-s|^{1 + \beta}$ for all $t,s \in [0,T]$.
        \item $\mathbb{E}[\sup_{t \in [0,T] \cap D} |X_t|] \leq C$, where $D$ denotes the dyadic numbers $\frac{k}{2^n}$.
        \item $\gamma < \beta / \alpha$.
    \end{itemize}

    Then there is a modification $\tilde{X_t}$ of $X_t$ with almost surely $\gamma$-H\"{o}lder continuous sample paths. Additionally, there is a function $A: [0,\infty) \to [0,1]$ which depends only on $T,\alpha,\beta,\gamma,K,C$ (not on $X$) and satisfies: \begin{itemize}
        \item $\lim_{M \to \infty} A(M) = 0$.
        \item $\mathbb{P}(\|\tilde{X}\|_\gamma > M) \leq A(M)$, where $$\|\tilde{X}\|_\gamma \coloneqq |\tilde{X}_0| + \sup_{0 \leq s < t \leq T} \frac{|\tilde{X}_t - \tilde{X}_s|}{t-s} \,.$$
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:40:26.991657+00:00","domain":"probability theory","id":"claim_058b807a1bf8c7b828f0fdf1eba17e153e289f4277f5d2ed8fbae78d93530da6","kind":"lemma","schema_version":1,"statement":"[Lemma lem-lowerboundlogpint of arXiv:2604.14318, '\large The free energy of the interacting Bose gas:\\\medskip a variational description \\'] For any $R,M\in (1,\infty)$, fix a shred configuration measure $\xi\in{\mathcal M }_1({\mathcal S }_{W_R}^{{{\scriptscriptstyle{({M}})}}})$.

\begin{enumerate}
\item There is a $C_M$ (only depending on $M$, $d$ and $\beta$) such that,  for any $R,M\in (1,\infty)$ and any shred configuration measure $\xi\in{\mathcal M }_1({\mathcal S }_{W_R}^{{{\scriptscriptstyle{({M}})}}})$,
\begin{equation}
-\langle\partial\Pi_{W_R}^{\ssup{{\mathcal S }}}(\xi),\mathfrak p_{W,M}\rangle \leq C_M\langle \xi,\mathfrak N_{W_R}^{\ssup{\ell,{\mathcal S }}}\rangle.
\end{equation}

\item There are constants $C_{M,\mathfrak r,T}$ (only depending on $M,\mathfrak r, T$ and $d$, $\beta$) and $C$ (depending only on $d$ and $\beta$) such that, for any $R,M,\mathfrak r, T, \vartheta\in(0,\infty)$ and $S\in\mathbb{N}$ and for any $\xi\in{\mathcal M }_1({\mathcal S }_{W_R})$ that is concentrated on $A^{{{\scriptscriptstyle{({\mathcal S }})}}}_{W_R;\Theta}$, where $\Theta=(M,\mathfrak r,T,\vartheta,S)$,
\begin{equation}
-\langle\partial\Pi_{W_R}^{\ssup{{\mathcal S }}}(\xi),\mathfrak p_{W,M}\rangle \leq \Big[\frac{C_{M,\mathfrak r,T}}R+\frac{C\vartheta^2}{S}\Big]\langle \xi,\mathfrak N_{W_R}^{\ssup{\ell,{\mathcal S }}}\rangle.
