{"assumptions":[],"created_at":"2026-10-27T17:24:45.934840+00:00","domain":"probability theory","id":"claim_05aee120343d5e7f6896271aa9789e113367ab6b64547f2e48214c642144f1f5","kind":"lemma","schema_version":1,"statement":"[Lemma eq:sde_non_unique of arXiv:2509.10984, 'Weak Existence and Uniqueness for Super-Brownian Motion with Irregular Drift'] \begin{enumerate}[label=(\roman*)]
