{"assumptions":[],"created_at":"2026-10-26T20:54:10.971936+00:00","domain":"probability theory","id":"claim_05df56e848dff654f54c2a3dd9c1c1b6ef3004a9f8456ad7d3c2b487329447c0","kind":"lemma","schema_version":1,"statement":"[Lem 44 of arXiv:2606.13459, 'Symmetric Cooperative Motion in Higher Dimensions'] Let $v_{0} \in L^{1}(\R^{d}) \cap L^{\infty}(\R^{d})$ where $v_{0} \geq 0$, and $v_{0}$ has a spatial modulus of continuity $\nu$. Let $v_{N}$ be generated by $\mathcal{S}_{N}$ with initial condition $v_{0}$. Then, there exists $N_{0} = N_{0}(d,m,\norm{v_{0}}_{L^{\infty}(\R^{d})}) \in \N$ such that the following hold. 
	\begin{enumerate}[(i)]
		\item For all $N \geq N_{0}$, and $t \geq 0$, 
		\begin{equation*}
			\norm{v_{N}(\cdot,t)}_{L^{\infty}(\R^{d})} \leq \norm{v_{0}}_{L^{\infty}(\R^{d})}\quad\text{and}\quad\norm{v_{N}(\cdot,t)}_{L^{1}(\R^{d})} \leq \norm{v_{0}}_{L^{1}(\R^{d})}.
		\end{equation*}

		\item For all $N \in \N$, $v_{N}$ admits $\nu$ as a spatial modulus of continuity on $\R^{d}\times[0,T]$.
		\item The tail sequence $(v_{N})_{N \geq N_{0}}$ admits an approximate temporal modulus of continuity on $\R^{d}\times[0,T]$.
		\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:48:49.853337+00:00","domain":"probability theory","id":"claim_05e0b6dd4d50eac5e09a7fb4abdb119424642894a29c8b9ed068e63624b39853","kind":"concept","schema_version":1,"statement":"[Lemma lem:bound_h of arXiv:2509.16694, 'A central limit theorem for two-dimensional directed polymers with critical spatial correl'] Let $a>-1$, $M\in \mathbb{Z}_{+}$ and $\varepsilon>0$.  Then, there exist $N_0=N_0(M,\varepsilon)$ such that for all $N\geq N_0,$ and for all $l\in\{1,\dots,M\}$,
\begin{equation}{}
(1-\varepsilon)\pi   \left(\frac{\log N}{2M}\right)^{a+1}\left(l+\mathds{1}_{a\leq0}\right)^a\leq \sum_{x\in A_{l}} h(x) \leq (1+\varepsilon)\pi 
   \left(\frac{\log N}{2M}\right)^{a+1}{\left(l+\mathds{1}_{a>0}\right)^a}\,.
