{"assumptions":[],"created_at":"2026-10-27T19:59:45.012285+00:00","domain":"probability theory","id":"claim_0648ea57e797d4553ddb68fc72a77f9223d7bade3293bc2d46725cb1e4be2ffa","kind":"theorem","schema_version":1,"statement":"[Proposition cspde WPE of arXiv:2605.13479, '\LARGE Dean-Kawasaki Equation with Biot-Savart and Keller-Segel Interactions: Existence an'] Let the interaction $\mathcal{V}[\cdot]$ be defined by (equation ker-V of the paper) and the initial condition $\rho_0\in\mathrm{Ent}(\mathbb{T}^2)$. For fixed $\rho \in \mathcal{C}_0$ in Lemma (entropymethod of the paper), let $g=\sqrt{\rho}\nabla\Psi^{\rho}$. Then there exists a nonnegative probabilistically weak renormalized kinetic solution $\rho^{\flat,\varepsilon}$ of (equation SCPDE of the paper) with initial data $\rho^{\flat}_0$ and control $g$, in the sense that for every $t\in[0,T]$ and $\psi \in \mathrm{C}_{c}^{\infty}\left(\mathbb{T}^2\times(0,\infty)\right)$, it holds almost surely that for almost every $t\in[0,T]$, 
\begin{align}
&\int_{\mathbb{R}}\int_{\mathbb{T}^2} \chi^{\flat,\varepsilon}(x, \zeta, \cdot) \psi(x, \zeta)\Big|_0^t = -\int_{0}^{t} \int_{\mathbb{R}} \int_{\mathbb{T}^2}\nabla\rho^{\flat,\varepsilon}\cdot\nabla_x\psi(x,\rho^{\flat,\varepsilon}) -\int_{0}^{t} \int_{\mathbb{R}} \int_{\mathbb{T}^2} \partial_{\zeta} \psi(x, \zeta) \mathrm{d}m^{\flat,\varepsilon}\nonumber\\
& - \int_{0}^{t} \int_{\mathbb{T}^2} \nabla\cdot (\rho^{\flat,\varepsilon} \mathcal{V}[\rho^{\flat,\varepsilon}])\psi(x, \rho^{\flat,\varepsilon})
+ \int_{0}^{t} \int_{\mathbb{T}^2} s_{\eta}(\rho^{\flat,\varepsilon})P_{K}g \cdot \nabla_x\psi(x, \rho^{\flat,\varepsilon})\nonumber\\
& + \int_{0}^{t} \int_{\mathbb{T}^2} s_{\eta}(\rho^{\flat,\varepsilon})P_{K}g \cdot \nabla\rho^{\flat,\varepsilon} \partial_\zeta\psi(x, \rho^{\flat,\varepsilon})+\sqrt{\varepsilon}\int_{0}^{t} \int_{\mathbb{T}^2} s_{\eta}(\rho^{\flat,\varepsilon}) \xi_{K}\cdot \nabla \psi(x, \rho^{\flat,\varepsilon})\nonumber\\
&-\frac{\varepsilon F_{1,K}}{2}\int^t_0\int_{\mathbb{T}^2}s_{\eta}'(\rho^{\flat,\varepsilon})^2\nabla\rho^{\flat,\varepsilon}\cdot(\nabla\psi)(x,\rho^{\flat,\varepsilon})+\frac{\varepsilon N_K}{2}\int_{0}^{t} \int_{\mathbb{T}^2} s_{\eta}(\rho^{\flat,\varepsilon})^2 \partial_{\zeta} \psi(x, \rho^{\flat,\varepsilon}),
\end{align}

with preservation of mass $\|\rho^{\flat,\varepsilon}\|_{L^{1}_{\mathbb{T}^2}}\equiv \|\rho^{\flat}_0\|_{L^{1}_{\mathbb{T}^2}}$ and the pathwise entropy inequality 

\begin{align}
\int_0^t\int_{\mathbb{T}^2}
|\nabla\sqrt{\rho^{\flat,\varepsilon}}|^2\mathrm{d}x\mathrm{d}s
\lesssim&\int_{\mathbb{T}^2}\Psi(\rho^{\flat}_0)\mathrm{d}x+\sqrt{\varepsilon}\int_0^t\int_{\mathbb{T}^2}
2\nabla\sqrt{\rho^{\flat,\varepsilon}}\cdot
\xi_{K}+\int_0^t\int_{\mathbb{T}^2}
2\nabla\sqrt{\rho^{\flat,\varepsilon}}\cdot
P_Kg
+\varepsilon N_KT+1,
\end{align}
almost surely, for all $t\in[0,T]$, and further the nonnegative kinetic measure $m^{\flat,\varepsilon}$ satisfies

\begin{align}
4\delta_{0}(\zeta-\rho^{\flat,\varepsilon})\zeta |\nabla \sqrt{\rho^{\flat,\varepsilon}}|^{2}\leqslant m^{\flat,\varepsilon},\quad \liminf_{M\to \infty} \mathbb{E}\big[m^{\flat,\varepsilon}(\mathbb{T}^2\times [0,T]\times [M,M+1])\big]=0,
\end{align}

where $\zeta$ stands for the velocity variable. Moreover, the law $\nu^{\varepsilon,\rho}$ of $\rho^{\flat,\varepsilon}$ satisfies 
\begin{align*}
\varepsilon\mathcal{H}\left(\nu^{\varepsilon,\rho}\mid
\mu^{\varepsilon}\right)
\leqslant \mathcal{I}(\rho). 
\end{align*}","status":"unverified"}

