{"assumptions":[],"created_at":"2026-10-26T19:18:27.578257+00:00","domain":"probability theory","id":"claim_0675b93472e6008e1c922aa507ebf76cb280eda9af511256a94ef9e1991d48a7","kind":"lemma","schema_version":1,"statement":"[Lem 46 of arXiv:2510.23423, 'One-arm exponents of the high-dimensional Ising model'] Let $d\geq 2$ and $G=(V,E)\subset H=(V',E')$ be two subgraphs of $\mathbb Z^d$. For every $\beta\geq 0$, and every $x,y \in V'$,
\begin{equation}
	\langle \sigma_x\sigma_y\rangle_{H,\beta}-\langle \sigma_x\sigma_y\rangle_{G,\beta}\leq \sum_{u\in \partial V}\langle \sigma_x\sigma_u\rangle_{G,\beta}\langle \sigma_u\sigma_y\rangle_{H,\beta},
\end{equation}
where $\p V:= \{ x\in V : \exists x'\in V' \setminus V \text{ with } xx' \in E' \}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:25:49.874985+00:00","domain":"probability theory","id":"claim_0677475d829ad8ff8d8d27b55fb40295201185f49ca5c4dd2e5ef2f1ab5d5714","kind":"theorem","schema_version":1,"statement":"[Proposition 23 (\textsf{Uniform truncation principle}) of arXiv:2609.02064, 'Coalescence and fluctuations of O'Connell--Yor polymers\\ via the free-energy correlation '] Let $K\subset\R$ be compact and $q>0$.  Then
  \begin{align}
    \sup_{u\in K}
    \int_{\DN}
      \left|e^{q\be H_u^\eps(\ga)}
        -e^{q\be H_u(\ga)}\right|\,\mu_\be(d\ga)
    \longrightarrow0.
  \end{align}
  More generally, suppose that
  $h_\eps:K\times\DN\to\R$ are uniformly bounded
  over $\eps\in [0, 1]$, and  for every
  $R<\infty$,
  \[
    \sup_{\substack{u\in K\\\ga_n\leq R}}
    |h_\eps(u,\ga)-h_0(u,\ga)|\longrightarrow0.
  \]
  Then
  \begin{align}
    \sup_{u\in K}\left|
      \int_{\DN} e^{q\be H_u^\eps(\ga)}h_\eps(u,\ga)\,\mu_\be(d\ga)
      -\int_{\DN} e^{q\be H_u(\ga)}h_0(u,\ga)\,\mu_\be(d\ga)
    \right|\longrightarrow0.
  \end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:29:52.232303+00:00","domain":"probability theory","id":"claim_067755c879b088337131e05a32266ac71883d34257660e57d4d46869986a35ca","kind":"concept","schema_version":1,"statement":"[Lemma 9 (Kasteleyn Lemma) of arXiv:2512.10199, 'Explicit correlation functions for the six-vertex model in the free-fermion regime'] For all $\orho \in \gen_n$,
