{"assumptions":[],"created_at":"2026-10-27T14:45:01.996570+00:00","domain":"probability theory","id":"claim_0681fce8d9295f767359741620349b3c00e365f7d7edba9b4ffad211c064fa96","kind":"lemma","schema_version":1,"statement":"[Lemma LEM:SEC1 of arXiv:2512.23957, 'Concentration and fluctuations of sine-Gordon measure around topological multi-soliton man'] Let $|Q|=1$.

\begin{itemize}

\item[(1)] If $ G \in \mathcal{C}_Q$ satisfies $E(G)=\inf_{\phi \in \mathcal{C}_Q}E(\phi) $, then there exists $\xi\in \mathbb{R}$ such that 
\begin{align*}
G(x)=m(x-\xi) \quad \textup{when $Q=1$}, \quad G(x)=m^{-}(x-\xi) \quad \textup{when $Q=-1$}.
\end{align*}

\medskip  

\item[(2)] 
Let $\textup{dist}(\phi, \mathcal{M}_1):=\inf_{\xi \in \mathbb{R}} \| \phi-m_{\xi} \|_{L^2(\mathbb{R})}$ and $\textup{dist}(\phi, \mathcal{M}_{-1}):=\inf_{\xi \in \mathbb{R}} \| \phi-m_{\xi}^{-} \|_{L^2(\mathbb{R})}$. There exists $c>0$ such that if $\phi \in \mathcal{C}_Q$ satisfies 
\begin{align*}
\textup{dist}(\phi, \mathcal{M}_Q)\ge \delta>0, 
\end{align*}

\noindent
then
\begin{align*}
E(\phi) \ge  \inf_{\phi \in \mathcal{C}_Q } E(\phi)+c \cdot \textup{dist}(\phi, \mathcal{M}_Q)^2 \ge E_{\textup{kink}}+c \cdot \delta^2.
\end{align*}

\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:20:15.586417+00:00","domain":"probability theory","id":"claim_068ec9f5c2a1519c05b1deafab4b812213be4e978c75413418aed68c7496db03","kind":"lemma","schema_version":1,"statement":"[Lemma lem:Lie-decomposition of arXiv:2609.00840, 'Kählerity of complete almost-Kähler gradient shrinking Ricci solitons'] Let $(M^{2m},g,J,\omega,f)$, $m\geq 2$, be an almost-K\"ahler gradient shrinking Ricci soliton. Then, for $V=\nabla f$ and $W=JV$, we have
	\begin{equation}
		\beta:=\mathcal L_V\omega
		=\frac{\Delta_gf}{m}\omega-2\rho_0+\nabla_V\omega,
	\end{equation}
	where $\rho_0$ is the trace-free Ricci form. Moreover, 
	\begin{equation}
		\nabla_V\omega\in\Lambda_J^-,
		\qquad
		(\nabla_V\omega)(V,W)=0,
	\end{equation}
	and
	\begin{equation}
		\beta(V,W)=\nabla^2 f(V,V)+\nabla^2 f(W,W).
	\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:28:49.115690+00:00","domain":"probability theory","id":"claim_0696fd71868cc0fad163f52ad640d65b680ba5b2e3aa607c84a72d5b5c406e91","kind":"theorem","schema_version":1,"statement":"[Thm THM61 of arXiv:2608.16170, '\bf On hitting time distributions of Markov processes with sub-Gaussian heat kernel bounds'] Assume that every $d$-bounded closed subset of $E$ is compact, and that $X$ satisfies one of the following sets of assumptions:
\begin{itemize}
    \item[{\rm(i)}] the symmetry assumptions (H1a) and (H1b);
    \item[{\rm(ii)}] the duality assumptions (H2a) and (H2b);
    \item[{\rm(iii)}] the sector condition (H3), and the associated semi-Dirichlet form $({\mathcal{E}},{\mathcal{F}})$ of $X$ is regular.
\end{itemize}
 If the transition density function of $X$ satisfies the following short-time lower bound estimate at a fixed point $x\in E$:
\[
p(t,x,y)\geq  \frac{C_1}{t^{\alpha/\beta}}\exp\left\{-C_2\left(\frac{d(x,y)}{t^{1/\beta}}\right)^{\beta/(\beta -1)}\right\}, \quad \forall  0<t\leq T, \, y\in E,
\]
for some $\alpha>0$, $\beta>1$, $C_1>0$, $C_2>0$ and $T>0$, then for any $B\in \mathscr{B}^n(E)$, 
\[
        \limsup_{t\downarrow 0}\frac{-t^{1/(\beta-1)}\cdot \left(\log \mathbb{P}^x[\sigma_B\leq t]\right)}{C_2}\leq  \widetilde{d}(x,B)^{\beta/(\beta-1)}.
\]","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:01:54.382873+00:00","domain":"probability theory","id":"claim_06988e403d008732c7bd289ea5f07d3bc695fae7d033ed4fc5a1fb383f8f98da","kind":"concept","schema_version":1,"statement":"[Lemma lem:stoch.comp of arXiv:2411.02033, 'Two stochastic versions of the Arps curve decline'] \hspace{1cm}
\begin{enumerate}
\item If $X$ and $Y$ are two positive random variables defined on the same probability space such that $X \preceq_{st} Y$ and if $f$ is a one-to-one map defined on $\mathbb{R}^+$, then $f(X) \preceq_{st} f(Y)$.
\item If $f$ and $g$ are two functions such that that for any $t \in \mathbb{R}$ $f(t) \leqslant g(t)$, then for any random variable $X$ $f(X) \preceq_{st} g(X)$.
\item Let $f$ and $g$ two continuous functions defined on $\mathbb{R}^+$ such that:
$$
\forall t \geqslant 0 , \quad f(t) \geqslant g(t) ,
$$
with $g(0) \leqslant f(0) \leqslant 0$. Then $T_{B,f(\cdot)} \preceq_{st} T_{B,g(\cdot)}$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:07:35.013113+00:00","domain":"probability theory","id":"claim_0698c2dbba0902b11980bfaf18829325729564a09745fc0b18f70fa0675c00f8","kind":"theorem","schema_version":1,"statement":"[Proposition 59 of arXiv:2609.02850, 'Canonical-row Chern flow on Bott--Samelson towers:\\ realizable-volume models for Schubert'] The bundle
