{"assumptions":[],"created_at":"2026-10-26T19:49:02.093215+00:00","domain":"probability theory","id":"claim_06acca6b3e50489ee13884de0d499c3a643e13794f1647d20bb0cc0d1d69098f","kind":"lemma","schema_version":1,"statement":"[Lem 9 of arXiv:2604.25964, 'Strong convergence rate of Euler-Maruyama approximations in temporal-spatial H\"older-norm'] For $\delta \in \widetilde{\mathbb{S}},$ $x \in \bR,$ $s\in [0, T],$ $\widetilde{s} \in [s, T], \widehat{s} \in [\widetilde{s},T],$ $\delta([0, T])\cap (s, \widehat{s}) = \emptyset,$ let $(X^{\delta,x}_{s,t})_{t\in[s,T]}:[s,T]  \times\Omega\to\mathbb{R} $ 
be an $(\mf_t)_{t\in[s,T]}$-adapted stochastic process with c\`adl\`ag  sample paths satisfying equation \eqref{y01}. 

Then, for all $p \ge 2$, there exists a positive constant $C_p$ such that 
\begin{enumerate}
     \item [\textup{(i)}]
    \begin{align*}
        \left[\mathbb{E}\left|X^{\delta, x}_{\widetilde{s},\widehat{s}}-X^{\delta, x}_{s,\widehat{s}}\right|^p\right]^{1/p} 
 \leq C_p |\widetilde{s} -s|^{1/p} (e^{2.5\overline{c}T}V(x))^{1/p}. 

 \end{align*}
 \item [\textup{(ii)}]
 \begin{align*}
\left[\mathbb{E}\left[\left|\left(X^{\iota, x}_{s,\widehat{s}}-X^{\delta,x}_{s,\widehat{s}}\right) - \left(X^{\iota, x}_{\widetilde{s},\widehat{s}}-X^{\delta, x}_{\widetilde{s},\widehat{s}}\right)\right|^p\right]\right]^{1/p}  
   \leq C_p |\delta|^{1/p} |\widetilde{s} -s|^{1/p} (e^{2.5\overline{c}T}V(x))^{1/p}.

   \end{align*}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:27:08.848141+00:00","domain":"probability theory","id":"claim_06ae4a4cfc9ea21643dd52e4fc1d3260180637c6908b9294ed0b4078060e7900","kind":"concept","schema_version":1,"statement":"[Prop 48 of arXiv:2511.10535, 'Eigenvalues of Brownian Motions on $\mathrm{GL}(N,\mathbb{C})$'] Let $a$ be an operator in a $W^\ast$-probability space $(\A,\tau)$, and for each $N\in\N$ let $A^N$ be a matrix in $\M_N(\C)$.
\begin{enumerate}
    \item If $A^N$ converges strongly to $a$, then for each $\varepsilon>0$ and all sufficiently large $N\in\N$ the spectrum of $A^N$ is contained in the $\varepsilon$-neighborhood of the spectrum of $a$: $\sigma(A^N)\subset\sigma(a)+\varepsilon$.
    \item If the ESD $\mu_{A^N}$ of $A^N$ converges weakly to the Brown measure $\mu_a$ of $a$, then for each $\varepsilon>0$ and all sufficiently large $N\in\N$ the support of $\mu_a$ is contained in the $\varepsilon$-neighborhood of the spectrum of $A^N$: $\supp\mu_a\subset \sigma(A^N)+\varepsilon$.
    \item Ergo: if $A^N\to a$ strongly and $\mu_{A^N}\to\mu_a$ weakly, and in addition $\supp\mu_a = \sigma(a)$, then $\sigma(A^N)\to\sigma(A)$ in Hausdorff distance.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

