{"assumptions":[],"created_at":"2026-10-27T05:47:53.352107+00:00","domain":"probability theory","id":"claim_073cbd0f21eb14fd9c0ff2eb2919c84e1949cc637a3b037da182dc558ab9b335","kind":"theorem","schema_version":1,"statement":"[Theorem 3 of arXiv:2607.15903, 'Uniqueness for nonlinear Fokker-Planck equations with general diffusion terms and their as'] \cite[Thm.~2.1]{ref13}
Assume that (\textbf{\romannumeral1}'), (\textbf{\romannumeral2}) and (\textbf{\romannumeral3}') hold. Then there exists a continuous contraction semigroup $S(t): [0, \infty ) \rightarrow L^{1}$ such that, for each $u_{0} \in  L^{1}(\mathbb{R}^{d})$, $u=u(t, u_{0})=S(t)u_{0}$ is a mild solution to (\ref{1}) and 
\begin{equation}
    \left | u(t,u_{0})- u(t,\tilde{u}_{0})\right | _{1} \leqslant \left | u_{0}- \tilde{u}_{0} \right | _{1} , \quad \forall u_{0}, \tilde{u}_{0} \in L^{1}, \; t\geqslant 0\notag 
\end{equation}
\begin{equation}
    u \geqslant 0, \text{a.e.} \; \text{on}\;  (0,\infty) \times \mathbb{R}^{d} ,\quad  \text{if} \; u_{0} \geqslant 0,\text{a.e.} \; \text{on} \; \mathbb{R}^{d},   \notag 
\end{equation}
\begin{equation}
    \int_{\mathbb{R}^{d} } u(t,x)dx,=\int_{\mathbb{R}^{d} } u_{0}(x)dx, \quad \forall u_{0} \in L^{1}, \; t \geqslant 0.\notag 
\end{equation}
Moreover, $u$ is a distributional solution to (\ref{1}), that is, for all $\varphi \in C^{\infty}_{0}([0,T)\times \mathbb{R}^{d})$,
\begin{equation}
\begin{split}
   \int^{T}_{0} &\int_{\mathbb{R}^{d}} \bigg(u(t,x)\frac{\partial \varphi }{\partial t}(t,x)+\sum\limits_{i,j=1}^{d}a_{ij}(x)\beta(x,u(t,x))D^{2}_{ij}\varphi(t,x)\\+& u(t,x)b(x, u(t,x)) \cdot \nabla \varphi (t,x) \bigg) dxdt +\int_{\mathbb{R}^{d}}u_{0}(x)\varphi(0,x)dx=0 .  
\end{split}\notag
