\|\widetilde{Q}^N-\bar{Q}\|_{T,1} \leq \kappa_1\|\widetilde{X}^N-\bar{X}\|_{T,1} + \kappa_2\|(\boldsymbol{G}^N)^T-\boldsymbol{G}^T\|_{op}\,. 
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:18:13.262755+00:00","domain":"probability theory","id":"claim_074a983d5042294117311c88ed98483cb4d179cbc4fb37973106fac1a0931c88","kind":"concept","schema_version":1,"statement":"[Lemma comparisonstep1 of arXiv:2507.10545, 'KPZ equation from a class of nonlinear SPDEs in infinite volume'] \fsp Fix any {\small$\mathrm{L}>0$}. There exists {\small$\gamma_{\mathrm{L},1}>0$} depending on {\small$\mathrm{L}$} such that with high probability, we have 

\begin{align}
\sup_{\t\in[0,1]}\sup_{|\x|\leq \mathrm{L}N}|\mathbf{Z}^{N}_{\t,\x}-\mathbf{Y}^{N,1}_{\t,\x}|\lesssim_{\mathrm{L}} N^{-\gamma_{\mathrm{L},1}},
\end{align}

where, upon recalling {\small$\mathbf{L}^{N,\zeta_{\mathrm{final}},\sim}$} from (equation eq:lzetasim-sde of the paper), we set

\begin{align}
\mathbf{Y}^{N,1}_{\t,\x}&:=\sum_{\y\in\Z}\mathbf{L}^{N,\zeta_{\mathrm{final}},\sim}_{0,\t,\x,\y}\mathbf{S}^{N}_{0,\y}.
