{"assumptions":[],"created_at":"2026-10-26T19:27:08.848573+00:00","domain":"probability theory","id":"claim_074b51728696d9852f718e389d08f0fbd1f08b2cc4d1df0dc321e9e5c1776f6b","kind":"definition","schema_version":1,"statement":"[Defination 3 of arXiv:2511.10814, '\Large \bf \boldmath\ \\ Convergence of the extended Kalman filter with small and state-de'] Let $\varphi:[0,\infty)\times \R^n \to \R^n,$  be  a  family  of   functions and $x_1, x_2 \in \R^n $. 

			\begin{enumerate}
				\item 
				$\varphi$  is said to be  \textbf{almost  linear} if  there  exists  a family  of matrix-valued observable processes $F:[0,\infty)\to \R^{n\times n}$  such  that 				
				\begin{equation}
					\vert \varphi(t,x_1)- \varphi(t,x_2) - F(t) (x_1-x_2) \vert  \leq \mu^{\eps} \vert x_1-x_2 \vert,
				\end{equation}
				for some family of  numbers  $\mu=(\mu^{\eps})_{\eps>0}$ converging to zero as $\eps \to 0$. \\ The  process $F$  will be  called an  \textbf{almost  derivative} of $f$.

				\item The  function  $\varphi$  will be  said  to  be \textbf{strongly  injective} if 
				\begin{equation}
					\vert \varphi (t,x_1)- \varphi(t,x_2)  \vert  \geq c \vert x_1-x_2 \vert,
				\end{equation}
				for  some $c>0$.
			\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:04:07.034042+00:00","domain":"probability theory","id":"claim_074d3767e36960c9be8eab5895cb5037c237f70d507b8afa997a68a1c1f324a6","kind":"theorem","schema_version":1,"statement":"[Proposition prop:siteperc_dom_SIR of arXiv:2607.29409, 'The Zombie Infection Model'] Let $G=(V,E)$ be a graph of bounded degree. Then, for any $\lambda > 0$ and $\Delta\Subset V$, there
		is a coupling $\widehat{\BP}$ of ${\mathcal{C}}^{\SIR}_{\Delta, \lambda}$,
		$\widetilde{G}_{u}\sim G_{q_u}^{\siteperc}$ and
		$\widetilde{G}_{l}\sim G_{q_l}^{\siteperc}$ such that
		\begin{equation}
			\widehat{\BP}\!\left( {\mathcal{C}}^{\siteperc}_{\Delta}(\widetilde{G}_{l}) \subseteq {\mathcal{C}}
			^{\SIR}_{\Delta, \lambda}\subseteq {\mathcal{C}}^{\siteperc}_{\Delta}( \widetilde{G}_{u}
			)\cup \partial_{v}^{o}\big({\mathcal{C}}^{\siteperc}_{\Delta}(\widetilde{G}_{u})\big) \right)
			= 1,
		\end{equation}
		where
		$q_{l} = \int_{0}^{\infty} (1-e^{-\lambda y})^{\mathrm{deg}(G)} e^{-y}\,dy \text{ and }q_{u}
    		= \frac{\lambda \mathrm{deg}(G)}{\lambda \mathrm{deg}(G) + 1}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:50:44.869909+00:00","domain":"probability theory","id":"claim_07523020c0d91cc30ea432f0cf2c11753ab9c35f108ee484465bf810d04927cb","kind":"theorem","schema_version":1,"statement":"[Proposition 9 (Deterministic and Gaussian transfer) of arXiv:2607.16724, 'Algebraic Transfer for Operator-Valued Gaussian Chaoses: Oriented Schatten Profiles and Si'] If $\Theta$ is cut-factorizable, then, for every
$K\in\cK_{\mathrm{in}}^{\mathrm{alg}}$ and $1\le r\le\infty$,
\begin{equation}

 \Prof_{n,r}(\Theta K)\le\Cost(\Theta)\Prof_{m,r}(K).
\end{equation}
For $2\le r<\infty$ and $1\le p<\infty$,
\begin{equation}

 \norm{\cT_{\Theta K}^{(n)}}_{L^p(\Omega;\Sch_r)}
 \le C_n(p+r)^{n/2}\Cost(\Theta)\Prof_{m,r}(K).
\end{equation}
Under the same restrictions on $p,r$, if, in addition, $K$ is a symmetric
same-field algebraic kernel and
$\Theta$ is same-field compatible, then
\begin{equation}

 \norm{I_n(\Theta^{\mathrm W}K)}_{L^p(\Omega;\Sch_r)}
 \le A_n(p+r)^{n/2}\Cost(\Theta)\Prof_{m,r}(K).
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:30:52.739021+00:00","domain":"probability theory","id":"claim_07544cd597a54dced2dd43a112e1a6db285382dbbf839decb7e25f6f26bb72a3","kind":"concept","schema_version":1,"statement":"[Corollary 6 of arXiv:2506.10494, 'Geometric Jensen-Shannon Divergence Between Gaussian Measures On Hilbert Space'] Let $\mu_i = \Ncal(m_i, C_i) \in \Gauss(\R^n)$, $i=0,1$. Then
			\begin{align}
					&\JS_{G_{\alpha}}(\mu_0 ||\mu_1) = \frac{(1-\alpha)}{2}||C_{\alpha}^{-1/2}(m_0- m_{\alpha})||^2 +\frac{\alpha}{2}||C_{\alpha}^{-1/2}(m_1- m_{\alpha})||^2
					\nonumber
					\\
					&\quad -\frac{1}{2}\log\frac{\det(C_0)^{1-\alpha}\det(C_1)^{\alpha}}{\det(C_{\alpha})} 
					+
					\frac{1}{2}\trace[C_{\alpha}^{-1}((1-\alpha)C_0 + \alpha C_1) - I].
				\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:19:06.748529+00:00","domain":"probability theory","id":"claim_075800f0ca4c42d7cb713108d3c08a06a9c2351aed296fab88be17836cb5e04e","kind":"theorem","schema_version":1,"statement":"[Theorem thm:tree-cylinder-square-sum-theorem-paper of arXiv:2606.08683, 'Exact Fourier dimensions of dyadic Mandelbrot cascades under minimal integrability'] Assume that the dyadic vector-weight law is energy-admissible.  Then, almost
