{"assumptions":[],"created_at":"2026-10-27T06:57:30.977097+00:00","domain":"probability theory","id":"claim_078aab30dc11ed3782e2ca7d407a634bec201916ba75dc20f8d71834ed4aa4c0","kind":"theorem","schema_version":1,"statement":"[Theorem 14 (\textsf{Master bounds}) of arXiv:2608.12451, '2608.12451'] Fix $r\in\N$ and
let $F\in L^4(\PP)$ belong to the $r$-th chaos in the Poisson setting
or Rademacher setting.
Recall $\cD(F)$ and $\fE_r(F)$ from \eqref{def_CD} and \eqref{E_abs}.
Assume that a nonnegative quantity $\rho(F)$ satisfies

\noi
\begin{align}
 \|J_{2r}(F^2)\|_2^2\geq2m_2(F)^2-\rho(F).

\end{align}

\noi
Put

\noi
\begin{align}
 \cT_F:=\frac1r\Gamma(F,F)-m_2(F)-\frac F2
 \AND
 \mathfrak d(F):=\abs{\cD(F)}+\rho(F).

\end{align}
Then,
\begin{align}
 \fE_r(F)&\leq\mathfrak{d}(F),
 \\
 \abs{m_3(F)-m_2(F)}
 &\leq\sqrt{m_2(F)\mathfrak d(F)},
 \\
 \norm{\cT_F}_2
 &\leq\frac{2r-1}{2r}\sqrt{\mathfrak d(F)}.

\end{align}
Moreover, without any lattice assumption,
\begin{align}
 \cJ(F)
 &\leq4\sqrt{m_2(F)\mathfrak d(F)}
   +12\mathfrak d(F).

\end{align}
If, in addition, $\rho(F)=0$ and $\cD(F)\geq0$, then
$12\mathfrak d(F)$ in \eqref{J_master} can be replaced by
$8\mathfrak d(F)$.

If $F$ additionally satisfies the lattice condition \eqref{cond_La}
with shift $\theta>0$, then, with
$c_\theta:=(1-e^{-\theta})/\theta$,
\noi
\begin{align}
 \dTV(F+\theta,P_\theta)
 &\leq c_\theta\bigg[
 \abs{m_2(F)-\theta}
 +\frac{2r-1}{2r}\sqrt{\mathfrak d(F)}
 +\frac23\sqrt{m_2(F)\mathfrak d(F)}
 +2\mathfrak d(F)
 \bigg].

\end{align}
In the preceding special case $\rho(F)=0$ and $\cD(F)\geq0$,
$2\mathfrak d(F)$ in \eqref{master_TV} can be replaced by
$\frac43\mathfrak d(F)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:32:23.559818+00:00","domain":"probability theory","id":"claim_078e65fb6674ed254b4193d535b5bc0dd36d601c9b9d9a4f9bcb5de3f5f27f94","kind":"theorem","schema_version":1,"statement":"[Cor 3.4 of arXiv:2603.13873, '{Solvability of BSDEs with possibly unbounded stochastic coefficients \\ on a general weig'] Let $\xi\in L_\tau^p(0;{\mathbb R}^k)$ and the generator $g$ satisfy assumptions (A:H1b of the paper) and (A:H2 of the paper)-(A:H5 of the paper). Assume further that for some constant $M>0$,
\begin{align}
\int_0^\tau \left(\mu_t+\frac{\theta}{2[1\wedge(p-1)]}\nu_t^2\right)^+ {\rm d}t\leq M.
\end{align}
Then, BSDE (equation BSDE1.1 of the paper) admits a unique $L^p$ solution $(y_t,z_t)_{t\in[0,\tau]}$ in the space of $H_\tau^p(0;{\mathbb R}^{k}\times{\mathbb R}^{k\times d})$. Moreover, if $|\xi|+\int_0^\tau |g(s,0,0)|{\rm d}s\in L^\infty(\Omega,\mathcal{F}_\tau, \mathbb{P};{\mathbb R})$, then $(y_t)_{t\in[0,\tau]}\in S^\infty({\mathbb R}^k)$.\vspace{0.1cm}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:54:34.570393+00:00","domain":"probability theory","id":"claim_07907a1ed4965d797addc3ca82ee855c4136ab8900f8629a638775087fbf2084","kind":"definition","schema_version":1,"statement":"[Definition 6 of arXiv:2606.14443, 'SEMICLASSICAL LIMIT OF POLYAKOV-LIOUVILLE MEASURE and Q-Curvature Uniformization ON EVEN-D'] The \emph{augmented (co-polyharmonic) field} $h$ is a centered Gaussian random variable taking values in $ H^{-s}$ for some $s>0$ with covariance
	\begin{equation*}

		\E  \Big[\langle h|\phi\rangle\cdot \langle h|\eta\rangle\Big]=\mathcal K(\phi,\eta)

		\quad\qquad \forall u,v\in  H^{s},
	\end{equation*}
	where
	\begin{equation*}
		\mathcal K(\phi,\eta)=\iint k(x,y)\, \phi(x)\, \eta(y)\, d\vol(x)\, d\vol(y).
	\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:57:28.229439+00:00","domain":"probability theory","id":"claim_0790898602030a71aacfe28fec9473546d1fe7d50d1efbab8a17d54a668abe30","kind":"lemma","schema_version":1,"statement":"[Lemma 10 of arXiv:2607.18104, '2607.18104'] There exist $c,C>0$ such that for each $n\in \N$, there exists an event $\mathsf{B}_n$ with
 \begin{equation} 
     \mathbf{P}_n(\mathsf{B}_n) \geq 1-C \exp\big(-cn^{9/8} \big) 
 \end{equation} on which:
\begin{enumerate}
    \item[(i)]   The unwrapped patched directed landscape $\Lpat$ is an element of the space of upper semi-continuous functions $ \USC(\SetR,\R \cup \{-\infty\})$.
    \item[(ii)]   The unwrapped patched directed landscape and its unwrapped inherited geodesics satisfy the following decomposition property: If $\bar\pi$ is an unwrapped inherited geodesic from $(x,s)$ to $(y,t)$ for some $(x,s,y,t)\in\SetR$ and $\tilde s\in (s,t)$ then $\bar\pi$ restricted to $[s,\tilde s]$ and $\bar\pi$ restricted to $[\tilde s, t]$ are both inherited geodesics, and 
\begin{equation}
\Lpat(x,s;y,t) = \Lpat(x,s;\bar\pi(\tilde s),\tilde s) + \Lpat(\bar\pi(\tilde s),\tilde s;y,t).
\end{equation} 
\item[(iii)] For every inherited geodesic $\pi \colon [s,t] \rightarrow \R$ in the unwrapped patched directed landscape, 
\begin{equation}
  \int \textup{d}\Lpat\circ \pi  = \Lpat(s,\pi(s);t,\pi(t)) . 
\end{equation}
    \item[(iv)]  For all  $(x,s;y,t)\in \SetR \cap \mathcal{V}_{n}$, we have that 
    \begin{equation}
     \Lpat(x,s;y,t) > - \infty \quad \text{ for all } (x,s;y,t)\in \SetR \cap \mathcal{V}_{n} , 
 \end{equation}
and there are unique rightmost and leftmost inherited geodesics for $ \Lpat$, which we denote by $\pinpt_{x,s;y,t}$ and $\pinmt_{x,s;y,t}$, respectively.
\item[(v)]  The result in \hyperref[eq:Patched2]{(ii)} holds true with $\mathcal{V}_n$ replaced by $\mathcal{D}_{n^{-1}}$ from \eqref{eq:ProbabilityBound} and/or when $\Lpat$ is replaced by $\Lpa$ (in which case we write $\pinp_{x,s;y,t}$ and $\pinm_{x,s;y,t}$ for the rightmost and leftmost wrapped inherited geodesics).
\end{enumerate}","status":"unverified"}

