		\item $u^{m+1} \in L^{1}_{\loc}(Q_{T})$.
		\item $u \in C((0,T);L^{1}_{\loc}(\R^{d}))$.
		\item For all $\vp \in C^{\infty}_{c}(Q_{T})$, we have
		\begin{equation} 
			\int_{\R^{d}} \int_{0}^{T} \left(u \vp_{t} + (u^{m+1})\frac{1}{2d}\Delta\vp\right)\,dt\,dx = 0.
