        W_n=\big(1+o(1)\big)\sum_{m=\max\{\lfloor t_{\mu/n}\rfloor,3\}}^{\lceil t_{\mu/n}\rceil}\frac{\tan^2\frac{\pi}{m}}{m}\exp\left(-\mu m-n\log\left(1+\tan^2\frac{\pi}{m}\right)\right)\,.
    \end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:01:15.317260+00:00","domain":"probability theory","id":"claim_0855786312c901ca2eef054a175167b06167a662fc974147472c035ff8e4c2f7","kind":"lemma","schema_version":1,"statement":"[Lemma 3 of arXiv:2608.30232, 'Strong Unique Continuation for Fractional Schr\"odinger Operators'] For every \(m\ge1\), \(g\in C_c^\infty(\mathbb R^n\setminus\{0\})\), and
\(\gamma\in\mathbb R\),
\begin{align}
 \|T_{i\gamma}^{(m)}g\|_{L^2(d\mu)}
