{"assumptions":[],"created_at":"2026-10-27T20:29:14.971628+00:00","domain":"probability theory","id":"claim_08c0dcf03893e3513212396442dec324f5d1d22a012860db636eb84c5d5cd1bb","kind":"concept","schema_version":1,"statement":"[Lemma part2 of arXiv:2606.15203, 'The existence of invariant sublinear expectations for $G\text{-}$SDEs'] Under the assumptions \textbf{(H1)} and \textbf{(H2)}, for any $\varphi \in B_b(\mathbb{R}^d)$,
  \begin{equation*}
   \nu(t,x) \coloneqq \underset{\theta \in  \mathcal{A}^{\Theta}_{t,T}}{{\rm sup}} E_P[\varphi(x+\int^T_t b(X_s^{t,x,\theta})ds+\int_t^T\theta_sdW_s)]  
 \end{equation*}
