{"assumptions":[],"created_at":"2026-10-26T20:52:45.033509+00:00","domain":"probability theory","id":"claim_08e3d17a66a83ca2146f578c9a0e9b6b3fd38f45c61bf96935f0ae102c855c69","kind":"theorem","schema_version":1,"statement":"[Proposition 5 of arXiv:2606.07839, 'Bounds on Spectral Gaps for Non-Reversible Markov Chains with Applications to Temporal Dif'] Let $P$ be a Markov kernel with invariant probability distribution $\mu$. Let $\phi_1,\ldots,\phi_n$ and $A$ be as in Proposition~\ref{prop:irreducibleHurwitz} and $\lambda\in [0,1)$.
  Define the matrix $S\in\bbC^{n\times n}$ by
  \begin{align*}
  S_{ij}&=\langle \phi_i,\phi_j\rangle - \overline{(\mu \phi_i)}(\mu\phi_j).        
  \end{align*}

  Let $\preceq$ denote the positive semidefinite partial order, and let $\gamma$ denote the smallest eigenvalue of $S$. Then $A$ satisfies the linear Lyapunov inequality:
  \begin{equation}

  \frac{1}{2}(A+A^\star)\preceq -(1-\lambda)\gap(P)\gamma I.
\end{equation}
In particular, the eigenvalues of $A$ have real parts at most $-(1-\lambda)\gap(P)\gamma$.

  If the following conditions hold:
  \begin{enumerate}
  \item  $\gap(P)>0$ 
  \item  
    the functions $\{\phi_1,\ldots,\phi_n\}$ are linearly independent,
  \item  
    the constant function, $\ones$, is not in the span of $\{\phi_1,\ldots,\phi_n\}$, 
  \end{enumerate}
 then $(1-\lambda)\gap(P)\gamma >0$ and so $A$ is Hurwitz.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:47:53.352903+00:00","domain":"probability theory","id":"claim_08e494bc99b96834b33763069706af13e0ee7395b99e057282eac5f5685ee962","kind":"theorem","schema_version":1,"statement":"[Theorem 10 of arXiv:2607.15903, 'Uniqueness for nonlinear Fokker-Planck equations with general diffusion terms and their as'] Assume that Hypothesis (\MakeUppercase{\romannumeral 1}) holds. Let $T>0$, and let $X^{1}(t)$ and $X^{2}(t)$ be two probabilistically weak solutions to (\ref{9}) on the stochastic bases $(\Omega_{1} ,\mathscr{F}_{1},(\mathscr{F}^{1}_{t})_{t \geqslant 0}, \mathbb{P}_{1})$, $(\Omega_{2} ,\mathscr{F}_{2},(\mathscr{F}^{2}_{t})_{t \geqslant 0}, \mathbb{P}_{2})$ such that $\mathcal{L}_{X^{1}(t)}, \mathcal{L}_{X^{2}(t)}$ are absolutely continuous w.r.t Lebesgue measure $dx$ and for
\begin{equation}
    u_{1}(t,\cdot):=\frac{d\mathcal{L}_{X^{1}(t)}}{dx},\quad u_{2}(t,\cdot):=\frac{d\mathcal{L}_{X^{2}(t)}}{dx},\notag
\end{equation}
we have
 \begin{equation}
    u_{1},u_{2} \in L^{1}((0,T)\times \mathbb{R}^{d})\cap L^{\infty}((0,T)\times \mathbb{R}^{d}) .\notag
 \end{equation}
 Then, $X^{1}$ and $X^{2}$ have the same law, i.e. $\mathbb{P}_{1}\circ (X^{1})^{-1}=\mathbb{P}_{2}\circ (X^{2})^{-1}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:01:25.655805+00:00","domain":"probability theory","id":"claim_08e9bc964ea808436efecd9eab3f6503de538049f7c82dc4c0337e999987339a","kind":"concept","schema_version":1,"statement":"[Lemma of arXiv:2605.16162, 'Deconfinement For $\mathrm{SO}(3)$ Lattice Yang--Mills at Strong Coupling'] Suppose $k<N$ and both $k$ and $N$ are odd. Then if $Q \sim \mrm{Haar}(\mrm{SO}(N))$,
