{"assumptions":[],"created_at":"2026-10-28T00:22:21.905038+00:00","domain":"probability theory","id":"claim_08f12872b3edeb5dd618fd9f5415c6db56086c8f5b99f0e123aa171203de25cb","kind":"theorem","schema_version":1,"statement":"[Theorem thm:characterization_two-sided_symmetric of arXiv:2411.11425, 'Non-equilibrium steady states with a spatial Markov structure'] Consider a one-site density $\Lambda^{(1)}$. The following two statements are equivalent:

\begin{enumerate}
    \item There exists a symmetric and two-sided Markov family $\{\Lambda^n\}_{n \geq 0}$ with one-site density $\Lambda^{(1)}$.

    \item $\forall z_1,z_2 \in \mathbb{R}^+$, $a,b \in I_{z_1,z_2}$ there exists a symmetric $g: \mathbb{R}^2 \rightarrow \mathbb{R}^+$ such that 

    \begin{equation}

        \Lambda^1_{a,b} (x) = f(a,b) \cdot g(b,x) \cdot g(x,a) \cdot \mathds{1}(x \in I_{a,b})
    \end{equation}

    with normalization

    \begin{equation}
        f(a,b) = \Bigg (\int_{a \wedge b}^{a \vee b}  g(b,y) \cdot g(y,a) dy \Bigg)^{-1}.
    \end{equation} 
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:24:25.984404+00:00","domain":"probability theory","id":"claim_08f213de13abea983dd35f1de39fb70b5a3923447234af2d6df2aa4256db4805","kind":"lemma","schema_version":1,"statement":"[Lemma 41 (cf. {\cite[Lemma 3.4 and Lemma 3.5) of arXiv:2507.07702, 'Observables of random spanning trees in random environment'] {MSS24}}] 
