        \end{align*}
                                when $r\ge \fc{4}{\ep'}\log \pf{2}{\ep'}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:05:57.797429+00:00","domain":"probability theory","id":"claim_093f6077bcce69a13ce714a70720ddc621d9e25972cba495caf36595fb5d264e","kind":"concept","schema_version":1,"statement":"[Theorem 3 of arXiv:2608.30551, 'Critical Discrete Hardy Inequalities in $L^p$'] Let $p>1$, $\sigma\in(0,1/2)$, and $\alpha\in(\sigma,1/2)$. If
$u\in\ell^p(\Z,(1+|x|)^{-2\sigma})$, then
\begin{equation}
\mathcal{E}_p^{\Z,\sigma}(u)
\geq
\sum_{x\in\Z}w_{p,\sigma,\alpha}(x)|u(x)|^p,
\end{equation}
where $w_{p,\sigma,\alpha}$ is given by
\begin{equation}
w_{p,\sigma,\alpha}(x)
:=
\frac{1}{a_p+1}
\frac{\Delta^\sigma k_{-\alpha}^{a_p}(x)}
     {k_{-\alpha}^{a_p}(x)}
+
\frac{a_p}{a_p+1}
\frac{\Delta^\sigma k_{-\alpha}(x)}
     {k_{-\alpha}(x)},
\qquad x\in\Z.
\end{equation}
The Hardy weight $w_{p, \sigma, \alpha}$ is strictly positive and as $|x|\to\infty$,
\begin{equation}
w_{p,\sigma,\alpha}(x)
=
\frac{\Psi(p,\sigma,\alpha)}{|x|^{2\sigma}}
+
O\left(
\frac{1}{
|x|^{2\sigma+1-\max\{2\sigma,1-2\alpha\}}
}
\right),
\end{equation}
where
\begin{equation}
\Psi(p,\sigma,\alpha)
:=
\frac{1}{a_p+1}
\frac{\mathcal{A}_{\gamma_p-\sigma}}
     {\mathcal{A}_{\gamma_p}}
+
\frac{a_p}{a_p+1}
\frac{\mathcal{A}_{\alpha-\sigma}}
     {\mathcal{A}_{\alpha}},
\end{equation}
with
\begin{equation}
\gamma_p
:=
\frac{1-a_p(1-2\alpha)}{2}.
\end{equation}
Moreover, $w_{p,\sigma,\alpha}$ is critical whenever
\begin{equation}
\alpha
\leq
\frac{2\sigma+a_p}{2(a_p+1)}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:06:06.297269+00:00","domain":"probability theory","id":"claim_09417f922cc55b784abbb00616c7cad1bdadd9abf3ea455329731d422fe7f9b2","kind":"theorem","schema_version":1,"statement":"[Proposition thm:local convergence of arXiv:2605.22787, 'Invariant measures for half-space geometric LPP: classification and the one force--one sol'] Fix $q\in (0,1)$, $c\in [0,1)$, and $M>1$. For each $m\in \mathbb{N}$, let $(y_{1,m},y_{2,m})\in \mathbb{Z}^2$ satisfy
