{"assumptions":[],"created_at":"2026-10-27T23:00:22.781639+00:00","domain":"probability theory","id":"claim_09ad81dcf1ae580c452fb1556da0795fdbe7bcfe23f8c6e06445ef7622ab89fa","kind":"theorem","schema_version":1,"statement":"[Cor vartheta expansion and analysis of arXiv:2411.01633, 'On the Limit of the Tridiagonal Model \\for $\beta$-Dyson Brownian Motion'] There is a $C=C(T,k)>0$ such that on a set $A_k$ with $\mathbb{P}(A_k)>1-c(T,k)n^{-2}$ the following holds.
    \begin{enumerate}
        \item For any deterministic unit vector $v \in V_{k}=\mathrm{Span}(\{e_j\}_{j=1}^k)$ and $x(t) \in \{\vartheta_j(t)\}_{j\leq k} \cup\{M(t)^{j_1}e_{j_2+2}\}_{0 \leq j_1 \leq k, 0 \leq j_2 \leq k-1}$
    \begin{equation}
        \sup_{t \in [0,T]} |\langle x(t),v \rangle| \leq \frac{C\log(n)^k}{\sqrt{n}}.

    \end{equation}
    In particular, the inequality also holds for $x(t)=\vartheta_j(t)$ for $j=1,\dots ,k$.
    \item For $j, \ell =0,1,\dots,k$,
    \begin{equation}
        \sup_{t \in [0,T]} |\vartheta_j(t)^T\vartheta_{\ell}(t)-\delta_{j,\ell}| \leq \frac{C\log(n)}{\sqrt{n}}.

    \end{equation}
    \item For $j, \ell =0,1,\dots ,k$, we have
    \begin{equation}
        \begin{split}
            ~&\vartheta_j(t)=(c_j(t)+\mu_j(t))\theta_j(t)+\\
            &\bigg( \vartheta_j(t)^T\frac{\theta_{j-1}(t)}{\|\theta_{j-1}(t)\|^2}-c_j(t)\theta_j(t)^T\theta_{j-1}(t)+\tilde{\mu}_j(t)\bigg)\theta_{j-1}(t)+\tilde{\epsilon}_{j}(t)
        \end{split}
    \end{equation}
     with $c_j(t):=\frac{1}{\|\theta_{j-1}(t)\|}$, $\tilde{\epsilon}_{j}(t) \in \Theta_{j-2}(t)+ \mathcal{E}_j(t)$, $\sup_{t \in [0,T]}||\tilde{\epsilon}_{j}(t)|| \leq C_{k,T} \frac{\log(n)^{k}}{\sqrt{n}}$, and $\sup_{t \in [0,T]} (|\mu_j(t)|+|\tilde{\mu}_j(t)|) \leq C_{k,T}\frac{\log(n)^{2(k-1)}}{n}$.
    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:35:57.052593+00:00","domain":"probability theory","id":"claim_09ae60ded22a8b8560f6c8490f04fad8dc0a45e6977b75429a079135c6684838","kind":"concept","schema_version":1,"statement":"[Lemma E[deg-edges]_asymp of arXiv:2604.05921, 'Simplicity of random hypergraphs'] If $\forall e \in E: \delta_e = \delta\in O(1)$ and
