{"assumptions":[],"created_at":"2026-10-26T19:44:17.167758+00:00","domain":"probability theory","id":"claim_09bcb46d3dc5a82ab65609cc2fd4843dfc89e8386d6fe3a37441c667a355aec5","kind":"lemma","schema_version":1,"statement":"[Lemma 10 of arXiv:2604.17973, 'Schauder estimates and classical solutions of the Dirichlet problem for stochastic parabol'] Let $\alpha\in(0,1)$, let $h\in C^{1+\alpha/2}([0,T];L_\omega^\gamma)$ satisfy
\[
h(0)=0,
\qquad
h'(0)=0,
\]
and let $v$ be the solution of
\begin{equation}
\partial_t v(t,y)=\partial_y^2 v(t,y),
\qquad
v(0,y)=0,
\qquad
v(t,0)=h(t).
\end{equation}
Then
\begin{equation}
|\partial_t v|_{(\alpha,\alpha/2);[0,T]\times\R_+}^{L_\omega^\gamma}
+|\partial_y^2 v|_{(\alpha,\alpha/2);[0,T]\times\R_+}^{L_\omega^\gamma}
\le C\,[h']_{\alpha/2;[0,T]}^{L_\omega^\gamma},
\end{equation}
where $C=C(\alpha,\gamma,T)$. 

Moreover, if $v_1$ and $v_2$ correspond to boundary data $h_1$ and $h_2$, respectively, and if $h_1'(0)=h_2'(0)=0$, then
\begin{equation}
\sup_{(t,y)\in[0,T]\times\R_+}
\E\bigl|\partial_y^2 v_1(t,y)-\partial_y^2 v_2(t,y)\bigr|^\gamma
\le C\sup_{t\in[0,T]}\E\bigl|h_1'(t)-h_2'(t)\bigr|^\gamma.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:50:36.765467+00:00","domain":"probability theory","id":"claim_09bce072b18f23c3262c5094ce5bb53474c6ca6b60fd5de1b0d169b026072054","kind":"lemma","schema_version":1,"statement":"[Lemma 23 of arXiv:2609.04155, 'The subconvexity problem for symmetric square\\ $L$-functions in Level aspect'] (Method of stationary phase)
			Let $w(x)$ be a nice function supported on $x\asymp X$, and suppose for all $j\geq 1$ the phase function $\phi(x)$ satisfies, 
			\begin{equation*}
				X^j \partial_x^j \phi(x)\ll Y.
			\end{equation*}
			Now suppose for some $x_0\asymp X$, known as stationary point, we have $\phi^\prime(x_0)=0$ and $X^2\partial_x^2\phi(x)\gg Y$. If $Y\gg R\geq 1$ for some $R$, then for any large $A>0$ we have
			\begin{equation}
				\int_\R w(x)e\left(\phi(x)\right)\, dx = \frac{X}{\sqrt{Y}}e\left(\phi(x_0)+\frac{1}{8}\right)w(x_0)+O_A\left(\frac{X}{R^A}\right).
			\end{equation}","status":"unverified"}

