\end{align}
where $c_n>0$, $I_{ij}(u)=c_{ij}\prod_{k=1}^{m_{ij}}(D^{\alpha_{ijk}}u)^{n_{ijk}}$ with $c_{ij}>0$, $|\alpha_{ijk}|\le 2n-2$, and $\alpha_{ijk}\in \mathbb{Z}^+$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:43:19.216721+00:00","domain":"probability theory","id":"claim_09fb8984c0184bd7dbb709477f5c8e8399c2d2910b1939911af814f84af34907","kind":"lemma","schema_version":1,"statement":"[Lemma 2602021059 of arXiv:2609.02626, 'Comparison principles and symmetry for subquadratic fractional $p$-Laplacian equations'] Let $N\ge 1$, $s\in (0, 1)$, $1<p<2$, and $u\in \widetilde{W}^{s,p}(U)\cap\widetilde{W}^{s,p}(\mathcal{T}(U))\cap  L^{\infty}(\mathbb{R}^N)$ where $U\subset  \mathbb{R}_+^N$ is a bounded open set.  If $w=u-u^*\ge 0$ a.e. in $\mathbb{R}^N_+\backslash U$, there holds 
\begin{equation}
\begin{aligned}
&\quad \int_{\mathbb{R}^{N}\times \mathbb{R}^{N}}\frac{(J_{u}(x, y)-J_{u^*}(x, y))\left(w_-(x){\mathbbm 1}_{U}(x)-w_-(y){\mathbbm 1}_{U}(y)\right)}{|x-y|^{N+sp}}{\rm d}x{\rm d}y\\
&\le-2^{p-1}(p-1)\|u\|^{p-2}_{L^\infty(\mathbb{R}^N)}\Big[\int_{A_3}\frac{w_-^2(x)}{|x-y|^{N+sp}}{\rm d}x{\rm d}y+\frac12\int_{A_4}\frac{\big|w_-(x)-w_-(y)\big|^2}{|x-y|^{N+sp}}{\rm d}x{\rm d}y\\
&\quad +\int_{A_4}\frac{w_-^2(x)}{|x-y^*|^{N+sp}}{\rm d}x{\rm d}y+\int_{U\times (\mathbb{R}^N_+\backslash U)}\frac{w_-^2(x)}{|x-y|^{N+sp}}{\rm d}x{\rm d}y\Big].\\
\end{aligned}
\end{equation}","status":"unverified"}

