    &\quad \frac{1}{m} \left[ \frac{\mu^2 S_e^{ 2}}{\mu -\frac{1}{2}\frac{2 \mu + \gamma}{\beta}  \sigma_1^2 I_e} +\frac{1}{2} \mu \kappa \sigma^2 x_e(1-x_e)+\mu x_e +\mu S_e(1-S_e) \right],
\end{align*}
almost surely, where $m=\min(\mu -\frac{1}{2}\frac{2 \mu + \gamma}{\beta}  \sigma_1^2 I_e , \, \mu +\gamma,\, \mu \left( \frac{1}{2} k \sigma^2 - 2 \delta \right))$.","status":"unverified"}

