{"assumptions":[],"created_at":"2026-10-27T17:42:08.474945+00:00","domain":"probability theory","id":"claim_0a7ba668af2961e9288a1b5e9bab55f2417d46eb753530968882838d5a402cd1","kind":"lemma","schema_version":1,"statement":"[Lemma lemma7 of arXiv:2511.19391, 'Central limit theorem for supercritical Crump-Mode-Jagers processes counted with non-indiv'] Suppose that assumptions (A1 of the paper)-(A8 of the paper) hold. Then,
\begin{enumerate}[label=(\textbf{\roman*})]
\item For $\lambda \in \Lambda_{\geq}$ of multiplicity $k \in \mathbb{N}$ and fix vectors $a,b \in \mathbb{R}^{k}$, the characteristic $a^{\top} \phi_{\lambda} b$ has c\`adl\`ag paths and satisfies (C1 of the paper)-(C3 of the paper). Moreover, for all $h \in \mathbb{N}_{0}$ and $\varepsilon >0$, 
\begin{align} 
\mathbb{E} \left[ \sum_{i=0}^{h} \sum_{|u|=i} \sup_{|s-t|\leq \varepsilon}|a^{\top}\phi_{\lambda, u}(s-S(u))b| \mathbf{1}_{(-\infty,0)}(s-S(u)) \right] < \infty
\end{align}
\noindent and 
\begin{align} 
\left(\sum_{i=0}^{h} \left( \sum_{|u|=i}|a^{\top}\phi_{\lambda, u}(s-S(u))b|  \right)^{2}\right)_{|s-t|\leq \varepsilon} \quad \text{is uniformly integrable}.
\end{align}

\item For $\lambda \in \Lambda$ of multiplicity $k \in \mathbb{N}$ and fix vectors $a,b \in \mathbb{R}^{k}$, the characteristic $a^{\top} \chi_{\lambda} b$ has c\`adl\`ag paths and satisfies (C1 of the paper)-(C3 of the paper). Moreover, for all $h \in \mathbb{N}_{0}$ and $\varepsilon >0$,  
\begin{align} 
\mathbb{E} \left[ \sum_{i=0}^{h} \sum_{|u|=i} \sup_{|s-t|\leq \varepsilon}|a^{\top}\chi_{\lambda, u}(s-S(u))b| \mathbf{1}_{(-\infty,0)}(s-S(u)) \right] < \infty
\end{align}
\noindent and 
\begin{align} 
\left(\sum_{i=0}^{h} \left( \sum_{|u|=i}|a^{\top}\chi_{\lambda, u}(s-S(u))b|  \right)^{2}\right)_{|s-t|\leq \varepsilon} \quad \text{is uniformly integrable}.
\end{align}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T16:38:11.916572+00:00","domain":"probability theory","id":"claim_0a7be1c0f57b1c96c83e2b9aa0655801ed7cadd7b46fe66dbb8e62c11f4d84e7","kind":"concept","schema_version":1,"statement":"[Theorem thm|integrationByPartsSpec of arXiv:2504.08935, 'Higher-Order Derivatives of First-Passage Percolation with Respect to the Environment'] For every nonempty $S\subseteq W$ and every random variable $\varphi$, the expected value of $\varphi r_S$ satisfies
