{"assumptions":[],"created_at":"2026-10-27T12:17:13.067076+00:00","domain":"probability theory","id":"claim_0a8c224e8930d7a5f15bbc958f1861c5ee78992c2e832025b4bb7cf5ed9a86e3","kind":"theorem","schema_version":1,"statement":"[Cor rulea of arXiv:2508.04954, 'Conditional exponential directed last passage percolation under a one-point upper large de'] Define
\begin{equation}
    \mathsf{A}^{m,n}_i:= i! \binom{m}{i}\binom{n}{i} .
\end{equation}
\begin{enumerate}[(a)]
\item 
If ${\boldsymbol \sigma}=\cdots \alpha^m\beta^n\cdots$ with $\{\alpha,\beta\}\notin \{ \{1, 2\}, \{2, 3\}, \{12, 3\}, \{1, 23\} \}$, then $\mathrm I^{{\boldsymbol \sigma}}_{{\boldsymbol \tau}} = \mathrm I^{{\boldsymbol \sigma}'}_{{\boldsymbol \tau}}$ where 
${\boldsymbol \sigma}'= \cdots \beta^{m} \alpha^{n}\cdots$.

\item  
If ${\boldsymbol \sigma}=\cdots \alpha^m\beta^n\cdots$ with $\{\alpha,\beta\}\in \{ \{1, 2\}, \{2, 3\}, \{12, 3\}, \{1, 23\} \}$, then\footnote{For example, if ${\boldsymbol \sigma}=\cdots 3^m (12)^n\cdots$, then ${\boldsymbol \sigma}_i= \cdots (12)^{n-i} (123)^i 3^{m-i}\cdots$.} 
\begin{equation*} \begin{split}
    \mathrm I^{{\boldsymbol \sigma}}_{{\boldsymbol \tau}} 
    =  \sum_{i=0}^{m\wedge n} (-1)^{\#} \mathsf{A}^{m,n}_i \mathrm I^{{\boldsymbol \sigma}_i}_{{\boldsymbol \tau}} , \qquad
    {\boldsymbol \sigma}_i= \cdots \beta^{n-i} (\alpha\beta)^i \alpha^{m-i}\cdots.
\end{split} \end{equation*}

\item 
If ${\boldsymbol \tau}=\cdots \alpha^m\beta^n\cdots$ with $\{\alpha,\beta\}\notin \{ \{1, 2\}, \{2, 3\}, \{12, 3\}, \{1, 23\} \}$, then 
$\mathrm I^{{\boldsymbol \sigma}}_{{\boldsymbol \tau}} = \mathrm I^{{\boldsymbol \sigma}}_{{\boldsymbol \tau}'}$ where ${\boldsymbol \tau}'= \cdots \beta^{m} \alpha^{n}\cdots$. 

\item  
If ${\boldsymbol \tau}=\cdots \alpha^m\beta^n\cdots$ with $\{\alpha,\beta\}\in \{ \{1, 2\}, \{2, 3\}, \{12, 3\}, \{1, 23\} \}$, then 
\begin{equation*} \begin{split}
    \mathrm I^{{\boldsymbol \sigma}}_{{\boldsymbol \tau}} 
    =  \sum_{i=0}^{m\wedge n} (-1)^{\#} \mathsf{A}^{m,n}_i \mathrm I^{{\boldsymbol \sigma}}_{{\boldsymbol \tau}_i} , \qquad
    {\boldsymbol \tau}_i= \cdots \beta^{n-i} (\alpha\beta)^i \alpha^{m-i}\cdots.
\end{split} \end{equation*}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:52:17.372781+00:00","domain":"probability theory","id":"claim_0a8cd47f1e01d6f62c8f508479c5d814ca492f00145713a0678643e2ddccbdb3","kind":"concept","schema_version":1,"statement":"[Lemma 8 (Tightness criterion check for regularly-varying covariance) of arXiv:2606.04179, 'Functional Scaling Limits of Interpolated Correlated Random Walks in Hölder Topology'] If \(\abs{\rho(k)} =  \abs{k}^{-\alpha}\slowVar(k)\) for a slowly
