{"assumptions":[],"created_at":"2026-10-27T21:59:24.048597+00:00","domain":"probability theory","id":"claim_0ae61d59a2b12bf239d00d0f2b0e47f92d213af65f7945260e7f6f2174a8e251","kind":"lemma","schema_version":1,"statement":"[Lemma lem:ac-curvature-free-potential-estimate of arXiv:2608.30779, 'Some uniform estimates for K\"ahler--Ricci Shrinkers'] One has
\begin{align}
 \dot\varphi_t(x)
 &=-\int_{-1}^t\frac{R_\omega(\Phi_s(x))}{|s|}\,ds,
 \\
 \varphi_t(x)
 &=-\int_{-1}^t(t-s)\frac{R_\omega(\Phi_s(x))}{|s|}\,ds.

\end{align}
In particular,
\begin{equation}
        -\rho^2(x)\le\varphi_t(x)\le0,
