	\begin{equation}
		h_{k,i}(\overline{y}):=\begin{cases}1 & \text{ if $\overline{y}=\emptyset$}\\ \\\displaystyle{\prod_{r=1}^m \amalg_{{\rm B}^-[0;i]}(y_r) \Pi_{{\rm B}^+[0;i]}(0,y_r')} &\text{ if $\overline{y}=((y_1,y_1'),\dots,(y_{m},y'_{m})) \in \textrm{E}_{m}[i]$ for $m \in \mathbb N$}.
