{"assumptions":[],"created_at":"2026-10-28T01:10:08.769989+00:00","domain":"probability theory","id":"claim_0b1d8b25fd64b0d2be2fb95bcbdeffd8464104d442aaab5f10d4eb2f47e47487","kind":"lemma","schema_version":1,"statement":"[Lem thm:norm-lemma-bernoulli of arXiv:2411.18155, 'Besov regularity of random wavelet series'] Let $d\in\mathds{N}$, $s,\alpha,\beta,\gamma\in\mathds{R}$, $p,r\in (0,\infty)$, $q\in (0,\infty]$, and $\mu,\nu \in (-\infty,0]$.
Let further $(\xi_{j,t,m})_{(j,t,m)\in\mathds{N}_0\times\left\{F,M\right\}^d\times\mathds{Z}^d}$ and $(\lambda_{j,t,m})_{(j,t,m)\in\mathds{N}_0\times\left\{F,M\right\}^d\times\mathds{Z}^d}$ be two families of random variables with $\xi_{j,t,m}\in\mathds{R}$ and $\lambda_{j,t,m}\in\left\{0,1\right\}$ for $(j,t,m)\in\mathds{N}_0\times\left\{F,M\right\}^d\times\mathds{Z}^d$.
Set
\begin{equation*}
\varrho_{j,m}\mathrel{\mathop:}= 2^{j\mu}\lr{1+\frac{\left\lVertm\right\rVert_\infty}{2^j }}^\nu
\end{equation*}
and $a=(a_{j,t,m})_{(j,t,m)\in J}$ where
\begin{equation*}
a_{j,t,m}\mathrel{\mathop:}= 2^{j\alpha} \lr{1+\frac{\left\lVertm\right\rVert_\infty}{2^j}}^{\beta + (\gamma-\beta)\mathds{1}_{j=0}}\lambda_{j,t,m}\xi_{j,t,m}
\end{equation*}
for $(j,t,m)\in J$.
If Property A'' is satisfied, then for $\widetilde{\Xi}$ as in 
  \hyperref[{eq:master-quantity-bernoulli}]{\textup{\tagform@{\ref*{eq:master-quantity-bernoulli}}}}
, we have $\left\lVerta\right\rVert_{b^s_{p,q}(\mathds{R}^d)}\lesssim\widetilde{\Xi}^{\frac{1}{p}}$ where the implied constant only depends on $\mu$, $\nu$, $\beta$, $\gamma$, $p$, $d$, and $r$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:07:35.023593+00:00","domain":"probability theory","id":"claim_0b209e77216d14ad39b1d09ea15c66fc1fe91ad2261696e130d554ce23f84353","kind":"lemma","schema_version":1,"statement":"[Lem 8 of arXiv:2609.02879, 'On the cut locus of Hamilton--Jacobi equations I: structure and propagation via the touchi'] Let $M$ be a compact connected smooth manifold without boundary, $H$ a Tonelli Hamiltonian on $M$, $\phi\in\SCL(M)$, and $u$ the viscosity solution of \eqref{eq:HJephi pre}. If $x\in\reg(\phi,H)$ and $t\in(0,\tau_{\phi,H}(x)]$ for $\tau_{\phi,H}(x)<+\infty$, or $t\in(0,+\infty)$ for $\tau_{\phi,H}(x)=+\infty$, then there exists a unique $(u,H)$-calibrated curve $\gamma:[0,t]\to M$ with $\gamma(0)=x$, and it is given by
	\begin{align*}
		\gamma(s)=\pi\circ\Phi^s_H(x,D\phi(x)),\qquad \forall s\in[0,t],
	\end{align*}
	where $\pi:T^*M\to M$ is the canonical projection and $\Phi^s_H$ is the Hamiltonian flow of $H$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:16:53.607442+00:00","domain":"probability theory","id":"claim_0b23cc49dc5689498af37cb9777a2f1fb6e94b011ff0fb055af7bf76ef424979","kind":"lemma","schema_version":1,"statement":"[Lemma lemm:est-S3 of arXiv:2412.05142, 'Strong convergence of the Euler scheme for singular kinetic SDEs driven by $\alpha$-stable'] Let $\phi:[0,1]\times\Omega\rightarrow{\mathbb R}^{2d}$ be a bounded measurable function. Let    $f\in{\mathbb C}_{\boldsymbol{a}} ^{(1+\alpha)\beta}$ for $\beta\in (0,\alpha-1)$. Further assume
    \begin{enumerate}
        \item there exist constants $\gamma_1,\gamma_\phi>0$ so that
        \begin{align}

        \gamma_1&>\frac{1}{2}+\frac{1}{\alpha}+\frac{\beta}{\alpha}\wedge\frac{1}{2}-\frac{\beta}{\alpha};\\

           {\mathbb E}^s|{\mathbb E}^t\phi_r-{\mathbb E}^s\phi_r|&\leqslant \gamma_\phi|r-s|^{\gamma_1}, \quad  (s,r)\in[0,1]_\leqslant^2, t\in[s,1];
        \end{align}
        \item  $\phi_{k_n(t)}$ is ${\mathcal F}_{(k_n(t)-n^{-1})\vee0}$ measurable,  $n\in{\mathbb N}$;
        \item $\phi\equiv0$ or $\beta>0$.
    \end{enumerate}
    Then for any $0<\epsilon<\frac{1}{2}$ there exists a constant $N=N(\alpha,\beta,d,\gamma_1,\epsilon)$ independent of $n$ so that for any $(S,T)\in [0,1]_\leqslant^2$ and any $\sigma$-algebra ${\mathscr G}\subset{\mathcal F}_{k_n(s)}$ the following holds
    \begin{align}

         \| \int_S^T &f(M_r+\Gamma_{r-k_n(r)}\phi_{k_n(r)})-\Gamma_{r-k_n(r)}f(M_{k_n(r)}+\phi_{k_n(r)})dr\|_{L_2(\Omega)|{\mathscr G}}\nonumber\\&\leqslant N \|f\|_{{\mathbb C}_{\boldsymbol{a}}^{(1+\alpha)\beta}}(1+\gamma_\phi)n^{-(\frac{1}{2}+\frac{\beta}{\alpha}\wedge\frac{1}{2})+2\epsilon}|T-S|^{\frac{1}{2}+\epsilon}.
    \end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:12:08.972806+00:00","domain":"probability theory","id":"claim_0b23f1e6ef208fcd788cd4939bf8b1041631e4d672fe36e4c6040659069eae4e","kind":"concept","schema_version":1,"statement":"[Thm thm_mainRiemannianManifold of arXiv:2608.17463, 'Persistence probabilities of fractional L\'evy fields indexed by hyperbolic space and othe'] For $0<H\leq 1/2$ let $(X_{H}(\eta))_{\eta\in\mathcal{M}}$ be the fractional L\'evy field on the $d$-dimensional connected Riemannian manifold $\mathcal{M}$ without boundary. For any relatively compact set $K\subset \mathcal{M}$ with $O$ in the interior of $K$ we have
    \begin{align*} 
        \prob{ \sup_{\eta\in K} X_{H}(\eta) < \varepsilon}  =\varepsilon^{\frac{d}{H} + \mathdutchcal{o}(1)}, \qquad \text{ as } \varepsilon\searrow 0.
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:56:36.579909+00:00","domain":"probability theory","id":"claim_0b25421f1e8f23bf44231c8109cdada2a057772b746aa2b42b69ef9df6e306b7","kind":"lemma","schema_version":1,"statement":"[Lemma lem: Solutions Near P_3 of arXiv:2608.30443, 'On smooth holosphere solutions to compressible Euler equation'] Assume (equation eq: Parameters of the paper). Let $c_+$, $c_-$, $A$ be given by (equation eq: c_pm of the paper), (equation eq: A of the paper).  Then, 
