{"assumptions":[],"created_at":"2026-10-27T16:03:35.743784+00:00","domain":"probability theory","id":"claim_0bb97f1d1611a0aa0abad6f327c332ebe5b2a594a1f2cf92d7096efcbb144f5a","kind":"theorem","schema_version":1,"statement":"[Prop boundedFeatureQuadLaplace of arXiv:2609.02743, 'Sharp mean-field estimates for diffusive log/Riesz gases in the Hilbert--Schmidt regime'] Assume that $\tilde{\mathsf{g}}$ admits a Hilbert-space feature representation: there are a separable real Hilbert space $\mathcal H$ and a strongly measurable map $k:{\mathbb{R}}^\mathsf{d}\to\mathcal H$ such that
\begin{align}
\tilde{\mathsf{g}}(x,y)=\langle k(x),k(y)\rangle_{\mathcal H}
\quad\text{for $\mu^{\otimes2}$-a.e. }(x,y),
\qquad
\int_{{\mathbb{R}}^\mathsf{d}}k\,\mathop{}\!\mathrm d\mu=0.
\end{align}
Set
\begin{align}
D(x)\coloneqq\|k(x)\|_{\mathcal H}^2,
\qquad
\mathcal M_\beta(k)\coloneqq
\int_{{\mathbb{R}}^\mathsf{d}}e^{\beta D(x)/2}\pa*{1+D(x)^4}\,\mathop{}\!\mathrm d\mu(x).
\end{align}
If $\mathcal M_\beta(k)<\infty$, then there is a constant $C_\beta<\infty$, depending only on $\beta$, such that, for every $N\ge1$,
\begin{align}
\Big|{\mathbb{E}}_{\mu^{\otimes N}}\Big[e^{-\frac{\beta}{2}W_N}\Big]
-\mathrm{det}_2(\mathrm{Id}+\beta T_\mu)^{-1/2}\Big|
\le \frac{C_\beta}{N}\pa*{1+\mathcal M_\beta(k)}^3.
\end{align}
In particular, if $k\in L^\infty(\mu;\mathcal H)$, then
\begin{align}
\Big|{\mathbb{E}}_{\mu^{\otimes N}}\Big[e^{-\frac{\beta}{2}W_N}\Big]
-\mathrm{det}_2(\mathrm{Id}+\beta T_\mu)^{-1/2}\Big|
\le C_\beta\exp\pa*{C_\beta\beta\|k\|_{L^\infty(\mu;\mathcal H)}^2}N^{-1}.
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:32:15.348261+00:00","domain":"probability theory","id":"claim_0bbd4d8745a3fa48f33d6cd6177a6ab8c4ee4e581ece0aaeef15926d7e150eb8","kind":"concept","schema_version":1,"statement":"[Proposition 2 of arXiv:2506.15159, 'Conditional central limit theorems for exponential random graphs'] Recall $E_n$ is the number of edges in the ERGM \cref{eq:ERGM} and $N=n(n-1)/2$.
