{"assumptions":[],"created_at":"2026-10-26T20:54:34.577533+00:00","domain":"probability theory","id":"claim_0bc17faac0cc1bc865d89819e41a39dd305aaf6267ce725cae582b3a0a44ba95","kind":"concept","schema_version":1,"statement":"[Theorem 17 of arXiv:2606.14812, 'Joint convergence in Wiener chaos via transport hierarchy and Malliavin covariances'] Let $p\geq 2$ and let $(X_N=I_p(f_N),N\geq 1)$ 
	satisfy \eqref{c1}. Let $Y_N=I_q(g_N)$ with 
	$ap\leq q<(a+1)p$ and 
	$\sup_N\|g_N\|_{H^{\otimes q}}<\infty$.

	\noindent\textbf{Non-critical case $ap<q<(a+1)p$.}
	Assume
	\begin{equation}
		(Y_N,Y_{1,N},\ldots,Y_{a,N})
		\xrightarrow[N\to\infty]{(d)}(Y,Y_1,\ldots,Y_a).
	\end{equation}

	\noindent\textbf{Critical case $q=ap$.}
	Assume
	\begin{equation}
		(Y_N,Y_{1,N},\ldots,Y_{a-1,N})
		\xrightarrow[N\to\infty]{(d)}(Y,Y_1,\ldots,Y_{a-1}),
	\end{equation}
	and $\mathbf{E}[Y_{a,N}]\to\rho_a\in\mathbb{R}$.

	\noindent In both cases, the following conclusions hold:
	\begin{enumerate}
		\item $(X_N,Y_N)\xrightarrow[N\to\infty]{(d)}(Z,Y)$ 
		where $Z\sim N(0,\sigma^2)$.
		\item There exists a random variable $\varepsilon$, 
		independent of $Z$, such that the limit admits the 
		decomposition:
		\begin{itemize}
			\item \textbf{Non-critical:}
			\begin{equation}
				Y = \sum_{r=1}^a\frac{Z^r}{p^r\sigma^{2r}}Y_r 
				+ \varepsilon,
			\end{equation}
			\item \textbf{Critical:}
			\begin{equation}
				Y = \sum_{r=1}^{a-1}\frac{Z^r}{p^r\sigma^{2r}}Y_r 
				+ \frac{\rho_a}{p^a\sigma^{2a}}Z^a + \varepsilon,
			\end{equation}
		\end{itemize}
		where in both cases $Z$ is independent of 
		$(Y_1,\ldots,Y_{a-1},\varepsilon)$ (and of $Y_a$ 
		in the non-critical case).
		\item The characteristic function of $(Z,Y)$ is:
		\begin{itemize}
			\item \textbf{Non-critical:}
			\begin{equation}
				\varphi(u,v) = \mathbf{E}\!\left[e^{iv\varepsilon}
				\exp\!\left(-\frac{\sigma^2}{2}\!\left(u+
				\frac{v}{p\sigma^2}\sum_{r=1}^a
				\frac{Z^{r-1}}{p^{r-1}\sigma^{2(r-1)}}Y_r
				\right)^2\right)\right],
			\end{equation}
			\item \textbf{Critical:}
			\begin{equation}
				\varphi(u,v) = \mathbf{E}\!\left[e^{iv\varepsilon}
				\exp\!\left(-\frac{\sigma^2}{2}\!\left(u+
				\frac{v}{p\sigma^2}\sum_{r=1}^{a-1}
				\frac{Z^{r-1}}{p^{r-1}\sigma^{2(r-1)}}Y_r
				+\frac{\rho_a v Z^{a-1}}{p^a\sigma^{2a}}
				\right)^2\right)\right].
			\end{equation}
		\end{itemize}

	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:58:38.147982+00:00","domain":"probability theory","id":"claim_0bc2a2d97f6efc350ebd5a4e0ba746077251528aa5ca1061b2652143ff7cd351","kind":"concept","schema_version":1,"statement":"[Corollary coro:fringe tree counts large of arXiv:2606.24465, 'History estimation in random recursive trees:\\Pointwise approach via iterated Jordan cent'] There exists a constant $C\ge 1$ such that for all  $t > 0$ and $n\in\mathbb{N}$
	\begin{equation*}
		\mathbb{P} \left( \big| \big\{ v\in [n]  : \mathrm{Fr}_{n}(v)  > n/t \big\} \big| >  Ct \right) \leq  \exp \left( 1 -t^{1/4} \right).
	\end{equation*}
\begin{proof}
The statement is clear for $t\leq 1$. So let $t> 1$.
Every $v\in \{u\in [n]:\mathrm{Fr}_n(u)>n/t\}$ other than the root has a parent $u\in \mathcal{U}$ and a child-index $i$ such that $(u,i)\in A_n^\prime$ and $\mathrm{Fr}_n(u)\mathrm{Fr}_n((u,i))>\,(n/t)^2$. Thus
\[
|\{v\in [n]:\mathrm{Fr}_n(v)>n/t\}\big|\le 1 + \big|\{(u,i)\in A_n^\prime:\ \mathrm{Fr}_n(u)\mathrm{Fr}_n((u,i)) > (n/t)^2\}\big|.
\]
Lemma (lem:mixed large of the paper) implies the probability that the right-hand term exceeds $Ct+1$ is at most $\exp(-t^{1/4})$, which yields the claim by increasing the constant $C$.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:42:08.474519+00:00","domain":"probability theory","id":"claim_0bc43425a8c9730246ea2f855d005db838888bf20a8b0448b3e9ea555520b1ea","kind":"lemma","schema_version":1,"statement":"[Lemma lemma5 of arXiv:2511.19391, 'Central limit theorem for supercritical Crump-Mode-Jagers processes counted with non-indiv'] Suppose that assumptions (A1 of the paper)-(A7 of the paper) hold and  let $\varphi$ be an $h$-dependent descendant characteristic, for some $h \in \mathbb{N}_{0}$, satisfying (C1 of the paper)-(C3 of the paper). Then, as $n \rightarrow \infty$, 
