{"assumptions":[],"created_at":"2026-10-26T20:58:28.471307+00:00","domain":"probability theory","id":"claim_0c11e5e303e4b82d4970479c76f3d3e55b4bb7b9096323bc6f2be690d1fb1e57","kind":"lemma","schema_version":1,"statement":"[Lemma 36 (Symmetrization and covariance) of arXiv:2606.29292, 'Intrinsic Gaussian Tensor Geometry and Random Operator Spectra'] Let $K$ be an operator-valued kernel of order $m$ as in
Definition~\ref{def:finite-rank-multiple-integral}.  Then
\begin{equation}

  I_m(K)=I_m(\operatorname{Sym}_mK).
\end{equation}
For $x\in\cC$ and $y\in\cE$, define the continuous linear functional
\[
  \lambda_{x,y}(\kappa)
  :=\ip{\Theta_{\cC,\cE}(\kappa)x}{y}_{\cE},
  \qquad \kappa\in\conj{\cC}\otimes\cE,
\]
and the scalar coefficient kernel
\begin{equation*}
  K_{x,y}:=(\Id\otimes\lambda_{x,y})K
  \in F_\C^{\otimes m}.
\end{equation*}
In the coordinates \eqref{eq:ordered-kernel-coordinates},
\[
  K_{x,y}
  =\sum_{i_1,\ldots,i_m=1}^N
    \ip{K_{i_1\cdots i_m}x}{y}_{\cE}
    h_{i_1}\otimes\cdots\otimes h_{i_m}.
\]
Then
\begin{equation}

  \ip{I_m(K)x}{y}_{\cE}
  =I_m^{\mathrm{scal}}(K_{x,y};W).
\end{equation}
If $L$ is an operator-valued kernel of order $n$, supported in the same
finite-dimensional subspace $F$ and with the same input and output spaces,
then, for $u\in\cC$ and $v\in\cE$,
\begin{equation}

\E\Bigl[
  \ip{I_m(K)x}{y}_{\cE}
  \overline{\ip{I_n(L)u}{v}_{\cE}}
\Bigr]
=
\begin{cases}
  m!\,\ip{\operatorname{Sym}_mK_{x,y}}
           {\operatorname{Sym}_mL_{u,v}}_{F_\C^{\otimes m}},
       & m=n,\\[2mm]
  0, & m\ne n.
\end{cases}
\end{equation}
Finally,
\begin{equation}

  \|I_m(K)\|_{L^2(\Omega;\Sch_2)}^2
  =m!\,\|\operatorname{Sym}_mK\|_{
     F_\C^{\otimes m}\otimes\conj{\cC}\otimes\cE}^2.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:32:38.632740+00:00","domain":"probability theory","id":"claim_0c1ab265b0c196374f16e4db94e3019ef5f98dc847ddd37fec66941794c03039","kind":"concept","schema_version":1,"statement":"[Theorem 1 (Eichelsbacher and L\"{o}we \cite{eichelsbacher2010stein}) of arXiv:2506.17061, 'Non-uniform bounds for non-normal approximation via Stein's method with applications to th'] Let $k$ be a positive integer and let $Y_k$ be a random variable distributed according to $p_k$ as given in \eqref{b1}. 
