\end{equation}
where $\alpha_2(k) = n_2(k)/E_k$ is the slow-mode energy fraction defined in (equation eq:alpha-def of the paper).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:32:18.850537+00:00","domain":"probability theory","id":"claim_0c3589d56a55a76602cee8a02313fe5c108b2599e5b58a6bcfe0039248e17171","kind":"theorem","schema_version":1,"statement":"[Thm 16 of arXiv:2609.03869, '\bf Sharp asymptotics for a transport model with a nonlocal condition of the Fisher-KPP ty'] Let $u$ be the solution of the linear transport problem \eqref{moving frame-u} in $\R_+\times[0,i_\dagger)\times\R$ with initial datum $u_0$ defined in $[0,i_\dagger)\times\R$ and satisfying the hypothesis of Theorem~\ref{thm_Dirichlet heat eqn}. 
		Then, for $\kappa_1,\kappa_2>0$ satisfying\footnote{This is possible by choosing  $0<\kappa_2<\frac{a_*}{8c_*^2\delta_* \widehat{\K_*}(0)}$.} $0<4c_*\kappa_2<\kappa_1<\sqrt{2\kappa_2 a_*/\big(\delta_*\widehat{\K_*}(0)\big)}$,  with $\delta_*$ given in \eqref{dr_2} and  $a_*=\int_\R  z\K_*(z)\md z$,  there exist $t^*>i_\dagger$ sufficiently large $($depending on $\kappa_1$$)$, and $\kappa_3\ge 1+\frac{4}{\kappa_1}$  such that the function $t^{-2}U(t,i,x)$ defined for $t\ge i+t^*$, $i\in[0,i_\dagger)$ and $x\ge X(t,i)-R:= c_*(t-i)-\frac{\kappa_2}{\kappa_1}\frac{c_*i}{\sqrt{t}}+
		\kappa_3\sqrt{t}-R$, with 
			\begin{equation}
			U(t,i,x):= e^{
				-\kappa_1\big(
				\frac{
					x-c_*(t-i)+
					\frac{\kappa_2}{\kappa_1} \frac{c_*i}{\sqrt{t}}
				}{\sqrt{t}}-\kappa_3\big)
			},
		\end{equation} 
		 is a supersolution of \eqref{moving frame-u} for $t\ge i+i_\dagger+t^*$, $i\in[0,i_\dagger)$ and $x\ge X(t,i)$, in the sense of Definition \ref{Def_super+sub}. Moreover, let $\varsigma\in(0,\frac{1}{2})$ be given in Theorem \ref{thm_Dirichlet heat eqn}, then for any fixed $0<\epsilon<\varsigma$, there exists $M>1$ such that
		\begin{equation*}
			|	u(t-t^*,i,x)|\le M t^{-2} U(t,i,x)
		\end{equation*}
		for $t\ge i+i_\dagger+ t^*$, $i\in[0,i_\dagger)$ and $x\ge X(t,i)+t^{\frac{1}{2}+\epsilon}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:22:21.884115+00:00","domain":"probability theory","id":"claim_0c3dab8c9ef6c6a13b98a84d0b5455c9ddf2e515bc7a28bf9ed37f2a971910b4","kind":"theorem","schema_version":1,"statement":"[Proposition prop:split Fox of arXiv:2411.11345, 'Real Gaussian exponential sums via a real moment map'] For all $x\in M$, the space $\mathscr{F}_x\subset \mathscr{F}\subset \mathscr{F}_0$ is a subspace of $(\mathscr{F}_0)_x\subset \mathscr{F}_0$ and we have the orthogonal splitting 
  \begin{equation}
    (\mathscr{F}_0)_x=\mathscr{F}_x\oplus \mathbb{R} \varphi_x
  \end{equation}
  where $\varphi_x\in \mathscr{F}_0$ is the function given for all $y\in M$ by 
  \begin{equation}
    \varphi_x(y):=f_0(x)\, \mathrm{K}(x,y)-\mathrm{K}(x) f_0(y).
  \end{equation}
  Moreover, we have $\|\varphi_x\|=\sqrt{\mathrm{K}(x)\mathrm{K}_0(x)}.$","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:31:14.337061+00:00","domain":"probability theory","id":"claim_0c43d845078a4dbfc09ed8fc2775a3178d531214182d2fe87da60271bc9a3e07","kind":"theorem","schema_version":1,"statement":"[Prop prop2 of arXiv:2606.17792, 'The Loss of Tension in an Infinite Membrane with Holes of Decaying Spatial Density'] Suppose
