	\mathopen{}\mathclose\bgroup\originalleft( 
	e^{-c \mathopen{}\mathclose\bgroup\originalleft\lvert\xi\aftergroup\egroup\originalright\rvert^{(2+\alpha)/2}}
	+ e^{-c \varrho \varepsilon_1 (1+\mathopen{}\mathclose\bgroup\originalleft\lvert\xi\aftergroup\egroup\originalright\rvert^{\alpha})}
	\aftergroup\egroup\originalright) 
