    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:35:10.780837+00:00","domain":"probability theory","id":"claim_0da799cd4f7248657d8b9c53ae78c3bd9d702b83e74fda3156631893e3744df6","kind":"lemma","schema_version":1,"statement":"[Lem 6 of arXiv:2603.29549, 'Multitype PCR branching processes'] The function $\bar F$, defined in \eqref{barF}, is $b_1$-Lipschitz with respect to the $\ell_1$-norm, and it
satisfies  
\begin{equation}
\big|F_i(\bar x)-F_i(\bar y)\big| \le b_i |x_i-y_i| +   x_i \|\bar x-\bar y\|, \quad \bar x,\bar y\in \Real_+^d,\quad i=1,\ldots,d.
\end{equation}
The $n$-th iterate of $\bar F$ admits the bound 
\begin{equation}

F^{(n)}_i (\bar x) \le b_i^n x_i, \quad \bar x\in \Real_+^d,\quad i=1,\ldots,d.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:43:53.615989+00:00","domain":"probability theory","id":"claim_0da8417bde9cafd0004bb7e8a50c195954857bc06c9fab3b14aa4db6ba32f94a","kind":"concept","schema_version":1,"statement":"[Corollary energy-ineq-Z of arXiv:2512.13200, 'Martingales on a Euclidean manifold with a boundary and reflected BSDEs in non-convex doma'] {Under Assumption (ass:brownian-case of the paper),} for any solution $(Y,Z,K)$ of the reflected BSDE (equation eq reflected bsde of the paper), the process $\int_ 0^. Z_s \mathrm{d} W_s$ is a BMO martingale. In particular, we have
    \begin{equation}

    \left| \sup_{t \in [0,T]}\mathbb{E}_t \left[ \left(\int_t^T |Z_s|^2\mathrm{d} s \right)^{n}\right]\right|_{\infty}\leqslant n! \|Z\|_{\ensuremath{\mathscr{B}^{2}}}^{2n},\quad  \forall n \in \mathbb{N}.
    \end{equation}
    and
    \begin{equation}

    \left| \sup_{t \in [0,T]}\mathbb{E}_t \left[ e^{\lambda \int_t^T |f(s,Y_s,Z_s)| +|Z_s|\mathrm{d} s}\right]\right|_{\infty}<+\infty, \quad \forall \lambda>0.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:31:45.417836+00:00","domain":"probability theory","id":"claim_0da9310cae776128009ee34cbb7f08682ac48b5f5f00d32ac60ef2e710814d8d","kind":"theorem","schema_version":1,"statement":"[Theorem thm:Kahane of arXiv:2412.06615, 'A family of log-correlated Gaussian processes'] For each $\alpha\in(0,2], \delta,\delta'>0$, $\{G_{\alpha,\beta}(f)\}_{f\in {\mathcal F}_{\delta,\delta',\beta}({\mathsf M})}$ is a family of symmetric $\alpha$-stable random variables with
\begin{equation}
{\mathbb E} \exp\pp{{\rm i} G_{\alpha,\beta}(f)} = \exp\pp{-2\int_0^\infty{\mathbb E}'_{\beta,r}\abs{\int_{\mathsf M}\pp{\inddd{m(A_x){\rm~is~odd}} - \wt p_{\beta,r}(x)}f(x)\lambda({\rm d} x)}^\alpha\frac{{\rm d} r}r}.
\end{equation}
In particular, when $\alpha=2$, this is a family of centered Gaussian random variables with
\begin{equation}
{\rm{Cov}}(G_{2,\beta}(f),G_{2,\beta}(g)) =\int_{\mathsf M}\int_{\mathsf M} f(x)g(y)\Gamma\topp\beta(x,y)\lambda({\rm d} x)\lambda({\rm d} y), 
\end{equation}
for all $f,g\in {\mathcal F}_{\delta,\delta',\beta}({\mathsf M})$, where
\begin{equation}
\Gamma\topp\beta(x,y) = \log \frac{\mu^\beta(A_x)+\mu^\beta(A_y)}{{\mathsf d}^\beta(x,y)} = 4\int_0^\infty \frac{\Gamma_r\topp\beta(x,y)}r{\rm d} r,
\end{equation}
with
\begin{multline}
\Gamma_r\topp\beta(x,y)\\ := {\mathbb E}'_{\beta,r}\pp{\pp{\inddd{m(A_x){\rm~is~odd}} - \mathbb P_{\beta,r}'\pp{m(A_x){\rm~is~odd})}}\pp{\inddd{m(A_y){\rm~is~odd}} - \mathbb P_{\beta,r}'\pp{m(A_y){\rm~is~odd}}}}.
\end{multline}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:43:04.566292+00:00","domain":"probability theory","id":"claim_0daa12b61eea380a94de0d3fcc4174261f4f0895424a23b7f8021a93bdf23c04","kind":"concept","schema_version":1,"statement":"[Theorem 7 of arXiv:2605.16868, '\ttl'] Under the same assumptions in Theorem \ref{thm-main}, we have
