\le \exp\Big(-\frac{c k_i}{(\log n)^{2\alpha}}\Big).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:38:36.887068+00:00","domain":"probability theory","id":"claim_0db898f7599e69f780e0e506c02ff4138a47fefe4b1c974c66f786ce6acf361b","kind":"theorem","schema_version":1,"statement":"[Theorem thm:pure-input of arXiv:2606.29557, 'Propagation of chaos for Belavkin equations beyond pure states'] Let Hypothesis~(hyp:perfect-efficiency-tensorization-purity of the paper) (1) hold.  
For $j\in[N]$, set
\begin{equation}
\rho_t^{N:(j)}
  :=
  \mathrm{Tr}_{[N]\setminus\{j\}}(\rho_t^N) \qquad \mbox{ and } \qquad  \alpha_{N,j}(t)
  :=
  1-\mathrm{Tr}\bigl(\rho_t^{N:(j)}\gamma_t^j\bigr).

\end{equation}
Then, for every $T>0$, there exists a constant $C_T<\infty$, independent
of $N$ and $j$, such that
\begin{equation}
  \sup_{0\le t\le T}
  \mathbb E\bigl[\alpha_{N,j}(t)\bigr]
  \le
  \frac{C_T}{\sqrt N}.

\end{equation}
Consequently, for every fixed $n\ge1$,
\begin{equation}
  \sup_{0\le t\le T}
  \mathbb E\left[
    \left\|
      \rho_t^{N:n}-\Gamma_t^n
    \right\|_1
  \right]
  \le
  2\sqrt{nC_T}\,N^{-1/4}.

\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:47:22.241168+00:00","domain":"probability theory","id":"claim_0db93652ffbcc2a8100ffece251520e42aeae7efed61f2124c2902918924b43f","kind":"theorem","schema_version":1,"statement":"[Theorem 21 of arXiv:2605.25715, '2605.25715'] {\cite[Corollary 4.4.7]{HJ91}}  
Let $A \in M_{d}(\mathbb{R})$ be symmetric and positive definite. Let $G \in M_d(\mathbb{R})$ and $\sigma(G) = \{ \lambda_1, \dots, \lambda_d \} \subset \mathbb{C}$ be the set of eigenvalues of $G$ counting multiplicities.  Assume that
\begin{equation} 
    \lambda_i + \lambda_j \neq 0 \quad \text{for all } 1 \leq i, j \leq d.
\end{equation}
Then there exists a unique solution $P$ satisfying the Lyapunov equation:
\begin{equation} 
    GP + PG^T = -2A.
\end{equation}
In particular, $P$ is given explicitly by:
\begin{equation} 
\text{\rm Vec}(P) = - (I \otimes G + G \otimes I)^{-1} \text{\rm Vec}(2A).
\end{equation}
where   $\text{Vec}$ and $\otimes$ are defined as in Definitions \ref{vectorizdefn}, \ref{tensorproducde}, respectively.
Moreover, $P$ is symmetric and invertible.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:07:15.775746+00:00","domain":"probability theory","id":"claim_0db9c6b92644f17988614d7198d6d3c24b5b47c90a8362183274845b77a9f903","kind":"concept","schema_version":1,"statement":"[Lemma lem:correlation_stopping of arXiv:2608.05089, 'Correlation decay in area-tilted line ensembles'] There is some $\lambda_0 > 1$ and $C, c > 0$ such that for all $\lambda \geqslant \lambda_0$
and all $k \in \mathbb{N}$, when $\mathbf{X}$ and $\mathbf{Y}$ are sampled independently we have
\begin{equation}
    \tau_\ell^{0,k} < 0 < \tau_r^{0,k}
    \qquad \text{and} \qquad
    \tau_\ell^{t,k} < t < \tau_r^{t,k}
\end{equation}
with probability at least $1 - C e^{-ct}$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:48:02.410644+00:00","domain":"probability theory","id":"claim_0dbb17ccfc118242e9889ca45671e86e3cf5eda9186c2a1361d1d04e77df989b","kind":"definition","schema_version":1,"statement":"[Definition def:admissible of arXiv:2608.26564, 'Real ideal points, Conway spheres, and left-orderable Dehn fillings'] An \emph{admissible real limiting datum} is a limiting gluing datum $\xi = (\chi_1, \chi_2)$ represented by irreducible homomorphisms $\rho_i: \pi_1(T_i) \to SL_2(\mathbb{R})$ such that, in the same-oriented strand variables,
\begin{equation}
	\rho_i(m_{i, 1}) = \rho_i(m_{i, 2}) = I \ \ \ \ \ \rho_i(m_{i, 3}) = \rho_i(m_{i, 4}) = P_i
\end{equation}
where $P_i$ is a noncentral parabolic of trace 2. Equivalently, in boundary variables, 
\begin{equation} \begin{array}{c|cccc} &\mu_{i,1}&\mu_{i,2}&\mu_{i,3}&\mu_{i,4}\\ \hline T_1&I&I&P_1^{-1}&P_1\\ T_2&I&I&P_2&P_2^{-1}. \end{array} \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:52:57.735642+00:00","domain":"probability theory","id":"claim_0dbbfc7df446caa0099e82e1d0e4e05106570c9fa54d87e0ae1a95dce24ed241","kind":"lemma","schema_version":1,"statement":"[Lemma 27 of arXiv:2609.02755, 'The Sharp Rate of Probabilistically Strong Convergence to the KPZ Equation'] We have the cointeraction property 
	\begin{align*}
		(\Delta_r^- \otimes \operatorname{id})\Delta^\partial = (\operatorname{id} \otimes \Delta^\partial) \Delta_r^-.
	\end{align*}
	for the operations on $\mcT$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:32:28.952442+00:00","domain":"probability theory","id":"claim_0dbc11a978aef94ed586e0607bdb5dccb58549e53461a41ac1d868ff8211bfd0","kind":"theorem","schema_version":1,"statement":"[Proposition prop:shearM of arXiv:2608.16915, 'Exact mean--covariance dynamics of the Weber field in the stochastic Lagrangian representa'] For $f_0\in L^2(\mathbb{T}^2)$ with zero mean, the field
\[
  u(t,x)=\bigl(e^{\nu t\Delta_\perp}f_0(x_2,x_3),\,0,\,0\bigr)
\]
is a global smooth solution of (equation eq:NS of the paper) for $t>0$, since $(u\cdot\nabla)u=0$. Its
mean displacement and mean deformation are
\begin{equation}
  \ell(t)=-t\,u(t),\qquad
  M(t)=I-t\,e_1\otimes\nabla_\perp e^{\nu t\Delta_\perp}f_0 ,
\end{equation}
and for every $0<\alpha<1$ and $\tau>0$,
\begin{equation}
  \sup_{t\ge\tau}\left\lVert M(t)-I\right\rVert_{C^\alpha}
  \le C_\alpha\,\nu^{-1-\alpha/2}\,\tau^{-\alpha/2}\,\left\lVert f_0\right\rVert_{L^2(\mathbb{T}^2)} .
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:43:18.739323+00:00","domain":"probability theory","id":"claim_0dbc73420c75dd3dfe5fdc5be8d321cccf5c9be672fe76080f592ce3972f77e7","kind":"definition","schema_version":1,"statement":"[Defi of arXiv:2609.02346, 'Regularised double shuffle relations for planar \AZVs{}'] Let $f_1,f_2,f_3:\mathcal{PT}_{\N^*}\longrightarrow\mathcal{PT}_{\N^*}$ be three linear maps defined by induction with
     \begin{equation*}
