         \end{cases}
     \end{gather*}
     We extend $f_i$ by linearity to a map of $\mathcal{PT}_{\N^*}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:37:51.456477+00:00","domain":"probability theory","id":"claim_0dbc850329121ca4c463b5ed5f1d8d355989e81aa3423cdaefcc0b1c156e4fdb","kind":"concept","schema_version":1,"statement":"[Lem 17 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] For every $n \in \mathbb{N}_+$, it holds 
\begin{align} 
 \sup_{r \in [0,T]} \Bigg\{ \frac{1}{n} \sum_{x} \big[  \Theta(n) ( \mathbb{L}_n^{\gamma,s} H )( \tfrac{x + q_n^r }{n}  ) \big]^{2}  \Bigg\} \leq C(\gamma,H).
\end{align}
Moreover, if $H \in C_c^{2}(\mathbb{R})$, then the role of $C(\gamma,H)$ above is fulfilled by some constant $C(H)$ satisfying \eqref{Cinvshift}. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T16:57:16.040615+00:00","domain":"probability theory","id":"claim_0dbf5a6ebae98c58edf3fc65e6d12f0ec3134484fbea3675b106f65f87caecc6","kind":"concept","schema_version":1,"statement":"[Proposition prop:integrationformula of arXiv:2506.02611, '\textbf{The tight length spectrum of large-genus random hyperbolic surfaces with many cusp'] Mirzakhani's integration formula generalizes to an integration formula on the moduli space of tight hyperbolic surfaces given by 
    \begin{align*}
        \int_{\mathcal{M}_{g,n,p}^{\mathrm{tight}}(\mathbf{L},\mathbf{K})} F^\Gamma_{\mathrm{tight}}(X) \mathrm{d}\mu_{g,n+p}^{\mathrm{WP}}(X) = C_{\Gamma}\int_{\mathbb{R}_+^k} x_1\cdots x_k f(\mathbf{x}) T_{g,n,p}(\mathbf{L},\mathbf{K},\Gamma,\mathbf{x}) \mathrm{d}x_1\cdots \mathrm{d}x_k,
    \end{align*}
    where $T_{g,n,p}(\mathbf{L},\mathbf{K},\Gamma,\mathbf{x})$ is defined with reference to the decomposition $\Sigma_{g,n} \setminus \Gamma = \bigsqcup_{i=1}^q \Sigma_{g_i,n_i+k_i}$ as 
    \begin{align*}
        T_{g,n,p}(\mathbf{L},\mathbf{K},\Gamma,\mathbf{x}) = \sum_{I_1\sqcup \cdots\sqcup I_q = \{1,\ldots,p\}} \prod_{i=1}^q T_{g_i,n_i+k_i,|I_i|}(\mathbf{L}^{(i)},\mathbf{x}^{(i)},\mathbf{K}_{I_i}).
    \end{align*}
    The constant $C_{\Gamma}$ only depends on $\Gamma$. We have $C_{\Gamma} \le 1$ and if $\Sigma_{g,n}\backslash \Gamma$ is connected, then $C_{\Gamma} = 2^{-k}$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:49:17.500920+00:00","domain":"probability theory","id":"claim_0dc0213ca639baf8d7753b25a02d1b19ef5158772acc34cfe386a98b6fd1ace3","kind":"concept","schema_version":1,"statement":"[Lemma 8 of arXiv:2605.30030, 'Critical exponents for planar random-cluster model with cluster-weight~$q=4$'] There exist constants~$C,c>0$ such that for every~$R/2 \ge r  \ge \ep \ge \delta>0$, every event~$A$ depending on~$\Lambda_r^\delta$ and every boundary condition~$\xi$ on~$\Lambda_R^\delta$, 
\begin{equation*}
\big| \phi_{\Lambda_R^\delta}^\xi[A\,|\,\calL_{\{0\},\eps}^{\rm odd}=\emptyset] - \phi_\delta[A\,|\,\calL_{\{0\},\eps}^{\rm odd}=\emptyset] \big|\le C\big(\tfrac{r}{R}\big)^c.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

