{"assumptions":[],"created_at":"2026-10-26T20:54:10.974066+00:00","domain":"probability theory","id":"claim_0e8a342ba3691818526845b3f34e3e4eb23e9cd241d39b2a1ca6113d73216d2d","kind":"concept","schema_version":1,"statement":"[Theorem 1 of arXiv:2606.13648, 'Stochastic dominations for FK percolation and sharp thinning thresholds for the Ising ener'] Let $q\ge 1$ and let $p, \tilde{p} \in [0,1]^E$ be parameters such that $p \leq \tilde{p}$ pointwise. We have the following stochastic domination:
	\begin{align}
		& \fk_{p,q} \domi \fk_{\tilde{p},q} \cap \ber{p/\tilde{p}}, \qquad\qquad\qquad \text{\emph{(upwards-movability)}}
	\end{align}
	where, for two percolation measures $\mu$ and $\nu$, $\mu\cap\nu$ denotes the law of $\omega\cap\omega'$ for independent configurations $\omega\sim\mu$ and $\omega'\sim\nu$. The ratio $p/\tilde{p}$ is understood edgewise.

	More generally, for any real numbers $q, \tilde{q} \ge 1$ and parameters $p, \tilde{p} \in [0,1]^E$, we have
	\begin{align}
		 \fk_{p\tilde{p}, q\tilde{q}} &\domi \fk_{p,q} \cap \fk_{\tilde{p}, \tilde{q}}, \qquad \text{and}\\
		  \fk_{\widehat{p}, q\tilde{q}} &\succcurlyeq \fk_{p,q} \cup \fk_{\tilde{p}, \tilde{q}},
	\end{align}
	where
	\begin{align}
		\widehat{p}:=(p^*\tilde{p}^*)^* = \frac{p\tilde p+p\tilde{q}(1-\tilde{p})+\tilde{p}q(1-p)}{(1-p)(1-\tilde{p})+p\tilde p+p\tilde{q}(1-\tilde{p})+\tilde{p}q(1-p)}.
	\end{align}
	(The reason for the notation $(p^*\tilde{p}^*)^*$ will be made clear in Remark \ref{rk. union equivalent intersection}.) (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:46:36.165305+00:00","domain":"probability theory","id":"claim_0e8b6dd69e38497fa8f64d900f072f81ee5b3b242f1ea5b1e38925803051b616","kind":"theorem","schema_version":1,"statement":"[Prop Prop_TwistedUniversalRamifiedEuclideanLineBundle of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] {Doan2024}}]

  $\mathbf{Ram}$ carries a \defined{twisted universal ramified Euclidean line bundle} in the following sense:
  \begin{enumerate}
  \item

    Consider the \defined{universal non-branching locus}
    \begin{equation*}
      \mathring{\mathbf{X}}
      \coloneq
      \set[\big]{
        ([{\mathfrak l}],x) \in \mathbf{Ram} \times X : x \notin \mathrm{Br}({\mathfrak l})
      }
      \subseteq
      \mathbf{Ram}\times X.
    \end{equation*}
    The projection map ${p} \mskip0.5mu\colon\thinspace \mathring{\mathbf{X}} \to \mathbf{Ram}$ is a fibre bundle.
  \item

    Denote by ${\mathfrak U}$ the set of those open subsets $\mathscr{U} \subseteq \mathbf{Ram}$ for which ${p} \mskip0.5mu\colon\thinspace \mathring{\mathbf{X}}|_\mathscr{U} \to \mathscr{U}$ is trivial.

    For every $\mathscr{U} \in {\mathfrak U}$ there is a Euclidean line bundle ${\mathfrak L}_\mathscr{U}$ over $\mathring{\mathbf{X}}|_\mathscr{U}$ and for every $[{\mathfrak l}] \in \mathscr{U}$ an isomorphism
    \begin{equation*}
      {\mathfrak L}_\mathscr{U}|_{[{\mathfrak l}] \times \paren{X{\backslash} \mathrm{Br}({\mathfrak l})}} \cong {\mathfrak l}
    \end{equation*}
    unique up to $\Aut({\mathfrak l}) = \set{\pm 1}$.
  \item

    There is a Čech $2$--cocycle $\lambda \in \check{\rm C}^2({\mathfrak U},\underline{\set{\pm 1}})$
    together with, for every $\mathscr{U},\mathscr{V} \in {\mathfrak U}$, an isomorphism
    $\phi_\mathscr{V}^\mathscr{U} \mskip0.5mu\colon\thinspace {\mathfrak L}_\mathscr{U}|_{\mathring{\mathbf{X}}|_{\mathscr{U}\cap \mathscr{V}}} \cong {\mathfrak L}_\mathscr{V}|_{\mathring{\mathbf{X}}|_{\mathscr{U}\cap \mathscr{V}}}$
    such that for every $\mathscr{U},\mathscr{V},\mathscr{W} \in {\mathfrak U}$
    \begin{equation*}
      {p}^*\lambda_{\mathscr{U}\mathscr{V}\mathscr{W}} \coloneq \phi_\mathscr{U}^\mathscr{W} \phi_\mathscr{W}^\mathscr{V} \phi_\mathscr{V}^\mathscr{U}
      \in \check{\rm C}^0\paren[\big]{\mathring{\mathbf{X}}|_{\mathscr{U} \cap \mathscr{V} \cap \mathscr{W}},\set{\pm 1}}.
    \end{equation*}
    Here $\underline{\set{\pm 1}}$ is the constant sheaf associated with the abelian group $\set{\pm 1}$.
  \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:26:17.758038+00:00","domain":"probability theory","id":"claim_0e8b944120a1f276b15629ce80caa45ca046445f4ed3fc69b75c4dd7c8b8b45e","kind":"concept","schema_version":1,"statement":"[Lemma 10 of arXiv:2511.05386, 'CLT for $\beta$-ensembles with Freud weights, application to the KLS conjecture in Schatte'] Let $p>2$.
