\end{cases}
\]","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:40:21.311842+00:00","domain":"probability theory","id":"claim_0eb35b9e170f994c258d4918d4e239caafae67c345234396cf30ce17261412b4","kind":"lemma","schema_version":1,"statement":"[Lemma 20 of arXiv:2604.08127, 'Asymptotics of Brownian occupation measures \\ with unusually large intersections'] Let $W_t$ be a Brownian motion in $\mathbb{R}^d$ and $0 = t_0 < t_1 < \dots < t_m$. Then, for any $0 \le \theta \le d$ and $0 = x_0, x_1 , \dots , x_m \in \mathbb{R}^d$,
    \begin{equation}

        \mathbb{E} \left[ \prod_{i=1}^m \delta(W (t_i) - x_i) \right] \le C^m \prod_{i=1}^m |t_i - t_{i-1}|^{-(d-\theta)/2} \prod_{i=1}^m |x_i - x_{i-1}|^{-\theta}.
    \end{equation}
    Similarly, if $k < d$ and $0 \le \theta \le k/2$,
    \begin{equation}

        \mathbb{E} \prod_{i=1}^m |W (t_i) - x_i|^{-k} \le C^m \prod_{i=1}^m |t_i - t_{i-1}|^{-(k-\theta)/2} \prod_{i=1}^m |x_i - x_{i-1}|^{-\theta}.
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:27:08.850597+00:00","domain":"probability theory","id":"claim_0eb3d6f41efde78de9481041bc5f768e5539510a213d6f9d1dbd203238538b9f","kind":"concept","schema_version":1,"statement":"[Lemma 32 of arXiv:2511.10814, '\Large \bf \boldmath\ \\ Convergence of the extended Kalman filter with small and state-de'] (Properties of symmetric and positive semi-definite matrices)
Let $A, B \in \mathcal{M}_{d}(\mathbb{R})$, $d \in \mathbb{N}$, symmetric and positive semi-definite matrices.
	Then it holds

\begin{enumerate}

\item 														
\begin{equation}
\lambda_{min}(A) \trace(B) \leq \trace(AB)  \leq  \lambda_{max}(A) \trace(B)
\end{equation}
where $\lambda_{min}(A)$  and $\lambda_{max}(A)$ denote the smallest and largest eigenvalue
	of A, respectively.

	\item  \begin{equation} 
	\dfrac{\trace(B)}{ \trace\left( A^{-1} \right)} \leq   \trace(AB) \leq \trace(A)  \trace (B) 
						\end{equation}														
where for the first inequality A is assumed to be positive definite.

\item \begin{equation}
	\trace^2(A)  \geq \trace\left( A^2 \right) \geq  \dfrac{1}{d} \trace^2 (A)
\end{equation}

\item  \begin{equation}				\vert A\vert_F = \sqrt{\trace\left( A^2 \right)}  \leq \trace(A)
						\end{equation}
			where $\vert A\vert_F$  denotes the Frobenius norm of A.
					\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:57:07.301035+00:00","domain":"probability theory","id":"claim_0eb53efe453e57b2beaaa548dc3e0cf66e49cdd8639cdffb44d600f10a83b8be","kind":"theorem","schema_version":1,"statement":"[Proposition 17 of arXiv:2606.23433, 'Emergence of Common Noise: Quantitative Conditional Propagation of Chaos'] Let $X=(X^{1},\ldots ,X^{N})\in L_{s}^{2}({\mathbb{R}}
