{"assumptions":[],"created_at":"2026-10-27T17:18:19.443695+00:00","domain":"probability theory","id":"claim_0ec9cc1babb4a7234e3c322d0312e14c687967b08661baacd83078b77bb7cfe7","kind":"definition","schema_version":1,"statement":"[Definition def:wishart of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] Let \(M\le N\) and  $\alpha = {M}/{N}$ where $M$ may depend on $N$, define   
\begin{equation} 
H_N \;=\; \Sigma_N \circ W_N,
\end{equation} as an inhomogeneous Wishart  matrix  and the corresponding additive perturbation (namely, signal-plus-noise matrices)   \begin{equation}
X_N \;=\; (H_N + A_N)\,(H_N + A_N)^*.
\end{equation}
where \(W_N=(W_{ij})\) is an \(M\times N\) random matrix with real or complex   entries  and \(\Sigma_N=(\sigma_{ij})\) is a deterministic  \(M\times N\)  matrix  with nonnegative entries. 
Precisely, the following assumptions hold:

\begin{enumerate}[leftmargin=*,label=(C\arabic*)]
  \item \textbf{(Entry moment)}  
 The entries $\{W_{ij}\}_{i,j=1}^N$ are independent, symmetric, and satisfy
 \begin{equation}
      \begin{cases}
       \mathbb{E}[W_{ij}^2]=1, & \text{real 
        case},\\
        \mathbb{E}[|W_{ij}|^2]=1,\;\mathbb{E}[W_{ij}^2]=0, & \text{complex 
        case}.
      \end{cases}
    \end{equation} 
    and for some \(\theta\ge1\) and all integers \(k\ge2\),
    \begin{equation}
      \mathbb{E}[|W_{ij}|^{2k}]
      \;\le\;
      \theta^{\,k-1}(2k-1)!!,
    \end{equation}
  where   \(\theta=\theta_N\to\infty\)  may be allowed  if needed.

  \item \textbf{(Variance profile)}  
    The profile matrix \(\Sigma_N=(\sigma_{ij})\) satisfies
    \begin{equation}
      \sum_{j=1}^N \sigma_{ij}^2 = 1
      \quad(\forall\,i\in[M]),
      \qquad
      \sum_{i=1}^M \sigma_{ij}^2 = \alpha
      \quad(\forall\,j\in[N]).
    \end{equation}
    Equivalently, the bipartite transition matrix on \(S=[M]\sqcup[N]\) is
    \begin{equation}
      P_{S}
      = \begin{pmatrix}
          0 & (\sigma_{ij}^2)_{M\times N} \\
          \alpha^{-1}(\sigma_{ij}^2)_{N\times M}^T & 0
        \end{pmatrix}.
    \end{equation}

  \item \textbf{(Rank-\(r\) perturbation)}  
    The deterministic matrix \(A_N\) admits a decomposition
\begin{equation}
    A_N = Q_1\,\Lambda\,Q_2^*, 
    \quad 
    \Lambda = \big( \mathrm{diag}(a_1,\dots,a_r, \underbrace{0,\dots,0}_{M-r}), \; 0_{M \times (N-M)} \big),
\end{equation}
where \(Q_1\) and \(Q_2\) are orthogonal (or unitary) matrices of size \(M\) and \(N\), respectively, and \(\underbrace{0,\dots,0}_{M-r}\) denotes the \(M-r\) zeros in the diagonal block.
     Moreover, for some fixed $\tau>0$, 
    \begin{equation}
      \|A_N\|_{\mathrm{op}}
      \;\le\;
      \sqrt{\alpha} \;+\;\tau\,N^{-1/3}.
    \end{equation}
\end{enumerate}
When  \(W_N\) has i.i.d.\ Gaussian entries,   the resulting model is denoted  by \(\widetilde X_N\) with \(\beta=1,2\).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:51:00.240483+00:00","domain":"probability theory","id":"claim_0eca8db8f0b718ac3488d4585a0e694429a477da4a8631dd1915eb68a5d619f3","kind":"theorem","schema_version":1,"statement":"[Proposition eq:diamond_simplified of arXiv:2604.22528, 'Malliavin calculus for signatures with applications to finance'] If ${\color{NavyBlue}{\mathbf{i}}}, {\color{NavyBlue}{\mathbf{k}}} \in A$ and $\bm{\ell}, \bm{\ell}' \in \TA[d+1]$, then the diamond product $\diamond^{{\color{NavyBlue}{\mathbf{i}}}, {\color{NavyBlue}{\mathbf{i}}}}_{{\color{NavyBlue}{\mathbf{k}}}}$ can be written in carré du champ form:
