{"assumptions":[],"created_at":"2026-10-28T00:32:56.081665+00:00","domain":"probability theory","id":"claim_0ef6061cf8b04b5ff4acadbed428026b20635307a76527a63f60c73cd60ff25d","kind":"theorem","schema_version":1,"statement":"[Proposition PropMartingaleProperty of arXiv:2411.12522, 'Canonical insurance models: stochastic equations and comparison theorems'] Let $Y$ be a jointly measurable and $\mathcal{F}^-$-adapted process such that 
	\begin{align*}
		\mathbb{E}_{s}^i\bigg[\int_{(s,t]} |Y(u)|  I^j(u-) \Lambda^{jk} (\mathrm{d} u)\bigg] < \infty.
	\end{align*}
	Then we have
	\begin{align*}
		\mathbb{E}_{s}^i\bigg[\int_{(s,t]} Y(u) N^{jk} (\mathrm{d} u)\bigg]=\mathbb{E}^i_{s}\bigg[ \int_{(s,t ]} Y(u) I^j(u-) \Lambda^{jk} (\mathrm{d} u)\bigg]
	\end{align*}
	for $0 \leq s < t < \infty$ and $ i,j,k \in \mathcal{Z}$ with $j \neq k$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:15:34.556650+00:00","domain":"probability theory","id":"claim_0ef78c6f077e058b1d956b900a4f49c58b8d6044a6ca5fa0216f1bff9c36290f","kind":"theorem","schema_version":1,"statement":"[Proposition 44 (curvature of the fiber block) of arXiv:2609.03332, 'Singularity Models of Finite-Time K\"ahler-Ricci Flows'] Let $X, Y \in \mathcal{H}_1$ be $g (t)$-unit with $Y$ orthogonal to $X$ and $J X$, and recall $J \nu = \xi^*$ up to sign. The sectional curvatures of $g (t)$ on planes tangent to $\mathcal{V}' = \mathbb{R} \nu \oplus \mathbb{R} \xi^* \oplus \mathcal{H}_1$ are
		\begin{equation}
		\begin{aligned}
			K ( \nu, \xi^* ) \;&=\; - \frac{( h^2 )''}{2} \,, \qquad & K ( \nu, X ) \;=\; K ( \xi^*, X ) \;&=\; \frac{1}{4 f_1^2} \left( \frac{h^2}{f_1^2} - ( h^2 )' \right) \,, \\
			K ( X, J X ) \;&=\; \frac{2}{f_1^2} - \frac{h^2}{f_1^4} \,, \qquad & K ( X, Y ) \;=\; K ( X, J Y ) \;&=\; \frac{1}{4 f_1^2} \left( 2 - \frac{h^2}{f_1^2} \right) \,.
		\end{aligned}
	\end{equation}
	Every bisectional curvature of a pair of $J$-invariant planes tangent to $\mathcal{V}'$ is a sum of two entries of \eqref{eq:fiber-curvature}, by the Kähler symmetry $\mathrm{Rm} ( u, J u, J v, v ) = \mathrm{Rm} ( u, v, v, u ) + \mathrm{Rm} ( u, J v, J v, u )$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:00:46.840593+00:00","domain":"probability theory","id":"claim_0ef7f6789993cc171a6f3f8d56b5ce8e518fe2f2c823195c3999a394f707c2a7","kind":"concept","schema_version":1,"statement":"[Lem 12 (Anti-concentration for $\sigma_{d,k}$) of arXiv:2608.13374, 'Nearly Sharp Comparison Results for sliced and max-sliced Wasserstein distances'] Let $1 \leq k < d$ and let $U \sim \sigma_{d,k}$. There exists a universal constant $C_0 > 0$ such that for any $v\in \R^d$ and $t > 0$,
		\begin{equation}
			\Psub{U \sim \sigma_{d,k}}{\norm{Uv} < t\sqrt{k/d}\,\norm{v}} \leq (C_0 t)^{k}.
		\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:52:57.737584+00:00","domain":"probability theory","id":"claim_0ef9267e2c8e636997b986e05d1eb167f87e6a1f5f671b70dae05793375a047e","kind":"definition","schema_version":1,"statement":"[Definition 35 of arXiv:2609.02755, 'The Sharp Rate of Probabilistically Strong Convergence to the KPZ Equation'] For $\zeta \in [0, \zeta_0)$ we write
	\begin{align*}
		E^\zeta_\vartheta = \{(Z, \boldsymbol{\psi}, \mcV) \in \cM_{\mathrm{adm}}(\tilde{\mfT}^\zeta) \times (C^{\vartheta - N\zeta})^3 \times \mathcal{D}^{3/2 + 2 \kappa - N\zeta, - \kappa - N\zeta} ({\tilde \mfT^\zeta_{\ge - 2\kappa}}) \},
	\end{align*}
	which we equip with the metric
	\begin{align*}
		d_{E^\zeta_\vartheta}&((Z, \boldsymbol{\psi}, \mcV), (\bar{Z}, \bar{\boldsymbol{\psi}}, \bar{\mcV})) \\
		&= \| Z; \bar{Z} \|^{(\zeta)}_{2+2\kappa; \mathcal{O}_T} + \| \boldsymbol{\psi} - \bar{\boldsymbol{\psi}} \|_{(C^{\vartheta - N\zeta})^3} + \| \mcV; \bar{\mcV} \|^{(\zeta)}_{3/2+2\kappa - N\zeta, -\kappa - N\zeta; \mathcal{O}_T}\;,
	\end{align*}
	with the dependence of this metric on the fixed terminal time $T$ suppressed.\\
	Furthermore, given $T > 0$, we define $E^\zeta_{\vartheta, T} \subset E^\zeta_\vartheta$ by
	$$E^\zeta_{\vartheta, T} = \{(Z, \boldsymbol{\psi}, \mcV) \in E^\zeta_\vartheta: \text{ there exists a unique solution to \eqref{eq: tct_sys} in } \mathcal{D}^{(\zeta)}_{T}(\vartheta; Z) \},$$
	where for $\zeta > 0$ all operations in \eqref{eq: tct_sys} are understood with respect to the grading $|\cdot|_\fs^{(\zeta)}$, with the truncation exponents lowered by $N\zeta$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:39:41.439444+00:00","domain":"probability theory","id":"claim_0efb0d4404f49b26e93a83a53b8f945d10b74a545a775550057703c56fff0742","kind":"theorem","schema_version":1,"statement":"[Prop 20 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] Let $0<\A{1},\A{2}\leq 1$ be such that $N^{-1}\ll  \pr{\A{1}\A{2}}^{1/2}$ and let $f\in S(m,\A{1},\A{2})$. Then,  
    \begin{equation*}
        \mathrm{tr}\pr{f_{N,\A{1},\A{2}}}=\pr{N\A{1}^{1/2}\A{2}^{1/2}}^d\int_{\mc{T}_{\A{1},\A{2}}}f(x,\xi)dxd\xi+r_N
    \end{equation*}
    where, for all $k\in \N$, 
    \begin{equation*}
        r_N=\mc{O}_k(1)N^{d-k}\A{1}^{(d-k)/2}\A{2}^{d/2}\sum_{\bb{\beta}+\bb{\gamma}\leq \max(2d+1,k)}\norme{\partial_x^\beta\partial_\xi^\gamma f}_{L^1(\mc{T}_{\A{1},\A{2}})}.
    \end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:58:28.467796+00:00","domain":"probability theory","id":"claim_0efb6076c80ff075258aea08736ce5a9f6ec193b8119923b06c70b62a2a77549","kind":"definition","schema_version":1,"statement":"[Definition 6 (Simultaneous Schatten-flattening completion) of arXiv:2606.29292, 'Intrinsic Gaussian Tensor Geometry and Random Operator Spectra'] For $2\le r<\infty$ and $S\subset[m]$ set
\begin{equation*}
  \mathfrak X_{S,r}
  :=\Sch_r(\conj{\cH_S}\otimes\cC,\cH_{S^c}\otimes\cE),
  \qquad
  \mathfrak X_{m,r}:=\bigoplus_{S\subset[m]}^{\ell^\infty}\mathfrak X_{S,r},
  \qquad
  \|(T_S)_S\|_{\mathfrak X_{m,r}}
  :=\max_{S\subset[m]}\|T_S\|_{\mathfrak X_{S,r}}.
\end{equation*}
Define
\begin{equation*}
  \Gamma_{m,r}K:=(\Flat_S(K))_{S\subset[m]},
  \qquad
  \|K\|_{m,r}:=\max_{S\subset[m]}\|\Flat_S(K)\|_{\Sch_r}.
\end{equation*}
The map $\Gamma_{m,r}$ is injective because $\Flat_\emptyset(K)$ determines
$K$ through the unitary identification
\eqref{eq:canonical-HS-identification}.  Denote the Banach completion of
$(\mathcal K_{\mathrm{alg}},\|\cdot\|_{m,r})$ by
\begin{equation*}
  \mathfrak T_{m,r}(\cH_1,\ldots,\cH_m;\cC,\cE).
\end{equation*}
The isometry $\Gamma_{m,r}$ realizes this completion as the closed subspace
\begin{equation}

  \mathfrak Y_{m,r}
  :=\overline{\Gamma_{m,r}(\mathcal K_{\mathrm{alg}})}^{\,\mathfrak X_{m,r}}
  \subset \mathfrak X_{m,r}.
\end{equation}
We call an element of $\mathfrak Y_{m,r}$ a \emph{completed simultaneous
flattening family}.  Membership in the closed range
\eqref{eq:completion-simultaneous-range} is precisely the compatibility
condition: equivalently, the family is the joint Schatten limit of all
flattenings of a single sequence of algebraic kernels.  An element of
$\mathfrak T_{m,r}$ need not be represented by a vector in the Hilbert tensor
product.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:32:28.994684+00:00","domain":"probability theory","id":"claim_0efce86bb5d8edcb74828dd8f5ac37aba8e9ffc64893a93d26745cc5ed1b7652","kind":"lemma","schema_version":1,"statement":"[Lem overlap_concentration of arXiv:2608.25362, 'Fluctuations of the free energy of the Sherrington--Kirkpatrick model with ferromagnetic i'] Consider $u_t$ defined in~(equation eq:u_t of the paper) corresponding to $\boldsymbol{\beta}$ and $h + \gamma \mu$.
    \begin{enumerate}[label=\textup{\roman*)}]
        \item Suppose $\Omega(\boldsymbol{\beta}, \gamma, h) = \{\mu, -\mu\}$ for some $\mu > 0$. Then for any $0 < t < 1$ and $\varepsilon > 0$, we have, for every $N$,
        \begin{align*}
            &\E \langle I\big(\big| |R_{\boldsymbol{\sigma}, \boldsymbol{\tau}}| - u_t \big| > \varepsilon\big)\rangle_t^{SKFI \times SK} \leqslant K_1 \exp \left( -{N}/{K_1}\right),\\
            \text{ and } 
            &\E \langle I\big(\big| |R_{\boldsymbol{\sigma}, \boldsymbol{\tau}}| - u_t \big| > \varepsilon\big)\rangle_t \leqslant K_2 \exp \left( - {N}/{K_2}\right),
        \end{align*}
        where $K_1$ and $K_2$ are constants independent of $N$.
        \item Suppose $\Omega(\boldsymbol{\beta}, \gamma, h) = \{\mu\}$ for some $\mu \neq 0$. Then for any $0 < t < 1$ and $\varepsilon > 0$, we have, for every $N$,
        \begin{align*}
            &\E \langle I\big(\big| R_{\boldsymbol{\sigma}, \boldsymbol{\tau}} - u_t \big| > \varepsilon\big)\rangle_t^{SKFI \times SK} \leqslant K_1 \exp \left( - {N}/{K_1}\right),\\
            \text{ and }
            &\E \langle I\big(\big| R_{\boldsymbol{\sigma}, \boldsymbol{\tau}} - u_t \big| > \varepsilon\big)\rangle_t \leqslant K_2 \exp \left( - {N}/{K_2}\right),
        \end{align*}
        where $K_1$ and $K_2$ are constants independent of $N$.
    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:53:10.161607+00:00","domain":"probability theory","id":"claim_0efe9e21c447258f3afbd878fa72b22d6590e07378b526275634d65c1ccbaee8","kind":"concept","schema_version":1,"statement":"[Proposition PropDataSingle of arXiv:2608.28949, 'The information geometry of product-reference discrete diffusion: Interaction growth compl'] For any choice of $u \in [a,b]$, the \textsf{IGC}\xspace increment is sandwiched as
\begin{subequations}
\begin{align}

  \frac{1}{2 c_u(a, b)} \mathsf{D}_u(a, b) & \leq \mathsf{G}(a, b) \leq 2
  c_u(a, b) \mathsf{D}_u(a, b).
\end{align}
Moreover, the one-step KL error~(equation EqnExactKL of the paper) is equal to
\begin{align}

\Gamma_{\scaleto{\operatorname{prod}}{5pt}}(a, b) & = \int_a^b \frac{\mathsf{D}_v(a, v)}{v (1 - v)} \, dv.
\end{align}
\end{subequations} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:37:15.263978+00:00","domain":"probability theory","id":"claim_0eff0d9b2e6a272ec32360f5db14a86bf4c74073cbd956c5a425201aef9558b9","kind":"definition","schema_version":1,"statement":"[10 2 of arXiv:2607.12303, 'Marginal Stationary Distributions and Convergence Rates of Higher Order Markov Chains'] {\rm
An $(m-1)$the order Markov chain with transition tensor $\cal P$ is siad to be {\it ergodic},\footnote{We note that in the first order case, an ergodic chain is also called an irreducible chain and a regular chain is equivalent to an irreducible and aperiodic chain. However, for higher order chains, irreducibility and ergodicity differ (see, for example, \cite{HanWanXu22}).} if given any $i_1, i_2, \ldots, i_m \in S$, there exists $k \ge 1$, which may depend on $i_1, i_2, \ldots, i_m$, such that $p^{(k)}_{i_1i_2\ldots i_m}>0$.  

It is called  {\it regular} if there exists some fixed $h \ge 1$ such that $p^{(h)}_{i_1i_2\ldots i_m} > 0$ for every $i_1, i_2, \ldots, i_m \in S$.
 }","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:52:05.699874+00:00","domain":"probability theory","id":"claim_0f01796dfcef30555ec635e334fa550e31eb1ed75506f47969f2f22125bf64f3","kind":"concept","schema_version":1,"statement":"[Lem incball.1 of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] If $k$ is large enough (depending only on $\gamma$), then, given $n\geq 0$, $i \in \mathbb{N}_{\geq 2}$ and~$x \in \mathbb{X}_k$ such that $\overline{{\rm B}^-[x;i+1] }\subseteq {\rm D}_n$, there exists $y \in \mathbb{X}_{k+(i-2)k^\gamma}$ satisfying $\overline{{\rm B}(y;k+ik^\gamma -3{\rm e}^{-k^\gamma})} \subseteq {\rm D}_n$ such that ${\rm B}^-[x;\max\{i-2,1\}] \subseteq {\rm B}^-[y;i-1]$, and, for all $t > 0$,
\begin{equation}
\widehat{N}^{\rm{in}}_t[y;i] \geq \widehat{N}_{t}[x;i]	 \geq \widehat{N}^{\rm{out}}_t[y;i],
\end{equation}  
 where 
\begin{equation}
\widehat{N}^{\rm{in}}_t[y;i]:=	k^\gamma N_{t}(y; k+(i-1)k^\gamma +{\rm e}^{-k^\gamma},k+ik^\gamma -5{\rm e}^{-k^\gamma})
\end{equation}
and 
\begin{equation}
\widehat{N}^{\rm{out}}_t[y;i]:= k^\gamma N_{t}(y; k+(i-1)k^\gamma -{\rm e}^{-k^\gamma},k+ik^\gamma -3{\rm e}^{-k^\gamma}).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:06:21.672453+00:00","domain":"probability theory","id":"claim_0f01aa668c481ac622c1de5275aeb7cfa9d5b4573ec47134bec58805056c3984","kind":"theorem","schema_version":1,"statement":"[Proposition 17 (Local flatness of the mean transition time) of arXiv:2607.20882, 'An Eyring--Kramers Law for the Hypoelliptic Third-Order\\ Langevin Diffusion'] For each $\varrho\in(1/2,1]$ there are $\delta,\eps_0>0$ such that, for all
$\eps\in(0,\eps_0)$ and $z\in B((m,0,0),\eps^\varrho)$,
\begin{equation}

