			\frac{(\eta(s)+r(s))^2}{c_A^2\sigma(s)^2}\,\text{d} s
			\Biggr\}
			G_r(x,y;t_1,t_2)\,\text{d} y.
		\end{aligned}
	\end{equation}

	Here $G_r$ is the fundamental solution of (equation eqA: Airy PDE with sigma diffusion of the paper).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:17:04.327572+00:00","domain":"probability theory","id":"claim_10362db3487007c35408a52e016e955b8012488236f21ac3093db1d066a71887","kind":"definition","schema_version":1,"statement":"[Definition defin:compressibilitymatrix of arXiv:2606.01937, 'Stationary fluctuations for an exclusion process with mass and energy conservation'] For any $\rho\in (0,1)$ and $\mathcal{E}\in (\rho ,\kappa\rho)$, we define the \emph{compressibility matrix} to be the covariance matrix
    \begin{equation*}
        \chi (\rho ,\mathcal{E} )\coloneq \begin{pmatrix}
            \mathrm{Var}_{\rho ,\mathcal{E}}(\xi_x) & \mathrm{Cov}_{\rho ,\mathcal{E}}(\xi_x;\eta_x) \\
            \mathrm{Cov}_{\rho ,\mathcal{E}}(\xi_x;\eta_x) & \mathrm{Var}_{\rho ,\mathcal{E}}(\eta_x)
        \end{pmatrix}.
    \end{equation*}
    After calculation, it is given by
    \begin{equation}
        \chi (\rho ,\mathcal{E}) = \begin{pmatrix}
            \rho (1-\rho) & \mathcal{E}(1-\rho)\\
            \mathcal{E}(1-\rho ) & \frac{(\mathcal{E}-\rho )(\kappa\rho -\mathcal{E})}{(\kappa -1)\rho} + \frac{(1-\rho )\mathcal{E}^2}{\rho }
        \end{pmatrix}.
    \end{equation}
    This matrix is symmetric and positive definite.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:01:56.347365+00:00","domain":"probability theory","id":"claim_10386ca1e83290ddc0e0985ad76b43ecf7ca0a1385df55aa2c7937bd5e2714c0","kind":"concept","schema_version":1,"statement":"[Lemma lem:ROC_first_order of arXiv:2609.02491, 'Generalised Random Parking for Trapeziums on a Strip'] There exists some $\ov\lambda(a,b) \in \mathbb{R}$, such that, for all $x > 2a(e+1)$, it holds that
    \begin{equation}
    \bigg|\eta(x) -\ov\lambda(a,b) x +1-\ov\lambda(a,b) \frac{a+b}{2}\bigg|
    \le \begin{dcases}
      \mleft(\frac{2e}{x/a}\mright)^{x/a-3/2} \frac{e^{3/2} K_1}{\sqrt{\pi}}, &\text{ if }a=b,\\
      \mleft(\frac{2e}{x/a}\mright)^{x/a-5/2} \frac{3e^{5/2}(2K_1+K_2)}{\sqrt{\pi}}, &\text{ if }a>b.
    \end{dcases}
\end{equation} where $K_1 \coloneqq 1 + 2a(2/(a+b)+\ov\lambda(a,b)) + \ov\lambda(a,b)\cdot  (a+b)/2>0$ and $K_2 \coloneqq (2/(a+b)+\ov\lambda(a,b))(a-b)/2\ge 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:17:13.062570+00:00","domain":"probability theory","id":"claim_103925ba3da6fb2a0402a887823572e66b23bed40d9f9d5a793b2ac184fc8d2a","kind":"concept","schema_version":1,"statement":"[Lem asymptotics_f2 of arXiv:2508.04954, 'Conditional exponential directed last passage percolation under a one-point upper large de'] Let $z_c^\pm$ be the critical points of $\mathrm G(z)$ as given in (equation eq: z_pm of the paper). 
Let $b\in {\mathbb R}$, and for each $L>0$, define the circles 
\begin{equation}
    \Sigma^{b, L}_{-}= \{ z\in {\mathbb C} \, : \, |z+1|= | z_c^- +1|+b L^{-\frac12} \}, 
    \qquad
    \Sigma^{b, L}_{+}= \{ z\in {\mathbb C} \, : \, |z|= |z_c^+| +b L^{-\frac12} \}. 
\end{equation}
\begin{itemize}
\item If $\alpha_1,\alpha_2 > 0$ and $\alpha_3 > (\sqrt{\alpha_1}+\sqrt{\alpha_2})^2$, then both  statements (eq:propertya of the paper)  and (eq:propertyb of the paper)  below hold.  
\item If $\alpha_1 < 0$ and $\alpha_2, \alpha_3 > 0$, then statement (eq:propertyb of the paper)  holds. 
\item If $\alpha_2 < 0$ and $\alpha_1, \alpha_3>0$, then statement (eq:propertya of the paper)  holds.  
\end{itemize}

\begin{enumerate}[(a)] 
\item 
There exists a constant $c>0$ such that for every $0 < \epsilon < 1/2$, 
\begin{equation} 
    \left| \frac{{\mathsf{f}}_{L}(z)}{{\mathsf{f}}_{L}(z_c^-)} \right| =   O(e^{-cL^{2\epsilon/3}})  
    \qquad \text{for $z \in \Sigma^{b, L}_{-}\cap \{ z\in {\mathbb C} : |z-z_c^-| \ge L^{-\frac12 + \frac{\epsilon}{3}}\}$}
\end{equation}
as $L \to \infty$. Furthermore, there exist  $L_0>0$ and $C>0$ such that for all $L>L_0$,
\begin{equation} 
    \left| \frac{{\mathsf{f}}_{L}(z)}{{\mathsf{f}}_{L}(z_c^-)} \right| \le C \quad \text{for $z \in \Sigma^{b, L}_{-}$}. 
\end{equation}

\item  
There exists a constant $c>0$ such that for every $0 < \epsilon < 1/2$,
\begin{equation} 
    \left| \frac{{\mathsf{f}}_{L}(z_c^+)}{{\mathsf{f}}_{L}(z)} \right| =   O(e^{-cL^{2\epsilon/3}})  
    \qquad \text{for $z \in \Sigma^{b, L}_{+}\cap \{ z\in {\mathbb C} : |z- z_c^+| \ge L^{-\frac12 + \frac{\epsilon}{3}}\}$}
\end{equation}
as $L\to \infty$. 
Furthermore, there exist $L_0>0$ and $C>0$ such that for all $L>L_0$,
\begin{equation} 
    \left| \frac{{\mathsf{f}}_{L}(z_c^+)}{{\mathsf{f}}_{L}(z)} \right| \le C \quad \text{for  $z \in \Sigma^{b, L}_{+}$}.
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:00:46.828989+00:00","domain":"probability theory","id":"claim_103c22384b6e320c83683aed6fcee6a611b70f8b6ccb3196dc3bab13762bfb6f","kind":"lemma","schema_version":1,"statement":"[Lemma 19 of arXiv:2608.13235, 'Mixing Properties of Random Laguerre Tessellations'] Let $\varepsilon > 0$ and assume that $\ppp$ is a stationary marked point process on $\rd \times \R$ such that $\p(\hat{\ppp} \in \Msettemp) = 1$. Then there exist constants $K_1,K_2,K_3, r_0 \geq 1$ such that for all $r \geq r_0$,
