{"assumptions":[],"created_at":"2026-10-27T06:21:45.379510+00:00","domain":"probability theory","id":"claim_103cbb55d026c7a46bff7bdb16f5a44823219d167b70e2e7b88f9e4399ea006d","kind":"concept","schema_version":1,"statement":"[Lem 20 of arXiv:2607.27535, 'Universal topological statistics on \\ triangulated singular spaces'] Let $\phi: U \rightarrow \RR^D$ be a $C^2$ map, where $U \subseteq \RR^d$ is a path-connected open subset. Then the following holds for all $x, y \in U$ and $v \in \RR^d$:
    \begin{align*}
        \|\phi(y) - \phi(x) - \Diff_x \phi(y-x) \| \le & \frac {h_\phi}2 \cdot \|y-x\|^2 \\
        \|\Diff_y \phi(v) - \Diff_x \phi(v) \| \le & h_\phi \cdot \|y-x \| \cdot \|v\|
    \end{align*}
    where $h_\phi$ is the supremum of the Hessian operator norm\footnote{Precise definition is $\big\| \hess_x(\phi) \big\|_\mathsf{op}^2 \eqdef
    \sup \bigg\{ \sum_{i=1}^D \big( u^\top \hess_x(\phi_i) v \big)^2 \>\bigg|\> \|u\|=\|v\|=1 \bigg\}$.}, $h_\phi \eqdef \sup_{x \in U} \big\| \hess_x(\phi) \big\|_\mathsf{op}$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:41:54.377166+00:00","domain":"probability theory","id":"claim_103e5af22a599e4cda4c9b93efe211a5a9f43b4d7b001af4a0e1602bf62aba3f","kind":"lemma","schema_version":1,"statement":"[Lemma lem:fsecondorder of arXiv:2412.01995, 'Exciting games and Monge-Amp\`{e}re equations'] Suppose $x^0 \in \partial \Delta$ with $x^0_1=\dotso=x^0_k=0$, $x^0_{k+1},\dotso,x^0_d >0$, and $\sum_{j=k+1}^d x_j^0<1$. Taking $r= (1-\sum_{i=k+1}^d x^0_i)/{(2d)}$,  there exist two positive constants $c_1(x^0)$, $c_2(x^0)$ such that for any $x_1,\dotso, x_k \in (0,r)$,
    \begin{align*}
   c_1(x^0) I_d \leq \nabla^2 \tilde \eta^{x_{1:k}}(x^0) \leq c_2(x^0) I_d,
  \end{align*}
  where $\tilde\eta^{x_{1:k}}$ is defined in (equation eq:tileta of the paper).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:33:17.731364+00:00","domain":"probability theory","id":"claim_103ea0b350c47666e78b5035118832ded16c928c01816442ca91d403427d851d","kind":"lemma","schema_version":1,"statement":"[Lemma 82 (Products with a negative H\"older coefficient) of arXiv:2607.10813, '2607.10813'] Let $0<\alpha<1$, $f\in\mathcal C^{-\alpha}(\R^3)$, and
$\varepsilon>0$.  For smooth finite-block functions the following estimates
hold, and they extend to the corresponding completed spaces.
\begin{enumerate}[label=\textup{(\roman*)},leftmargin=2.3em]
\item If $g\in L^2$, then
\begin{equation}
 \|g\prec f\|_{B_{2,\infty}^{-\alpha}}
 +\|g\prec f\|_{H^{-\alpha-\varepsilon}}
 \lesssim_\varepsilon
 \|g\|_{L^2}\|f\|_{\mathcal C^{-\alpha}}.
\end{equation}
\item If $g\in H^s\cap B_{2,\infty}^{\tau}$, then
\begin{align}
 \|f\prec g\|_{H^{s-\alpha}}
 &\lesssim \|f\|_{\mathcal C^{-\alpha}}\|g\|_{H^s},
 \\
 \|f\prec g\|_{B_{2,\infty}^{\tau-\alpha}}
 &\lesssim \|f\|_{\mathcal C^{-\alpha}}
              \|g\|_{B_{2,\infty}^{\tau}}.

\end{align}
If only the Besov norm of $g$ is used, then
\begin{equation}
 \|f\prec g\|_{H^{\tau-\alpha-\varepsilon}}
 \lesssim_\varepsilon
 \|f\|_{\mathcal C^{-\alpha}}
 \|g\|_{B_{2,\infty}^{\tau}}.
\end{equation}
\item If $s>\alpha$ and $g\in H^s$, then the resonant product is defined and
\begin{equation}
 \|g\circ f\|_{B_{2,\infty}^{s-\alpha}}
 +\|g\circ f\|_{H^{s-\alpha-\varepsilon}}
 \lesssim_\varepsilon
 \|g\|_{H^s}\|f\|_{\mathcal C^{-\alpha}}.
\end{equation}
\end{enumerate}
Multiplication of the left-hand sides by a fixed function in
