Then
\begin{eqnarray}
\frac{d\psi(t)}{dt}  & = &       \frac{\mbox{sign}(s)\beta^2}{2\sqrt{n}} \lp  \lp\sum_{k_1=1}^{r+1} \phi_{k_1}^{(r)}\rp +\phi_{22}^{(r)}+\phi_{01}^{(r)}+\phi_{02}^{(r)}\rp.
