\frac{d\psi(t)}{dt}  & = &       \frac{\mbox{sign}(s)\beta^2}{2\sqrt{n}}  \lp \sum_{k_1=1}^{r+1} \phi_{k_1}^{(r)}  +\phi_{22}^{(r)}   \rp.
 \end{eqnarray}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:38:37.417434+00:00","domain":"probability theory","id":"claim_10b402f60a5073713d133e975dd31fbc37fe3799e66a6bdf70f535bbdb8ccfcf","kind":"theorem","schema_version":1,"statement":"[Corollary 22 of arXiv:2605.16072, 'Stochastic integration \\with respect to a L\'evy basis'] Let $\Theta\colon \Borel_b(\Rp\times \O) \to L_P^0(\Omega;\R)$ be a L\'evy basis and $(\Xi_k)_{k\in{\mathbb N}}$ a sequence of $\Theta$-integrable predictable processes. Then the following are 
 	equivalent:
 	\begin{enumerate}
 		\item[{\rm (a)}] $\displaystyle \lim_{k\to\infty}E[\norm{\Xi_k}_\Theta\wedge 1]=0$;
