{"assumptions":[],"created_at":"2026-10-27T08:18:19.223759+00:00","domain":"probability theory","id":"claim_114033a0fd496f35d2b4263a1df44510e8c3406f8160dee33bf46554aa86b714","kind":"definition","schema_version":1,"statement":"[Definition 8 of arXiv:2608.29086, '2608.29086'] [$|\psi |_0$]
