{"assumptions":[],"created_at":"2026-10-28T00:55:42.239039+00:00","domain":"probability theory","id":"claim_117b0600afd81c26180253672059cb5620aa5dfbd6dee09e521728f9ee5f106e","kind":"concept","schema_version":1,"statement":"[Lemma lem: late points concentration of arXiv:2411.16398, 'Large Deviations of Cover Time of Tori in Dimensions $d\geq 3$'] Let $\varepsilon >0$. For every $\alpha_0, \lambda_0 \in (0,1)$, uniformly in $\alpha \in [\alpha_0,1)$, $\lambda \in [\lambda_0,1]$ and $F \subset \mathbb{T}_N$ satisfying $|F|=\lfloor\lambda N^d\rfloor$, 
    \begin{equation}

        \lim_{N \to \infty}\mathsf{P}\left(\Big||\mathcal{L}^\alpha_F|-\lambda N^{d(1-\alpha)}\Big|>\varepsilon \lambda N^{d(1-\alpha)}\right) = 0.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:34:45.715118+00:00","domain":"probability theory","id":"claim_117d170d5462db1932c64c663479bc8f79d018984090b5562dda415c7691c153","kind":"theorem","schema_version":1,"statement":"[Prop Prop-Linear-Lower of arXiv:2609.01964, 'The critical exponent for the two-dimensional semilinear wave equation with strong damping'] Assume that $u_0,u_1\in\mathcal C_0^\infty$ and additionally that $M_1$ in (equation Positive-Mean of the paper) is positive. Define
	\begin{align*}
		W_{\mathrm{lin}}(t,r):=r^{\frac12}\mathcal M\bigl[S_0(t)u_0+S_1(t)u_1\bigr](r).
	\end{align*}
	For every fixed $0<\sigma_-<\sigma_+<\infty$, one has
	\begin{align}
		W_{\mathrm{lin}}\bigl(t,t-\sigma\sqrt t\,\bigr)=M_1\Phi(\sigma)\,t^{-\frac14}+o(t^{-\frac14})\ \ \text{as}\ \ t\to\infty,
	\end{align}
	uniformly for $\sigma\in[\sigma_-,\sigma_+]$. Consequently, there exist $T_{\mathrm{lin}},c_{\mathrm{lin}}>0$ such that
	\begin{align*}
		W_{\mathrm{lin}}(t,r)\geqslant c_{\mathrm{lin}}t^{-\frac14}
	\end{align*}
	whenever $t\geqslant T_{\mathrm{lin}}$ and $r=t-\sigma\sqrt t$ for $\sigma\in[\sigma_-,\sigma_+]$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:47:40.724206+00:00","domain":"probability theory","id":"claim_11811017a6b5d9fc285af2231b0fbe82dbba7832ba2ecb34e01fb5c5243d39b9","kind":"lemma","schema_version":1,"statement":"[Lemma lem:bound_G of arXiv:2604.18558, 'Uniform analyticity of local observables in FK-percolation and analyticity of the Ising sp'] There exists $c_\epsilon>0$, going to 0 when $\epsilon$ tends to 0, such that for every $\epsilon > 0$ small enough, if $|z| < \epsilon$, then:
\begin{align*}
\sum_{\{\bar\gamma\} \in \mathfrak{I}\cap I(\Delta)} |G_z(\{\bar\gamma\})|\exp(-c_\epsilon |\mathsf{Tr}(\{ \bar\gamma \})|) \leq \phi_{\mathbb T_N,p}[F(\omega)].
\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:43:45.394341+00:00","domain":"probability theory","id":"claim_1182895d87c65cac831e88b345a17d5ef4213164c76c42ca8451e5b31f590887","kind":"concept","schema_version":1,"statement":"[Lemma 38 of arXiv:2609.04139, 'The conformally invariant metric on CLE$_4$ II:\\ existence of geodesics'] Fix $a>0$ and let $\Gamma_{V_a}$ be a non-nested CLE$_4$ in $V_a$. Then, there exists $r_0>0$ such that with positive probability, we have that 
\begin{align*}
D_{\Gamma_{V_a}}^{V_a}(\{0\} \times [0,1], \{a\} \times [0,1]) <r_0 \quad \text{and} \quad 2r_0 \le D_{\Gamma_{V_a}}^{V_a}([0,a] \times \{0\}, [0,a] \times \{1\}).
\end{align*}
Moreover, the following holds with positive probability. Let $L_2 = \{0\} \times [1/5,4/5]$ and let $L = \{0\} \times [0, 1]$ be the left boundary of $V_a$. Let $\partial_\mathrm{R} \SCB_{r_0}(L; D^{V_a}_{\Gamma_{V_a}})$, the \emph{right boundary} of the metric ball (it faces the right side of $V_a$ but may also meet $L$), be the intersection of $\SCB_{r_0}(L; D^{V_a}_{\Gamma_{V_a}})$ with the closure of the union of the connected components $C$ of $V_a \setminus \SCB_{r_0}(L; D^{V_a}_{\Gamma_{V_a}})$ such that $\overline{C} \cap (\{a\} \times (0,1)) \neq \emptyset$. Then:
	\begin{enumerate}[label=(\alph*),ref=\alph*]
		\item We have $D_{\Gamma_{V_a}}^{V_a}(L_2, \{a\} \times [1/5,4/5]) < r_0$;
		\item The right boundary $\partial_\mathrm{R} \SCB_{r_0}(L; D^{V_a}_{\Gamma_{V_a}})$ intersects $L_2$;
		\item We have $D_{\Gamma_{V_a}}^{V_a}([0,a] \times \{0\}, [0,a] \times \{1/5\}) \ge 2r_0$ and $D_{\Gamma_{V_a}}^{V_a}([0,a] \times \{4/5\}, [0,a] \times \{1\}) \ge 2r_0$.
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

