{"assumptions":[],"created_at":"2026-10-27T12:13:31.963784+00:00","domain":"probability theory","id":"claim_11a3b86165931f9fba99c35041e5659e336cca8e592a1e8ea0d563e28b1ea11a","kind":"lemma","schema_version":1,"statement":"[Lemma lem:final-dist-bounds of arXiv:2506.23062, 'Shifted Composition IV\@: \\ Toward Ballistic Acceleration for Log-Concave Sampling'] Under the same assumptions as Theorem~(thm:kl_local_error of the paper),
    \begin{align*}
        \mathtt{d}_t^2
        &\leqslant \exp(-c\omega_+ t)\,\Bigl(\frac{1-\exp(-\omega\,(T+Ah-t))}{1-\exp(-\omega\,(T+Ah))}\Bigr)^{cc_0}\,\mathtt{d}_0^2 + \mathtt{e}_t^2\,,
    \end{align*}
    where $\mathtt{e}_t$ is bounded as follows.
    \begin{enumerate}
        \item \textbf{Convex and high friction case:}
        Let $T_0 \coloneqq T+Ah-|\omega|^{-1}$ and $T_1 \coloneqq T+Ah-|\omega|^{-1}\log(1+c_0|\omega|/\gamma)$.
        Then,
        \begin{align*}
            \mathtt{e}_t^2 \lesssim \begin{dcases}
                \frac{(\bar{\mathcal{E}}^{\rm w})^2}{\alpha^2 h^2} + \frac{(\bar{\mathcal{E}}^{\rm s})^2}{\alpha\beta^{1/2} h}\,, & t\leqslant T_0\,, \\[0.25em]
                \Bigl[\frac{(\bar{\mathcal{E}}^{\rm w})^2}{\beta h^2} + (\bar{\mathcal{E}}^{\rm s})^2\Bigr] \, (T+Ah-t)^2 + \frac{(\bar{\mathcal{E}}^{\rm s})^2}{\beta h}\,(T+Ah-t)\,, & t\in [T_0, T_1]\,, \\[0.25em]
                \frac{(\bar{\mathcal{E}}^{\rm w})^2}{h^2}\,(T+Ah-t)^4 + \frac{(\bar{\mathcal{E}}^{\rm s})^2}{h}\,(T+Ah-t)^3 
            +\beta^2\,(\bar{\mathcal{E}}^{\rm s})^2\,(T+Ah-t)^6\,, & t \geqslant T_1\,.
            \end{dcases}
        \end{align*}


    \item \textbf{Semi-convex and low friction case:}
        Let $T_0 \coloneqq T+Ah-|\omega|^{-1}$.
        Then,
        \begin{align*}
            \mathtt{e}_t^2 \lesssim \begin{dcases}
                \frac{(\bar{\mathcal{E}}^{\rm w})^2}{\beta^2 h^2} + \frac{(\bar{\mathcal{E}}^{\rm s})^2}{\beta^{3/2} h}\,,
                & t\leqslant T_0\,, \\[0.25em]
                \frac{(\bar{\mathcal{E}}^{\rm w})^2}{h^2}\,(T+Ah-t)^4 + \frac{(\bar{\mathcal{E}}^{\rm s})^2}{h}\,(T+Ah-t)^3\,, & t \geqslant T_0\,.
            \end{dcases}
        \end{align*}

    \end{enumerate}
    Moreover, in all cases, $\mathtt{e}_T^2 \lesssim h^2\,(\bar{\mathcal{E}}^{\rm w} + \bar{\mathcal{E}}^{\rm s})^2$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:32:15.346723+00:00","domain":"probability theory","id":"claim_11acea3b7c543eb1c6ccff695c4b5a3701a3c99c38488816dca934f6bd4906fe","kind":"definition","schema_version":1,"statement":"[Definition 52 of arXiv:2506.15044, '2506.15044'] \normalfont
In the financial market $(S,\mathbb{F},\mathbb{B})$, suppose that the investor's wealth ${X}$ and trading strategy ${\vartheta}$ are defined as per \eqref{wealth}. Let $\alpha>0$ be a real number, and denote by $L(S,\mathbb{F},\mathbb{B})$ the collection of all $(\mathbb{F},\mathbb{B})$-strategies ${\vartheta}\in \mathcal{L}^\mathbb{B}({S})$.
\begin{itemize}
  \item[$(1)$] A strategy ${\vartheta}\in L(S,\mathbb{F},\mathbb{B})$ is called {\bf self-financing} if the wealth ${X}$ can be expressed as
  \begin{equation}
      {X}=({x}_0-\vartheta_0S_0)\mathfrak{I}_\mathbb{B}+{\vartheta}_{\bullet}{S}.
  \end{equation}

  \item[$(2)$] A strategy ${\vartheta}\in L(S,\mathbb{F},\mathbb{B})$ is called {\bf $\alpha$-admissible} if
      \[
      {\vartheta}_{\bullet}{S}\geq (-\alpha)\mathfrak{I}_\mathbb{B}.
      \]
      Denote by $l_\alpha(S,\mathbb{F},\mathbb{B})$ the set of all $\alpha$-admissible strategies in the financial market $(S,\mathbb{F},\mathbb{B})$. Furthermore, a strategy ${\vartheta}\in L(S,\mathbb{F},\mathbb{B})$ is called admissible if $\vartheta\in\bigcup_{a>0}l_a(S,\mathbb{F},\mathbb{B})$, and we denote by $l(S,\mathbb{F},\mathbb{B})$ the set of all admissible strategies in the financial market $(S,\mathbb{F},\mathbb{B})$.
\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:09:49.849618+00:00","domain":"probability theory","id":"claim_11ae1256fbb77c443d1e4b4fa01f1cda6515a8ab01c0f3d92b8975e455561d7c","kind":"concept","schema_version":1,"statement":"[Proposition 63 of arXiv:2609.03070, 'Variants of order semicontinuity in Banach lattices'] The following conditions are equivalent:
