{"assumptions":[],"created_at":"2026-10-27T13:20:07.894284+00:00","domain":"probability theory","id":"claim_1269d242024ada8591b2dc50fc966253a7bfe5c0f4e9097f8312cb981ccd30fd","kind":"lemma","schema_version":1,"statement":"[Lemma majorization_property of arXiv:2608.23765, '\texorpdfstring{Tight Majorizations and Convergence Rates\\ of Nuclear Norm Minimization I'] Let $\mathcal{B}, \tilde{\mathcal{B}}: \R^{d_1 \times d_2} \to \R^{d_1 \times d_2}$ be linear operators.
    Let $\mathbf{P}_{\mathbf{U}} \in \R^{d_1 \times d_1}, \mathbf{P}_{\mathbf{V}} \in \R^{d_2 \times d_2}$
    be orthogonal projection matrices.
    Denote by $\mathbf{P}_{\mathbf{U},\bot} := \mathbf{I} - \mathbf{P}_{\mathbf{U}}$ 
    and 
    $\mathbf{P}_{\mathbf{V},\bot} := \mathbf{I} - \mathbf{P}_{\mathbf{V}}$
    the projections onto the orthogonal complement.
    Define the operation
    $\mathcal{C} (\mathbf{A}) := \mathbf{P}_{\mathbf{U}} \mathbf{A} \mathbf{P}_{\mathbf{V}} + \mathbf{P}_{\mathbf{U},\bot} \mathbf{A} \mathbf{P}_{\mathbf{V},\bot}$
    for any matrix $\mathbf{A} \in \R^{d_1 \times d_2}$.
    Let now $\mathbf{Z} \in \R^{d_1 \times d_2}$ be fixed.
    Assume that the following properties hold:
    \begin{enumerate}
        \item 
        Assume that 
        $ \mathbf{Z} = \mathcal{C} (\mathbf{Z}) $.
        \item $\mathcal{B}$ is self-adjoint, i.e.,
        $\innerproduct{ \mathcal{B}(\mathbf{W}_1), \mathbf{W}_2 }
        = \innerproduct{ \mathbf{W}_1, \mathcal{B}(\mathbf{W}_2) }$
        for all $\mathbf{W}_1, \mathbf{W}_2 \in \R^{d_1 \times d_2}$.
        In addition, $\mathcal{B}$ is positive definite,
        i.e., $\innerproduct{ \mathcal{B}(\mathbf{W}_1), \mathbf{W}_1 } > 0$
        for all $\mathbf{W}_1 \in \R^{d_1 \times d_2} \backslash \{ \mathbf{0} \}$.
        \item $\tilde{\mathcal{B}}$ is self-adjoint and positive definite.
        \item It holds that 
        \begin{equation*}
          \mathcal{C}
          (\tilde{\mathcal{B}} 
          ( 
            \mathcal{C} ( \hat{\mathbf{W}} ) 
          )
          )
          =
          \mathcal{C} ( \mathcal{B} ( \mathcal{C} ( \hat{\mathbf{W}} ) ) )
        \end{equation*}
        for any matrix $\hat{\mathbf{W}} \in \R^{d_1 \times d_2}$. 
        \item It holds that 
        \begin{equation}
           \mathbf{P}_{\mathbf{U}} \tilde{\mathcal{B}} 
           ( \mathcal{C} ( \hat{\mathbf{W}} )  ) \mathbf{P}_{\mathbf{V},\bot} 
           +
           \mathbf{P}_{\mathbf{U},\bot} \tilde{\mathcal{B}} 
           ( \mathcal{C} ( \hat{\mathbf{W}} )  ) \mathbf{P}_{\mathbf{V}}
           = \mathbf{0}
        \end{equation}
        for any matrix $\hat{\mathbf{W}} \in \R^{d_1 \times d_2}$.
    \end{enumerate}
    Define $\mathbf{W} := \mathcal{B}^{-1} (\mathbf{Z})$
    and $\widetilde{\mathbf{W}} := \tilde{\mathcal{B}}^{-1} (\mathbf{Z})$.
    Then it holds that
    \begin{equation*}
        \langle  \mathbf{Z}, \mathbf{W}  \rangle_{F}
        \ge 
        \innerproduct{\mathbf{Z}, \widetilde{\mathbf{W}}}.
    \end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:45:38.364519+00:00","domain":"probability theory","id":"claim_126bd5e8e7b5dff9c41ae66fde3735ec7a4abf7713ef14c44f630098b687f8b5","kind":"lemma","schema_version":1,"statement":"[Lemma 35 of arXiv:2604.21669, 'Discontinuous transition in 2D Potts:\\ II. order-order interface convergence'] Let \(0<J<U\) satisfy \(\sinh 2J=e^{-2U}\). Then, there exist \(c_0\geq 0, n_0\geq 1\) such that for any \(n\geq n_0\), \(m_n\geq c_0n\),
