{"assumptions":[],"created_at":"2026-10-26T19:16:49.557182+00:00","domain":"probability theory","id":"claim_12875e755a54a9197413ee43974f06af5e400a4b3b8aa769761631bf606d0192","kind":"concept","schema_version":1,"statement":"[Cor 6 ({Cor.~\ref{c:LST}, \ref{c:GC}, \ref{c:GF}}) of arXiv:2509.06869, 'Infinite Interacting Brownian Motions and EVI Gradient Flows'] Suppose~\ref{ass:CE}, ~\ref{ass:ConditionalClos} and Assumption~\ref{ia:AP}.    Then, the following hold: 
\begin{enumerate}[{\rm (a)}]

\item  $(${\bf  gradient flow: curves of maximal slope}$)$ The dual semigroup~$\bigl(\mathcal T_t^{\U, \QP}\nu_0\bigr)_{t \ge 0}$ is the unique solution to the $\mssW_{2, \mssd_{\U}}$-gradient flow of $\Ent_{\QP}$ starting at $\nu_0$ in the sense of {\it  curves of maximal slope}. 
Namely, for every $\nu_0 \in \mcP_e(\U)$, the curve $[0, \infty) \ni t \mapsto \nu_t=\mathcal T_t^{\U, \QP} \nu_0$ satisfies the energy equality:
\begin{align} 
\frac{\diff}{\diff t} \Ent_\QP({\nu_t}) = -|\dot\nu_t|^2 = -|{\sf D}_{\mssW_{2, \mssd_{\U}}}^- \Ent_\QP|^2(\nu_t) \quad\text{a.e.~$t>0$} \comma
\end{align}
where $|{\sf D}_{\mssW_{2, \mssd_{\U}}}^- \cdot|$ is the descending slope in terms of $\mssW_{2, \mssd_{\U}}$, see \eqref{d:DLP}. 
Furthermore, 
\begin{align*}
|{\sf D}_{{\mssW}_{2, \mssd_\U}}^- \Ent_\QP(\nu)|^2 = 4{\sf F}(\nu)= 4\Ch^{\U, \QP}(\sqrt{\rho}) \cquad \nu=\rho\cdot \QP \in \dom{\Fis_\QP}\fstop
\end{align*}

\item  $(${\bf geodesical convexity}$)$ The space~$(\dom{\Ent_\QP}, {\mssW}_{2, \mssd_\U})$ is an extended geodesic metric space. Furthermore, the entropy~$\Ent_\QP$ is geodesically convex along every ${\mssW}_{2, \mssd_\U}$-geodesic $(\nu_t)_{t \in [0,1]}$$:$ for every $\nu_0, \nu_1 \in \dom{\Ent_\QP}$ with $\mssW_{2, \mssd_\U}(\nu_0, \nu_1)<\infty$, there exists a $\mssW_{2, \mssd_\U}$-constant speed geodesic $(v_t)_{t \in [0,1]}$ connecting $\nu_0$ and $\nu_1$ such that 
\begin{align*}
\Ent_\QP(\nu_t) \le (1-t)\Ent_{\QP}(\nu_0) + t \Ent_{\QP}(\nu_1) -\frac{K}{2}t(1-t)\mssW_{2, \mssd_{\U}}(\nu_0, \nu_1)\cquad t \in [0,1] \fstop
\end{align*}
\item   $(${\bf RCD property}$)$ the extended metric measure space $(\U, \tau_\mrmv, \mssd_\U, \QP)$ is an $\RCD(K,\infty)$ space. 
\vspace{2mm}

\item    $(${\bf Distorted Brunn--Minkowski inequality}$)$ Let $A_0, A_1 \subset \U$ be Borel sets with $\QP(A_0)\QP(A_1)>0$ and define $\nu_0:=\frac{\1_{A_0}}{\QP(A_0)} \cdot \mu$ and $\nu_1:=\frac{\1_{A_1}}{\QP(A_1)} \cdot \mu$. Suppose $\mssW_{2, \mssd_{\U}}(\nu_0, \nu_1)<\infty$. Define the $t$-barycentre $(0 \le t \le 1)$ as 
$$[A_0, A_1]_t:=\{\eta \in \U: \eta=\gamma_t,\ \gamma \in {\rm Geo}(\U, \mssd_\U),\ \gamma_0 \in A_0,\ \gamma_1 \in A_1\} \comma$$
where ${\rm Geo}(\U, \mssd_\U)$ is the space of constant speed geodesics in $\U$, see the definition~after \eqref{d:MD}.  
 Then, 

\begin{align*}
\log \frac{1}{\mu\bigl([A_0, A_1]_t \bigr)} \le (1-t)	\log \frac{1}{\mu(A_0)} + t \log \frac{1}{\mu(A_1)} - \frac{K}{2}(1-t)t\mssW_{2, \mssd_\U}(\nu_0, \nu_1) \fstop
\end{align*}

\item    $(${\bf HWI inequality}$)$ For~$\nu_0 \in \dom{\Ent_\QP}, \nu_1 \in \mcP(\U)$ with  $\mssW_{2, \mssd_\U}(\nu_0, \nu_1)<\infty$, 
$$\Ent_{\QP}(\nu_0) \le \Ent_{\QP}(\nu_1)+2\mssW_{2, \mssd_{\U}}(\nu_0, \nu_1)\Fis_{\QP}(\nu_0)^{1/2} -\frac{K}{2}\mssW_{2, \mssd_{\U}}(\nu_0, \nu_1)^2 \fstop$$

 \item $(${\bf Talagrand inequality}$)$  If $K>0$ and $(\E^{\U, \QP}, \dom{\E^{\U,\QP}})$ is irreducible, then 
$$\mssW_{2, \mssd_{\U}}^2(\nu, \QP) \le \frac{2}{K}\Ent_\QP(\nu) \cquad \nu \in \dom{\Ent_\QP} \fstop$$

\item $(${\bf log-Sobolev inequality}$)$  If $K>0$ and $(\E^{\U, \QP}, \dom{\E^{\U,\QP}})$ is irreducible, then 
$$\Ent_\QP(\nu) \le \frac{2\Fis_\QP(\nu)}{K}  \cquad \nu \in \dom{\Ent_\QP} \cap \dom{\Fis_\QP} \fstop$$

\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

