{"assumptions":[],"created_at":"2026-10-26T20:53:31.974942+00:00","domain":"probability theory","id":"claim_12a2d6cd76d492973ad3f914a51f7617ac606c68cf9e5c4369a5c0a08efd1f25","kind":"lemma","schema_version":1,"statement":"[Lemma 9 of arXiv:2606.11142, 'Strong invariance principles for diffusions, Markov chains and their perturbations.'] Let $P^m_{(x,y)}$ and $P^m_{\epsilon,(x,y)}$ denote the distributions of the vectors $V = (Z_{t_1}, \dots, Z_{t_m})$ and $V^\epsilon = (Z^\epsilon_{t_1}, \dots, Z^\epsilon_{t_m})$, respectively, where $Z_{t_k} = (X_{t_k}, Y_{t_k})$ and $Z^\epsilon_{t_k} = (X^\epsilon_{t_k}, Y^\epsilon_{t_k})$. These vectors consist of random variables sampled at the nodes of either the Euler scheme and its perturbed version, or a diffusion process and its perturbed counterpart, both starting from the initial point $z_0 = (x, y)$. Then, there exists a constant $C > 0$, such that:
\begin{equation*}
\|P^m_{(x,y)} - P^m_{\epsilon,(x,y)}\|_{TV} \le C m \bar{\Delta}_{\epsilon,\gamma,q},
\end{equation*}
where $z = (z_1, \dots, z_m)$, $z_k = (x_k, y_k) \in \mathbb{R}^{2d}$, and $dz = dz_1 \dots dz_m$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:48:47.303063+00:00","domain":"probability theory","id":"claim_12a65f6e783f857ed635b23e146a4497fe55d3123b5d093b0b1db219d327d7ce","kind":"theorem","schema_version":1,"statement":"[Theorem thm5.9 of arXiv:2604.22130, 'Reflected Stochastic Differential Equations Driven by $G$-Brownian Motion with Nonlinear C'] Given two reflected $G$-BSDEs with parameters $(x^i,f^i,h^i,g^i,l^i,r^i)$, $i=1,2$ satisfying Assumption (ass1 of the paper) and Assumption (ass2 of the paper), we additionally suppose in the following:
\begin{itemize}
\item[(1)] $x^1\leq x^2$, $g^1=g^2=g$;

\item[(2)] for each $x\in\mathbb{R}$, $f^1(t,x)\leq f^2(t,x)$, $h^1(t,x)\leq h^2(t,x)$, $l^2(t,x)\leq l^1(t,x)$, $r^2(t,x)\leq r^1(t,x)$, $t\in[0,T]$, q.s.;
\item[(3)] there exists a constant $c>0$, such that for $i=1,2$, $t\in[0,T]$ and $x,y\in\mathbb{R}$, the following inequality holds q.s.,
\begin{align}
c|x-y|\leq |r^i(t,\omega,x)-r^i(t,\omega,y)|\vee| l^i(t,\omega,x)-l^i(t,\omega,y)|;
\end{align}
\item[(4)] for each $n\in\mathbb{N}$ and $i=1,2$, there exists a pair $(l^{i,n},r^{i,n})$ satisfying Assumption (ass1 of the paper) and (equation lowerlip of the paper), such that $(l^{i,n,})^{-1}(\cdot,0)$ and $(r^{i,n})^{-1}(\cdot,0)$ are bounded, $l^{2,n}(t,x)\leq l^{1,n}(t,x)$,  $r^{2,n}(t,x)\leq r^{1,n}(t,x)$, for any $n\in\mathbb{N}$, $t\in[0,T]$, q.s., and 
\begin{align*}
\lim_{n\rightarrow \infty}\hat{\mathbb{E}}\left[\sup_{t\in[0,T]}|(l^i)^{-1}(t,0)-(l^{i,n})^{-1}(t,0)|^p\right]=\lim_{n\rightarrow \infty}\hat{\mathbb{E}}\left[\sup_{t\in[0,T]}|(r^i)^{-1}(t,x)-(r^{i,n})^{-1}(t,0)|^p\right]=0.

\end{align*}
\end{itemize}
Let $(X^i,A^i)$ be the solution to the reflected $G$-SDE with parameters $(x^i,f^i,h^i,g^i,l^i,r^i)$, $i=1,2$. Then, we have
\begin{displaymath}
X_t^1\leq X_t^2, \ t\in[0,T], \textrm{ q.s.}
\end{displaymath}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:29:52.231918+00:00","domain":"probability theory","id":"claim_12a6fa17b337c20092d38316d493a8708058c8167dcc6596ff128bf6f0a6742b","kind":"concept","schema_version":1,"statement":"[Lemma 4 of arXiv:2512.10199, 'Explicit correlation functions for the six-vertex model in the free-fermion regime'] There is a bijection 
\begin{align*}
\Phi \colon \sixv_n \longleftrightarrow \pure_n.
\end{align*}
between the set $\sixv_n$ of six-vertex configurations on $\mathbb{T}_n$ and the set $\pure_n$ of pure snake configurations on $\mathbb{T}_n$.
This bijection is constructed by looking at the local vertex type at $v$, and deciding the values of $\rho(v-\tfrac{1}{2}e^1)$ and $\rho(v-\tfrac{1}{2}e^2)$ according to the rule in Figure \ref{fig:arrowtosnake}:
\begin{itemize}
\item a red line from $v-\tfrac{1}{2}e^i$ to $v+\tfrac{1}{2}e^j$ corresponds to setting $\rho(v-\tfrac{1}{2}e^i) = v+\tfrac{1}{2}e^j$; and
\item no red line emerging from $v -\tfrac{1}{2}e^i$ corresponds to a fixed-point mid-edge, i.e., $\rho(v-\tfrac{1}{2}e^i) = v - \tfrac{1}{2}e^i$.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:53:10.210613+00:00","domain":"probability theory","id":"claim_12a72ea68fdfd3a362b8d41e282f179340224bc9630986494af1fb1e843c8640","kind":"concept","schema_version":1,"statement":"[Thm lasso of arXiv:2608.29018, 'Sharp Restricted Isometry Thresholds for\\ Global Minima of Rank-Restricted Matrix LASSO'] Fix integers $r_{\star}\ge1$ and $k\ge2$. Suppose
that $\operatorname{rank}(X_{\star})\ler_{\star}$ and that $\mathcal{A}\in\operatorname{RIP}(\delta,k)$. Define
the threshold
\begin{equation}
\delta_{\mathrm{sharp}}(t)\coloneqq\begin{cases}
\sqrt{\dfrac{t-1}{t}}, & t\ge\dfrac{4}{3},\\[2ex]
\dfrac{t}{4-t}, & 0<t<\dfrac{4}{3}.
\end{cases}
\end{equation}
\begin{itemize}
\item \emph{(Sufficiency)} If $\delta<\delta_{\mathrm{sharp}}(k/r_{\star})$, then every global
minimizer $X_{\lambda,r}$ of ((eq:matrix-lasso of the paper)) with $\lambda>0$
satisfies 
\begin{equation}
r\ger_{\star},\;\;\lambda\gtrsim\normop{\mathcal{A}^{*}(\xi)}\implies\normF{X_{\lambda,r}-X_{\star}}\lesssim\sqrt{r_{\star}}\,\lambda,
\end{equation}
where the hidden constants depend only on $\delta$ and on the ratio
$k/r_{\star}$. 
\item \emph{(Necessity)} If $\delta\ge\delta_{\mathrm{sharp}}(k/r_{\star})+1/r_{\star}$, then there
exist $X_{\star}$ and $\mathcal{A}$ with $\operatorname{rank}(X_{\star})\ler_{\star}$ and $\mathcal{A}\in\operatorname{RIP}(\delta,k)$
such that, even in the noiseless case $\xi=0$, every global minimizer
$X_{\lambda,r}$ of ((eq:matrix-lasso of the paper)) satisfies 
\begin{equation}
r\gtrsimr_{\star},\;\;\lambda>0\implies\normF{X_{\lambda,r}-X_{\star}}\ge\normF{X_{\star}},
\end{equation}
where the hidden constant depends only on the ratio $k/r_{\star}$. 
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:41:19.328772+00:00","domain":"probability theory","id":"claim_12a738de2aeeaa4180d2bf5e63e23e8b28eb6e61f93395c00803e4c396ce36a4","kind":"definition","schema_version":1,"statement":"[Definition of arXiv:2609.04045, 'Heat content and spectrum for subordinated sub-Laplacians'] A subgroup $\mathbb K$ of a Carnot group is said to be \emph{homogeneous} if
