{"assumptions":[],"created_at":"2026-10-27T17:42:08.403708+00:00","domain":"probability theory","id":"claim_12f37a41fed8fc7eac50861016104b80f6d9a4f1f29c8b8eeca32117d9114207","kind":"definition","schema_version":1,"statement":"[Definition of arXiv:2511.11036, 'Analysis of a class of Recursive Distributional Equations Including the Resistance of the '] An upper semicontinuous function $F : \mathbb{R} \times (0,+\infty) \to \mathbb{R}$ is said to satisfy the differential inequality $\partial_{t} F - \mathcal{F} ( \partial_{x} F, \partial_{x}^{2} F ) + Q(F) \leq 0$ in the viscosity sense in $\mathbb{R} \times (0,+\infty)$ if it has the following property: If $\varphi$ is a smooth function defined in some open set $U \subseteq \mathbb{R} \times (0,+\infty)$ and if there is a point $(x_{0},t_{0}) \in U$ at which $\varphi$ touches $F$ from above (that is, $F(x,t) \leq \varphi(x,t)$ for all $(x,t) \in U$ with equality when $(x,t) = (x_{0},t_{0})$), then
		\begin{align*}
			\partial_{t}\varphi(x_{0},t_{0}) - \mathcal{F} ( \partial_{x} \varphi(x_{0},t_{0}), \partial_{x}^{2} \varphi(x_{0},t_{0}) ) + Q( \varphi(x_{0},t_{0}) ) \leq 0.
		\end{align*}

	A lower semicontinuous function $G : \mathbb{R} \times (0,+\infty) \to \mathbb{R}$ is said to satisfy the differential inequality $\partial_{t} G - \mathcal{F} ( \partial_{x} G, \partial_{x}^{2} G ) + Q(G) \geq 0$ in the viscosity sense in $\mathbb{R} \times (0,+\infty)$ if it has the following property: If $\varphi$ is a smooth function defined in some open set $U \subseteq \mathbb{R} \times (0,+\infty)$ and if there is a point $(x_{0},t_{0}) \in U$ at which $\varphi$ touches $F$ from below (that is, $F(x,t) \geq \varphi(x,t)$ for all $(x,t) \in U$ with equality when $(x,t) = (x_{0},t_{0})$), then
		\begin{align*}
			\partial_{t} \varphi(x_{0},t_{0}) - \mathcal{F} ( \partial_{x} \varphi(x_{0},t_{0}), \partial_{x}^{2}\varphi(x_{0},t_{0}) ) + Q( \varphi(x_{0},t_{0}) ) \geq 0.
		\end{align*}

	A continuous function $F : \mathbb{R} \times (0,+\infty) \to \mathbb{R}$ is said to satisfy the differential equation $\partial_{t} F - \mathcal{F} ( \partial_{x} F, \partial^{2}_{x} F ) + Q(F) = 0$ in the viscosity sense in $\mathbb{R} \times (0,+\infty)$ if it satisfies both $\partial_{t} F - \mathcal{F} ( \partial_{x} F, \partial_{x}^{2} F ) + Q(F) \leq 0$ and $\partial_{t} F - \mathcal{F} ( \partial_{x} F, \partial^{2}_{x} F ) + Q(F) \geq 0$ in the viscosity sense in $\mathbb{R} \times (0,+\infty)$.","status":"unverified"}

