 \end{cases}
 $$ (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:31:20.890647+00:00","domain":"probability theory","id":"claim_1420fc6a7b854674a4c27b19a2c40040bb1e9d605cc071ea38e58d3e630f6600","kind":"theorem","schema_version":1,"statement":"[Teorema 31 (integration by parts formula) of arXiv:2506.11937, 'Random rotational invariance of integration by parts formulas within a Bismut-type approac'] Let $ (X,W)$ be a solution to  $ SDE_{\mu,\sigma}$ and let $ V= (Y, C, \tau, H)$ be an infinitesimal stochastic symmetry for  $SDE{\mu,\sigma}$. Let $T_{\lambda}=(\Phi_{\lambda}, B_{\lambda}, \eta_{\lambda}, h_{\lambda})$ be the one-paramer group related to $ V$, where, as usual $\Phi_{\lambda}=(\tilde{\Phi}_{\lambda},f_{\lambda})$ and $\ Y=(\tilde{Y},m)$. Assuming Hypothesis A' (\ref{ipotesi A'}), then the following integration by parts formula holds for every $ t \in [0,T]$, for all $ F$  bounded functional with bounded first and second derivative:
\begin{equation}
    -m(t) \mathbb{E}_{\mathbb{P}}[L(F(X_t))] + \mathbb{E}_{\mathbb{P}}[F(X_t) \int_0^t (H_{\alpha}(X_s,s) d W_s^{\alpha})] + \mathbb{E}_{\mathbb{P}}[Y(F(X_t))] - \mathbb{E}_{\mathbb{P}}[Y(F(X_0))]=0.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:56:14.251863+00:00","domain":"probability theory","id":"claim_14234c679da188be395866d47667121620e9b5d4c03e4bbc11a779154ee46fb1","kind":"concept","schema_version":1,"statement":"[Lemma lemma_stochastic_domination of arXiv:2412.09532, 'Percolation on the stationary distributions of the voter model with stirring'] There is a dimension-dependent constant~$c_d> 0$ such that the following holds. Given~$k \in \mathbb{N}$, let~$x_1,\dots,x_k \in \mathbb{Z}^d$ and let~$(X^1_t,\dots,X^k_t)_{t \ge 0}$ be a system of independent random walks started from~$(x_1,\dots,x_k)$. For fixed~$r > 0$, we write
    \begin{equation}
        \eta(x_n):= \mathds{1} \{ X^n_t \in B(X^1_t,r) \cup \cdots \cup B(X^{n-1}_t,r) \}, \quad n =1,\dots,k.
    \end{equation}
    Then, the random configuration~$\{\eta(x_n): n = 1,\dots,k\}$ is stochastically dominated by a product Bernoulli distribution on~$\{0,1\}^{\{x_1,\dots,x_k\}}$ with density parameter~$k \cdot c_d \cdot r^d \cdot t^{-d/2}$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:56:03.897879+00:00","domain":"probability theory","id":"claim_14261e3b4f580d4b4a43238c5c2b1a6edb48675849adb545d44c1af7715b0d6b","kind":"lemma","schema_version":1,"statement":"[Lem 4 of arXiv:2606.19925, 'Asymptotic properties for fully coupled delayed forward-backward stochastic differential e'] Suppose that assumptions $({\bf A1})$--$({\bf A3})$ hold. Furthermore, assume that either the time horizon $T$ or the Lipschitz constant $K$ is sufficiently small so that
\begin{eqnarray}
(57 + 432K)K e \max(1, T^2)< 1.
\end{eqnarray}			
Then there exists a positive constant $C$, independent of $\varepsilon$, such that for every $x,y\in\R$,
\begin{eqnarray*}
&&\E\left[\sup_{ t\leq s \leq T}e^{\beta s} |X^{t,x,\varepsilon}(s)- X^{t,y,\varepsilon}(s)|^2 +  \sup_{ t\leq s \leq T}e^{\beta s} |Y^{t,x,\varepsilon}(s)- Y^{t, y,\varepsilon}(s)|^2\right.\nonumber\\
&&\left.+ \int_t^T e^{\beta s} |Z^{t,x,\varepsilon}(s)- Z^{t, y,\varepsilon}(s)|^2 ds \right]\leq  C |x-y|^2.
\end{eqnarray*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:43:16.158587+00:00","domain":"probability theory","id":"claim_1427aa15064f14b0b281907254e2b2b1bf4641bec42d124b71680a8281926ec2","kind":"lemma","schema_version":1,"statement":"[Lemma 16 of arXiv:2604.13845, 'Minkowski content construction of\\ the CLE gasket measure'] Suppose that $\Gamma$ is a $\CLE_{\kappa}$ on a simply connected domain $D \subseteq \C$, and let $\meas{\cdot}{\Upsilon_{\le\ell}}$ be the volume measure on the union of its gaskets of levels at most $\ell$. For every $\ell \in \N$, $n \in \N$, $a,b>0$, and $K \subseteq D$ compact, there is a constant $c>0$ and events $E_M$ with $\p[E_M] \ge 1-cM^{-b}$ for each $M > 1$ such that the measure $\E[ (\meas{\cdot}{\Upsilon_{\le\ell}} \otimes \cdots \otimes \meas{\cdot}{\Upsilon_{\le\ell}}) \one_{E_M}]$ has a density $g$ with respect to Lebesgue measure that satisfies the bound
\begin{equation}

g(z_1,\ldots,z_n) \leq M \bigl( \min_{i \neq i'} |z_i - z_{i'}|\bigr)^{-a} \prod_{i=2}^n \bigl( \min_{i' < i} |z_i - z_{i'}| \bigr)^{\dcle - 2} ,
\quad z_1,\ldots,z_n \in K .
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:29:52.208087+00:00","domain":"probability theory","id":"claim_14284648d9822eb96e6fb091919691858903acd66398814438c1e85e040de08d","kind":"concept","schema_version":1,"statement":"[Theorem 8 (Asymptotics as $\alpha \to 0, \pi$ along $\mathcal M$) of arXiv:2512.09136, 'On the Green's functions and Martin boundary structure of a planar diffusion in a disconti'] Let $z_0 \in \R^2$ and let $\alpha_0 = 0$.
\begin{itemize}
    \item Assume that $x_{max}^+ < x_{max}^-$ (cases B and C of Figure~\ref{anglesalphab}). Then, for $\alpha \geq 0$ we have
\begin{equation}
g^{z_0}(r\cos(\alpha), r\sin(\alpha))
\underset{r\to\infty \atop\alpha\to0, \alpha \geq 0}{\sim}
 C_0f_0(z_0)\left(\kappa\alpha + \frac{1}{r} \right) \frac{e^{-r(\cos(\alpha)x(\alpha) + \sin(\alpha)y(\alpha))}}{\sqrt{r}}.
\end{equation}
where $\kappa > 0$ is an explicit constant (cf. \eqref{eq:kappa} below), $C_0$ is given by \eqref{eq:C_0}, and $f_0(z_0)$ is given by \eqref{f(z_0)col}. Moreover,
\[
\left.\partial_\alpha \left(C(\alpha)h_{\alpha}(z_0)\right)\right|_{\alpha = 0^+} = \kappa C_0f_0(z_0).
\]

\item Assume now that $x_{max}^+ > x_{max}^-$ (cases A and D of Figure~\ref{anglesalphab}). Then, for $\alpha \leq 0$,
\begin{equation}
g^{z_0}(r\cos(\alpha), r\sin(\alpha))
\underset{r\to\infty \atop\alpha\to0, \alpha \leq 0}{\sim}
 C_0f_0(z_0)\left(\kappa|\alpha| + \frac{1}{r} \right) \frac{e^{-r(\cos(\alpha)x(\alpha) + \sin(\alpha)z(\alpha))}}{\sqrt{r}},
\end{equation}
where $f_0(z_0)$ is given by \eqref{f(z_0)branch}. Moreover,
\[
\left.\partial_\alpha \left(C(\alpha)h_{\alpha}(z_0)\right)\right|_{\alpha = 0^-} = \kappa C_0f_0(z_0).
\]
\end{itemize}

The symmetric result holds for $\alpha_0 = \pi$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:19:46.235845+00:00","domain":"probability theory","id":"claim_14289d2f2f5ec0f7ec2c43867dbafb985e2fbe70fa4ead888f1b2f162f3e5ec0","kind":"theorem","schema_version":1,"statement":"[Thm 86 (Three-entropy formula) of arXiv:2507.08909, 'Annealed almost periodic entropy'] If~\eqref{eq:traces-fast} holds and $\phi \in \B(\A,\rmM_k)_+$, then
	\begin{equation} 
\rmh_{\bspi}^\ann(\phi) = \rmh_{\bspi}^0(\phi) + \log \Delta \phi_{\rm{ac}}
