{"assumptions":[],"created_at":"2026-10-27T10:07:48.550515+00:00","domain":"probability theory","id":"claim_1459090ccfd4bd0f0849fb703f64c4f4a718e9152943bf21abae276483176a30","kind":"concept","schema_version":1,"statement":"[Theorem 1 of arXiv:2609.01403, '2609.01403'] Let \(n\geq2\) and \(0<s<1\). Define
\[
    \Gamma_{n,s}
    =
    \mathcal F^{-1}
    \left(\frac{1}{|\xi|^2+|\xi|^{2s}}\right)
    \in\mathcal S'(\mathbb R^n).
\]
Then
\begin{equation}
    \mathscr{L}_s\Gamma_{n,s}
    =\delta_0
    \qquad\text{in }\mathcal S'(\mathbb R^n),

\end{equation}
and \(\Gamma_{n,s}\) is represented by a smooth real-valued radial
function in \(\mathbb R^n\setminus\{0\}\). Moreover, the following assertions hold.

\begin{enumerate}
\item \textbf{Asymptotics at the origin.}

\begin{description}
\item[\(n\geq3\) and \(4-2s<n\)]
As \(|x|\to0\),
\begin{equation}
\begin{aligned}
    \Gamma_{n,s}(x)
    &=
    \frac{|x|^{2-n}}{(n-2)\omega_{n-1}}
    -\kappa_{n,4-2s}|x|^{4-2s-n}
    +o\!\left(|x|^{4-2s-n}\right),\\
    \nabla\Gamma_{n,s}(x)
    &=
    -\frac{x}{\omega_{n-1}|x|^n}
    -(4-2s-n)\kappa_{n,4-2s}
      x|x|^{2-2s-n}
    +o\!\left(|x|^{3-2s-n}\right).
\end{aligned}

\end{equation}

\item[\(n=3\) and \(s=\frac12\)]
As \(|x|\to0\),
\begin{equation}
\begin{aligned}
    \Gamma_{3,1/2}(x)
    &=
    \frac{1}{4\pi|x|}
    -\frac{1}{2\pi^2}\log\frac1{|x|}
    +O(1),\\
    \nabla\Gamma_{3,1/2}(x)
    &=
    -\frac{x}{4\pi|x|^3}
    +\frac{1}{2\pi^2}\frac{x}{|x|^2}
    +O(1).
\end{aligned}

\end{equation}

\item[\(n=3\) and \(0<s<\frac12\)]
There exists \(C_{3,s}\in\mathbb R\) such that, as \(|x|\to0\),
\begin{equation}
\begin{aligned}
    \Gamma_{3,s}(x)
    &=
    \frac{1}{4\pi|x|}
    +C_{3,s}
    -\kappa_{3,4-2s}|x|^{1-2s}
    +o\!\left(|x|^{1-2s}\right),\\
    \nabla\Gamma_{3,s}(x)
    &=
    -\frac{x}{4\pi|x|^3}
    -(1-2s)\kappa_{3,4-2s}
      x|x|^{-1-2s}
    +o\!\left(|x|^{-2s}\right).
\end{aligned}

\end{equation}

\item[\(n=2\)]
There exists \(C_{2,s}\in\mathbb R\) such that, as \(|x|\to0\),
\begin{equation}
\begin{aligned}
    \Gamma_{2,s}(x)
    &=
    \frac{1}{2\pi}\log\frac1{|x|}
    +C_{2,s}
    -\kappa_{2,4-2s}|x|^{2-2s}
    +o\!\left(|x|^{2-2s}\right),\\
    \nabla\Gamma_{2,s}(x)
    &=
    -\frac{x}{2\pi|x|^2}
    -(2-2s)\kappa_{2,4-2s}
      x|x|^{-2s}
    +o\!\left(|x|^{1-2s}\right).
\end{aligned}

\end{equation}
\end{description}

\item \textbf{Asymptotics at infinity.}

\begin{description}
\item[\(s\neq\frac12\)]
As \(|x|\to\infty\),
\begin{equation}
\begin{aligned}
    \Gamma_{n,s}(x)
    &=
    \kappa_{n,2s}|x|^{2s-n}
    -\kappa_{n,4s-2}|x|^{4s-2-n}
    +o\!\left(|x|^{4s-2-n}\right),\\
    \nabla\Gamma_{n,s}(x)
    &=
    -(n-2s)\kappa_{n,2s}
      \frac{x}{|x|^{n+2-2s}}
    \\&\qquad
    +(n+2-4s)\kappa_{n,4s-2}
      \frac{x}{|x|^{n+4-4s}}
    +o\!\left(|x|^{4s-3-n}\right).
\end{aligned}

\end{equation}

\item[\(s=\frac12\)]
As \(|x|\to\infty\),
\begin{equation}
\begin{aligned}
    \Gamma_{n,1/2}(x)
    &=
    \kappa_{n,1}|x|^{1-n}
    +\kappa_{n,-1}|x|^{-n-1}
    +o\!\left(|x|^{-n-1}\right),\\
    \nabla\Gamma_{n,1/2}(x)
    &=
    -(n-1)\kappa_{n,1}
      \frac{x}{|x|^{n+1}}
    -(n+1)\kappa_{n,-1}
      \frac{x}{|x|^{n+3}}
    +o\!\left(|x|^{-n-2}\right).
\end{aligned}

\end{equation}
\end{description}
\end{enumerate}
All vector-valued little-\(o\) terms are understood with respect to the
Euclidean norm. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:59:58.445146+00:00","domain":"probability theory","id":"claim_145e435fbc82f2ed3768da10887832fe54d39cdbebbc5783210c769f18d88f43","kind":"concept","schema_version":1,"statement":"[Proposition prop:Wellsforheight of arXiv:2604.24743, 'The impact of disorder and non-convex interactions on delocalisation of height functions'] For any $L \in \ensuremath{\mathbb{N}}$, any $x \in \Lambda_L$ and any $\beta \geq 0$, one has the inequality
