{"assumptions":[],"created_at":"2026-10-27T14:55:18.940327+00:00","domain":"probability theory","id":"claim_149af633c76e10c6d7801f036c2517fbf721435e5a002753e4585c28d042993a","kind":"definition","schema_version":1,"statement":"[Definition eq:weightedHolder of arXiv:2602.08591, 'The Yang--Mills measure on compact surfaces as a \\ universal scaling limit of lattice gau'] Set $\alpha\in (0,1)$.
On the cylinder $[\min(f),\max(f)]_r \times \mathbb{S}^1_\theta $ near any element $(r_0,\theta_0)$,
we define local scaling centered at $(r_0,\theta_0)$ as~:
$$ \mathcal{S}^{\lambda}_{r_0,\theta_0}(r,\theta)\coloneq (\lambda(r-r_0)+r_0,\lambda(\theta-\theta_0)+\theta_0  ), \forall \lambda\in \mathbb{R}_{>0} . $$

We define weighted semi-norms a singular point $(r_0,\theta_0)\in \Psi(\mathrm{Crit}(f)_1) \subset [\min(f),\max(f)]_r \times \mathbb{S}^1_\theta$ in the cylinder.
We require that for a certain scaling exponent $s<2\alpha-1$,
\begin{equation}
\Vert \tilde{A}\Vert_{\mathcal{W}^{\alpha,\alpha-1;p;s}_{r,\theta}(\mathrm{Cyl})}^p\coloneq   \sum_{(r_0,\theta_0)\in \Psi(\mathrm{Crit}(f)_1)} \sum_{I\times J} \sum_{n=0}^\infty \left(2^{n(s-\frac{2}{p})}\Vert \mathcal{S}^{2^{-n} *}_{(r_0,\theta_0)} \tilde{A}\Vert_{\mathcal{W}^{\alpha,\alpha-1;p}_{r,\theta} (I\times J) }\right)^p + \sum_{I_2\times J_2} \Vert \tilde{A} 
\Vert^p_{\mathcal{W}^{\alpha,\alpha-1;p}_{r,\theta}(I_2\times J_2)} 
 \end{equation}
where we take the first sum over some \emph{finite cover} of the form $I_r\times J_\theta$ of a certain corona of the form $\{ m\in \Sigma; \mathrm{dist}(m,\Psi(a))\in [1,2] \}$ centered near a singular point $\Psi(a)=(r_0,\theta_0)$ and the second sum $\sum_{I_2\times J_2} \Vert \tilde{A} \Vert^p_{\mathcal{W}^{\alpha,\alpha-1,p}_{I_2\times J_2}}$ runs over a finite cover of $\{m, \mathrm{dist}\left(m,  \Psi\left(\mathrm{Crit}(f)_1\right)\right)\geqslant 1 \}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:59:25.050456+00:00","domain":"probability theory","id":"claim_149be224a2cdc3427e09a0c9fa7273e2efd002f0d3abd6ab3b2866b4296b4ff9","kind":"theorem","schema_version":1,"statement":"[Mypropo 14 of arXiv:2607.00495, 'Rank deficiency of Bernoulli random matrices for growing corank'] For any $M>0$, $p \in (0,1/2]$, $\delta \in (0,1)$ and $\varepsilon \in (0,p)$. there exist $n_{\ref{One dimensional 1}}=n_{\ref{One dimensional 1}}(p,\delta,\varepsilon)$ and $L_{\ref{One dimensional 1}}= C_{\ref{One dimensional 1}}e^{c_{\ref{One dimensional 1}}Mk}$, where $C_{\ref{One dimensional 1}}$ and $c_{\ref{One dimensional 1}}$ depending only on $p,\varepsilon$ and $\delta$. Let $f \in \ell_{1}(\mathbb{Z})$ such that $\| f\|_{1}=1$, $n \ge n_{\ref{One dimensional 1}}$, $n/2 \le l \le n$ and let $\mathcal{A}$ be an $(N,n,K,\delta)$-admissible set for $N \le 2^{n}$ and $K>0$. Then
    \begin{align*}
        \mathbb{P}\left( \Vert f_{\mathcal{A},p,l}\Vert_{\infty} \ge \max \{ L_{\ref{One dimensional 1}}/N\sqrt{n} , \left( 1-p+\varepsilon \right)^{l}\Vert f\Vert_{\infty} \} \right) \le e^{-Mkn}.
    \end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T21:02:06.325498+00:00","domain":"probability theory","id":"claim_149d24c9ac186aa861473938c03198041af5797bcda9acae8de62af9393383c5","kind":"concept","schema_version":1,"statement":"[Thm 4 of arXiv:2607.06242, 'Exponential mixing and Freidlin--Wentzell large deviation principle for Markov cocycles'] Assume that there is a lower semicontinuous function $U: E\to[0,\infty)$ and a measurable function $S:E\to[0,\infty]$ such that for any given $x,y\in E$ there exist progressively measurable processes $X_t^{\s,x}$ and $Y_t^{\s,x,y}$
      (denoted $X_t^{\s}$ and $Y_t^{\s}$ for simplicity)
      such that the following conditions hold:
      \begin{enumerate}[label=(H\arabic*)]
        \item There is a lower semicontinuous function $V: E\to \mathbb R_+$ and constant $\gamma>0$ such that
        \begin{align*}
          P_t^{\sigma}V(x) + \gamma \int_0^tP_s^{\sigma}V(x)ds\leq V(x) + \int_0^tK(\beta_s\s)ds
        \end{align*}
        where $K\in L^1(\Sigma,m)$ is nonnegative, and for any $M>0$, $U, p$ are bounded on $\{V\leq M\}$ and $\{V\leq M\}\times \{V\leq M\}$. 
        \item There exist $\zeta,\kappa>0$ such that for all $t\geq 0$,
        \begin{align*}
          p(X_t^{\s},Y_t^{\s})\leq p(x,y)\exp\left(-\zeta t + \kappa\int_0^tS(X_s^{\s})ds\right).
        \end{align*}
        \item There exist $\varpi>0$ and $b\in L^1(\Sigma,m)$ such that 
        \begin{align*}
          U(X_t^{\s}) + \varpi\int_0^tS(X_s^{\s})ds \leq U(x)+ \int_0^tb(\beta_s\s)ds + M_t^{\s},
        \end{align*}
        where $M_t^{\s}$ is a continuous local martingale with $M_0^\sigma=0$ and
        \[d\langle M^{\s}\rangle_t\leq b_1S(X_t^{\s})dt+b_2(\b_t\s)dt \quad \text{ for }t\geq 0,\]
        where  $b_1>0$ is a constant and  $b_2\in L^1(\Sigma,m)$ is nonnegative. Furthermore, 
        \begin{align*}
          \zeta>\frac{\kappa}{\varpi} \int_{\Sigma}b d m.
        \end{align*}
        \item The law of $\left(X_t^{\s}\right)_{t\in\mathbb R_+}$ coincides with $\mathbf P_{\s,x}$ and for any $\d\in(0,1]$, there exist a constant $C_{\d}>0$ and  a measurable function $\bar{\varepsilon}_{\d}:\mathbb{R}_+\to (0,1)$ which is non-increasing, such that for any $t\geq 0$, 
        \begin{align*}
          d_{TV}\left(\mathcal{L}(Y_t^{\s}), P_{t}^{\s}(y,\cdot)\right)\leq C_{\d}\left(M_{\d}(t,\s)\right)^{1/2}, \,\quad d_{TV}\left(\mathcal{L}(Y_t^{\s}), P_{t}^{\s}(y,\cdot)\right)\leq 1-\bar{\varepsilon}_{\d}(M_{\d}(t,\s)),
        \end{align*}
        where 
        \[ M_{\d}(t,\s): =\mathbf E\left(\int_0^tb_3(\beta_s\s)p(X_s^{\s},Y_s^{\s})ds\right)^{\d},\]
        and $b_3\in L^1(\Sigma,m)$ is nonnegative. 
      \end{enumerate}
      Then there is a unique $\beta_t$-invariant stationary measure 
      $(\G_\sigma)_{\s\in \Sigma}$
      of $P_t^{\s}$  such that $\G_\sigma P_t^\sigma=\G_{\beta_t \sigma}$ $m$-a.s. for all $t\geq 0$. Furthermore, there exist $\Sigma_0\subset\Sigma$ with $m(\Sigma_0)=1$, $T>0$ and $\l>0$ such that the following properties hold.
      \begin{itemize}
        \item Pullback exponential stability: for every $\sigma\in \Sigma_0$ and $x\in E$, there is $C_{\lambda}(\sigma,x)>0$ such that, for all $t\geq 0$,
        \begin{align*}
          \W_{\rho\wedge 1}\left(\delta_x P_t^{\beta_{-t} \sigma}, \G_\sigma\right) \leq C_\lambda(\sigma,x)e^{-\lambda t}.
        \end{align*}
        \item Forward exponential stability: for each fixed $r\in[0,T)$, there is a full measure set $\Sigma_r\subset\Sigma_0$ such that, for every $\sigma\in \Sigma_r$ and $x\in E$, there is $C_{\lambda,r}(\sigma,x)>0$ such that, for all $n\geq0$,
        \begin{align*}
          \W_{\rho\wedge 1}\left(\delta_x P_t^\sigma, \G_{\beta_t \sigma}\right) \leq C_{\lambda,r}(\sigma,x)e^{-\lambda t},\qquad t=nT+r.
        \end{align*}
      \end{itemize}
      Here $\W_{\rho\wedge 1}$ is the Wasserstein distance induced by the metric $\rho\wedge 1$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:36:12.190949+00:00","domain":"probability theory","id":"claim_149d9737e967092bdb0bf77444ca55808d86d930378eec3c15c8fd6c07daa59e","kind":"lemma","schema_version":1,"statement":"[Lemma 15 (Wall-defect splitting) of arXiv:2609.03916, 'Halfspace Theorems for Anisotropic Minimal Surfaces and Perimeter Minimizers'] Let $H:=\{x_{n+1}>0\}$, let $P:=\partial H$, and let
