{"assumptions":[],"created_at":"2026-10-27T08:18:19.238866+00:00","domain":"probability theory","id":"claim_14baf6b667b4ca1399d4ebf32d5fb48a6aae8a77d910ca143b6412566a90bc23","kind":"theorem","schema_version":1,"statement":"[Proposition 87 (Determing equation for the singularities within a flow) of arXiv:2608.29086, '2608.29086'] Given $M \subset H_0$, its open covering $V=\{S_i \subset M\ |\ i \in I \}$, and locally defined affine flows 
\begin{equation*}
CAF=\{\Psi(Cone\ A_i, S_i) \in FLOW(S_i)\ |\ i \in I\}.
\end{equation*}
Suppose $CAF$ is consistent. Then, a flow $\Psi_0 \in FLOW(M)$ is obtained by
\begin{equation*}
\Psi_0:=\sum_{i \in I} \Psi(Cone\ A_i, S_i).
\end{equation*}
Equation (\ref{eq_det}) below is called the \textit{determing equation} for the singularities within $\Psi_0$:
\begin{equation}
\sum_{i \in I} \Psi(Cone\ A_i, S_i)=\Psi_{Cone\ \bigcup_{i \in I} A_i}|_{M}.
\end{equation}
Then, 
\begin{enumerate}
\item $HOLE(\Psi_0)$ contains no singular region if Equation (\ref{eq_det}) holds. 
\item $HOLE(\Psi_0)$ contains a singular region if ${\prod}_{i\in I}(Cone\ A_{1i}, S_i)$ is closed and Equation (\ref{eq_det}) dose not hold. 
\item $HOLE(\Psi_0)$ contains a singular region if we cannot choose ${\prod}_{i\in I}(Cone\ A_{1i}, S_i)$ in such a way that it is closed. 
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:52:17.366134+00:00","domain":"probability theory","id":"claim_14bf32fc3bab19c1830a358e2c0ed8f5fa30d06332583233583b89c88b9fe36b","kind":"concept","schema_version":1,"statement":"[Theorem 4 (PDE theory) of arXiv:2606.02786, 'Non-local SDEs, critical drifts and local blow-ups'] Assume that the Borel measurable drift $b:\mathbb R^{1+d} \rightarrow \mathbb R^d$ satisfies  {\rm($\mathbf{H}$)}.
(Or, in complete generality, assume that the operator norms in \eqref{adams_est1}, \eqref{adams_est2} are sufficiently small.)
	Then the following are true:


	\begin{enumerate}[label=(\roman*)]


		\item
		For every $1<p<\infty$, there exist constants $c_{d,\alpha,p,\epsilon}>0$ and $\lambda_{d,\alpha,p,\epsilon} \geq 0$ such that if 
		$$\||b_{\mathfrak s}|^{\frac{1}{\alpha-1}}\|_{E_{1+\epsilon}} < c_{d,\alpha,p,\epsilon}$$ 
		then, given a right-hand side 
		\begin{equation}

		f \in \mathbb{W}_\alpha^{-\frac{2}{\alpha}+(-1+\frac{1}{\alpha})\frac{2}{p'},p}(\mathbb{R}^{1+d})
		\end{equation}
		and a sequence of functions
		$\{f_n\} \subset L^\infty(\mathbb{R}^{1+d})$ such that $$
		f_n \rightarrow f \quad \text{ in } \mathbb{W}_\alpha^{-\frac{2}{\alpha}+(-1+\frac{1}{\alpha})\frac{2}{p'},p},
		$$
		the solutions $\eta_n$ of the approximating inhomogeneous Kolmogorov-Fokker-Planck equations
		\begin{equation*}
			\lambda \eta_n + \partial_t 
			\eta_n
			 +(- \Delta)^{\frac{\alpha}{2}} \eta_n - {\rm div\,} (b_n   \eta_n)=f_n, \qquad \lambda > \lambda_{d,\alpha,p,\epsilon},
		\end{equation*}
		where $\{b_n\}$ is defined in \eqref{b_n},
		converge as $n \rightarrow \infty$ in $\mathbb{W}_\alpha^{\frac{\alpha-1}{\alpha}\frac{2}{p},p}$ to the function (formal Duhamel series) 
		\begin{equation}

			\eta=(\lambda+\partial_t  +(- \Delta)^{\frac{\alpha}{2}})^{(-1+\frac{1}{\alpha})\frac{1}{p}}(1-G_pH_p)^{-1} (\lambda+\partial_t  +(- \Delta)^{\frac{\alpha}{2}})^{-\frac{1}{\alpha}+(-1+\frac{1}{\alpha})\frac{1}{p'}} f
		\end{equation}
		where
		\begin{equation*}
			G_p:=\nabla \cdot (\lambda+\partial_t  +(- \Delta)^{\frac{\alpha}{2}} )^{-\frac{1}{\alpha}+(-1+\frac{1}{\alpha})\frac{1}{p^\prime}}  b^{\frac{1}{p^\prime}}, 
		\end{equation*}
		\begin{equation*}
			H_p:=|b|^{\frac{1}{p}}(\lambda+\partial_t  +(- \Delta)^{\frac{\alpha}{2}})^{(-1+\frac{1}{\alpha})\frac{1}{p}},
		\end{equation*}
		are bounded operators on $L^p(\mathbb{R}^{1+d})$, and the $L^p \rightarrow L^p$ operator norm of the denominator of the geometric series in \eqref{FPu_repr31} is dominated by
		\begin{equation*}
			\|G_p\|_{p \rightarrow p}\|H_p\|_{p \rightarrow p} <1,
		\end{equation*}
		so the series converges in $L^p(\mathbb{R}^{1+d})$.
		It follows that $\eta \in \mathbb{W}_\alpha^{(1-\frac{1}{\alpha})\frac{2}{p},p}.$

	Another representation for $\eta$:
		\begin{align}
			& \eta =  (\lambda+\partial_t  +(- \Delta)^{\frac{\alpha}{2}})^{-1}f \notag \\
			&\quad - (\lambda+\partial_t  +(- \Delta)^{\frac{\alpha}{2}})^{(-1+\frac{1}{\alpha})\frac{1}{p}}G_p (1-H_pG_p)^{-1}H_p (\lambda+\partial_t  +(- \Delta)^{\frac{\alpha}{2}})^{-\frac{1}{\alpha}+(-1+\frac{1}{\alpha})\frac{1}{p'}} f. 
		\end{align}



		\smallskip


		\item For a fixed $1<p<\infty$ from {(\textit{i})}, given a right-hand side $f$ satisfying \eqref{f_cond}, the function $\eta$ given by \eqref{FPu_repr31} is the unique $L^p$ weak solution (see the definition after the theorem) to the inhomogeneous Kolmogorov-Fokker-Planck equation 
	\begin{align}
		\lambda \eta + \partial_t \eta +(-\Delta)^{\frac{\alpha}{2}}\eta- {\rm div\,}( b  \eta)=f.
	\end{align}



		\item In particular, whenever $1<p<\frac{d+1}{d}$ in {\rm(\textit{ii})}, the following Cauchy problem for the Kolmogorov-Fokker-Planck  equation
		\begin{equation}
		\left\{
		\begin{array}{l}
					\lambda  \eta + \partial_t \eta +(-\Delta)^{\frac{\alpha}{2}}\eta- {\rm div\,}( b  \eta)=0, \\
					\eta|_{t=0}=\delta_x,
					\end{array}
					\right.
		\end{equation} 
		has a unique weak solution $\eta(t,\cdot)$. This weak solution corresponds to selecting the right-hand side $f:=\delta_{t=0}\delta_x$ in (\textit{ii}) -- it satisfies \eqref{f_cond}.
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

