{"assumptions":[],"created_at":"2026-10-26T20:54:34.577170+00:00","domain":"probability theory","id":"claim_156fbdb367c2a4376537b258e6dea92a4fb0f472a675bbc40e4d5b6bd4f29cef","kind":"concept","schema_version":1,"statement":"[Theorem 13 of arXiv:2606.14812, 'Joint convergence in Wiener chaos via transport hierarchy and Malliavin covariances'] Let $p\geq 2$ and let $(X_N=I_p(f_N), N\geq 1)$ with $f_N\in H^{\odot p}$ 
		for all $N\geq 1$. Assume that $(X_N, N\geq 1)$ satisfies \eqref{c1}. 
		Let $Y_N=I_q(g_N)$ with $q=ap$ for some integer $a\geq 1$. Assume that
		\begin{equation*}
			(Y_N, Y_{1,N}, \ldots, Y_{a-1,N}) \xrightarrow[N\to\infty]{(d)} 
			(Y, Y_1, \ldots, Y_{a-1}),
		\end{equation*}
		and that there exists $\rho_a\in\mathbb{R}$ such that
		\begin{equation*}
			\mathbf{E}[Y_{a,N}] \xrightarrow[N\to\infty]{} \rho_a.
		\end{equation*}
		Then $(X_N, Y_N)\xrightarrow[N\to\infty]{(d)}(Z,Y)$, where 
		$Z\sim N(0,\sigma^2)$ and the characteristic function of $(Z,Y)$ 
		is given by, for every $(u,v)\in\mathbb{R}^2$,
		\begin{equation}
			\varphi(u,v) 
			= e^{-\sigma^2 u^2/2}
			\sum_{\ell=0}^\infty \frac{u^\ell}{\ell!}
			\sum_{\substack{m=(m_1,\ldots,m_{a-1})\in\mathbb{N}^{a-1}\\ 
					|m|\leq \ell}}
			B_{\ell,m}(v)\,
			\mathbf{E}\!\left[\prod_{r=1}^{a-1}Y_r^{m_r}\, e^{ivY}\right],
		\end{equation}
		where the coefficients $B_{\ell,m}(v)$ are defined by the following recursion:
		\begin{equation}
			B_{0,(0,\ldots,0)} = 1, \qquad B_{\ell,m} = 0 
			\text{ if any component of $m$ is negative or } |m|>\ell,
		\end{equation}
		and
		\begin{equation}
			B_{\ell+1,m} = -\frac{v}{p}\,B_{\ell,m-e_1} 
			+ \frac{i}{p}\sum_{s=1}^{a-2}(m_s+1)\,B_{\ell,m+e_s-e_{s+1}}
			+ \frac{i\rho_a}{p}\,(m_{a-1}+1)\,B_{\ell,m+e_{a-1}}.
		\end{equation}
		The series \eqref{fib} converges absolutely for every $(u,v)\in\mathbb{R}^2$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:32:38.635413+00:00","domain":"probability theory","id":"claim_15719be0532b4379dc9df02d4f2a59f0eb4b140fffa6fa3b3d69e7dd5cc161cb","kind":"theorem","schema_version":1,"statement":"[Proposition 7 of arXiv:2506.17109, 'Limit theorems under nonlinear expectations dominated by sublinear expectations'] Let $\{X_{i}=(X_{i,1},\ldots,X_{i,m})\}_{i=1}^{\infty}$ be a
