 \qquad |u|\leq\varepsilon.

\end{equation}
Moreover, locally uniformly in $(x,v)\in\mathbb R^d\times\mathbb R$,
\begin{equation}
 \chi_{T,x}\left(\frac v{\sqrt T}\right)
