        \item $\underline{\underline{W}}_{G,p}(\mu^{(m)}, \nu) \to 0$ and $\int d(x, \tilde{x})^p \,d\mu^{(m)}(x) \to \int d(x, \tilde{x})^p \,d\nu(x),$ as $m \to \infty$ for some (and hence all) $\tilde{x} \in \mathcal{X}$.
