{"assumptions":[],"created_at":"2026-10-27T18:40:26.984895+00:00","domain":"probability theory","id":"claim_15bf1fffbd364bb60fd93a4222cd489dc69fa5f3be7e7d61bc3314e518614c6d","kind":"lemma","schema_version":1,"statement":"[Lemma lem:fuk-nagaev of arXiv:2604.13968, 'Divisible sandpiles via random walks in random scenery'] Let $(Y_i)_{i\in I}$ be a finite collection of independent mean-zero random variables with $M_p\coloneqq\sum_{i\in I}\mathbb{E}[|Y_i|^p]<\infty$ for some $p\geq 1$.
		\begin{enumerate}[label=\textup{(\alph*)}]
			\item \textup{(Polynomial tail, $p\in[1,2]$)}\; If $p\in[1,2]$, then for all $t>0$,
			\begin{equation}
				\mathbb{P}\biggl(\Bigl|\sum_{i\in I}Y_i\Bigr|\geq t\biggr)\leq C_p\,\frac{M_p}{t^p}\,.
			\end{equation}
			Here $C_p<\infty$ depends only on~$p$.
			\item \textup{(Polynomial $+$ Gaussian tail)}\; If $p\geq 2$ and $B^2\coloneqq\sum_{i\in I}\mathbb{E}[Y_i^2]<\infty$, then for all $t>0$,
			\begin{equation}
				\mathbb{P}\biggl(\Bigl|\sum_{i\in I}Y_i\Bigr|\geq t\biggr)\leq C_p\,\frac{M_p}{t^p}+2\exp\biggl(-c\,\frac{t^2}{B^2}\biggr)\,.
			\end{equation}
			Here $c>0$ and $C_p<\infty$ depend only on~$p$.
			\item \textup{(Bernstein)}\; If $|Y_i|\leq M$ a.s.\ for each~$i$ and $B^2\coloneqq\sum_{i\in I}\mathbb{E}[Y_i^2]<\infty$, then for all $t>0$,
			\begin{equation}
				\mathbb{P}\biggl(\Bigl|\sum_{i\in I}Y_i\Bigr|\geq t\biggr)\leq 2\exp\biggl(-\frac{t^2/2}{B^2+Mt/3}\biggr)\,.
			\end{equation}
		\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:02:28.586942+00:00","domain":"probability theory","id":"claim_15c015f138d579046f5d586e30cc08a454e9492937cb46bd7080115e607a98d6","kind":"lemma","schema_version":1,"statement":"[Lemma 19 of arXiv:2609.01333, '2609.01333'] Let  $\delta>0$, $\beta\in (0,1)$, $\alpha\in (0,\beta)$, ${u} \in \cB^\beta_\delta$ and $\psi,u, {u}_1,\dots, {u}_k \in C^{1,\beta}(\R)$ and $k\in \N \cup \{0\}$. We  define the functions $\cV_i: \R\to \R$ by
\begin{align*}
\cV_1(t)&= \int_{\mathbb{S}^1} \int_{\R}   (w(t)-w(t-r)) \psi(t-r)   D_{u}^k {\overline{\cK}} ({u},t ,r , p_\theta   ) [u_1,\dots,u_k] \mathrm{d}r  \mathrm{d}\theta
\\
\cV_2(t)&=  w(t) \int_{\mathbb{S}^1} p_\theta^2 \int_{\R}   \psi(t-r p_\theta)  D_{u}^k {\cK} ({u},t ,r   , p_\theta ) [u_1,\dots,u_k] \mathrm{d}r \mathrm{d}\theta .
\end{align*}

Then the following estimates hold
\begin{align}

\|\cV_1\|_{C^{0, \alpha}(\R)}
&\leq  c(1+ \|{u}\|_{C^{1,\beta}(\R)} )^{c} \|w\|_{C^{0,\beta}(\R)}  \|\psi\|_{C^{1,\beta}(\R)}     \prod_{i=1}^k \|{u}_i\|_{C^{1, \beta}(\R)}
\\

\|\cV_2\|_{C^{0,\beta}(\R)}
&\leq  c(1+ \|{u}\|_{C^{1,\beta}(\R)} )^{c}  \|w\|_{C^{0,\beta}(\R)}  \|\psi\|_{C^{1,\beta}(\R)}     \prod_{i=1}^k \|{u}_i\|_{C^{1, \beta}(\R)}.
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:31:20.586601+00:00","domain":"probability theory","id":"claim_15c212c87f63da409dd6485a12c3c4489315ac0b25f2d706f8abb54cded2f8f0","kind":"definition","schema_version":1,"statement":"[Definition 1 (Two-parameter Mittag--Leffler function) of arXiv:2608.25164, 'A time-fractional Kalman filter'] For $z,\alpha,\beta\in\mathbb C$ with
