       \Gamma_{{s,j}} &\leq \min\Big(1-\rho, \frac{\mu_j}{\mu_{\Sigma}}\Big) \Big(R_{{s,j}}^{\max} - \frac{1}{2} \mathbb{E}\left[(\mu_j S_j)^2\right]\Big) \\

       - \Gamma_{a} &\leq (1-\rho) \bigg(\frac{1}{2}\mathbb{E}\left[(\Lambda A)^2\right] - R_{a}^{\min}\bigg) 
    \end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:33:46.775804+00:00","domain":"probability theory","id":"claim_15daaa7d03711996f272e9d02255463dd50eba78d44ad0f3ff575cdabac470d8","kind":"concept","schema_version":1,"statement":"[Proposition 1 of arXiv:2603.25452, 'New approach to optimal control of delayed stochastic Volterra integral equations'] \textbf{(Generalized Clark--Ocone Formula~\cite{Aase2000})}\\
