{"assumptions":[],"created_at":"2026-10-27T21:05:37.777553+00:00","domain":"probability theory","id":"claim_167d4e18e60ff189a0dbfab2462d8e7affbcb928fc6fa20951911043b20e6da1","kind":"theorem","schema_version":1,"statement":"[Pro 2.2 of arXiv:2608.00420, '{Weighted $L^p$ solutions of scalar BSDEs with general unbounded stochastic coefficients}\'] Let $\bar\rho_t(\omega)$, $\bar\mu_t(\omega)$: $\Omega \times [0,\tau]\mapsto {\mathbb R}$ and $\bar f_t(\omega)$, $\bar\nu_t(\omega)$: $\Omega \times [0,\tau]\mapsto {\mathbb R}_+$ be four $(\mathcal{F}_t)$-progressively measurable processes satisfying $\int_{0}^{\tau}\left(|\bar\rho_t|+|\bar\mu_t|+\bar\nu_t^2\right){\rm d}t<+\infty$,
\begin{align*}
\bar\rho_t\geq \bar\mu_t+\frac{\theta}{2(p-1)}\bar\nu_t^2, \ \ t\in[0,\tau]
\end{align*}
for some constant $\theta>1$, and
$$
\mathbb{E}\left[\left(\int_0^\tau e^{\int_{0}^{t}\bar\rho_r{\rm d}r}\bar f_t{\rm d}t\right)^{p}\right]<+\infty.
$$
Assume that the generator $g$ satisfies the following assumption:
\begin{enumerate}
\renewcommand{(A)}{(A)}
\renewcommand{(A)}{(A)}
\item $\forall (t,y,z)\in[0,\tau]\times{\mathbb R}\times{\mathbb R}^d$,~ $\sgn(y)g(\omega,t,y,z) \leq \bar f_t(\omega) + \bar\mu_t(\omega)|y| + \bar\nu_t(\omega)|z|$,
\end{enumerate}
and $(y_t,z_t)_{t\in [0,\tau]}$ is an adapted solution of BSDE (equation BSDE1.1 of the paper) such that $y_\cdot\in S_\tau^{p}(\bar\rho_\cdot;{\mathbb R})$. Then there exists a constant $C_{p,\theta}>0$ depending only on $p$ and $\theta$ such that for each $0\leq r\leq t< +\infty$,
\begin{align*}
\mathbb{E}\left[\sup_{s\in[t\wedge\tau,\tau]}\left(e^{p
\int_{0}^{s}\bar{\rho}_{r}{\rm d}r}|y_s|^{p}\right)\bigg|\mathcal{F}_{r\wedge\tau}\right]\leq
C_{p,\theta}\mathbb{E}\left[e^{p\int_{0}^{\tau}\bar{\rho}_{r}{\rm d}r}|\xi|^{p}+\left(
\int_{t\wedge\tau}^{\tau}e^{ \int_{0}^{s}\bar{\rho}_r{\rm d}r}\bar{f}_s{\rm d}s\right)^{p}\bigg|\mathcal{F}_{r\wedge\tau}\right].
\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:53:31.975035+00:00","domain":"probability theory","id":"claim_167dd7ec8e500837f1e49992b3a32cd296aa6a36b3d18ed9a5eb139e2ac58cff","kind":"concept","schema_version":1,"statement":"[Theorem 10 of arXiv:2606.11142, 'Strong invariance principles for diffusions, Markov chains and their perturbations.'] (Simplified Theorem 1.1 from \cite{Bitter}). Under the Boundedness Assumption, for every $n$ and pairs $(t_i, x), (t_j, y)$, there exists a constant $C > 0$ such that the error between the transition densities is bounded by:
\begin{equation*}
