{"assumptions":[],"created_at":"2026-10-26T20:59:53.167404+00:00","domain":"probability theory","id":"claim_1686467a22c61c75065cff7ddd10c3ba3cfafa93801041f000455bfacefdd7c0","kind":"definition","schema_version":1,"statement":"[Definition 2 (Weighted Polynomial Topologies) of arXiv:2607.03318, 'Continuous Differentiability of the Value Function for Infinite-Dimensional Finite-Horizon'] Let $m \ge 1$. We define the continuous \emph{spatial weight function} $w_m \colon H \to \mathbb{R}$ by
\begin{equation} 

    w_m(x) := 1 + \|x\|_H^m, \quad \forall x \in H.
\end{equation}
Associated with this weight, we introduce the following functional spaces:
\begin{enumerate}[label={(\textit{\roman*})}, leftmargin=*]
    \item The \emph{measurable weighted space} $\mathcal{B}_m(H)$ consists of all Borel-measurable mappings $\varphi \colon H \to \mathbb{R}$ such that the following norm is finite:
    \begin{equation}
        \|\varphi\|_{\mathcal{B}_m} := \sup_{x \in H} \frac{|\varphi(x)|}{w_m(x)}.
    \end{equation}

    \item The \emph{continuous weighted space} $\mathcal{C}_m(H)$ is the subspace of $\mathcal{B}_m(H)$ consisting of mappings $\varphi$ that are continuous on $H$. It is equipped with the same norm $\|\cdot\|_{\mathcal{B}_{m}}$.

    \item The \emph{parabolic measurable weighted space} $\mathcal{B}_m([0, T] \times H)$ consists of all Borel-measurable mappings $\psi \colon [0, T] \times H \to \mathbb{R}$ such that the following norm is finite:
    \begin{equation}
        \|\psi\|_{\mathcal{B}_{m, T}} := \sup_{(t, x) \in [0, T] \times H} \frac{|\psi(t, x)|}{w_m(x)}.
    \end{equation}

    \item The \emph{parabolic continuous weighted space} $\mathcal{C}_m([0, T] \times H)$ is the subspace of $\mathcal{B}_m([0, T] \times H)$ consisting of mappings $\psi$ that are jointly continuous on $[0, T] \times H$. It is equipped with the same norm $\|\cdot\|_{\mathcal{B}_{m, T}}$.

    \item The \emph{spatial weighted local Lipschitz space} $\mathrm{Lip}_m(H)$ is the subspace of $\mathcal{C}_m(H)$ consisting of mappings $\varphi \colon H \to \R$ for which there exists a constant $K > 0$ such that
    \begin{equation}
        |\varphi(x) - \varphi(y)| \le K \big(1 + \|x\|_H^{m-1} + \|y\|_H^{m-1}\big) \|x - y\|_H
    \end{equation}
    for all $x, y \in H$.

    \item The \emph{weighted local Lipschitz space} $\mathrm{Lip}_{m}([0, T] \times H)$ is the subspace of $\mathcal{C}_m([0, T] \times H)$ consisting of mappings $\psi$ for which there exists a constant $K > 0$ such that
    \begin{equation} 
        |\psi(t, x) - \psi(t, y)| \le K \big(1 + \|x\|_H^{m-1} + \|y\|_H^{m-1}\big) \|x - y\|_H
    \end{equation}
    for all $x, y \in H$ and $t \in [0, T]$. 
\end{enumerate}","status":"unverified"}

