{"assumptions":[],"created_at":"2026-10-26T20:56:03.902815+00:00","domain":"probability theory","id":"claim_177187fd881a7d8bdf35118e4e5bb08b80c684d8e83a418f41e923be22d62f2f","kind":"lemma","schema_version":1,"statement":"[Lemma 23 of arXiv:2606.20908, 'On It\^o-Stratonovich formula for rough sheets'] Let $x$ and $z$ be two regular paths indexed by the plane, let $(\ga_{1},\ga_{2})\in (0,\infty)^{2}$, $p\geq 1$, and $\eps>0$ be a small parameter. In all items below, $U^{2}_{\ga_{1},\ga_{2},p}$ is the functional from Definition~\ref{def:U2}, and $(i,j)$ stands for either $(1,2)$ or $(\hat{1},\hat{2})$. Then the following holds true:

\begin{enumerate}[label=\textnormal{\textbf{(\roman*)}}]
    \item If $U^{2}_{\ga_{1},\ga_{2},p}(\bx^{i;j})<\infty$ and $U^{2}_{\ga_{1},\ga_{2},p}(\bz^{i;j})<\infty$, then $\bx^{i;j}, \bz^{i;j}\in \cp_{2,2}^{\ga_{1},\ga_{2}}$. Furthermore, there exists a universal constant $c_{2} > 0$ such that
\begin{align}}
\bigl\lVert \bx^{i;j}-\bz^{i;j}\bigr\rVert_{\ga_{1};\ga_{2}}\le c_{2}\,U^{2}_{\ga_{1},\ga_{2},p}(\bx^{i;j}-\bz^{i;j}).
\end{align}


    \item Assume that $U^{2}_{2\ga_{1},\ga_{2},p}(\bx^{1i;0\cdot j})<\infty$ and $U^{2}_{2\ga_{1},\ga_{2},p}(\bz^{1i;0\cdot j})<\infty$. Assume in addition that
\begin{equation}}
\bx^{i;j},\bz^{i;j}\in \cp_{2,2}^{\ga_{1},\ga_{2}},
\quad\text{and}\quad
\bx^{1i;2\cdot j},\bz^{1i;2\cdot j}\in \cp_{2,3}^{2\ga_{1}+\eps,\ga_{2}}.
\end{equation}
Then for all $p>\frac{1}{2\eps}$ we have $\bx^{1i;0\cdot j}, \bz^{1i;0\cdot j}\in \cp_{2,2}^{2\ga_{1},\ga_{2}}$. In addition, there exists a  constant $c_{3} > 0$ depending on $\varepsilon$ and $p$ such that
\begin{align}}
\bigl\lVert \bx^{1i;0\cdot j} - \bz^{1i;0\cdot j} \bigr\rVert^{2p}_{2\gamma_{1};\gamma_{2}} &\le
c_{3}\,\Bigl(\bigl(U^{2}_{2\ga_{1},\ga_{2},p}(\bz^{1i;0\cdot j}-\bx^{1i;0\cdot j})\bigr)^{2p} \notag\\
&\qquad +\bigl\lVert \bz^{1;0}\,\bz^{i;j} -\bx^{1;0}\,\bx^{i;j}\bigr\rVert_{2\ga_{1};\ga_{2}}^{2p}+\bigl\lVert \bz^{1i;2\cdot j} -\bx^{1i;2\cdot j}\bigr\rVert_{2\ga_{1}+\eps;\ga_{2}}^{2p}\Bigr).
\end{align}
\end{enumerate}","status":"unverified"}

