If $\ch(F)=0$, then the above statements still hold by replacing $\A^1$ and $\G_m$ by $\A^{1,\pfn}$ and $\G_m^{\pfn}$ respectively. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:32:56.102271+00:00","domain":"probability theory","id":"claim_17968034c961d2018d5deefac4f14d34cec647e8d39e5951e9e8cbf70bf13566","kind":"concept","schema_version":1,"statement":"[Theorem eq:mvt of arXiv:2411.13030, 'Classification of the limit shape for 1+1-dimensional FPP'] Let $(X_{m,n})_{0\le m < n}$ be a family of random variables that satisfies:

\begin{enumerate}[label=(\alph*)]
\item $X_{0,n}\le X_{0,m} + X_{m,n}$, for all $0<m<n$.
\item The distribution of the sequences $(X_{m,m+k})_{k\ge 1}$ and $(X_{m+1,m+k+1})_{k\ge 1}$ is the same for all $m\ge 0$.
\item For each $k\ge 1$, the sequence $(X_{nk,(n+1)k})_{n\ge 0}$ is stationary. 
\item $\E{}{X_{0,1}}<\infty$ and $\E{}{X_{0,n}}>-cn$ for some finite constant $c$. 
\end{enumerate}
Then 
\begin{equation}
\lim_{n\to \infty} \frac{X_{0,n}}{n}  \text{ exists a.s. and in }  L^1.

\end{equation}
Furthermore, if the stationary sequence in (c) is also ergodic, then the limit in (equation eq:mvt of the paper) is constant almost surely and equal to 
\begin{equation}

\lim_{n\to \infty} \frac{\E{}{X_{0,n}}}{n} = \inf_n \frac 1 n \E{}{X_{0,n}}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:28:34.982339+00:00","domain":"probability theory","id":"claim_17973d240c4a25de326747173e0c03f7867c069e69fecc12fafbe2cc68b7d598","kind":"concept","schema_version":1,"statement":"[Thm Corner process of arXiv:2412.05999, 'Non-Archimedean GUE corners and Hecke modules'] Let $t=1/q$, $n\ge 1$ be an integer.
\begin{enumerate}[left=0pt]
\item(Alternating case)\begin{enumerate}[left=0pt]
\item Let $\nu \in \Sig_n$ and let $A\in\Alt_{2n+1}(F)$ be random, with the unique $GL_{2n+1}(\mathfrak{o})$-invariant distribution such that $\SN^{\alt}(A)=\lambda$. Let $A_{2n}$ be the $2n\times2n$ corner of $A$ on the top left. Then $\SN^{\alt}(A_{2n})\in\Sig_n$ has distribution $\mathbf{P}_{2n<2n+1}^{\alt}(\cdot\mid\nu)$ defined by

\begin{equation}
\mathbf{P}_{2n<2n+1}^{\alt}(\lambda \mid \nu)=\frac{Q_{\lambda/\nu}(t;t^2)P_\lambda(1,t^2,\ldots,t^{2n-2};t^2)}{P_\nu(1,t^2,\ldots,t^{2n-2};t^2)\prod_{t^2}(t;1,t^2,\ldots,t^{2n-2})}
\end{equation}

\item Let $\lambda \in \Sig_n$, and let $A\in \Alt_{2n}(F)$ be random, with the unique $GL_{2n}(\mathfrak{o})$-invariant distribution such that $\SN^{\alt}(A)=\lambda$. Let $A_{2n-1}$ be the top left $(2n-1)\times(2n-1)$ corner of $A$. Then $\SN^{\alt}(A_{2n-1})\in\Sig_{n-1}$ has distribution $\mathbf{P}_{2n-1<2n}^{\alt}(\cdot\mid\lambda)$ given by

\begin{equation}
\mathbf{P}_{2n-1<2n}^{\alt}(\nu\mid\lambda)=\frac{P_{\lambda/\nu}(1;t^2)P_\nu(t^2,t^4,\ldots,t^{2n-2};t^2)}{P_\lambda(1,t^2,\ldots,t^{2n-2};t^2)}
\end{equation}
\end{enumerate}

\item(Hermitian case) Let $\lambda \in \Sig_n$ and let $A\in\Her_n(F)$ be random, with the unique $GL_n(\mathfrak{o})$-invariant distribution such that $\SN^{\her}(A)=\lambda$. Let $A_{n-1}$ be the top left $(n-1)\times(n-1)$ corner of $A$. Then $\SN^{\her}(A_{n-1})\in\Sig_{n-1}$ has distribution $\mathbf{P}_{n-1<n}^{\her}(\cdot\mid\lambda)$ given by
\begin{equation}
\mathbf{P}_{n-1<n}^{\her}(\nu\mid\lambda)=\sum_{\kappa\in\Sig_{n-1}} \frac{P_{\lambda/\kappa}(1;-t) Q_{\nu/\kappa}(-1;-t)P_\nu(-t,\ldots,(-t)^{n-1};-t)}{P_\lambda(1,\ldots,(-t)^{n-1};-t)\Pi_{-t}(1;t,\ldots,-(-t)^{n-1})}  
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

