        \left \|D^k_{\vec{x}} \d_\theta^r(I_q(\E D^q_{\bullet}e^{{\rm i}\theta X_u}))\right\|_{L^p(\Omega)}\lesssim(1+|\theta|)^k\Psi_{\alpha,u}^{\otimes k}(\vec{x}),
