{"assumptions":[],"created_at":"2026-10-28T00:45:32.055587+00:00","domain":"probability theory","id":"claim_1845ebe038a0645a57ea7f1778e7049dde52a8259a74b25d66ded8044829a66e","kind":"lemma","schema_version":1,"statement":"[Lemma l.interpolation of arXiv:2411.14105, 'Simultaneous replica-symmetry breaking \\ for vector spin glasses'] Let $\mu$ be a finite nonzero Borel measure supported on the unit ball of $\mathbb{R}^{D}$. For every $q\in \mathcal Q_\infty$, $x\in\mathbb{R}^{D}$, and $z\in\mathbb{R}^{D\times D}$, we set
\begin{gather}
\begin{split}
    \mathbf{f}_\mu(q,x,z) &= \mathbb{E} \log \iint \exp \left(\sqrt{2}\sigma\cdot w^q(\mathbf{h})+\sigma\cdot x + \sigma\sigma^\intercal\cdot(z-q(1))\right)\mathrm{d} \mu(\sigma) \mathrm{d} \mathfrak{R}(\mathbf{h}),
    \\
    \left\langle \cdot \right\rangle_{\mu,q,x,z} &= \frac{\exp \left(\sqrt{2}\sigma\cdot w^q(\mathbf{h})+\sigma\cdot x+ \sigma\sigma^\intercal\cdot(z-q(1))\right)\mathrm{d} \mu(\sigma) \mathrm{d} \mathfrak{R}(\mathbf{h})}{\iint \exp \left(\sqrt{2}\sigma\cdot w^q(\mathbf{h})+\sigma\cdot x+ \sigma\sigma^\intercal\cdot(z-q(1))\right)\mathrm{d} \mu(\sigma) \mathrm{d} \mathfrak{R}(\mathbf{h})}.
\end{split}
\end{gather}
Then, for every $q,q'\in\mathcal Q_\infty$, every $x,x'\in \mathbb{R}^{D}$, and every $z,z'\in\mathbb{R}^{{D}\times{D}}$, writing $q_\lambda = \lambda q+(1-\lambda)q'$, $x_\lambda =\lambda x+(1-\lambda)x'$, and $z_\lambda =\lambda z+(1-\lambda)z'$, we have
\begin{align}
    \mathbf{f}_\mu(q,x,z) - \mathbf{f}_\mu(q',x',z')= \int_0^1\mathbb{E} \left\langle R_{1,1}-R_{1,2}  + \sigma^1\cdot (x-x')\right\rangle_{\mu,q_\lambda,x_\lambda,z_\lambda} \mathrm{d} \lambda;
\end{align}
and, for any bounded measurable function $\mathbf{F}:\left(\mathbb{R}^{D}\right)^n \times \mathbb{R}^{n\times n}\to \mathbb{R}$ with $n\in\mathbb{N}$, there are constants $(c_{l,l'})_{1\leqslant l,l'\leqslant n+1}$ and $(c_l)_{1\leqslant l\leqslant n+1}$ depending only on $n$ such that
\begin{align}
\begin{split}
     &\mathbb{E}\left\langle \mathbf{F}(\cdots) \right\rangle_{\mu,q,x,z} - \mathbb{E}\left\langle \mathbf{F}(\cdots)\right\rangle_{\mu,q',x',z'}
    \\
    &= \int_0^1\mathbb{E} \left\langle \mathbf{F}(\cdots) \left(\sum_{l,l'=1}^{n+1} c_{l,l'}R_{l,l'} + \sum_{l=1}^{n+1}c_l \sigma^l\cdot (x-x')\right)\right\rangle_{\mu,q_\lambda,x_\lambda,z_\lambda} \mathrm{d} \lambda
\end{split}
\end{align}
where $\mathbf{F}(\cdots) = \mathbf{F}\left(\sigma^1,\dots ,\sigma^n;\; \left(\mathbf{h}^l\wedge\mathbf{h}^{l'}\right)_{1\leqslant l,l'\leqslant n}\right)$ and
\begin{align*}
    R_{l,l'}= 
    \begin{cases}
        \sigma^l\left(\sigma^{l}\right)^\intercal \cdot \left(z-z'\right),\quad &\text{if $l= l'$},
        \\\sigma^l\left(\sigma^{l'}\right)^\intercal \cdot \left(q-q'\right)\left(\mathbf{h}^l\wedge\mathbf{h}^{l'}\right),\quad &\text{if $l\neq l'$}.
    \end{cases}
\end{align*}","status":"unverified"}

