{"assumptions":[],"created_at":"2026-10-27T07:33:06.540430+00:00","domain":"probability theory","id":"claim_19339c9133069a12366335f4611a882b0c915eb4332ba70a0cf7eb25e5421303","kind":"concept","schema_version":1,"statement":"[Theorem 1 of arXiv:2608.25887, '\bf Efficient Estimation of High Information Projections using Nearest Neighbours'] Let $X_1, X_2, ...$ be a sequence of i.i.d. random variables on $\R^p; p > 4$, with density function $f_X$ satisfying
    \begin{itemize}
    \item[C1:] The support of $f_X$ is bounded, i.e. $\exists M > 0$ s.t. $Supp(f_X):= \{\x \in \R^p | f_X(\x) > 0\} \subset B_M(\0)$.
    \item[C2:] The density $f_X$ has bounded first two derivatives on the interior of $Supp(f_X)$.
    \item[C3:] There exist $l, H > 0$ s.t.
    \begin{align*}
        \sup_{\substack{\x \in Supp(f_X)\\0 < h_1 \leq h_2 \leq H}} \frac{f_X(\x)^2h_1^{p-1}h_2^{p-1}h_2^3}{\oint_{B_{h_1}(\x)}\oint_{B_{h_2}(\x)}f_X(\z)f_X(\w)d\z d\w} \leq l
    \end{align*}
    \item[C4:] For any $a > 0$ $\exists U > 0$ for which
    \begin{align*}
        \sup_{\substack{\x \in Supp(f_X),\\ 0 < u < U}} \frac{1}{\Fdx(u)^k} \int_1^\infty \Fdx( u\epsilon^{-1/a})^k d\epsilon = o(1),
    \end{align*}
    as $k \to \infty$.
\end{itemize}
Then
\begin{align*}
    I(\X_n, k(n)) \xrightarrow{P} I(f_X)
\end{align*}
provided the sequence $\{k(n)\}_{n \in \mathbb{N}}$ satisfies $k(n) \to \infty$ and $k(n)^{2-p/4}/n^{1-p/4} \to 0$ as $n\to\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:58:09.062210+00:00","domain":"probability theory","id":"claim_19340151a1dc44153256ecb9927a5948cea0d25c6e371fa5dfd514d82122cf59","kind":"theorem","schema_version":1,"statement":"[Thm 12 of arXiv:2606.27078, 'Semimartingale Optimal Transport with Jumps: A General Framework and Equivalent Formulatio'] Let $\Theta \subseteq \mathbb{R}^d \times \mathbb{S}_+^d \times \mathcal{L}$ be closed, convex, and satisfy Assumptions \ref{B} and \ref{J}. Moreover, let $\ell$ satisfy Assumption~\ref{ellcontinuous}. Then $\lambda$ is the unique viscosity solution of the HJB equation
