{"assumptions":[],"created_at":"2026-10-26T19:16:49.561443+00:00","domain":"probability theory","id":"claim_19b838b94f390f69924b9a604ca06818bb9d5ff0dd5da690408a9cbfe53fe54b","kind":"concept","schema_version":1,"statement":"[Cor 62 of arXiv:2509.06869, 'Infinite Interacting Brownian Motions and EVI Gradient Flows'] Let $\QP$ be a Borel probability measure on~$\U$ and $\mathcal F^{\U, \QP} \subset  \dom{\EE{\dUpsilon}{\QP}}$ be any closed Markovian subspace.  Suppose~\ref{ass:SCE}, \ref{ass:ConditionalClos}, \ref{ass:ConditionalErg},~\ref{ass:QR} of~$\mathcal F^{\U, \QP}$, ~\ref{ass:Rig} and~\ref{ass:T}. Then, the following hold:



\begin{enumerate}[$(i)$]

\item  $\ttonde{\EE{\dUpsilon}{\QP}, \mathcal F^{\U, \QP}}$ is irreducible;
\item $\{S^{\dUpsilon, \QP}_t\}$ is irreducible, i.e., every $\Xi\in \mathscr B(\tau_\mrmv)^\QP$ with
 $$S^{\dUpsilon, \QP}_t (\1_{\Xi}f) = \1_{\Xi}S^{\dUpsilon, \QP}_t f,\quad  f \in L^2(\QP) $$
 satisfies either $\QP(\Xi)=1$ or $\QP(\Xi)=0$;
\item $\{S^{\dUpsilon, \QP}_t\}$ is ergodic, i.e., 
\begin{align*}
\int_{\dUpsilon} \biggl( S^{\dUpsilon, \QP}_t u - \int_{\dUpsilon} u \diff \QP \biggr)^2 \diff \QP \xrightarrow{t \to \infty} 0, \quad u \in L^2(\QP);
\end{align*}
\item $L^{\dUpsilon, \QP}$-harmonic functions are trivial, i.e., 
$$\text{If}\ u \in \dom{L^{\dUpsilon, \QP}}\ \text{and}\  L^{\dUpsilon, \QP}u =0, \quad \text{then}\  \ u=\text{const.}\,.$$

\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:10:07.357916+00:00","domain":"probability theory","id":"claim_19b87cc27a6b619b2dd0451ed4f8f89d22b4ca8f9a3b82d4985fe97fe0925d1e","kind":"lemma","schema_version":1,"statement":"[Lemma halfpoints of arXiv:2603.05467, 'Thresholds for colouring the random Borsuk graph'] If $n$ is large enough, the following hold:
