            \text{there is a path }
            \infty\to(\boldsymbol{x},k)\to\boldsymbol{y}\}
            =\boldsymbol{x}+p^k\mathbb{Z}_p^n.
        \end{align*}
    \end{enumerate}","status":"unverified"}

