{"assumptions":[],"created_at":"2026-10-27T23:20:55.703037+00:00","domain":"probability theory","id":"claim_19eab8dd788b7b21bd04c0886816ba4652e7da4f9bf2193fbec9d3ef9340a815","kind":"concept","schema_version":1,"statement":"[Proposition PROP:OUproj of arXiv:2411.07840, 'Central limit theorem for the focusing $Φ^4$-measure in the infinite volume limit'] Define the field
\begin{align}
h&:=\mathbf{P}_{V^{L^2}_{x_0,0}} B^{-\frac{1}{2}}w_0 \notag \\
&=\mathbf{P}_{V^{L^2}_{x_0,0}} B_1^{-\frac{1}{2}}\Re w_0+i\mathbf{P}_{V^{L^2}_{x_0,0}} B_2^{-\frac{1}{2}} \Im w_0

\end{align}

\noindent 
lies in $H^{\frac{1}{2}-\epsilon}(\mathbb{T}_{L^2})$ for each $\epsilon>0$. Moreover, the $h$ is a Gaussian process with covariance operator
\begin{equation}
\left(\begin{array}{cc}
C_1& \\
& C_2
\end{array}\right)=\mathbf{P}_{V^{L^2}_{x_0,0}}\left(\begin{array}{cc}
B_1^{-1}& \\
& B_2^{-1}
\end{array}\right)\mathbf{P}_{V^{L^2}_{x_0,0}}
\end{equation}
on $L^2(\mathbb{T}_{L^2})=\Re L^2(\mathbb{T}_{L^2})\oplus i\Im L^2(\mathbb{T}_{L^2})$.
\begin{proof}
For $f, g\in L^2(\mathbb{T}_{L^2};\mathbb{R})$, we have
\begin{align*}
\mathbb{E}[\langle \Re h, f \rangle \langle \Re h, g\rangle]&=\sum_{n} \langle \mathbf{P}_{V^{L^2}_{x_0,0}} B_1^{-\frac{1}{2}} u_n,f\rangle\langle \mathbf{P}_{V^{L^2}_{x_0,0}} B_1^{-\frac{1}{2}} u_n,g\rangle\\
&=\langle B_1^{-\frac{1}{2}} \mathbf{P}_{V^{L^2}_{x_0,0}} f, B_1^{-\frac{1}{2}}\mathbf{P}_{V^{L^2}_{x_0,0}} g\rangle\\
&=\langle f, \mathbf{P}_{V^{L^2}_{x_0,0}} B_1^{-1}\mathbf{P}_{V^{L^2}_{x_0,0}} g\rangle\\
&=\langle f,C_1 g\rangle.
\end{align*}
Similar computations show
\begin{align*}
\mathbb{E}[\langle \Im h, f \rangle \langle \Im h, g\rangle]&=\langle f, C_2 g\rangle,\\
\mathbb{E}[\langle \Im h, f \rangle \langle \Re h, g\rangle]&=0.
\end{align*}
This proves the claim regarding the covariance.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

