{"assumptions":[],"created_at":"2026-10-27T14:04:39.779736+00:00","domain":"probability theory","id":"claim_1a148d251466e02f20a88b69b954abc95d8cde6a287562d53965d9e4a9e8208a","kind":"concept","schema_version":1,"statement":"[Lemma PropertiesMuDisc of arXiv:2609.02325, 'A Payne-Weinberger inequality\\for quantum dot Dirac operators'] Given $a>0$, let $\mu_\mathbb{D}(a)$ denote the first eigenvalue of the $\overline{\partial}$-Robin Laplacian $\mathcal{R}_{a}$~in the unit disk and, given $\theta\in(-\frac \pi 2, \frac \pi 2)$ and $m\geqslant 0$, let $\lambda_\mathbb{D}$ denote the first positive eigenvalue of the quantum dot Dirac operator $\mathcal{D}_{\theta, m}$ in the unit disk; that is, $\lambda_\mathbb{D} := \lambda_\mathbb{D}(\theta,m)$.~Then, 
	\begin{enumerate}[label=$(\roman*)$]
		\item the function $a\mapsto \mu_\mathbb{D}(a)$ is real analytic and concave in $(0,+\infty)$;

		\item it holds that
		\begin{equation} 
			\mu_\mathbb{D} \big( \vartheta(\theta) (\lambda_\mathbb{D}+m) \big) = \lambda_\mathbb{D}^2-m^2\text{;}
		\end{equation}
		\item the derivative of $a\mapsto \mu_\mathbb{D}(a)$  satisfies
		\begin{equation}
			a\frac{d}{da}\mu_\mathbb{D}(a) \leqslant \mu_\mathbb{D}(a) \quad \text{ for all } a>0
		\end{equation}
		and
		 \begin{equation}
			\frac{d}{da}\mu_{\mathbb{D}}(a)\Big|_{a=\vartheta(\theta)(\lambda_\mathbb{D}+m)} = \dfrac{2}{1+ \frac{\lambda_\mathbb{D}+m}{\lambda_\mathbb{D}-m}\vartheta(\theta)^2 }.
		\end{equation}
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:23:25.623825+00:00","domain":"probability theory","id":"claim_1a1eba0fbe5b9ad1cf9e1f6d28248a7015a25202badab9f49cb43c2c3c7bf0a1","kind":"concept","schema_version":1,"statement":"[Lemma lem_transfer_d of arXiv:2609.01250, 'Global regularity for 2D gravity water waves with two retreating point vortices'] For any functions $f(\cdot,t),g(\cdot,t)$, there holds
    \begin{equation}
    f\bar g_\alpha+f_\alpha\bar g=\frac{2}{it}(\Omega_0f\bar g_\alpha+L_0f\bar g_t-f_\alpha\overline{\Omega_0g}-f_t\overline{L_0g}),
