    \begin{equation}
    \begin{aligned}
    &(f_t(\alpha,t)-f_t(\beta,t)) g(\beta,t)-(f(\alpha,t)-f(\beta,t))g_t(\beta,t)\\
    =&\ \frac{2}{it}(\Omega_0f(\alpha,t)-\Omega_0f(\beta,t)-(\alpha-\beta)f_t(\alpha,t))g_t(\beta,t)-\frac{2}{it}(f_t(\alpha,t)-f_t(\beta,t)){\Omega_0g(\beta,t)}.
