\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:25:55.385535+00:00","domain":"probability theory","id":"claim_1a3a1cb1b5c4463aa46e102062da92fcd20c0854dec2e7925d4f0cd9b7b67aec","kind":"concept","schema_version":1,"statement":"[Theorem 6 of arXiv:2607.28004, 'Folding representations of reflected diffusions'] Let Assumption~\ref{ass:coefficients_Z} on the coefficients of the system \eqref{eq:RSDE_YZ} hold for $I = [0,1]$.
    \begin{enumerate}[label = (\roman*),noitemsep]
        \item There exist unique $f:I \times E \to I$ with $f(\cdot,z)$ belonging to $W^{2,1}(I)$ for every $z \in E$, and $\nu: E \to (0,\infty)$ satisfying
        \[\begin{cases}
            \partial_y f(y,z)  = \frac{1}{\nu(z)}\widehat \sigma(f(y,z),z), &   (y,z) \in I \times E, \\
            f(0,z) = 0, \quad  f(1,z) = 1, & z \in E,
        \end{cases}\]
        where $\widehat \sigma$ is given by \eqref{eq:sigma_hat}.
        These functions are explicitly given by the expressions
        \begin{equation} 

        f(y,z) = \kappa^{-1}\bigg(\frac{y}{\nu(z)},z\bigg), \qquad \text{where} \qquad \nu(z) = \bigg(\int_0^1 \frac{1}{\widehat \sigma(u,z)}du\bigg)^{-1}
        \end{equation}
        and $\kappa^{-1}(\cdot,z)$ the inverse of the function $\kappa(\cdot,z)$ in \eqref{eq:f_Z}. Moreover, $f(\cdot,\cdot)$ is of class $C^1$, $f(x,\cdot)$ is of class $C^2$ for every $x \in I$, and $\nu(\cdot)$ is of class $C^2$.
        \item Consider the SDE system 
        \begin{equation}

        \begin{aligned}
            dX_t & = \alpha(X_t,Z_t)dt + \nu(Z_t)\big(dB_t + \sigma_X(\overline X_t,Z_t)^\top d\overline W_t\big), \\
            dZ_t & = \overline b_Z(X_t,Z_t)dt + \overline \sigma_Z(X_t,Z_t)d\overline W_t,
        \end{aligned}
        \end{equation}
        where 
        $\overline b_Z(x,z) = b_Z(f(|\overline x|,z),z), \overline \sigma_Z(x,z) = \sigma_Z(f(|\overline x|,z),z)$
        with $\overline x = x - \Even(x)$, where $f(\cdot,\cdot)$ and $\nu(\cdot)$ are given by \eqref{eq:nu_Z}, $\sigma_X(\cdot,\cdot)$ is given by \eqref{eq:sigmaX},
        and where
        \[\alpha(x,z) = \sign(\overline x) \,\zeta_{\nu(z)}(\overline x,z), \qquad (x,z) \in [0,1] \times E,\]
        with $\zeta$ given by \eqref{eq:zetaZ}. This system has a globally defined weak solution, which is unique in law, for any initial values $(X_0,Z_0) = (x,z) \in \R \times E$.
        \item The process $(Y,Z) = (f(|\overline X|,Z),Z)$, with $(X,Z)$ as in \eqref{eq:SDE_system_interval}, $f$ as in \eqref{eq:nu_Z} and $\overline X = X - \Even(X)$,  satisfies the RSDE system \eqref{eq:RSDE_YZ} on $I\times E$ with initial condition $(Y_0,Z_0) = (f(|\overline X_0|,Z_0),Z_0)$, scalar Brownian Motion  \begin{align*} 
    W & =  \int_0^\cdot \sign(\overline X_t)\sqrt{1-\big\|\rho\big(f(|\overline X_t|,Z_t),Z_t\big)\big\|^2}\,dB_t + \int_0^\cdot \rho\big(f(|\overline X_t|,Z_t),Z_t\big)^\top d\overline W_t, 
\intertext{and reflection term}
        \Phi & = \sum_{n \in \Z}\int_0^\cdot  \frac{1}{\nu(Z_t)} \big(\sigma(0,Z_t)\sqrt{1-\|\rho(0,Z_t)\|^2}\, dL_t^{2n}(X)\\
        & \qquad \qquad \qquad \qquad   - \sigma(1,Z_t)\sqrt{1-\|\rho(1,Z_t)\|^2}\, dL_t^{2n+1}(X)\big).
        \end{align*}
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:33:46.773508+00:00","domain":"probability theory","id":"claim_1a3e6633c85c59e07641ef45ec6fdef3910964474af1f68f65e4fe53bbac24e1","kind":"lemma","schema_version":1,"statement":"[Lemma 67 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Assume the same notation as in Definition \ref{Def.LETop}. For any $s \in [0, \bar{\kappa})$, we can find $\epsilon > 0$, depending on $q,c,s$, such that 
