\dfrac{\log \ell}{i^{2-2\beta}}\, \log n, & \text{ if } \beta=1/2,
\end{cases}
\end{align*}
and, in particular,
\begin{align*}
\frac{1}{\tilde{s}_n}\sum_{i=1}^{n-2}\mu_{i,\cdot,\cdot}^{(n)}\cong\begin{cases}
\log n & \text{ if } \beta=1/2,\\
1 & \text{ if } \beta\in (0,1/2).
\end{cases}
