{"assumptions":[],"created_at":"2026-10-26T20:56:49.283176+00:00","domain":"probability theory","id":"claim_1a7ecb028d7496c4848aca9eb4e6311d0ac18d32814e0e92dd1356c3e3a765f6","kind":"concept","schema_version":1,"statement":"[Theorem 1 of arXiv:2606.22940, 'From smooth to discontinuous kernels: a variance transfer principle for hyperuniform proce'] (Non-asymptotic result) Let $ d\geqslant 1.$ Let $  \alpha \geqslant 0.$ Let $\maxscale,\delta >0$  such that $\maxscale (d + 2) + \delta <\frac{ 1}{d}$. 
 \begin{itemize}
\item (i) Assume that there exists  a non-degenerate  function $ f\in \B_{ c}^{ }(B_{ 1})$ non-negative such that for some finite constant $ C_{ f}$,    for all $N\geqslant 1,R \in [1,N^{ \maxscale }]  ,$  
\begin{align}

\sup_{ x\in \Sigma ^{ R }}\mathbf E  \left[\;
   \overline{\X_{ N}}(\tau _{ x}f_{ R  }) ^{ 2}
\right]\leqslant C _{ f}  R ^{ d  -\alpha }.
\end{align}

 Then   for $N\geqslant 1,\varepsilon _{ N}: = N^{ -\delta },$
  for $\gamma \in (0,1], \varphi \in \F_{ \gamma }(B_{ 1})$ we have  for all $ R \in [R^{ \circ}_{ f},N^{ \maxscale }],$   
\begin{align}

\sup_{ x\in \Sigma ^{2\varepsilon _{ N}N^{ 1/d}  }} \overline{  \textrm{Var} }^{ \varepsilon _{ N}}\left[
{ \X_{ N}}(\tau_{ x }\varphi _{  R} )
\right]\leqslant C_{ \varphi ,f} V_{ \alpha ,\gamma }(R)\end{align}

where $ C_{ \varphi ,f},R^{ \circ}_{ f}<\infty $ only depend on $ \varphi ,f,d,C_{ f}.$

 \item (ii) {\bf Converse direction}. Assume $ \alpha \in (0,2).$  Let  $ f\in \C_{ c}^{ k}(  \mathbb  T  _{ 1}^{ d})$  for some $k>(d + 1)/2 $.
Assume that   there is $R _{ N}\leqslant N^{ \maxscale }$ with $ R_{ N}\to \infty $ such that,  with $ \varepsilon _{ N} = N^{ -\delta }$,
\begin{align}

 \frac{  \overline{\textrm{Var}}^{ \varepsilon _{ N}}\left(\X_{ N}(f_{ R_{ N}})\right)}{V_{ \alpha ,1}(R_{ N})} \to \infty .
\end{align}
Then there is $ R_{ N}'\in [1,R_{ N}]$ such that
\begin{align}
  \frac{  \textrm{Var}\left(\X_{ N}(B(0,R_{ N}'))\right)}{ V_{ \alpha  ,1 }(R'_{ N})} \to \infty .
