{"assumptions":[],"created_at":"2026-10-27T13:54:12.597767+00:00","domain":"probability theory","id":"claim_1a854697790b86dd0eaddee9ddfd018f3c70a27b026d385b541fac4e49c77374","kind":"concept","schema_version":1,"statement":"[Prop P:constrained-estimate of arXiv:2604.10020, 'The directed landscape in half-space'] {ganguly2023optimal}}]

