    \item without fading: $\Scal_{\sst{\Vcal;\Tcal}}\leq_{\textnormal{L}} \Scal_{t;\sst{\Tcal}} \leq_{\textnormal{L}} \Scal_{{\sst S};\sst{\Tcal}}$ and $\Scal_{{\sst \Ical};\sst{\Tcal}} \leq_{\textnormal{L}}  \Scal_{{\sst I};\sst{\Tcal}}$,
