{"assumptions":[],"created_at":"2026-10-27T10:30:28.832671+00:00","domain":"probability theory","id":"claim_1c233977e89c477b5fc9b1eee013ffbf5179ec742b82006b8efcecf1258573eb","kind":"lemma","schema_version":1,"statement":"[Lemma 17 of arXiv:2609.02147, '2609.02147'] Let \eqref{A1}--\eqref{A4} and \eqref{equn} hold. Let $P_n \in \R^N$ be such that, for some $R_n \to \infty$,
\[
    u_n(P_n) =\max_{B_{R_n \tilde{\varepsilon}_n}(P_n)} u_n(x) \quad \text{where} \quad 
    \tilde{\varepsilon}_n \coloneq u_n(P_n)^{ - (p-2)/2 } \to 0. 
\]
Set $\varepsilon_n \coloneq \lambda_n^{-\frac{1}{2}}$. Then
\begin{equation}
    \left( \frac{\tilde{\varepsilon}_n}{\varepsilon_n} \right)^2 \to \tilde{\lambda} \in (0, a_0],
\end{equation}
where $a_0$ is the number in \eqref{A3}. Moreover, 
\begin{equation}
    \limsup_{n \to +\infty} \frac{\operatorname{dist}(P_n, \partial\Omega)}{\tilde{\varepsilon}_n} = +\infty
\end{equation}
holds, and passing to a subsequence if necessary, we have
\begin{enumerate}[label={\rm (\roman*)}]
    \item 
    $P_n \in \Omega$;
    \item 
    the scaled sequence
    \begin{equation*}
        U_n(x) \coloneq a_0^{\frac{1}{p-2}} \varepsilon_n^{\frac{2}{p-2}} u_n(\varepsilon_n x + P_n) 
        = a_0^{ \frac{1}{p-2} } \lambda_n^{ - \frac{1}{p-2} } u_n ( \lambda_n^{ - \frac{1}{2} } x + P_n )
    \end{equation*}
    converges to some $U \in H^1(\mathbb{R}^N)$ in $C^1_{\rm loc}(\mathbb{R}^N)$, where $U$ is a unique positive solution to 
    \begin{equation}
        \begin{dcases}
            -\Delta U + U = |U|^{p-2}U,\quad U>0 & \text{in } \mathbb{R}^N, \\
            U(0) = \max_{x \in \mathbb{R}^N} U, & \\
            U(x) \to 0 \quad \text{as } |x| \to +\infty;
        \end{dcases}
    \end{equation}
    \item
    there exists $\phi_n \in C_0^\infty(\R^N)$, with $\operatorname{supp}\phi_n \subset B_{R\varepsilon_n}(P_n)$ for some $R > 0$, 
    such that $Q_{\lambda_n, \tau_n,u_n}(\phi_n ) < 0$;
    \item
    for all $R > 0$ and $q \ge 1$,
    \[
        \lim_{n \to \infty} \lambda_n^{\frac{N}{2} - \frac{q}{p-2}} \int_{B_{R\varepsilon_n}(P_n)} u_n^q \, dx 
        = \lim_{n \to \infty} a_0^{ - \frac{q}{p-2} } \int_{B_R(0)} U_n^q \, dy = a_0^{ - \frac{q}{p-2} } \int_{B_R(0)} U^q\, dy.
    \]
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:32:34.762486+00:00","domain":"probability theory","id":"claim_1c24dd2653ecb030f0cd83b7b34026d0175fa94392f902e83985fbc50cc3b355","kind":"lemma","schema_version":1,"statement":"[Lemma symmetry_of_K of arXiv:2411.08220, 'Nonlocal operators with Neumann conditions'] For $t>0$, $f,g\in \mathcal{B}^+(\mathbb{R})$,
