{"assumptions":[],"created_at":"2026-10-27T18:44:24.695748+00:00","domain":"probability theory","id":"claim_1c8eb04a1fd208485e50275577c1b80cecad45cc74c8b12adf615b48baf6db34","kind":"definition","schema_version":1,"statement":"[Definition def:limiting_function of arXiv:2604.20215, '\bf Edge Universality for Inhomogeneous Random Matrices II: Markov Chain Comparison and Cr'] Given a typical diagram $\Gamma$, for $t_1,\dots,t_s>0$ we introduce a family of linear constraints for edge–weighted variables $\{\alpha_e\geq 0\}$
\begin{equation}
\mathfrak{C}(\{t_i\})
:\quad
\sum_{e\in E(\Gamma)} c_i(e)\,\alpha_e \;\le\; t_i,
\quad i=1,\dots,s,
\end{equation}
where \(c_i(e)\in \{0,1,2\}\)  counts how many times the edge
$e$ appears in the boundary $\partial D_i$.
   Let \(C_\Gamma>0\) be a combinatorial constant depending only on \(\Gamma\) defined by
\begin{equation}
    C_\Gamma=\lim_{n_j\rightarrow\infty}\frac{\#\{(w_e)_{e\in E(\Gamma)}|
        m_j, w_e\in \mathbb{N},~m_j \ge 0,\; w_e \ge 1,~
        2m_j + \sum\limits_{e \in \partial D_j} w_e = n_j,~ j=1,\dots,s\}}{\mathrm{Vol}\{(\alpha_e)_{e\in E(\Gamma)}|\alpha_e\in \mathbb{R}^+, \sum_{e\in E(\Gamma)} c_j(e)\,\alpha_e \;\le\; n_j,
\quad j=1,\dots,s\}}.
\end{equation}
The three limiting  diagram functions are then defined separately for each phase regime as follows:
\begin{enumerate}
    \item[(i)] \textbf{(Supercritical case)}
    \begin{equation}
\mathcal{F}^{\mathrm{(Super)}}_\Gamma(t_1,\dots,t_s)
\;=\frac{C_\Gamma}{\,t_1\cdots t_s\,}\mathrm{Vol}_{\mathfrak{C}}(\{t_i\}),
\end{equation}
where
\begin{equation}
    \mathrm{Vol}_{\mathfrak{C}}(\{t_i\})=\int_{\mathfrak{C}(\{t_i\})}1\,\prod_{e\in E(\Gamma)}d\alpha_e.
\end{equation}
\item[(ii)]  \textbf{(Subcritical case, $\alpha>d=1$)}
\begin{equation}
    \mathcal{F}^{\mathrm{(Sub)}}_\Gamma(t_1,\dots,t_s)
    \;=\;
    \frac{C_\Gamma}{\,t_1\cdots t_s\,}\,
    \int_{x_v\in \mathbb{R}^d, v\ne v_0}\int_{\mathfrak{C}(\{t_i\})}
    \prod_{e\in E(\Gamma)}f_{\alpha}(x_{u}-x_{v},\alpha_e ) \prod_{e\in E(\Gamma)}d\alpha_e \prod_{v_0\neq v\in V(\Gamma)} dx_v,
\end{equation} where
the first integral is over all $x_v$ in $\mathbb{R}^d$ except for  $x_{v_0}=0$, with   some $v_0\in V(\Gamma)$.
\item[(iii)] \textbf{(Critical case, $\alpha>d=1$)}
    \begin{equation}
    \mathcal{F}^{\mathrm{(Crit)}}_\Gamma(t_1,\dots,t_s;\tau)
    \;=\;
    \frac{C_\Gamma}{\,t_1\cdots t_s\,}\,
    \int_{x_v\in \mathbb{T}^d}\int_{\mathfrak{C}(\{t_i\})}
    \prod_{e\in E(\Gamma)}\theta_{\alpha}(x_{u}-x_{v},\alpha_e\tau) \prod_{e\in E(\Gamma)}d\alpha_e \prod_{v\in V(\Gamma)}dx_v.
\end{equation}
\end{enumerate}","status":"unverified"}

