{"assumptions":[],"created_at":"2026-10-26T19:36:04.990116+00:00","domain":"probability theory","id":"claim_1cdf027beb37ef1aa1111027d558c4ad7fdc1e1c8ae001cbe417f86ff1a9266d","kind":"theorem","schema_version":1,"statement":"[Theorem 10 of arXiv:2604.00882, 'On some extensions of generalized counting processes'] The probabilities ${\tilde p}_n^\nu(t)$
satisfy the following  equation
\begin{equation}
	\frac{d^{2\nu} \tilde p_n^\nu}{dt^{2\nu}} + 2\lambda \frac{d^\nu \tilde p_n^\nu}{dt^\nu} = - \Lambda \tilde p_n(t) + \sum_{j=1}^{\min\{n,k\}}\lambda_j \tilde p_{n-j}(t), \,\, n\geq0,
\end{equation}
with the standard initial condition and fractional derivatives in C-D sense.

	The solution ${\tilde p}_n^\nu(t)$, for $n = 0, 1, \dots$ and $t \ge 0$, of \eqref{fM2eq} is given as follows:
	\begin{description}
	\item $\quad$if $\lambda=\Lambda^{1/2}$,
	\begin{align}
		\tilde p_n^\nu(t) &= \sum_{r=0}^n \sum_{\substack{\alpha_1+\alpha_2+\dots+\alpha_k=r \\ \alpha_1+2\alpha_2+\dots+k\alpha_k=n}} \binom{r}{\alpha_1, \alpha_2, \dots, \alpha_k} \lambda_1^{\alpha_1} \lambda_2^{\alpha_2} \dots \lambda_k^{\alpha_k} \nonumber \\
				&\times  \left(t^{2r\nu} E_{\nu, 2r\nu+1}^{2r+1}(-\Lambda^{1/2} t^\nu) + \Lambda^{1/2} t^{(2r+1)\nu} E_{\nu, (2r+1)\nu+1}^{2r+2}(-\Lambda^{1/2} t^\nu)\right),
	\end{align}
	where the generalized Mittag-Leffler function is defined in \eqref{ML3};
		\item $\quad$if $\lambda>\Lambda^{1/2}$,
		\begin{align}
		\tilde p_n^\nu(t) &= \sum_{r=0}^n \sum_{\substack{\alpha_1+\alpha_2+\dots+\alpha_k=r \\ \alpha_1+2\alpha_2+\dots+k\alpha_k=n}} \binom{r}{\alpha_1, \alpha_2, \dots, \alpha_k} \lambda_1^{\alpha_1} \lambda_2^{\alpha_2} \dots \lambda_k^{\alpha_k} \nonumber \\
				&\times  \left(\lambda^{2k} t^{2k\nu} E_{\nu, 2k\nu+1}^{k+1, k+1}(p_1 t^\nu, p_2 t^\nu) + \lambda^{2k+1} t^{(2k+1)\nu} E_{\nu, (2k+1)\nu+1}^{k+1, k+1}(p_1 t^\nu, p_2 t^\nu)\right),
	\end{align}		
		where
		$p_1$ and  $p_2$ are given in \eqref{pp}
		and the multivariate Mittag-Leffler function is defined in \eqref{multML}.
	\end{description}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T21:02:38.609123+00:00","domain":"probability theory","id":"claim_1ce1475430041ba07a380e3473a0c6640e15bd4c9f4e4d2d434c94fe26cfff68","kind":"theorem","schema_version":1,"statement":"[Prop 10 of arXiv:2607.08314, 'Berry-Heisenberg random waves'] Let us fix $c\in \mathcal{O}^{1}$ and $N\in \mathbb{N}$ and let $\{ \phi_{\ell} , \, \theta^{\ell}_{k}, \, \psi^{\ell}_{j}, \; \ell = 1,\ldots N \}_{k,j=0}^{\infty}$ be a sequence of i.i.d. $\text{Unif}(0,2\pi)$, $\{ \varepsilon_{\ell}, \; \ell = 1,\ldots N\}$ be i.i.d. $\text{Unif}\{-1,1\}$, and $\{ \eta_{\ell}, \; \ell = 1,\ldots N\}$ be i.i.d. uniform random variables on $\mathbb{S}^{1}$. Moreover, we assume that $ \phi_{\ell} , \, \theta^{\ell}_{k}, \, \psi^{\ell}_{j}, \varepsilon_{\ell}, \eta_{\ell}$ are all independent from each other for all $k,j=0,1,\ldots,  \ell = 1,\ldots N$. Let us define the random wave 
    \begin{align*}
       & u_{\alpha}^{N} (g):= \frac{1}{\sqrt{N}} \sum_{\ell =1}^{N}  u_{\alpha, \ell}(g),
    \end{align*}
    where 
    \begin{align*}
        & u_{\alpha, \ell} (g) :=\sqrt{2c_{-1}}  e^{i \left( \sqrt{\alpha} \, z \cdot \eta_{\ell} + \phi_{\ell} \right)}+  \pi^{\frac{1}{4}} \sum_{k,j=0}^{\infty} \sqrt{2c_{k}} e^{i \left( \theta^{\ell}_{k} + \psi^{\ell}_{j}\right)} e^{\alpha, \varepsilon_{\ell}}_{k,j} (g), & g= (z,t) \in \Hei.
    \end{align*}
    Then, the finite dimensional distributions of $u_{\alpha}^{N}$ converge in law to the distribution of $\xi_{\alpha,c}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:53:54.856518+00:00","domain":"probability theory","id":"claim_1ce49d7f2cc9c668bc1e84fbc3af59e49e29133aa92af501d058b592d75a41c1","kind":"lemma","schema_version":1,"statement":"[Lemma 8 of arXiv:2607.17030, 'Stationary measures for log-gamma polymer on a strip and in half-space'] Let $-\alpha<u<0$ and $v>u$. 
