{"assumptions":[],"created_at":"2026-10-28T02:16:53.596348+00:00","domain":"probability theory","id":"claim_1d24884f4811b322ed6880c5e90257959ab63d6931cb65a04f3cb6563c94f036","kind":"concept","schema_version":1,"statement":"[Theorem thm:Okura of arXiv:2412.05030, 'Characterization of Subordinate Symmetric Markov Processes'] \begin{enumerate}[(i)]
    \item The Dirichlet form $(\mathcal{E}^S,\mathcal{F}^S)$ is regular.
    \item $\mathcal{F} \subset \mathcal{F}^S$.
    \item $(\mathcal{E}^S,\mathcal{F}^S)$ is pure-jump type and has the following explicit formula
  \begin{equation}
      \mathcal{E}^S(f,g) = \int_{M \times M} (u(x)- u(y))(v(x) - v(y)) J(x,y) d\mu(x)d\mu(y),\quad f,g \in \mathcal{F}^S,
  \end{equation}
  where the jump kernel $J(x,y)$ is 
  \begin{equation}
    J(x,y) = \frac{1}{2}\int_0^\infty p(t,x,y)d\nu(t).
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:44:39.720832+00:00","domain":"probability theory","id":"claim_1d24d908a6e3ed5b2390cd61e3e00417182cad90c30294412cee23648685b660","kind":"concept","schema_version":1,"statement":"[Theorem 4 of arXiv:2608.29747, 'Reduced Khovanov-Rozansky homology'] \cite[attributed to Ocneanu]{Jones1987Hecke}
For each $n \in \N$, there exists a unique $T$-module homomorphism $\mathrm{Tr}_n: \mathrm{H}_n \to \Z[a^{\pm 1}, q^{\pm 1}, \frac{1}{q-q^{-1}}]$ such that
\begin{enumerate}
    \item $\mathrm{Tr}_n (BB') = \mathrm{Tr}_n (B'B)$ for all $B, B' \in \mathrm{H}_n$,
    \item $\mathrm{Tr}_{n+1} (i(B)) = \{0\} \mathrm{Tr}_{n}(B)$ and $\mathrm{Tr}_{n+1} (i(B)B_{n}) = \{1\} \mathrm{Tr}_{n}(B)$ for all $B \in \H_n$, and
    \item $\mathrm{Tr}_{1} (1) = 1$,
\end{enumerate}
where $i : H_n \to H_{n+1}$ is the inclusion map that sends $B_j \mapsto B_j$ for all $j \in \{1, \dots, n-1\}$ and $\{n\} = \frac{aq^{-n}-a^{-1}q^n}{q-q^{-1}}$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:28:04.861365+00:00","domain":"probability theory","id":"claim_1d2bbcabcb8d449e539df5b86321937ba3fa1b92d3f576ff23417e4fb95df008","kind":"lemma","schema_version":1,"statement":"[Lem 37 of arXiv:2511.21496, 'Optimal local central limit theorems on Wiener chaos'] For $j \in \N_0$ and $\varphi \in C_{\mathrm{c}}^{\infty}(\R)$, we define the smooth function 
\begin{equation}
    f_{\varphi^{(j)}}(x) \coloneqq e^{\frac{x^2}{2}}\int_{-\infty}^{x} \left( \varphi^{(j)}(y) - \E\left[\varphi^{(j)}(\cN)\right] \right)e^{-\frac{y^2}{2}}dy.
\end{equation}
Then, $f_{\varphi^{(j)}}$ satisfies 
\begin{equation}
    f_{\varphi^{(j)}}'(x) - xf_{\varphi^{(j)}}(x) = \varphi^{(j)}(x) - \E\left[\varphi^{(j)}(\cN)\right] 
\end{equation}
and 
\begin{equation}
