        \end{eqnarray}
        where $\zeta_{j,\max{}}$ is a solution in $\zeta$ to the following equation:
         \begin{eqnarray}
             \exp(-\zeta)\bigg((1+q_1)x_1^0+\sum_{\ell=2}^{\infty}(1+q_\ell)\bigg[x_1^0\frac{\zeta^{\ell-1}}{(\ell-1)!}\Big(1-\sum_{i=0}^{\ell-1}p_i\Big)\nonumber&&\\
            +\displaystyle\sum_{k=2}^{\ell}\frac{x_k^0}{(\ell-k)!}\zeta^{\ell-k}\prod_{i=k}^{\ell-1}(1-q_i)\bigg]\bigg)&=&1.
         \end{eqnarray}
         Moreover, if either $p_{m+1}\geq\sum_{j=0}^{m}p_j$ for any $m\leq m_0$ and $p_{m}=0$ for any $m\geq m_0+1$ or $p_{m+1}<\sum_{j=0}^{m}p_j$ for any $m\geq2$, the global maximum of the spreader's proportion is also the unique critical point. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:21:10.899123+00:00","domain":"probability theory","id":"claim_1dd2525d2bb063a25d97f8dbc7d2f911d0b10b1d65f9ce8f5236c84adb820ad1","kind":"definition","schema_version":1,"statement":"[Definition 19 of arXiv:2601.16377, '2601.16377'] Given an $H$-tuple $\boldsymbol{\nu}=(\nu_h)_{h = 1}^H$ of nonnegative measures, with $\nu_h$ having support in $[\hat a'_h,\hat b'_h]$ and a density $\nu_h(x)$ with respect to the Lebesgue measure, we define
 \begin{equation}

  \mathcal{I}[\boldsymbol{\nu}]=\sum_{g,h = 1}^{H} \int_{\hat a'_{g}}^{\hat b'_{g}} \int_{\hat a'_{h}}^{\hat b'_{h}} \theta_{g,h}\log|x-y|
 \, \nu_{g}(x)\nu_{h}(y)\dd x \dd y- \sum_{h=1}^{H} \int_{\hat a'_h}^{\hat b'_h} V_h(x) \nu_h(x)\dd x.
 \end{equation}
 whenever the integral in the right-hand side makes sense. We call $-\mathcal{I}$ the energy functional.","status":"unverified"}

