{"assumptions":[],"created_at":"2026-10-27T12:15:15.495651+00:00","domain":"probability theory","id":"claim_1e3738172535ccfbceefa63788f95d87b457178b225792673c6096b1ae1e1593","kind":"definition","schema_version":1,"statement":"[Definition smoothing-kernel of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] For $\varepsilon >0$, let $k_{\varepsilon
}:[0,1]^{2}\rightarrow \lbrack 0,\infty )$ be a continuous kernel such that:

\begin{enumerate}
\item[(i)] \emph{(doubly stochastic)} for every $s,u\in \lbrack 0,1]$, 
\begin{equation}
\int_{0}^{1}k_{\varepsilon }(u,s)\,du=1,\qquad \int_{0}^{1}k_{\varepsilon
}(u,s)\,ds=1;  
\end{equation}

\item[(ii)] \emph{(approximate identity)} for every continuous $
g:[0,1]\rightarrow R$, 
\begin{equation}
\int_{0}^{1}g(s)\,k_{\varepsilon }(u,s)\,ds\longrightarrow g(u)\qquad \text{
uniformly in }u\in \lbrack 0,1]\ \text{as }\varepsilon \downarrow 0;

\end{equation}

\item[(iii)] \emph{($\mathrm{TP}_{2}$)} the kernel $k_{\varepsilon }$ is 
\textit{totally positive of order two}: for all $u_{1}\leq u_{2}$ and $
s_{1}\leq s_{2}$, 
\begin{equation}
k_{\varepsilon }(u_{1},s_{1})\,k_{\varepsilon }(u_{2},s_{2})\geq
k_{\varepsilon }(u_{1},s_{2})\,k_{\varepsilon }(u_{2},s_{1}).  
\end{equation}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:32:58.302817+00:00","domain":"probability theory","id":"claim_1e3c6b94218a471d29290051529e4157d4a5d576e54deebf484c0e1c8856da2c","kind":"concept","schema_version":1,"statement":"[Lemma lem:two-point_local_time_estimate of arXiv:2505.10256, 'Stochastic Oscillators out of equilibrium:\\ scaling limits and correlation estimates'] There exists a constant $C=C(T)>0$ such that  
