 \end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:43:18.714394+00:00","domain":"probability theory","id":"claim_1e48d819b44e6202a4ddc8d5c389046472b0d7c8aa9c7b4006202b0ebfc72309","kind":"definition","schema_version":1,"statement":"[Defi shuffle_trees of arXiv:2609.02346, 'Regularised double shuffle relations for planar \AZVs{}'] Let $\Omega$ be a set. Let us define for any pair of trees $(S,T)$ in $\text{PT}_\Omega\times \text{PT}_\Omega$ the products $S<T$ and $S>T$ (and also $S\shuffle^T T:=S<T+S>T$) inductively on $|S|+|T|$. 
    \begin{enumerate}
	   \item $S<T$. If $S$ has only one vertex, we can assume  $S = \begin{picture}(10,5)(-2,-1)
\put(0,0){\circle*{2}}
\put(2,-2){$\tiny x$}
\end{picture}$. Then we set
	   \begin{equation} 
	    \begin{picture}(10,5)(-2,-1)
\put(0,0){\circle*{2}}
\put(2,-2){$\tiny x$}
\end{picture}<T \coloneqq B_+^x(T).
	   \end{equation}
       If $S$ does not have only one vertex, we can assume $S=B_+^x(S_1\cdots S_k)$. Then we set
       $$S<T \coloneqq B_+^x(S_1\cdots(S_k\shuffle^T T)).$$
	   \item $S>T$. If $T$ has only one vertex, we can assume $T = \begin{picture}(10,5)(-2,-1)
\put(0,0){\circle*{2}}
\put(2,-2){$\tiny y$}
\end{picture}$. Then we set
	   \begin{equation} 
	    S>\begin{picture}(10,5)(-2,-1)
\put(0,0){\circle*{2}}
\put(2,-2){$\tiny y$}
\end{picture} \coloneqq B_+^y(S).
	   \end{equation}
       If $T$ does not have only one vertex, we can assume $T=B_+^y(T_1\cdots T_\ell)$. Then we set
       $$S>T := B_+^y((S\shuffle^T T_1)\cdots T_\ell).$$
	  \end{enumerate}
	 We then extend these products by bilinearity to products on $\mathcal{PT}_\Omega$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:36:49.912286+00:00","domain":"probability theory","id":"claim_1e49a42952a98d492e0a66090b99d933175fe7f44ce8c3143be04ff540403708","kind":"concept","schema_version":1,"statement":"[Theorem thm:main of arXiv:2609.01557, '$L^\infty$ Variational Approximation of the Aubry Set'] Assume that \(H\in C^\infty(\mathbb R^n\times\mathbb T^n)\) is a periodic Tonelli Hamiltonian.  Let \(u_k\) be the normalized minimizers of (equation eq:Ik of the paper), and let \(u_\infty\) be a uniform subsequential limit. 
