{"assumptions":[],"created_at":"2026-10-27T13:47:12.037665+00:00","domain":"probability theory","id":"claim_1e58351c7c4f0dbb9eef09bbf57fd266aaafc8ecf70251655f88d6be35dbc20f","kind":"definition","schema_version":1,"statement":"[Definition def-transport-weak-1 of arXiv:2512.17727, 'Stochastic transport equation with L\'evy noise'] Assume that  $b\in L_{loc}^{1}(\mathbb{R}^{d};\mathbb{R}^{d})$ satisfies $\operatorname{div}\,b\in L_{loc}^{1}(\mathbb{R}^{d})
$.  If  $u_{0}\in L^{\infty }(\mathbb{R}^{d})$ then 
a weak$^\ast$-$\mathrm{L}^{\infty}$-solution to the stochastic transport equation problem (equation eqn-transport-strong of the paper)
is a  
{measurable and essentially bounded}  stochastic process 
\begin{equation}
u:
 [0,T]\times\mathbb{R}^d\times \Omega \to \mathbb{R}
\end{equation}
in the sense that 
{ for some $M>0 $, 
  \begin{align}
    \sup_{t\in[0,T]}\| u( t,  \cdot,\omega) \|_{L^\infty(\mathbb{R}^d)} \leq M,\quad\mathbb{P}\text{-a.s.}
\end{align}
 (cf. (equation eq-esb03 of the paper))} and the following two conditions are satisfied. 
 \begin{trivlist}
 \item[(ds1)] For every test function $\theta\in C_c^{\infty}(\mathbb{R}^d)$, the process 
 $u_{\cdot}(\theta):  [0,T]\times \Omega \to \mathbb{R}$ defined by 
 \begin{equation}
u_{t}(\theta)=\int_{\mathbb{R}^d}\theta(x)u(t,x)\,dx, \;\; t \in [0,T], 
\end{equation}
   is $\mathbb{F}$-adapted and c\`{a}dl\`{a}g,  $\mathbb{P}$-almost surely. 
  \item[(ds2)] For every test function $\theta\in C_c^{\infty}(\mathbb{R}^d)$, for every $t \in [0,T]$, the following identity is satisfied $\mathbb{P}$-almost surely, 
\begin{equation}
