       \int_{\mathbb{R}^d}u(t,x)\,\theta(x)\,dx=&\int_{\mathbb{R}^d}u_{0}(x)\,\theta(x)\,dx+\int_0^t\int_{\mathbb{R}^d}u(s,x)\,[b(x)\cdot  D\theta(x)+\operatorname{div}\, b(x)\,\theta(x)]\,dx\,d s\nonumber\\
       &+\sum_{i=1}^d\int_0^t\Bigl( \int_{\mathbb{R}^d}u(s-,x)D_i\theta(x)\,dx      \Bigr)\diamond d L_s^i.
       \end{aligned}
\end{equation}
