{"assumptions":[],"created_at":"2026-10-28T02:10:43.768535+00:00","domain":"probability theory","id":"claim_1e5ab2f0eae799c6a09c3ae8c6c351c581c8312e8257f14e2d5ce57b64685d79","kind":"lemma","schema_version":1,"statement":"[Lemma yesno of arXiv:2412.04284, 'Approximately jumping towards the Origin'] Let $k \equiv -1$ modulo 8. If $z_k$ exists, $z_{k+2} \neq z_k$, and $z_{k+4}=z_{k+2}$, then:
    \begin{itemize}
        \item[1.] If $|z_k|<2$ then $|z_{k+4}|<\sqrt{2}$.
        \item[2.] If $2\leq |z_k|\leq \sqrt{5}$ then $|z_{k+4}|< \sqrt{8(1-\sqrt{3}/2)}$.
        \item[3.] If $|z_k|>\sqrt{5}$ then $|z_k|>|z_{k+4}|+\sqrt{5}-1$.
    \end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:32:56.073650+00:00","domain":"probability theory","id":"claim_1e6023f442475071bb24c398b6d2a16ce4bfe84786dc3a9b6ea9fda420b6c97c","kind":"theorem","schema_version":1,"statement":"[Proposition prop:modulus-both-U of arXiv:2411.12192, 'Sample path properties and small ball probabilities for stochastic fractional diffusion eq'] Assume the conditions of Lemma (le:sLND-U of the paper) hold.  Let  $I=[-M,M]^{d+1}$ with $0<M<\infty$ and let   $\rho(t,x)=|t|^{\theta_1}+|x|^{\theta_2}$.
  \begin{enumerate}
    \item (Uniform modulus of continuity). There exists a constant $k_1\in(0,\infty)$ such that
    \begin{equation*}
      \lim_{\varepsilon\to0^+}\sup_{\substack{(t,x),(s,y)\in I;\\ \rho(t-s,x-y)\le\varepsilon}}\dfrac{|U(t,x)-U(s,y)|}{\rho(t-s,x-y)\sqrt{\log\left(1+\rho(t-s,x-y)^{-1}\right)}}=k_1,
      \text{ a.s. }
    \end{equation*}
    \item (Local modulus of continuity). There exists a constant $k_2\in(0,\infty)$ such that for any $(t,x)\in I$,     \begin{equation*}
      \lim_{\varepsilon\to0^+}\sup_{\rho(s,y)\le \varepsilon} \dfrac{|U(t+s,x+y)-U(t,x)|}{\rho(s,y)\sqrt{\log\log\left(1+\rho(s,y)^{-1}\right)}}=k_2,
      \text{ a.s. }
    \end{equation*}
   \item (Chung's LIL). There exists a constant $k_3\in(0,\infty)$ such that for all $(t,x)\in I$,
  \begin{equation*}
    \liminf_{\varepsilon\to0^+}\sup_{\rho(s,y)\le \varepsilon} \dfrac{|U(t+s,x+y)-U(t,x)|}{\varepsilon\left(\log\log 1/\varepsilon\right)^{-1/Q}}=k_3, \text{ a.s. }
  \end{equation*}
  where $Q=\frac{1}{\theta_1}+\frac{d}{\theta_2}$.
  \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:33:17.689108+00:00","domain":"probability theory","id":"claim_1e680ceb65e6b95e3a1746775f3dc017d2f156aa982c242775cd39e53e11c43d","kind":"lemma","schema_version":1,"statement":"[Lemma 4 (Compact-support continuity upgrade) of arXiv:2607.10813, '2607.10813'] Let $K\Subset\R^3$, let $\alpha,\beta,r\in\R$ with $r<\beta$, and suppose
$f:[0,T]\to\mathcal S'(\R^3)$ satisfies
\begin{equation}
