\ensuremath{\mathsf{Q}_{\scaleto{\textsf{IGC}\xspace}{4pt}}}(\eta, \xi) \, d\xi \, d\eta \qquad \mbox{where $\lambda(r) =
  \log(r/(1-r))$.}
