{"assumptions":[],"created_at":"2026-10-27T20:50:48.852760+00:00","domain":"probability theory","id":"claim_1e758f10d6cd483c238c172121d991eecd09f7a174d4a056ce130280ac0ca3f6","kind":"theorem","schema_version":1,"statement":"[Theorem thm:stat.dist.alpha>0.beta>lambda0 of arXiv:2607.10708, 'A class of Markov processes with resetting and applications to cybersecurity'] Let $X=(N,\Lambda,C)$  be a self-exciting PDMP with resetting and $Y=(N,\Lambda)$. Under Assumption (a:finitereset of the paper) holds and with $\alpha>0\ \&\  \beta>{\lambda^o}$, $Y$ has invariant measure $\Pi$ on $\mathbb N_0\times[{\lambda^o}, A)$, given by the following:

\begin{equation} 
    \Pi(n, d\lambda)=\pi(n,\lambda)d\lambda 

\end{equation}
    whose density is defined as

\begin{equation} 
  \begin{split}
    \pi(0,\lambda)=&\mathds{1}_{\{\lambda <\beta\}}\frac{K_0}{\alpha  (\beta -{\lambda^o})} \left(\frac{\beta -\lambda }{\beta -{\lambda^o}}\right)^{\frac{\beta -\alpha }{\alpha }} e^{\frac{\lambda - {\lambda^o}}{\alpha}},\\
    \pi(n,\lambda)=&\mathds{1}_{\{\lambda<\beta\}}\frac{1}{F(\lambda)}\int_{{\lambda^o}}^{\lambda} \frac{F(y)p(n-1,y)}{\alpha(\beta-y)}dy\\
    &+\mathds{1}_{\{\lambda\geq \beta\}}\frac{1}{F(\lambda)}\int_{\lambda}^{A} \frac{F(y)p(n-1,y)}{\alpha(y-\beta)}dy, \quad n\geq 1.
  \end{split}

\end{equation}
  For $n\ge 0$, 

\begin{equation} 
    p(n,\lambda) = \int \mathds{1}_{\{u+{\lambda^o}<\lambda\}} (\lambda-u) \pi(n,\lambda-u)\,dG_{\ell}(n+1, u),

\end{equation}

\begin{equation} 
    F(\lambda)=\exp(-\frac{\lambda}{\alpha})|\lambda-\beta|^{\frac{\alpha-\beta}{\alpha}},

\end{equation}
  and $K_0=\sum_{n=1}^\infty \int_{[{\lambda^o},A)} \lambda \bar{G}_{\ell}(n, (A-\lambda) \textrm{-}) \Pi(n-1, d \lambda)$.","status":"unverified"}

