{"assumptions":[],"created_at":"2026-10-27T16:38:11.778790+00:00","domain":"probability theory","id":"claim_1ea07b99c414d58455efc9410e5f54cbc06269b25ca55a8d607a2b87dddbb8b8","kind":"concept","schema_version":1,"statement":"[Theorem Théorème Survie forte et faible sur Td of arXiv:2504.03627, 'Richardson’s model and the contact process with stirring: long time behavior.'] \begin{enumerate}
    \item Let $\lambda>0$ and $(\xi_t)_{t\ge 0}$ be $\mathrm{RMS}(\lambda,1)$ on the homogeneous tree $T_d$. There exists $\lambda_s^{\mathrm{RMS}}(d)>0$ such that:
    \begin{itemize}
        \item if $\lambda>\lambda_s^{\mathrm{RMS}}(d)$, then the $\mathrm{RMS}(\lambda,1)$ survives strongly,
        \item if $0<\lambda<\lambda_s^{\mathrm{RMS}}(d)$, then the $\mathrm{RMS}(\lambda,1)$ survives weakly but does not survive strongly.
    \end{itemize}
    Moreover, we have:
    \begin{align}
        \frac{d+1}{2\sqrt{d}}-1\le\lambda_s^{\mathrm{RMS}}(d)\le\frac{d+1}{\sqrt{d}-1}. 
    \end{align} 
    \item Let $\lambda,\nu>0$ and $(\xi_t)_{t\ge 0}$ be a $\mathrm{CPS}(\lambda,1,\nu)$. There exists $\lambda_s^{\mathrm{CPS}}(d,\nu)>0$ such that:
    \begin{itemize}
        \item if $\lambda>\lambda_s^{\mathrm{CPS}}(d,\nu)$, then the $\mathrm{CPS}(\lambda,1,\nu)$ survives strongly,
        \item if $0<\lambda<\lambda_s^{\mathrm{CPS}}(d,\nu)$, then the $\mathrm{CPS}(\lambda,1,\nu)$ does not survive strongly,
    \end{itemize}
    and we have 
    \begin{align}
        \nu\left(\frac{d+1}{2\sqrt{d}}-1\right)\le\lambda_s^{\mathrm{CPS}}(d,\nu)\le \frac{(d+1)\nu+1}{\sqrt{d}-1}.
    \end{align}
    Moreover:
    \begin{itemize}
        \item For all $(d,\nu)$ in 
    $$W=\left\{(d,\nu)\in \llbracket 2,+\infty\llbracket \times (0,+\infty)~:~\nu\left(\frac{d+1}{2\sqrt{d}}-1\right)-\frac{(d+1)\nu+1}{d-1}> 0\right\},$$
    there exist infection rates $\lambda>0$ such that $\mathrm{CPS}(\lambda,1,\nu)$ survives weakly, but not strongly.
        \item The set $W$ is non-empty if and only if $d\ge 17$.
    \end{itemize}
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:19:06.721730+00:00","domain":"probability theory","id":"claim_1ea0ae358e37584eb81de78ce62dfa2e6243463f9aabcd3275b9fb382501dc00","kind":"concept","schema_version":1,"statement":"[Theorem thm2.2 of arXiv:2606.01944, 'Propagation of Chaos for Mean-field Mean Reflected Backward Stochastic Differential Equati'] Under Assumptions (H1)-(H4), the mean-field mean reflected BSDE associated with $(\xi,f,h)$ admits a unique solution $(Y,Z,K)\in \mathcal{S}^2\times\mathcal{H}^2\times I[0,T]$. Moreover, for each $t\in[0,T]$, we have 
 \begin{align*}
     K_T-K_t=\sup_{s\in[t,T]}L_s(\bar{Y}_s), 
 \end{align*}
 where
 \begin{align*}
\bar{Y}_s:=\mathsf{E}\left[\xi+\int_s^T f(r,Y_r,\mathsf{E}[Y_r],Z_r,\mathsf{E}[Z_r])ds\Big|\mathcal{F}_s\right].
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:36:04.990695+00:00","domain":"probability theory","id":"claim_1ea33c84428bd863a81e15f420a460c9f6cf406d958a6cff9c0326c8876f1e30","kind":"theorem","schema_version":1,"statement":"[Theorem 17 of arXiv:2604.00882, 'On some extensions of generalized counting processes'] The probabilities ${p}^{\alpha,\rho}_n(t)=\Prob\{N(\mathcal{L}^{\alpha,\rho}(t))=n\}$ satisfy the following  equation
	\begin{equation}
		\left({\mathcal D}^{2\alpha,\rho}_t + {\mathcal D}^{\alpha,\rho}_t\right) p_n^{\alpha,\rho}(t) = -\lambda(p_n^{\alpha,\rho}(t) - p_{n-1}^{\alpha,\rho}(t)), \quad n \ge 0,
	\end{equation}
	with the standard initial condition, and  the probability generating function $
	{G}_{\alpha,\rho}(u, t)$, $|u| \leq 1$, solves the equation
	\begin{equation*}
		\left({\mathcal D}^{2\alpha,\rho}_t + {\mathcal D}^{\alpha,\rho}_t\right) G_{\alpha,\rho}(u, t) = \lambda(u - 1)G_{\alpha,\rho}(u, t), 
	\end{equation*}
	with $G_{\alpha,\rho}(u, 0) = 1$; the generalized fractional derivatives  in the C-D sense are defined in \eqref{exfDt}.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:26:20.445899+00:00","domain":"probability theory","id":"claim_1ea8d8391a8baab5e91c8a1939109929528864767f6aa000b59066353a27bd8d","kind":"definition","schema_version":1,"statement":"[Defn embedded-map of arXiv:2411.11676, 'Surface sums for lattice Yang--Mills in the large-$N$ limit'] An \textbf{embedded map} is a pair $M = (m,\psi)$ where
\begin{enumerate}
	\item $m=\{m_1,\dots,m_r\}$ is a multiset of $r$ maps (with or without boundary and of any genus) with the following two properties (see the top of Figure~(fig-embedded-maps-exemp of the paper)):
	\begin{enumerate}
		\item[(1a)] The dual graph of each component of $m$ is bipartite. The faces of $m$ in one partite class are called \textbf{blue faces} and those in the other class are called \textbf{yellow faces}.
		\item[(1b)] The external faces of each component of $m$ with boundary are yellow faces.
	\end{enumerate}
	We call a multiset of maps (with or without boundary and of any genus) with these two properties a \textbf{YB-bipartite maps family}.
	\item $\psi:m \to \Lambda$ is a graph homomorphism  with the following two properties (see the bottom of Figure~(fig-embedded-maps-exemp of the paper)):
	\begin{enumerate}
		\item[(2a)] $\psi$ sends each internal yellow face of $m$ isomorphically to an unoriented plaquette of $\Lambda$,
		\item[(2b)] $\psi$ sends each blue face of $m$ to a single unoriented edge of $\Lambda$.
	\end{enumerate}
	We call a graph homomorphism $\psi:m \to \Lambda$ with these two properties a \textbf{lattice embedding} of $m$.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:38:36.828791+00:00","domain":"probability theory","id":"claim_1ea90d770eaa6a57661259393b090a87aa4076db06bc410890a2f23e2ae20746","kind":"theorem","schema_version":1,"statement":"[Theorem thm:discrete-bound of arXiv:2606.28869, '\bfseries A General Theory of Paths:\\ \large Signatures, Jump Lifts, and Expected Signatu'] Equip $T^{(m)}(\mathbb{R}^d)$ with the projective tensor norm summed over levels. Let
\begin{equation}
V=\sum_{i=1}^n\left\lVert z_i\right\rVert,
\qquad
\delta=\max_i\left\lVert z_i\right\rVert.
\end{equation}
Then
\begin{equation}
\norm{S_m^{\rm PL}(z)-S_m^{\rm disc}(z)}
\le
\exp(2V)\sum_{i=1}^n\sum_{k=2}^{m}\frac{\left\lVert z_i\right\rVert^k}{k!}.
\end{equation}
If $\delta\le 1$, then
\begin{equation}
\norm{S_m^{\rm PL}(z)-S_m^{\rm disc}(z)}
\le
\exp(2V+1)\,\delta V.
\end{equation}
In particular, for increments of a Lipschitz path sampled on a mesh of size $\Delta$, with $\left\lVert z_i\right\rVert\le L\Delta$, the error is $O(\Delta)$ at fixed total variation.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:17:33.999726+00:00","domain":"probability theory","id":"claim_1eabe3067721184da25bb16765fab390099fd0fb5011cd876542fb8e0afb8eaa","kind":"theorem","schema_version":1,"statement":"[Theorem 39 of arXiv:2609.03403, 'Hyperpositive functions, sector bounded functions and a trace formula'] Let $F\in\mathcal{HP}_{T,t}$ with representation \eqref{repre-321-11}, and let $\mathfrak H(K)$ denote the reproducing kernel Hilbert space with reproducing kernel
