{"assumptions":[],"created_at":"2026-10-28T00:55:42.214548+00:00","domain":"probability theory","id":"claim_1eb6892827cb4396bd3bff2c02ef1e78d28252c56c8403e14483f37263ce701d","kind":"concept","schema_version":1,"statement":"[Lemma lem:asympbiasvar of arXiv:2411.16366, 'Connections between sequential Bayesian inference and evolutionary dynamics'] \textbf{Steady state Bias-Variance}. Suppose assumptions (ass:Astable of the paper) and (ass:eigsymmA of the paper) holds along with $\mathbb{E}[\varepsilon_0] = 0$ and $C_0 = C_\infty$ where $C_\infty$ satisfies
\begin{align}

	0 = GC_\infty + C_\infty G^\top + \Sigma -rC_\infty H^\top \Xi^{-1} H C_\infty.
\end{align}
For $\nu_t, E_t$ as defined in (equation eq:defnnut of the paper) and (equation eq:defnEt of the paper) respectively,  $\nu_t \rightarrow \nu_\infty$ and $E_t \rightarrow E_\infty$ as $t \rightarrow \infty$, where
\begin{align}

	\nu_\infty &= \| A_\infty^{-1} b \|^2 \\


	E_\infty &=  \text{Tr}\left[ (\Sigma + (r-s) \left( G - A_\infty \right)C_\infty  - 2A_\infty^{-1} b b^\top) X_\infty \right] \\

    & \leq -\frac{1}{\alpha(A_\infty + A_\infty^\top)} \left( - 2 \text{Tr}[A_\infty^{-1}b b^\top] + \text{Tr}[\Sigma] + (r-s)^2 \alpha(H^\top \Xi^{-1}H) \|C_\infty\|_F\right)
\end{align}         
where $X_\infty$ is the unique solution of the Lyapunov equation  
\begin{align*}
	A_\infty^\top X_\infty + X_\infty A_\infty + I = 0.  
\end{align*}
In the scalar case $m=n=1$, $\nu_\infty$ and $E_\infty$ can be characterised entirely in terms of the system parameters $G, H, \Sigma, \Xi, b$, 
\begin{align}

	\nu_\infty &= \left(\frac{b}{A_\infty(r,s)} \right)^2 \\

	E_\infty = \tilde{P}_\infty &=  - \frac{1}{2}\left(\Sigma + \left( \frac{G - A_\infty(r,s)}{H} \right)^2 \Xi  \right)  \frac{1}{A_\infty(r,s)}  + \left(\frac{b}{A_\infty(r,s)} \right)^2
\end{align}
where 
\begin{align}

	A_\infty(r,s) &=  \frac{s}{r} G + \frac{(r-s)}{r} A_\infty(r,0) \\
	A_\infty(r,0) &= -\sqrt{G^2 + rH^2 \Xi^{-1} \Sigma}.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:25:12.186880+00:00","domain":"probability theory","id":"claim_1eb74cb427407b4c1894b93609662fdf5926b7f4e81cf487fa805b906f31435f","kind":"lemma","schema_version":1,"statement":"[Lemma 19 of arXiv:2510.20492, 'Heterochromatic two-arm probabilities for metric graph Gaussian free fields'] For any $d\ge 3$ and $v_1,v_2,v_3\in \widetilde{\mathbb{Z}}^d$ with $|v_i-v_j|\ge d$ for all $i\neq j$, 
	\begin{equation}
		\bar{\mathbf{e}}_{v_1,v_2}(\{\widetilde{\eta}: v_3\in \mathrm{ran}(\{\widetilde{\eta}) \}) \lesssim \tfrac{|v_1-v_3|^{2-d}|v_3-v_2|^{2-d}}{|v_1-v_2|^{2-d}}. 
	\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:23:25.622669+00:00","domain":"probability theory","id":"claim_1eb852377b805288e4e8c071b6c06a64076ab37ec498021af07c76499a825b7e","kind":"concept","schema_version":1,"statement":"[Thm main of arXiv:2609.01250, 'Global regularity for 2D gravity water waves with two retreating point vortices'] Let $s\in\mathbb{N}$, $s\geq 10$. There exist $\epsilon_0>0$ and $\lambda_0>0$ sufficiently small such that for all $0<\epsilon\leq\epsilon_0$ and $0<\lambda\leq\lambda_0$, if the initial data satisfy the condition above and
  \begin{equation}
    \left\lVertv_0\right\rVert_{H^{s+1/2}}+\left\lVertz_0-\alpha\right\rVert_{\dot{H}^{1/2}\cap \dot{H}^{s+1}} +\norm{\alpha\partial_{\alpha}v_0}_{H^{s-1/2}}+\norm{\alpha\partial_{\alpha}\partial_{\alpha}\xi_0}_{H^{s-1}}   \le \epsilon,
  \end{equation}
   the point vortex strengths and $H_0$ satisfy 
  \begin{equation}
      \frac{\lambda}{c_sH_0^\frac{1}{2}}\leq\epsilon\leq c_s\lambda H_0^{\frac{1}{4}},\quad c_sH_0^{\frac{1}{2}}\geq1
  \end{equation}
  where $c_s$ is a small constant dependent on $s$, then the water wave system with point vortices is globally well-posed. Moreover,
  \begin{equation}
    \sup_{t\ge 0}\bigl(\left\lVertz_t\right\rVert_{H^{s+1/2}}+\left\lVertz-\alpha\right\rVert_{\dot{H}^{1/2}}+ \norm{z_{\alpha}-1}_{H^s}+\norm{z_{tt}}_{H^s}\bigr)\leq C\epsilon,
\end{equation}
and for all $t\geq 1$,
\begin{equation}
   \norm{z_{\alpha}(\cdot,t)-1}_{W^{s-2,\infty}}+ \norm{z_{tt}(\cdot,t)}_{W^{s-2,\infty}}+\norm{\partial_{\alpha}z_t}_{W^{s-3,\infty}}\leq C\epsilon \langle t\rangle^{-1/2}.
\end{equation}
  Furthermore, the distance between the point vortices and the free surface satisfies
  \begin{equation}
    \operatorname{dist}(z_j(t), \Sigma(t)) \ge c\,(H_0+\lambda t),\qquad j=1,2,
  \end{equation}
  for some constants $c,C>0$ independent of $\epsilon$, $\lambda$, $H_0$ and $t$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

