\end{equation}
 and if $\sqrt{2 \theta \kappa}>{\pi}$, by
\begin{equation}
 \mu(x)= \left\{\begin{array}{lll}
 \dfrac{1}{\theta} & & |x| \leq \alpha \\[10pt]
  \dfrac{2 \sqrt{(\beta^2 - x^2)(x^2 - \alpha^2)}}{\pi \theta \beta |x|}\,\Pi_1\bigg[-\dfrac{\alpha^2}{x^2}\,;\,\mathsf{k}\bigg] & & |x| \in (\alpha,\beta) \\[10pt]
  0& & |x|\geq \beta \end{array}\right. ,
\end{equation}
 where $\beta$ and $\mathsf{k} = \frac{\alpha}{\beta}$ are determined by the system of two equations:
