    \end{matrix}\right)K}\right\}_{m \geq n}
    \]
    of $\mathcal{H}$ and the basis of $\mathbb{C}[\alpha^{\pm1},\beta^{\pm1}]^{S_2}$ given by 
    \[
    \left\{\tau_{m+n,n}(\alpha, \beta) = \alpha^n \beta^n \left( \alpha^m + \alpha^{m-1}\beta + \cdots + \beta^m \right)\right\}_{m, n \in \mathbb{Z}_{\geq 0}}
