    \end{equation}

\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:21:28.750257+00:00","domain":"probability theory","id":"claim_1ff4c13b40c294f91fc534c9a6aef5fe2c56613ebca9bfd8058e39d1b11f34c1","kind":"concept","schema_version":1,"statement":"[Lemma lem:sa of arXiv:2605.03718, 'Potential Hessian Ascent III:\\ Sampling the Sherrington--Kirkpatrick Model at $\beta < 1/'] {koehler2022sampling}, cf. [dyer1991computing]}]

Let $0<\varepsilon<1$. Suppose that $p_\ell, 1\leqslant\ell\leqslant M+1$ are distributions on $\Omega$, and that in \pref{alg:sa} we are given sampling oracles for $\widetilde p_\ell$, $1\leqslant \ell\leqslant M$ such that the following hold for each $1\leqslant \ell \leqslant M$.
\begin{enumerate}
    \item (Variance bound) $\fc{\mathop{{}\boldsymbol{\mathrm{Var}}}_{P_\ell}(g_\ell(x))}{(\mathop{{}\mathbb{E}}_{P_\ell} g_\ell(x))^2} \leqslant \sigma^2$.
    \item (Bias bound) $\ab{\mathop{{}\mathbb{E}}_{P_\ell}g_\ell(x) - \mathop{{}\mathbb{E}}_{\widetilde P_\ell}g_\ell(x)}\leqslant \fc{\varepsilon}{4M}$.
\end{enumerate}
Then taking $N\geqslant \fc{320\sigma^2 M}{\varepsilon^2}$ and $R\geqslant 32 \log  \prc\delta$, with probability $1-\delta$, the output $\widehat Z$ satisfies $\widehat Z\in [e^{-\varepsilon}, e^{\varepsilon}] \cdot Z$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

