{"assumptions":[],"created_at":"2026-10-27T14:38:23.594915+00:00","domain":"probability theory","id":"claim_204bf6149c128f7755a3f4d55dd4f836fa5b61244699d3adf5df6f2e72a1636e","kind":"theorem","schema_version":1,"statement":"[Theorem th4.1 of arXiv:2511.07173, '\bf Mean-field backward stochastic Volterra integral equations: well-posedness and related'] \rm

Let (ass3.1 of the paper) be in force and $g$ is Lipschitz continuous with respect to  $(\mu,\nu)$ in 1-Wasserstein distance.
Let $(Y^{N,i}(\cdot),Z^{N,i,j}(\cdot,\cdot))_{1\leqslant j\leqslant N}$, $(\overline{Y}^{i}(\cdot),\overline{Z}^i(\cdot,\cdot))$ be the solutions of   Eq. ((1.3 of the paper)) and  Eq. ((5.2 of the paper)), respectively. Then,  for  $1<p<2$,
\begin{equation*}
		\begin{aligned}
			&\ \mathbb{E}\bigg[\int_0^T|  Y^{N,i}(t)- \overline{Y}^i(t)|^pdt

			+ \int_0^T\(\int_t^T \sum\limits_{j=1}^N|Z^{N,i,j}(t,s)- \delta_{ij}\overline{Z}^i(t,s)|^2ds\)^\frac{p}{2} dt\bigg] \nonumber\\
			   &\leqslant C  \mathbb{E}\int_0^T  {\cal W}_p^p(\mu^N(t), \overline{\mu}(t))dt
              +C  \mathbb{E}\int_0^T\int_t^T{\cal W}_p^p(\nu^N(t,r), \overline{\nu}(t,r))drdt.
		\end{aligned}
	\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:59:45.007926+00:00","domain":"probability theory","id":"claim_2051b2deb18c3f6b536b94e66d4cd32543e6f57bb41b89c255ee6d2737a41002","kind":"concept","schema_version":1,"statement":"[Theorem main left soft edge2 of arXiv:2605.12777, 'Mesoscopic Rates of Convergence for Complex Wishart Matrices at the Leftmost Spectrum Edge'] Consider an LUE $L_{a,N}$ such that $\lim\limits_{N\rightarrow\infty}\frac{N}{n}=\gamma\in(0,1)$ where $n=N+a$. On any $A\subset[s_0,+\infty)$ for $s_0>-\infty$. Define parameters:
    \begin{equation*}
      \begin{array}{ll}
      \mu_{k,m}:=\left(\sqrt{k+\frac{1}{2}}-\sqrt{m+\frac{1}{2}}\right)^2,\\
      \sigma_{k,m}:=\left(\sqrt{k+\frac{1}{2}}-\sqrt{m+\frac{1}{2}}\right)\left(\left(m+\frac{1}{2}\right)^{-\frac{1}{2}}-\left(k+\frac{1}{2}\right)^{-\frac{1}{2}}\right)^{\frac{1}{3}}.
      \end{array}
    \end{equation*}
    Let $G_\tau=\xi_\tau$, $H_\tau=-\eta_\tau$ be kernels defined in (equation left soft kernel of the paper) and $\tau$ be the scaling with respect to
\begin{equation*}
    \tilde{\mu}_{n,N}=\left(\frac{1}{\sqrt{\sigma_{n-1,N}}}+\frac{1}{\sqrt{\sigma_{n,N-1}}}\right)\left(\frac{1}{\mu_{n-1,N}\sqrt{\sigma_{n-1,N}}}+\frac{1}{\mu_{n,N-1}\sqrt{\sigma_{n,N-1}}}\right)^{-1},
\end{equation*}
\begin{equation*}
    \tilde{\sigma}_{n,N}=\left(\frac{\sqrt{\sigma_{n-1,N}}}{\mu_{n-1,N}}+\frac{\sqrt{\sigma_{n,N-1}}}{\mu_{n,N-1}}\right)\left(\frac{1}{\mu_{n-1,N}\sqrt{\sigma_{n-1,N}}}+\frac{1}{\mu_{n,N-1}\sqrt{\sigma_{n,N-1}}}\right)^{-1}.
\end{equation*}
Then, for large $N$ and $t\in A$,
   \begin{equation}
\begin{array}{ll}
  |G_{\tau}(t)+H_{\tau}(t)+(-1)^{N+1}\sqrt2 Ai(t)|\le N^{-\frac{2}{3}}C(s_0,\gamma)e^{-\frac{t}{2}},\\
  \\
  \left|G_{\tau}(t)+(-1)^{N+1}\frac{\sqrt2}{2} Ai(t)\right|\le N^{-\frac{1}{3}}C(s_0,\gamma)e^{-\frac{t}{2}},\\
  \\
  \left|H_{\tau}(t)+(-1)^{N+1}\frac{\sqrt2}{2} Ai(t)\right|\le N^{-\frac{1}{3}}C(s_0,\gamma)e^{-\frac{t}{2}}.
\end{array}
\end{equation}
Furthermore, for any fixed $\gamma$, $C(s_0,\gamma)$ is non-increasing with respect to $s_0$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:49:05.413424+00:00","domain":"probability theory","id":"claim_2053d3282017c1d2d8edde1b3505d97bc3525bc18390c8aa10b2984997aa465a","kind":"lemma","schema_version":1,"statement":"[Lemma of arXiv:2601.07808, 'Supercritical long-range percolation on graphs of polynomial growth: the truncated one-arm'] \label[lemma]{lem:block_connectivity}
