{"assumptions":[],"created_at":"2026-10-26T20:24:30.013967+00:00","domain":"probability theory","id":"claim_20f1a64b1fee0dab6ba1e7517ea25d2f1ee4deffc140bb09235adadd761044ff","kind":"concept","schema_version":1,"statement":"[Theorem 4 ({\cite[Theorem 2.6) of arXiv:2605.04684, 'Ergodicity of stochastic functional differential equation with jumps and finite delay'] {Butkovsky2020}}]
 Assume that the Markov {semigroup $(P_t)$ is Feller}. Suppose that:
\begin{enumerate}
\item [1.] There exists a measurable function $V: \mathscr{D} \rightarrow[0, \infty)$ which satisfies the Lyapunov condition, that is, there exist a concave differentiable function $f: \mathbb{R}_{+} \rightarrow \mathbb{R}_{+}$ increasing to infinity with $f(0)=0$ and a constant $K>0$ such that for any $t \geq 0, \xi \in \mathscr{D}$,
\begin{equation*}
    P_{t} V(\xi) \leq V(\xi)-\int_{0}^{t} P_{s}(f \circ V)(\xi) \d s+K t.
\end{equation*}

\item[2.] For any $f,g\in\mathscr{D}$, $d(f,g)\wedge 1 \leq \|f-g\|_{\infty}$.

\item[3.] Condition \ref{C1} holds for functions $r, L$.

\item [4.]There exists $t_{0}>0$ such that for any $M>0$, Condition \ref{C2} holds for  $B=\{V \leq M\}$ and $t_{0}$.
\end{enumerate}
Then the Markov semigroup $(P_{t})$  has a unique invariant measure $\pi$. Moreover, for any $\delta \in(0,1)$ there exist constants $C_{1}, C_{2}>0$ such that for any $\xi \in \mathscr{D}$,
\begin{equation}
    W_{d \wedge 1}\left(P_{t}(\xi, \cdot), \pi\right) \leq \frac{C_{1}\left(1+f(V(\xi))^{\delta}\right)}{f\left(F^{-1}\left(C_{2} t\right)\right)^{\delta}}, \quad  t \geq 0,
\end{equation}
where $F(x)$ is defined by
\begin{equation}
    F(x):=\int_{1}^{x} \frac{1}{f(u)}\d u,  \quad x \geq 1.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:15:16.647517+00:00","domain":"probability theory","id":"claim_20f72dc96b9316c45de4346a86335f63da6feef873a964b42e459eed8dfcfa13","kind":"theorem","schema_version":1,"statement":"[Theorem 2 of arXiv:2608.30736, 'Stability results for distribution-dependent stochastic Volterra equations'] Suppose  $(K_b,K_{\sigma})$ and $(\tilde{K}_b,\tilde{K}_{\sigma})$ satisfy Assumption~\ref{ass:kernel}, Assumption~\ref{ass:coefficients1} is satisfied and assume $X_0, \tilde{X}_0 \in L^p(\Omega)$. Let $(X_t)_{t\in[0,T]}$ and $(\tilde{X}_t)_{t\in[0,T]}$ be the strong solution to the DDSVE \eqref{eq:MFSVE} and \eqref{eq:MFSVE2}, respectively. Then, there is some constant $C>0$, depending on $b$, $\sigma$, $\tilde{b}$, $\tilde{\sigma}$, ${K}_b$, ${K}_\sigma$, $\tilde{K}_b$, $\tilde{K}_\sigma$ and $p$, such that
