{"assumptions":[],"created_at":"2026-10-28T00:59:45.465203+00:00","domain":"probability theory","id":"claim_21002982a64b2a1f164adacbb80ca3570d7de5c221970f445bef4577aa457982","kind":"theorem","schema_version":1,"statement":"[Proposition prop:aveflowim of arXiv:2411.16572, 'Optimal decay of eigenvector overlap for non-Hermitian random matrices'] Fix small $n$--independent constants $\tau,\omega_*,\epsilon>0$, and for $i=1,2$ fix spectral parameters $\Lambda_{i,0}$ as in (equation eq:defincond of the paper), with $|z_{i,0}|\le 10$, $|\eta_{i,0}|\le \omega_*$. For $t\le T^*$ let $\Lambda_{i,t}$ be the solution of (equation eq:charflowmat of the paper) with initial condition $\Lambda_{i,0}$. Let $G_{i,t}:=(W_t-\Lambda_{i,t})^{-1}$, and let $\widehat{M}_{12,t}^A$ be the deterministic approximation of $\mathrm{Im}\, G_{1,t}A\mathrm{Im}\, G_{2,t}$ from (equation avlaw12_im of the paper). Let $\ell$ from (equation eq:defcontrolparam of the paper), and define the control parameter
	\begin{equation}

		\widehat{\gamma}=\widehat{\gamma}(\eta_1,z_1,\eta_2,z_2):=|z_1-z_2|^2+\rho_1|\eta_1|+\rho_2|\eta_2|+\left(\frac{\eta_1}{\rho_1}\right)^2+\left(\frac{\eta_2}{\rho_2}\right)^2, \qquad\quad \widehat{\gamma}_t:=\widehat{\gamma}(\eta_{1,t},z_{1,t},\eta_{2,t},z_{2,t}).
	\end{equation}
	Assume that for some small $0<\xi\le \epsilon/10$, with very high probability, it holds
	\begin{equation}
		\big|\big\langle\big(\mathrm{Im}\, G_{1,0}A_1\mathrm{Im}\, G_{2,0}-\widehat{M}_{12,0}^{A_1}\big)A_2\big\rangle\big|\le \frac{n^\xi\rho_{1,0}\rho_{2,0}}{\sqrt{n\ell_0}\widehat{\gamma}_0}\wedge \frac{n^\xi}{n|\eta_{1,0}\eta_{2,0}|}
	\end{equation}
	uniformly in $\lVert A_i\rVert\le 1$ and for any $|\eta_i|\in [|\eta_{i,0}|,n^{100}]$. Then,
	\begin{equation}
		\big|\langle (\mathrm{Im}\, G_{1,t}A_1\mathrm{Im}\, G_{2,t}-\widehat{M}_{12,t}^{A_1})A_2\rangle\big|\le \frac{n^{2\xi}\rho_{1,t}\rho_{2,t}}{\sqrt{n\ell_t}\widehat{\gamma}_t}\wedge \frac{n^{2\xi}}{n|\eta_{1,t}\eta_{2,t}|},
	\end{equation}
	with very high probability uniformly in $\lVert A_i\rVert\le 1$ and all $t\le T^*$ such that $n\ell_t\ge n^\epsilon$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:28:34.970452+00:00","domain":"probability theory","id":"claim_21005a0809ddfe617baac2e0b8db315c99438407abbcd46721f693c6dd06583f","kind":"definition","schema_version":1,"statement":"[Defi eq: Hall Littlewood polynomial of arXiv:2412.05999, 'Non-Archimedean GUE corners and Hecke modules'] Let $\lambda=(\lambda_1,\ldots,\lambda_n)\in\Sig_n$ be an integer signature of length $n$. For each integer $m\ge 0$, denote $V_m(t)=\frac{(1-t)(1-t^2)\cdots(1-t^m)}{(1-t)^m}$. Then, the \emph{Hall-Littlewood polynomial} $P_\lambda(x_1,\ldots,x_n;t)$ is defined by

\begin{equation}
P_\lambda(x_1,\ldots,x_n;t) = \frac{1}{V_\lambda(t)} \sum_{\sigma \in S_n} \sigma\left(x_1^{\lambda_1}\cdots x_n^{\lambda_n} \prod_{1 \leq i < j \leq n} \frac{x_i-tx_j}{x_i-x_j}\right)
\end{equation}
where $V_\lambda(t) = \prod_{i \in \mathbb{Z}} V_{m_i(\lambda)}(t)=\frac{1}{(1-t)^n}\prod_{i\in\mathbb{Z}}(t;t)_{m_i(\lambda)}$. Here the notation $(a;q)_n := (1-a)(1-aq) \cdots (1-aq^{n-1})$ for $n \geq 0$, with $(a;q)_0 =1$ and $(a;q)_\infty$ defined in the obvious way.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:45:02.014612+00:00","domain":"probability theory","id":"claim_2101bf4e42a58203b85d9e19038192b3becf73ae72df2cdf1e83cf1ac862bde3","kind":"theorem","schema_version":1,"statement":"[Proposition PROP:cha of arXiv:2512.23957, 'Concentration and fluctuations of sine-Gordon measure around topological multi-soliton man'] Let $ Q \in \mathbb{Z}$ with $Q>0$, $\delta_\varepsilon=\eta\sqrt{\varepsilon \log \frac 1\varepsilon}$, $d_\varepsilon=\big|\log (\varepsilon \log \frac 1\varepsilon)   \big|$, as in (equation LDPIN2 of the paper) and (equation LDPIN3 of the paper), and let $F$ be a bounded, continuous function. Then  
\begin{align}
&\int_{ \{  \textup{dist}(\phi, \mathcal{M}_Q^{\varepsilon, \, \ge d_\varepsilon} ) <\delta_\varepsilon        \}  } F( \sqrt{\varepsilon}^{-1} (\phi- \pi^\varepsilon(\phi) )  )  \rho_{\varepsilon}^Q(d\phi) \notag \\
&=\overline Z_{\varepsilon}^{-1}  \int \cdots \int_{U_\varepsilon }  F(v)  e^{\frac 1\varepsilon \mathcal{E}_{\xi_1\,\dots,\xi_Q}(\sqrt{\varepsilon}v ) }  
\textup{Det}_{\xi_1,\dots,\xi_Q}(\sqrt{\varepsilon}v) \,  \nu^\perp_{\xi_1, \dots, \xi_Q}(dv)  \,  d\xi_1 \dots, d\xi_Q,  

\end{align}

\noindent
where  $\nu^\perp_{ \xi_1, \dots, \xi_Q }$ is the Gaussian measure in Lemma (LEM:Gauss of the paper), and 
\begin{align*}
&U_\varepsilon:=\big\{ ( \xi_1,\dots, \xi_Q, v )\in  \Delta_Q \times V_{\xi_1,\dots,\xi_Q}: \| \sqrt{\varepsilon} v \|_{L^2 }< \delta_\varepsilon \; \textup{and} \; \min_{i \neq j}|\xi_i-\xi_j | \ge d_\varepsilon    \big\}\\
&\mathcal{E}_{\xi_1,\dots,\xi_Q}(\sqrt{\varepsilon}v )= \int_{-L_\varepsilon}^{L_\varepsilon}  \sin\big(\theta_x m_{\xi_1,\dots,\xi_Q}(x) +(1-\theta_x) \sqrt{\varepsilon}v(x)  \big) \cdot (\sqrt{\varepsilon}v  )^3  dx, \quad |\theta_x| \le 1\\
&\textup{Det}_{\xi_1,\dots,\xi_Q}(\sqrt{\varepsilon}v):=\det\big( \Id-W_{\xi_1,\dots \xi_Q, \sqrt{\varepsilon }v }\big).
\end{align*}

 In (equation CC0 of the paper), the partition function $\overline Z_\varepsilon$ represents the integral  over $U_\varepsilon$ with $F=1$, and $W_{\xi_1, \dots, \xi_Q, \sqrt{\varepsilon}v}$ is the Weingarten map, defined in (equation Wein of the paper).","status":"unverified"}

