{"assumptions":[],"created_at":"2026-10-27T16:53:30.574878+00:00","domain":"probability theory","id":"claim_21a26b044f9a22d946be550457fd01ccfb75e7773b3a307d84bd73261b17c9bd","kind":"theorem","schema_version":1,"statement":"[Theorem thm-Ito-JS-I.4.57 of arXiv:2505.24043, 'Weak solutions of Navier-Stokes Equation with purely discontinuous L\'evy Noise'] Suppose that $\xi$ is  real-valued  semimartingale. Then for every $t\geq 0$, almost surely
\begin{align}
  \xi(t)^2 &=\xi(0)^2+ \int_0^t 2 \xi(s-)\, \mathrm{d} \xi(s) + \langle \xi^{\mathrm{c}}\rangle(t) + \sum_{s\leq t}  (\Delta \xi(s))^2, \\

&=\xi(0)^2+ \int_0^t 2 \xi(s-) \, \mathrm{d} \xi(s)+ [\xi](t).
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:39:18.537327+00:00","domain":"probability theory","id":"claim_21a294e7de16cf43ac179f58195a5a2507a80e3f30c6112fe3f1b0766159a024","kind":"theorem","schema_version":1,"statement":"[Theorem 26 of arXiv:2609.02294, 'Existence and Blow-Up for Non-linear Fokker-Planck with Controlled Drift Divergence'] Assume condition \eqref{eq:assumptions2}. The following holds.
    \begin{enumerate}
        \item  If $k <k_c$, there are stationary solutions.

        \item  If $k =k_c$, then every well defined solution $u$ decays like $\|u(t)\|_\infty\leq \mathcal O(t^{-\frac{d}{2}}) $.
        \item  If $k>k_c$, and the solution $u$ is uniformly bounded in time and space, i.e. $u \in L^\infty_{t,x}$, then decays like $\|u(t)\|_\infty\leq \mathcal O(t^{-\frac{d}{2}}) $.
    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T16:26:02.688174+00:00","domain":"probability theory","id":"claim_21a5a1a7e7756143ba53f66eda18fa3ce114bd5cebd753c82612a137a7021a32","kind":"concept","schema_version":1,"statement":"[Lemma notBAS of arXiv:2608.30747, 'Compact homogeneous complex manifolds'] If $\alpha,\beta,\alpha+\beta\in\Delta_\qg^+$, $\alpha-\beta,2\alpha+\beta\notin\Delta_\qg$, then 
\begin{align*}
(\Lambda^b(E_\beta)\cdot R^b)(E_\alpha,E_{-\alpha})E_{-\alpha}  
=& c\left(\tfrac{1}{x_{\alpha+\beta}}g_\ag(A_\alpha,A_{\beta})-\left(\tfrac{1}{x_\alpha}-\tfrac{1}{x_{\alpha+\beta}}\right)g_\ag(A_\alpha,A_\alpha) 
 \right. \\
&\hspace{.4cm} \left. +\tfrac{N_{\alpha,\beta}^2(x_{\alpha+\beta}-x_\beta)}{x_{\alpha+\beta}}
 - \tfrac{N_{\alpha,\beta}^2(x_{\alpha+\beta}-x_\alpha)^2}{x_{\beta}x_{\alpha+\beta}}  
+\la\alpha,\beta\ra\right) E_{\alpha+\beta},
\end{align*}
where $c:=-\tfrac{N_{\alpha,\beta}(x_{\alpha+\beta}-x_\beta)}{x_{\alpha+\beta}}$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:32:11.141555+00:00","domain":"probability theory","id":"claim_21a7d507b4d5a9954cc7f89607feb41dabb1c5849b6161e217a69270e6ab2e41","kind":"concept","schema_version":1,"statement":"[Theorem lem:8 of arXiv:2510.13572, 'Coalescence in Markov chains'] \mbox{\hfil}
\begin{letlist}
\item
We have that $1\in K(P)$ if and only if $P\in\mathcal{P}_S$ is aperiodic. 
In this case, $k(\mu_{\text{\rm ind}})=1$.
\item
If $P\in\mathcal{P}_S$ has period $d$, then the coalescence classes of $\mu_{\text{\rm ind}}$
are a.s.\ the cyclic classes of $P$ and therefore  $k(\mu_{\text{\rm ind}})=d$.
Hence, $d\in K(P)$, and moreover $d\le k$ for all $k\in K(P)$. 
\end{letlist} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:06:55.268960+00:00","domain":"probability theory","id":"claim_21aca395af0dc8742d6d98426a47b8b28bc188906c1364c6493a0370e54414df","kind":"concept","schema_version":1,"statement":"[Theorem thm:azuma-mtp of arXiv:2512.21026, 'Minimax Duality in Game-Theoretic Probability\thanks{Work in progress: mistakes are likely'] Suppose for $T\in\mathbb{N}$ the sequence $\{X_t\}_{t=1}^T$ is a (measure-theoretic) supermartingale.
  If $|X_t-X_{t-1}|\leq c_t$ a.s.\ for all $t\leq T$ for constants $c_t\geq 0$,
  then for all $\epsilon > 0$ we have
  \begin{align}

\mathbb{P}[X_T-X_0\geq \epsilon] \leq \exp \left(- {\epsilon ^{2} \over 2\sum _{t=1}^{T}c_{t}^{2}}\right).
  \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:05:57.784921+00:00","domain":"probability theory","id":"claim_21b2e51a66ad24610533dce66353ffdce402307cc352a4d3d4552bdb277b54cc","kind":"lemma","schema_version":1,"statement":"[Lemma 39 of arXiv:2608.30549, '\vspace{-1cm}Maximally Spread Out Measures and Implications\\{} for Phase Transitions in A'] For $d, n, L_0 \in \N$ and $C_0 \geq 1$, define
  \begin{align*}
    &\CalNN_n (C_0, L_0;\RR^d) \\
    &:= \biggl\{
           R_\varrho (\CalW)
           \,\,:\,\,
           \begin{array}{c}
                \text{$\CalW$ neural network weights with}\\ 
           \| \CalW \|_{\ell^0} \leq n, \,\,
           \| \CalW \|_{\ell^\infty} \leq C_0, \,\,
           L(\CalW) \leq L_0, \,\,
           d_{\mathrm{in}}(\CalW) = d, \,\,
           d_{\mathrm{out}}(\CalW) = 1
           \end{array}
         \biggr\}
    .
  \end{align*}
  Then for any measurable, bounded set $\Omega \subset \R^d$ and any $p \!\in\! (0,\infty]$,
  there exist constants $R \!=\! R(\Omega) \!\geq\! 1$ and $C = C(\Omega, p, d) > 0$
  such that for every $\eps \in (0,1)$, it holds that
  \[
      \cn \bigl(\CalNN_n (C_0, L_0;\RR^d), \norm{\cdot}_{L^p(\Omega)}, \eps\bigr)
    \leq \left( C \cdot L_0^4 \cdot \left( 8 d^2 R \cdot C_0 \cdot n \right)^{1+L_0} \cdot \eps^{-1} \right)^{2n}
    .
  \]","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:10:08.757868+00:00","domain":"probability theory","id":"claim_21b48bbed09909856bfe4e8bc25bd3f9bbad77a4520cb960423dd0fc4f5a0c10","kind":"lemma","schema_version":1,"statement":"[Lemma lem:error_bounds2 of arXiv:2411.17827, 'Ordered random walks and the Airy line ensemble'] Let $a < 1/4$, $\theta > 1$ and $\varepsilon \in (0, 1/2)$. There exists $t_0 > 0, \delta > 0$ and $c, C > 0$ such that uniformly in $d(t) \leq t^a$ and $t > t_0$ and $\varepsilon' < \varepsilon$, for all $x \in W^d$
with $\lvert x_j \rvert \leq t^{\theta}/\log(t)$,
\begin{align*}
\mathbf E_{x}[V(S(t)); \tau > t, \nu_t > t^{1-\varepsilon}] & \leq CV(x)
e^{t^{(4+\delta) a} - ct^{\epsilon'}};
\end{align*}
and for all $x \in W^d$ with $x_{j+1} - x_j \geq 1$ for all $j = 2, \ldots, d$,
\begin{align*}
\mathbf E_{x}[\Delta(B(t)); \tau > t, \nu_t > t^{1-\varepsilon}] & \leq C\Delta(x)e^{\theta t^{2a}\log(t) - ct^{\epsilon'}}.
\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:25:49.865818+00:00","domain":"probability theory","id":"claim_21b8931dc522242ef61ddcebc0d3e37dd4d82778b56691c5e62fbb8201320b4e","kind":"lemma","schema_version":1,"statement":"[Lemma 15 of arXiv:2609.02019, '2609.02019'] Let the assumptions of Theorem~\ref{Thm-local-solution} hold and let
		\[
		\theta\in\left(\frac32,\,
		s-\max\{2\delta_{\mathcal Q},1\}\right).
		\]
		Let $v_n^{(R)}$ be the approximate solution  obtained in Lemma \ref{Lemma: existence of XnR}.
		Then the following properties hold almost surely:
		\begin{enumerate}[label={\bf (\arabic*)},leftmargin=0.79cm]\setlength\itemsep{0.2em}




			\item
			Let
			\[
			\tau_N^{n,m}(R)
			\triangleq
			N
			\wedge
			\inf\left\{
			t\ge0:
			\|v_n^{(R)}(t)\|_{H^s}
			\vee
			\|v_m^{(R)}(t)\|_{H^s}
			\ge N
			\right\},
			\quad n,m\ge1,\quad N\ge1.
			\]
			Then, for every $N>0$,
			\begin{equation}

				\lim_{n\to\infty}
				\sup_{m\ge n}
				\E\left[
				\sup_{t\in[0,\tau_N^{n,m}(R)]}
				\|v_n^{(R)}(t)-v_m^{(R)}(t)\|_{H^\theta}^2
				\Big|\F_0
				\right]
				=
				0.
			\end{equation}

			\item
			There exists an $\mathcal F_t$-progressively measurable $H^s$-valued process
			$v^{(R)}=(v^{(R)}(t))_{t\ge0}$
			satisfying, for every $T>0$,
			\begin{equation}

				\E\left[
				\sup_{t\in[0,T]}
				\|v^{(R)}(t)\|_{H^s}^2
				\Big|\F_0
				\right]
				\le
				2\|v_0\|_{H^s}^2
				\exp\left\{
				C
				\Big(
				1+2R
				+\|\partial_xv_0\|_{L^\infty}
				+\|\mathcal H\partial_xv_0\|_{L^\infty}
				\Big)T
				\right\}.
			\end{equation}
			Moreover, for a subsequence of $\{v_n^{(R)}\}_{n\ge1}$, still denoted by
			$\{v_n^{(R)}\}_{n\ge1}$, and for every $s'\in[\theta,s)$,
			\begin{equation}

				\lim_{n\to\infty}
				\sup_{t\in[0,T]}
				\|v_n^{(R)}(t)-v^{(R)}(t)\|_{H^{s'}}
				=
				0,
				\quad
				T>0.
			\end{equation}
		\end{enumerate}","status":"unverified"}

