{"assumptions":[],"created_at":"2026-10-26T20:48:17.116202+00:00","domain":"probability theory","id":"claim_22bb2d60f29e0d76efbfffb23f368399a859443f46153fbf4452f54caa5af099","kind":"concept","schema_version":1,"statement":"[Cor 136 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Let $C>1$ be a fixed constant. 
	Denote $\gamma'' = \gamma_{x^{SW}_{q;a,b,c}}'',\gamma'''=\gamma_{x^{SW}_{q;a,b,c}}'''$, and let
	\begin{flalign}

		x = x^{SW}_{q;a,b,c} + \mathfrak{d} \hat{x}; \qquad y =  \mathfrak{d}^2 \hat{y}.
	\end{flalign}	
Assume that $z=(x,y)\in \mathfrak L_{q;a,b,c}$ with {$\me_{z;q}\ge (1/C) \md, \md_z\asymp \md$.}	
	\noindent Denoting  
	\begin{flalign}

		\hat{f}(\hat{x}, \hat{y}) = \mathfrak{d}^{-1} \cdot f(x,y); \qquad \Gamma_{\hat{x}} = \gamma''+\md\hat x(\gamma'''-\gamma''\log {\mathfrak q}+4 \gamma''^2).          
	\end{flalign}

	\noindent we have 
	\begin{flalign}
		\hat{f} (\hat{x}, \hat{y}) & =  \mathrm{i} \Gamma_{\hat{x}}^{1/2}  \Big( 2 \hat{y} - \gamma'' \hat{x}^2 - \displaystyle\frac{\gamma'''}{3} \mathfrak{d} \hat{x}^3 \Big)^{1/2}  - \gamma'' \hat{x}  - \mathfrak{d} \Big( \gamma''^2 + \displaystyle\frac{\gamma'''}{2} \Big) \hat{x}^2         + \mathfrak{d} g  \Big(\hat{y}- \gamma''\displaystyle\frac{\hat{x}^2}{2} \Big)  + \mathcal{O} ( \mathfrak{d}^2),
	\end{flalign}
        where $A',B',D'$ are as in \eqref{DAB} with $x=x^{SW}_{q;a,b,c}$ and
