{"assumptions":[],"created_at":"2026-10-27T19:59:45.011229+00:00","domain":"probability theory","id":"claim_231928ae4b5afafc23690223c865c4f3ae1c065a488572eca684320e9132e136","kind":"definition","schema_version":1,"statement":"[Definition RKS smooth spde of arXiv:2605.13479, '\LARGE Dean-Kawasaki Equation with Biot-Savart and Keller-Segel Interactions: Existence an'] (Renormalized kinetic solution)
	Let the interaction $\mathcal{V}[\cdot]$ be defined by (equation ker-V of the paper) and $\rho_0\in L^{1}_{\mathbb{T}^2}$. For any $\varepsilon \in (0,1)$ and $\eta \in[0,1)$, a renormalized kinetic solution $\rho$ of (equation SPDE-1 of the paper) with initial datum $\rho_0$ is a nonnegative, almost surely continuous $L^1_{\mathbb{T}^2}$-valued $\mathcal{F}_t$-predictable process $\rho \in L^1_{\Omega \times[0, T]}L^1_{\mathbb{T}^2}$ that satisfies the following properties.



	\begin{enumerate}
		\item Conservation of mass: almost surely for every $t\in[0,T]$,
		\begin{equation}
		\|\rho(\cdot,t)\|_{L^{1}_{\mathbb{T}^{2}}}=\left\|\rho_0\right\|_{L^{1}_{\mathbb{T}^{2}}}.
		\end{equation}




		\item Pathwise entropy dissipation estimates: almost surely, 
		\begin{align}
\int_0^t\int_{\mathbb{T}^2}
|\nabla\sqrt{\rho}|^2\mathrm{d}x\mathrm{d}s
\lesssim&\int_{\mathbb{T}^2}\Psi(\rho_0)\mathrm{d}x+\sqrt{\varepsilon}\int_0^t\int_{\mathbb{T}^2}
2\nabla\sqrt{\rho}\cdot
\xi_{K}
+\varepsilon N_KT+1,
\end{align}
for all $t \in [0,T]$.  








		Furthermore, there exists a nonnegative kinetic measure $q$ ([FG24]) satisfying the following properties. 
		\item Regularity: almost surely
		\begin{align}
		4\delta_{0}(\xi-\rho)\xi|\nabla \sqrt{\rho}|^{2}\leqslant q\quad {\rm{on}}\ \mathbb{T}^2\times(0,\infty)\times[0,T].
		\end{align}
		\item Vanishing at infinity: we have
		\begin{align}
		\liminf_{M\to \infty}\mathbb{E}\Big[q(\mathbb{T}^2\times [0,T]\times [M,M+1])\Big]=0.
		\end{align}


