{"assumptions":[],"created_at":"2026-10-27T12:17:13.061999+00:00","domain":"probability theory","id":"claim_2390b2ae51bb731bcf1e258a8b3ec9ad29ce6c894c3a93d3c1c0d66088663a44","kind":"concept","schema_version":1,"statement":"[Lem bootstrap of arXiv:2508.04954, 'Conditional exponential directed last passage percolation under a one-point upper large de'] Let $\Omega$ be an open subset of ${\mathbb R}^2$. 
Let $\{Z_n(x,y)\}_{(x,y)\in \Omega}$, $n\in {\mathbb N}$, and $\{Z(x,y)\}_{(x,y)\in \Omega}$ be random fields.  

Let $m\in {\mathbb N}$. 
Suppose that the following two conditions hold: 
\begin{enumerate}[(a)]
\item If $(x_i, y_i)\in \Omega$, $i=1, \cdots, m$ and $y_1, \cdots, y_m$ are distinct, then 
\begin{equation*}
    \{Z_n(x_i,y_i)\}_{i=1,\dots,m} \xrightarrow{d} \{Z(x_i,y_i)\}_{i=1,\dots,m}
    \qquad \textnormal{as $n\to \infty$.}
\end{equation*}

\item 
For every $x_1, \cdots, x_m \in \pi_x(\Omega)$ and $r_1 \cdots, r_m \in {\mathbb R}$
\begin{equation*}
	(y_1, \cdots, y_m) \mapsto \mathbb{P} (Z(x_i, y_i) \leq r_i, \, i = 1, \cdots, m)
\end{equation*}
is jointly continuous in $(y_1, \cdots, y_m) \in \prod_{i=1}^m \pi_y(\Omega \cap (\{x_i\} \times {\mathbb R}))$. 
\end{enumerate}
Then, every $m$-point distribution of $\{Z_n(x,y)\}_{(x,y) \in \Omega}$ converges to that of $\{Z(x,y)\}_{(x,y) \in \Omega}$ as $n\to \infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:01:39.420720+00:00","domain":"probability theory","id":"claim_239224745832883d32c34f586e134048d825b5384b4e6d9713c1a37b069c9643","kind":"definition","schema_version":1,"statement":"[Definition of arXiv:2607.22156, 'A random matrix approach to lamplighter groups'] Let $J$ be a set of indices and consider two families of formal variables $\mathbf{x}=(x_{j})_{j\in J}$ and $\mathbf{x^{*}}=(x_{j}^{*})_{j\in J}$.
	    \begin{enumerate}
	        \item A \emph{*-test graph} $T = (G, \gamma, \epsilon )$ in the variables $\mathbf{x}$ is a finite connected multi-digraph $G = (V , E, \mathrm{src}, \mathrm{tar})$ together with edge labels $\epsilon : E \rightarrow \{1,*\}$ and $\gamma : E \rightarrow J$. One can see the maps $\gamma$ and $\epsilon$ as indicating that an edge $e\in E$ is labeled $x_{\gamma(e)}^{\epsilon(e)}$. The maps $\mathrm{src}$, $\mathrm{tar} : E \rightarrow V$ specify the source, $\mathrm{src}(e)$ and target, $\mathrm{tar}(e)$ of each edge $e \in E$. 
            \item A \emph{*-graph monomial} $g=(T,v_{in},v_{out})$ is a *-test graph $T$ together with the data of two vertices  $v_{in}$ and $v_{out}$ in $V$. We refer to the roots $(v_{in}, v_{out}) \in V^{2}$ as the input and the output, respectively, though they need not be distinct. We denote by $\mathcal{G}\langle\mathbf{x},\mathbf{x^*}\rangle$ the set of all such *-graph monomials which can be extended to $\mathbb{C}\mathcal{G}\langle\mathbf{x},\mathbf{x^*}\rangle$ the space of finite linear complex combinations of *-graph monomials in variable $\mathbf{x}$ (graphs are considered up to isomorphisms of graphs preserving labeled and in/outputs).
	    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:48:45.325434+00:00","domain":"probability theory","id":"claim_239532178db6b64589cc66b3ed18775fdcbbdd46f21b6884af9628fa469d70b3","kind":"concept","schema_version":1,"statement":"[Lemma l:DiffusionP of arXiv:2411.14936, 'Massive Particle Systems,\\Wasserstein Brownian Motions,\\ and the Dean--Kawasaki Equation'] Let~$u\eqdef F\circ \hat\mbff^\star$ and $v\eqdef G\circ \hat\mbfg^\star$ be in~$\hFC{}{0}$. Then,~$u,v\in\msD(\widehat\mcL_\pi)$ ($\subset\msD(\widehat\mcG_\pi)$) and
\begin{gather}

\widehat\mcG_\pi(u,v)= \sum_{i,j}^{k,h} (\partial_i F) \circ \hat\mbff^\star \cdot (\partial_j G) \circ \hat\mbfg^\star \cdot \mathsf{\Gamma}(\hat f_i, \hat g_j)^\star \,\mathrm{,}\;\,
\\

\widehat\mcL_\pi u = \sum_i^k (\partial_i F)\circ \hat\mbff^\star \cdot \tparen{(\tfrac{1}{\id_\mbbI}\otimes\mssL) \hat f_i}^\star + \sum_{i,j}^{k,k} (\partial_{ij}^2F)\circ \hat\mbff^\star \cdot \mathsf{\Gamma}(\hat f_i,\hat f_j)^\star\,\mathrm{,}\;\,
\end{gather}
are well-defined (i.e., independent of the choice of the representatives~$F$,~$\hat\mbff$ for~$u$ and~$G$,~$\hat\mbfg$ for~$v$) and independent of~$\pi\in\msP(\mbfT)$.

Furthermore, we have the intrinsic representations
\begin{align}

\widehat\mcG(u,v)_\eta =& \int_M \mathsf{\Gamma}^z\big\lvert_{z=x} \big({u(\eta+\eta_x\delta_z-\eta_x\delta_x), u(\eta+\eta_x\delta_z-\eta_x\delta_x)}\big) \mathop{}\!\mathrm{d}\eta(x) \,\mathrm{,}\;\,
\\

\widehat\mcL(u)_\eta=& \int_M \frac{\mssL^z\big\lvert_{z=x}u(\eta+\eta_x\delta_z-\eta_x\delta_x)}{{\eta_x}^2} \mathop{}\!\mathrm{d}\eta(x) \,\mathrm{.}
\end{align}

\begin{proof}
We prove the assertions for the generator. The argument for the carr\'e du champ operator is completely analogous and therefore it is omitted.
The well-posedness and the independence from~$\pi$ follow at once from the intrinsic representation~(equation eq:l:DiffusionP:0.4 of the paper), so it suffices to show the latter.
To this end, choose freely~$\hat f,\hat f_1,\hat f_2\in\msR_0\otimes \msA$. Since~$\hat f^\star\eta$ is a \emph{finite} sum, simply by linearity of~$\mssL$ (bilinearity of~$\mathsf{\Gamma}$), we may compute
\begin{align}
\nonumber
\mssL^z\big\lvert_{z=x}&\ \big({\hat f^\star(\eta+\eta_x\delta_z-\eta_x\delta_x)}\big) =
\\
\nonumber
=&\ \mssL^z\big\lvert_{z=x} \braket{\int \hat f(\eta_y,y) \mathop{}\!\mathrm{d}\eta(y)+ \eta_x\hat f_i(\eta_x,z)-\eta_x\hat f_i(\eta_x,x)}
\\

=&\ \eta_x (\mssL \hat f)(\eta_x,x)\,\mathrm{,}\;\,
\end{align}
and
\begin{align}
\nonumber
\mathsf{\Gamma}^z\big\lvert_{z=x}&\ \left(\hat f_1^\star (\eta+\eta_x\delta_z-\eta_x\delta_x),\hat f_2^\star (\eta+\eta_x\delta_z-\eta_x\delta_x)\right)=
\\
\nonumber
=&\ \mathsf{\Gamma}^z\big\lvert_{z=x}\Big[\hat f_1^\star\eta +\eta_x\hat f_i(\eta_x,z)-\eta_x\hat f_1(\eta_x,x), 
\hat f_2^\star\eta +\eta_x\hat f_2(\eta_x,z)-\eta_x\hat f_2(\eta_x,x)\Big]
\\
\nonumber
=&\ \mathsf{\Gamma}^z\big\lvert_{z=x}\left[\eta_x\hat f_1(\eta_x,z), \eta_x\hat f_2(\eta_x,z)\right]
\\

=&\ {\eta_x}^2\, \mathsf{\Gamma}(\hat f_1,\hat f_2)(\eta_x,x) \,\mathrm{.}
\end{align}

Now, by the diffusion property for~$(\mssL,\msA)$,
\begin{align}
\nonumber
\mssL^z\big\lvert_{z=x}&\ u\big({\eta+\eta_x\delta_z-\eta_x\delta_x}\big)=
\\

=&\ \sum_i^k (\partial_i F)(\hat\mbff^\star \eta)\, \mssL^z\big\lvert_{z=x} \big({\hat f_i^\star(\eta+\eta_x\delta_z-\eta_x\delta_x)}\big)
\\
\nonumber
&+ \sum_{i,j}^{k,k} (\partial^2_{ij} F)(\hat\mbff^\star \eta)\, \mathsf{\Gamma}^z\big\lvert_{z=x} \Big(\hat f_i^\star (\eta+\eta_x\delta_z-\eta_x\delta_x),
\hat f_j^\star (\eta+\eta_x\delta_z-\eta_x\delta_x)\Big)\,\mathrm{.}
\end{align}

Substituting~(equation eq:l:DiffusionP:4 of the paper) and~(equation eq:l:DiffusionP:5 of the paper) into~(equation eq:l:DiffusionP:3 of the paper), dividing by~${\eta_x}^2$ and integrating w.r.t.~$\eta$ we obtain the right-hand side of~(equation eq:l:DiffusionP:0.2 of the paper), and thus the conclusion by~(equation eq:l:DiffusionP:0.2 of the paper) and the diffusion property for~$\widehat\mcL_\pi$.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:36:16.004828+00:00","domain":"probability theory","id":"claim_23956ab76dde303fc8e5b1daccd6101b22557dad67c63ddbc3034d1fdcb112ff","kind":"theorem","schema_version":1,"statement":"[Theorem prop_w of arXiv:2606.27549, 'On Analytically Tractable Multidimensional Diffusions via Doob $h$-Transforms, with Resett'] Let $h({\bf x})=h_c({\bf x})\in C^{2}(\mathcal{D})$ be a function satisfying the conditions of Theorem (teo_1 of the paper), with 

\begin{equation}
   h_c({\bf x}):=1+c \,k({\bf x}), 
   \qquad {\bf x}\in \mathcal{D},

\end{equation}

where $k({\bf x})\in C^{2}(\mathcal{D})$ is a positive function, and $c \in (c_m,+\infty)$,  with $c_m=\displaystyle-\inf_{{\bf x} \in {\cal D}} \frac{1}{k({\bf x})}$.

Then, the transition p.d.f.\ given in ((2.1 of the paper)), for all   $t>\tau\geq  0$ and 
$\bf{x},\,\bf{y}\in  {\cal D}$ can be expressed as  

\begin{equation*} 
    f({\bf x}, t \,|\,{\bf y}, \tau)
    ={1+c \,k({\bf x})\over 1+c \,k({\bf y})}\,
    \widehat{f}({\bf x},t\,|\,{\bf y},\tau),
\end{equation*}

and it can be decomposed as the following mixture

\begin{equation}
    f({\bf x},t\,|\,{\bf y},\tau)
    =\theta_c({\bf y})\,
    \widehat{f}({\bf x},t\,|\,{\bf y},\tau)
    +(1-\theta_c({\bf y}))\,
    \widetilde{f}({\bf x},t\,|\,{\bf y},\tau),

\end{equation}

with  
 \begin{equation}
   \theta_c({\bf y})=\frac{1}{h_c({\bf y})},  

 \end{equation}

and where 
  \begin{equation} 
      \widetilde{f}({\bf x}, t\,|\,{\bf y}, \tau)
      =\frac{k({\bf x})}{k({\bf y})}\,
      \widehat{f}({\bf x},t\,|\,{\bf y}, \tau)
       \end{equation}
 is the transition p.d.f.\ of the diffusion process, say 
 $\widetilde{\bf X}_t=\big(\widetilde{\bf X}_t\big)_{t\geq 0}$,  having the following infinitesimal moments:

   \begin{equation}
   \begin{array}{ll}
	\widetilde{b}_i({\bf x})
	=\widehat{b}_i({\bf x})+\displaystyle{1\over k({\bf x})}\sum_{j=1}^n \widehat{a}_{ij}({\bf x})
