			F^{(N-1),-}_{\text{in}} \leq F^{(N),-}_{\text{in}} \leq F_{\text{in}} \leq F^{(N),+}_{\text{in}} \leq F^{(N-1),+}_{\text{in}} \quad \text{pointwise for each} \, \, N,  \\
