{"assumptions":[],"created_at":"2026-10-27T13:49:06.311244+00:00","domain":"probability theory","id":"claim_23f7855bf404d9b35f16543cb5338810b5e7397037694ace252501a8058311c0","kind":"concept","schema_version":1,"statement":"[Theorem th:main of arXiv:2601.06850, 'Explosion and non-explosion in pure birth Crump--Mode--Jagers branching processes'] ~

\begin{enumerate}[\normalfont(i)]
