{"assumptions":[],"created_at":"2026-10-27T06:39:11.667721+00:00","domain":"probability theory","id":"claim_247bd03c9b1a9f1b8c9fb786c4788d0797db05ff624e869e2c17c8edc65838e5","kind":"theorem","schema_version":1,"statement":"[Proposition 1 of arXiv:2608.04716, 'Extinction Time Estimate for Subcritical (Binary) Homogeneous Crump-Mode-Jagers Processes'] There holds
	\begin{equation}
		\begin{split}	q(x,t)&=\P(T\leq t\mid Z_0=\1_{[x,\infty)})=\frac{\int_x^{x+t} W(t+x-s)\d F(s)}{(1-F(x))W(t)}\\&=1+\frac{\lambda \int_0^x (1-F(y))W^\prime(t+x-y)\d y -W^\prime(t+x)}{\lambda(1-F(x))W(t)}.
		\end{split}
	\end{equation}
	where the function $W$ is the scale function  defined in \cite[page 11]{lambert2010contour} having Laplace transform
	\begin{equation}\Lcal(W)(s):=\int_{0}^\infty W(r)e^{-sr}\d r=\frac{1}{\lambda \left( \E[e^{-s\tau }]-1\right)+s}.\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:33:12.002647+00:00","domain":"probability theory","id":"claim_247f700c67fbec3e80a9445e9adcfe6dbedaff1a13d518fa19279d1e72613ff5","kind":"theorem","schema_version":1,"statement":"[Proposition prop:near-divisible of arXiv:2609.02820, 'Sharpness and critical scaling of parking'] For all
	sufficiently small $\delta>0$,
	\begin{equation}
		\mathbb{E} u_\infty^\delta(0)\leq C
		\begin{cases}
			\delta^{-3}&d=1\,,\\
			\delta^{-1}&d=2\,,\\
			\delta^{-1/3}&d=3\,,\\
			\log(e/\delta)&d\geq4.
		\end{cases}
	\end{equation}
	The reverse inequality holds when $d\leq4$, and when $d\geq5$ the lower bound
	is $c[\log(e/\delta)]^{2/d}$. If in addition $\eta_\delta(0)$ is bounded
	uniformly in $\delta$, then $\mathbb{E} u_\infty^\delta(0)\asymp[\log(e/\delta)]^{2/d}$
	when $d\geq5$.","status":"unverified"}

