{"assumptions":[],"created_at":"2026-10-26T19:46:12.274365+00:00","domain":"probability theory","id":"claim_249e1ca84a54a0972d05f81de255d0247b298ace82605a211c0c38a2e3475ed9","kind":"theorem","schema_version":1,"statement":"[Theorem 11 ($\AW_2$ between filtered Gaussian processes) of arXiv:2604.22159, 'Adapted optimal transport between filtered Gaussian processes'] Let $a, b \in \bR^{Nd}$ and $L, M \in \mathscr{L}(N,d)$.
\begin{enumerate}
\item[(i)] We have
\begin{equation} 
\begin{split}
\AW_2^2(\bG^{a, L}, \bG^{b,M}) = \|a - b\|_2^2 + \dist_{\mathrm{AW}}^2(L, M),
\end{split}
\end{equation}
where $\dist_{\mathrm{AW}}$ is the pseudo-metric on $\mathscr{L}(N, d)$ defined by
\begin{equation} 
\dist_{\mathrm{AW}}(L, M) := \Big(\|L\|_F^2 + \|M\|_F^2 - 2 \sum_{t=1}^N \|(L^{\intercal}M)_{t,t} \|_{*}\Big)^{1/2}.
\end{equation}
We let $\tilde{\mathscr{L}}(N, d)$ be the quotient space $\mathscr{L}(N, d) / \sim$, where $L \sim M$ if and only if $\dist_{\mathrm{AW}}(L, M) = 0$. We use the same symbol $\dist_{\mathrm{AW}}$ to denote the induced metric.
\item[(ii)]
There exists a Gaussian bicausal coupling that is optimal for $\AW_2(\bG^{a, L}, \bG^{b,M})$. A Gaussian bicausal coupling of the form $\pi^P$ defined by \eqref{eqn:joint.Gaussian}, where $P = \diag(P_1, \ldots, P_N)$ is block diagonal, is optimal if and only if
\[
P_t \in \mathscr{P}( (L^{\intercal} M)_{t,t}), \quad t \in [N].
\]
In particular, we may pick $P_t = V_t U_t^{\intercal}$, so that $P$ is block diagonal with orthogonal diagonal blocks (written $P \in \mathscr{O}(N, d)$).
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:48:24.320589+00:00","domain":"probability theory","id":"claim_24a23e079121aaab8f9e5e564b5a1b385633aab38f4829a0f53dd020a28175a4","kind":"concept","schema_version":1,"statement":"[Lemma lem:clean lem_unique_saddlepoint of arXiv:2605.31356, 'P\'olya--Schur problems and free probability'] \begin{enumerate}
	\item Let $\mu$ be any freely infinitely divisible distribution. Then, for any $z\in\mathbb{C}_{+}\cup\{z\in\mathbb{R}: -\infty<\operatorname{Im} G_{\mu}(z+\ii0)<0\}$
	 \begin{equation}
	z-\frac{1}{u}-R_{\mu}(u)=0
\end{equation} has a unique solution $G_{\mu}(z)$ in $\mathbb{C}_-$. Hence, if $f_n\in\mathcal{LP}$ and $z\in\mathbb{C}_{+}\cup\{z\in\mathbb{R}:-\infty< \operatorname{Im} G_{\mu_{c,\Sigma}}(z+\ii0)<0 \}$, then (equation eq:clean saddle point equation of the paper) has a unique solution in $\mathbb{C}_{-}$ given by $u_n^*(z)=G_{\mu_n}(z)$.

\item If $\{f_{n}\}$ satisfy Assumption (assump:main assumption of the paper), then for any $\varepsilon>0$ (equation eq:clean saddle point equation of the paper) has at most one solution in $\{u\in\mathbb{C}:\operatorname{Im} u<-\varepsilon\}$ for $n$ sufficiently large. Additionally, if $\varepsilon>0$ is sufficiently small, then this unique solution $u_n^*(z)$ exists. 

\item Let $\{f_n\}$ satisfy Assumption (assump:main assumption of the paper) and let $B\subset\mathbb{C}_{+}\cup\{z\in\mathbb{R}: -\infty<\operatorname{Im} G_{\mu_{c,\Sigma}}(z+\ii0)<0 \}$ be a compact subset. Let $\varepsilon>0$ be small enough such that (equation eq:clean saddle point equation of the paper) has a unique solution $u=u_n^*(z)\in\{u\in\mathbb{C}:\operatorname{Im} u<-\varepsilon\}$ for all $z\in B$. Then, $u_n^*$ is analytic on a neighborhood of $B$ and \begin{equation}
