{"assumptions":[],"created_at":"2026-10-26T20:54:10.972037+00:00","domain":"probability theory","id":"claim_24b4a75dbb634077cc4997083954a4125bbc98cda5f85c731b3ef768db7602f6","kind":"concept","schema_version":1,"statement":"[Thm 45 of arXiv:2606.13459, 'Symmetric Cooperative Motion in Higher Dimensions'] \cite[Theorem 4.2]{karlsenrisebro01} 
