{"assumptions":[],"created_at":"2026-10-27T17:11:02.384716+00:00","domain":"probability theory","id":"claim_24fdbbe6a2d2ad043864d94eabbc582157af9be2c66217a32ba76ae4f6beca7d","kind":"concept","schema_version":1,"statement":"[Proposition prop:local_hajek_intro of arXiv:2507.10531, 'Quantitative central limit theorems for exponential random graphs'] Define
