\quad \textup{and} \quad

\begin{dcases}
(i\partial_t+\Delta - \overline{V_j})v_j = 0, \quad &\textup{in}\,\, \Sigma, \\
v_j(T, \centerdot) = g\in L^2(\mathbb{R}^n), &\textup{in}\,\, \mathbb{R}^n.
\end{dcases} 
\]

Then, it holds that 

\begin{equation}
\|u_j - u_k \|_{L^2_w(\Sigma)} \leq 4T \| V_j - V_k \|_{w} \|u_k\|_{L^2_w(\Sigma)}
\end{equation}

and

\begin{equation}
\|v_j - v_k \|_{L^2_w(\Sigma)} \leq 4T \| V_j - V_k \|_{w} \|v_k\|_{L^2_w(\Sigma)},
