{"assumptions":[],"created_at":"2026-10-27T19:59:45.015950+00:00","domain":"probability theory","id":"claim_262e166b3811f61275a5c83c385bdadfe2e45d1164d56e26023c793eadba5c55","kind":"concept","schema_version":1,"statement":"[Theorem thm:main of arXiv:2605.15401, 'Noise Tradeoffs, Stationary Information Flow, and Structural Balance in Unit-Birth Network'] Consider the unit-birth CTMC on $S=\mathbb{Z}_{\ge0}^N$ with generator
(equation eq:generator of the paper). Suppose Assumption~(ass:standing of the paper) holds, and let
$\pi$ be its stationary distribution. 
Then the following statements hold.
\begin{enumerate}[label=\textup{(\arabic*)}, leftmargin=2.2em]
\item For each $i$,
\begin{equation}
\mathbb{E}_\pi[X_i]=\tau_i\,\mu_i,
\end{equation}
and
\begin{equation}
F_{X_i}
=1+\frac{\mathrm{Cov}_\pi\!\big(f_i(X_{-i}),X_i\big)}{\mu_i}.
\end{equation}

\item The single information flow $(\dot I)_{X_i}$ defined in
(equation eq:Idot_clean_def of the paper) is well defined, and for each $i$,
\begin{equation}
\frac{F_{X_i}-1}{\tau_i}\ge (\dot I)_{X_i}.
\end{equation}

\item We have zero total information flow:
\begin{equation}
\sum_{i=1}^N (\dot I)_{X_i}=0.
\end{equation}
\end{enumerate}
Consequently, we have the global tradeoff
\begin{equation}
\sum_{i=1}^N \frac{F_{X_i}-1}{\tau_i}
\ge
\sum_{i=1}^N (\dot I)_{X_i}
=0.
\end{equation}
In particular, it is impossible to have $F_{X_i}\le 1$ for all $i$ with strict
inequality for at least one index: if $F_{X_k}<1$ for some $k$, then there
exists $j\neq k$ such that $F_{X_j}>1$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:51:26.749471+00:00","domain":"probability theory","id":"claim_262f7a1f99044741c45fd42ba9d8132f96a74ed0628f9b0f31bc433eb3420cdd","kind":"concept","schema_version":1,"statement":"[Proposition prop:factorial_moments of arXiv:2606.09386, 'High-degree vertices in uniform recursive directed acyclic graphs with freezing'] Fix $m\in\mathbb{N}$, $c\in(0,m+1)$, and $K,L\in\mathbb{N}_0$ such that $K+L\geq 1$. Let $\mathbf x$ be a choice sequence that satisfies Assumption~$\hyperref[ass:A]{\mathbf{x}}$ for some $\varepsilon<1-c/(m+1)$ in Part~(item:hI of the paper) and some $\eta<1-c/(m+1)$ in Part~(item:Jn of the paper).  Let $i=i(n),i'=i'(n)$ and $j=j(n),j'=j'(n)$ be integers such that $i<i'$ and $j<j'$ for all $n$, $i+\lfloor\log_\theta (A_n)\rfloor\geq 0$ and $j+\lfloor\log_\theta F_n\rfloor\geq 0$ for all $n$, and 
\begin{equation} 
\limsup_{n\to\infty} \frac{\log_\theta (A_n)+i'}{h_n^+}<c\qquad\text{and}\qquad \limsup_{n\to\infty} \frac{\log_\theta(F_n)+j'}{\log F_n}<c.
\end{equation} 
Then, there exists $\alpha\in(0,1)$ such that for any non-negative integers $b_i,\ldots, b_{i'}$ and $c_j,\ldots, c_{j'}$ such that $b_i+\cdots+b_{i'}=K$ and $c_j+\cdots+c_{j'}=L$, we have 
\begin{equation}\begin{aligned} 
