{"assumptions":[],"created_at":"2026-10-27T15:32:35.596007+00:00","domain":"probability theory","id":"claim_2659c5b6b7ca1a852c81144e2132cff2edd603c51af6b027a68bd06f7fa40259","kind":"concept","schema_version":1,"statement":"[Theorem eq:asymptsaddlepoint of arXiv:2606.06187, 'How to Study Reflected Brownian Motion in a Quadrant via Kernel Functional Equations?\\ \m'] The Green function ${g}(\rho \cos \omega,\rho \sin \omega)$ has the following asymptotics as $\omega\to\omega_0\in(0,\beta)$ and $\rho\to\infty$, for any $n\in\mathbb{N}$:
\begin{itemize}
\item If $\omega^{*}<\omega_0<\omega^{**}$ then
\begin{equation}
{g}
(\rho \cos \omega,\rho \sin \omega)
\underset{\rho\to\infty \atop\omega\to\omega_0}{\sim}
e^{-2\rho|\widetilde{\mu}| \sin^2 \left( \frac{\omega-\theta}{2} \right)} \frac{1}{\sqrt{\rho}}
  \sum_{k=0}^n \frac{\widetilde{c_k}(\omega)}{ \rho^{k}}

  \end{equation}
\item If $\omega_0<\omega^*$ then
\begin{equation}
{g}
(\rho \cos \omega,\rho \sin \omega)
\underset{\rho\to\infty \atop\omega\to\omega_0}{\sim}
c^{*} e^{-2\rho|\widetilde{\mu}| \sin^2 \left( {\omega+\delta-\theta} \right)}
+
e^{-2\rho|\widetilde{\mu}| \sin^2 \left( \frac{\omega-\theta}{2} \right)} \frac{1}{\sqrt{\rho}}
  \sum_{k=0}^n \frac{\widetilde{c_k}(\omega)}{ \rho^{k}}

  \end{equation}
\item If $\omega^{**}<\omega_0$ then
\begin{equation}
{g}
(\rho \cos \omega,\rho \sin \omega)
\underset{\rho\to\infty \atop\omega\to\omega_0}{\sim}
c^{**}e^{-2\rho|\widetilde{\mu}| \sin^2 \left( {\omega-\epsilon-\theta} \right)}
+
e^{-2\rho|\widetilde{\mu}| \sin^2 \left( \frac{\omega-\theta}{2} \right)} \frac{1}{\sqrt{\rho}}
  \sum_{k=0}^n \frac{\widetilde{c_k}(\omega)}{ \rho^{k}}

  \end{equation}
\end{itemize}
where $c^*$ and $c^{**}$ are {positive} constants and $c_k(\omega)$ are $\omega$-dependent coefficients such that $\widetilde{c_k}(\omega)\underset{\omega\to\omega_0}{\longrightarrow} \widetilde{c_k}(\omega_0)$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

