    \begin{equation}
        \limsup_{n \to \infty} n^{p/d} \mathbb{E}\left[\W_p^p\left(\hat{g}_n, g\right) \right]\leqslant \beta_{p,d}\int_{(0,1)^d} g(x) f(x)^{-p/d}\mathrm{d} x.
