    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:33:17.715038+00:00","domain":"probability theory","id":"claim_273f429b514f7b06fd41e782704216c2036e484d2fc5eb7b9884555b3ed20d93","kind":"lemma","schema_version":1,"statement":"[Lemma 54 (Inner-localization shell transfer) of arXiv:2607.10813, '2607.10813'] Fix $\chi_{\mathrm{in}},\chi_{\mathrm{out}}\in C_c^\infty(\R^3)$.
Let $N,Q,R,L,M$ denote, respectively, the low--high stochastic, input,
Duhamel-output, outer stochastic, and final-output shells.  Assume
\[
 Q\le c_{\mathrm{ap}}N,
 \qquad L\sim_{\mathrm{ap}}R.
\]
At finite cutoff, every centered block is obtained by covariance pullback
from a finite sum of deterministic coefficient kernels
\begin{equation}
\begin{aligned}
 H_{N,R,L,Q,M}^{t,s}(\ell,r,q,n)
 ={}&\widetilde\rho_N(\ell)\widetilde\rho_L(r)
      \chi_Q(q)\chi_M(n)\\
 &\times\int_{\R^3}\widehat\chi_{\mathrm{in}}(z)
 \widehat\chi_{\mathrm{out}}(n-q-\ell-r-z)\\
 &\qquad\times\varphi_R(q+\ell+z)
 K_a(t-s,q+\ell+z)\,
 \mathfrak a_{N,R,L,Q,M,z}(\ell,r,q,n)\dd z.
\end{aligned}
\end{equation}
Here the tilded factors are the auxiliary plateaux from
\eqref{eq:auxiliary-shell-plateau}.  The stochastic legs are composed with
$\mathsf S_{b,N,s}^{\Lambda}$ and $\mathsf S_{c,L,t}^{\Lambda}$, respectively,
so that
\begin{equation}
 \widetilde\rho_N(\ell)\widetilde\rho_L(r)
 [\rho_Nm_\Lambda](\ell)[\rho_Lm_\Lambda](r)
 =\rho_N(\ell)\rho_L(r)m_\Lambda(\ell)m_\Lambda(r).
\end{equation}
The factor $m_\Lambda$ is omitted when $\Lambda=\infty$, and the deterministic
coefficient kernel is unchanged.  Here $\varphi_R$ is an enlarged shell cutoff
and
\begin{equation}
 \sup_{N,R,L,Q,M,z}
 \|\mathfrak a_{N,R,L,Q,M,z}\|_{L^\infty}\lesssim1.
\end{equation}
The remaining Bony symbols and finite-overlap cutoffs are absorbed into
$\mathfrak a$.  This amplitude is independent of $(t,s)$, and the deterministic
time dependence is displayed in $K_a(t-s,\cdot)$.  The synthesis maps carry
the stochastic shell and spectral-cutoff factors.  The propagated frequency
in \eqref{eq:two-localizer-kernel} is
\begin{equation}
 p=q+\ell+z.
\end{equation}

There is a constant $C_{\mathrm{tr}}>1$, depending only on the
Littlewood--Paley supports and the aperture, such that we write
$R\sim_{\mathrm{tr}}N$ when
$C_{\mathrm{tr}}^{-1}N\le R\le C_{\mathrm{tr}}N$.  Enlarging
$C_{\mathrm{tr}}$ absorbs the finite inhomogeneous exceptions.  This
relation has the following properties.
\begin{enumerate}[label=\textup{(\roman*)}]
\item If $R\sim_{\mathrm{tr}}N$, then, since
$L\sim_{\mathrm{ap}}R$, on the support of
\eqref{eq:two-localizer-kernel},
\begin{equation}
 \la p\ra\sim\la R\ra\sim\la L\ra\sim\la N\ra,
 \qquad
 |K_a(t-s,p)|\lesssim\la N\ra^{-1}.
\end{equation}
Thus the factor
\begin{equation}
 \mathfrak m_z:=\la N\ra\varphi_R(p)K_a(t-s,p)
 \mathfrak a_{N,R,L,Q,M,z}
\end{equation}
has uniformly bounded modulus, uniformly in $z$.

\item If $R\not\sim_{\mathrm{tr}}N$, then for every $A>0$,
\begin{equation}
 \sup_{\substack{|q|\lesssim Q,\ |\ell|\sim N}}
 \int_{\R^3}|\widehat\chi_{\mathrm{in}}(z)|
 \one_{\{\varphi_R(q+\ell+z)\ne0\}}\dd z
 \lesssim_A\la N+R\ra^{-A}.
\end{equation}
For $M\lesssim R$, after covariance pullback the four oriented flattenings
of this transfer tail satisfy, for every $A>0$,
\begin{equation}
 \max_{1\le\varkappa\le4}\|F_{\varkappa,\Lambda,N,R,L,Q,M}^{\sharp}\|_{\mathfrak S_2}
 \lesssim_A
 \la N+R\ra^{-A}
 \la N\ra^{1/2+\beta_b}\la R\ra^{-1/2+\beta_c}\la Q\ra^{3/2}.
\end{equation}
For $M\gg R$ there is, in addition, arbitrary decay in $M$.

\item Let $(t,s),(t',s')\in\Delta_T$ and put
$d_\Delta:=|t-t'|+|s-s'|$.  For every $A>0$ and
$0<\theta\le1/2$, the transfer-tail flattenings satisfy
\begin{equation}
\begin{aligned}
 &\max_{1\le\varkappa\le4}
 \|F_{\varkappa,N,R,L,Q,M}^{\sharp}(t,s)
     -F_{\varkappa,N,R,L,Q,M}^{\sharp}(t',s')\|_{\mathfrak S_2}\\
 &\qquad\lesssim_{A,\theta}
 d_\Delta^\theta\langle N+R\rangle^{-A}
 \langle N\rangle^{1/2+\beta_b}
 \langle R\rangle^{-1/2+\beta_c}
 \langle Q\rangle^{3/2}.
\end{aligned}
\end{equation}
If $F_{\varkappa,\Lambda}^{\sharp}$ denotes the corresponding cutoff flattening,
then
\begin{equation}
 \max_{1\le\varkappa\le4}
 \|F_{\varkappa,\Lambda}^{\sharp}-F_{\varkappa,\infty}^{\sharp}\|_{\mathfrak S_2}
 \lesssim_A
 \langle N+R\rangle^{-A}
 \langle N\rangle^{1/","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:48:45.315584+00:00","domain":"probability theory","id":"claim_2741d30149ec59228b7586d9462f9935cfacecd9d475a93161ad23300c4e7b85","kind":"concept","schema_version":1,"statement":"[Lemma eq:c1 of arXiv:2411.14921, 'A boundary Harnack principle and its application to analyticity of 3D Brownian intersectio'] There exist constants $0<b_1=b_1(\lambda), b_2=b_2(\lambda)<\infty$ such that 
