{"assumptions":[],"created_at":"2026-10-26T19:46:12.278553+00:00","domain":"probability theory","id":"claim_276a160d9fe22bf7e26cfc1b63db2c5a69f8105cc13da1829219c8bd4918fdb5","kind":"definition","schema_version":1,"statement":"[Definition 11 of arXiv:2604.22461, 'Large deviation principles for stationary solutions and invariant measures of a class of S'] For any $t_0 >-\infty$, we define $\sC_{t_0}$ as the space $C(\R;H) \cap  \{ \cap_{N \geq 1} L^2([t_0,N];V) \}$ equipped with the following distance
    \begin{equation*}
         d_{t_0} (X,Y) := \Big(  \sum_{N=1}^{+\infty} \frac{ 1 \wedge \sup_{s\in [-N,N] } \| X_s -Y_s \|_{H}^2 \wedge \int_{-N \vee t_0}^N  \| X_s -Y_s \|_{V}^2 \, \d s}{2^{N}} \Big)^{1/2},
    \end{equation*}
    for all $X,Y \in \sC_{t_0} $.


    The space $\sC_{+\infty}$ is defined as $C(\R;H)$ equipped with the metric
    \begin{equation*}
         d_{+\infty} (X,Y) := \Big(  \sum_{N=1}^{+\infty} \frac{ 1 \wedge \sup_{s\in [-N,N] } \| X_s -Y_s \|_{H}^2 }{2^{N}} \Big)^{1/2},
    \end{equation*}
    for all $X,Y \in \sC_{+\infty} $. For any $t_0 \in [ -\infty, +\infty]$ and $p \geq 1$, we define $L^{p}(\Omega,\sC_{t_0})$ as the space of all random functions lie on $\sC_{t_0}$ with the metric $ |\E |d_{t_0} (\cdot,\cdot)|^{p}|^{1/p} $.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:32:23.773417+00:00","domain":"probability theory","id":"claim_276cba76e27b004905d58c2f4a80ccbd864463237d884aff9e60329fbfa4c63f","kind":"concept","schema_version":1,"statement":"[Thm main of arXiv:2603.25606, 'Stabilization of stochastic networks in Markovian environment'] Let $G=(V,E)$ be a finite, connected, directed graph and let $(\eta_n)_{n\in \mathbb{N}}$ be a stochastic network in a Markovian environment on $G$ which satisfies ((eq:only-local-reduction of the paper)), ((eq:bfb of the paper)) and ((eq:irr of the paper)). Let $M$ be the expected offspring matrix as in (equation eq:expected-toppling-matrix of the paper) and 
$$\alpha=\max\{-M(v,v)\,|\,v\in V\}+1\quad \text{and} \quad
\rho=r(M+\alpha I)-\alpha,$$
 where $r(M+\alpha I)$ is the Perron-Frobenius eigenvalue of $M+\alpha I$.
\begin{enumerate}
\setlength\itemsep{0em}
\item (Subcritical case) If $\rho<0$, then for any initial state $\eta_0:V\to\mathbb{N}_0$, the network stabilizes almost surely.
\item (Critical case) If $\rho=0$, then either there exists a conserved quantity, or the network  stabilizes almost surely for every initial state.
\item (Supercritical case) If $\rho>0$, then there exists an initial state $\eta_0:V\to\mathbb{N}_0$, for which the network does not stabilize with positive probability.
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:40:26.990996+00:00","domain":"probability theory","id":"claim_276cff7dbfd2a71045a09f16cd579bb9421abba351192945c588875bc109c5e8","kind":"lemma","schema_version":1,"statement":"[Lemma lem-distboundshred of arXiv:2604.14318, '\large The free energy of the interacting Bose gas:\\\medskip a variational description \\'] Fix $R\in(0,\infty)$ and $W=W_R=[-R,R]^d$ and $M\in(0,R)$.  Assume that $\Lambda$ is a large centred box.

\begin{enumerate}
\item Fix $m\in\mathbb{N}$ and $l_1,l_2,\dots,l_m\in\mathbb{N}$ such that $\sum_{j=1}^m l_j=k$. Fix $w_1,\dots,w_m\in W$ and $z_1,\dots,z_m\in Z_{N,R}$ such that $z_j\not=z_{j-1}$ for any $j$, where $z_0=z_m$. Then
\begin{equation}
\begin{aligned}
\widehat \mathbb{P}^{\ssup{k,\Lambda,{\rm bc}}}&\Big(\mathfrak  m(B)=m,\forall j=1,\dots,m \colon \tau_{j}-\tau_{j-1}=l_j, B_{l_j \beta}\in {\rm d} ( z_j+w_j)\Big)\\
&=\bigotimes_{j=1}^m p_{z_{j-1}+w_{j-1}}^{\ssup{W,\Lambda,{\rm bc}}}(l_i,z_j+w_j)\,{\rm d} w_j, \qquad z_0=z_m, w_0=w_m.
\end{aligned}
\end{equation}
Furthermore, under  conditioning on the event 
\begin{equation}
A_{m}\big((l_j,w_j)_{j\in[m]}\big)=\{\mathfrak m_R(B)=m,\forall j=1,\dots,m \colon \tau_{j+1}-\tau_j=l_j, B_{l_j \beta}=  z_j+w_j\},
\end{equation}
the shreds $(B_{s +\tau_j\beta})_{s\in [0,l_j\beta]}$ are independent over $j\in\{1,\dots,m \}$ and have distribution $q^\ssup{l_j,W,\Lambda,{\rm bc}}_{ z_{j-1}+w_{j-1}, z_j+w_j}$.

\item For ${\rm  bc}={\rm par}$ and $\widehat \mathbb{P}^{\ssup{k,\Lambda,{\rm par}}}$ restricted to all the legs of $B$ lying in ${\mathcal C }_1^{{{\scriptscriptstyle{({M}})}}}$, we can replace $p^{\ssup{W,\Lambda,{\rm par}}}$ by $p^{{{\scriptscriptstyle{({W,M}})}}}$ and $q^\ssup{l_j,W,\Lambda,{\rm par}}$ by $q^{{{\scriptscriptstyle{({l_j,W,M}})}}}$ in these two statements.

\item For any $z\in Z_{N,R}^\circ$ such that all legs start start in $W_z$ have spread $< M$ and for any $j$ satisfying $z_{j-1}=z$, we may replace $p_{ z_{j-1}+w_{j-1}}^{\ssup{W,\Lambda,{\rm per}}}$ by $p_{ z_{j-1}+w_{j-1}}^{{{\scriptscriptstyle{({W,M}})}}}$ and $q^\ssup{l_j,W,\Lambda,{\rm per}}_{ z_{j-1}+w_{j-1}, z_j+w_j}$ by $q^{{\scriptscriptstyle{({l_j,W,M}})}}_{ z_{j-1}+w_{j-1}, z_j+w_j}$ in these statements.
\end{enumerate}","status":"unverified"}

