{"assumptions":[],"created_at":"2026-10-26T19:21:10.896350+00:00","domain":"probability theory","id":"claim_27b84bd69510df4e7cd52c011dbe13c6292f6810b02b15a65626e301ae8fcfb1","kind":"theorem","schema_version":1,"statement":"[Proposition 47 of arXiv:2508.04938, 'Perfect t-embeddings of doubly periodic Aztec diamonds'] For a non-boundary vertex~$(2\ell x,4y)$ in~$(A_{2\ell N}')^*$ and two functions~$f$ and~$g$, set
\begin{equation*}
I_{f,g}(x,y)=
\frac{1}{(2\pi\i)^2}\int_{\tilde \Gamma_s}\int_{\tilde \Gamma_l}f(z_2)Q(z_2,w_2)Q(z_1,w_1) g(z_1) 
\frac{(z_2-1)^{\ell N}}{(z_1-1)^{\ell N}}\frac{w_2^{x-N}}{w_1^{x-N}}\frac{z_1^y}{z_2^y}\frac{\d z_2\d z_1}{z_2-z_1},
\end{equation*}
where~$\tilde \Gamma_s$ and~$\tilde \Gamma_l$ are as in Lemma~\ref{lem:bdry_bulk}.

Let~$(2\ell x,4y)$ and~$(2\ell x',4y')$ be non-boundary vertices in~$(A_{2\ell N}')^*$, and let~$f$ and~$g$ be as in~\eqref{eq:f_def_2xell} and~\eqref{eq:g_def_2xell}, and~$\bar g(z)=\overline{g(\bar z)}$. Then 
\begin{equation*}
\cT(2\ell x,4y)-\cT(2\ell x',4y')=I_{f,g}(x,y)-I_{f,g}(x',y')
\end{equation*}
and
\begin{equation*}
\cO(2\ell x,4y)-\cO(2\ell x',4y')=I_{f,\bar g}(x,y)-I_{f,\bar g}(x',y').
\end{equation*}","status":"unverified"}

