{"assumptions":[],"created_at":"2026-10-27T15:12:20.561189+00:00","domain":"probability theory","id":"claim_27fc74c58312d09658bf0460fdc44c1ed9d8df7cca249445e79587acfb0cfe0f","kind":"lemma","schema_version":1,"statement":"[Lemma L:PX:LB of arXiv:2604.08129, 'Polarity of points for Gaussian random fields in critical dimension'] There exists a constant $C_0>0$ such that for all $\varepsilon\in(0,1)$, all $n$ of the form $n = 2^p$ for some $p \in {\mathbb N}^+$, and all $t_1, \dots, t_n\in B_{\varepsilon^{\beta}}$,
\begin{align*}

{\mathbb P}\left\{ |X(t_1)| \le \varepsilon, \dots, |X(t_n)|\le \varepsilon\right\} \ge C_0^n \varepsilon^{nd} \frac{1}{\sigma^d(|t_1|)} \prod_{0 \le k < p} \prod_{2^k < i \le 2^{k+1}} \frac{1}{\sigma^d(d(t_i, F_k))}
\end{align*}
provided that
\begin{align}
\sigma(|t_1|) \ge 2^{-p}\varepsilon \, \text{ and } \sigma(d(t_i, F_k)) \ge 2^{k-p}\varepsilon \
    \text{ for  $0\le k < p$ and $2^k < i \le 2^{k+1}$,}
\end{align}
where $F_k = \{t_1, \dots, t_{2^k}\}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:51:11.639636+00:00","domain":"probability theory","id":"claim_27fdf054fa00ff154daf647f909988179212806b44f9e057396e089d5870c747","kind":"definition","schema_version":1,"statement":"[Definition 17 of arXiv:2605.31344, 'Subcritical sharpness for real-valued spin models'] Let $\mu$ be a measure on pairs $(\sfa, \omega) \in (\mathbb{R}^{+})^{\overline{\Lambda}} \times \{0,1\}^{\overline{E}(\Lambda)}$ and recall Definition \ref{Def: increasing}.
    \begin{itemize}
    \item We say that $\mu$ is \textit{weakly monotonic} if $\sfa|_{\partial^{\mathrm{ext}}\Lambda}$ is deterministic and for any $\Lambda' \subset \Lambda$, $E' \subset \{xy \in \overline{E}(\Lambda') : x,y \in \Lambda' \cup \partial^{\mathrm{ext}} \Lambda\}$, and any $\sfa_1, \sfa_2 \in (\mathbb{R}^{+})^{\Lambda'}, \omega_1, \omega_2 \in \{0, 1\}^{E'}$ with $\sfa_1 \leq \sfa_2$ and $\omega_1 \leq \omega_2$ pointwise,
    \begin{equation*}
        \mu[\ \cdot \mid \sfa|_{\Lambda'} = \sfa_1, \omega|_{E'} = \omega_1] \preceq \mu[\ \cdot \mid \sfa|_{\Lambda'} = \sfa_2, \omega|_{E'} = \omega_2].
    \end{equation*}
    \item
    We say that $\mu$ satisfies the FKG inequality if for any increasing square-integrable functions $f, g: (\mathbb{R}^{+})^{\overline{\Lambda}} \times \{0, 1\}^{\overline{E}(\Lambda)} \rightarrow \mathbb{R}$, we have
    $\mu[f \cdot g] \geq \mu[f] \mu[g].$
    \end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:28:04.861759+00:00","domain":"probability theory","id":"claim_27febde53bbeaef2e3c9b1c058964fab26a6fa14d6ed5a26afb21e5e3839892d","kind":"theorem","schema_version":1,"statement":"[Prp 42 of arXiv:2511.21496, 'Optimal local central limit theorems on Wiener chaos'] Let $\mathbf{F} = \{F_n\}_{n \in \N} \subset \cW_m$ with $m \geq 2$ such that $\E[F^2_n] = 1$ and $F_n \xrightarrow[n \to \infty]{d} \cN(0,1)$. 
