\begin{equation}
    \left\lVert \rho_{F_n}^{} - \rho_{\cN}^{} + \frac{\kappa_3(F_n)}{3!} \rho_{\cN}^{(3)} \right\rVert \leq C_{\mathbf{F},k,m,r} \left( |\kappa_{3}(F_n)|^2 + |\kappa_3(F_n)|\kappa_4(F_n) + \kappa_4(F_n) \right) 
\end{equation} 
for all sufficiently large $n$, where $\norm{\cdot} \in \{ \norm{\cdot}_{C_\mathrm{b}^{k}(\R)}, \norm{\cdot}_{W^{k,r}(\R)} \}$ and $C_{\mathbf{F},k,m,r}$ is a constant depending on $\mathbf{F}$, $k$, $m$, and $r$, but not on $n$.","status":"unverified"}

