{"assumptions":[],"created_at":"2026-10-28T02:56:14.353491+00:00","domain":"probability theory","id":"claim_289ceb003eed08a698a604fde12edf0f49acd0e7acc48457e4f835c55cc1898b","kind":"lemma","schema_version":1,"statement":"[Lem inequality_mark_variance of arXiv:2412.10001, 'On the Markov transformation of Gaussian processes'] Consider a continuous semi-definite positive kernel $K : \mathbb{R}^2 \to \mathbb{R}$ such that $K(t,t) = 1$ for every $t \in \mathbb{R}$. Fix $a<b \in \mathbb{R}^2$ and denote by $P$ a centered Gaussian measure with covariance function $K.$

		\begin{enumerate}
			\item Assume, for every $s<t \in \mathbb{R}^2$, 
			\begin{equation}
				\sup_{v \in [s,t]} \left|L_v^K(h) - \alpha^K(v) \right| \xrightarrow[h \to 0^+]{} 0.
			\end{equation} 
		Then \[ \forall (R_n)_{n \geq 1} \in \mathcal{A}, \exists M \in \mathbb{R}_+, \forall (s,t) \in [a,b]^2,\forall n \geq 1, 1- K_n(s,t) \leq M|s-t|,\] where $K_n$ stands for the covariance function of $P_{[R_n]}.$
			\item Assume  $K : (s,t) \mapsto \tilde{K}(t-s)$ is a stationary kernel, $ \alpha \in \mathbb{R}_+$ is a cluster point of $L^K : h \in \mathbb{R}_+^* \mapsto h^{-1}(1- \tilde{K}(h)) $ and $L^K$ is bounded. Fix a positive sequence $(s_n)_{n \geq 1}$  converging to zero such that $\lim_{n \to + \infty} L^K(s_n) = \alpha$ and put $(R_n)_{n \geq 1} := \left( \left( s_n \cdot \mathbb{Z} \right) \cap [-n,n] \right)_{n \geq 1} \in \mathcal{A}$.  Then, \[\exists M \in \mathbb{R}_+,\forall (s,t) \in [a,b]^2, \forall n \geq 1, 1- K_n(s,t) \leq M|s-t|,\]
			where $K_n$ stands for the covariance function of $P_{[R_n]}.$ 
		\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:20:33.747236+00:00","domain":"probability theory","id":"claim_289f2d66d670b84ca229bd8b5e1f76cc4f464ea81bcfb341fd90d74a66f0f160","kind":"concept","schema_version":1,"statement":"[Thm 2 (Microscopic hop-count LLN and CLT) of arXiv:2607.28865, 'First-Passage Percolation on Spread-out line graphs: Microscopic Regime'] Assume that $\ell\ge2$ is fixed and $\go$ is not deterministic. For integers $a<b$, let $H^{(\ell)}(a,b)$ denote the minimum number of edges among all geodesics from $a$ to $b$ in the $\ell$-spread-out line graph. Then
\begin{align}
    \frac1n\cdot {H^{(\ell)}(0,n)}\to \mu_{\mathrm{Hop}}
    \text{ a.s.~and }
    \frac1n\cdot {\E H^{(\ell)}(0,n)}\to \mu_{\mathrm{Hop}}
\end{align}
for some constant $\mu_{\mathrm{Hop}}\in(0,\infty)$.
Moreover,
\begin{align}
    n^{-1/2}\cdot (H^{(\ell)}(0,n)-n\cdot \mu_{\mathrm{Hop}})
    \Longrightarrow 
    \N(0,\gs^2_{\mathrm{Hop}}),
\end{align}
where $\gs^2_{\mathrm{Hop}}$ is a positive constant given in~\eqref{eq:hop-var-def}. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:59:25.048436+00:00","domain":"probability theory","id":"claim_28a06cc9064f7df4b291197d754105ec1a1ce36edc8b4faf1c5cd33c7c4bdce4","kind":"concept","schema_version":1,"statement":"[Mylem 3 of arXiv:2607.00495, 'Rank deficiency of Bernoulli random matrices for growing corank'] Let $X_{1},\dots,X_{n}$ be independent non-negative random variables
\begin{itemize}
    \item Assume that there exist $\eta >0$ and $ \tau >0$ such that $\mathbb{P}( X_{j} \le \eta) \le \tau$. Then for all $\varepsilon \in (0,1]$,
    \begin{align*}
        \mathbb{P}\left( \sum_{j=1}^{n} X_{j} \le \eta \varepsilon n \right) \le \left( \frac{e}{\varepsilon} \right)^{\varepsilon n} \tau^{n-\varepsilon n}.
    \end{align*}
\item  Assume that there exist $M$, $m> 0$ and $s_{0} \ge 0$ such that $\mathbb{P}\left(X_{j}\le s\right)\le \left(Ms \right)^{m}$ for all $s\ge s_{0}$. Then
\begin{align*}
\mathbb{P}\left(\sum_{j=1}^{n}X_{j} \le n s\right)\le \left(C_{\ref{Tenzorization}}M s\right)^{mn}\quad ~\text{for all}~~ s\ge s_{0},
\end{align*}
where $C_{\ref{Tenzorization}}$ is a constant.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:07:35.010265+00:00","domain":"probability theory","id":"claim_28a09ccd8d0cfa7951aeac3151b1b67312609e54192cf94e121d9a39e6f10263","kind":"theorem","schema_version":1,"statement":"[Proposition 12 of arXiv:2609.02850, 'Canonical-row Chern flow on Bott--Samelson towers:\\ realizable-volume models for Schubert'] Let $\beta\in\NN^n$, put $m=d-|\beta|\ge0$, and let
$0\le e\le m$.  For any $i,j,k\in[n]$,
\begin{equation}
 \binom{m}{e}
