			\begin{align}
				\E_x\left[\int_0^{\tau_c^-}e^{-qt-A_t}f(X_t)dt\right]=\int_c^{\infty}f(y)\left(c^{(q)}_{{\mathbf{T}}(\nu_A)}(y,c)W_{{\mathbf{T}}(\nu_A)}^{(q)}(x,c)-W_{{\mathbf{T}}(\nu_A)}^{(q)}(x,y)\right)dy.
			\end{align}}
			{Additionally, we have that $c^{(q)}_{{\mathbf{T}}(\nu_A)}(y,c)<\infty$ for every $y\geq c$.} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:25:12.194482+00:00","domain":"probability theory","id":"claim_28fc2418d3c1493e2be3330b39ed4939785fe4c53c74660b1be09476dae8c5dc","kind":"concept","schema_version":1,"statement":"[Lem 10 (\hspace{-0.05em}{{\cite[Lemma~2.2) of arXiv:2510.22783, 'Universality of Cutoff for Riffle Shuffling'] {csiszár2004information}}}]

		For any fixed $A>0$ and any non-negative real numbers $a_0,a_1,\ldots a_{k-1} \in [0,A]$, satisfying $a_i\log N \in \mathbb{Z}$, 
		\begin{equation*}
			N^{a_{\tot} H(a_0,\dots,a_{k-1})-o_N(1)}\leq \binom{a_{\tot}\log(N)}{a_0\log(N),\dots,a_{k-1}\log(N)}\leq N^{a_{\tot} H(a_0,\dots,a_{k-1})},
		\end{equation*}
		where the term $o_N(1)$ tends to $0$ for any fixed $A$ as $N\to\infty$, uniformly in $a_0,\dots,a_{k-1}\in [0,A]$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:20:15.681439+00:00","domain":"probability theory","id":"claim_2900c7e8e8ba7fb400d7af51aef21bd576aa8b7858ac6b2a8d5cd566ca767b48","kind":"concept","schema_version":1,"statement":"[Lemma lem:cada-closure of arXiv:2609.00944, 'The Ramsey threshold for trees versus odd cycles'] If $G$ is a graph of order $N$ and $u,v$ are nonadjacent vertices with
$d_G(u)+d_G(v)\ge N$, then, for $G'=G+uv$, the following equivalence holds
for every $A\subseteq V(G)$ and every integer $1\le k\le |A|$:
$G$ has a cycle $C$ with $|V(C)\cap A|\ge k$ if and only if $G'$ does. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:35:19.872250+00:00","domain":"probability theory","id":"claim_29012b5d10bcdcf4f75a44e9cc21791a4c136f971819d453381b71d9e0320f10","kind":"concept","schema_version":1,"statement":"[Theorem thm:eta of arXiv:2608.24963, 'Why and When Neural Networks Improve Local Approximation in Optimization'] Let $f$ be bounded below (Assumption~(ass:lower_bounded of the paper)) with $L$-Lipschitz gradient, let
\[
T(\epsilon):=\inf\{k\in\mathbb{N}:\ \left\lVert \nabla f(x_k) \right\rVert_2\le\epsilon\},
\]
and let $t_k$ be the number of successful surrogate steps taken at outer iteration $k$. Define the \emph{average} number of successful surrogate steps per outer iteration over the first $T$ iterations,
\begin{equation}
S(T):=\frac{1}{T}\sum_{k=0}^{T-1}t_k ,
\end{equation}
and the surrogate gain
\begin{equation}
\eta(S)=\frac{1+\frac{S}{2(n+1)}}{1+S}.
\end{equation}
Then the number $FE(\epsilon)$ of evaluations of $f$ required by the surrogate-augmented method satisfies
\begin{equation}
FE(\epsilon)\ \le\ 4\,\eta\!\left(S(T(\epsilon))\right)(n+1)\,C_{\max}\,(f(x_0)-f_{\mathrm{low}})\,\epsilon^{-2}
\;+\;\log_2\!\left(\tfrac{\sigma_{\max}}{\sigma_0}\right)(n+1)\;+\;T(\epsilon),
\end{equation}
with $\sigma_{\max}$ and $C_{\max}$ the problem constants defined in [Taminiau2025Arxiv2502]. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:25:45.010846+00:00","domain":"probability theory","id":"claim_2903bc33db66f859d2c79a6b558432e6d51d9f23c5549069259d73263b5b1c05","kind":"theorem","schema_version":1,"statement":"[Corollary 38 of arXiv:2605.11801, 'A non-local singular non-linear Fokker-Planck PDE'] Suppose $B \in C_T \shc^{-\beta}$ and $v_0 \in \shc^{\beta+}$.
  Let $v$ be the solution  to the Fokker-Planck PDE  \eqref{eq:FPlimBis}
  such that $v_0$ is non-negative $\|v_0\|_{L^1}=1$.
    Then $v$ preserves non-negativity and conserves the mass in the sense that
  $\|v(t)\|_{L^1}=1$ for each $t\in[0,T]$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:04:55.816399+00:00","domain":"probability theory","id":"claim_2904dec4c48c0e2c45390d101bba73051816405a3a1e4e7dfd9f557ef8464b12","kind":"concept","schema_version":1,"statement":"[Thm t:def-YM-general of arXiv:2607.24640, 'The Yang-Mills measure on surfaces via Morse theory'] There exists a finitely additive functional 
$$
\mathbb{M}_{\operatorname{YM}}:\mathcal{B}_\infty^G\rightarrow \mathbb{R}_+
$$
such that the following holds
 \begin{enumerate}
  \item for all $n\geqslant 1$, $\mathbb{M}_{\operatorname{YM}}$ is a measure on $(\Omega\times G^{2g},\mathcal{B}_n^G)$;
  \item  for every continuous and piecewise $\mathcal{C}^1$ curve $\gamma:[0,1]\rightarrow \Sigma$ that is everywhere transverse to $V$, one can find a random variable $\mathbf{Hol}(\gamma)\in G$ such that, for every $n\geqslant 1$,  
  $$
  \gamma([0,1])\subset K_n\ \Longrightarrow\ \mathbf{Hol}(\gamma)\ \text{is}\ \mathcal{B}_{n}^G-\text{measurable}
  ,$$ 
  and, for every admissible disk $D$, the law of $\mathbf{Hol}(\partial D)$ is given by
  $$
  \boxed{\mathbb{M}_{\operatorname{YM}}\left(\mathbf{Hol}(\partial D)\in d\mathrm{g}\right)=\left(\sum_{\rho\in\widehat{G}}\frac{e^{-\frac{c_2(\rho)}{2}\upsilon(\Sigma\setminus D)}}{\left(\operatorname{dim} V_\rho\right)^{2g-1}}\chi_\rho(\mathrm{g})\right)\left(\sum_{\rho\in\widehat{G}}\operatorname{dim} V_\rho e^{-\frac{c_2(\rho)}{2}\upsilon(D)}\chi_\rho(\mathrm{g})\right)\mu_G(d\mathrm{g}),}
  $$
  where $\rho:G\rightarrow \operatorname{GL}(V_\rho)$ runs over the equivalent classes $\widehat{G}$ of unitary irreducible representations of $G$, $c_2(\rho)$ is the Casimir number of $\rho$ and $\chi_\rho$ is the character of $\rho$.
 \end{enumerate}
 In particular, the partition function is given by
  $$
  \boxed{Z_{\operatorname{YM}}:=\mathbb{M}_{\operatorname{YM}}(\Omega\times G^{2g})=\sum_{\rho\in\widehat{G}}e^{-\frac{c_2(\rho)}{2}\upsilon(\Sigma)}\left(\operatorname{dim} V_\rho\right)^{2-2g}.}
  $$ (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:52:47.244979+00:00","domain":"probability theory","id":"claim_29070aa7cd7ad505a162772a263514902082cbcd022bdd26243ce0b7777f2287","kind":"lemma","schema_version":1,"statement":"[Lemma 21 (the map is a contraction) of arXiv:2609.01093, 'Ideal MHD below the classical well-posedness threshold'] With $T_*$ chosen by \eqref{eq:Tstar}, the map $\mathcal M$ satisfies
\begin{equation}
 \|\mathcal M\Ufield-\mathcal M\Vfield\|_{\mathcal Y}
 \le C_\delta T^\varepsilon R(1+R)
       \|\Ufield-\Vfield\|_{\mathcal Y}
 \le\tfrac12\|\Ufield-\Vfield\|_{\mathcal Y}
\end{equation}
for all $\Ufield,\Vfield\in\mathcal U_{R,\delta}$ and every $T\le T_*$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:30:24.614262+00:00","domain":"probability theory","id":"claim_29078015a90b2a6ce4bb2b36b606241e2b02ded5b24d9ff55ff57f33731ba34c","kind":"definition","schema_version":1,"statement":"[Definition 4 of arXiv:2506.09462, 'Transition Path Theory For L\'{e}vy-Type Processes: SDE Representation and Statistics'] The \textbf{$AB$-transition exit distribution} on \(\bar{A} \cap (\partial A + 1)\) and the \textbf{$BA$-transition exit distribution} on \(\bar{B} \cap (\partial B + 1)\) are defined as follows:  
\begin{equation}
    \begin{aligned}
        &\eta^-_A(\d x) = \frac{1}{v^-_A}\rho(x)\mathcal{L}q(x), \quad x \in \bar{A} \cap (\partial A + 1),\\
        &\eta^-_B(\d x) = \frac{1}{v^-_B}\rho(x)\mathcal{L}q(x), \quad x \in \bar{B} \cap (\partial B + 1),
    \end{aligned}
\end{equation}
where \(v^-_A\) and \(v^-_B\) are normalizing constants such that \(\eta^-_A\) and \(\eta^-_B\) define probability measures on \(\bar{A} \cap (\partial A + 1)\) and \(\bar{B} \cap (\partial B + 1)\), respectively.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:56:14.260618+00:00","domain":"probability theory","id":"claim_290abb563874eaebf9d506f86806fa6c665783506b47e979489613f71c8a5c89","kind":"definition","schema_version":1,"statement":"[Defn def:ifs of arXiv:2412.09535, 'Local limit theorem for joint subgraph counts'] Given downwards closed $\mathcal{H}$, an integer $n$, and some $\eta > 0$, a collection of statistics $\mathcal{F} = (F_H)_{H \in \mathcal{H}}$, where $F_H \in \mathcal{R}_{\mathcal{H},n}$ for all $H \in \mathcal{H}$, is an \vocab{$(\mathcal{H}, n, \eta)$-integral factor system} (abbreviated \vocab{$(\mathcal{H}, n, \eta)$-IFS} or \vocab{IFS} if the parameters are unimportant) if for all $H \in \mathcal{H}$, in $\mathcal{R}_n$ we can write
\[F_H = \sum_{\mathrm{NIV}~\mkern-5mu H' \preceq H} a_{H'} X^*_{H'} = \sum_{\mathrm{NIV}~\mkern-5mu H' \preceq H} b_{H'} \gamma^*_{H'} = \sum_{\mathrm{NIV}~\mkern-5mu H' \preceq H} c_{H'} \gamma_{H'},\]
where
\begin{cond}
\item  all $a_{H'}$ are integers and $a_H = 1$;
\item  $\abs{b_{H'}} \leq \eta n^{(v(H) - v(H'))/2}$ for all $H'$ and $b_H = (p(1-p))^{e(H)/2}$;
\item  $\abs{c_{H'}} \leq \eta n^{(v(H) - v(H'))/2}$ for all $H'$ and $c_H = (p(1-p))^{e(H)/2}$.
\end{cond}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:58:28.470305+00:00","domain":"probability theory","id":"claim_290f6629b376b6170491625f6f3c37f8805bf20632dcead3f469066b83f34ab7","kind":"lemma","schema_version":1,"statement":"[Lemma 29 ($L^2$-regularity of the Wick exponential) of arXiv:2606.29292, 'Intrinsic Gaussian Tensor Geometry and Random Operator Spectra'] For $h,k\in\cH$,
\begin{equation}

  \E\bigl[\mathcal E_W(h)\mathcal E_W(k)\bigr]
  =\exp\bigl(\ip{h}{k}_{\cH}\bigr).
\end{equation}
If $h_1,\ldots,h_q\in\cH$, then
\begin{equation}

  t\longmapsto
  \mathcal E_W\!\left(\sum_{\nu=1}^q t_\nu h_\nu\right),
  \qquad t\in\R^q,
\end{equation}
is a smooth map from $\R^q$ to $L^2(\Omega)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:10:08.726206+00:00","domain":"probability theory","id":"claim_29111cd1b0d0713765b7eeac0b348f5d72fe6088b2a779e7ce99d128454671bb","kind":"concept","schema_version":1,"statement":"[Lemma structureH-1 of arXiv:2411.17653, 'Exclusion processes with non-reversible boundary: hydrodynamics and large deviations'] A linear functional $L:H_0^1(f)\to\mathbb{R}$ belongs to $H^{-1}(f)$ if, and only if, there exists $P\in L^2(1/f)$ such that 
    \begin{equation*}
        L(H)=\int_0^T\int_0^1 P_t\;\nabla H_t\;dx\;dt,
    \end{equation*}
    for every $H\in C_{c}^{\infty}(\Omega_T)$. In this case, 
    \begin{equation*}
        ||L||^2_{-1,f}=\int_0^T\{\langle P_t, P_t\rangle_{f(t)^{-1}}-c_t\}\;dt,
    \end{equation*}
    where $c_t=\{\langle P_t/f_t\rangle^2\;/\;\langle 1/f(t)\rangle\}\mathds{1}\{\langle 1/f(t)\rangle<\infty\}$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T21:02:38.597714+00:00","domain":"probability theory","id":"claim_291434e11a4cb5d6552317b5282a5d9210d79a237cf396e0a478df5ed65d6636","kind":"concept","schema_version":1,"statement":"[Proposition 19 of arXiv:2607.07283, 'Multi-time Markov renewal chains and stratified renewal theorems'] For $x\in C$,

