{"assumptions":[],"created_at":"2026-10-26T19:32:58.355955+00:00","domain":"probability theory","id":"claim_298be4e5d49e992dc1e373e64763837decb8687b9892844eb343f28d1a3367f1","kind":"concept","schema_version":1,"statement":"[Proposition 2 of arXiv:2506.18313, 'A stochastic model for the diffusion of competing opinions with trend-following, oppositio'] For any $n\ge 1$, we have
\begin{equation}

 \dE[(N_n,M_n)] = \dE(N_n)(1,-1)+T_n(0,1)
\end{equation}
and
\begin{equation}

 \dE[(N_n,M_n)^T(N_n,M_n)] = \dE(N_n^2)\left(\begin{array}{cc}
1 & -1 \\
-1 & 1 
\end{array}
\right)+T_n\dE(N_n)\left(\begin{array}{cc}
0 & 1 \\
1 & -2
\end{array}
\right)
+T_n^2\left(\begin{array}{cc}
0 & 0 \\
0 & 1
\end{array}
\right),
\end{equation}
where
\begin{equation}

 \dE[N_n] = \frac{(\theta+T_0)_n}{(T_0)_n}\left(N_0-\frac{a}{1-\theta} T_0\right)+\frac{a}{1-\theta}T_n,
\end{equation}
and
\begin{eqnarray}

 \dE[N_n^2]  = \frac{(2\theta+T_0)_n}{(T_0)_n}\Bigg[ N_0^2+  \frac{1}{(2\theta+T_0)}\left( N_0 - \frac{a}{1-\theta}T_0\right) \left[ (2a-1)T_0+(\theta+T_0)\left(\frac{2a(2\theta+T_0)}{(\theta-1)} \right) \right] \notag \\
+  \frac{a(1-2a)}{(1-\theta)(2\theta-1)} \left(T_0 -  \frac{(T_0)_{n+1}}{(2\theta+T_0)_n}\right)- \frac{a^2}{(1-\theta)^2} \frac{\Gamma(T_0+2)}{\Gamma(T_0)} \left(1-\frac{(T_0+2)_{n-1}}{(2\theta+T_0)_{n-1}} \right)  \notag\\
- \frac{(\theta+T_0)}{(2\theta+T_0)}\left( N_0 - \frac{a}{1-\theta}T_0\right) \left[ (2a-1)\frac{(\theta+T_0+1)_{n-1}}{(2\theta+T_0+1)_{n-1}}+ \frac{2a}{\theta-1}\frac{(\theta+T_0+1)_{n}}{(2\theta+T_0+1)_{n-1}}\right]  \Bigg].
\end{eqnarray} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:57:51.751719+00:00","domain":"probability theory","id":"claim_298c3be7b165ecb445db8abf689b13dfb6a8b7c5dc1c23d72b46d147cf42c36e","kind":"concept","schema_version":1,"statement":"[Lemma 6 of arXiv:2608.30155, 'Gradient Estimates Near the Natural Exponent for Very Weak Solutions to $A_p$-Weighted Qua'] \cite[Lemma 6.1]{G03}
