			\eps^{2d}
			\sum_{x \in \eps\Zd}
			\sum_{\substack{z \in \eps\Zd \\ \eps 3^k \le \|z\|_\infty < \eps 3^{k+1}}}
			J(z)\bigl(h(x{+}z) - h(x)\bigr)^2\,.
		\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:23:05.283509+00:00","domain":"probability theory","id":"claim_29bb13e07e0344f8b0375b1a03a80d2a7d07907ef5f4c13ad1cc56777f7d64a0","kind":"concept","schema_version":1,"statement":"[Theorem 7 (Finite-prefix certification theorem) of arXiv:2608.21496, '2608.21496'] For integers $N>m\ge1$, the worst-case bounded-reliability identified width in Eq.~\ref{eq:worstwidthdefinition} is exactly
\begin{equation}
W_{m,N}=B_{m,N}.

\end{equation}
Define two complete joint candidate laws $P_\pm$ by
\begin{equation}
\begin{aligned}
U_\pm&\sim\mathrm{Unif}(0,1),\\
T_\pm\mid U_\pm=u&\sim\mathrm{Bernoulli}\{f_\pm(u)\},\\
f_\pm(u)&=\frac{1\pm\sigma_m(u)}2,
\end{aligned}

\end{equation}
and take candidate sequences iid under each law. These worlds satisfy $\theta_n^+=\theta_n^-=1/2$ for every $n\le m$, but
\begin{equation}
\theta_N^\pm=\frac{1\pm B_{m,N}}2.

\end{equation}
At the common evidence $(\theta_1,\ldots,\theta_m)=(1/2,\ldots,1/2)$, the identified set is exactly
\begin{equation}
\left[\frac{1-B_{m,N}}2,\frac{1+B_{m,N}}2\right];

\end{equation}
every interior value is attained by the iid candidate law with $U\sim\mathrm{Unif}(0,1)$ and $T\mid U=u\sim\mathrm{Bernoulli}\{\lambda f_+(u)+(1-\lambda)f_-(u)\}$ for some $\lambda\in[0,1]$. Consequently Eq.~\ref{eq:exactfrontier} is the full worst-case identified width, not only a lower bound. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:25:49.867107+00:00","domain":"probability theory","id":"claim_29bfe9348d0930c5530f62bf5c6f297325e1d82c966b048ced36d89907bf3878","kind":"definition","schema_version":1,"statement":"[Definition 6 (Weak solution) of arXiv:2609.02022, 'Well-Posedness for SDEs with Logarithmical Critical Distributional Drifts'] Let $\mathfrak F:=(\Omega,\sF,(\sF_t)_{t\geq0},\bP)$ be a stochastic basis, and let $(X,W)$ be a pair of $\mR^d$-valued continuous $\sF_t$-adapted processes on $\mathfrak F$. We call $(\mathfrak F,X,W)$ a weak solution of SDE \eqref{SDE} with initial distribution $\mu\in\sP(\mR^d)$ if $W$ is an $\sF_t$-Brownian motion, $\bP\circ X_0^{-1}=\mu$, and
\begin{align}
    X_t=X_0+A_t^b+\sqrt{2}W_t,\  t\in[0,T],\ a.s.,\no
\end{align}
where $A_t^b:=\lim_{n\to\infty}\int_0^t b_n(s,X_s)\dif s$ exists in the $L^2$-sense.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:55:56.995072+00:00","domain":"probability theory","id":"claim_29c1b98b23650b400aa202f1b7a6db714e5d54b0692822df14ef457147445c02","kind":"lemma","schema_version":1,"statement":"[Lemma 3 (Boundedness of $\P_{\mathrm{K}}$) of arXiv:2609.02784, 'Maximizing the fundamental Laplace--Neumann \\ eigenvalue on quadrilaterals'] Define the ellipsoidal set
\begin{equation}
P_\mathrm{E} \;:=\; \left\{ \p \in \mathbb R^4 \colon
\bigl(1 + |a|\bigr)^2 \;+\; b^2 \;+\; c^2 \;+\; d^2 \;\leq\; T \right\}
\end{equation}
and the axis-aligned box
\begin{equation}

P_\mathrm{C} \;:=\; \left\{ \p \in \mathbb R^4 \colon  |a| \leq \alpha,\;\; |b|,\, |c| \leq \beta,\;\; |d| \leq \delta \right\},
\end{equation}
with
$\alpha = \bigl(\tfrac{T}{2} - 1\bigr)^{1/2}\approx 0.415$,
$\beta = \tfrac{1}{2}\bigl(\sqrt T - 2 + \sqrt{T + 4\sqrt T - 4}\bigr) \approx 0.822$, and
$\delta = \bigl(\tfrac{T}{2}\bigr)^{1/2} - 1  \approx 0.083$.
Then $\P_{\mathrm{K}} \subset P_{\mathrm{E}}$ and $\P_{\mathrm{K}} \subset P_{\mathrm{C}}$. In particular, $\P_{\mathrm{K}}$ is compact.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:38:23.623186+00:00","domain":"probability theory","id":"claim_29c28d09b63dbed05e5ba465fc0d3e847d95767d783ea7554ec085baaaf3cfe7","kind":"concept","schema_version":1,"statement":"[Theorem EHI:t:BerryEsseen of arXiv:2511.08956, '\textbf{Towards a characterization of elliptic Harnack inequality for jump processes}'] Let $(\xi_i)_{i \in I}$ be an independent collection of random vectors in $\mathbb{R}^d$, each with mean $0$. Assume that $\mathrm{Var}(\sum_{i \in I} \xi_i) = \sigma^2 I_d$, where $\sigma>0$. Let $Z$ be a standard multivariate Gaussian (with mean $0$ and variance $I_d$). Then for all measurable convex sets $A \subseteq \mathbb{R}^d$,
    \begin{equation*}
        \left| \mathbb{P}\left( \sum_{i \in I} \xi_i \in A \right) - \mathbb{P}\left( \sigma Z \in A \right) \right| \leq C_{BE} \cdot \frac{\sum_{i \in I} \mathbb{E}|\xi_i|^3}{\sigma^3},
