{"assumptions":[],"created_at":"2026-10-27T18:51:26.696779+00:00","domain":"probability theory","id":"claim_29dafe3ad9308dd11dd9b520a20ad5e087b0ee82346f8d351ef806273a79fbf4","kind":"theorem","schema_version":1,"statement":"[Proposition prop:CE-meso of arXiv:2606.06612, 'The limit shape and emergence of the \\ Discrete Gaussian level lines'] Fix $n\geq 0$ and $g\geq 0$. There exists $\beta_0$ such that the following holds for all $\beta\geq \beta_0$. Let $V\subset \mathbb Z^2$ be a connected domain with $g$ holes, and consider the \ensuremath{\mathbb Z\textsc{gff}}\xspace model $\pi_{V;F}^{\eta}$ with a floor at $0$ imposed only on a subset $F\subset V$, and boundary conditions $\eta$ that are $H+1-n$ on a $*$-connected path in $\partial_{\mathtt v} V$ and $H-n$ elsewhere so that they induce a unique disagreement polymer $(\gamma,\{D_i\},\{h_i\})$ in $V\cup \partial_{\mathtt v} V$ that contains boundary disagreements. Further suppose $|\partial_{\mathtt v} F|\vee |\partial_{\mathtt v} V| \leq  O(L^{2/3}e^{\sqrt{\log L}})$, denote by $D_0$ and $D_1$ the regions of $\gamma$ containing the boundary vertices of $V$ at heights $H+1-n$ and $H-n$, respectively, and let
		\begin{align*} \ensuremath{\mathcal G}&:=\left\{|\gamma|\leq L^{2/3}e^{\sqrt{\log L}}\right\}\,,\\
        \ensuremath{\mathcal G}^\dagger &:= \ensuremath{\mathcal G} \cap \left\{\max_{i\geq 2} |\partial D_i| < \log L \right\}\,.\end{align*}
        Then 
        \begin{align}
        \pi_{V;F}^\eta( \ensuremath{\mathcal G}^\dagger \mid \ensuremath{\mathcal G}) &= 1-o(1)\,,\\

			\pi^\eta_{V;F}(\gamma \mid \ensuremath{\mathcal G}^\dagger) &=(1+o(1))\mathfrak{q}_{V;F}^{\eta}(\gamma)\quad\mbox{uniformly over all} \quad \gamma\in \ensuremath{\mathcal G}^\dagger\,,
		\end{align}
        where $\mathfrak{q}_{V;F}^\eta$ is the probability distribution on $\gamma\in\ensuremath{\mathcal G}^\dagger$ given~by 
		\begin{equation*}
        \mathfrak{q}_{V;F}^{\eta}(\gamma) := 
		\frac1{Z^\eta_{V;F}} \exp\bigg(-{\ensuremath{\mathscr E}}^*_\beta(\gamma) + \frac{\uprho_{n}}{N_n}|D_0\cap F|+ \mathfrak{I}_V(\gamma) \bigg)
		\end{equation*}
        with $N_n$ from (eq:Nn-def of the paper), $\mathfrak{I}_V$ from (eq:IU(gamma)-def of the paper), $\uprho_{n}$ from (eq:rho-n-def of the paper), and a normalizer $Z^\eta_{V;F}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:44:24.696062+00:00","domain":"probability theory","id":"claim_29dfee7e806b9377fd54ed8a51eab1755c273a302aec97ecd96fd7d1b710403f","kind":"lemma","schema_version":1,"statement":"[Lemma lem:limit_function_upper_bound of arXiv:2604.20215, '\bf Edge Universality for Inhomogeneous Random Matrices II: Markov Chain Comparison and Cr'] Let $\Gamma$ be a connected typical diagram. Let   $t=\sum_{i=1}^s t_i$,
   the following upper bounds for limiting diagram functions  hold  for some constant $C>0$.
    \begin{enumerate}
    \item[(i)] \textbf{(Supercritical case)}
    \begin{equation}
\mathrm{Vol}_{\mathfrak{C}}(\{t_i\})\le \frac{(Ct)^{|E|}}{(|E|)!}.
\end{equation}
\item[(ii)]  \textbf{(Subcritical case, $\alpha>d=1$)}  For    a chosen vertex $v_0$ and   $x_{v_0}=0$,
\begin{equation}
    \int_{x_v\in \mathbb{R}^d, v\ne v_0}\int_{\mathfrak{C}(\{t_i\})}
    \prod_{e\in E(\Gamma)}f_{\alpha}(x_{e}-y_{e},\alpha_e ) \prod_{e\in E(\Gamma)}d\alpha_e \prod_{v\in V(\Gamma),v\neq v_0}dx_v\le \frac{(Ct)^{|E|-\frac{1}{\alpha}(|E|-|V|+1)}}{(|E|-\frac{1}{\alpha}(|E|-|V|+1))!}.
\end{equation}
Here, $x_e$ and $y_e$ denote the variables $x_u$ and $x_v$ associated with the endpoints of the edge $e=\{u,v\}$.
\item[(iii)] \textbf{(Critical case, $\alpha>d=1$)}
   For some constant  $C_{\tau}$ depending on  $\tau>0$, \begin{equation}
    \begin{aligned}
    &\int_{x_v\in \mathbb{T}^d}\int_{\mathfrak{C}(\{t_i\})}
    \prod_{e\in E(\Gamma)}\theta_{\alpha}(x_{e}-y_{e},\alpha_e \tau) \prod_{e\in E(\Gamma)}d\alpha_e \prod_{v\in V(\Gamma)}dx_v\le \frac{(Ct)^{|E|}}{(|E|)!}+\frac{(C_{\tau}t)^{|E|-\frac{1}{\alpha}(|E|-|V|+1)}}{(|E|-\frac{1}{\alpha}(|E|-|V|+1))!}.
    \end{aligned}
\end{equation}
Here, $x_e$ and $y_e$ denote the variables $x_u$ and $x_v$ associated with the endpoints of the edge $e=\{u,v\}$.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:16:53.570877+00:00","domain":"probability theory","id":"claim_29e0ff47329dfa84b128ef2e405acca59a6118d3ce95a8535cfa7cdb69423235","kind":"theorem","schema_version":1,"statement":"[Theorem thm:unique of arXiv:2412.04589, 'Inverting the Markovian projection for pure jump processes'] Let $X_t = \sum_{k=1}^\infty \bm{1}_{\{\tau_k \leq t\}}$, $t \geq 0$, be a counting process, with $0 < \tau_1 < \tau_2 < \cdots$ $\mathbb{P}$-a.s. Let $\mathbb{A}^k$ be the natural filtration of the process $(\bm{1}_{\{\tau_k \leq t\}})_{t \geq 0}$ for $k \in \mathbb{N}^*$. Let $\mathbb{G}^0 \coloneqq \mathbb{F}$, $\mathbb{G}^k \coloneqq \mathbb{F} \newtriangledown (\newbigtriangledown_{i=1}^k \mathbb{A}^i)$ for $k \in \mathbb{N}^*$ and $\mathbb{G} \coloneqq \mathbb{F} \newtriangledown (\newbigtriangledown_{i=1}^\infty \mathbb{A}^i)$. Suppose that
	\begin{enumerate}[label=(\roman*), nosep]
		\item $\mathbb{F} = \mathbb{G}^0 \hookrightarrow \cdots \hookrightarrow \mathbb{G}^{k-1} \hookrightarrow \mathbb{G}^k \hookrightarrow \cdots \hookrightarrow \mathbb{G}$;

		\item for each $k \in \mathbb{N}^*$, the process $Z^k_t \coloneqq \mathbb{P}(\tau_k > t \,|\, \mathcal{G}^{k-1}_t)$, $t \geq 0$, has a continuous modification which is strictly positive, where $\mathcal{G}^{k-1}_t$ is the element of $\mathbb{G}^{k-1}$ at time $t$.
	\end{enumerate}
	Moreover, let $\eta$, $\lambda$ be given by Assumption~(asm:1 of the paper), and suppose that the process in (equation eq:X_compen of the paper) is a $\mathbb{G}$-martingale. Then, the law of $X$ is uniquely determined by $\lambda$ and the law of $\eta$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:04:06.985314+00:00","domain":"probability theory","id":"claim_29e2c69058980d001fea2331d81889bea2d2fd88d4e01e522ab592edf9acdcf7","kind":"definition","schema_version":1,"statement":"[Definition def:dGFF of arXiv:2607.27810, 'Perturbed Beta Corners Process'] The \emph{discrete Gaussian Free Field (dGFF)} on the $\infty$-corners lattice
$\{\mathsf{y}_i^k\}$ is a centered Gaussian vector $\{\zeta_i^k\}_{1\le i\le k\le N}$
with $\zeta_i^N=0$ for all $i=1,\ldots,N$ (the top row is pinned), and with the
remaining variables having joint density proportional to
\begin{equation}

	\exp\left(\sum_{k=1}^{N-1}\left[
		\sum_{1\le i<j\le k}\frac{(\zeta_i^k-\zeta_j^k)^2}{2(\mathsf{y}_i^k-\mathsf{y}_j^k)^2}
		- \sum_{p=1}^k\sum_{q=1}^{k+1}\frac{(\zeta_p^k-\zeta_q^{k+1})^2}{4(\mathsf{y}_p^k-\mathsf{y}_q^{k+1})^2}
	\right]\right).
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:45:32.064311+00:00","domain":"probability theory","id":"claim_29e4c494b1baf25dbebf9fd8fac0e162d758d26c8943ef811f81e187fdbe1cca","kind":"theorem","schema_version":1,"statement":"[Corollary of arXiv:2411.14105, 'Simultaneous replica-symmetry breaking \\ for vector spin glasses'] Under the same setup of Lemma~(l.time_der_sol of the paper), it holds for every $(t,x)\in[0,T]\times \mathbb{R}^{D}$ that
