{"assumptions":[],"created_at":"2026-10-27T05:30:36.750912+00:00","domain":"probability theory","id":"claim_2a4c62ffb4358153477957437ef7ce9dea9fc2a7ec324cc10110eba2c4580374","kind":"concept","schema_version":1,"statement":"[Lemma 20 ({\cite[Lemma 8.1) of arXiv:2607.08696, 'Spectrum of Directed Inhomogeneous Random Graphs'] {BasakCookZetouni}}] 
