\end{enumerate}

in which case the graph percolates in $k=2$ time steps.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:56:49.285863+00:00","domain":"probability theory","id":"claim_2a882a51f73ef982d9e88b7e57cbae1ff334de8298f84116b113bf156e03be73","kind":"definition","schema_version":1,"statement":"[Definition 4 (Geometric $p$-rough paths) of arXiv:2606.22964, 'Signature McKean--Vlasov stochastic differential equations'] Let $p\geq 1$. We define $C^{0,\textup{$p$-var}}_o([0,T],G^{\lfloor p\rfloor}(\mathbb{R}^k))$ as the set of continuous paths $\mathbf{x}:[0,T]\rightarrow G^{\lfloor p\rfloor}(\mathbb{R}^k)$ such that $\mathbf{x}_0=(1,0,\dots,0)$ and for which there exists a sequence of bounded variation, $\mathbb{R}^k$-valued paths $\{x_n\}_{n\geq 0}$ such that
    \begin{equation*}
        d_{\textup{hom $p$-var};[0,T]}\left(\mathbf{x},S^{\leq \lfloor p\rfloor}(x_n)_\cdot\right)\xrightarrow{n\rightarrow\infty} 0\qquad \Big(\textit{equiv.}\;d_{\textup{inhom $p$-var};[0,T]}\left(\mathbf{x},S^{\leq \lfloor p\rfloor}(x_n)_\cdot\right)\xrightarrow{n\rightarrow\infty} 0\Big),
    \end{equation*}
    where $S^{\leq \lfloor p\rfloor}_\cdot$ denotes the \emph{step-$\lfloor p\rfloor$ signature} for continuous paths of bounded variation \eqref{eq:signature_C_1_path} as a function of time.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:49:02.089245+00:00","domain":"probability theory","id":"claim_2a8858033e30fe78b0911a293e3c81de1e7e313d791536f71090353af6086af6","kind":"lemma","schema_version":1,"statement":"[Lemma 15 (Scaling limit) of arXiv:2604.25877, 'Asymptotic height of Plancherel random trees'] Let $r_n$ be as in \eqref{eq:rn} and $M_{r_n}$ as in \eqref{eq:NB}.
