{"assumptions":[],"created_at":"2026-10-27T05:50:44.875875+00:00","domain":"probability theory","id":"claim_2b0c9be38bab799246e7bc0e62ce92c3ac40cc42984bfd58b47ec340db961797","kind":"lemma","schema_version":1,"statement":"[Lemma 54 (Polynomial rearrangement and convolution tails) of arXiv:2607.16724, 'Algebraic Transfer for Operator-Valued Gaussian Chaoses: Oriented Schatten Profiles and Si'] Assume \eqref{eq:group-growth}.  If $0<\theta\le D$, $R\ge1$, and
$E\subset\Gamma$ is finite with $\#E\le C_0R^D$, then
\begin{align}

 \sum_{x\in E}\langle x\rangle^{-\theta}
 &\le C_{\Gamma,D,C_0,\theta}
 \begin{cases}
  R^{D-\theta},&0<\theta<D,\\
  \log(e+R),&\theta=D.
 \end{cases}
\end{align}
Moreover,
\begin{equation}

 \sum_{x\in E}\langle x\rangle^{-D}\log(e+\langle x\rangle)
 \le C_{\Gamma,D,C_0}\log(e+R)^2.
\end{equation}

Let $D/2<\alpha\le D$, put $\gamma:=2\alpha-D$, and define
\[
 H_\alpha(z):=
 \sum_{x\in\Gamma}
 \langle x\rangle^{-\alpha}
 \langle x^{-1}z\rangle^{-\alpha}.
\]
Then
\begin{equation}

 H_\alpha(z)\le C_{\Gamma,D,\alpha}
 \begin{cases}
  \langle z\rangle^{-\gamma},&D/2<\alpha<D,\\
  \langle z\rangle^{-D}\log(e+\langle z\rangle),&\alpha=D.
 \end{cases}
\end{equation}
For $M\ge1$, the truncated tail
\[
 H_{\alpha,>M}(z):=
 \sum_x
 \langle x\rangle^{-\alpha}
 \langle x^{-1}z\rangle^{-\alpha}
 \mathbf1_{\{\max(|x|,|x^{-1}z|)>M\}}
\]
satisfies
\begin{equation}

 H_{\alpha,>M}(z)\le C_{\Gamma,D,\alpha}
 \begin{cases}
  \max\{M,\langle z\rangle\}^{-\gamma},&D/2<\alpha<D,\\
  \max\{M,\langle z\rangle\}^{-D}
       \log(e+\langle z\rangle),&\alpha=D.
 \end{cases}
\end{equation}","status":"unverified"}

