	where $\mathfrak{A}$ has the following schematic structure:
	\begin{equation} 
		\mathfrak{A}  = \smoothfunction(\badcontrolvars,\gtorus^{-1},\angrmD \vec{x}, \muX \wavearray, \tander \wavearray) \tander \wavearray + \smoothfunction(\controlvars) \upmu (\VortVort,\DivGradEnt) + \smoothfunction(\controlvars) (\upmu \tander \wavearray) (\Omega,\GradEnt) + \smoothfunction(\controlvars)\muX \wavearray (\Omega,\GradEnt) + \smoothfunction(\controlvars)(\Omega,\GradEnt)^2 
	\end{equation}

	Moreover, without assuming that the geometric wave equations \eqref{E:VELOCITYWAVEEQUATION}--\eqref{E:ENTROPYWAVEEQUATION} are satisfied, we have:
	\begin{align} 
		\Ricfour_{\Lunit \Lunit} = & \frac{\Lunit \upmu}{\upmu} \mytr_{\gtorus} \upchi + L \left\lbrace -\frac{1}{2} \mytr_{\gtorus} \angG \diamond \Lunit \wavearray + \angG_{\Lunit}^{\#} \diamond \cdot \angrmD \wavearray \right\rbrace \notag \\
		& - \frac{1}{2} \vec{G}_{\Lunit \Lunit} \diamond \angLap \wavearray + \mathfrak{B}, 
	\end{align}
	where $\mathfrak{B}$ has the following schematic structure:

	\begin{equation} 
		\mathfrak{B} = \text{$\smoothfunction(\controlvars, \gtorus^{-1}, \angrmD \vec{x} )$} (\tander \wavearray) \tander \controlvars.
	\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:46:12.275071+00:00","domain":"probability theory","id":"claim_2b96c86f4f9a22db5def45769bc7a7c6c54e8c010b86e21fc98a5ed4e0c4cfdb","kind":"theorem","schema_version":1,"statement":"[Theorem 19 ($\AW_2$ between Gaussian distributions) of arXiv:2604.22159, 'Adapted optimal transport between filtered Gaussian processes'] { \ }
