       \begin{cases}
          \d \bar{X}_t^\ve=\bar{b}(t,t/\ve,\bar{X}_t^\ve)\d t+\sigma(t,\bar{X}_t^\ve) \d L_t^1,\\
          \bar{X}_s^\ve=x,
       \end{cases}
    \end{equation}
where
\begin{equation}
    \bar{b}(t_1,t_2,x)=\int_{\br^m}b(t_1,x,y)\rho_{t_2}^{x}(\d y),
\end{equation}
and $\rho_t^{x}$ is the unique periodic measure associated with the frozen equation
\begin{equation*}
\begin{cases}
\d Y_t=f(t,x,Y_t)\d t+g(t,Y_t) \d L_t^2,\\
Y_s=y.
\end{cases}
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:38:13.632838+00:00","domain":"probability theory","id":"claim_2baf763b87df0504c571498babe6a4f4de2957bd010da9d9b0902541d9f73d5e","kind":"lemma","schema_version":1,"statement":"[Lemma 5 (Compatibility lemma) of arXiv:2609.00673, '2609.00673'] Let \(x_i>0\) for \(1\le i\le n-1\), and let
\(\phi_i\in(-\pi,\pi]\setminus\{0,\pi\}\) for \(1\le i\le n-2\).
Assume
\begin{equation}
\frac{x_{i+2}+x_{i+1}\cos\phi_{i+1}}{\sin\phi_{i+1}}
=
\frac{x_i+x_{i+1}\cos\phi_i}{\sin\phi_i},
\qquad 1\le i\le n-3.

\end{equation}
Define the endpoint values
\begin{align}
y_1&=\frac{x_2+x_1\cos\phi_1}{\sin\phi_1},
\\
y_{n-1}&=\frac{x_{n-2}+x_{n-1}\cos\phi_{n-2}}
{\sin\phi_{n-2}},

\end{align}
and, for \(2\le j\le n-2\), define \(y_j\) by either of the equal
expressions
\begin{equation}
y_j=
\frac{x_{j-1}+x_j\cos\phi_{j-1}}{\sin\phi_{j-1}}
=
\frac{x_{j+1}+x_j\cos\phi_j}{\sin\phi_j}.

\end{equation}
The equality in \eqref{eq:y-interior} is precisely
\eqref{eq:finite-step} with index \(j-1\). Then, for every
\(1\le i\le n-2\),
\begin{align}
-x_i&=x_{i+1}\cos\phi_i-y_{i+1}\sin\phi_i,
\\
y_i&=x_{i+1}\sin\phi_i+y_{i+1}\cos\phi_i.

\end{align}","status":"unverified"}

