{"assumptions":[],"created_at":"2026-10-27T12:17:13.082366+00:00","domain":"probability theory","id":"claim_2be851f3f2c145c01497e311f8f447c04df330d4c6e4f74a921fecc0af54418d","kind":"theorem","schema_version":1,"statement":"[Theorem TA of arXiv:2510.12480, 'Cyclic and alternating $U$-statistics'] With notations and assumptions 
as in Section~(Sprel of the paper),
the following holds.
\begin{romenumerate}
\par
 \refstepcounter{thmenumerate}\textup{(\roman{thmenumerate})\enspace} 
We have
\begin{align}
  \operatorname{\mathbb E}{} [U^{+-}_n(f)] = (-1)^n\lrflfrac n2\mu

.\end{align}

\par
 \refstepcounter{thmenumerate}\textup{(\roman{thmenumerate})\enspace} 
As \ensuremath{{n\to\infty}},
\begin{align}
n^{-3}\operatorname{Var}[U^{+-}_n(f)]\to
  \sigma^2:=\tfrac{1}{3}\operatorname{\mathbb E}{} [f_2(X)^2]
\end{align}
and 
\begin{align}
  n^{-3/2}\left(U^{+-}_n(f)-\operatorname{\mathbb E}{}[U^{+-}_n(f)]\right) \overset{\mathrm{d}}{\longrightarrow} N(0,\sigma^2).
\end{align}

\par
 \refstepcounter{thmenumerate}\textup{(\roman{thmenumerate})\enspace} 
If\/ $f_2(X)=0$ a.s., and thus $\sigma^2=0$, then
\begin{align}

  \operatorname{Var}[U^{+-}_n(f)]
=\tfrac{1}{2}n^2\operatorname{Var} [f_{12}(X_1,X_2)] + O(n).
\end{align}
Moreover, there exists
a finite or infinite sequence of real numbers $(\lambda_r)_1^R$ such that
\begin{align}
n^{-1}\left(U^{+-}_n(f)-\operatorname{\mathbb E}{}[U^{+-}_n(f)]\right) \overset{\mathrm{d}}{\longrightarrow} 
  W:=\sum_{r=1}^R\tfrac12\lambda_r(\zeta_r^2-1),
\end{align}
where $(\zeta_r)_1^R$ are independent standard normal variables.
The coefficients
$(\lambda_r)_1^R$ in (equation ta2 of the paper) are the nonzero eigenvalues (with multiplicities) 
of the self-adjoint  operator 
on $(L^2({\mathcal X}\times\ensuremath{[0,1]},\nu\times\ell))^2$
given in block form by
\begin{align}
\tfrac12 \begin{pmatrix}-T_{\widehat{f_{12}}}&T_{\widecheck{f_{12}}}\\-T_{\widecheck{f_{12}}}&T_{\widehat{f_{12}}}\end{pmatrix}.
\end{align}
We have
\begin{align}
\operatorname{Var} W=
\tfrac12\sum_{r=1}^R\lambda_r^2 = \tfrac12\operatorname{Var}[f_{12}(X_1,X_2)]
<\infty.
\end{align}

\par
 \refstepcounter{thmenumerate}\textup{(\roman{thmenumerate})\enspace} 
In the special case of (TA2 of the paper) where
furthermore
$f$ is symmetric, 
then also
\begin{align}
n^{-1}\left(U^{+-}_n(f)-\operatorname{\mathbb E}{}[U^{+-}_n(f)]\right) \overset{\mathrm{d}}{\longrightarrow} 
W:=\sum_{r=1}^R\lambda_r\vartheta_r,
\end{align}
where $(\vartheta_r)_1^R$ are i.i.d\xperiod{} with the distribution (equation xeta of the paper),
and the coefficients
$(\lambda_r)_1^R$  are the nonzero eigenvalues (with multiplicities) 
of the integral operator $T_f$ on $L^2({\mathcal X},\nu)$.
We have
\begin{align}
  \operatorname{Var} W = \tfrac12\sum_{r=1}^R\lambda_r^2 = \tfrac12\operatorname{Var}[f_{12}(X_1,X_2)].
\end{align}

\par
 \refstepcounter{thmenumerate}\textup{(\roman{thmenumerate})\enspace} 
In the special case of (TA2 of the paper) where
furthermore
$f$ is antisymmetric, 
then also
\begin{align}

  n^{-1}{U^{+-}_n(f)} \overset{\mathrm{d}}{\longrightarrow} 
W:=\sum_{q=1}^{Q_+}\lambda^{\mathsf a}_q\eta_q,
\end{align}
where 
$(\eta_q)_1^{Q_+}$ are independent random variables with the stochastic area
distribution (equation area of the paper), and
the coefficients 
$(\lambda^{\mathsf a}_q)_1^{Q_+}$  are the positive numbers such that the imaginary
number $\mathrm{i}\lambda^{\mathsf a}_q$ is an eigenvalue of the 
anti-self-adjoint
operator $T_f$ on $L^2_{\mathbb C}({\mathcal X},\nu)$.
We have
\begin{align}
  \operatorname{Var} W = \sum_{q=1}^{Q_+}(\lambda^{\mathsf a}_q)^2 = \tfrac12\operatorname{Var}[f_{12}(X_1,X_2)].
\end{align}

\par
 \refstepcounter{thmenumerate}\textup{(\roman{thmenumerate})\enspace} 
If $f_2=f_{12}=0$, then
\begin{align}
  \operatorname{Var}[U^{+-}_{n}(f)]=n\sigma^2_1+O(1)
\end{align}
where
\begin{align}
  \sigma^2_1&:=\tfrac12\operatorname{Var}[f_1(X)]
.\end{align}
Furthermore,
\begin{align}
  n^{-1/2}\bigpar{U^{+-}_{n}(f)-\operatorname{\mathbb E}{} [U^{+-}_{n}(f)]}&\overset{\mathrm{d}}{\longrightarrow} N(0,\sigma^2_1).
\end{align}
\end{romenumerate}","status":"unverified"}

