{"assumptions":[],"created_at":"2026-10-27T17:24:45.892284+00:00","domain":"probability theory","id":"claim_2c1a6fcaf0ebc50fec0f5d01ce2d5f87b24f9366ebfc605e49a090e8551d60a2","kind":"concept","schema_version":1,"statement":"[Corollary cor:pythKL of arXiv:2509.02996, 'Group-averaged Markov chains: mixing improvement'] Assume that $\pi,\nu,G,P,M,\mathcal{X}$ satisfy the assumptions as stated in Theorem (thm:bisection of the paper). We have
	\begin{align*}
		D^\pi_{KL}(P \| M) &= D^\pi_{KL}(P \| \overline{P}) + D^{\pi}_{KL}(\overline{P} \| M), \quad M \in \mathcal{L}(G,G^{-1}), \\
		D^\pi_{KL}(P \| M) &= D^\pi_{KL}(P \| P_{la}) + D^{\pi}_{KL}(P_{la} \| M), \quad M \in \mathcal{LI}(G), \\
		D^\pi_{KL}(P \| M) &= D^\pi_{KL}(P \| P_{ra}) + D^{\pi}_{KL}(P_{ra} \| M), \quad M \in \mathcal{RI}(G), \\
		D^\pi_{KL}(P \| M) &= D^\pi_{KL}(P \| (P_{la})_{ra}) + D^{\pi}_{KL}((P_{la})_{ra} \| M), \quad M \in \mathcal{LI}(G) \cap \mathcal{RI}(G).

	\end{align*}
	Using the last equality above and by replacing $P$ with $P_{da}$, we note that, in view of (equation eq:Pdalara of the paper),
	\begin{align*}
		D^\pi_{KL}(P_{da} \| M) &= D^\pi_{KL}(P_{da} \| (P_{la})_{ra}) + D^{\pi}_{KL}((P_{la})_{ra} \| M), \quad M \in \mathcal{LI}(G) \cap \mathcal{RI}(G).
	\end{align*}
	If $G$ is further assumed to be Abelian, then
	\begin{align*}
		D^\pi_{KL}(P \| M) &= D^\pi_{KL}(P \| \widetilde{P}) + D^{\pi}_{KL}(\widetilde{P} \| M), \quad M \in \mathcal{L}(G,G).
	\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:09:43.671762+00:00","domain":"probability theory","id":"claim_2c1bcab7f05421af80871627f7f564341448ba1684381cefefc39c6a2160bae7","kind":"concept","schema_version":1,"statement":"[Proposition prop:Gaussian:process:moments of arXiv:2605.28106, 'Gaussian Processes with Sample Paths in Reproducing Kernel Banach Spaces'] Let \( \gamma \) be a Gaussian measure on \( (\mathbb{R}^T,\mathcal{C}(\mathbb{R}^T)) \).
    \begin{enumerate}
        \item There exists a unique function \( a : T \to \mathbb{R} \) such that
        \begin{equation*}
            a_\gamma(f) = f(a), \qquad \forall f \in (\mathbb{R}^T)^*.
        \end{equation*}
        \item There exists a unique function \( K : T \times T \to \mathbb{R} \) such that
        \begin{equation*}
            R_\gamma(\delta_s,\delta_t) = K(s,t), \qquad \forall s,t \in T.
        \end{equation*}
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:09:49.862276+00:00","domain":"probability theory","id":"claim_2c1cd612619e83c482d45f34618cd16e90486c470760c66a5efb143417f669c4","kind":"lemma","schema_version":1,"statement":"[Lemma 21 of arXiv:2609.03084, 'Convergence rates to traveling waves for an FKPP model with nonlinear advection'] Suppose $0 \leq \chi < 1$ so that $U_*$ has the asymptotics given by \eqref{pulled_asymptotics} as $x \to +\infty$. There exists
