		=
		\bigcap_{\tau\geq0}
		\overline{
		\bigcup_{t\geq\tau}\varphi_P^\epsilon(t)K_P
		}^{P}.
	\end{align}
	Moreover, $\mathcal A_P^\epsilon\subset K_P$, so $\mathcal A_P^\epsilon\in\mathfrak D_P$, and
	\begin{align}
