{"assumptions":[],"created_at":"2026-10-28T02:16:53.637847+00:00","domain":"probability theory","id":"claim_2cb0cc75d8f1cc25af4f6dec7be28c712508b5e4c6dca185267c03ad2e5052f3","kind":"concept","schema_version":1,"statement":"[Thm thm4 of arXiv:2412.05521, 'Random attractors for the stochastic Nernst-Planck-Navier-Stokes system with multiplicativ'] Suppose $v^\varepsilon(0) \in H^1$ and $c_i(0) \in H^1$. Let $T > 0$. Suppose $(v^\varepsilon,c_1,c_2)$ is the solution of (equation b1 of the paper) on the interval $[0,T]$ with 
		\begin{align}
			\int_{0}^{T}(\|c_1(t)\|_{L^2}^2+\|c_2(t)\|_{L^2}^2)dt \textless \infty.
		\end{align}
		Then, $v^\varepsilon \in 
		L^{\infty}(0,T;H^1) \cap L^2(0,T;H^2)$ and $c_i \in L^{\infty}(0,T;H^1) \cap L^2(0,T;H^2) $. 
		\begin{proof}
			The differential inequality (equation b6 of the paper) gives
			\begin{align}
				\frac{d}{dt}( \|\sigma\|_{L^2}^{2}\ + \|\rho\|_{L^2}^{2}\ ) +D(\|\nabla\rho\|_{L^2}^{2} + \|\nabla\sigma\|_{L^2}^{2}) \leq C\|\sigma\|_{L^2}^{4}+C\|\rho\|_{L^2}^{4} \leq C(\|\sigma\|_{L^2}^{2}+C\|\rho\|_{L^2}^{2})^2.
			\end{align}
			Under the assumption (equation b22 of the paper), we conclude that $c_i \in L^{\infty}(0,T;L^2) \cap L^2(0,T;H^1) $.  \newline
			The differential inequality (equation b4 of the paper) gives
			\begin{align}
				\frac{d}{dt}&\|\nabla v^\varepsilon\|_{L^2}^{2}\ +\nu \|\Delta v^\varepsilon\|_{L^2}^{2}\notag \\&\leq \frac{D}{2}\|\nabla \rho \|_{L^2}^2+C{z}^4(t,\omega)\|\rho \|_{L^2}^6+\frac{C}{z^2(t,\omega)}\|\nabla v^\varepsilon \|_{L^2}^{4}+C_f+Cz^4(t,\omega).
			\end{align}
			Thus, we obtain that $v^\varepsilon \in  L^{\infty}(0,T;H^1) \cap L^2(0,T;H^2)$. \newline
			Taking the $L^2$ inner product of the equation satisfied by $\sigma$ in (equation b5 of the paper) with -$\Delta \sigma$, we get
			\begin{align}
				\frac{1}{2}\frac{d}{dt} \|\nabla \sigma\|_{L^2}^{2}\ + D \|\Delta \sigma\|_{L^2}^{2} =\frac{1}{z(t,\omega)}\int (v^\varepsilon\cdot \nabla \sigma)\Delta \sigma -D\int \nabla\cdot(\rho \nabla \Phi)\Delta \sigma.
			\end{align}
			We estimate
			\begin{align}
				|\int \rho \Delta \Phi \Delta \sigma| \leq \frac{1}{6}\|\Delta \sigma\|_{L^2}^2+C\|\rho\|_{L^2}^4+C\|\nabla \rho\|_{L^2}^4,
			\end{align}
			\begin{align}
				|\int (\nabla \rho \cdot  \nabla \Phi) \Delta \sigma| \leq \frac{1}{6}\|\Delta \sigma\|_{L^2}^2+C\|\nabla \rho\|_{L^2}^4,
			\end{align}
			and 
			\begin{align}
				|\frac{1}{z(t,\omega)}\int (v^\varepsilon\cdot \nabla \sigma)\Delta \sigma| \leq \frac{D}{6}\|\Delta \sigma\|_{L^2}^2+\frac{C}{z^4(t,\omega)}+C\|\nabla v^\varepsilon\|_{L^2}^4\|\nabla \sigma\|_{L^2}^4,
			\end{align}
			where we used elliptic regularity, Young's inequality, Ladyzhenskaya's inequality and Poincar$\acute{\mathrm{e}}$'s inequality.

			Then, we take the $L^2$ inner product of the equation satisfied by $\rho$ in (equation b5 of the paper) with -$\Delta \rho$ to obtain
			\begin{align}
				\frac{1}{2}\frac{d}{dt} \|\nabla \rho\|_{L^2}^{2}\ + D \|\Delta \rho\|_{L^2}^{2} =\frac{1}{z(t,\omega)}\int (v^\varepsilon\cdot \nabla \rho)\Delta \rho -D\int \nabla\cdot(\sigma \nabla \Phi)\Delta \rho.
			\end{align}
			Similarly, we estimate
			\begin{align}
				|\int \sigma \Delta \Phi \Delta \rho| \leq \frac{1}{6}\|\Delta \rho\|_{L^2}^2+C\|\sigma\|_{L^2}^2\|\nabla \sigma\|_{L^2}^2+C\|\nabla \rho\|_{L^2}^4,
			\end{align}
			\begin{align}
				|\int (\nabla \sigma \cdot  \nabla \Phi) \Delta \rho| \leq \frac{1}{6}\|\Delta \rho\|_{L^2}^2+C\|\nabla \rho\|_{L^2}^4+C\|\nabla \sigma\|_{L^2}^4,
			\end{align}
			and 
			\begin{align}
				|\frac{1}{z(t,\omega)}\int (v^\varepsilon\cdot \nabla \rho)\Delta \rho|&=|z^{-1}\int (\nabla v^\varepsilon \nabla \rho \nabla \rho|\notag\\&  \leq \frac{D}{6}\|\Delta \rho\|_{L^2}^2+\frac{C}{z^4(t,\omega)}+C\|\nabla v^\varepsilon\|_{L^2}^4\|\nabla \rho\|_{L^2}^4.
			\end{align}
			Adding (equation b25 of the paper) to (equation b32 of the paper) together, we conclude that $c_i \in L^{\infty}(0,T;H^1) \cap L^2(0,T;H^2) $ with bounds depending on the initial data and $T$.
		\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:57:49.909759+00:00","domain":"probability theory","id":"claim_2cb201ac4a7d417b3b0f53936b914a5e366586a8ce1cf918e618ae6818a44d9f","kind":"theorem","schema_version":1,"statement":"[Cor weak Q of arXiv:2411.00663, 'Ergodicity and Mixing of invariant capacities and applications'] Let $(\Omega,\mathcal{F},V,T)$ be a weakly mixing capacity preserving system, where $V$ is an upper probability, and $Q\in\mathcal{ M}^{wm}(T)\cap \operatorname{core}(V)$ be as in Lemma (lem:core of w.m. of the paper). Then for any $\widetilde{P}\in \operatorname{core}(V\times V)$,
