{"assumptions":[],"created_at":"2026-10-26T19:26:17.760541+00:00","domain":"probability theory","id":"claim_2cf352a96b65ed4060268c699586e7e0fbcf1a4f9dce0a6b354fdde2b0a8552e","kind":"lemma","schema_version":1,"statement":"[Lemma 42 of arXiv:2511.05386, 'CLT for $\beta$-ensembles with Freud weights, application to the KLS conjecture in Schatte'] Let $\mu$ be a probability measure on $[-1,1]$. 
	Let $\ell \geq 1$ and $\theta \in \cC^\ell(\R)$. 
	For $x \in \R$, let
	\begin{equation} 
		\Theta (x) \coloneqq
		\int_{-1}^1 \frac{\theta(t)-\theta(x)}{t-x} \diff \mu(t).
	\end{equation}
	Then, the following properties hold.
	\begin{enumerate}
		\item The function $\Theta$ is in $\cC^{\ell-1}(\R)$ with $\norme{\Theta}_{\cC^{\ell-1}} \leq \norme{\theta}_{\cC^\ell}$ and, for any $0 \leq k \leq \ell-1$ and $x \in \R$,
		\begin{equation} 
			\Theta^{(k)}(x) = k!
			\int_{-1}^1 \frac{\theta(t)-T_k[\theta,x](t)}{(t-x)^{k+1}} \diff \mu(t).
		\end{equation}
		Moreover, $\Theta$ is $\cC^{\ell}$ on $\R\setminus [-1,1]$ and \eqref{eq:derivative_Theta} holds with $k=\ell$ and $x \notin [-1,1]$.

		\item If $\int_{-1}^1 \frac{1}{1-t} \diff \mu(t) < \infty$, then $\Theta$ is $\ell$ times differentiable at 1 and \eqref{eq:derivative_Theta} holds with $k=\ell$ and $x=1$.

		\item If $\mu$ has a density $\varrho$ such that, for some $M>0$, for any $x \in[-1,1]$, $\varrho(x) \leq M \sqrt{1-x}$, and if, for any $x \geq 1$, $\theta(x) = T_\ell[\theta,1](x)$, then
		\begin{equation} 
			\abs{\Theta^{(\ell)}(x)-\Theta^{(\ell)}(1)}
			\begin{cases}
				\leq 8 M (\ell+1) \left( \sup_{[-1,1]} \lvert \theta^{(\ell)} \rvert \right) (x-1)^{1/2}, & \text{for } x \in [1,2], \\
				= o((x-1)^{1/2}), & \text{as } x \downarrow 1.
			\end{cases}
		\end{equation}
	\end{enumerate}","status":"unverified"}

