{"assumptions":[],"created_at":"2026-10-27T19:33:43.753160+00:00","domain":"probability theory","id":"claim_2d02bcf708ae966b591efa18bda0907736cb62164d7e73aed710c2aceaf957ac","kind":"definition","schema_version":1,"statement":"[Definition def of cH of arXiv:2609.01984, 'Instantaneous shrinking of supports for stochastic PDEs\footnote{JY was supported by a KIA'] Let $\tau\le T$ be a bounded stopping time and $u\in\mathbb H_p^\eta(\tau)$.
\begin{enumerate}[(i)]
\item 
We write $u\in\mathcal{H}^{\eta}_p(\tau)$ if $u_0\in U_{p}^{\eta}$ and there exists $(f,g)\in
\mathbb{H}_{p}^{\eta-2}(\tau)\times\mathbb{H}_{p}^{\eta-1}(\tau,\ell_2)$ such that
\begin{equation*}
\mathrm{d} u = f\mathrm{d} t+\sum_{k=1}^{\infty} g^k \mathrm{d} w_t^k,\quad   t\in (0, \tau]\,; \quad u(0,\cdot) = u_0
\end{equation*}
in the sense of distributions, i.e., for any $\varphi\in C_c^\infty$, the equality
\begin{equation} 
(u(t,\cdot),\varphi) = (u_0,\varphi) + \int_0^t(f(s,\cdot),\varphi)\mathrm{d} s + \sum_{k=1}^{\infty} \int_0^t(g^k(s,\cdot),\varphi)\mathrm{d} w_s^k
\end{equation}
holds for all $t\in [0,\tau]$ almost surely. Here, $(w^k)_{k\geq 1}$ is a family of independent one-dimensional Brownian motions. In this case, we write
\begin{equation*}
\mathbb{D} u:= f,\quad \mathbb{S} u:=g.
\end{equation*}
\item
The norm of $\mathcal{H}_{p}^{\eta}(\tau)$ is defined by
\begin{equation*}
\| u \|_{\mathcal{H}_{p}^{\eta}(\tau)} :=  \| u \|_{\mathbb{H}_{p}^{\eta}(\tau)} + \| \mathbb{D} u \|_{\mathbb{H}_{p}^{\eta-2}(\tau)} + \| \mathbb{S} u \|_{\mathbb{H}_{p}^{\eta-1}(\tau,\ell_2)} + \| u_0 \|_{U_{p}^{\eta}}.
\end{equation*}

\end{enumerate} For another bounded stopping time $\bar{\tau}\le \tau$, we write $\mathcal{H}_{p}^{\eta}( \bar{\tau},\tau)$ for the corresponding space on the shifted time interval $\text{\,\raise.2ex\hbox{${\scriptstyle
|}$}\kern-.34em$($} \bar{\tau},\tau\text{$]$\kern-.15em$]$}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:52:17.374288+00:00","domain":"probability theory","id":"claim_2d0332ea5787819e33f17c8ca01d805fecf26b9a20114804d44a34c7297f17a9","kind":"theorem","schema_version":1,"statement":"[Thm 13 (Local Martingale Criterion) of arXiv:2606.04245, 'Properties of a Special Type of Filtration and its Martingale Criteria'] Let $F=(F(t))_{t\in\cT}$ be an $\cH$-measurable process with càdlàg paths and $\EE[\sup\limits_{t\in[0,t_G)} |F(t)|]<+\infty$. Let $L$ be an integrable random variable (i.e., $\EE[|L|]<+\infty$).
    We define the process $M = (M_t)_{t\in\RRl_+} $ by the equality: 
    \begin{equation}
       M_t =F(t)\ind_{\{t<\gamma\} }+L\ind_{\{t\geq \gamma\}}. 
    \end{equation}   
    Then the following are equivalent: 
    \begin{enumerate}
        \item  $(M_t)_{t\in\cT}$ is a martingale.
        \item  The process $M$ is local martingale on $\RRl_+$, and the following equality holds on the set $\{\gamma=t_G\}$: 
        $$
        \EE(L|\cH)\ind \{\gamma=t_G\}=F(0)\ind \{\gamma=t_G\}
        $$
    \end{enumerate}","status":"unverified"}

