    =
    H_{\mathrm{BG};{\mathbf{p}},[{\mathfrak l}]}^\mathbf{Sl} \oplus V_{\mathscr{G};{\mathbf{p}},[{\mathfrak l}]}^\mathbf{Sl} \oplus V_{\nabla,\mathrm{Uh};{\mathbf{p}},[{\mathfrak l}]}^\mathbf{Sl}
  \end{align*}
  defined by
  \begin{align*}
    H_{\mathrm{BG};{\mathbf{p}},[{\mathfrak l}]}^\mathbf{Sl}
