{"assumptions":[],"created_at":"2026-10-27T20:09:43.678340+00:00","domain":"probability theory","id":"claim_2d23f63fe9871cd77caf7b9bdb8a3d2a4bb27d2cccb2c7cd4f3a0443855d4de4","kind":"definition","schema_version":1,"statement":"[Defn B-omega-mixing of arXiv:2605.28430, 'Limit theory for Lipschitz-localized statistics in random geometric models'] \begin{enumerate}[wide,label=(\roman*),labelindent=0pt]\

\item  The  marks $U$ of the point process $\tilde \mathcal{P}=\sum_{x \in \mathcal{P}}
  \delta_{\tilde{x}}$, $\tilde{x}=(x,U)$, $x\in\mathbb{R}^d$,  $U\in\mathbb{K}$,
satisfy  {\em $\mathbb{B} $-mixing correlations} if
 (equation e.markmixing of the paper) holds when \textnormal{BL}\ is replaced by $\mathbb{B} $; i.e.,
  for all $p,q \in \mathbb{N}$, and all $f \in \mathbb{B} (\mathbb{K}^p), g \in \mathbb{B} (\mathbb{K}^q)$, 
 \begin{align*}
\left|\mathbb {E} _{\bk x1{p+q}}[f(\bk U1{p})g(\bk U{p+1}{p+q})] - \mathbb {E} _{\bk x1p}[f(\bk U1p)] \mathbb {E} _{\bk x{p+1}{p+q}}[g(\bk U{p+1}{p+q})]\right|
\, & \le \, \omega_{p+q}(s), \qquad x_1,\ldots,x_{p+q} \in \mathbb{R}^d,
\end{align*}
where $s = \inf_{i \in \{1,...,p\}, j \in \{p + 1,...,p + q\} } |x_i - x_j|$ and $\omega_k :  [0, \infty) \to [0, 2]$, $k\in\mathbb{N}$ 
is an increasing-decreasing family of functions.

\item  A marked point process $\tilde \mathcal{P} = \{(x, U(x))\}_{x \in \mathcal{P}}$ has  {\em $\mathbb{B} $-mixing
  correlations}  if (equation e.mppmixing of the paper) holds when \textnormal{BL}\ is replaced by $\mathbb{B} $ i.e.,
  for all $p,q \in \mathbb{N}$, and all $f \in \mathbb{B} (\mathbb{K}^p), g \in \mathbb{B} (\mathbb{K}^q)$, 
 \begin{align} \nonumber
& \left|\mathbb {E} _{\bk x1{p+q}}[f(\bk U1{p})g(\bk U{p+1}{p+q})]\rho^{(p+q)}(\bk x1{p+q}) - \mathbb {E} _{\bk x1p}[f(\bk U1p)] \rho^{(p)}(\bk x1{p})\mathbb {E} _{\bk x{p+1}{p+q}}[g(\bk U{p+1}{p+q})]\rho^{(q)}(\bk
x{p+1}{p+q})\right|\\
 &\hspace{0.1\linewidth}\le \omega_{p+q}(s),  \qquad x_1,\ldots,x_{p+q} \in \mathbb{R}^d,
\end{align}
with $s,\omega_k, k \in \mathbb{N}$ as in Item (i). Similarly, a {\em family of marked point processes}   $(\tilde\mathcal{P}_l)_{l \in \mathbb{N}},$ has  $\mathbb{B} $-mixing correlations if Definition~(d.omegahmixing of the paper)(i.family-mixing of the paper) holds when \textnormal{BL}\ is replaced by $\mathbb{B} $. 

\item  If  $(\omega_k)_{k \in \mathbb{N}}$ are fast decreasing functions, then   we respectively speak of  the  {\em fast $\mathbb{B} $-mixing} of  marks, a marked point process, or a family of marked point processes.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:25:41.598429+00:00","domain":"probability theory","id":"claim_2d26de44b2186a009c994ce1ae39c299947ae43f444a18921dc735e522f7d92d","kind":"lemma","schema_version":1,"statement":"[Lemma lem:uniformgreensbound of arXiv:2608.11603, 'Continuous-time directed polymers to the Critical SHF via moments'] {}
	Recall that ${\mathcal{L}}_{\varepsilon,n} = \sum_{k=1}^{n}\mathcal{L}_{\varepsilon}^{(k)}$. Then the following inequality holds:
	\begin{equation*}
		\frac{1}{\lambda + \F{\mathcal{L}}_{\varepsilon,n}(\xi)} \lesssim \frac{1}{\lambda + \frac{1}{2} \Vert \xi\Vert^2} \, ,
	\end{equation*}
	uniformly over $\xi \in \widehat{\mathbb{T}}_{\varepsilon}^{2[\![n]\!]}$ and $\varepsilon > 0$. Moreover, we have the bound
	\begin{equation*}
     \Big|\F{\mathcal{L}}_{\varepsilon,n}(\xi) - \frac{1}{2}\Vert \xi\Vert^2 \,  \Big| \lesssim \varepsilon^{\delta}\Vert \xi\Vert^{2+\delta} \, \, ,
	\end{equation*}
	where $\delta$ is as in Assumption~(assumption2 of the paper). In particular, this implies that the symbol $\F{\mathcal{L}}_{\varepsilon,n}(\xi)$ converges to $\frac{1}{2} \Vert \xi\Vert^2$ uniformly on compact sets.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:44:17.163866+00:00","domain":"probability theory","id":"claim_2d285740c5b1abec5d8f90f1f155f76344c9e20f31d07bb3897739d708f71c4b","kind":"concept","schema_version":1,"statement":"[Proposition 7 of arXiv:2604.17526, '2604.17526'] If the target distribution~$\pi$ is the Gaussian~$\mathcal N(0, \epsilon I_d)$, then choosing
  \begin{equation}
    K = \ceil[\bigg]{\frac{d}{\epsilon}}
    \,,
  \end{equation}
  choosing the temperatures~$\set{\epsilon_k}$ so that~$\epsilon_{K+1} = \epsilon$ and~$\set{1/\epsilon_k}_{1 \leq k \leq K}$ are linearly spaced, and choosing~$\pi_k$ to be the Gaussian~$\mathcal N(0, \epsilon_k I_d)$ will ensure
  \begin{equation}
    \prod_{k = 1}^K \norm{P_{k}^\infty r_{k}^2}_{L^\infty}
      \leq C
      \,.
  \end{equation}
  In this case, Proposition~\ref{p:expectedDiff} with~$T = \infty$ will yield a variance bound that is \emph{independent} of both~$\epsilon$ and~$d$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:44:24.695556+00:00","domain":"probability theory","id":"claim_2d2d69646608058562520a4b18fb7351a5f4183edd367a670bda9458ae9f058b","kind":"concept","schema_version":1,"statement":"[Lemma lem:asy_theta of arXiv:2604.20215, '\bf Edge Universality for Inhomogeneous Random Matrices II: Markov Chain Comparison and Cr'] The $\alpha$-stable theta function $\theta_{\alpha}(x, \tau)$ defined in (equation theta of the paper) satisfies the following asymptotic properties for $x \in \mathbb{T}^d$ and $\tau > 0$.
\begin{enumerate}
     \item[(i)] \textbf{(Small $\tau$ regime)} As $\tau \to 0$,
    \begin{equation}
        \theta_{\alpha}(x, \tau) = f_{\alpha}(x, \tau) + O(\tau).
    \end{equation}
    \item[(ii)] \textbf{(Large $\tau$ regime)} As $\tau \to \infty$,
    \begin{equation}
        \theta_{\alpha}(x, \tau) = 1 + O\big(e^{-c_{\alpha} (2\pi)^{\alpha} \tau}\big).
    \end{equation}
    \item[(iii)] \textbf{(Uniform upper bound)} There exists a constant $C > 0$ such that
    \begin{equation}
        \theta_{\alpha}(x, \tau) \le C\big(1 + \tau^{-\frac{d}{\alpha}}\big).
    \end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:32:20.716223+00:00","domain":"probability theory","id":"claim_2d2e2ab431ae9ab1da7186ea32825f870194155a200314265b2633d8e7311857","kind":"theorem","schema_version":1,"statement":"[Proposition 8 (Geometric meaning of the trisecant sign) of arXiv:2609.00285, 'Multicrossing complex of knot and secant classes'] Assume that $\nu$ is the unit vector of the axis $Oz$ and $s$ is a horizontal trisecant on arcs $\alpha_1(t)$, $\alpha_2(t)$ and $\alpha_3(t)$ in a plane $z=z_0$. Assume also that $(\dot\alpha_i,\nu)>0$, $i=1,2,3$.
\begin{enumerate}
