           &\mathbb{P}(\sigma_{min}(A_{n+1}-\lambda_i I_{n+1})\leq\delta_i n^{-1/2},i=1,2)\lesssim \delta_1\delta_2+e^{-\Omega(n)}\\&+\sup_{r_1,r_2\in\mathbb{R}}\mathbb{P}_{A_n,X}\left(
    \frac{|\langle (A_n-\lambda_i I_n)^{-1}X,X\rangle-r_i|}{\|(A_n-\lambda_i I_n)^{-1}X\|_2}\leq\delta_i,i=1,2,\frac{\mu_1(\lambda_1)\mu_1(\lambda_2)}{n}\leq(\delta_1\delta_2)^{-p}
