{"assumptions":[],"created_at":"2026-10-27T13:59:53.333936+00:00","domain":"probability theory","id":"claim_2d78472fe69c5afe300ae521d066f5c8fd806fb1b48d15a22607ac21ce6caf06","kind":"lemma","schema_version":1,"statement":"[Lemma lem-alpha>2-second-round of arXiv:2607.22324, 'The conclave process'] {}
    When $\alpha\geq 2$, define
    \begin{align*}
        \mathfrak M_{\alpha} = \Big\{ & (M,\delta): \frac{(\log n)^{\alpha}}{(\log\log n)^{2\alpha}} \leq M \leq (\log n)^{\alpha}(\log \log n)^\alpha,  \\
        & \frac{(\log \log n)^{-300-\alpha}}{\log n} \leq \delta \leq \frac{(\log \log n)^{300+\alpha}}{\log n} \Big\} \,.  
    \end{align*}
    Also define
    \begin{align*}
        \mathfrak M_{\alpha}' = \Big\{ & (M,\delta): \frac{(\log n)^{\alpha}}{(\log \log n)^{2\alpha}} \leq M \leq (\log n)^{\alpha}(\log \log n)^\alpha, \\
        &\frac{(\log \log n)^{-300-\alpha}}{(\log n)^{\frac{\alpha}{2}}} \leq \delta \leq \frac{(\log \log n)^{300+\alpha}}{(\log n)^{\frac\alpha 2}}  \Big\} \,.
    \end{align*}
    We have
    \begin{align*}
        &\mathbb P_n^{\alpha}\left( (\mathbf X^{(1)}_2,\ldots,\mathbf X^{(n)}_2) \in \cup_{(M,\delta) \in \mathfrak M_\alpha} \overline{\Omega}_n(M,\delta) \mid E_{\mathsf{unique}} \right) = 1-o(1) \,; \\
        &\mathbb P_n^{\alpha}\left( (\mathbf X^{(1)}_2,\ldots,\mathbf X^{(n)}_2) \in \cup_{(M,\delta) \in \mathfrak M_\alpha'} \overline{\Omega}_n(M,\delta) \mid E_{\mathsf{unique}}^c \right) = 1-o(1) \,.
    \end{align*}
    Moreover, for $\alpha > 2$ we have
    \begin{align*}
        &\mathbb P_n^{\alpha}\Big( \mathcal L(\mathbf X_2) = \mathcal L(\mathbf X_1)  \mid E_{\mathsf{unique}} \Big) = 1-o(1) \,; \\
        &\mathbb P_n^{\alpha}\Big( \mathcal L(\mathbf X_2) \subsetneq \mathcal L(\mathbf X_1), |\mathcal L(\mathbf X_2)| = 1  \mid E_{\mathsf{unique}}^c \Big) = 1-o(1) \,.
    \end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:33:17.690082+00:00","domain":"probability theory","id":"claim_2d78e8e7dfac6c30c8714aeae461fbcee9e79ca3de4f77d2834c11bfb43bdb17","kind":"definition","schema_version":1,"statement":"[Definition 13 (Admissible Fourier-multiplier Gaussian forcing) of arXiv:2607.10813, '2607.10813'] Let the channel-dependent upper orders $\betaW,\betaK$ satisfy
\eqref{eq:parameter-vector}.  For $a\in\mathfrak C$, let
\[
 \mathfrak h_a\in S^{\beta_a}_{1,0}(\R^3;\R),
 \qquad
 \mathfrak h_a(-\xi)=\mathfrak h_a(\xi).
\]
For $L\in\N_0$, set
\begin{equation}
 [\mathfrak h_a]_{\beta_a,L}
 :=\max_{|\alpha|\le L}\sup_{\xi\in\R^3}
 \langle\xi\rangle^{-\beta_a+|\alpha|}
 |\partial_\xi^\alpha\mathfrak h_a(\xi)|<\infty.
\end{equation}
Set
\begin{equation}
 \mathfrak H_{\mathrm{prof}}
 :=\max_{a\in\mathfrak C}[\mathfrak h_a]_{\beta_a,0}
 =\max_{a\in\mathfrak C}\sup_{\xi\in\R^3}
   \langle\xi\rangle^{-\beta_a}|\mathfrak h_a(\xi)|.
\end{equation}
For a real test function
$\varphi\in C_c^\infty((0,\infty)\times\R^3)$, the multiplier
$\mathfrak h_a(D_x)$ acts only in the spatial variable.  The map
$\varphi\mapsto\mathfrak h_a(D_x)\varphi$ is continuous from
$C_c^\infty((0,\infty)\times\R^3)$ to the real Gaussian Hilbert space
$\mathfrak H$.  Hence the formula
\begin{equation}
 \xi_a(\varphi):=\mathbf W_a(\mathfrak h_a(D_x)\varphi),
 \qquad a\in\mathfrak C,
\end{equation}
defines a real centered Gaussian random distribution.  Set
\[
 \mathfrak q_a(\xi):=|\mathfrak h_a(\xi)|^2,
 \qquad
 Q_a:=\mathfrak h_a(D_x)^*\mathfrak h_a(D_x)
      =\mathfrak h_a(D_x)^2.
\]
Then $\mathfrak q_a(\xi)\lesssim\langle\xi\rangle^{2\beta_a}$ and
\begin{equation}
\begin{aligned}
 \E[\xi_a(\varphi)\xi_b(\psi)]
 &=\delta_{ab}
   \langle\mathfrak h_a(D_x)\varphi,
          \mathfrak h_a(D_x)\psi\rangle_{\mathfrak H}\\
 &=\delta_{ab}\int_0^\infty
   \langle Q_a\varphi(t),\psi(t)\rangle_{L_x^2}\dd t.
\end{aligned}
\end{equation}
Equivalently, in the non-conjugated Fourier random-measure convention,
\begin{equation}
 \E[\widehat\xi_a(\dd\xi,\dd t)
       \widehat\xi_b(\dd\eta,\dd s)]
 =\delta_{ab}(2\pi)^3\delta(t-s)\delta(\xi+\eta)
  \mathfrak q_a(\xi)\dd\xi\dd\eta\dd t\dd s.
\end{equation}
Thus the forcing is white in time, stationary in space, and independent
between the two colors.  Its law depends on the profile only through the
spectral density $\mathfrak q_a$.","status":"unverified"}

