{"assumptions":[],"created_at":"2026-10-28T00:32:56.074060+00:00","domain":"probability theory","id":"claim_2e0a86c82ac55eb1684a981d7ec8ec7dfd4ff7205efd6d07188a2f686e14ef7b","kind":"theorem","schema_version":1,"statement":"[Theorem th:modulus-both of arXiv:2411.12192, 'Sample path properties and small ball probabilities for stochastic fractional diffusion eq'] Assume the conditions of Proposition (prop:reg-V-add of the paper) hold. Denote $I=[a,b]\times[-M,M]^d$ with $0<a<b<\infty$ and $0<M<\infty$.  Denote $\rho(t,x)=|t|^{\theta_1}+|x|^{\theta_2}$.
  \begin{enumerate}
    \item (Uniform modulus of continuity). There exists a constant $k_1\in(0,\infty)$ such that
    \begin{equation*}
      \lim_{\varepsilon\to0^+}\sup_{\substack{(t,x),(s,y)\in I;\\ \rho(t-s,x-y)\le\varepsilon}}\dfrac{|u(t,x)-u(s,y)|}{\rho(t-s,x-y)\sqrt{\log\left(1+\rho(t-s,x-y)^{-1}\right)}}=k_1,
      \text{ a.s. }
    \end{equation*}
    \item (Local modulus of continuity). There exists a constant $k_2\in(0,\infty)$ such that for any $(t,x)\in I$,
    \begin{equation*}
      \lim_{\varepsilon\to0^+}\sup_{\rho(s,y)\le \varepsilon} \dfrac{|u(t+s,x+y)-u(t,x)|}{\rho(s,y)\sqrt{\log\log\left(1+\rho(s,y)^{-1}\right)}}=k_2,
      \text{ a.s. }
    \end{equation*}
   \item (Chung's LIL). There exists a constant $k_3\in(0,\infty)$ such that for all $(t,x)\in I$,
  \begin{equation*}
    \liminf_{\varepsilon\to0^+}\sup_{\rho(s,y)\le \varepsilon} \dfrac{|u(t+s,x+y)-u(t,x)|}{\varepsilon\left(\log\log 1/\varepsilon\right)^{-1/Q}}=k_3, \text{ a.s. }
  \end{equation*}
  where $Q=\frac{1}{\theta_1}+\frac{d}{\theta_2}$.
  \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:50:44.862137+00:00","domain":"probability theory","id":"claim_2e0b4fd43bdace3cf6aeb6d49d538d12abe88cd17c69f93404cd7671bb40f2cc","kind":"theorem","schema_version":1,"statement":"[Proposition 12 (Stationary vector area asymptotic) of arXiv:2607.16502, 'Asymptotic Behavior of Path Functionals for Vector-Valued Gaussian Processes at High Level'] For the process above,
\begin{equation}

  \pk{ A_T(u)>L u^{-2/\alpha} }
