\end{equation}
    with $\rho(t)$ defined in {\hyperref[AISRTh4]{Theorem~\ref{AISRTh4}}}. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:21:06.859180+00:00","domain":"probability theory","id":"claim_2e464438242ce53f99afd43f65f2d0f59fc6c2a7eb9a17be05518c858eab3962","kind":"concept","schema_version":1,"statement":"[Thm 1 of arXiv:2608.21090, 'Ornstein--Uhlenbeck process conditioned to have restricted $L_2$-norm'] Let $0<\theta<\frac{1}{2\gamma}$. Assume there are $K>0$ and $\beta\in(0,1/2)$ such that the sequence $y_T$ satisfies $|y_T-\theta T|\leq K T^\beta$. Then
    \begin{equation*}
        \P_x\left((U_t)_{t\geq0}\in~\cdot~\vert~Z_T \leq y_T\right)
        \overset{w}{\longrightarrow}\mathcal{L}(\tilde{U}), \qquad \text{as $T\to\infty$,}
    \end{equation*}
     where $\tilde{U}$ is an Ornstein--Uhlenbeck process started at $x$ with parameter $\frac{1}{2\theta}$ and $\overset{w}{\longrightarrow}$ stands for weak convergence on $\CC([0,\infty))$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:54:12.434825+00:00","domain":"probability theory","id":"claim_2e47267ced95e99131c3f2f468e21d4cc871c52ada54cb0985b67e255368b6b5","kind":"theorem","schema_version":1,"statement":"[Corollary cor: ReductionBoundedWithoutSym of arXiv:2603.26932, 'On the satisfaction frequency of spectral characterization conditions'] Suppose that $\bM_{p,\beta} \sim \operatorname{Haar}(R_{p,\beta}^{n\times n})$. 
    Let $\rank_q(\cdot)$ refer to the rank over $\bbF_q \cong \bbZ[x]/(p\bbZ[x] + \beta(x)\bbZ[x])$. 
    Then, for every $k\leq n$,  as random $R_{p,\beta}$ modules, 
    \begin{align}
        \bbP\Bigl(\coker\bigl(\bM_{p,\beta},\bigr) \in  *  \mid \rank_{q}\bigl(\bM_{p,\beta}\bigr) = n-k\Bigr) = \bbP\Bigl(\coker\bigl(\bK  \bigr) \in  * \Bigr),
    \end{align}
    where $\bK$ is a $k\times k$ matrix with entries Haar distributed on $pR_{p,\beta} + \beta(x) R_{p,\beta}$. 
    That is, 
    \begin{align}
        \bK  \sim  p\operatorname{Haar}(R_{p,\beta}^{k\times k})  + \beta(x) \operatorname{Haar}(R_{p,\beta}^{k\times k}).   
    \end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:25:44.588556+00:00","domain":"probability theory","id":"claim_2e4746257dca49d317143f00e2d9c19d8034b178ad43ac5a2c2bde4776b76fce","kind":"definition","schema_version":1,"statement":"[Defi def:curve of maximal slope of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] [AGS08]
    Let $(S,d)$ be a metric space and $F:S\to (-\infty,\infty]$ measurable. A locally absolutely continuous curve $v:(a,b)\to S$ is a curve of maximal slope for the functional $F$ with respect to its strong upper gradient $g$, if $F\circ v$ is $\mathsf{Leb}_{\IR}-$a.e. equal to  a non-increasing map $f$ and \begin{align*}
        f'(t)\leq -\frac{1}{2}\left\lvertv'\right\rvert^2(t)-\frac{1}{2}g^2(v(t)) \text{ in } (0,\infty).
    \end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:16:46.105472+00:00","domain":"probability theory","id":"claim_2e4c3cf94b45bd8567d64e503fc3f3321c8b840e5458e0387073c5a5a41d6511","kind":"concept","schema_version":1,"statement":"[Lem lm:shocksandwich of arXiv:2604.12963, 'Shocks, instability, and the twenty networks\\ of infinite geodesics in the Directed Lands'] For all $\omega\in\Omega_0$, $x,s,\theta\in\mathbb{R}$, ${\raisebox{-0pt}{\scaleobj{1.1}{\boxempty}}}\in\{-,+\}$, and any $\theta{\raisebox{-0pt}{\scaleobj{1.1}{\boxempty}}}$ shock interface $\tau$ from $(x,s)$, 
  \begin{align}
  \Upsilon_{(x,s)}\dir{L}{\theta}{{\raisebox{1.5pt}{\scaleobj{0.6}{\boxempty}}}}\preceq\tau\preceq\Upsilon_{(x,s)}\dir{R}{\theta}{{\raisebox{1.5pt}{\scaleobj{0.6}{\boxempty}}}}.
  \end{align}
  Consequently, 
  \begin{align}
  \lim_{r\to-\infty}r^{-1}\tau(r)=(\theta,1).
  \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:56:49.286352+00:00","domain":"probability theory","id":"claim_2e4c772d4edee44b03648d7a06e92779cb50f717eb66f521a2efa9ff887711c4","kind":"theorem","schema_version":1,"statement":"[Theorem 10 of arXiv:2606.22964, 'Signature McKean--Vlasov stochastic differential equations'] For any $\widehat{\mathbf{x}}\in\widehat{C}^{\alpha,p}_o$ and some $\beta>0$ and $\gamma\geq\lfloor 1/\alpha\rfloor$, let
    \begin{equation*}
        \psi(\widehat{\mathbf{x}}) := \exp\left(\beta(\lVert \widehat{\mathbf{x}} \rVert_{\textup{hom $p$-var};[0,T]} + \lVert \widehat{\mathbf{x}} \rVert_{\textup{hom $\alpha$-H\"{o}l};[0,T]})^\gamma\right).
    \end{equation*}
    Also, let
    \begin{equation*}
        B_\psi(\widehat{C}^{\alpha,p}_o) := \Bigg\{f:\widehat{C}^{\alpha,p}_o\rightarrow\mathbb{R} \,:\, \lVert f\rVert
        _{\mathcal{B}_\psi(\widehat{C}^{\alpha,p}_o)}:=\sup_{\widehat{\mathbf{x}}\in\widehat{C}^{\alpha,p}_o}\frac{f(\widehat{\mathbf{x}})}{\psi(\widehat{\mathbf{x}})}<\infty\Bigg\}
    \end{equation*}
    and $\mathcal{B}_\psi(\widehat{C}^{\alpha,p}_o)$ be the closure with respect to $\lVert \cdot\rVert_{\mathcal{B}_\psi(\widehat{C}^{\alpha,p}_o)}$ of the space $C_b^0\left(\widehat{C}^{\alpha,p}_o;\mathbb{R}\right)$ of bounded and continuous real-valued functions over $\widehat{C}^{\alpha,p}_o$. Then, for every map $f\in \mathcal{B}_\psi(\widehat{C}^{\alpha,p}_o)$ and for every $\varepsilon>0$, there exists a linear function of the form 
    \begin{equation*}
        (T(\mathbb{R}^{k+1}))\ni S(\widehat{\mathbf{x}})_T \longmapsto \langle\ell,S(\widehat{\mathbf{x}})_T\rangle := \sum_{0\leq |I|\leq N} \alpha_I\big\langle \varepsilon_I, S^{|I|}(\widehat{\mathbf{x}})_T \big\rangle_{(\mathbb{R}^{k+1})^{\otimes |I|}},
    \end{equation*}
    where $N\in\mathbb{N}$, $\alpha_I\in\mathbb{R}$, $I=(i_1,\dots,i_m)\in\{1,\dots,k\}^m$ is a multi-index with $|I|=m$, $\varepsilon_I:=\varepsilon_{i_1}\otimes\dots\otimes\varepsilon_{i_m}$ are the basis elements of $(\mathbb{R}^{k+1})^{\otimes m}$, and $\langle \cdot,\cdot\rangle_{(\mathbb{R}^{k+1})^{\otimes |I|}}$ is the usual inner product on $(\mathbb{R}^{k+1})^{\otimes |I|}$, such that
    \begin{equation*}
        \sup_{t\in[0,T]}\sup_{\widehat{\mathbf{x}}\in \widehat{C}^{\alpha,p}_o} \frac{ \big|f(\widehat{\mathbf{x}}_{\cdot\wedge t}) -\langle\ell,S(\widehat{\mathbf{x}})_t\rangle\big| }{ \psi(\widehat{\mathbf{x}}_{\cdot\wedge t}) } < \varepsilon.
    \end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:51:15.033887+00:00","domain":"probability theory","id":"claim_2e53b66d551c1019dbd4501f7577ab17add5f520a9031ae248d09281646c674e","kind":"concept","schema_version":1,"statement":"[Theorem 6tmod3.3 of arXiv:2609.03926, 'Overcolored Partition $k$-tuples Restricted by Parity of the Parts'] For all $n,r,s,k,t\ge0$ and values of $(t,u,\ell)$ as in sets $A_{t,u,\ell}, B_{t,u,\ell}, C_{t,u,\ell},\\ D_{t,u,\ell}$ and $E_{t,u,\ell}$, we have
