{"assumptions":[],"created_at":"2026-10-27T09:24:34.413281+00:00","domain":"probability theory","id":"claim_2e811dec6bfbc80dcdee3c5b3679ab473f08decf33405a9e14130a3e6b6c068f","kind":"concept","schema_version":1,"statement":"[Theorem 3 of arXiv:2608.31099, '\bf On (fake) Stationarity in Stochastic Volterra Equations with Affine Drift and Regular '] Let \( \alpha \in \left( 1, \frac32\right) \) , let \(\rho\geq0\), let \( K(t) = K_{\alpha,\rho}(t) =  e^{-\rho t}\frac{t^{\alpha-1}}{\Gamma(\alpha)} \), \( t > 0 \) the exponential-fractional kernel, set \(\phi\) as in~\eqref{eq:notcst_phi} and let $\sigma(t,x):= \varsigma(t)\sigma(x)$ in ~\eqref{eq:Volterrameanrevert}-\eqref{eq:Volterrameanrevert_} where \( \sigma : \mathbb{R} \to \mathbb{R} \) is the Lipschitz continuous function~\eqref{eq:sigmafakeI&II}, with \([\sigma]_{\text{Lip}}=\kappa_2\) and $\varsigma $ is a non-negative, continuous function given by Equation~\eqref{eq:VolterraStabilizerCont} for some fixed $\lambda >0$ and 
	 \( c \in \left( 0, \frac{\alpha-1}{8\kappa_2} \right) \). Let \( X_0 \in L^p(\P) \) for some $p>\frac{2}{\alpha-1}>2$ such that \( \mathbb{E}[X_0] =m_0\) and \(Var(X_0) = v_0=\frac{c\sigma^2( m_0)}{1-c\kappa_2}.\)
	Then,
	\begin{enumerate}
		\item Assume that the diffusion coefficient  $\sigma$ is non-degenerated (in the sense $\sigma(m_0) \neq0$) 

		\noindent $(a)$ Case $\kappa_2 > 0$. The solution \( (X_t)_{t \geq 0} \) to the Volterra equation~\eqref{eq:Volterrameanrevert} or ~\eqref{eq:Volterrameanrevert_} starting from $X_0$ has a fake stationary regime of type I, in the sense that
		\vspace{-.3cm}
		\begin{equation}\forall\, t\ge 0, \quad 
		\mathbb{E}[X_t] = m_0, \; \text{Var}(X_t) = v_0= \frac{c\sigma^2(m_0)}{1 - c\kappa_2},\; \text{and}\;\; \mathbb{E}[\sigma^2(X_t)] = \bar{\sigma}_0^2 =\frac{\sigma^2(m_0)}{1 - c\kappa_2}.
		\vspace{-.1cm}
		\end{equation}
		\noindent $(a)$ Case $\kappa_2 = 0$. Then $\kappa_1=0$ and \((X_t)_{t\geq0}\) is a Gaussian process with a fake stationary regime of type~II, with \( \nu \) as one-dimensional marginal distribution, provided that if $X_0 \sim \nu := \mathcal{N}\!\left(m_0,c\kappa_0^2\right)$.

		\item The family of shifted processes \( X_{t+\cdot}, t \geq 0 \), is \( C \)-tight as \( t \to +\infty \) and its (functional) limiting distributions are all \( L^2 \)-stationary processes with mean \(m_0\) and autocovariance function \( C_\infty \) given, for \( t_1, t_2 \geq 0 \), \( t_1 \leq t_2 \), by \(C_\infty:=C_{f_{\alpha,\rho,\lambda}}(t_1,t_2)\)
		\vspace{-.3cm}
			\begin{equation}
				\text{Cov}(X_{t+t_1}, X_{t+t_2}) \overset{t \to +\infty}{\to} C_{f_{\alpha,\rho,\lambda}}(t_1,t_2) := \ell_\infty^2 v_0 + \frac{\varsigma_{\infty}^2 v_0 }{c\lambda^2}\int_0^{+\infty}  f_{\alpha,\rho,\lambda}(t_2-t_1+u)f_{\alpha,\rho,\lambda}(u)du.
			\end{equation}
		\vspace{-.3cm}
		$$\varsigma_{\infty}^2 :=\lim_{t \to +\infty}\varsigma_{\alpha,\rho,\lambda,c}^2(t)  = \begin{cases}
			1, & \text{in the autonomous diffusion setting of~\eqref{eq:VolterraStabilizerCont}},\\
			\frac{c\lambda^2 (1-\ell_\infty^2)}{\int_0^{+\infty}f^2_{\alpha,\rho, \lambda}(s)ds}, & \text{in the time-dependent diffusion setting of~\eqref{eq:VolterraStabilizerCont}}.
		\end{cases} $$

		\item {\em $L^p$-confluence:} If $m_0= (1-a) \frac{\mu_\infty}{\lambda}$ i.e. \(\ell_\infty=0\), then for any starting random variable \( X_0^\prime  \in L^p(\P) \), a solution to the Volterra SDE ~\eqref{eq:Volterrameanrevert}-\eqref{eq:Volterrameanrevert_} starting from \( X_0^\prime \) satisfies \( \| X_t^\prime - X_t \|_p\to 0\) as $t \to \infty$ and


		\centerline{$\mathbb{E}[X_t] \to m_0, \quad \text{and} \quad \text{Var}(X_t) \to \frac{c\sigma^2(m_0)}{1 - c\kappa_2} \quad \text{as} \quad t \to +\infty.$}
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:59:45.008945+00:00","domain":"probability theory","id":"claim_2e81f300b6bdc37dc304ce3514e0a90cdd3fb14b1423952850ce97d81f6346e6","kind":"definition","schema_version":1,"statement":"[Definition def4 classic DPPs of arXiv:2605.12777, 'Mesoscopic Rates of Convergence for Complex Wishart Matrices at the Leftmost Spectrum Edge'] An \textbf{Airy~point~process} $\mathfrak{X}_{Ai}$ is a DPP given by the kernel:
\begin{equation}
    K_{Ai}(x,y)=\left\{\begin{array}{rr}
      \frac{Ai(x)Ai'(y)-Ai(y)Ai'(x)}{x-y},~~x\ne y\\\\
      \left(Ai'(x)\right)^2-xAi^2(x),~~x=y
    \end{array}\right.
\end{equation}
for $(x,y)\in\mathbb{R}^2$, where
\begin{equation*}
    Ai(x)=\frac{1}{\pi}\int_0^\infty\cos\left(\frac{t^2}{3}+xt\right)dt
\end{equation*}
is the \textbf{Airy~function}.

Similarly, a \textbf{Bessel~point~process} $\mathfrak{X}_{Bes,a}$ with parameter $a\ge0$ is a DPP with the kernel:
\begin{equation}
    K_{Bes,a}(x,y)=\left\{\begin{array}{cc}
    \frac{\sqrt y J'_a(\sqrt y)J_a(\sqrt x)-\sqrt x J'_a(\sqrt x)J_a(\sqrt y)}{2(x-y)},~~x\ne y\\\\
    \frac{x-a^2}{4x}\left(J_a(\sqrt x)\right)^2+\frac{1}{4}\left(J'_a(\sqrt x)\right)^2,~~x=y
    \end{array}\right.
\end{equation}
for $x,~y\ge0$, where
\begin{equation*}
    J_a(x)=\sum_{m=0}^\infty\frac{(-1)^m}{\Gamma(m+1)\Gamma(m+a+1)}\left(\frac{x}{2}\right)^{2m+a}
\end{equation*}
is the \textbf{Bessel~function} with parameter $a$.","status":"unverified"}

