{"assumptions":[],"created_at":"2026-10-28T00:59:45.529007+00:00","domain":"probability theory","id":"claim_2e93a78e95c18da77dd8669b5b094e3120d8ef236ef6b7a91ebcb8dd42a27148","kind":"theorem","schema_version":1,"statement":"[Theorem eq:lowerboundEnt of arXiv:2411.16913, 'Entropies of the Poisson distribution as functions of intensity: ``normal'' and ``anomalou'] \begin{enumerate}
    \item 
 For any $\lambda>1$,
 \begin{equation}
     \mathbf H(\lambda)\geq \frac{1}{2}\log (2\pi\lambda) -h(\lambda)=:L(\lambda), 
 \end{equation}
where $\mathbf H (\lambda)$ is either of $\mathbf H_{SH}(\lambda)$, $\mathbf H_R(\alpha,\lambda)$, $\mathbf H_{GR}(\alpha,\lambda)$, $\mathbf H_{GR}(\alpha,\beta,\lambda)$ for all admissible values of the parameters and
\begin{equation}
        h(\lambda):= \frac{1}{2}\log\left(1+\frac{1}{(\lambda-1)\vee 1}\right)-\frac1{12\lambda+1}>0, \qquad \lambda>0.
\end{equation}
 \item  For the Shannon entropy, the following upper bound holds
\begin{equation}

\mathbf H_{SH}(\lambda)\le    \frac{1}{2} \log {(2\pi \lambda)}+1+\frac{1}{6\lambda}=:U_{SH}(\lambda), \qquad\lambda>1.
\end{equation}

\item For the R\'enyi entropy, we define $\gamma_*:=\exp\left(-\dfrac{\pi}{e}\bigl(e^{\frac16}-1\bigr)\right)\approx 0.811$, and pick any $\gamma\in[\gamma_*,1)$. Then $\mathbf H_{R}(\alpha,\lambda)<U_{R}(\alpha,\lambda,\gamma)$ for all $\lambda>1$ and $\alpha>0$, $\alpha\neq1$, where:
\begin{enumerate}
    \item for $\alpha\in(0,1)$ and $\lambda>1$,
\begin{align}\notag
    U_{R}(\alpha,\lambda,\gamma):=&\frac{1}{1-\alpha}\Biggl(\log E_\alpha\left(\Bigl(\dfrac{\alpha}{\gamma}\lambda\Bigr)^\alpha\right)-\alpha\lambda\Biggr)+\frac{1}{2}\log\frac{\pi}{-e\log\gamma}
    \\&\quad +\frac\alpha{2(1-\alpha)}\log\alpha +\frac{1}{12\alpha(1-\alpha)}+\frac{1}{2}\log(1-\alpha).

\end{align}
\item for $\alpha>1$ and $\lambda>1$,
\begin{align}\notag
    U_{R}(\alpha,\lambda,\gamma):&=\frac{1}{\alpha-1}\Biggl(\alpha\lambda-\log E_\alpha\bigl( (\alpha\gamma\lambda)^\alpha \bigr)\Biggr)+\frac12\log\frac{\pi}{-e\log\gamma}\\&\quad -\frac{\alpha}{2(\alpha-1)}\log\alpha+\frac{\alpha}{12(\alpha-1)}+\frac12\log(\alpha-1).
\end{align}
\end{enumerate}
Here $E_\alpha$ denotes the Mittag--Leffler function.
\item For the Tsallis entropy, the estimates (equation eq:powergrowthT of the paper)
and (equation eq:powergrowthT2 of the paper) hold true with $\bigl(2\pi\lfloor\lambda\rfloor\bigr)^{\frac{1-\alpha}{2}}$ replaced by $(2\pi\lambda)^{\frac{1-\alpha}{2}}e^{-h(\lambda)}$.
\item For the Sharma--Mittal entropy, the estimates (equation eq:powergrowthSM of the paper)
and (equation eq:powergrowthSM2 of the paper) hold true with $\bigl(2\pi\lfloor\lambda\rfloor\bigr)^{\frac{1-\beta}{2}}$ replaced by $(2\pi\lambda)^{\frac{1-\beta}{2}}e^{-h(\lambda)}$.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:48:49.901678+00:00","domain":"probability theory","id":"claim_2e967e4def0493e34215cde084a25c642fdc8617f10093748d54d877c1cffb5b","kind":"concept","schema_version":1,"statement":"[Theorem SSK with critically scaled external field \cite{Baiketal21,landon2020fluctuations} of arXiv:2510.26960, 'Free energy fluctuations in SK and related spin glass models: \\ A literature survey'] When the external field is critically scaled as described below, the free energy of SSK exhibits the following convergence in distribution as $N\to\infty$.
\begin{enumerate}[(i)]
\item If $\beta<1$ and $h=HN^{-1/4}$ for fixed $H>0$, then
 \begin{equation} 
N(F_N(\beta,h)-F(\beta,h))\to\mathcal{N}(-\frac12 \sigma^2,\sigma^2)
 \end{equation} 
where $\sigma^2=-\frac12\log(1-\beta^2)+\frac{H^4\beta^4}{2(1-\beta^2)}$.

\item If $\beta>1$ and $h=HN^{-1/6}$ for fixed $H>0$, then
 \begin{equation} 
\frac{2N^{2/3}}{\beta-1}(F_N(\beta,h)-F(\beta,h))\to \tilde{\mathcal{F}}_{\beta,H}
 \end{equation} 
where $\tilde{\mathcal{F}}_{\beta,H}$ is a function of Gaussian random variables and a GOE Airy point process.
\end{enumerate} 
The limiting free energy $F(\beta,h)$ in this setting is given by the formula
 \begin{equation} 
F(\beta,h)=\begin{cases}
\frac14\beta^2+\frac12\beta^2h^2& \text{for }\beta\leq1,\\
\beta-\frac12\log\beta-\frac34+\frac12\beta h^2 & \text{for }\beta\geq1.
\end{cases}
 \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

