{"assumptions":[],"created_at":"2026-10-26T19:33:23.331530+00:00","domain":"probability theory","id":"claim_2e997b91b87cff19fd4742d59091c5a014c19a546157b85d67ff8638b2bb2134","kind":"concept","schema_version":1,"statement":"[Theorem 2 of arXiv:2506.22040, '\vspace{-3em} Khinchin inequalities for uniforms on spheres with a deficit'] Let $d \geq 2$ be a fixed dimension, let $\xi_1, \xi_2, \dots$ be independent random vectors uniform on the unit Euclidean sphere $S^{d-1}$ in $\R^d$. Let $p \geq 2$. For every $n \geq 2$, every real scalars $a_1, \dots, a_n$ with $\sum_{j=1}^n a_j^2 = 1$, we have
\begin{equation}
\E\left|\sum_{j=1}^n a_j\xi_j\right|^p \leq \E\left|\sum_{j=1}^n \frac{1}{\sqrt{n}}\xi_j\right|^p - \tilde{c}_{p,d}\sum_{j=1}^n \left(\frac{1}{n}-a_j^2\right)^2,
\end{equation}
where
\[ 
\tilde{c}_{p,d} = \frac{p(p-2)}{4d}\begin{cases}
\frac{(p+d-2)(p+d-4)}{d(d+2)}, & 2 \leq p \leq 4, \\ 0.385, & p > 4. \end{cases}
 \] (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:45:17.711275+00:00","domain":"probability theory","id":"claim_2e9cca82e18e2ae3fd6cb4a606777eb76aebe48954786540fe9c16c4fbf5b01e","kind":"concept","schema_version":1,"statement":"[Theorem distance of arXiv:2604.11761, 'The smallest singular value of signed random combinatorial matrices'] Let $M_n$ be an $n \times n$ random matrix satisfying the assumptions of Theorem (main of the paper). Let $R_1, \dots, R_n$ denote its rows, and for each $j \in [n]$, let $H_j$ denote the subspace spanned by the remaining rows:
\begin{align*}
H_j := \mathrm{span}\{ R_i : i \neq j, i \in [n] \}.
\end{align*}
Let $v_j$ be a random unit vector orthogonal to $H_j$ and measurable with respect to the $\sigma$–field generated by $H_j$. Then there exist constants $C, c > 0$ such that for all $\varepsilon \ge 0$, the Lévy concentration function satisfies
\begin{align}
\mathcal{L}(\langle R_j, v_j \rangle, \varepsilon) \le C\varepsilon + 2e^{-cn}.
\end{align}
In particular, this implies the distance bound
\begin{align*}
\textbf{P} \left( \operatorname{dist}(R_j, H_j) \le \varepsilon \right) \le C\varepsilon + 2e^{-cn}.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:45:01.976659+00:00","domain":"probability theory","id":"claim_2e9d3855084e97d9905eaa513e2450b291a955994ca8fca2c30aa51d99f76d63","kind":"concept","schema_version":1,"statement":"[Theorem THM:1 of arXiv:2512.23957, 'Concentration and fluctuations of sine-Gordon measure around topological multi-soliton man'] Let $Q \in \mathbb{Z}$ with $Q \neq 0$, and $L_\varepsilon =\varepsilon^{-\frac 12+\eta}$ with $\eta>0$ arbitrarily small but fixed.

\begin{itemize}
\item[(i)] There exists $c>0$ such that for any $\delta>0$ 
\begin{align}
\limsup_{\varepsilon \to 0} \varepsilon \log \rho_\varepsilon^Q  \big(\{   \textup{dist}(\phi, \mathcal{M}_Q ) \ge \delta   \} \big) \le -c \delta^2,

\end{align}

\noindent
where $\textup{dist}$ denotes the $L^2(\mathbb{R})$-distance and the multi-soliton manifold\footnote{The multi-soliton profile $m(\cdot-\xi_1)+\dots +m(\cdot-\xi_Q)$ is invariant under permutation of the labels $i=1,\ldots, |Q|$. Each unordered configuration corresponds to $Q!$ identical ordered configurations. Because of the indistinguishable nature, we work with the ordered set.} is defined as
\begin{align}
\mathcal{M}_Q:=\Big\{\sum_{j=1}^Q m(\cdot-\xi_j): -\infty<\xi_1\le \dots \le \xi_Q<\infty  \Big\}, \quad Q>0.

\end{align}

\noindent 
For $Q<0$, we define the corresponding multi-soliton manifold with anti-kinks. 

\medskip 

\item[(ii)] There exists $c>0$ such that  
\begin{align} 
\limsup_{\varepsilon \to 0} \varepsilon \log \rho_\varepsilon^Q  \big(\{   \textup{dist}(\phi, \mathcal{M}_Q^{<d} ) < \delta  \big) \le - c e^{- d},

\end{align}

\noindent
for any $\delta>0$, $d>0$ satisfying\footnote{ Later, we prove that the collision manifold $\mathcal{M}_Q^{<d}$ is an unlikely event. Therefore, when the field $\phi$ is sufficiently close to $\mathcal{M}_Q^{<d}$, in the sense that $ c e^{-d } \ge \delta^2$, we obtain the same result. See Lemmas~(LEM:GAP2 of the paper) and~(lem:gap-multikink of the paper).} $ c  e^{-d } \ge \delta^2$, where the collision manifold $\mathcal{M}_Q^{<d}$, $Q>0$, is defined as 
\begin{align}
\mathcal{M}^{<d}_{Q}:=\Big\{\sum_{j=1}^Q m(\cdot-\xi_j) : -\infty<\xi_1\le \dots \le \xi_{Q}<\infty \; \; \textup{and} \; \; \min_{i \neq j} |\xi_i-\xi_j|<d \Big\}.

\end{align}

\noindent
For $Q<0$, we define the corresponding manifold with anti-kinks. 

\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:13:18.517936+00:00","domain":"probability theory","id":"claim_2e9de70eb66d4036caa9e7969dc13a01c17054781ffb4cdf5074846e521d476a","kind":"concept","schema_version":1,"statement":"[Lemma 31 of arXiv:2608.30602, '2608.30602'] Suppose $|V(x)|\lesssim\langle x\rangle^{-8-}$ and that zero is either a second-kind threshold singularity or an eigenvalue of $H$. Then there exists $\lambda_0=\lambda_0(V)\in(0,1)$ such that for $\lambda\in(0,\lambda_0)$ the operators $(M^{\pm}(\lambda))^{-1}\in\mathbb{B}(L^2)$ admit the expansion
	\begin{equation}
		\begin{aligned}
			\bigl(M^{\pm}(\lambda)\bigr)^{-1}
			&=(I-S_2)\mathcal{L}_{00}^{\pm}(\lambda)(I-S_2)
			+(I-S_2)\mathcal{L}_{01}^{\pm}(\lambda)S_2\\
			&\quad+S_2\mathcal{L}_{10}^{\pm}(\lambda)(I-S_2)
			+S_2\mathcal{L}_{11}^{\pm}(\lambda)S_2,
		\end{aligned}
	\end{equation}
	where
	\begin{equation}
		\mathcal{L}_{00}^{\pm}(\lambda)=
		\begin{cases}
			h_{\pm}(\lambda)^{-1}N+QD_0Q+\tilde{\mathcal{O}}_2(\lambda^{3/2}), 
			&\text{if no s-wave},\\[4mm]
			-h_{\pm}(\lambda)(S_1-S_2)D_1(S_1-S_2)
			-N(S_1-S_2)D_1(S_1-S_2)\\[1mm]
			\quad-(S_1-S_2)D_1(S_1-S_2)N+QD_0Q
			+\tilde{\mathcal{O}}_2(\lambda^{3/2}), 
			& \text{if  has s-wave},
		\end{cases}
	\end{equation}
	and
	\begin{equation}
		\mathcal{L}_{11}^{\pm}(\lambda)=
		\begin{cases}
			\dfrac{S_3D_3S_3}{\lambda^2}+\tilde{\mathcal{O}}_2(\lambda^{-1+}), 
			&\text{if no p-wave},\\[6mm]
			\dfrac{S_3D_3S_3}{\lambda^2}
			+\dfrac{N_1}{\lambda^2g_1^{\pm}(\lambda)}
			+\tilde{\mathcal{O}}_2\!\left(\lambda^{-2}g_1^{\pm}(\lambda)^{-2}\right), 
			& \text{if has p-wave},
		\end{cases}
	\end{equation}
	and
	\begin{equation}
		\mathcal{L}_{01}^{\pm}(\lambda)=\tilde{\mathcal{O}}_2(\log^2\lambda),\qquad 
