{"assumptions":[],"created_at":"2026-10-26T19:43:44.243666+00:00","domain":"probability theory","id":"claim_2eac246d7f0ec0ddf75421d100bcbeea42d8d99e9983e020407da230bc5d9e6c","kind":"concept","schema_version":1,"statement":"[Corollary 7 of arXiv:2604.15191, 'Quantitative Stability of Many-Marginal Schr\"odinger Bridge'] Under the same assumptions as in Theorem~\ref{thm: eot_expansion}, we have
\begin{align*}
\eot_{\varepsilon}(\rho_{t}, \rho_{t+\varepsilon})
&= \varepsilon\int_{\mb T^d}\log u_{t,0}\,\dd\rho_t + \sum_{k=1}^{K-1}\varepsilon^{k+1}\bigg[\sum_{l=1}^k\int_{\mb T^d}\frac{(-1)^{l+1}}{l u_{t,0}^l}\sum_{\substack{s_1 + \cdots + s_l=k\\ 1\leq s_1,\cdots, s_l\leq K}}u_{t,s_1}\cdots u_{t,s_l}\,\dd\rho_t\bigg]\\
&\quad + \varepsilon\int_{\mb T^d}\log v_{t,0}\,\dd\rho_{t+\varepsilon} + \sum_{k=1}^{K-1}\varepsilon^{k+1}\bigg[\sum_{l=1}^k\int_{\mb T^d}\frac{(-1)^{l+1}}{l v_{t,0}^l}\sum_{\substack{s_1 + \cdots + s_l=k\\ 1\leq s_1,\cdots, s_l\leq K}}v_{t,s_1}\cdots v_{t,s_l}\,\dd\rho_{t+\varepsilon}\bigg]
+ O(\varepsilon^{K+1}),
\end{align*}
where the big-O notation omits a constant depending  only on $d$, $\alpha$, $K$, $L_\rho$,
and 
\begin{align*}
\big\{\|\rho_t^{(K+2-i)}\|_{\m C^{2K+2i-2,\alpha}}: i\in[K+2]\big\}, \hbox{ and }
\sup\big\{\|\rho_r^{(i)}\|_{\m C^{2j}}: r\in[t, t+\varepsilon], \,\, i,j\in\mb N,\,\,i+j\leq K+1\big\}.
\end{align*}
\myqed (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:56:37.667363+00:00","domain":"probability theory","id":"claim_2eacd5e3ef0bef73bc38037e5b2a82f3aa74a0d89760d8f91dde28061e94e3f5","kind":"theorem","schema_version":1,"statement":"[Prop cox of arXiv:2609.00110, 'Phase Transition and Fluctuation Results for First-Passage Percolation on Spread-Out Cycle'] The following statements hold.
\begin{enumeratei}
\item  \textup{(Independent residuals.)} For every deterministic $t\geqslant0$, conditionally on $\mathcal{F}_t^{\rm orig}$,
the family
\begin{align*}
 \{R_e:e\in\mathcal{B}_{\mathfrak{a}_\ell t}\}
\end{align*}
is independent and each variable has the $\mathrm{Exp}(1)$ law.

\item  \textup{(Collision event.)} For every deterministic $s\geqslant0$, with $t=s/\mathfrak{a}_\ell $, on $\Omega_*$,
\begin{align}
 \{\mathsf{S}_{\mathrm{col}}>s\}
 =
 \bigcap_{e\in\mathcal{B}_s}
 \left\{
 R_e> L_e(t)^\theta-(L_e^{\mathrm{act}})^\theta
 \right\}.
\end{align}

\item  \textup{(Cox survival.)} For every $s\geqslant0$,
\begin{align*}
 \pr(\mathsf{S}_{\mathrm{col}}>s\mid\mathcal{F}_s)=e^{-\gL_s}.
\end{align*}
Consequently,
\begin{align*}
 \pr(\mathsf{S}_{\mathrm{col}}>s)=\E e^{-\gL_s}.
\end{align*}

\item  \textup{(Marked form.)}
Let $e_{\mathrm{col}}$ denote the a.s.\ unique bridge realising the collision, and put $\mathcal{B}_\infty:=\bigcup_{s\geqslant0}\mathcal{B}_s$.
For $e\in\mathcal{B}_\infty$, define its individual cumulative hazard by
\begin{align*}
 \gL_e(s)
 :=
 \begin{cases}
 0,
 &s<\mathfrak{a}_\ell\gt_e^{\mathrm{act}},\\
 \left(A_e(s)/\mathfrak{a}_\ell\right)^\theta-(L_e^{\mathrm{act}})^\theta,
 &s\geqslant\mathfrak{a}_\ell\gt_e^{\mathrm{act}}.
 \end{cases}
\end{align*}
Then $\gL_s=\sum_{e\in\mathcal{B}_\infty}\gL_e(s)$.
For every non-negative predictable field $(\Psi(e,s))_{e,s}$, \emph{i.e.,}~$s\mapsto\Psi(e,s)$ is left-continuous and adapted to
$(\mathcal{F}_s)_{s\geqslant0}$,
\begin{align}
 \E\bigl[\Psi(e_{\mathrm{col}},\mathsf{S}_{\mathrm{col}})\bigr]
 =
 \E\int_0^\infty
 e^{-\gL_s}\,
 \frac{2\theta}{\mathfrak{a}_\ell^\theta}
 \sum_{e\in\mathcal{B}_s}A_e(s)^{\theta-1}\Psi(e,s)
 \,\mathrm d s .
\end{align}
In words, conditionally on the censored exploration, the collision occurs on the
bridge $e$ in $[s,s+\mathrm d s)$ with rate
$\frac{2\theta}{\mathfrak{a}_\ell^\theta}A_e(s)^{\theta-1}\,\mathrm d s$, thinned by the
survival factor $e^{-\gL_s}$.
\end{enumeratei}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:54:10.966975+00:00","domain":"probability theory","id":"claim_2eafc52e55d6ad7db9ccfe109790d837ad0d509d4e9b66dec5a90c1d886d7e16","kind":"definition","schema_version":1,"statement":"[Definition 35 of arXiv:2606.12720, 'On McDiarmid's Inequality under Dependence \\ via Approximate Tensorization of Entropy'] {Hellinger Integral of Order $\alpha$}

