{"assumptions":[],"created_at":"2026-10-27T13:12:09.045229+00:00","domain":"probability theory","id":"claim_2f00aa8de79bc5c32986170f724b00bf21766f62213a446e2fcc5527dc509ad6","kind":"lemma","schema_version":1,"statement":"[Lemma lem:gaussianTVrate of arXiv:2608.25279, 'Provable Non-Acceleration of Standard Strang\\ Splittings of Kinetic Langevin Dynamics'] Let
\begin{equation*}
 Y_{n+1}=MY_n+G\xi_{n+1}
\end{equation*}
be a Gaussian autoregressive process on $\mathbb R^N$, with transition kernel $Q$, where $M\in\mathbb R^{N\times N}$ satisfies $\rho(M)<1$, $G\in\mathbb R^{N\times N'}$, the $\xi_n$ are i.i.d.\ standard Gaussian vectors in $\mathbb R^{N'}$, and the covariance $\Sigma_{n_0}$ of the $n_0$-step transition law is nonsingular for some $n_0\ge1$; this holds in particular when $GG^\top\succ0$, with $n_0=1$. Then the chain has a unique invariant law $\pi$, which is a centered Gaussian. Moreover,
\begin{equation}
 \limsup_{n\to\infty}\lVert \delta_zQ^n-\pi\rVert_{\mathrm{TV}}^{1/n}\le\rho(M)
 \qquad\text{for every initial state }z,
\end{equation}
and the limit exists and equals $\rho(M)$ for a suitable $z$. Finally, there are initial states $z,\widetilde z$ such that
\begin{equation}
 \lim_{n\to\infty}
 \norm{\delta_zQ^n-\delta_{\widetilde z}Q^n}_{\mathrm{TV}}^{1/n}=\rho(M).
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:13:49.975637+00:00","domain":"probability theory","id":"claim_2f0747e0c81f72e03ab8f4677c10d7233c893095bfa41fc168ca5df15e5ba7cc","kind":"lemma","schema_version":1,"statement":"[Lemma lem:tricks of arXiv:2411.07157, 'Rough differential equations in the flow approach'] For $\varphi\in C^\infty_c(\R^2)$ and $\psi\in C_c^\infty(\R)$, we define $A^\varphi (t_1,t_2,s_1,s_2)\eqdef\delta(t_1-s_1)\delta(t_2-s_2)\varphi(s_1,s_2)$, $B^\varphi(t_1,t_2,s_1)\eqdef\delta(t_1-s_1)\varphi(s_1,t_2)$, and $C^\psi(t_1,t_2,s_1)\eqdef\delta(t_1-s_1)\delta(t_2-s_1)\psi(s_1)$.

    Then, for every $N\geqslant1$, uniformly in $\varphi$, $\psi$ and $\mu\in(0,1]$, we have
    \begin{equs}
        \norm{K_{N,\mu}^{\otimes4}A^\varphi(t_1,t_2,s_1,s_2)}_{L^\infty_{t_1}L^1_{t_2}L^1_{s_1}L^1_{s_2}}&\lesssim \norm{K_{N,\mu}^{\otimes2}\varphi(s_1,s_2)}_{L^\infty_{s_1}L^1_{s_2}}\,,\\      \norm{K_{N,\mu}^{\otimes3}B^\varphi(t_1,t_2,s_1)}_{L^\infty_{t_1}L^1_{t_2}L^1_{s_1}}&\lesssim \norm{K_{N,\mu}^{\otimes2}\varphi(s_1,s_2)}_{L^\infty_{s_1}L^1_{s_2}}\,,\\\norm{K_{N,\mu}^{\otimes3}C^\psi(t_1,t_2,s_1)}_{L^\infty_{t_1}L^1_{t_2}L^1_{s_1}}&\lesssim \norm{K_{N,\mu}\psi(s_1)}_{L^\infty_{s_1}}\,.
    \end{equs}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:59:25.043983+00:00","domain":"probability theory","id":"claim_2f08dfb0684d0e34f4f2b01202ebfdcb4ab4141236fe33fded5ffe76e36b3fcf","kind":"lemma","schema_version":1,"statement":"[Lemma 14 of arXiv:2606.31936, 'Coupling and Maximal Inequalities for Graph-Dependent Empirical Processes'] Let $q : = \max_{m \in [M]} |B_{m}|$. For any fixed measurable function \(g\) and any $n \in \mathbb{N}$ and  \(t>0\),
