    \end{equation}
    Then $\Phi$ is called a \textit{(stationary) renewal process} with renewal distribution $\BQ$ if $(X_{n+1}-X_n)_{n\in\N}$ is a family of independent random variables with the common distribution $\BQ$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:12:20.546227+00:00","domain":"probability theory","id":"claim_2f98c9be041f9af3e458c2686a09b1e646c3611ad38d2c1e174700cf099e86a7","kind":"concept","schema_version":1,"statement":"[Lemma lem:dub of arXiv:2603.28161, 'Boundary four-point connectivities of conformal loop ensembles'] {dubedat2015}}]
Let $n\ge1$, $\mathbf{x}=(x_1,...,x_n)$ and $\varepsilon>0$. Let $U=\{(y_1,y_2,\mathbf{x}):|y_1-u|<\varepsilon, 0\le y_2-y_1<\varepsilon,\|\mathbf{x}-{\bf x}_0\|<\varepsilon\}$, and $\Delta=\{(y_1,y_2,\mathbf{x})\in U:y_1=y_2\}$. For $\rho,\tau,\sigma\in\mathbbm{R}$, consider the differential operator
\begin{equation}
\mathcal{M}=\frac{1}{2}\partial_{y_1}^2+\left(\frac{\rho}{y_1-y_2}+a(y_1,y_2,\mathbf{x})\right)\partial_{y_1}+\left(\frac{\tau}{2(y_2-y_1)}+b(y_1,y_2,\mathbf{x})\right)\partial_{y_2}+{\bf X}+\left(-\frac{\tau \sigma}{2(y_1-y_2)^2}+\frac{d(y_1,y_2,\mathbf{x})}{y_2-y_1}\right)
\end{equation}
where ${\bf X}:=\sum_{i=1}^nc_i(y_1,\mathbf{x})\partial_{x_i}$, and $a,b,c,d$ are smooth on $U$. Suppose $\alpha_-<\alpha_+$ are the two roots of the indicial equation $\alpha(\alpha-1)+(\tau+2\rho)\alpha-\tau \sigma=0$.

Suppose $f$ is a real-valued smooth function on $U\setminus\Delta$ such that $\mathcal{M} f=0$ and $f=O((y_2-y_1)^{\alpha_-+\delta})$ for some $\delta>0$. Further, assume that for ${\bf Y}:=\partial_{y_1}$ and ${\bf Y},{\bf X}$ satisfies the H\"ormander's condition on $U\setminus\Delta$. Then there exists a smooth function $g$ on $U$ such that $f=(y_2-y_1)^{\alpha_+}g$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:49:06.341443+00:00","domain":"probability theory","id":"claim_2f9f7c861fb7afac99a4a198db673a0977a27f4b3c5fa20065c634fefcdb089d","kind":"definition","schema_version":1,"statement":"[Definition of arXiv:2602.04303, '\Large\textbf{Strong solutions to SDEs with singular drifts driven by fractional Brownian '] $($$\mathcal{F}_t$-fractional Brownian motion [nualart2002regularization] $)$ Let $(\Omega,\mathcal{F},\mathbb{P},(\mathcal{F}_t)_{t\in[0,T]})$ be a filtered probability space where $(\mathcal{F}_{t})_{t\in[0,T]}$ is a filtration such that $\mathcal{F}_0$ contains all the sets of probability zero. We say that $B^H$ $(H<1/2)$ is a $\mathcal{F}_t$-fractional Brownian motion if there exists a $\mathcal{F}_t$-Brownian motion $W$ such that $B^H$ can be formulated as
			$$B_t^H=\int_0^tK_H(t,s)\mathrm{d} W_s,$$
			where for $0<\leq s\leq t\leq T$,
			\begin{align*}
				K_H(t,s):=C_H\left[\left(\frac{t}{s}\right)^{H-\frac12}(t-s)^{H-\frac12}+\left(\frac12-H\right) s^{\frac12-H}\int_s^tr^{H-\frac32}(r-s)^{H-\frac12}\mathrm{d} r\right].
			\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:48:00.288341+00:00","domain":"probability theory","id":"claim_2fa2af9427a34c8f1cf2694f37d38d9a0e7d21e505fe6ac47953f014fd733dd0","kind":"theorem","schema_version":1,"statement":"[Prop upscale of arXiv:2609.03033, 'An Overview of Einstein $4$-Manifolds'] Let $(M^4,g)$ be a smooth compact oriented Riemannian manifold,
 and suppose, for a fixed spin$^c$ structure $\mathfrak{c}$,  that there is a solution of the unperturbed Seiberg-Witten equations  ((drc of the paper)--(sd of the paper))  for every 
 metric $\widehat{g}$ in the conformal class of  $g$.  
Then the scalar curvature 
$s$ and self-dual Weyl curvature $W_+$ of $g$ must satisfy
\begin{equation}

\int_M \left(s-\sqrt{6}|W_+|\right)^{2}d\mu_g  \geq  72\pi^2 [c_1^+]^2 .
\end{equation}
 Moreover, if $c_1^+:= c_1(L)^+$ is non-zero, equality can only occur  if $g$ is an almost-K\"ahler metric for which $s-\sqrt{6}|W_+|$ is a  negative constant,  for which the 
