{"assumptions":[],"created_at":"2026-10-26T19:28:31.959497+00:00","domain":"probability theory","id":"claim_2fc3fb88ba5bd09fc644cbe0805043c9bd83ed3eb257e9dbd233554fd639b856","kind":"theorem","schema_version":1,"statement":"[Thm 27 (Pfaffian point process for general initial conditions) of arXiv:2512.02286, 'Pfaffian Transition Probability and Correlation Kernel of TASEP in Half-space'] Let $N\geq M\geq 0$ be integers such that $N+M$ is even and fix $y=(y_1,\dotsc,y_M)$ satisfying $y_M>N-M+1$.
    Let $L:\widetilde{\mathcal{X}}\times\widetilde{\mathcal{X}}\to\mathbb{C}^{2\times 2}$ be defined by \eqref{eq:L-ensemble empty} where the domain of $L(\vir_i,\vir_j)$ is extended to $1\leq i,j\leq N+M$. Additionally we require 
    \begin{align}
    \begin{split}

        L((i,x),\virst_{N+\ell}) & = \left[\begin{array}{cc}
            0 & 0 \\
            0 & \Xi_{N-\ell} (x)
        \end{array}\right]\mathbbm{1}_{i=N}, \\
        L(\virst_{N+k},(j,x))&\,=\,-L((j,x),\virst_{N+k})^T,
    \end{split}
    \end{align}
    for $1\leq i,j\leq N$, $1\leq k,\ell\leq M$ and $x\in\mathbb{N}$.
    Then
    \begin{equation}
        \mu_{N,M}(A|y) = \frac{\pf\left[L_{\mathcal{V}\cup\mathcal{U}\cup A}\right]}{\pf\left[J_\mathcal{X}+L\right]}.
    \end{equation}
    defines a Pfaffian point process on $\mathcal{X}$ with correlation kernel
    \begin{equation}
        K = J + \left(J_\mathcal{X}+L\right)^{-1}\Big|_{\mathcal{X}\times\mathcal{X}}
    \end{equation}
    (with $\left(J_\mathcal{X}+L\right)^{-1}$ now computed on the whole space $\widetilde{\mathcal{X}}=\mathcal{V}\cup\mathcal{U}\cup\mathcal{X}$) which is supported on configurations in $\Lambda_N$, and is proportional to $\mathcal{W}_{N,M}(\cdot|y)$ (defined in \eqref{eq:W-measure initial}) there.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:57:49.854841+00:00","domain":"probability theory","id":"claim_2fcb9caad94c0bf9134727bd9a9808c9f7160b845eaf0df27b6e646fced22def","kind":"concept","schema_version":1,"statement":"[Lemma prop:hook-prop of arXiv:2410.23944, 'Hitting time mixing for the random transposition walk'] Let $\lambda\vdash n$. Then,
