{"assumptions":[],"created_at":"2026-10-27T11:23:37.815961+00:00","domain":"probability theory","id":"claim_304a2d1540a796446f3c98b4fd909a6552f2479dcfa61f1d16e4756a7649a564","kind":"theorem","schema_version":1,"statement":"[Theorem 7 of arXiv:2609.03634, 'Joint Laws of Maximum Drawdown and Maximum Drawup for Spectrally Negative L\'{e}vy Process'] Fix $a<0<b$. Under $\mathbb{P}_{a,b}^{<}$, the following identities hold.
\begin{enumerate}[label=\textup{(\roman*)}]
\item For the pre-infimum process,
\begin{equation*}\small
\mathbb{P}_{a,b}^{<}\{M_{0,H_I}^-<d\}=\begin{cases}
0, & d\le -a,\\
\displaystyle
1-\left[\frac{W^{(\gamma)\prime}(d)W^{(\gamma)}(b-a)-W^{(\gamma)\prime}(b-a)W^{(\gamma)}(d)}{W^{(\gamma)\prime}(-a)W^{(\gamma)}(b-a)-W^{(\gamma)\prime}(b-a)W^{(\gamma)}(-a)}\right]
\left(\frac{W^{(\gamma)}(-a)}{W^{(\gamma)}(d)}\right),
& -a<d<b-a,\\
1, & d\ge b-a.
\end{cases}
\end{equation*}

\item For the intermediate process,
\begin{equation*}
\mathbb{P}_{a,b}^{<}\{M_{H_I,H_S}^-<d\}=\begin{cases}
0, & d\le0,\\[4pt]
\displaystyle
\frac{W^{(\gamma)}(b-a)}{W^{(\gamma)}(d)}
\exp\left\{-(b-a-d)\frac{W_+^{(\gamma)\prime}(d)}{W^{(\gamma)}(d)}\right\},
& 0<d<b-a,\\[12pt]
1, & d\ge b-a.
\end{cases}
\end{equation*}

\item For the post-supremum process,
\begin{equation*}
\mathbb{P}_{a,b}^{<}\{M_{H_S,T}^-<d\}=\begin{cases}
0, & d\le0,\\[4pt]
\displaystyle
\frac{\bigl(Z^{(\gamma)}(d)-1\bigr)\dfrac{W^{(\gamma)\prime}(d)}{W^{(\gamma)}(d)}-\gamma W^{(\gamma)}(d)}
{\bigl(Z^{(\gamma)}(b-a)-1\bigr)\dfrac{W^{(\gamma)\prime}(b-a)}{W^{(\gamma)}(b-a)}-\gamma W^{(\gamma)}(b-a)},
& 0<d<b-a,\\[14pt]
1, & d\ge b-a.
\end{cases}
\end{equation*}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:22:20.962326+00:00","domain":"probability theory","id":"claim_304de43d7668114f9d99f0f8cee05ae9a94b412de49fb70f3ef6155313940f5c","kind":"lemma","schema_version":1,"statement":"[Lem 12 of arXiv:2605.28776, 'Limiting distributions of triangle counts in linear preferential attachment models'] For a random variable $\go$ supported on $(0,1)$ and for $k\ge 1$, we have
