{"assumptions":[],"created_at":"2026-10-27T21:12:46.901304+00:00","domain":"probability theory","id":"claim_3085326f210966f8d24a336a162092c361ab479c541f5ac522734b54521c4394","kind":"definition","schema_version":1,"statement":"[Definition meaGWregedef of arXiv:2608.09856, '\bf Mass erasure on measured $\bbR$-trees,\\ applications to L\'evy forests'] We fix $\xi$ and $\varrho$, two probability distributions on $\mathbb{N}$. 
We assume that $\xi$ is (sub)critical: $\sum_{k\in \mathbb{N}} \xi (k) \! \leq \!  1$. 
We fix $c\! \in \!  \mathbb{R}^*_+$ and a (conservative) c{\`a}dl{\`a}g subordinator $S\! = \! (S_s)_{s\in \mathbb{R}_+}$ 
whose Laplace exponent $\phi (y)\! = \!   -\! \log {\bf E} [e^{-yS_1}]$ is given by 
\begin{equation}

\forall y\! \in \!  \mathbb{R}_+, \quad \phi(y)= \kappa y + \int_{\mathbb{R}^*_+} \!\! \! \! \big( 1\! -\! e^{-yz} \big) \, \Gamma (dz) , 
\end{equation} 
where $\kappa\! \in \!  \mathbb{R}_+$ and $\int_{\mathbb{R}^*_+}\!  \min (1, z)\,  \Gamma (dz) \! <\!  \infty$. For all $n\! \in \!  \mathbb{N}$, we fix $\Lambda_n, \Lambda_{\varnothing, n} \! \in \!  \mathcal{M}_{ 1} (\mathbb{R}_+)$ and we write $\Lambda\! = \! (\Lambda_n)_{n\in\mathbb{N}}$ and $\Lambda_\varnothing\! = \! (\Lambda_{\varnothing,n})_{n\in\mathbb{N}}$.
\begin{compactenum}

\smallskip

\item[$(a)$] A random variable $\tau\colon \Omega\!  \to\!  \mathbb{T}_{\!  \mathtt{dis}}$ is a ($\xi, \varrho$)-Galton--Watson forest (a GW($\xi, \varrho$)-forest for short) if ${\bf P} (\tau \! = \!  \mathbf t)\! = \!  \varrho (\mathbf k_\varnothing(\mathbf t))\prod_{u\in \mathbf t\backslash \{ \varnothing\}} \xi (\mathbf k_u (\mathbf t))$ for all $\mathbf t \! \in \!   \mathbb{T}_{\! \mathtt{dis}}$. If $\varrho \! = \!  \xi$, $\tau$ is a $\xi$-Galton--Watson tree  (a GW($\xi$)-tree for short). 

\smallskip

\item[$(b)$] We denote by $Q_{\xi, c, \phi, \Lambda} $ the law of $\widetilde{\mathtt{T}}\mathtt{ree}  (\tau\, ; (\ell (\cdot), w_\cdot, \mu_\cdot))$ where $\tau$ is a GW($\xi$)-tree and conditionally given $\tau$, the r.v.s
$(\ell (u),w_u,\mu_u)$, $u\! \in \!  \tau$, are independent and distributed as follows: for all $u\! \in \!  \tau$, all measurable and bounded $f_1, f_2 \colon   \mathbb{R}_+ \! \to\!  \mathbb{R}$, $f_3\colon \mathcal M_{\! f}(\mathbb{R}_+) \! \to\!  \mathbb{R}$, ${\bf P}$-a.s.\vspace{-1mm}
\begin{equation}

{\bf E} \big[ f_1(w_u)f_2(\ell(u))f_3 (\mu_u) \,\big| \, \tau \big]\!=\! \langle \Lambda_{\mathbf k_u (\tau)} ,  f_1 \rangle   \! \int_0^\infty \!\! \! dt \, ce^{-ct} f_2 (t) \, {\bf E} \big[ f_3 \big({\bf 1}_{[0, t]} (s) dS_s  \big)\big].\vspace{-1mm}
\end{equation}
\item[$(c)$] We denote by $P_{\xi, c, \phi, \Lambda, \varrho, \Lambda_{\varnothing}} $ the law of $\widetilde{\mathtt{T}}\mathtt{ree}  (\tau; (\ell (\cdot), w_\cdot, \mu_\cdot))$ where $\tau$ is a GW($\xi, \varrho$)-forest and conditionally given $\tau$ the r.v.s
$(\ell (u),w_u,\mu_u)$, $u\! \in \!  \tau$, are independent and distributed as follows: ${\bf P}$-a.s.~$\mu_\varnothing\! = \!   0$, $\ell (\varnothing)\! = \!  0$ and ${\bf E} [ f_1 (w_\varnothing) \, | \, \tau]\! = \!   \langle \Lambda_{\varnothing , \mathbf k_{\varnothing} (\tau)} , f_1   
\rangle $ and for all $u\! \in \!  \tau \backslash \{\varnothing \}$, ((lawatu of the paper)) holds true.

\smallskip

\item[$(d)$] We next denote by $\texttt Q_{\xi, c}$ the law on $(\mathbb{T}^0_{\! c} , {\boldsymbol{\delta}}_{\mathtt{GH}})$ 
of $\Phi^1_0$ under $Q_{\xi, c, \phi, \Lambda}$, which is the law of a purely metric GW($\xi, c$)-tree (we simply forget about the measure component under $Q_{\xi, c, \phi, \Lambda}$). Similarly we denote by $\texttt P_{\! \xi, c, \varrho}$ the law on $(\mathbb{T}^0_{\! c} , {\boldsymbol{\delta}}_{\mathtt{GH}})$ 
of $\Phi^1_0$ under $P_{\xi, c, \phi, \Lambda, \varrho, \Lambda_{\varnothing}} $. $\hfill \square$ 
\end{compactenum}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:33:12.347116+00:00","domain":"probability theory","id":"claim_3088e975b76392e737f8143a893e10e8e6b087e93cdd39675d09ce1fea303e16","kind":"definition","schema_version":1,"statement":"[Dfn 150 (chaotic IAMP, phase I) of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] Similarly to \eqref{eq:A-ell}, define $\bA^{\aux}=\bG^{\aux}/N^{1/2}$.
Take a large integer $\linit\geq 10(\ubl)$ with 
\beq

0  \ll \frac{1}{\linit} \ll 
1-\upp\ll \eta\ll\delta\ll 
  \frac{1}{L}\ll \epsilon \ll \iota' \ll\iota \ll 1\,.
\eeq
(Again, this should not be confused with Assumption~\ref{a:params}, which only applies to Sections~\ref{s:rerand} and \ref{s:sde}.) Consider the IAMP iterates $(\hat{\by}^{\ell},\hat{\bv}^{\ell})_{-\linit\leq \ell\leq -1}$ defined by
\beq
\begin{aligned}
  \hat{\by}^{\ell+1}&=
  \alpha^{-1/2}
  (\bA^{\aux})^{\top}
    \hat{\bv}^{\ell}
  -\alpha^{1/2}
    \hat{\by}^{\ell}\in\bbR^N,
  \\
  \hat{\bv}^{\ell}
  &=\bA^{\aux}\hat{\by}^{\ell}
  -\alpha^{-1/2}\hat{\bv}^{\ell-1}
  \in\bbR^M\,,
\end{aligned}
\eeq
started from
$\hat{\by}^{-\linit}$ a standard gaussian vector in $\R^N$,
and $\hat{\bv}^{-\linit}=\bzero\in\R^M$. As mentioned above, we also consider another input $\tilde{\bz}$
which is $\upp$-correlated with $\bz$ for some constant $\upp\in (0,1)$. Generate iterates $(\tilde{\by}^{\ell},\tilde{\bv}^{\ell})$ for
$-\linit\leq \ell\leq -1$ using the matrix $\tilde{\bG}^{\aux}$,
started from
  \[\begin{aligned}
  \tilde{\by}^{-\linit} &=\hat{\by}^{-\linit} \in \R^N\,, \\ 
  \tilde{\bv}^{-\linit} &=\bzero\in\R^M\,.\end{aligned}
  \]
\textbf{In particular, the initialization $\tilde{\by}^{-\linit}=\hat{\by}^{-\linit}$ is treated as fixed in the algorithm, meaning it will be part of the random seed $\omega$ (see \eqref{e:iamp.chaotic.omega} below).}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:25:40.178937+00:00","domain":"probability theory","id":"claim_308b91d18ec3a1a4af66e275d9eb988d6421c4a9ebf1c5c0bb99525dcf176f61","kind":"lemma","schema_version":1,"statement":"[Lemma lem:Diagonal of arXiv:2609.01562, 'Points of maximal traffic on a grid with obstruction'] Let $B=(c,d)\in\mathcal{R}_2(n)$ be such that $c\ge 1$, $d\ge 1$, and $c+d\le n$. Then,
