\begin{enumerate}
    \item $\infty$ is not in the support of $\operatorname{div}(g)$;
    \item $g(\infty) = 1$;
    \item For every $\mathbb{Z}$-invariant orbit $E$ in $\mathbb{C}$, that is, a subset of $\mathbb{C}$ of the form $e + \mathbb{Z}$, we have
    \[
    \sum_{a \in E} \operatorname{ord}_a(g) = 0.
    \]
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:20:15.486703+00:00","domain":"probability theory","id":"claim_30a8521b74cf40f0091a9d1a37955cee2db594d1d2de2fba5860fff50aad0094","kind":"concept","schema_version":1,"statement":"[Cor 83 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Let $j\geq 0$.
Let $n\geq 1$
and let $\alpha_{n}>\alpha_{n-1}>\dots >\alpha_{1}>\alpha_{0}=1$.
Let $(c_{0}, c_{1}, \dots, c_{n})$
be the unique solution to the linear system
\begin{displaymath}
\forall k\in \{0,\dots, n-1\},
\sum_{i=0}^{n} c_{i} \alpha_{i}^{-(k+1/2)} = 0,
\qquad
\sum_{i=0}^{n} c_{i} \alpha_{i}^{-(n+1/2)} = 1.
\end{displaymath}
Then
\begin{displaymath}
\psi_{2n+1, j} = \lim_{\varepsilon \to 0} (-1)^{n}\dfrac{2^{n} n! (n+1/2)}{(2\pi)^{n}}\vert\log\varepsilon\vert^{n+1/2}
\sum_{i=0}^{n} c_{i} \ind_{\Ns_{\varepsilon^{\alpha_{i}}}(\clus_j)},
\end{displaymath}
with convergence in $L^{2}(d\PP,\sigma(\Phi),H^{-\eta}(\C))$ for $\eta>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:00:15.223957+00:00","domain":"probability theory","id":"claim_30aaf3f4fa3c791936ab47115f87769dad1b1f4b3472a703dd330ef3a98facee","kind":"definition","schema_version":1,"statement":"[Definition 56 (The forests $\kH^{(3)}_n(\alpha,\delta,\eps)$ and $H_n^{(3)}(\alpha,\delta,\eps)$) of arXiv:2607.18201, 'Finding Adam in noisy trees'] Given $\cT_n$, let $(Z_v)_{v\in [n]}$ form a collection of conditionally independent random variables, with
\begin{align*}
    Z_v\stackrel{d}{=} \textrm{Bin}\left(n-d_{\cT_n}(v),\frac{\lambda}{n}\right).
\end{align*}
Recall $\gamma$ from \eqref{eq:def_gamma}. For any $\alpha\in (0,1),\delta>0$ and $\eps\in (0,\gamma)$, define $\kH_n^{(3)}(\alpha,\delta,\eps)$ to be the subforest of $\cT_n$ spanned by the vertices in 
\begin{align*}
\{1,2,\dots,\floor{n^{\gamma-\eps}}\}\cup\{v\in \{\floor{n^{\gamma-\eps}},\floor{n^{\gamma-\eps}}+1,\dots,n\}\cap D_{\cT_n}(\alpha+\delta):d_{\cT_n}(v)+Z_v>(1-\alpha)\log n\}.    
\end{align*}
Define further $H_n^{(3)}(\alpha,\delta,\eps)$ to be the subforest obtained from  $\kH_n^{(3)}(\alpha,\delta,\eps)$ by including in it all vertices in $[n]\setminus V(\kH_n^{(3)}(\alpha,\delta))$ as isolated vertices.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:16:46.149459+00:00","domain":"probability theory","id":"claim_30ac8e5585ceefe7e0eae949d4c6497327c67f056ed7ddb2d0803a6138cf7ec6","kind":"theorem","schema_version":1,"statement":"[Proposition prop:D15 of arXiv:2605.03718, 'Potential Hessian Ascent III:\\ Sampling the Sherrington--Kirkpatrick Model at $\beta < 1/'] Fix a finite number of replicas and let $G^-\in \mathcal Q$ be any quadratic bulk observable, where
