{"assumptions":[],"created_at":"2026-10-27T17:38:58.714336+00:00","domain":"probability theory","id":"claim_30d8d1732ac52eeeab153f2563f231f99f76a912b8bd6d3ee92d6a7761d35f6f","kind":"definition","schema_version":1,"statement":"[Definition def:RGflow of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] Let  $j \le N$ on $\Lambda = \Lambda_N$,  $j< \infty$ on $\Lambda = \Z^d$ and $\alpha \in [1/2,1]$.
\begin{enumerate}
\item Sequence $( \vec{\nu}_k , \vec{g}_k ,  \vec{\lambda}_k ,  K_k)_{k \le j} \in \prod_{k =0}^j \D_j (\alpha)$ is called the \emph{RG flow of length $j$} if there exist $(\delta u_{k})_{k=1}^j$ with
\begin{align}
	(\delta u_{k+1} ,   \vec{\nu}_{k+1} , \vec{g}_{k+1},  \vec{\lambda}_{k+1} ,  K_{k+1} ) = \Phi^{\Lambda}_{k+1} ( \vec{\nu}_k , \vec{g}_k ,  \vec{\lambda}_k ,  K_k )
	\quad \text{for all} \quad k < j
	.
\end{align}
The sequence is called the \emph{infinite RG flow} if the same holds with $j = \infty$.

We use the term \emph{bulk RG flow} for a sequence $( \vec{\nu}_k , \vec{g}_k, K_{\varnothing,k})_{k \le j} \in \prod_{k=0}^j \D_{\varnothing,k} (\alpha)$ with the same property.

\item For $j< \infty$,  sequence $( \vec{\nu}_k , \vec{g}_k )_{k \le j} \in \prod_{k =0}^j \cD_{\varnothing,k}^{(0)} (\alpha)$ is called the \emph{bulk perturbative RG flow of length $j$} if there exist $(\delta u_{k})_{k=1}^j$ with
\begin{align}
	(\delta u_{k+1} ,   \vec{\nu}_{k+1} , \vec{g}_{k+1}  ) = \mathbb{V}^{(0)} \Phi_{k+1}^{{\operatorname{pt}}} ( \vec{\nu}_k , \vec{g}_k )
	\quad \text{for all} \quad k < j .
\end{align}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:36:31.223676+00:00","domain":"probability theory","id":"claim_30d9017a80af25f00bec28443514f62215e778f47baa07d13459e92070e97d00","kind":"theorem","schema_version":1,"statement":"[Theorem 16 (Full convergence of a fixed anchored finite-time Hopf profile) of arXiv:2609.00501, 'Uniqueness of Finite-Time Varifold Limits for the M\"obius-Invariant Willmore Flow'] Under the hypotheses of Corollary~\ref{cor:hopf}, fix the oriented
normal gauge and the material anchor introduced above, and let
\(\widetilde\gamma_t\) be the anchored constant-speed profile
\eqref{eq:anchored-gauge}.  Set
\begin{equation}

 C_{\mathrm g}:=\left(\frac2\pi+64\right)^{1/2}.
\end{equation}
Then, for \(0\leq s<t<T\),
\begin{equation}

 \|\widetilde\gamma_t-\widetilde\gamma_s\|_{L^2(\Sph^1)}
 \leq
 \frac{C_{\mathrm g}}{\sqrt\pi}
 \sqrt{(t-s)\bigl(W(s)-W(t)\bigr)} .
\end{equation}
There are an embedded regular constant-speed curve
\(\gamma_T\in W^{2,2}(\Sph^1,\Sph^2)\cap C^1(\Sph^1,\Sph^2)\)
and a number \(L_T\in[\pi,8]\) such that, as \(t\nearrow T\),
\begin{align}
 \widetilde\gamma_t&\rightharpoonup\gamma_T
 &&\text{weakly in }W^{2,2}(\Sph^1,\R^3),\\
 \widetilde\gamma_t&\longrightarrow\gamma_T
 &&\text{strongly in }W^{1,2}(\Sph^1,\R^3),\\
 \widetilde\gamma_t&\longrightarrow\gamma_T
 &&\text{strongly in }C^{1,\alpha}(\Sph^1,\R^3),
   \quad 0<\alpha<\tfrac12,\\
 L(\widetilde\gamma_t)&\longrightarrow L_T=L(\gamma_T),
 \qquad |\partial_x\gamma_T|=L_T .
\end{align}
The trace of \(\gamma_T\) is the embedded \(C^1\) profile
\(\pi(\spt\Var_T)\) of the unique limiting Hopf torus.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:12:13.566905+00:00","domain":"probability theory","id":"claim_30da8ed07fbfd670d02360a4abe0bba0b906c024c80a021056b10f9b517ba477","kind":"theorem","schema_version":1,"statement":"[Corollary 20 (Finite-time fixed-marginal $W_2$ chaos) of arXiv:2608.28827, 'Quantitative Target Convergence and Uniform-in-Time\\ Propagation of Chaos for Langevin-Re'] Under the same assumptions, for every $1\le k\le N$,
