{"assumptions":[],"created_at":"2026-10-26T20:43:04.584759+00:00","domain":"probability theory","id":"claim_30fb84492d801bbff532935c6e62f27264bfe1c493fedddf021803846c169e32","kind":"lemma","schema_version":1,"statement":"[Lemma 23 of arXiv:2605.16868, '\ttl'] Let $\boldsymbol{F}_1$ and $\boldsymbol{F}_2$ be two operators in $\mathcal{R}$ with respective bounded parameters $(\gamma_1,k_1)$ and $(\gamma_2,k_2)$. Then for any $X\in \mathcal{D}_T(L_1)$ and all $n\geq1$, $m\geq0$, $i=1,2$,
\begin{enumerate}[label=(\roman*)]

\item
\begin{equation}

\|\boldsymbol{F}_i^{(m)}\pi^n_{X,F_i}(0)\|_{T,1} \leq \|\boldsymbol{F}_i^{(m)}\|_{op}\|X\|_{T,1} + \|\boldsymbol{F}_i^{(m+1)}\pi^{n-1}_{X,F_i}(0)\|_{T,1}\,,
\end{equation}

\item
\begin{equation}

\|\pi^n_{X,F_i}(0)\|_{T,1} \leq \bigg(\sum_{j=0}^{n-1}\|\boldsymbol{F}_i^{(j)}\|_{op}\bigg)\|X\|_{T,1}\,,
\end{equation}

\item
\begin{equation}

\begin{split}
&\boldsymbol{F}_2^{(m)}\sup_{0\leq s\leq t}\big|(\pi^n_{X,F_1}(0))(s) - (\pi^n_{X,F_2}(0))(s)\big| \\&\leq \boldsymbol{F}_2^{(m)}\sup_{0\le s\le t}\big|(\boldsymbol{F}_1-\boldsymbol{F}_2)(\pi^{n-1}_{X,F_1}(0))(s)\big|  \\
& \quad+ \boldsymbol{F}_2^{(m+1)}\sup_{0\leq s\leq t}\big|(\pi^{n-1}_{X,F_1}(0))(s) - (\pi^{n-1}_{X,F_2}(0))(s)\big|\,, 
\end{split}
\end{equation}

\item
\begin{equation}

\|\pi^n_{X,F_1}(0) - \pi^n_{X,F_2}(0)\|_{T,1} \leq \bigg(\sum_{j=0}^{n-1}\|\boldsymbol{F}_2^{(j)}\|_{op}\bigg)\frac{k_1\|\boldsymbol{F}_1-\boldsymbol{F}_2\|_{op}\|X\|_{T,1}}{1-\gamma_1}\,,
\end{equation}

\item
\begin{equation}

\|\Psi_{F_i}(X)\|_{T,1} \leq \frac{k_i\|X\|_{T,1}}{1-\gamma_i}\,,
\end{equation}

\item
\begin{equation}

\|\Psi_{F_1}(X)-\Psi_{F_2}(X)\|_{T,1} \leq \frac{k_1k_2\|\boldsymbol{F}_1-\boldsymbol{F}_2\|_{op}\|X\|_{T,1}}{(1-\gamma_1)(1-\gamma_2)}\,. 
\end{equation}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:48:24.616803+00:00","domain":"probability theory","id":"claim_30ff7f144cfaed7c77c33bea4894cbcb26d8169824ea870c0a2257d0b1ad4f41","kind":"concept","schema_version":1,"statement":"[Lemma g_moments of arXiv:2601.04997, 'Fluctuations of the Boundary-Driven Symmetric Zero-Range Process from the NESS'] For $\ell=1, 2$, we have that
