	\end{equation*}
	Thus $W$ preserves the full almost-K\"ahler structure
	$(g,J,\omega)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:05:09.524336+00:00","domain":"probability theory","id":"claim_315d1bd8f9caeee53fb6f5e450c4fad7b086ea691f604396ef9667b825bf6099","kind":"concept","schema_version":1,"statement":"[Prop pr:main_bound of arXiv:2411.03482, 'Ergodicity of 2D singular stochastic Navier--Stokes equations'] For any initial data $u[0] = u_{\mathfrak{r}}[0] + u_{\mathfrak{s}}[0]$ with $\|u_{\mathfrak{r}}[0]\|_{\mathcal{C}^{-\kappa}} \leq 2\alpha_0$ and $\|u_{\mathfrak{s}}[0]\| = \lambda$\,, define $w^{\mathcal{L}}$ and the stopping time $T$ as above. Then there exists some constant $C$ such that for any $0 < a, \alpha_0 < 1$, we have 
	\begin{equ}

		\mathbb{E} \Big( e^{\frac{T\wedge a}{2}}\|w^{\mathcal{L}}[T\wedge a]\|^2 - \|w^{\mathcal{L}}[0]\|^2\Big) \leq C \alpha_0 \cdot a^{1-6\kappa} \lambda^2 + C a\;.
	\end{equ} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:31:45.219849+00:00","domain":"probability theory","id":"claim_315d5855e774ff6878d4f001425a8261e438519c47505f17458ad3959039abe3","kind":"concept","schema_version":1,"statement":"[Theorem maintheorem of arXiv:2412.06086, 'Zeros of conditional Gaussian analytic functions, random sub-unitary matrices and q-series'] Fix $s>0$. Then in the limit $k\to\infty$ it holds that
\begin{align}
P_k\big(e^{-s/k}\big)=\frac{A(s)}{\sqrt{k\pi}}\, e^{-k\Psi (s)} (1+O(1/k))
\end{align}
with
\begin{align*}
A(s)=\sqrt{\frac{\log z_s}{2(z_s-s)}}, \quad \Psi(s)=\log z_s+\frac{1}{s} \operatorname{Li}_2(1-z_s),
\end{align*}
where
$z_s=e^{s+w_s}$ and $w_s=W_{-1}(-se^{-s})$ when $s\in(0,1)$ and $w_s=W_{0}(-se^{-s})$ when $s\ge 1$.
Moreover, for $t>0$,
\begin{align}
P_k\big(t; e^{-s/k}\big)=z_se^{t(1-z_s)} P_k\big(e^{-s/k}\big) \big(1+O(1/k)\big)\, .
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:59:24.053005+00:00","domain":"probability theory","id":"claim_31611a8cce7f7f9d9361e5dc0faa71b80b81eed8ee51deb3c75995954481ed99","kind":"lemma","schema_version":1,"statement":"[Lemma lem:multiplier of arXiv:2608.30888, 'Three-term asymptotics for discrete\\ Hardy--Rellich constants in high dimension'] For every fixed $q\in\mathbb N$ and $\beta>0$, there are
$N^{\mathrm{mult}}_{\beta,q}\in\mathbb N$ and positive constants
$C_{\beta,q},c_\beta$ such that, for all
$N\geq N^{\mathrm{mult}}_{\beta,q}$,
\begin{equation}
 \sup_{\substack{g\in\operatorname{ran}P_{<q}\\ \left\lVert g\right\rVert_2=1}}
 \int_{\mathbb T^N}|1-\rho^{-\beta}|^2|g|^2\,d\mu
 \leq \frac{C_{\beta,q}}N+C_{\beta,q}e^{-c_{\beta}N}.
\end{equation}
Consequently, for the same dimensions, if $h=\rho^\beta$,
$\phi\in\mathscr F_{q,N}$ and $v=h\phi$,
then
\begin{equation}
 \norm{P_{<q}v}_2\leq C_{\beta,q}N^{-1/2}\left\lVert v\right\rVert_2.
\end{equation}","status":"unverified"}

