{"assumptions":[],"created_at":"2026-10-27T19:58:40.870865+00:00","domain":"probability theory","id":"claim_3232f7120baed9b756836aa959e2ce7ae69800b62a4a9876d0d464368299360c","kind":"lemma","schema_version":1,"statement":"[Lemma lem:tail_coup of arXiv:2605.10491, 'Zero-couplings of infinite measures with cyclically monotone support and multivariate regu'] Let $P$ and $Q$ in $\mathcal{P}(\mathbb{R}^d)$ be regularly varying with auxiliary functions $b_1$ and $b_2$, indices $\alpha_1 > 0$ and $\alpha_2 > 0$, and limit measures $\mu$ and $\nu$ in $\mathrm{M}_{0}(\mathbb{R}^d)$, respectively. Let $\psi$ be a closed convex function such $\partial\psi$ contains the cyclically monotone support of some $\pi\in\Pi_{\mathrm{cm}}(P,Q)$. Every sequence of positive numbers $t_n \to \infty$ then contains a subsequence such that, as $n \to \infty$ along the subsequence, we have writing $B(t) = \operatorname{diag}(b_1(t) 1_d, b_2(t) 1_d)$,
    \begin{align}

        t_n \operatorname{res}\pi(B(t_n) \,\cdot\,) 
        &\raisebox{-0.5pt}{\,\scriptsize$\stackrel{\raisebox{-0.5pt}{\mbox{\tiny $0$}}}{\longrightarrow}$}\, \gamma 
        &&\text{in $\mathrm{M}_{0}(\reals^d\times\reals^d)$}, \\
        \notag
        B(t_n)^{-1} \partial \psi

        &\raisebox{-0.5pt}{\,\scriptsize$\stackrel{\raisebox{-0.5pt}{\mbox{\tiny $\mathcal{F}$}}}{\longrightarrow}$}\, \partial\bar{\psi} 
        &&\text{in $\mathcal{F}(\reals^d\times\reals^d)$}, 
    \end{align}
	for some $\gamma \in \Gamma_{0,\mathrm{cm}}(\mu, \nu)$ and some closed convex function $\bar{\psi}$ satisfying $\operatorname{spt} \gamma \subset \partial \bar{\psi}$ and $\bar{\psi}(0) = \inf_{x\in\mathbb{R}^d} \bar{\psi}(x) < \infty$.
    If $\Gamma_{0,\mathrm{cm}}(\mu, \nu)$ is a singleton, say $\left\{\gamma\right\}$, then we actually have $t \operatorname{res} \pi(B(t) \,\cdot\,) \raisebox{-0.5pt}{\,\scriptsize$\stackrel{\raisebox{-0.5pt}{\mbox{\tiny $0$}}}{\longrightarrow}$}\, \gamma$ as $t\to\infty$, and, with $E = \operatorname{diag}(\alpha_{1}^{-1} 1_d, \alpha_{2}^{-1} 1_d)$, the measure $\gamma$ satisfies
    \begin{equation}

        \forall \lambda > 0, \qquad \gamma(\lambda^{-E}\,\cdot\,) = \lambda \gamma(\,\cdot\,);
    \end{equation}
    in particular, its support satisfies $\lambda^E \operatorname{spt} \gamma = \operatorname{spt} \gamma$ for all $\lambda > 0$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:23:37.839539+00:00","domain":"probability theory","id":"claim_323bc6724be351160f920345541e92686c991b9e658beed48148d79c539b97df","kind":"concept","schema_version":1,"statement":"[Theorem 3 (Caffarelli--Silvestre extension for the hierarchical Laplacian) of arXiv:2609.03647, 'Extension Problems for the Vladimirov--Taibleson Operator and the Hierarchical Laplacian'] Let $f\in \mathcal{S}_0(X)$ and assume the standing hypotheses above.
Suppose that
\begin{align*}
    \kappa:=\lim_{k\to+\infty}\frac{\lambda(B_k(x))}{C(B_k(x))}
\end{align*}
exists, belongs to $(0,+\infty)$, and is independent of $x$, with convergence uniform on compact subsets of $X$. Consider the following extension problem
    \begin{align*}
        \begin{cases}
        \Delta_W\varphi(v_B)=0,&v_B\in\mathcal{T}_X;\\
        \varphi|_{\partial\mathcal{T}_X}(x)=f(x),&x\in X;\\
        \varphi(\infty)=0.
    \end{cases}
    \end{align*}
    Here $W(B,B')=\frac{1}{\kappa}\frac{m(B)\lambda(B)\lambda(B')}{C(B)}$, where $B'$ is the unique immediate super-ball of $B$. The problem has a unique solution in the canonical class of harmonic functions with an $L^2(X,m)$ trace and a flux
    \begin{align*}
        \Phi(B)=W(B,B')\left(\varphi(v_B)-\varphi(v_{B'})\right)
    \end{align*}
    of the form
    \begin{align*}
        \Phi(B)=\int_Bg_\varphi(y)dm(y),
        \qquad g_\varphi\in \mathcal{S}_0(X).
    \end{align*}
    For this solution, $g_\varphi=\kappa^{-1}L_Cf$. Given a chain $\cdots\supseteq B_{k-1}(x)\supseteq B_k(x)\supseteq B_{k+1}(x)\supseteq\cdots\ni x$, define the deformed normal derivative at $x\in\partial\mathcal{T}_X\setminus\{\infty\}$ by
    \begin{align*}
        \partial_n^{(W)}\varphi(x)=\lim_{k\to+\infty}\frac{W(B_k,B_{k-1})}{m(B_k)}(f(x)-\varphi(v_{B_{k-1}})),
    \end{align*}
    where the limit exists in $L^2(X,m)$. The corresponding Dirichlet-to-Neumann map is the hierarchical Laplacian:
    \begin{align*}
        \partial_n^{(W)}\varphi(x)=L_Cf(x).
    \end{align*}
    Here the equality holds in $L^2(X,m)$.
    The solution also satisfies the energy identity
\begin{align*}
    \frac{1}{2}\sum_{\substack{v_A,v_B\in \mathcal{T}_{X}\\v_A\sim v_B}}|\varphi(v_A)-\varphi(v_B)|^2W(A,B)
    =&\frac{1}{\kappa}\int_Xf(x)L_Cf(x)dm(x).
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

