{"assumptions":[],"created_at":"2026-10-27T21:41:19.332792+00:00","domain":"probability theory","id":"claim_32728224b8c730d1970c84bbdcfcae3dbe7a445cd3236fe996455eb4a20bb813","kind":"lemma","schema_version":1,"statement":"[Lemma def:weak_axioms2 of arXiv:2609.04138, 'The conformally invariant metric on $\CLE_4$ I:\\ subsequential limits of the non-simple C'] Taking images under conformal maps is a bijection, with inverse the restriction to $U=\BD$, from the couplings $(\Gamma,D)$, $\Gamma$ a non-nested $\CLE_4$ in $\BD$ and $D$ a metric on $\Gamma$, satisfying the following conditions onto the weak geodesic $\CLE_4$ metric couplings of~(def:weak_axioms of the paper):
	\begin{enumerate}[label=(\Roman*), ref=\Roman*]
		\item {\bfseries (Weak geodesic metric)} Recall that the metric ball $\SCB_t(\SCL)=\SCB_t(\SCL; D)$ (resp.~$\SCB_t^-(\SCL)=\SCB_t^-(\SCL; D)$) denotes the closure of the union of the domains surrounded by $\SCL^\prime$ for $\SCL^\prime\in\Gamma$ with $D(\SCL,\SCL^\prime) \le t$ (resp.~$D(\SCL,\SCL^\prime) < t$). For a general subset $A\subset\overline\BD$, define
		\begin{equation*}
			D(\SCL, A) \defeq \inf\bigl\{t \ge 0: \SCB_t(\SCL) \cap A \neq \emptyset\bigr\}, 
		\end{equation*}
		and in particular $D(\SCL, z) \defeq D(\SCL, \{z\})$ for all $z \in \overline{\BD}$. Also write $\SCB_t(A)=\SCB_t(A;D)$ (resp.~$\SCB_t^-(A)=\SCB_t^-(A;D)$) for the closure of the union of $A$ and of the domains surrounded by $\SCL$ for $\SCL\in\Gamma$ with $D(\SCL,A)\le t$ (resp.~$D(\SCL,A)<t$). Then:
		\begin{enumerate}[label=(\roman*), ref=\roman*]
			\item Let $\SCL \in \Gamma$ and $t \ge 0$. Then the metric ball $\SCB_t(\SCL)$ is connected. The same is true with a deterministic connected arc of $\partial \BD$ in place of $\SCL$.
			\item Let $\SCL \in \Gamma$ and $t \ge 0$. Then
			\begin{equation*}
				\lim_{t^\prime \downarrow t} \SCB_{t^\prime}(\SCL) = \SCB_t(\SCL) \quad \text{and} \quad \lim_{t^\prime \uparrow t} \SCB_{t^\prime}(\SCL) = \SCB_t^-(\SCL)
			\end{equation*}
			with respect to the Hausdorff metric, the second limit being required only for $t > 0$; see (subsec:setup of the paper) for the convention used when a ball is empty. The same is true with a deterministic connected arc of $\partial \BD$ in place of $\SCL$.
			\item Let $\SCL_1, \SCL_2 \in \Gamma$ and $t \ge 0$. Suppose that $\SCB_t(\SCL_1) \cap \SCL_2 = \emptyset$. Then
			\begin{equation*}
				D(\SCL_1, \SCL_2) = t + D( \SCL_2, \SCB_t(\SCL_1)). 
			\end{equation*}
			The same is true with a deterministic connected arc (resp.~two deterministic and disjoint connected arcs) of $\partial \BD$ in place of $\SCL_1$ (resp.~$\SCL_1$ and $\SCL_2$).
			\item Let $\SCL_1, \SCL_2 \in \Gamma$. Then, the compact set $K_{\SCL_1, \SCL_2}$ defined as the closure of $ \{ z \in \overline{\BD}, \ D(\SCL_1, z)+ D(\SCL_2,z)= D(\SCL_1, \SCL_2) \}$ contains a connected component $\widetilde{K}_{\SCL_1, \SCL_2} $ that contains both $\SCL_1$ and $\SCL_2$. The same is true with a deterministic connected arc (resp.~two deterministic and disjoint connected arcs) of $\partial\BD$ in place of $\SCL_1$ (resp.~$\SCL_1$ and $\SCL_2$). 
		\end{enumerate}
		\item {\bfseries (Locality)} Let $V \subseteq \BD$ be a deterministic simply connected subdomain. Let $\{V_j\}_j$ be the connected components of $V^\star$ (cf.~(equation eq:def-V-star of the paper)). Let $I$ be a deterministic connected arc of $\partial \BD$. For each $j$, let $\phi_j$ be a conformal mapping from $V_j$ onto $\BD$ that is a.s.\ determined by
		\begin{multline}
			\bigl\{\SCL \in \Gamma: \SCL \not\subseteq V\bigr\} \quad \text{and} \quad \bigl\{\SCB_t(\SCL): \SCL \in \Gamma, \ \SCL \not\subseteq V, \ t \in [0, D(\SCL, \partial V^\star)]\bigr\}, \\
			\text{and} \quad \bigl\{\SCB_t(I): t \in [0, D(I, \partial V^\star)]\bigr\}.
		\end{multline}
		There exists a coupling of $(\Gamma, D)$ with some $(\phi_j(\Gamma\vert_{V_j}), D_j)$'s such that 
		\begin{itemize}
			\item Conditionally on~(equation eq:weak_axiom_locality2 of the paper), the $(\phi_j(\Gamma\vert_{V_j}), D_j)$'s are independent and their conditional laws are those of $(\Gamma, D)$.
