\end{equation}
Then for every pair  $(s,t)\in C^2_{+}$ 
\begin{equation}
\overline{\mathbb{E}} \bigl[  \overline{N}_{a_k}  (t)\lvert \mathscr{H}_{s} \bigr]= \overline{N}_{a_k}(s).
\end{equation}
Moreover,
\begin{align}
\sup_{k \ge 2}\;\;\sup_{t \in C  }\; \overline{\mathbb{E}} \left[ \lvert{\overline{N}_{a_k}(t)}\rvert^{2} \right] <\infty.
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:44:17.354923+00:00","domain":"probability theory","id":"claim_3277f06ba553470f5faec2c361d3e85f5b872ce2777d0ada8b987d8bbf1d0498","kind":"lemma","schema_version":1,"statement":"[Lemma lem:sampling-alg-exact-remask of arXiv:2608.23554, 'Provably adaptive sampling with uniform and remasking \\ discrete diffusion models'] Consider the remasking process with parameter \(p_M\) and let \(\rho = \sqrt{1 - p_M}\).
    Recall \(\widehat \mu_i(b)\) defined in~(eq:sampling-alg of the paper):
    \begin{equation*}
        \widehat \mu_i(b) \ \propto\ \Pr(X_{\ell}^i = x_{\ell}^i \mid X_u^i = b)\left(\widehat \Pr(X_0^i = b \mid X_{\ell}^{-i} = x_{\ell}^{-i}) e^{-u} + \nu(u, b)(1 - e^{-u})\right).
    \end{equation*}
    Then, for \(x_{\ell}^i \in [S]\),
    \begin{equation*}
        \widehat \mu_i(b) \ \propto\ \begin{cases}
            \left(\widehat \Pr(X_0^i = b \mid X_{\ell}^{-i} = x_{\ell}^{-i}) + \frac{
            \cosh(u \rho) - 1
            }{S}\right) \left(\bI\{b = x_{\ell}^i\} + \frac{\cosh(\Delta\rho) - 1}{S}\right), \quad &\text{if } b \in [S], \\
            \frac{1}{S} \sinh(u\rho)\sinh(\Delta\rho), \quad &\text{if } b = \mathrm{REMASK}, \\
            0 ,&\text{if } b = \mathrm{MASK}.
        \end{cases}
    \end{equation*}
    For \(x_{\ell}^i = \mathrm{REMASK}\),
    \begin{equation*}
        \widehat \mu_i(b) \ \propto\ \begin{cases}
                        \left(\widehat \Pr(X_0^i = b \mid X_{\ell}^{-i} = x_{\ell}^{-i}) + \frac{
            \cosh(u \rho) - 1
            }{S}\right) \rho \sinh(\Delta \rho), \quad &\text{if } b \in [S], \\
            \rho\sinh(u\rho)\cosh(\Delta\rho), \quad &\text{if } b = \mathrm{REMASK}, \\
            0 ,&\text{if } b = \mathrm{MASK}.
        \end{cases}
    \end{equation*}
    For \(x_{\ell}^i = \mathrm{MASK}\),
    \begin{equation*}
        \widehat \mu_i(b) \ \propto\ \begin{cases}
                        e^{-u}\left(\widehat \Pr(X_0^i = b \mid X_{\ell}^{-i} = x_{\ell}^{-i}) + \frac{
            \cosh(u \rho) - 1
            }{S}\right) \left(1 - e^{-\Delta}\left(\cosh(\Delta \rho) + \rho \sinh(\Delta\rho)\right)\right), \quad &\text{if } b \in [S], \\
            e^{-u}\rho\sinh(u\rho)\left(1 - e^{-\Delta} \left(\cosh(\Delta \rho) + \frac{\sinh(\Delta \rho)}{\rho}\right)\right), \quad &\text{if } b = \mathrm{REMASK}, \\
            1 - e^{-u}\left(\cosh(u \rho) + \rho \sinh(u \rho)\right) ,&\text{if } b = \mathrm{MASK}.
        \end{cases}
    \end{equation*}
    Normalization factor should be computed separately for each of the three cases: \(x_{\ell}^i \in [S], x_{\ell}^i = \mathrm{REMASK},\) and \(x_{\ell}^i = \mathrm{MASK}\).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:02:11.304277+00:00","domain":"probability theory","id":"claim_32788dc88c85f8fd10e7754971d1f4b3d9cd98efb9c94a529296564922686360","kind":"theorem","schema_version":1,"statement":"[Prop prop-busemann-uihbot of arXiv:2510.26123, 'Directed distances in bipolar-oriented triangulations:\\ exact exponents and scaling limit'] Let $\{x_k^{\operatorname{b}}\}_{k\in\mathbbm Z}$ be the boundary vertices of the UIBHBOT as in the discussion just after~(equation eqn-uihbot-bdy-time of the paper). There exists a unique function $\mathcal X^{\operatorname{b}} :  \mathbbm Z \to \mathbbm Z$, called the \textbf{Busemann function}, such that $\mathcal X^{\operatorname{b}}(0) = 0$ and the following is true. Let $k,k' \in \mathbbm Z$ and let $\{w_j\}_{j\in\mathbbm N}$ be a sequence of distinct vertices of $M^{\operatorname{b}}$ such that for each $j\in\mathbbm N$, each of $x_k^{\operatorname{b}}$ and $x_{k'}^{\operatorname{b}}$ can be joined to $w_j$ by a directed path in $M^{\operatorname{b}}$. Then
\begin{equation} 
\mathcal X^{\operatorname{b}}(k') -\mathcal X^{\operatorname{b}}(k) = {\operatorname{XDP}}_{M^{\operatorname{b}}}(x_{k'} , w_j) - {\operatorname{XDP}}_{M^{\operatorname{b}}}(x_{k } , w_j) ,\quad \text{for each sufficiently large $j\in\mathbbm N$.}
\end{equation}
Furthermore, the increments $\mathcal X^{\operatorname{b}}(k) - \mathcal X^{\operatorname{b}}(k-1)$ are i.i.d., and if $\mathcal X$ is the Busemann function for $M_{0,\infty}$ as in Theorem~(thm-busemann of the paper), then 
\begin{equation}  
\mathcal X^{\operatorname{b}}(k) - \mathcal X^{\operatorname{b}}(k-1) \overset{d}{=}   \mathcal X(0) - \mathcal X(-1) .
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:25:44.577841+00:00","domain":"probability theory","id":"claim_32790cdfc5011f32b7de21b22c807e5feabfd0ab5c8c544e8ccbbf58fb65f25f","kind":"concept","schema_version":1,"statement":"[Lemma lem: validity of D of arXiv:2509.04349, 'Precise asymptotics for the norm of large random rectangular Toeplitz matrices'] For any $x\in\mathbb{R}$, any integers $1\leq s_1<\cdots<s_R\leq m$, and all sufficiently large $m$, we have
