{"assumptions":[],"created_at":"2026-10-27T09:13:18.508046+00:00","domain":"probability theory","id":"claim_32b8e7a930fd9058bb6b6b8a65ac852653549d0375bae367168e6f753b9b48a0","kind":"theorem","schema_version":1,"statement":"[Corollary 17 of arXiv:2608.30589, 'Vector-Valued Wavelet Bases as Hilbert $\mathbb{M}_m(\mathbb{R})$-Module Bases: A Construc'] Consider the following classes of wavelet bases:
\begin{enumerate}
    \item A wavelet basis of \(L^2(\mathbb{R})\) associated with an MRA.
    \item A vector-valued wavelet basis of \(L^2(\mathbb{R}, \mathbb{R}^m)\) (\(m \ge 2\)) associated with a VMRA.
    \item An \(m\)-multiwavelet basis of \(L^2(\mathbb{R})\) associated with an MRA.
\end{enumerate}
Then
\[
  \textup{(1)} \;\implies\; \textup{(2)}
  \quad\text{and}\quad
  \textup{(2)} \;\iff\; \textup{(3)}.
\]
In particular, any basis in \textup{(1)} yields bases in \textup{(2)} and \textup{(3)}, and the construction preserves regularity, vanishing moments, and compact support.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:16:46.145535+00:00","domain":"probability theory","id":"claim_32bb957b2ff24ff706f023b5bbdf759fa34f005a2cc1a2465c52ceeb877efb61","kind":"lemma","schema_version":1,"statement":"[Lemma lem:stability-s of arXiv:2605.03718, 'Potential Hessian Ascent III:\\ Sampling the Sherrington--Kirkpatrick Model at $\beta < 1/'] Fix the number of replicas $k\in\mathbb N$, and let $F: \Sigma^k \to \mathbb R$ be a bounded function of
$(\rho^1,\varepsilon^1),\dots,(\rho^k,\varepsilon^k)$. Assume that
\begin{equation}
    \sup_{s\in[0,1]}\ \max_{a<b\leqslant k+2}\ \big\|R^-_{ab}-q^*\big\|_{L^p(\nu_s)}
    \;+\;
    \sup_{s\in[0,1]}\ \max_{a\leqslant k+1}\ \big\|M^-_{a}-m^*\big\|_{L^p(\nu_s)}
    \;\leqslant\; C_{p,k}\,n^{-1/2}.
\end{equation}

Then, the following two stability statements hold for $F$ along the cavity interpolation,
\begin{enumerate}
    \item \textbf{Small perturbation for bulk functions}: For bulk functions the following holds
    \begin{equation} 
        \big|\nu_s(F)-\nu_1(F)\big|
        \;\leqslant\;
        C_{\beta,k}\,n^{-1/2}\int_s^1 \|F\|_{L^2(\nu_u)}\,du
        \;\leqslant\;
        C_{\beta,k}\,n^{-1/2}\,\sup_{u\in[s,1]}\|F\|_{L^2(\nu_u)}.
        \end{equation}
        In particular, if $\sup_{u\in[0,1]}\|F\|_{L^2(\nu_u)} = O(n^{-\alpha})$, then
        \[
        \sup_{s\in[0,1]}\big|\nu_s(F)-\nu_1(F)\big| = O\big(n^{-(\alpha+1/2)}\big).
        \]   
    \item \textbf{Gr\"onwall stability}: Via Gr\"onwall's inequality,
    \begin{equation}
        \big|\nu_t(F)-\nu_1(F)\big|
        \;\leqslant\;
        \Big(e^{4\beta^2 r(r+1)(1-t)}-1\Big)\,\nu_1(F).
    \end{equation}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:42:57.182688+00:00","domain":"probability theory","id":"claim_32bcda4fd47008e4314afe1d62ccd0118f95521de83ab5e0f673ed40cf98ba34","kind":"definition","schema_version":1,"statement":"[Definition def:axioms of arXiv:2609.04140, 'The conformally invariant metric on $\CLE_4$ III:\\ uniqueness'] By a (strong) $\CLE_4$ metric, we mean a family of \textbf{deterministic} measurable mappings 
    \begin{equation*}
        D = \left\{D^U \colon \mathscr{LoopEns}(U) \to \BR^{U_\BQ \times U_\BQ},\quad  \Gamma_U \mapsto D_{\Gamma_U}^U\right\}_U,
    \end{equation*}
    where $U \subsetneq \BC$ ranges over all simply connected domains, such that the following conditions are satisfied whenever $U \subsetneq \BC$ is a deterministic simply connected domain and $\Gamma_U$ is a non-nested $\CLE_4$ in $U$:
    \begin{enumerate}[label=(\Roman*), ref=\Roman*]
        \item {\bfseries (Geodesic metric)} The mapping $D_{\Gamma_U}^U$ a.s.\ determines a metric on $\Gamma_U$ such that for each $\SCL_1, \SCL_2 \in \Gamma_U$, there exists an admissible path $P$ (which we shall refer to as a \emph{$D_{\Gamma_U}^U$-geodesic}) connecting $\SCL_1$ and $\SCL_2$ such that $D_{\Gamma_U}^U(\SCL_1, \SCL_2) = \len(P; D_{\Gamma_U}^U)$. Moreover, for all conformal mapping $\phi \colon U \to \BD$, the process $(\phi(\SCB_t(\SCL; D^U_{\Gamma_U})))_{t\ge 0}$ is c\`adl\`ag with respect to the Hausdorff distance, and, for all $t, s\ge 0$, if $\SCB_t(\SCL_1; D^U_{\Gamma_U}) \cap \SCB_s(\SCL_2; D^U_{\Gamma_U}) \neq \emptyset$, then $D^U_{\Gamma_U} (\SCL_1, \SCL_2) \le t+s$. The same is true with a deterministic connected arc (resp.\ two deterministic disjoint connected arcs) of $\partial U$ in place of $\SCL_1$ (resp.\ $\SCL_1$ and $\SCL_2$).
        \item {\bfseries (Locality)} Let $V \subseteq U$ be a deterministic simply connected subdomain. Then, a.s., for each connected component $V_j$ of $V^\star$, 
        \begin{equation*}
            D_{\Gamma_U}^U(\SCL_1, \SCL_2; V_j) = D_{\Gamma_U|_{V_j}}^{V_j}(\SCL_1, \SCL_2), \quad \forall \SCL_1, \SCL_2 \in \Gamma_U|_{V_j}.
        \end{equation*}
        \item {\bfseries (Conformal invariance)} Let $\phi \colon U \to \phi(U)$ be a deterministic conformal mapping. Then, a.s., 
        \begin{equation*}
            D_{\Gamma_U}^U(\SCL_1, \SCL_2) = D_{\phi(\Gamma_U)}^{\phi(U)}(\phi(\SCL_1), \phi(\SCL_2)), \quad \forall \SCL_1, \SCL_2 \in \Gamma_U. 
        \end{equation*}









        \item {\bfseries (Uniform exploration)} The collection $\{(\SCL, D_{\Gamma_U}^U(\SCL, \partial U))\}_{\SCL \in \Gamma_U}$ has the law of a uniform exploration of $\Gamma_U$ (cf.\ [CoInCLEExpl]).
    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:44:39.705576+00:00","domain":"probability theory","id":"claim_32bddc82037b54875d1313757ef0286d55af6849a4d6dce46693103243ade895","kind":"theorem","schema_version":1,"statement":"[Proposition 4 (Zvonkin change-of-variables identity) of arXiv:2608.29726, '\LARGE A Priori Estimates for Singular Fractional Stochastic Burgers Equations'] For smooth data, the variable \(m\) from \eqref{eq:m-def} solves
\begin{equation}
  m_t-\partial_y\Dcal_{\Psi}^{\gamma}m
  =\partial_y\bigl(a m^2+2Q_\lambda m+R\bigr),
\end{equation}
where
\begin{equation}
\begin{aligned}
  a&=(J^2)^\Phi,
  &\qquad Q_0&=(\ell J)^\Phi,\\
  Q_\lambda&=Q_0+\frac\lambda2\psi^\Phi,
  &\qquad R&=(\ell^2)^\Phi.
\end{aligned}
\end{equation}
For a scalar field \(f\), define the transformed flux operator by
\begin{equation}
  \Dcal_{\Psi}^{\gamma}f
  =\bigl[
    \Rcal_\gamma(Jf^\Psi)
    +f^\Psi\Lambda^\gamma\psi
  \bigr]^\Phi.
\end{equation}
Throughout, \(\Dcal_\Psi^\gamma\) and
\(\Acal_{\Psi}^{\gamma}:=-\partial_y\Dcal_{\Psi}^{\gamma}\) are,
respectively, the transformed flux and diffusion operators.
Here \(a=(J^2)^\Phi\) is the coefficient of the quadratic transport
flux; the principal diffusion coefficient is
\((J^\gamma)^\Phi\).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:38:04.519613+00:00","domain":"probability theory","id":"claim_32bea28ed8c79562695f77ef8de1f60ee28f1e85bb449c0fbb94c019ff6f5bea","kind":"concept","schema_version":1,"statement":"[Theorem of arXiv:2607.18011, 'From local giants to locality in long-range percolation'] \thlabel{cor:characters_smoothness}
    Let $G$ be a transitive graph of polynomial growth with $d \geq 1$, and suppose that $J : V \times V \to \mathbf{R}_+$ is a transitive kernel satisfying $J(x,y) = \Omega (d_G(x,y)^{-d \alpha})$ with $\alpha \in (1,2)$.

