{"assumptions":[],"created_at":"2026-10-27T17:38:58.708609+00:00","domain":"probability theory","id":"claim_333d68572bbec451de2ad71f0f2ffbf9beb66a5aa56ef6a1859f3db661271d04","kind":"concept","schema_version":1,"statement":"[Proposition prop:theFRD of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] Let $d \ge 3$,  $\eta \in [0,2)$ and $\vec{\textbf{a}} \in \operatorname{HB}_{\epsilon_p}$ for sufficiently small $\epsilon_p$.  Then there exist covariance matrices $\Gamma_j$ on $\Z^d$ such that (equation eq:LetaFRD of the paper) and the following hold.

\begin{enumerate}
	\item (Symmetries) $\Gamma_j : \Z^d \times \Z^d \rightarrow \R$ is a covariance matrix invariant under isometries,
	i.e., $\Gamma_t \ge 0$ and $\Gamma_t (E (x) , E(y)) = \Gamma_j (x,y)$ for any isometry $E : \Z^d \rightarrow \Z^d$.
	\item (Finite range property) $\Gamma_j$ has range $< L^j$ in the $\ell^1$-metric,  i.e.,  $\Gamma_j (x,y) =0$ whenever $\norm{x-y}_{\ell^{1}} \ge L^j$. 
	\item (Upper bound) For each $k, k_x,k_y \ge 0$ with $k_x + k_y = k$,  
	\begin{align}
		\big\| \nabla_x^{k_x} \nabla_y^{k_y} \Gamma_{j+1} (x,y) \big\|_{\ell^\infty (\Z^d \times \Z^d)} \le C_k \frac{L^{-(d-2+\eta)j}}{1 + \textbf{a}^{(\emptyset)} L^{(2-\eta)j}}	 .  
	\end{align}
	uniformly in $j,  L$ for some constant $C_k$.	
\end{enumerate}
When $\textbf{a}^{(\emptyset)} >0$ and $\Lambda = \Lambda_N$,  then there exist $t_N >0$ and a covariance $\Gamma_N^{\Lambda}$ on $\Lambda_N$,  that satisfy (equation eq:LetaFRD of the paper) with $\Gamma_j$ the projections of those of $\Z^d$ and satisfy the following.
\begin{enumerate}
	\item $\Gamma_N^{\Lambda}$ satisfies the same symmetries and the upper bounds as $\Gamma_N$.  

	\item $t_N \in (0, (\textbf{a}^{(\emptyset)})^{-1})$ and there exists $C >0$ such that $t_N >  (\textbf{a}^{(\emptyset)})^{-1} - CL^{(2-\eta) N}$.
\end{enumerate}
Moreover,  $\Gamma_j$ is continuous in $\vec{\textbf{a}} \in \operatorname{HB}_{\epsilon_p}$ and $\Gamma_N^{\Lambda}$ and $t_N$ are continuous in $\vec{\textbf{a}} \in \operatorname{HB}_{\epsilon_p} \backslash \{ \textbf{a}^{(\emptyset)} = 0 \}$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:52:23.575556+00:00","domain":"probability theory","id":"claim_3345099fdcd068ac84d06d6dd120df1e20275adfc7965b0e746fd9c81f1a2cab","kind":"lemma","schema_version":1,"statement":"[Lemma L:LX23cond of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] Let $\alpha > 0$, $\beta \in (0, 2]$, $\gamma \ge 0$, $H \in [1/2, 1)$ and
