	Moreover, if $w$ and $w'$ are not isomorphic, the functions $u\mapsto c(w,u)$ and $u\mapsto c(w',u)$ are restrictions of distinct analytic functions, and they are distinct almost everywhere on $[0,1]$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:06:55.278548+00:00","domain":"probability theory","id":"claim_337fa9fa88fafb5ea48ee0d7f8f97e3a41d28f70709baddfb5c91545e3d75050","kind":"concept","schema_version":1,"statement":"[Lemma lem:independent of arXiv:2601.08184, 'Wasserstein-p Central Limit Theorem Rates: From Local Dependence to Markov Chains'] Let $\{X_i\}_{i=0}^{n-1}$ be an independent sequence of of $\mathbb{R}^d$-valued random vectors with $\mathbb{E}[X_i]=0$ and $\frac{1}{n}\operatorname{Var}(S_n) = I_d.$ If $\sup_{0 \leq i \leq n-1}\mathbb{E}[\|X_i\|^{p+q}] \in \mathcal O(1) $ for some $p \geq 2$ and $q \in (0,2]$, we have
    \begin{align*}
       \mathcal{W}_p(\mathcal{L}(\tfrac{S_n}{\sqrt{n}}), \mathcal{N}(0, I_d)) \in \mathcal{O}(n^{-\frac{p+q-2}{2p}})  .
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:01:22.580512+00:00","domain":"probability theory","id":"claim_3385445d327abeea4b23c625c8e250e9ef4ab7e17e64e1ec0155c28b08f7ba8f","kind":"lemma","schema_version":1,"statement":"[Lemma Qn of arXiv:2605.16963, 'Stochastic Euler Equations with Pseudo-differential Noise: Continuous and Discontinuous Pe'] Let $\mathcal Q_1,\mathcal Q_2\in \mathbb{A}^{\alpha}\cup \mathbb{B}^{\beta}$ with symbols taking values in $\mathbb{C}^{d\times d}$ and with fixed decomposition.   There exist  sequences $\{\mathcal Q_{i,n}\}_{n\ge1}$ $(i=1,2)$ such that the following properties hold:
		\begin{enumerate}[label={{\bf (\arabic*)}},leftmargin=0.79cm]\setlength\itemsep{0.2em}
			\item For $i=1,2$ and $n\ge1$, $\mathcal Q_{i,n}\in{\rm OP}\mathbf S^{-\infty}$ if $\mathcal Q_i\in\mathbb{A}^{\alpha}$ or $\mathcal Q_{i,n}\in{\rm OP}\mathbf S_0^{-\infty}$ if $\mathcal Q_i\in\mathbb{B}^{\beta}$;



			\item $\{\mathcal Q_{i,n}\}_{n\ge1}\subset \mathbb{A}^{\alpha}$ is bounded   if $\mathcal Q_{i}\in \mathbb{A}^{\alpha}$ and $\{\mathcal Q_{i,n}\}_{n\ge1}\subset \mathbb{B}^{\beta}$ is bounded if $\mathcal Q_{i}\in \mathbb{B}^{\beta}$; 

			\item Let $\delta_i=\delta_{\mathcal Q_i}$ be given in (equation delta-Qi of the paper). Then, for $i=1,2$ and $\theta\ge0$,
			\begin{align}
				\lim_{n\to\infty}\|\mathcal Q_{i,n}f-\mathcal Q_{i}f\|_{H^{\theta}} =0,\qquad f\in H_d^{\theta+\delta_i}, 
			\end{align}
			\begin{align}
				\|\mathcal Q_{i,n}-\mathcal Q_{i,m}\|_{\mathscr L(H^s,H^{\theta})} 
				\lesssim  (n \land m)^{-(s-\theta-\delta_i)},\qquad s>\theta+\delta_i,
			\end{align}
			\begin{align}
				\|\mathcal Q_{i,n}^2-\mathcal Q_{i,m}^2\|_{\mathscr L(H^s,H^{\theta})}
				\lesssim   (n \land m)^{-(s-\theta-2\delta_i)},\qquad s>\theta+2\delta_i.
			\end{align}

			\item $($\textbf{Uniform cancellation in renormalization}$)$  Let $s \ge 0$. There exist constants $C_{i,j}=C_{i,j}(s,d)>0$, for $i,j\in\{1,2\}$, such that
			\begin{equation}
				\sup_{n \ge 1} \left| \langle f, \mathcal{Q}_{i,n} f \rangle_{H^s} \right| \leq C_{i,1} \|f\|^2_{H^s}, \qquad f \in H_d^s, \quad i = 1,2,
			\end{equation}
			and
			\begin{equation}
				\sup_{n \ge 1} \left| \langle \mathcal{Q}_{i,n}^2 f, f \rangle_{H^s} + \langle \mathcal{Q}_{i,n} f, \mathcal{Q}_{i,n} f \rangle_{H^s} \right| \leq C_{i,2} \|f\|^2_{H^s}, \qquad f \in H_d^s, \quad i = 1,2.
			\end{equation}

			\item  In particular, 
			if $\mathcal Q_i\in\mathbb{B}^\beta$ satisfies $\mathcal Q_i+\mathcal Q_i^*=0$ for $i=1,2$, then for  any $s \ge 0$,
			\begin{equation*} 
				\sup_{n \ge 1} \left| \langle f, \mathcal{Q}_{i,n} f \rangle_{H^s} \right| =0, \qquad f \in H_d^s, \quad i = 1,2,
			\end{equation*}
			and
			\begin{equation*} 
				\sup_{n \ge 1} \left| \langle \mathcal{Q}_{i,n}^2 f, f \rangle_{H^s} + \langle \mathcal{Q}_{i,n} f, \mathcal{Q}_{i,n} f \rangle_{H^s} \right| =0, \qquad f \in H_d^s, \quad i = 1,2.
			\end{equation*}
		\end{enumerate}","status":"unverified"}

