{"assumptions":[],"created_at":"2026-10-27T08:18:19.220921+00:00","domain":"probability theory","id":"claim_339a9ea6a53b11aa1c91328821d477b1cf004e83c09cbf6d3e14db3a92e9517a","kind":"definition","schema_version":1,"statement":"[Definition 2 of arXiv:2608.29086, '2608.29086'] [$M_1 \subset M_2$]
Given two triangular meshes $S$ and $M$. $S$ is called a \textit{submesh} of $M$ if
\begin{align*} 
Tri(S) &\subset Tri(M), \\
Edge(S)&:=\{ ab \in Edge(M)\ |\ \exists c \in Ver(M) \text{ such that } abc \in Tri(S) \}, \\
Ver(S)&:=\{ a \in Ver(M) \ |\  \exists b \in Ver(M) \text{ such that } ab \in Edge(S) \}.
\end{align*}
$SUBMESH(M)$ denotes the collection of all submeshes of $M$. Given $M_1, M_2 \in SUBMESH(M)$. \underline{We write $M_1 \subset M_2$ if $M_1 \in SUBMESH(M_2)$}.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:48:47.287357+00:00","domain":"probability theory","id":"claim_339dfce56f822ba795468071493c10f9e05ba8b2088613ea21ee1b70e9b99fc7","kind":"concept","schema_version":1,"statement":"[Lemma first order mu of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] Let $q\in [0,1)$, $\mathbf{m}\in (-1,1)^N$, and set $\mu:=\frac{1}{N}\sum_{i=1}^N \delta_{m_i}\in\mathcal{P}((-1,1))$. Let $\zeta\in \mathcal{P}([q,1])$ and let $(X_t^{\mu})_{t\in [q,1]}$ be the Auffinger--Chen process with law-matching condition
		\begin{equation}
			\begin{cases}    \mathrm{d} X_t^\mu=\xi''(t)\,\zeta([0,t])\,\partial_x \Phi_\zeta(t,X^\mu_t)\,\mathrm{d} t+\sqrt{\xi''(t)}\, \mathrm{d} B_t,\\
				\mathrm{Law}\bigl(\partial_x\Phi_\zeta(q,X^\mu_q)\bigr)=\mu.
			\end{cases}
		\end{equation}
		Recall $\mathrm{TAP}(\mu,\zeta)$ from (equation def:TAPmuzeta of the paper). The following assertions hold.
		\begin{enumerate}[label=(\roman*)]
			\item The map $\zeta \mapsto \mathrm{TAP}(\mu,\zeta)$ is strictly convex on $\mathcal{P}([q,1])$.
			\item For every finite signed measure $\eta$ on $[q,1]$ with $\eta([q,1])=0$, the Gâteaux derivative of $\mathrm{TAP}(\mu,\cdot)$ at $\zeta$ in the direction $\eta$ is given by 
			\begin{equation}
				D\mathrm{TAP}(\mu,\cdot)(\zeta)[\eta]=\frac{1}{2}\int_q^1 \xi''(s)\Bigl(\mathbb{E}\bigl[(\partial_x\Phi_\zeta(s,X^\mu_s))^2\bigr]-s \Bigr)\,\eta([0,s])\,\mathrm{d} s.
			\end{equation}
			\item For every $s\in [q,1]$, define 
			\begin{equation}
				H^\mu_\zeta(s):=\frac{1}{2}\int_s^1 \xi''(r)\Bigl(\mathbb{E}\bigl[(\partial_x\Phi_\zeta(r,X^\mu_r))^2\bigr]-r\Bigr)\mathrm{d} r,
			\end{equation}
			and extend it to $[0,1]$ by setting
			\begin{equation}
				    \hat{H}_\zeta^\mu(s):=\begin{cases}
					{H}_\zeta^\mu(q) & \text{if $s\in [0,q)$,}\\
					{H}_\zeta^\mu(s) & \text{if $s\in [q,1]$.}
				\end{cases}
			\end{equation}
			Then $\zeta\in \mathcal{P}([q,1])$ is the unique minimizer of $\mathrm{TAP}(\mu,\cdot)$ if and only if for every $\zeta'\in \mathcal{P}([q,1])$,
			\begin{equation*}
				\int_q^1 \hat{H}^\mu_{\zeta}(s)\, \mathrm{d} \zeta'(s) \geq  \int_q^1 \hat{H}^\mu_{\zeta}(s)\, \mathrm{d} \zeta(s).
			\end{equation*}
			Equivalently, $\zeta\in \mathcal{P}([q,1])$ is the unique minimizer of $\mathrm{TAP}(\mu,\cdot)$ if and only if 
			\begin{equation}
				\mathrm{supp}(\zeta)\subset \underset{[0,1]}{\mathrm{arg\,min}}\, \hat{H}_\zeta^\mu.
			\end{equation}
			\item Let $\zeta\in \mathcal{P}([q,1])$ be the unique minimizer of $\mathrm{TAP}(\mu,\cdot)$. Then, for every $q'\in \mathrm{supp}(\zeta)$,
			\begin{equation}
				\mathbb{E}\bigl[(\partial_x\Phi_\zeta(q',X^\mu_{q'}))^2\bigr]=q'.
			\end{equation}
			(For interior points $q'\in (q,1)$ this is a first-order optimality condition; at the boundary $q'=q$ it follows from the law-matching condition~(equation eq:AC mu of the paper), since $\mathbb{E}[(\partial_x\Phi_\zeta(q,X_q^\mu))^2]=\int m^2\,\mathrm{d}\mu(m)=q$.)
			\item Let $\zeta\in \mathcal{P}([q,1])$ be the unique minimizer of $\mathrm{TAP}(\mu,\cdot)$. Then, for every $q'\in \mathrm{supp}(\zeta)$,
			\begin{equation}
				\xi''(q')\,\mathbb{E}\bigl[(\partial_{xx}\Phi_\zeta(q',X^\mu_{q'}))^2\bigr]\leq 1.
			\end{equation}
			\item Let $\zeta\in\mathcal{P}([q,1])$ be the unique minimizer of $\mathrm{TAP}(\mu,\cdot)$. Then
			\begin{equation}
				q\in \mathrm{supp}(\zeta).
			\end{equation}
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:58:53.184493+00:00","domain":"probability theory","id":"claim_33a13cb3e037c57795025d1d900b07cd72a3035f2b98b39c0b485ec509fcdbfc","kind":"concept","schema_version":1,"statement":"[Theorem 1 of arXiv:2606.30349, 'Attenuated Poisson Dirichlet approximations for divisibility configurations'] Let $\pi_n$ be a uniformly random permutation of $\{1,\dots,n\}$ and let
\begin{align*}
