{"assumptions":[],"created_at":"2026-10-27T11:57:07.197409+00:00","domain":"probability theory","id":"claim_33e29f0135f4b33540498abdc3ce2ae6a443dc269f2e7292b5ca559aff0aeb83","kind":"concept","schema_version":1,"statement":"[Proposition prop:DKS-propositions of arXiv:2509.04333, 'The limiting law of the Discrete Gaussian level lines'] The following statements hold for any finite $n$ and sufficiently large $\beta$. Let $A=(A_1,A_2), B=(B_1,B_2)$ be any two points, and assume that $A$ is to the left of $B$. Let $\theta_{A, B}$, $M_{A, B}$, $\ell_{A, B}$ denote the angle, horizontal length, and length of the line segment $\overline{AB}$ respectively, and assume that $|\theta_{A, B}|$ is bounded away from $\pi/2$. Let $\ensuremath{\mathcal S} = \ensuremath{\mathcal S}(A, B)$ denote the infinite vertical strip with $A, B$ on its boundary, and let $W \supset \ensuremath{\mathcal S}$.
		\begin{enumerate}[(i)]
			\item [DKS92] Let $\overline{h}_t(\gamma)$ be the maximum height of $\gamma$ above $\overline{AB}$ at the line $x = A_1 + t$. There exist constants $C, c> 0$ such that for any $A, B$ as above,
			\begin{equation*}
				{\widehat Z}^n_{W, \mathbb Z^2}(A, B \mid \overline{h}_t(\gamma) \geq j) \leq C\sqrt{M_{A, B}}e^{-c(j \wedge j^2/t)}{\widehat Z}^n_{W, \mathbb Z^2}(A, B)\,.
			\end{equation*}
			Let $\ell_t(\gamma)$ be the number of bonds in $\gamma$ to the left of $x = A_1 + t$. For some constant $K(\theta_{A, B})$, we have
			\begin{equation*}
				{\widehat Z}^n_{W, \mathbb Z^2}(A, B \mid \ell_t(\gamma) \geq j + K(\theta_{A, B})t) \leq C\sqrt{M_{A, B}}e^{-c(j \wedge j^2/t)}{\widehat Z}^n_{W, \mathbb Z^2}(A, B)\,.
			\end{equation*}

			\item [DKS92] There exists $C > 0$ such that for any $A, B$ as above,
			\begin{align*}
				&\left|\log {\widehat Z}^n_{\mathbb Z^2, \mathbb Z^2}(A, B) + \tau_{\beta, n}\ell_{A, B} + \tfrac12\log M_{A, B}\right| \leq C\,, \mbox{ and }\\
				&\left|\log {\widehat Z}^n_{\ensuremath{\mathcal S}, \mathbb Z^2}(A, B) + \tau_{\beta, n}\ell_{A, B} + \tfrac12\log M_{A, B}\right| \leq C\,.
			\end{align*} 

		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:33:46.768105+00:00","domain":"probability theory","id":"claim_33e2ee311d06e9d0a6fa43acab7c6af65e8e50551b6c56e41da11e379f1e67c5","kind":"definition","schema_version":1,"statement":"[Definition 18 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Let $k \in \mathbb{N}$ and $\mathfrak{W}_k$ denote the set of signatures of length $k$, i.e.
\begin{equation}
\mathfrak{W}_k = \{ \vec{x} = (x_1, \dots, x_k) \in \mathbb{Z}^k: x_1 \geq  x_2 \geq  \cdots \geq  x_k \}.
\end{equation}
Let $\vec{x}, \vec{y} \in \mathfrak{W}_k$, $T_0, T_1 \in \mathbb{Z}$ with $T_0 < T_1$, and $f: \llbracket T_0, T_1 \rrbracket \rightarrow (-\infty, \infty]$ and $g: \llbracket T_0, T_1 \rrbracket \rightarrow [-\infty, \infty)$ be two functions. With the above data we define the {\em $(f,g)$-interlacing geometric line ensemble on the interval $\llbracket T_0, T_1 \rrbracket$ with entrance data $\vec{x}$ and exit data $\vec{y}$} to be the $\Sigma$-indexed geometric line ensemble $\mathfrak{Q}$ with $\Sigma = \llbracket 1, k\rrbracket$ on $\llbracket T_0, T_1 \rrbracket$ and with the law of $\mathfrak{Q}$ equal to $\mathbb{P}^{T_0,T_1, \vec{x},\vec{y}}_{\operatorname{Geom}}$ (the law of $k$ independent uniform increasing paths $\{B_i: \llbracket T_0, T_1 \rrbracket \rightarrow \mathbb{Z} \}_{i = 1}^k$ from $B_i(T_0) = x_i$ to $B_i(T_1) = y_i$), conditioned on 
\begin{equation}
\begin{split}
\ice  = &\left\{ B_0 \succeq B_1 \succeq B_2 \succeq \cdots \succeq B_{k+1} \right\},
\end{split}
\end{equation}
with the convention that $B_0(x) = f(x)$ and $B_{k+1}(x) = g(x)$.

The above definition is well-posed if there exist $B_i \in \Omega(T_0,T_1,x_i,y_i)$ for $i \in \llbracket 1, k \rrbracket$ that satisfy the conditions in $\ice$. We denote by $\Omega_{\ice}(T_0, T_1, \vec{x}, \vec{y}, f,g)$ the set of collections of $k$ increasing paths that satisfy the conditions in $\ice$ and then the distribution of $\mathfrak{Q}$ is simply the uniform measure on $\Omega_{\ice}(T_0, T_1, \vec{x}, \vec{y}, f,g)$. We denote the probability distribution of $\mathfrak{Q}$ as $\mathbb{P}_{\ice, \operatorname{Geom}}^{T_0,T_1, \vec{x}, \vec{y}, f, g}$ and write $\mathbb{E}_{\ice, \operatorname{Geom}}^{T_0, T_1, \vec{x}, \vec{y}, f, g}$ for the expectation with respect to this measure. If $f=+\infty$ and $g=-\infty$, we drop them from the notation and simply write $\Omega_{\ice}(T_0,T_1,\vec{x},\vec{y})$, $\mathbb{P}^{T_0, T_1, \vec{x},\vec{y}}_{\ice, \operatorname{Geom}}$, and $\mathbb{E}^{T_0, T_1, \vec{x},\vec{y}}_{\ice, \operatorname{Geom}}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T16:30:50.732530+00:00","domain":"probability theory","id":"claim_33e440b572a6c7f9141d1507193088ff9f248514a77d69eff65c55ced73da7a1","kind":"concept","schema_version":1,"statement":"[Theorem thm: quadratic interaction random of arXiv:2503.24372, 'A criterion on the free energy for log-Sobolev inequalities in mean-field particle systems'] Let $V(x)=\frac{x^4}{4}-\lambda \frac{x^2}{2}$ ($\lambda\in\R$) or more generally suppose that $V$ satisfies Assumption~(ass_doublewell of the paper). 
