{"assumptions":[],"created_at":"2026-10-27T14:49:05.487970+00:00","domain":"probability theory","id":"claim_3585f78f675a51fb316775abc75d0586b727aed90982fdd5f9335a2199bdea27","kind":"definition","schema_version":1,"statement":"[Deff def:strong of arXiv:2601.19145, 'Stochastic Persistence in Infinite Dimensions'] Fix $r \in [2,\infty), \theta \in \mathbb{R}$, a stopping time $\tau$, and assume $x \in L^p(\Omega;C([0,T];B))$. 
   We say a process $x_t$ is a strong solution in $\mathcal{B}_{\theta,r}$ to (equation eq:gefx of the paper) up to time $\tau$
    if for all $T > 0$:
    \begin{enumerate}[label=(\roman*)]
        \item $\mathbb{E}[\int_0^{T\wedge \tau} \|x_t\|_{1+\theta, r} dt] < \infty$
        \item $F: B \to \mathcal{B}_{\theta, r}$ and $\mathbb{E}[\int_0^{T\wedge \tau} \|F(x_t)\|_{\theta,r} dt] < \infty$
        \item $G: B \to \gamma(\mathcal{U},\mathcal{B}_{\theta, r})$ and $\mathbb{E}[\int_0^{T\wedge\tau} \|G(x_t)\|_{\theta,r}^2dt] < \infty$
    \end{enumerate}
    (see (fractional-domains-deff of the paper) for the definition of the norms) and furthermore
    \begin{equation}
    x_{t \wedge \tau} = x_0 + \int_0^{t \wedge \tau} Ax_s + F(x_s)ds + \int_0^{t \wedge \tau} G(x_s)dW_s \,.    
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:01:54.388843+00:00","domain":"probability theory","id":"claim_358761eab6f7d09c91284608dda4ee11da03b99dee6e8fecc1f40770011ceaf6","kind":"concept","schema_version":1,"statement":"[Theorem directions_poles of arXiv:2411.02156, 'Martin boundary of a degenerate Reflected Brownian Motion in a wedge'] Suppose $\alpha^* > 0$ (i.e., $\phi_2$ has a pole). Then:
\begin{itemize}
\item If $r(\alpha - \alpha^{*})^2\to 0$, then:
\begin{equation}
g^{z_0}(r\cos(\alpha), r\sin(\alpha))
\underset{r\to\infty \atop \alpha\to \alpha^*}{\sim} 
\frac{1}{2}h_{\alpha^*}(z_0)e^{-r(\cos(\alpha)x^* + \sin(\alpha)y^*)}.
  \end{equation}  
\nb{where $h_{\alpha^*}(z_0)$ is given by (equation harm2 of the paper).}
\item If $r(\alpha - \alpha^{*})^2\to K>0$ for some constant $K$, then for $\alpha < \alpha^*$ (resp. $\alpha > \alpha^*$),
\begin{equation}
g^{z_0}(r\cos(\alpha), r\sin(\alpha))
\underset{r\to\infty \atop \alpha\to \alpha^*}{\sim} 
c_Kh_{\alpha^*}(z_0)e^{-r(\cos(\alpha)x^* + \sin(\alpha)y^*)}
  \end{equation}  
  $$\left(resp.\quad g^{z_0}(r\cos(\alpha), r\sin(\alpha))\underset{r\to\infty \atop \alpha\to \alpha^*}{\sim} 
\tilde c_Kh_{\alpha^*}(z_0)e^{-r(\cos(\alpha)x^* + \sin(\alpha)y^*)}\right).$$
where constants $c_K > 0$, $\tilde c_K > 0$ are independant of initial condition $z_0$.
\item If $r(\alpha-\alpha^{*})^2\to \infty$, then:
\begin{itemize}
\item If $\alpha<\alpha^{*}$, then \begin{equation}
g^{z_0}(r\cos(\alpha), r\sin(\alpha))
\underset{r\to\infty \atop \alpha\to \alpha^*}{\sim} 
h_{\alpha^*}(z_0)e^{-r(\cos(\alpha)x^* + \sin(\alpha)y^*)}.
  \end{equation}  
\item If $\alpha>\alpha^{*}$, then:
\begin{equation}
g^{z_0}(r\cos(\alpha), r\sin(\alpha))
\underset{r\to\infty \atop \alpha\to \alpha^*}{\sim} 
h_{\alpha^*}(z_0)e^{-r(\cos(\alpha)x(\alpha) + \sin(\alpha)y(\alpha)} \frac{1}{\sqrt{r}}\frac{C}{\alpha-\alpha^{*}}
  \end{equation} where $C$ is a positive constant independent of initial condition $z_0$.
\end{itemize}
\end{itemize}
Furthermore, $h_{\alpha^*}(z_0) > 0$.

Constants $c_K, \tilde c_K$ and $C$, are made explicit in~[franceschi2023asymptotics]. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:43:43.468484+00:00","domain":"probability theory","id":"claim_35892819dbc351f3f96d78baa2688bad1d32144ebf0862a888bdcb50a13d041b","kind":"definition","schema_version":1,"statement":"[Definition def:CS(Dir) of arXiv:2509.04155, 'An Approach to Sub-Gaussian Heat Kernel Estimates via Analysis on Metric Spaces'] For a given $\delta > 0$, we say that $(\mathcal{E},\mathcal{F})$ satisfies the \emph{cutoff Sobolev inequality} (eq:CS(Dir) of the paper) if there is a constant $C \geq 1$ for which the following holds.
    For every $x \in X$ and $R \in (0,\diam(X))$ there is a cutoff function $\xi \in \mathcal{F}_p$ for $B(x,R) \subseteq B(x,2R)$ such that
    \begin{equation}
    \tag{$\textup{CS}_{\delta}(\Psi)$}
    \int_{B(y,r)} f_{qc}^2 \, d\Gamma\Span{\xi} \leq C \left(\frac{r}{R}\right)^\delta \left( \int_{B(y,2r)} \, d\Gamma\Span{f} + \frac{1}{\Psi(r)} \int_{B(y,2r)} f^2 \, d\mu \right). \end{equation}
    for all $y \in X$, $0 < r \leq 3R$ and $f \in \mathcal{F}$.
    Here $f_{qc}$ is any quasicontinuous $\mu$-representative of $f$; see [FOT] for a detailed exposition on quasicontinuity.
    If $\Psi(r) = r^\beta$ for some $\beta \geq 2$, we write \hyperref[eq:CS(Dir)]{$\textup{CS}_\delta(\beta)$} instead.","status":"unverified"}

{"assumptions":["Rare events have positive probability","Polish state space for weak-convergence criterion","No assertion that the toy process is percolation"],"created_at":"2026-10-10T08:06:45.814101+00:00","domain":"probability theory","id":"claim_358a09f18cc575b995f83aeac9ef59b9d258fa8f4b9da339f3bfd50dc8c5cd1c","kind":"lemma","schema_version":1,"statement":"AUTHOR-CHECKED; independent w346 audit PENDING. Unconditional convergence, even almost sure convergence, and an exact
