		&\ \ +\sum_{n=2}^{\infty}\sum_{j=0}^{n-2}\binom{n-1}{j}\Big(\frac{b+c}{c}\Big)_{j}\Big(\frac{r}{c}\Big)_{n-j}\Big(\Big(\frac{b+r+c}{c}\Big)_n\Big)^{-1}\frac{(\lambda\theta^\alpha)^{\frac{b}{c}+j+1}}{\theta}(\mu(t-\theta)^\alpha)^{\frac{r}{c}+n-j-1}\nonumber\\
		&\hspace{1.7cm}\cdot  E_{\alpha,\alpha\big(\frac{b}{c}+j+1\big)}^{\frac{b}{c}+j+1}(-\lambda\theta^\alpha) E_{\alpha,\alpha\big(\frac{r}{c}+n-j-1\big)+1}^{\frac{r}{c}+n-j}(-\mu(t-\theta)^\alpha)\bigg),\, -v_2 t< x <v_1t
