{"assumptions":[],"created_at":"2026-10-27T20:50:48.848409+00:00","domain":"probability theory","id":"claim_359b0b7e8ac2c58f373623ebe789b2d9f9a0ff06375f9746746021c37ae7e7e7","kind":"concept","schema_version":1,"statement":"[Tm main_tm of arXiv:2607.08869, 'Inequalities for convex functions of random points inside and on the boundary of convex bo'] Let $K$ be a convex body in $\mathbb{R}^d$ satisfying one of the following:
    \begin{itemize}
        \item $d = 2$ and $\mathbb E I = \mathbb E B$;
        \item $K$ is a circumscribed polytope whose inscribed sphere center $O$ coincides with $\mathbb EI$ and $\mathbb EB$.
    \end{itemize}
    Let $\varphi: (\mathbb{R}^d)^k \to \mathbb{R}$ be a function convex in each argument.
    Then
    \begin{align}
        \mathbb E \varphi(I_1, \ldots, I_k) \leqslant  \mathbb E \varphi(B_1, \ldots, B_k),
    \end{align}
    where $I_1,\dots,I_k$ and $B_1,\dots,B_k$ are independent samples uniformly distributed inside $K$ and on $\partial K$, respectively. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:00:46.828705+00:00","domain":"probability theory","id":"claim_359d29cd6a0220845150d0ddcfd938889ce15baed6adeebc2231a63aa63e6755","kind":"lemma","schema_version":1,"statement":"[Lemma 17 of arXiv:2608.13235, 'Mixing Properties of Random Laguerre Tessellations'] Let $l \in \n$, $K_1(l) \geq 2k(l)+3$ and define $C_l\coloneqq 2l^{\frac{1}{d+\delta}}K_1(l)$, $\beta_l\coloneqq \sqrt{C_l^2-1}-1$ and $K_3(l)\coloneqq \sqrt{8}C_l$. Then for any $r\geq 1$,
    \begin{align*}  
    \begin{split}
    \varphi \in E^3_{r,K_3(l)} &\cap \hatMsetl \cap (E^1_{r,K_1(l)})^c \\
    &\implies \varphi(\beta_lrB^d\times(-\infty,r^2])=0 \text{ or } \exists j \in \{1,\dots,\theta_l\} \text{ such that } \varphi(\beta_lrB_j\times(-\infty,r^2])=0 ,
    \end{split}
\end{align*} 
    where $\theta_l$ is the minimal number of balls with unit radius needed to cover the ball $(K_3(l)+1)B^d$ and $B_1,\dots,B_{\theta_l}$ is the minimal cover.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:52:23.564960+00:00","domain":"probability theory","id":"claim_35a03c2c1c8a128992d06b0209690a9ed3e4d6666c30fb07956453c7c11d3dd4","kind":"concept","schema_version":1,"statement":"[Lemma L:K of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] When $\beta\in \{1,2\}$ and $\gamma = 0$, the constant
  $K(\alpha,\beta,\gamma;H,\ell;\nu,d)$, together with $\rho_0 = \beta + \gamma -
    1 + H - \ell\beta/(2\alpha)$, in~(equation E:SecMom-K of the paper) can be explicitly computed
  as follows:
  \begin{enumerate}[\rm (i)]
    \item For $\beta = 1$, we have that $\rho_0 = H-\ell/(2\alpha)$. Moreover, if $H\in(1/2,1)$,
          \begin{subequations}
            \begin{align}
              K(\alpha,1,0;H,\ell;\nu,d)
               & = \frac{2^{3+\ell/\alpha} H \pi^{(2+d)/2} \Gamma\left(\ell/\alpha\right) \lMr{2}{F}{1}\left(1,\ell/\alpha;2H;-1\right) }{\nu^{\ell/\alpha} \Gamma\left(d/2\right) (2\alpha H-\ell)};
            \end{align}
            and if $H=1/2$
            \begin{align}
              K(\alpha,1,0;1/2,\ell;\nu,d)
               & = \frac{2^{2}\pi^{(2+d)/2} \Gamma(\ell/\alpha) }{\nu^{\ell/\alpha}\Gamma (d / 2) (\alpha-\ell)}.
            \end{align}
          \end{subequations}
    \item
          For $\beta = 2$, we have the following cases:

          \begin{enumerate}[\rm a)]

            \item if $H = 1/2$ and $\ell\in(0,\alpha)\setminus\{\alpha/2\}$, then $\rho_0
                    = 1+ H -\ell /\alpha$ and
                  \begin{align}
                    K(\alpha,2,0;1/2,\ell;\nu,d)
                    = \frac{ 2^{3-\ell/\alpha} \nu^{1-\ell/\alpha} \pi^{(d+2)/2} \Gamma\left(2(\ell/\alpha-1)\right) \cos\left(\pi\ell/\alpha\right) }{\Gamma(d/2) \left(3\alpha-2\ell\right) };
                  \end{align}

            \item if $H = 1/2$ and $\ell = \alpha/2$, then $\rho_0 = 1$ and
                  \begin{align}
                    K(\alpha,2,0;1/2,\alpha/2;\nu,d)
                    = \frac{ 2^{1/2} \nu^{1/2} \pi^{(d+4)/2} }{\Gamma(d/2) \alpha };
                  \end{align}

            \item if $H\in (1/2,1)$ and
                  $\ell\in(0,(1/2+H)\alpha)\setminus\{\alpha/2,\alpha\}$, then $\rho_0 = 1+ H
                    - \ell/\alpha$ and
                  \begin{align}
                    \begin{aligned}
                       & K(\alpha,2,0;H,\ell;\nu,d)
                      =  \frac{ 2^{\ell/\alpha} \nu^{1-\ell/\alpha} H \pi^{(d+2)/2}  }{ \Gamma(d/2) } \times \Gamma(2(\ell/\alpha-1))\cos\left(\pi\ell/\alpha\right)                                                                                                   \\
                       & \qquad \times \Bigg[ \frac{ \alpha[1-2H] }{ (\alpha[1/2+H]-\ell) (\alpha[1+H]-\ell) }                                                               + 2 \frac{ \lMr{2}{F}{1}\left(1,2(\ell/\alpha-1);2H;-1\right) }{\alpha[1+H]-\ell} \Bigg];
                    \end{aligned}
                  \end{align}

            \item if $H\in (1/2,1)$ and $\ell=\alpha/2$, then $\rho_0 = 1/2 + H$ and
                  \begin{align}
                    K(\alpha,2,0;H,\alpha/2;\nu,d)
                    = \frac{ 2^{3/2} \nu^{1/2} \pi^{(d+4)/2}}{ \alpha  (1+2H) \Gamma\left(d/2\right) };
                  \end{align}

            \item if $H\in (1/2,1)$ and $\ell=\alpha$, then $\rho_0 = H$ and
                  \begin{align}
                    K(\alpha,2,0;H,\alpha;\nu,d)
                    = \frac{ 2^2 \pi^{(d+2)/2} }{ \alpha \Gamma (d/2) } \left(\frac{\lMr{2}{F}{1}(1,1;1+2H;-1)}{2H}+\frac{1}{2H-1}\right)
                  \end{align}
                  which does not depend on $\nu$. See Fig.(F:K-5 of the paper) for some plots related
                  to this constant.

          \end{enumerate}
  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

