&\leq
e^{-\lambda_{\mathrm{damp}}t}
\mathscr V_{\mathrm{damp}}(0),
\qquad
\lambda_{\mathrm{damp}}
:=
\min\left\{
\frac{2\mu\delta}{A},
\min_{i\in\mathcal I}\kappa_i
\right\}.

\end{align}
In particular, \(\mathscr E(t)\to0\) and \(q_i(t)\to0\) exponentially for
all selected modes.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:48:47.301393+00:00","domain":"probability theory","id":"claim_35cafd21a4dab1eb3e5f3a020db6f9191d2b761d1502ae71c2ef962439d588f2","kind":"definition","schema_version":1,"statement":"[Definition of arXiv:2604.22130, 'Reflected Stochastic Differential Equations Driven by $G$-Brownian Motion with Nonlinear C'] A scalar valued random variable $\xi\in L_{ip}(\Omega_T)$ is called $G$-normal distributed, i.e., $\xi\sim \mathcal{N}(0,[\underline{\sigma}^2,\bar{\sigma}^2])$, if for each $\varphi\in C_{l,Lip}(\mathbb{R})$, $u(t,x):=\hat{\mathbb{E}}[\varphi(x+\sqrt{t}\xi)]$ is a viscosity solution to the following PDE :
\begin{displaymath}
\begin{cases}
\partial_t u-G(\partial_x^2 u)=0,  &(t,x)\in\mathbb{R}^+\times\mathbb{R};\\
u(0,x)=\varphi(x), &x\in\mathbb{R}.
\end{cases}
\end{displaymath}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:05:52.386518+00:00","domain":"probability theory","id":"claim_35d07ec3bfc42cadcb995214e59f7b3b5c58767a47ecefac223374999e06bb58","kind":"lemma","schema_version":1,"statement":"[Lemma lemma for limit identity of arXiv:2504.06238, 'Infinite Boundary Friction Limit for Weak Solutions of the Stochastic Navier-Stokes Equati'] $\tilde{u}$ satisfies the identity
 \begin{align} \nonumber
     \inner{\tilde{u}_t}{\phi} = \inner{\tilde{u}_0}{\phi} - \int_0^{t}\inner{\mathcal{L}_{\tilde{u}_s}\tilde{u}_s}{\phi}ds &- \nu\int_0^{t} \inner{\tilde{u}_s}{\phi}_1 ds\\ &+ \frac{1}{2}\int_0^{t}\sum_{i=1}^\infty \inner{B_i\tilde{u}_s}{B_i^*\phi} ds - \int_0^{t} \inner{B\tilde{u}_s}{\phi} d\mathcal{W}_s \nonumber
