{"assumptions":[],"created_at":"2026-10-27T23:06:42.727777+00:00","domain":"probability theory","id":"claim_3642b7626ce78f24d7dc4abdc4f6fb6d0258c2ab9da166fa391dabd3a1b45497","kind":"definition","schema_version":1,"statement":"[Definition def-weak-solution-skeleton-equation of arXiv:2411.04500, '\LARGE Probabilistic Approaches to The Energy Equality in Forced Surface Quasi-Geostrophic'] Let $\theta_0\in H^{\alpha-2\beta}(\mathbb{T}^2)$ and $g\in L^2([0,T];H)$. We say that $\theta$ is a weak solution of (equation PDE-SQG of the paper) with initial data $\theta_0$ if 

	(i)
	$
	\theta\in  L^\infty([0,T];H^{\alpha-2\beta}(\mathbb{T}^2)) \cap  L^2([0,T];H^{2\alpha-2\beta}(\mathbb{T}^2))\cap C([0,T];H_w^{\alpha-2\beta}(\mathbb{T}^2)).
	$

	(ii) For every $\varphi\in  C^\infty([0,T];H^\infty(\mathbb{T}^2))$, for all $ t\in[0,T]$,
	\begin{equation}
		\begin{aligned}
			&\langle \theta(t),\varphi(t)\rangle=\langle \theta_0,\varphi(0)\rangle+\int^t_0\langle \theta,\partial_s\varphi\rangle \,\mathrm{d}s-\int^t_0\langle \theta,\Lambda^{2\alpha}\varphi\rangle  \,\mathrm{d}s\\&-\frac{1}{2}\int^t_0\left\langle R_2 \theta,\left[\Lambda, \partial_1 \varphi\right]\Lambda^{-1} \theta\right\rangle \,\mathrm{d} s+\frac{1}{2}\int_0^t\left\langle R_1 \theta  ,\left[\Lambda, \partial_2 \varphi\right]\Lambda^{-1} \theta\right\rangle \,\mathrm{d}s+\int^t_0\langle\Lambda^{2\beta}\varphi,g\rangle \,\mathrm{d}s.
		\end{aligned}
	\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:19:56.669471+00:00","domain":"probability theory","id":"claim_3646926203fd0c01b29b8abfe4e528cebc89d538b8278e7fcd77c68afe1c04cf","kind":"definition","schema_version":1,"statement":"[Definition 11 of arXiv:2608.30875, 'A Decomposition Theorem for Topological Semi-small Maps'] Let $X^{n}$ be an $n$-dimensional pseudomanifold with a filtration
   	$X = X_{n} \supseteq X_{n-2} \supseteq \cdots \supseteq X_{0} \supseteq \emptyset$, and set
   	$U_{k} = X - X_{n-k}$ for $k \geq 2$, with inclusion maps $i_{k}:U_{k} \hookrightarrow U_{k+1}$. Let $\mathcal{L}$ be a local system on $X-X_{n-2}$. Deligne's sheaf complex $IC^{\overline{p}}_{X}(\mathcal{L})$ with respect to the perversity $\overline{p}$ is defined as 
   	\begin{align*}
   		IC^{\overline{p}}_{X}(\mathcal{L}) = \tau_{\leq \overline{p}(n)-n} Ri_{n \ast}  \cdots \tau_{\leq \overline{p}(3)-n} Ri_{3\ast}   \tau_{\leq \overline{p}(2)-n} Ri_{2 \ast} \mathcal{L}[n].
   	\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T16:50:26.944827+00:00","domain":"probability theory","id":"claim_364b9aa094b8f7517351374f012472c16f78fece8d8e15b0d8db022f7c1d4541","kind":"concept","schema_version":1,"statement":"[Proposition p:BP of arXiv:2505.09604, 'Exceptional force, uncountably many solutions in the KPZ fixed point'] The following holds on the event $\Omega_1$ for all $\xi \in \mathbb{R}$. Assume $y \in \mathcal{B}_{t,\xi}\setminus \mathfrak S_{t,\xi}$ for some $t \in \mathbb{R}$. Then, there exists $s_0<t$ and $x_0 \in \mathbb{R}$ such that 
         \begin{equation} 
         y=\tau^{\xi,-}_{(x_0,s_0)}(t)=\tau^{\xi,+}_{(x_0,s_0)}(t).
         \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:36:16.062402+00:00","domain":"probability theory","id":"claim_364cb8eac8d897b65a83730889d3a884e41875dc22048d17b80623673ad14862","kind":"lemma","schema_version":1,"statement":"[Lemma lemma_Wbar2 of arXiv:2606.28067, 'Ergodic approximation for the invariant distribution: An abstract framework for law-depend'] Let $p\ge 1$, $X_0 \in L^p$ and $\{X_k\}_{k\in {\mathbb N}}$ be the chain defined by~(equation New1 of the paper). 
		Suppose that (equation na1a of the paper)  
		holds and $\Gamma_{p}(X)=\left(1+\max_{k\in {\mathbb{N}}}\mathbb{E}
		[\left\vert X_{k}\right\vert ^{p}]\right)^{1/p}<\infty $.\newline
		\textbf{A. }  Then,
		there exists a constant $C\in {\mathbb{R}}_{+}$ depending on the sequence $
		(\gamma _{n})_n$, $c_{\ast }$ and $p$ such that for every $i<j$ and every $
		\varphi \in C_{b}^{1}({\mathbb{R}}^{d})$ 
		\begin{equation*}
			\mathbb{E}[\left\vert \mathbb{E}[\varphi (X_{j})-\mathbb{E}[\varphi
			(X_{j})]\mid X_{i}]\right\vert] \leq C\left\Vert \nabla \varphi \right\Vert
			_{\infty }\Gamma_{p}(X) \left( e^{-\frac{b}{p}
				(t_{j}-t_{i})}+ \gamma _{j}^{\varepsilon /p}\right)  
		\end{equation*}
		\textbf{B. }Moreover, suppose that (equation New0 of the paper)
		is satisfied with $\varepsilon$ replaced by $\varepsilon /p$ (in particular,
		this yields $\sum_{i=1}^{\infty }\gamma _{i}^{1+\varepsilon /p}<\infty $). Then, 
		\begin{equation}
			\mathbb{E}\left[ \left( \int_{{\mathbb{R}}^{d}}\varphi (x)(\rho _{k}(X)(dx)-
			\mathcal{L}_{k}(X)(dx))\right) ^{2}\right] \leq C\Gamma_{p}(X)\left\Vert
			\varphi \right\Vert _{\infty }\left\Vert \nabla \varphi \right\Vert _{\infty
			}t_{k}^{-1},  
		\end{equation}
		with a constant $C$ that only depends on $b$, $\varepsilon $, $c_{\ast }$,
		the sequence $(\gamma _{n})$ and $p$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:39:12.215743+00:00","domain":"probability theory","id":"claim_364ded5804ff81169cec353cfba432167c8527320f4f795d178a6b1a37bbf77a","kind":"concept","schema_version":1,"statement":"[Theorem th: Naz_Sod of arXiv:2412.07690, 'A law of large numbers concerning the distribution of critical points of random Fourier se'] Fix $\ell\in {{\mathbb N}}_0$ and $\alpha\in (0,1)$. Suppose that $\EuScript{V}$ is an open subset of ${\mathbb R}^m$ and $X:\Omega\times \EuScript{V}\to{\mathbb R}$ is a  centered Gaussian function with covariance kernel  $\EuScript{K}_X$. Assume that $\EuScript{K}\in C^{2\ell+2}\big(\, \EuScript{V}\times \EuScript{V})$.  Then $X$ admits a $C^{\ell,\alpha}$-modification. Moreover, for every box $B\subset \EuScript{V}$ and every $p\geq 1$  there exists a constant $C_p=C(B,\EuScript{V},\ell,\alpha)$ such that
   \begin{equation}
   {\mathbb E}\big[\, \Vert X\Vert^p_{C^{\ell,\alpha}(B)}\,\big] \leq C\big\Vert\, \EuScript{K}_X\,\big\Vert^{p+1}_{C^{2\ell+2}(B\times B)},
  \end{equation}
   where $C^{k,\alpha}$  denotes the spaces of functions that are  $k$ times differentiable and the $k$-th differential is H\"{o}lder continuous with exponent $\alpha$.\nobreak\hfill\penalty250 \hbox{}\nobreak\hfill$\rlap{$\sqcap$}\sqcup$\vskip\aline (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:50:30.556208+00:00","domain":"probability theory","id":"claim_364e44285178983159b0c45fdc1c13c4f147dc8617d210973c95308abc49c5ac","kind":"concept","schema_version":1,"statement":"[Proposition 18 of arXiv:2605.30055, 'The Wasserstein cost of importance sampling'] Let $Q \subset \mathbb{R}^d$ be an open connected set with smooth boundary. For any $p \in [1, \infty[$, there is a constant $C$ depending only on $p$ such that for any differentiable function $h$ on $Q$ such that $\nabla h \in L^p(Q)$, 
\begin{equation}
    \int_Q |h-m|^p \leqslant C \mathrm{diam}(Q)^p \int_Q |\nabla h|^p
\end{equation} 
where $m = \frac{1}{|Q|} \int_Q h$ is the mean value of $h$ on $Q$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:38:25.224056+00:00","domain":"probability theory","id":"claim_364e8ac9273abffbcc9f3474552c64452895bea4740dc8e1fc9792bfd967505a","kind":"concept","schema_version":1,"statement":"[Theorem thm:mainv1 of arXiv:2609.00324, 'Quantitative Stability for Fractional Yamabe minimizers'] Let $\gamma \in (0,1)$ and $(M^n , [\hat{h}])$ be the conformal infinity of an asymptotically hyperbolic manifold $(X^{n+1},g^+ )$ such that $\Lambda_{\gamma} (M,[\hat{h}]) < \Lambda_{\gamma} (\mathbb{S}^n ,[h_{0}])$. Then, there exist constants $C>0$ and $\theta \geq 0$ such that
    \begin{align*}
        I_{\gamma} [w,\hat{h}]  - \Lambda_{\gamma} (M,[\hat{h}]) \geq C d(w,\mathcal{M})^{2+\theta} \quad \forall w \in H^{\gamma}(M,\mathbb{R}_+),
    \end{align*}
    where
    \begin{align*}
        d(w,\mathcal{M}) := \frac{\inf \{\|w-u\|_{H^{\gamma}(M)} : u \in \mathcal{M} \} }{\|w\|_{H^{\gamma}(M)}},
    \end{align*}
    and $\mathcal{M}$ is the set of minimizers of $I_{\gamma}[-,\hat{h}]$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:54:10.971582+00:00","domain":"probability theory","id":"claim_365043b666a12eb7045272df99725b5b4d8ae5e46d3059ef40c7e0f6ec554481","kind":"concept","schema_version":1,"statement":"[Lem 40 of arXiv:2606.13459, 'Symmetric Cooperative Motion in Higher Dimensions'] [\cite{splitting}, Lemma 3.3] 
	Let $(v_{N})_{N \in \N}$ be a sequence of functions defined on $\R^{d} \times [a,b]$ which satisfies the following conditions:
	\begin{enumerate}
		\item There exists $C> 0$ such that for all $N \in \N$ and $t \in [a,b]$,
		\begin{equation*}
			\norm{v_{N}(\cdot,t)}_{L^{1}(\R^{d})} \leq C \text{ and } \norm{v_{N}(\cdot,t)}_{L^{\infty}(\R^{d})} \leq C.
		\end{equation*}
		\item There exists a spatial modulus of continuity $\nu$ such that for all $N\in \N$ and $t \in [a,b]$,
		\begin{equation*}
			\norm{v_{N}(\cdot + y,t) - v_{N}(\cdot,t)}_{L^{1}(\R^{d})} \leq \nu(|y|).
		\end{equation*}
		\item There exists an approximate temporal modulus of continuity $\om$ such that for all $N \in \N$ and $s, t \in [a,b]$,
		\begin{equation*}
			\norm{v_{N}(\cdot,t) - v_{N}(\cdot,s)}_{L^{1}(\R^{d})} \leq \om(|t-s| + \tfrac{1}{N}).
		\end{equation*}
	\end{enumerate}
	Then $(v_{N})_{N\in \N}$ is compact in the strong topology of $L^{1}_{\loc}(\R^{d}\times[a,b])$. Moreover, if $v$ is an $L^{1}_{\loc}(\R^{d}\times[a,b])$-limit point of $(v_{N})_{N \in \N}$, then $v \in L^{1}(\R^{d}\times[a,b])\cap L^{\infty}(\R^{d}\times[a,b]) \cap C([a,b];L^{1}(\R^{d}))$, and $v$ has a spatial modulus of continuity $\nu$ on $\R^{d}\times[a,b]$ and $v$ has a temporal modulus of continuity $\om$ on $\R^{d}\times[a,b]$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

