{"assumptions":[],"created_at":"2026-10-27T06:39:11.674216+00:00","domain":"probability theory","id":"claim_368adbdff36221afd567ec5759f75cc55fd32b204d820a5525f484b4b324ad91","kind":"concept","schema_version":1,"statement":"[Theorem 13 of arXiv:2608.04853, 'Minimal-Norm Extensions of Stationary Kernels on Subgroups of Locally Compact Abelian Grou'] Let $G$ be a locally compact abelian group and let $H\subseteq G$ be a closed subgroup. Let $k:G\times G \to \R$ be a stationary kernel with spectral density $\hat{k} \in L^1(\hat{G}) \cap L^\infty(\hat{G})$, and assume that the spectral density $\hat{k}_H(\xi_H)$ of the kernel $k_H:H \times H \to \R$ given by $k_H(x,y):=k(x,y)$ for all $x,y \in H$ belongs to $ L^\infty(\hat{H})$. Then the minimal-norm extension operator $M_W: \mathcal{N}(H) \to \mathcal{N}(G)$ is given on the Fourier side by 
    \begin{align*}
        \widehat{M_W g}(\xi_H+\xi^\perp) = \hat{g}(\xi_H) \frac{\hat k(\xi_H+\xi^\perp)}
{\hat k_H(\xi_H)} 
    \end{align*}
    for $g \in \mathcal{N}(H)$, for almost all $\xi_H \in \hat{G}/H^\perp$ and $\xi^\perp \in H^\perp$. On the set where $\hat{k}_H=0$, the quotient is interpreted as zero.  

    Set $A:\hat{G}/H^\perp \to \R$ as
    \begin{align*}
        A(\xi_H):= \frac{
\int_{H^\perp}
|\hat k(\xi_H+\xi^\perp)|^2 \d\xi^\perp
}{
|\hat k_H(\xi_H)|^2
},
\qquad
\xi_H\in \hat G/H^\perp,
    \end{align*}
with the convention $A(\xi_H)=0$ whenever $\hat{k}_H(\xi_H)=0$. If $A \in L^\infty(\hat{G}/H^\perp)$ then the same Fourier formula defines a bounded operator $M:L^2(H) \to L^2(G)$ satisfying $M|_{\mathcal{N}(H)}=M_W$, and 
\begin{align*}
    \Vert M \Vert_{L^2(H) \to L^2(G)}^2 = \esssup_{\xi_H \in \hat{G}/H^\perp} A(\xi_H).
\end{align*}
Moreover, 
\begin{align*}
    \inf_{ \Vert g \Vert_{L^2(H)}=1} \Vert M g \Vert_{L^2(G)}^2 = \essinf_{\xi_H \in \hat{G}/H^\perp} A(\xi_H).
\end{align*}
Finally, for $0 \leq \theta \leq 1$, the operator $M$ restricts to a bounded operator $M_\theta:\mathcal{N}(H)_\theta \to \mathcal{N}(G)_\theta$ and 
\begin{align*}
\Vert M_\theta \Vert_{\mathcal{N}(H)_\theta \to \mathcal{N}(G)_\theta} \leq \esssup_{\xi_H \in \hat{G}/H^\perp} A(\xi_H)^{\theta/2}.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:37:51.457935+00:00","domain":"probability theory","id":"claim_368e8d9d6d3c02c238d03e68af5966d2a6524b8fd632188d17586f14507a1756","kind":"concept","schema_version":1,"statement":"[Cor 33 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] Let $\gamma \geq 1$, $0 \leq s \leq t \leq T$, $\delta \in [0, \; 1]$ and $n \in \mathbb{N}_+$. It holds
\begin{align*}
	&	\mathbb{E}_{\nu_{\rho}} \Bigg[ \Bigg\{ \frac{\Theta(n) K_n}{  \sqrt{n} } \int_s^t \dd r \sum_{x} \sum_{z=1}^{L_n-1}   [  H ( \tfrac{ \lfloor x+z - r v_n \rfloor }{n}  ) - H ( \tfrac{ \lfloor x - r v_n \rfloor }{n}  )  ] a(z)   \bar{\xi}_x^{\alpha}( \eta_r^n ) \big[ \bar{\xi} _{x+z}^{\beta}( \eta_r^n ) - \bar{\xi} _{x+1}^{\beta}( \eta_r^n ) \big] \Bigg\}^{2} \Bigg] \\
	\leq & \widehat{C}(t-s)^{1+\delta} \Bigg( \frac{\big[ \Theta(n) K_n\big]^{\delta+1} }{n^{2}} + \big[  K_n \big]^2 f_{\delta}(n)   \Bigg),
\end{align*} 
where $f_{\delta}:\mathbb{N}_+ \mapsto \mathbb{R}$ is given by
\begin{align} 
\forall n \in \mathbb{N}_+, \quad f_{\delta}(n):= 
\begin{dcases}
 (L_n/n)^{ 1 - \delta } \big[ \log(L_n) \big]^{2 \delta} , \quad & \gamma  =1, \\
  (L_n/n)^{ (2-\gamma)(1 - \delta) }     n^{2 \delta (\gamma-1) }, \quad & 1 < \gamma  <2, \\
 n^{2 \delta} \big[ \log(L_n) \big]^{1 - \delta} \big[ \log(n) \big]^{-1-\delta}, \quad & \gamma  =2, \\
 n^{2 \delta}, \quad & \gamma > 2. 
\end{dcases}
\end{align}
Furthermore, if $H \in C_c^2(\mathbb{R})$, the role of $\widehat{C}$ is fulfilled by some constant $C(H)$ satisfying \eqref{Cinvshift}. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

