		\exp \big( -\tfrac{d}{2t} \| y \|^2 \big) 
		\exp \left( O \left(  \frac{1}{\sqrt{t}} + \frac{\| y \|^3}{t^2} \right) \right).
\end{equation}
Therefore, for any $\sigma \in (0,1)$ and $t$ sufficiently large,
\begin{equation}
	\frac{1}{p^y_t} \leq e^{t^{\sigma}}, \qquad \forall y \in \mathbb{Z}^d: \|y\| \leq t^{\sigma}. 
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

