{"assumptions":[],"created_at":"2026-10-27T14:49:05.434228+00:00","domain":"probability theory","id":"claim_372e4db53af94d55b9c147e55d223656f94854e7e1b1f8ccc798374802d50cfc","kind":"concept","schema_version":1,"statement":"[Lemma lem:grad of arXiv:2601.10568, 'Hydrodynamic Limit with a Weierstrass-type result'] Let $\ndef{\mathbf{J}_\beta}$ be the algebraic current, defined through $\mathcal{L}^{\beta,\ell_N}[\pi_0]=\nabla\tau^{-1}[-\mathbf{J}_{\beta,\ell_N}]$, where $\mathbf{J}_{\beta,\ell_N}$ is given, explicitly, by
\begin{align}
    \mathbf{J}_{\beta,\ell_N}
    =
    \frac{1}{\ell_N+1}
    \sum_{j=1}^{\ell_N}
    \mathbf{J}_{\beta}^j(\eta)
\quad\text{with}\quad
    \mathbf{J}_{\beta}^j(\eta)
    =\beta(\langle \eta\rangle_{j})
    (
    \mathbf{e}_{0,1}(\eta)
    -
    \mathbf{e}_{1,0}(\eta)
    )
    .
\end{align}

For each $\eta\in\Omega_N$, let $\ndef{P_{\ell_N}}(\eta)$ be the number of particles in the box $\llbracket0,\ell_N\rrbracket$. It holds that
\begin{align}
    \mathbf{J}_{\beta,\ell_N}=-\nabla \mathbf{H}_{\beta,\ell_N},
\end{align}
where $\mathbf{H}_{\beta,\ell_N}=\mathbf{h}_{\beta,\ell_N}+\mathbf{g}_{\beta,\ell_N}$ and 
\begin{align}

    \mathbf{h}_{\beta,\ell_N}(\eta)
    &=
    \frac{1}{\ell_N+1}
    \sum_{n=0}^{P_{\ell_N}(\eta)-1}
    \beta(\tfrac{n}{\ell_N})
    ,
    \\

    \mathbf{g}_{\beta,\ell_N}(\eta)
    &=
    \frac{1}{\ell_N+1}
    \sum_{j=1}^{\ell_N}
    \sum_{i=1}^{j}
    \tau^{-i}\mathbf{J}_{\beta,\ell_N}^j(\eta),

\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:53:53.203098+00:00","domain":"probability theory","id":"claim_37301225900e0cbfa4e39f9c998fd19db4ef37b9daf893fbb28837bcfde2f376","kind":"definition","schema_version":1,"statement":"[Definition 9 of arXiv:2606.12670, 'The censored stochastic six-vertex model and parabolic Kazhdan--Lusztig $R$-polynomials'] Let $P_k$ be the propagator of the following dynamics on particle configurations $\eta\colon\mathbb Z\to\{0,1\}$. 
    Exchange the values of $\eta(k)$ and $\eta(k+1)$ with probability $b_1$ if $(\eta(k),\eta(k+1))=(0,1)$ and with probability $b_2$ if $(\eta(k),\eta(k+1))=(1,0)$.
    In other words, if $\nu$ is a measure on particle configurations and $\eta$ is a particle configuration, then
    \[
    P_k\nu(\eta)=\begin{cases}
        b_2\nu(\eta^k)+(1-b_1)\nu(\eta), &\text{ if }(\eta(k),\eta(k+1))=(0,1)\\
        b_1\nu(\eta^k)+(1-b_2)\nu(\eta), &\text{ if }(\eta(k),\eta(k+1))=(1,0)\\
        \nu(\eta), &\text{ if }\eta(k)=\eta(k+1)\,.
    \end{cases}
    \]","status":"unverified"}

