    \end{align}
  \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:17:13.082110+00:00","domain":"probability theory","id":"claim_380c908e0f90f2ce20090457ac3e6e4e916f0d38fea174d125a509d241b03eb1","kind":"theorem","schema_version":1,"statement":"[Theorem TB of arXiv:2510.12480, 'Cyclic and alternating $U$-statistics'] With notations and assumptions 
as in Section~(Sprel of the paper),
the following holds for the bi-alternating $U$-statistic{} $U^{--}_n(f)$ in (equation U-- of the paper).

\begin{romenumerate}
\par
 \refstepcounter{thmenumerate}\textup{(\roman{thmenumerate})\enspace} 
We have
\begin{align}
  \operatorname{\mathbb E}{} [U^{--}_n(f)] = -\floor{\tfrac{n}{2}} \mu
=O(n),
\end{align}
and, as \ensuremath{{n\to\infty}}, we have the weak law of large numbers 
\begin{align}
  \frac{1}{\binom n2} U^{--}_n(f)\overset{\mathrm{p}}{\longrightarrow} 0.
\end{align}

  \par
 \refstepcounter{thmenumerate}\textup{(\roman{thmenumerate})\enspace} 
We have
\begin{align}
  \operatorname{Var}[U^{--}_n(f)] 
=\tfrac{1}{2}n^2\operatorname{Var} [f_{12}(X_1,X_2)] + O(n).
\end{align}
Moreover, there exists a
finite or infinite sequence of real numbers $(\lambda_r)_1^{R}$ 
such that
\begin{align}
n^{-1}\left(U^{--}_n(f)-\operatorname{\mathbb E}{}[U^{--}_n(f)]\right) \overset{\mathrm{d}}{\longrightarrow} 
W:=\sum_{r=1}^R\tfrac12\lambda_r(\zeta_r^2-1)
\end{align}
where $(\zeta_r)_1^R$ are  independent standard normal variables.
The coefficients
$(\lambda_r)_1^R$ in (equation tb2 of the paper) are the nonzero eigenvalues (with multiplicities) 
of the self-adjoint 
integral operator $T_{{\widehat{f_{12}}}}$ 
on $L^2({\mathcal X}\times\ensuremath{[0,1]},\nu\times\ell)$.
We have
\begin{align}
\operatorname{Var} W = \tfrac12  \sum_{r=1}^R\lambda_r^2&
=\tfrac12\operatorname{Var}[f_{12}(X_1,X_2)].
\end{align}

\par
 \refstepcounter{thmenumerate}\textup{(\roman{thmenumerate})\enspace} 
In the special case of (TB2 of the paper) where
furthermore
$f$ is symmetric, 
the coefficients
$(\lambda_r)_1^R$ in (equation tb2 of the paper) are the nonzero eigenvalues (with multiplicities) 
of the self-adjoint 
integral operator $T_{f_{12}}$ 
on $L^2({\mathcal X},\nu)$.

\par
 \refstepcounter{thmenumerate}\textup{(\roman{thmenumerate})\enspace} 
In the special case of (TB2 of the paper) where
furthermore
$f$ is antisymmetric, 
then also
\begin{align}

  n^{-1}U^{--}_n(f) \overset{\mathrm{d}}{\longrightarrow} 
W:=\sum_{q=1}^{Q_+}\lambda^{\mathsf a}_q\eta_q,
\end{align}
where $(\eta_q)_1^{Q_+}$ are independent random variables with the stochastic area
distribution (equation area of the paper), and
the coefficients $(\lambda^{\mathsf a}_q)_1^{Q_+}$  are the positive numbers such that the
imaginary number $\mathrm{i}\lambda^{\mathsf a}_q$ is an eigenvalue of the 
anti-self-adjoint operator $T_{f_{12}}$ on $L^2_{\mathbb C}({\mathcal X},\nu)$.
We have
\begin{align}
  \operatorname{Var} W = \sum_{q=1}^{Q_+}(\lambda^{\mathsf a}_q)^2 = \tfrac12\operatorname{Var}[f_{12}(X_1,X_2)].
\end{align}
\par
 \refstepcounter{thmenumerate}\textup{(\roman{thmenumerate})\enspace} 
If $f_{12}=0$, then
\begin{align}
  \operatorname{Var}[U^{--}_{2n}(f)]&=2n\sigma^2_{\mathsf e}+O(1),
\\  
  \operatorname{Var}[U^{--}_{2n+1}(f)]&=(2n+1)\sigma^2_{\mathsf o}+O(1),
\end{align}
where
\begin{align}
  \sigma^2_{\mathsf e}&:=\tfrac12\bigl(\operatorname{Var}[f_1(X)] + \operatorname{Var}[f_2(X)]\bigr),
\\
  \sigma^2_{\mathsf o}&:=\tfrac12\operatorname{Var}[{f_1(X)+f_2(X)}].
\end{align}
Furthermore,
\begin{align}
  (2n)^{-1/2}\bigpar{U^{--}_{2n}(f)-\operatorname{\mathbb E}{} [U^{--}_{2n}(f)]}&\overset{\mathrm{d}}{\longrightarrow} N(0,\sigma^2_{\mathsf e}),
\\  
(2n+1)^{-1/2}\bigpar{U^{--}_{2n+1}(f)-\operatorname{\mathbb E}{}[U^{--}_{2n+1}(f)]}&\overset{\mathrm{d}}{\longrightarrow} N(0,\sigma^2_{\mathsf o}).
\end{align}
\end{romenumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:48:45.304865+00:00","domain":"probability theory","id":"claim_380d6e60d54047628ca0d13535e1d70a265bc7a8aebcd7eb435427c204dd345a","kind":"concept","schema_version":1,"statement":"[Theorem eq:linear_seat of arXiv:2411.14818, 'Scaling limits of solitons in the Box-Ball system'] Suppose that $\eta \in \Omega$. Then, for any $k \in {\mathbb{N}}$ and $i \in {\mathbb{Z}}$, we have
                    \begin{align}
                        \zeta_{k}\left(T\eta, i +  k + o_{k}\left(\eta\right) \right) = \zeta_{k}\left(\eta, i \right),
                    \end{align}
                where the offset $o_{k}\left(\eta\right)$ is given by 
                    \begin{align}
                        &o_{k}\left(\eta\right) \\
                        &:= s_{\infty}\left(\eta,0\right) - s_{\infty}\left( T\eta,0\right) + 2\sum_{y = s_{\infty}\left(0\right)+ 1}^{0} \sum_{\ell = 1}^{k}  \eta^{\downarrow}_{\ell}\left(y\right) - 2\sum_{y = Ts_{\infty}\left(0\right)+1}^{0}\sum_{\ell = 1}^{k}  T\eta^{\uparrow}_{\ell}\left(y\right).
                    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:51:26.724968+00:00","domain":"probability theory","id":"claim_380d767b3e3a24d95bbcc53b3348a0d7202912c841252246d99fc03653180dbd","kind":"theorem","schema_version":1,"statement":"[Proposition prop:key-area-estimate-p of arXiv:2606.06612, 'The limit shape and emergence of the \\ Discrete Gaussian level lines'] Fix $g\geq 0$, $n \geq 0$, and set $h = H+1-n$. Assume $\beta$ is sufficiently large. Let $\delta_p$ be the minimum of the constant from (clm:pi(h|h)-lower-p of the paper) and $\frac16$. There exists $c>0$ such that the following holds for every $\log^2L \leq \ell_0 \leq L^{\frac12 - \frac{\delta_p}2}$, and subsets 
    $F \subseteq V\subset \mathbb Z^2$ where $F$ has $g$ holes and $|\partial F| \leq L^{3/2}$.
    Let $\Xi = \Xi_1+\Xi_2+\Xi_3$, where for $1 < p < 2$ we define 
    \begin{equation} \Xi_1 =  \frac{|\partial V|}Le^{c\beta(\log L)^{\frac{2p-2}p}}\,,\qquad \Xi_2 = \frac{|F|}
     {\ell_0 L} e^{c\beta(\log L)^{\frac{p-1}{p}}} \,,\qquad \Xi_3 =\frac{|\partial F|\ell_0 }LL^{-\delta_p+o(1)}\,,\end{equation}
     and for $p > 2$ we define
     \begin{equation} \Xi_1 =  \frac{|\partial V|}LL^{\varepsilon_\beta}\,,\qquad \Xi_2 = \frac{|F|}
     {\ell_0 L} e^{c\sqrt{\beta\log L}}\,,\qquad \Xi_3 =\frac{|\partial F|\ell_0 }Le^{-c(\beta)\sqrt{\log L}^{\frac{p}{p-1}}}\,.\end{equation}
    \begin{enumerate}[(i)]
    \item If $1 < p < 2$ and $|F|\leq \ell_0 L e^{-c\beta(\log L)^{\frac{p-1}{p}}}$, or $p > 2$ and $|F|\leq \ell_0 L e^{-c\sqrt{\beta\log L}}$, then
    \begin{align}{\widehat\pi}^{(p),0}_V(\phi_x \geq -h,\, \forall x \in F) = \exp\left(-\xi^{(p)}_{\ell_0,h}|F| +O(\Xi) + o(L^{-5}) \right)\,.
    \end{align}
\item Otherwise, if $\mathfrak{S}$ is the event that there are no disagreement polymers $\gamma$ with $|\gamma| \geq \log L$, then
\begin{align}
    {\widehat\pi}^{(p),0}_V(\phi_x \geq -h,\, \forall x \in F) &\geq \exp\left(-\xi^{(p)}_{\ell_0,h}|F| + O(\Xi)\right)\,,\\

 {\widehat\pi}^{(p),0}_V(\phi_x \geq -h,\, \forall x \in F\mid\mathfrak{S}) &\leq \exp\left(-\xi^{(p)}_{\ell_0,h}|F| + O(\Xi)+o(L^{-5})\right)\,.
\end{align}
If $|F| \leq  \big(\frac{3\beta}{{\widehat\pi}^{(p)}_\infty(\phi_o > h)}\big)^2 $, then the last upper bound also applies to ${\widehat\pi}^{(p),0}_V(\phi_x\geq -h,\,\forall x\in F)$.
\end{enumerate}
    The same holds under ${\widehat\pi}^{(p)}_\infty$, in which case the error term $\Xi_1$ can be omitted from $\Xi$. Separately, in the special case where $F = \llbracket1,\ell\rrbracket^2$ with $ \ell_0 + 10\lceil \log L\rceil \mid \ell$, the error term $\Xi_3$ can be omitted from $\Xi$.","status":"unverified"}

