\end{equation}
\begin{compactenum}

\smallskip

\item[$(ii)$] Suppose that $\ttb\ino (1, \infty)$ is such that $\sum_{k\in \bbN} k^{\ttb} \nu (k) \leko \infty$. 
Then, 
$\bE [ U_\boo^\ttb]\leko \infty$ if $\bT$ is a GW($\nu$)-tree or an infinite  
GW($\nu$)-tree. If $\bT$ is 
an invariant GW($\nu$)-tree, then $\bE [ U_\boo^{\ttb-1}] \leko \infty$ if $\ttb \ino (2, \infty)$. 

\item[$(iii)$] The harmonic coordinates are the $\bbR$-valued r.v.~$(S_x)_{x\in \bT}$ defined by the following  
\end{compactenum}
\begin{equation}

S_\boo \eqo 0 \quad \textrm{and} \quad \forall x \ino \bT\backslash \{ \varnothing\} , \quad S_x \! -\! S_{\overleftarrow{x}}\eqo U_x  ,  
\end{equation}
\begin{compactenum}
\item[] on the event where (\ref{welldefcoo}) holds true and by $S_x \eqo 0$, $x\ino \bT$, on the $\bP$-negligible complementary event. 
Let $\overline{X}_n \eqo (\bT, X_n)$, $n\ino \bbN$, be a $\mathtt m_\nu$-biased RW such that $X_0 \eqo \boo$. We denote by $\ccF_{\! n}$ the $\sigma$-field generated by $(\overline{X}_k)_{0\leq k\leq n}$. Then $(S_{X_n})_{n\in \bbN}$ is a $(\ccF_{\! n})_{n\in \bbN}$-martingale:
\end{compactenum}
\begin{equation}

