{"assumptions":[],"created_at":"2026-10-27T07:31:20.610340+00:00","domain":"probability theory","id":"claim_38652550d7871090706ab2ee54de8ce155751e0dae10979477ebfed7245e98f2","kind":"concept","schema_version":1,"statement":"[Lemma 20 (Wang, Zhao and Zhu {\cite[Lemma 2.6) of arXiv:2608.25772, 'Propagation of Chaos and Gaussian Fluctuations for Mean-field Coupled Maps'] {WZZ23}}]
