   &-\int_{t}^{b}\aleph(t,s)dB_{s},\quad t\in [0,b].
\end{align}
such that the subsequent inequality holds almost surely: 
\begin{align}
&\Big\langle g_{u}(t, \bar{Y}(t),\mathbb{E}\bar{Y}(t), \bar{u}(t)) + \mathbb{E} \bigg[ \int_t^b \kappa_u(s, t, \bar{Y}(t),\mathbb{E}\bar{Y}(t), \bar{u}(t))^\ast X(s) \, ds\nonumber \\
&+ \int_t^b \nu_u(s, t, \bar{Y}(t),\mathbb{E}\bar{Y}(t), \bar{u}(t))^\ast \aleph(s, t) \, ds \mid \mathscr{F}_t \bigg](u - \bar{u}(t))\Big\rangle_{U} \geq 0,\quad \forall u\in U, \quad  t\in [0,b]\, a.s.
