{"assumptions":[],"created_at":"2026-10-27T10:07:48.565525+00:00","domain":"probability theory","id":"claim_38ced204ed4ecd9504a6df68b32a377e01404f8fb026d54c3f330e5c0760ab84","kind":"lemma","schema_version":1,"statement":"[Lemma 22 of arXiv:2609.01460, 'On cost-induced Santal\'o-type inequalities \\ in Polish measure spaces'] Let $\nu$ be a Borel measure on $\R^n$ and let $\mu$ be a Borel measure on
$\R^d$ which is homogeneous of degree $\alpha>0$. Suppose there
exists a continuous cost function $c:\R^n\times\R^d\to\R$ and a collection
$\mathcal C\subset 2^{\R^n}$ of bounded, measurable sets such that
\begin{enumerate}
    \item $c$ is positively $1$-homogeneous in the second variable;
    \item $-c$ is a non-negative mapping on
    $\mathcal C\times\mathcal B(\R^d)$;
    \item any $K\in\mathcal C$ failing the non-degeneracy condition \eqref{eq:non_degen} has $\nu$-measure zero;
    \item there exists $\lambda\in(0,1)$ and a set $B\in\mathcal C$ such that,
    for every $K\in\mathcal C$,
    \begin{equation}

        \nu(K)^\lambda \mu(K^{\circ,c})^{1-\lambda}
        \leq
        \nu(B)^\lambda \mu(B^{\circ,c})^{1-\lambda}
        :=
        C_{\nu,\mu}.
    \end{equation}
\end{enumerate}

Define the function $F(r)=C_{\nu,\mu}\,r^{\alpha(1-\lambda)}$ on $\R_+$. Then, the polish spaces $(\R^n,|\cdot|,\nu)$ and $(\R^d,|\cdot|,\mu)$ satisfy the cost-Santal\'o inequality associated with
$(\lambda,c,F)$ with domain $(\mathcal C,\mathcal B(\R^d))$. In the implied geometric
inequality,
\begin{equation}

    \nu(K)^\lambda \mu(L)^{1-\lambda}
    \leq
    C_{\nu,\mu}\,M(K,L)^{\alpha(1-\lambda)},
\end{equation}
where
\[ K\in\mathcal C, \,\,L\in\mathcal B(\R^d), \qquad \text{and} \quad M(K,L)=\sup_{x\in K,y\in L}-c(x,y),
\]
we have an equality characterization: if $L$ is bounded with $\nu(K)\mu(L)>0$, then there is equality in
\eqref{eq:implied_sant} if and only if, up to removal of null sets, one has $L=M(K,L)K^{\circ,c}$ and $K$ is a set for which equality holds in \eqref{eq:gen_geom_hypo}.

Consequently, for every $f\in\mathcal F(\mathcal C)$ and non-negative
measurable function $g$ satisfying the pointwise bound
\[
    f(x)^\lambda g(y)^{1-\lambda}
    \leq
    \Omega(-c(x,y)), \qquad \forall \, x\in \R^n, \, y\in \R^d, \text{such that } (-c(x,y))>0,
\]
 for a non-increasing function $\Omega:\R_+\to\R_+$, one has the functional inequality
\begin{equation}

\begin{split}
    \left(\int_{\R^n} f(x)\,d\nu(x)\right)^\lambda
    \left(\int_{\R^d} g(y)\,d\mu(y)\right)^{1-\lambda}
    &\leq
    C_{\nu,\mu}\,\alpha(1-\lambda)
    \int_0^\infty
    \Omega(r)r^{\alpha(1-\lambda)-1}\,dr
    \\
    &=\frac{C_{\nu,\mu}}{\mu(B_2^d)}
    \int_{\R^d}
    \Omega\left(|z|^{\frac{1}{1-\lambda}}\right)
    d\mu(z).
\end{split}
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:35:57.241324+00:00","domain":"probability theory","id":"claim_38d0b8ec4d6ae7776dad56ebc827d0622e00a0c9ec9c88cd16e3e25de7fc6fd5","kind":"concept","schema_version":1,"statement":"[Lemma lem:from-bgrs1-and-av of arXiv:2604.08154, '\small Hydrodynamic limit of the directed exclusion process'] ([bahadoran_constructive_2002],  [andjel_vares_hydrodynamic_1987]).
Let $\mu$ be a probability measure on $\mathbf{X}$ such that: 
\begin{enumerate}[(a)]
	\item $\nu_\rho\leq \mu\leq\nu_\lambda$ for some $0\leq\rho<\lambda$; 
	\item either $\mu\tau_1\leq\mu$ or $\mu\tau_1\geq\mu$.
\end{enumerate}


Then, any sequence $T_n\to\infty$ has a subsequence $T_{n_m}$ for which there exists
a dense countable subset $D$ of $\mathbb{R}$ satisfying
\begin{equation}
\lim_{m\to\infty}\frac{1}{T_{n_m}}\int_0^{T_{n_m}}\mu\tau_{[vt]}\ensuremath{\mathcal P}_t\, {\rm d} t=\int\nu_\alpha\,\gamma_v({\rm d}\alpha)=\mu_v\in\ensuremath{\mathcal I}\cap \ensuremath{\mathcal S}\; \text{,}\;\;\qquad v \in D\; \text{,}\;\;
\end{equation} 
where $\gamma_v$ is a probability measure on $[\rho,\lambda]$. 
Also, if $u<v$ are in $D$,
\begin{equation}
\lim_{m\to\infty}\mu\ensuremath{\mathcal P}_{T_{n_m}}\left(\frac{1}{T_{n_m}}\sum_{[uT_{n_m}]}^{[vT_{n_m}]}\eta(x)\right)=F(v)-F(u)\; \text{,}\;\;
\end{equation}
