		N_{\alpha_1,\alpha_2}^\beta(t_1,t_2)\overset{d}{=}N_\beta(T_{2\alpha_1}(t_1),T_{2\alpha_2}(t_2))\overset{d}{=}N(H_\beta(T_{2\alpha_1}(t_1),T_{2\alpha_2}(t_2))),\ (t_1,t_2)\in\mathbb{R}^2_+,
