        \left\|\mathbf u_n^{\mu} \odot \boldsymbol\Sigma_n (\mathbf u_n)\right\|_{\mathbf H^{\theta}_n}^2 &\lesssim \left\|\mathbf u_n^\mu\right\|_{\mathbf H^{\theta}_n}^2 + \left\|\mathbf u_n^{\mu+2}\right\|_{\mathbf H^{\theta}_n}^2, \\

