{"assumptions":[],"created_at":"2026-10-26T19:29:52.205321+00:00","domain":"probability theory","id":"claim_38fc13e98118ce9be690c03e32220c106352fa030938fa69a4e5fbf2908708f5","kind":"definition","schema_version":1,"statement":"[Defi 3 (Green's measures and Laplace transforms) of arXiv:2512.09136, 'On the Green's functions and Martin boundary structure of a planar diffusion in a disconti'] For $z_0=(a_0,b_0) \in \R^2$, we define the Green's measure on the plane $\R^2$ by
\begin{equation}
G(z_0,S) = \E_{z_0}\left[\int_0^{+\infty}\fc_{S}(Z_t)\,dt\right] = \iint_S g^{z_0}(a,b)\,da \,db, \quad \forall S \in \mathcal{B}(\R^2)
\end{equation}
where its density $g^{z_0}$ is called the Green's function and is equal to
\begin{equation}
g^{z_0}(a,b) = \int_0^{+\infty} p_t^{z_0}(a,b)\,dt, \quad \forall (a,b)\in\mathbb{R}^2.
\end{equation}

For $x, y, z \in \R$, we also define the Laplace transforms of $G(z_0,\cdot)$ restricted to the half-planes $\R \times (0,+\infty)$ and $\R \times (-\infty,0)$ by
$$
\phi_+^{z_0}(x,y) = \E_{z_0}\left[\int_0^{+\infty} e^{xA_t + yB_t} \fc_{B_t > 0}\,dt\right]
=\int_{\mathbb{R}}\int_0^\infty g^{z_0}(a,b)e^{xa+yb} 
\,da \,db, 
$$
$$
\phi_-^{z_0}(x,z) = \E_{z_0}\left[\int_0^{+\infty} e^{xA_t + zB_t} \fc_{B_t < 0}\,dt\right]
=\int_{\mathbb{R}}\int_{-\infty}^0 g^{z_0}(a,b)e^{xa+zb} 
\,da \,db.
$$
Finally, we define the Green's measure on the axis $\R \times \{0\}$  by
\begin{equation}
H(z_0, S) = \E_{z_0}\left[\int_0^{+\infty} \fc_S(A_t)\,dL^0_t(B)\right], \quad \forall S \in \mathcal{B}(\R)
\end{equation}
and its Laplace transform $\phi^{z_0}$ as
\begin{equation}
\phi^{z_0}(x) = \E_{z_0}\left[\int_0^{+\infty} e^{xA_t}\,dL^0_t(B)\right].
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:54:15.689123+00:00","domain":"probability theory","id":"claim_38fd57045d10a676db26d996429fa7762eb10af36c8056a13c0ba9f5b81a940f","kind":"concept","schema_version":1,"statement":"[Proposition 70 of arXiv:2608.09700, 'A general paracontrolled ansatz for singular SPDEs'] Let $Z_a\in B^{r(a)}_{i(a)}$ for any $a\in\mcA$ setting 
