\le
C_\eta S .
\end{equation}
The same ambient problem still has full-class minimax risk
\begin{equation}
\mathfrak R_{\rm mm}^{\rm full}(T_{M,N},\tau)
:=
\inf_{\widehat\theta}
\sup_{\theta\in T_{M,N}}
\mathbb E_\theta d(\theta,\widehat\theta(Y))
\asymp S,
\end{equation}
where the infimum is over all measurable estimators with values in the ambient Euclidean space.  Hence
\[
\frac{\mathfrak R_{\rm RNN}^{H}(\Lambda_{\rm under}(\eta))}
     {\mathfrak R_{\rm RNN}^{H}(\Lambda_{\rm opt}(\eta))}
\asymp
\frac{\mathfrak R_{\rm mm}^{\rm full}(T_{M,N},\tau)}
     {\mathfrak R_{\rm RNN}^{H}(\Lambda_{\rm opt}(\eta))}
\asymp
\frac{S}{R}
=
\frac18\sqrt{\frac{\log N}{\log M}}.
\]
For the associated Gaussian field \(X_t=\langle Z,t\rangle\), every \(\lambda\in\Lambda_{\rm opt}(\eta)\) satisfies the approximate comparison condition \eqref{eq:comparison-decoder-condition} with \(\Omega(t)=\lambda\|t\|_2^2\) and \(\varepsilon_{\rm cmp}=0\).  Thus Theorem~\ref{thm:nn-comparison}, together with \eqref{eq:opt-penalty-ghost-mass}, gives
\begin{equation}
\mathcal G_{\rm alg}(\lambda)
:=
\mathbb E_{\Theta,Z}
\bigl[X_{\widehat\Theta_\lambda(\Theta+\tau Z)}-X_\Theta\bigr]
\asymp
R\sqrt{\log M},
\qquad
\lambda\in\Lambda_{\rm opt}(\eta),
\end{equation}
where \(\Theta\sim\pi\) is the prior of Theorem~\ref{thm:decision-aligned-separation}.  Th (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:46:55.644186+00:00","domain":"probability theory","id":"claim_39f1e118db6246e456201f8f0b7e456e767d9caac8983608ee3d1bb8664d8b9d","kind":"concept","schema_version":1,"statement":"[Lemma 14 of arXiv:2605.24445, 'Matrix concentration inequalities for time-inhomogeneous Markov chains'] \label[lemma]{lem:tropp_step}
Let $P$ be a Markov operator on a Polish metric space $(\Omega,d)$. Let $G\colon \Omega \to \Hm$ and $x \in \Omega$ such that $PG(x) = 0$. Let $A \in \Hm$ such that $G(y)^2 \preceq A^2$ for any $y \in \supp P(x,\cdot)$.
Then, for any deterministic $H \in \Hm$,
\[
P \tr\exp\left( H + G \right)(x) \le  \tr\exp\left( H +  2 A^2 \right).
\] (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

