{"assumptions":[],"created_at":"2026-10-27T08:44:39.706200+00:00","domain":"probability theory","id":"claim_39f5bdd671abf3485c4e6944da9c097800b5c9b796a388e6835d0aa81262f74a","kind":"theorem","schema_version":1,"statement":"[Proposition 7 (Paralinearization of the transformed fractional flux operator) of arXiv:2608.29726, '\LARGE A Priori Estimates for Singular Fractional Stochastic Burgers Equations'] Let \(1<\gamma<2\), \(0<\beta<1\), and let
\(\Psi\in C^{1+\beta}(\T)\) be an orientation-preserving bi-Lipschitz map
with Jacobian satisfying \eqref{eq:J-bounds}.
The operator \(\Dcal_{\Psi}^{\gamma}\) defined in
\eqref{eq:Dflux} admits the paralinearization
\begin{equation}
  \Dcal_{\Psi}^{\gamma}f
  =(J^\gamma)^\Phi\prec\Rcal_\gamma f
  +\mathcal S_\Psi f,
\end{equation}
where \(\prec\) is the spatial Bony paraproduct.  For every
\(f\in H^{\gamma/2}\) and every
\begin{equation}
 \sigma<\min\{\gamma/2,1-\gamma/2+\beta\},
\end{equation}
the remainder satisfies
\begin{equation}
  \norm{\mathcal S_\Psi f}_{H^\sigma}
  \lesssim\norm f_{H^{\gamma/2}}.
\end{equation}
Thus \(\mathcal S_\Psi\) has order at most
\(\max\{0,\gamma-1-\beta\}+\).  Consequently,
\begin{align}
  \norm{\Dcal_{\Psi}^{\gamma}f}_{H^{1-\gamma/2}}
  &\lesssim\norm f_{H^{\gamma/2}},
  \\
  \norm{\Acal_{\Psi}^{\gamma}f}_{H^{-\gamma/2}}
  &\lesssim\norm f_{H^{\gamma/2}}.

\end{align}
The map
\[
 \Psi\longmapsto\Acal_\Psi^\gamma
 \quad\text{with values in}\quad
 \mathcal L(H^{\gamma/2},H^{-\gamma/2})
\]
is continuous on bounded subsets of \(C^{1+\beta}\) with fixed
bi-Lipschitz constants.  After any loss from \(\beta\) to
\(\beta_0<\beta\), this dependence has a local H\"older modulus.  All
displayed bounds are locally uniform under these assumptions.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:52:51.762773+00:00","domain":"probability theory","id":"claim_39f7b686247d6472f6eb1ecc2691a26b884cf5af4a5d7e40e70264ad2c9c0e8b","kind":"theorem","schema_version":1,"statement":"[Theorem thm:Z2L2bound2 of arXiv:2604.28068, 'Mean-square Stability and Bifurcations for Dissipative SDEs'] Let Assumption~(assum:FG_bounds of the paper) and (equation eq:diagonalize of the paper) hold, $Y$ be the solution of the centered SDE~(equation eq:main_YSDE of the paper) and $Z$ be the linearization error defined in (equation eq:Zdiff of the paper). Suppose there exists a non-decreasing
 function $K:[0,\infty)\to [0,\infty)$ such that
\begin{equation}
\mathbb{E}\left[\|R_F(Y(t),x^\ast)\|^2\right] \bigvee \expect{\|\mathrm{R_G}(Y(t),x^\ast)\|_{\mathbf{F}}^2} \leq K(t)  \qquad \text{for all } t\geq 0.
\end{equation}
 Then for any $\delta_1,\delta_2>0$ we have
\begin{equation*}
 \mathbb{E}\left[\|Z(t)\|^2\right]\leq 
 \left[\left(1+\delta_1^{-1}+\delta_2^{-1}\right) K(t)t +\|Z(0)\|^2\right]
e^{\boldsymbol{\mu} t}\qquad \text{for all } t\geq 0,
\end{equation*}
where
\begin{equation}

\boldsymbol{\mu}:=2\lambda_{\max}\{\mathbf{D}F(x^\ast)\} + \delta_1 + (1+\delta_2)\|\mathbf{D}G(x^\ast)\|_{T_3}^2.  
\end{equation}
In particular, if $K$ is of subexponential growth and $\boldsymbol{\mu}<0$ 
then $\lim_{t\to\infty} \mathbb{E}\left[\|Z(t)\|^2\right]=0.$","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:06:07.090875+00:00","domain":"probability theory","id":"claim_39f9e78045c52f469f7c7e0225acabc3192023a5186a1b748b12da2b5af5e16d","kind":"theorem","schema_version":1,"statement":"[Theo 30 of arXiv:2608.28148, 'Flows and homotopies of Banach Lie algebroids'] Let $(A,\pi,M,\rho,\LB_A)$ be a Banach almost Lie algebroid and $\mathfrak{u}\in\Gamma(A_U)$ a local section. Then there exists a unique linear vector field $(\mathcal{X}_\mathfrak{u}, \rho(\mathfrak{u}))$ on $A_U$, such that
\begin{enumerate} 
\item for every local section $\sigma$ of $A^*$ we have 
\begin{align}
\LXu (\Phi^\sigma)=\Phi^{L_\mathfrak{u}\sigma}, \quad T\pi\circ \LXu = \rho(\mathfrak{u}) \circ \pi.
\end{align}
In local coordinates this field is given by, 
\begin{align} 
\LXu(x,\alpha) = \left( x,\alpha, r_x(\mathsf{u}(x)), d_x\mathsf{u}(r_x(\alpha))+C_x(\alpha,\mathsf{u}(x)) \right).
\end{align}
\item The local flow $\mathfrak{F}^t_\mathfrak{u}$ of $\LXu$ is a vector-bundle isomorphism covering $\varphi_t:=\Fl^t_{\rho(\mathfrak{u})}$ the local flow of $\rho(\mathfrak{u})$. For every local dual section $\sigma$ and $x\in U$,
\begin{align}
L_\mathfrak{u}\sigma = \left. \frac{d}{dt} \right|_{t=0} \left(\mathfrak{F}^t_{\mathfrak{u},x})^T(\sigma\circ\varphi_t) (x)\right). \end{align} 
 where $(\mathfrak{F}_{\mathfrak{u},x}^t)^T\colon A^*_{\varphi_t(x)}\to A^*_x$ is the transpose\footnote{For a continuous linear map $L\colon E\to F$, its transpose is $L^T\colon F^*\to E^*, L^T(\lambda):=\lambda\circ L$.} of $\mathfrak{F}_\mathfrak{u}^t \colon A_x\to A_{\varphi_t(x)}$.
 \item  Using the flows $\mathfrak{F}^t_\mathfrak{u}$ and $\varphi_t$ from 2., for every local section $\mathfrak{v}$, 
\begin{align}
\left. \frac{d}{dt} \right|_{t=0} (\mathfrak{F}^t_{\mathfrak{u},x})^*\mathfrak{v}(x) = \LB[\mathfrak{u},\mathfrak{v}]_A(x), \quad x\in U
\end{align}
where $(\mathfrak{F}^t_\mathfrak{u})^*\mathfrak{v}(x) = (\mathfrak{F}^{t}_{\mathfrak{u},x})^{-1} \bigl( \mathfrak{v}(\varphi_t(x)) \bigr)$.
 \end{enumerate}","status":"unverified"}

