\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:46:09.854360+00:00","domain":"probability theory","id":"claim_3a2035e043bb40e1b704153239d28396e607ab5b2633d755aeb114f45abda26a","kind":"definition","schema_version":1,"statement":"[Definition 1 of arXiv:2605.20026, 'Quasihelix properties\\ of selected Volterra Gaussian processes'] A Gaussian process $G=\{G_t,\ t\ge0\}$ is called
\begin{itemize}
    \item[$(i)$] a \emph{$\rho$-quasihelix} if there exist $\rho>0$ and constants $C_1,C_2>0$ such that, for all $t,s\in[0,\infty)$,
    \begin{equation*}
        C_1|t-s|^{\rho}
        \le
        \|G_t-G_s\|_2
        \le
        C_2|t-s|^{\rho};
    \end{equation*}

    \item[$(ii)$] a \emph{local $(\rho,T_1,T_2)$-quasihelix} on the interval $[T_1,T_2]$ if there exist $\rho>0$ and constants $C_1(T_1,T_2),C_2(T_1,T_2)>0$ such that, for all $t,s\in[T_1,T_2]$,
    \begin{equation}
        C_1(T_1,T_2)|t-s|^{\rho}
        \le
        \|G_t-G_s\|_2
        \le
        C_2(T_1,T_2)|t-s|^{\rho};
    \end{equation}

    \item[$(iii)$] a \emph{local $(\rho_1,\rho_2,T_1,T_2)$-generalized quasihelix} on the interval $[T_1,T_2]$ if there exist $\rho_1,\rho_2>0$ and constants $C_1(T_1,T_2),C_2(T_1,T_2)>0$ such that, for all $t,s\in[T_1,T_2]$,
    \begin{equation}
        C_1(T_1,T_2)|t-s|^{\rho_1}
        \le
        \|G_t-G_s\|_2
        \le
        C_2(T_1,T_2)|t-s|^{\rho_2}.
    \end{equation}
\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:21:45.321838+00:00","domain":"probability theory","id":"claim_3a2084b237cc2ffd1ac5a79ea670222bf7935101539955d0d9ec8cb1330787ef","kind":"lemma","schema_version":1,"statement":"[Lemma 9 of arXiv:2607.27150, 'Modelling Anomalous Diffusion: The Role of CTRWs and Non-Local Dynamics'] Fix $T>0$, and let $(\mathfrak{B}, \left\| \cdot \right\|)$ be a Banach space. Suppose that $f: [0, +\infty) \mapsto \mathfrak{B}$,  is such that there exists a Bochner integrable function $g: [0, +\infty) \mapsto \mathfrak{B}$ such that
		\begin{align}
			f(t) - f(0) = \int_0^t g(s) \, ds,\quad t \in [0,T].
		\end{align}
		Then $\partial_tf(t)$ and $\phi(\partial_t) f(t)$ exists a.e. in $[0,T]$ and are elements of $L^1([0,T]; \mathfrak{B})$. Moreover, for almost all $t\in [0,T]$, it holds that $\partial_tf(t)=g(t)$ and
		\begin{align}
			\phi(\partial_t)\big(f(t)-f(0)\big) = b \partial_tf(t) + \int_0^t \partial_sf(s) \, \bar{\nu}(t-s) \, ds.

		\end{align}
		If, furthermore, $g\in C([0,T]; \mathfrak{B})$, then $t \mapsto \phi(\partial_t ) f(t) \in C([0,T]; \mathfrak{B})$ and \eqref{der_dentro} holds for all $t\in [0,T]$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:25:05.832289+00:00","domain":"probability theory","id":"claim_3a21a9f8075ef308365eaa131c4876ff12ba90fc85362eeb67e8fa055ca31422","kind":"concept","schema_version":1,"statement":"[Corollary 5 (Regret under the logarithmic buffer) of arXiv:2608.22227, '\fontsize{18pt}{20pt}\selectfont \bf Risk-Sensitive Reinforcement Learning with Smoothed Q'] For each $t$ choose \(\beta_t = \frac{\tau} {\log(\mathrm e + t)},\) and define \(K_\tau \coloneqq \left\lceil \exp\!\left(\frac{\tau}{\rho_\tau}\right)-\mathrm e \right\rceil\). Then, under the conditions of Theorem~\ref{thm:UCB-BQRL-finite}, with probability at least \(1-2\delta\), $\Reg_\tau(T)\le\;2H K_\tau+ \allowbreak \frac{c\log(\mathrm e+T-1)}{\tau}\sqrt{SA TH^4\log\!\frac{2SATH}{\delta}} + \allowbreak\frac{c\log(\mathrm e+T-1)}{\tau}\sqrt{\frac{TH^4}{2}\log\!\frac{2SATH}{\delta}\log\!\frac{1}{\delta}} \allowbreak$. Consequently,
\(\Reg_\tau(T) = \widetilde{\mathcal O}\!\left(
\frac{1}{\tau}\sqrt{SATH^4}
\right) + O(K_\tau H)\). (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:31:49.844714+00:00","domain":"probability theory","id":"claim_3a22abc3e0a88ee0d5d43e162f848b272610de918e4b35b917c2fe521fcc1580","kind":"definition","schema_version":1,"statement":"[Definition def: fluid problem of arXiv:2608.23756, 'Measure-valued fluid limits for partial service queues\\with correlated patience and servi'] The set of solutions of the \emph{fluid problem} is denoted by $\mathcal{S}^+$. We say that a measure-valued function $\boldsymbol{\mu} \in D_{\mathcal{M}_F^+(\mathbbm{R}_+^2)}[0, \infty)$ is a solution of the fluid problem, and thus belongs to $\mathcal{S}^+$, if it satisfies the following conditions.
	\begin{enumerate}
		\item[(a)] We have $\boldsymbol{\mu}_t(U_g^c) = 0$ for all $t \geq 0$, where we use the notation $U_g^c \vcentcolon= \mathbbm{R}_+^2 \setminus U_g$.

		\item[(b)] The $y$-marginal of $\boldsymbol{\mu}_t$ is absolutely continuous with respect to the Lebesgue measure for all $t \geq 0$; this is the measure $A \mapsto \boldsymbol{\mu}_t(\mathbbm{R}_+ \times A)$ defined for Borel sets $A \subset \mathbbm{R}_+$.

		\item[(c)] The following integral is finite for all $t \geq 0$:
		\begin{equation*}
			\int_0^t \angled{\bar r(\boldsymbol{\mu}_s)h_g^x + h_g^y}{\boldsymbol{\mu}_s}ds = \int_0^t\int_{U_g} \left[\bar r\left(\boldsymbol{\mu}_s, y\right)h_g^x(x, y) + h_g^y(x, y)\right]\boldsymbol{\mu}_s(dx, dy)ds < \infty.
		\end{equation*}

		\item[(d)] The following equation holds for all $t \geq 0$ and $\varphi \in C_c^1(\mathbbm{R}_+^3)$:
		\begin{equation}

			\begin{split}
				\angled{\varphi_t}{\boldsymbol{\mu}_t} &= \angled{\varphi_0}{\boldsymbol{\mu}_0} + \lambda_0 \int_0^t \varphi_s(0, 0)ds - \int_0^t \angled{\varphi_s\left[\bar r(\boldsymbol{\mu}_s)h_g^x + h_g^y\right]}{\boldsymbol{\mu}_s}ds \\
				&+ \int_0^t \angled{\partial_t\varphi_s + \bar r\left(\boldsymbol{\mu}_s\right)\partial_x\varphi_s + \partial_y\varphi_s}{\boldsymbol{\mu}_s}ds.
			\end{split}
		\end{equation}
	\end{enumerate}
	We remark that the values of the test function $\varphi$ are denoted by $\varphi_t(x, y)$, with the time variable as a subscript. Also, the integrals with respect to $\boldsymbol{\mu}_s$ only involve the variables $x$ and $y$ of the integrand and keep the time variable $s$ fixed. We establish in Appendix (app: measurability properties of the paper) that the iterated integrals on the right-hand side of (equation eq: transport equation of the paper) are well-defined. Specifically, we show that the inner integrals are Borel measurable with respect to $s$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T21:00:30.497863+00:00","domain":"probability theory","id":"claim_3a233fb088e0a43002543b0bdc2d1a4e893a99a23cb1bc262b7885d1c76f1261","kind":"concept","schema_version":1,"statement":"[Proposition 2 (Standard Bernstein representations) of arXiv:2607.04467, 'Bernstein Functions at Work:\\ Coalescents, Copulas, and Subordination'] The following standard facts are used below.
\begin{enumerate}[label=\textup{(\roman*)},leftmargin=2.3em]
\item If \(g\in\BF\), then there are \(a,b\ge0\) and a measure \(\nu\) on
\((0,\infty)\) satisfying
