{"assumptions":[],"created_at":"2026-10-27T05:44:27.958367+00:00","domain":"probability theory","id":"claim_3a8643a550c6c6683e38b9cf521fe9b29fa6957064004e53afa6f17cc3fd1184","kind":"concept","schema_version":1,"statement":"[Theorem 3 (Gaussian localization of massive forest components) of arXiv:2607.13210, 'Punctured Wilson--Evolving Sets and Root Identities for Massive Kirchhoff Forests'] Assume that $\pi\equiv1$, let $n=|V|$, and let $d_G$ be a graph distance. Suppose that
there exist $\nu>4$ and constants $C_V,C_H,c_H>0$ such that, for every $x,y\in V$,
$r\geq0$ and $t\geq0$, we find:
\begin{equation}
  |B(x,r)|\leq C_V(1+r)^\nu
\end{equation}
and also, we get:
\begin{equation}
  P_t(x,y)
  \leq
  \frac{C_H}{(1+t)^{\nu/2}}
  \exp\left(-c_H\frac{d_G(x,y)^2}{1+t}\right)
  +\frac{C_H}{n}.
\end{equation}
Then there exist $C,c>0$, depending only on the constants above, such that, for every
$0<q\leq1$ and every $x,y\in V$, one gets:
\begin{equation}
  h_q(x,y)
  \leq C\left[
  (1+d_G(x,y))^{2-\nu}e^{-c\sqrt q\,d_G(x,y)}
  +\frac{1}{qn}
  \right],
\end{equation}
\begin{equation}
  \Pp(x\leftrightarrow_q y)
  \leq C\left[
  (1+d_G(x,y))^{4-\nu}e^{-c\sqrt q\,d_G(x,y)}
  +\frac{1}{q^2n}
  \right],
\end{equation}
and
\begin{equation}
  \Ee[|C_q(x)|]\leq Cq^{-2}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:32:58.356138+00:00","domain":"probability theory","id":"claim_3a8a832bfdd572a9520a31423e7bda199949ea2df43cc4788bfe6ab262182e43","kind":"concept","schema_version":1,"statement":"[Theorem 4 of arXiv:2506.18313, 'A stochastic model for the diffusion of competing opinions with trend-following, oppositio'] Assume $\theta=1/2$. Then, as $n \to \infty$, the following results hold:
\begin{itemize}

\item [(i)] (Almost sure convergence of empirical measures)
\begin{equation}

\begin{array}{lll}
\displaystyle\lim_{n\to\infty}  \dfrac{1}{\log\log n}\displaystyle\sum_{j=2}^n\frac{1}{j\log j}\left(\mathbb{I}\left\{\sqrt{\frac{j}{\log j}}\hat{N}_j \le x \right\},\mathbb{I}\left\{\sqrt{\frac{j}{\log j}}\hat{M}_j \le y \right\}  \right) = G(x,y)    & \text{ a.s.},
\end{array}
\end{equation}
where $G$ is the distribution function of a normal random vector with
\begin{equation}
\mathbb{E}[(X,Y)]= (0,0)  \  \text{ and } \
\mathbb{V}[(X,Y)]= 2a(1-2a)  \left(\begin{array}{cc}
1 & -1 \\
-1 & 1 
\end{array}
\right).
\end{equation}

\item [(ii)] (Almost sure convergence of moments)  
For all integers $m \geq 1$, we have

\begin{equation}

\begin{array}{lll}
  \displaystyle\frac{1}{\log \log n}\sum_{j=2}^n \left(\frac{1}{j \log j}\right)^{m+1} j^{m-1} \left(\hat{N}_j^{2m},\hat{M}_j^{2m}\right) \rightarrow \frac{[a(1-2a)]^{m}(2m)!}{ m!}(1,1)   & \text{ a.s.},
\end{array}
\end{equation}    


\item[(iii)] (Law of the iterated logarithm)
\begin{equation}

        \limsup_{n \to \infty} \pm \frac{\sqrt{n}(\hat{N}_n, \hat{M}_n) }{\sqrt{2 \log n \cdot \log \log ( \log n)}} = \sqrt{ 2a(1-2a)} (1,1) \ \text{ a.s. }
    \end{equation}


    \item [(iv)] (Asymptotic behavior of the average difference process)  
We have the almost sure convergence
\[\displaystyle\lim_{n \to \infty} \frac{C_n}{n}=\frac{4a-1}{2},\]
and the following central limit theorem:
\begin{equation}

\sqrt{\frac{n}{\log n}}\left(\frac{C_n}{n}-\frac{4a-1}{2}\right) \overset{d}{\longrightarrow} \mathcal{N} \left(0,\frac{32a(1-2a)}{9}\right).
\end{equation} 
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:55:18.056572+00:00","domain":"probability theory","id":"claim_3a8d5540fe31573a6dc6768c739b26c45cdaf2a614557d99510f24d4b5f17d26","kind":"concept","schema_version":1,"statement":"[Proposition 25 of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] We fix $(t,q)\in(0,\infty)\times \mcl Q_\infty^\D$ and suppose that there is a sequence $(N_k,x_k,q_k)_{k\in\N}$ such that $\lim_{k\to\infty} N_k=+\infty$, $\lim_{k\to\infty}\Delta_{N_k}(x_k,q_k)=0$, $\sup_k|q_k|_{L^\infty}<\infty$, and $q_k$ converges pointwise a.e.\ to some $q\in\mcl Q_\infty^\D$. Then, there are a subsequence $(N'_k,x'_k,q'_k)_{k\in\N}$ and ${p}\in \mcl Q^\D_{\infty,\leq 1}$ such that
\begin{enumerate}
    \item  $R_{N'_k}$ under $\E\la\cdot\ra^\circ_{N'_k,x'_k,q'_k}$ converges in law to
    \begin{align*}
        \Ll(Q^{\ell,\ell'}_{p}\1_{\ell\neq \ell'}+ (\vecone,1) \1_{\ell =\ell'}\Rr)_{\ell,\ell'\in\N}
\end{align*}
    under $\E \la\cdot\ra_\fR$ as $k$ tends to infinity;
    \item  we have $\lim_{k\to\infty}A_{N'_k}\Ll(x'_k,q'_k\Rr) =-  \mathscr{P}_{t,{q}}({p})$;
    \item 
    for every bounded continuous $g:\R^{\D}\times \R\to\R$,
    \begin{equation*}  \lim_{k\to\infty} \E \la g\Ll(\diag\Ll(\tau\tau'^\intercal\Rr), \alpha\wedge\alpha'\Rr)\ra_{N'_k+1,x'_k,q'_k} =\E \la g\Ll(\diag\Ll(\tau\tau'^\intercal\Rr), \alpha\wedge\alpha'\Rr)\ra_{\fR,{q}+t\nabla\xi({p})}.
    \end{equation*}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

