        \begin{align*}
          \esssup\limits_{p\in\BM} \int_{\|x\|>u} \varphi(x,p,q) \, d x \, \BQ(d q)
        \end{align*}
        decays exponentially fast as $u\to\infty$, then for $t<t_T$ there exists $\delta_2:=\delta_2(t)$ such that 
        \begin{align*}
            \esssup\limits_{p\in\BM}\BE_t e^{\delta_2 D(V^{(0,p)})}<\infty.
        \end{align*}
       \item [{\rm (iv)}] Suppose $n\in\N$ satisfies \eqref{c:main}. Then $t_T=t_c\in(0,\infty)$ and 
$\bar{c}_{t_c}=\BE_{t_c}\int |V^{(0,p)}|\,\BQ(dp)=\infty$.
        \item[{\rm (v)}] Suppose $n\in\N$ satisfies \eqref{c:main}. Then
        \begin{align*}
        \|c(t)\|_r\ge \frac{t_c}{\Delta_n(t)(t_c-t)},
    \end{align*}
    for $t<t_c$ and for all $r\in[1,\infty]$. 
       \item[{\rm (vi)}] Suppose that $n\in\N$ satisfies \eqref{c:main} and let $\delta>0$.  
Then 
\begin{align*}
    \|\theta(t)\|_r \geq \left(\frac{\bar\theta(t_c)}{\delta}+\frac{\I\{\bar\theta(t_c)=0\}}{2t\Delta_n(t)}\right)(t-t_c),
\end{align*}
for all $t\in[t_c, t_c + \delta]$ and $r\in\left[1,\infty\right]$. 
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:52:17.371078+00:00","domain":"probability theory","id":"claim_3ab3b842df9d9cdc546b51ab48295d017ff315b6bd6ca22a2f0b2c543cdaee55","kind":"theorem","schema_version":1,"statement":"[Theorem 11 of arXiv:2606.03661, '2606.03661'] For the Laplace transform $\mathscr{L}_t[t^\mu \Psi_\alpha^\nu(-\kappa t);z]$ 
