{"assumptions":[],"created_at":"2026-10-27T18:48:24.299942+00:00","domain":"probability theory","id":"claim_3afa20d537eba59cba99a48d643b32309714b5a37ed22639e3076f7668d1490f","kind":"theorem","schema_version":1,"statement":"[Proposition prop:IPS:relative-entropy:evolution of arXiv:2605.16904, 'Positive-rate PCA and IPS with stationary Bernoulli measures are rapidly forgetful \footno'] Let $\Phi$ be an IPS with a strictly positive local transition rule $\varphi\colon\Sigma^N\times\Sigma\to(0,1)$, and suppose that $\Phi$ admits a stationary Bernoulli measure $\lambda=\lambda_q$.

	Then,
	\begin{equation}
		D_J(\mu\Phi^t\relto\lambda) \leq
			D_J(\mu\Phi^t\relto\lambda)\mathrm{e}^{-\kappa t}
			+
			\frac{1-\kappa}{\kappa}\abs{N}\log(\sfrac{1}{q_\mathsf{min}})\cdot\abs{\partial^- N(J)}

	\end{equation}
	for every probability measure~$\mu$, every finite set $J\subseteq\mathbb{Z}^d$, and every $t\geq 0$, where
	$\kappa \coloneqq \min\big\{\varphi(a_N,b)/q(b): a_N\in\Sigma^N,b\in\Sigma\big\}$
	and
	$q_\mathsf{min}\coloneqq\min\{q(a): a\in\Sigma\}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:10:07.501853+00:00","domain":"probability theory","id":"claim_3afb71eeee01c9533714b4d21e18834b05a9062ee687edf7ad5df54f77bcae1c","kind":"theorem","schema_version":1,"statement":"[Proposition eq:bounded-moment-match of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[proposition]{prop:bounded-moment-law}
