{"assumptions":[],"created_at":"2026-10-27T19:37:08.312366+00:00","domain":"probability theory","id":"claim_3b3b7cf012f976cc21ed15fd31214cb50463f373f39a87abf707c3dc09016105","kind":"concept","schema_version":1,"statement":"[Lemma Delta_t of arXiv:2608.29507, 'Denoising as Projection: Constrained Optimization with Gradient-Guided Diffusion'] Let $u_t, v_t$ be defined as in (equation eq:def-u-v of the paper) and let $\Delta_t := (\Phi_{t}(A^\top u_{t}) - \Phi_{t}(x_{t}^\star))$ and $\widetilde{\eta}$ defined as in (equation eq:subspace-dynamics of the paper), then under the conditions specified in Theorem (theorem: convergence-guided-diffusion of the paper), we have
    \begin{align*}
        \Delta_{t-1} \le (1-\widetilde{\eta} \mu c)\Delta_t + \frac{(\sigma_t^2 - \sigma_{t-1}^2)\eta^{-1}D^2}{2} +  \frac{\widetilde{\eta} L^2}{2}\|v_t\|^2
    \end{align*}
\begin{proof}
    We start with bounding
    \begin{align*}
        \mathrm{LHS}
        &:= \bigl(\Phi_t(A^\top u_{t-1})-\Phi_t(x_t^\star)\bigr)
        -\bigl(\Phi_t(A^\top u_t)-\Phi_t(x_t^\star)\bigr)\\
        &=\Phi_t(A^\top u_{t-1})-\Phi_t(A^\top u_t).
    \end{align*}
    From the $L$-smoothness of $f$, the definition of $\Phi_t$, and the fact that
    $AA^\top=I$, we have
    \begin{align*}
        \mathrm{LHS}
        &\le
        \left\langle
        \nabla\Phi_t(A^\top u_t),
        A^\top(u_{t-1}-u_t)
        \right\rangle\\
        &\quad
        +\frac{1}{2}
        \left\langle
        u_{t-1}-u_t,
        \left(
        LI+\frac{\sigma_t^2}{\eta}\Sigma^{-1}
        \right)
        (u_{t-1}-u_t)
        \right\rangle.
    \end{align*}
    By (equation eq:subspace-dynamics of the paper),
    \[
        u_{t-1}-u_t
        =
        -\widetilde{\eta} M_tA\nabla\Phi_t(x_t).
    \]
    Therefore,
    \begin{align*}
        \mathrm{LHS}
        &\le
        -\widetilde{\eta}
        \left\langle
        \nabla\Phi_t(A^\top u_t),
        A^\top M_tA\nabla\Phi_t(x_t)
        \right\rangle\\
        &\quad
        +\frac{\widetilde{\eta}^2}{2}
        \left\langle
        M_tA\nabla\Phi_t(x_t),
        \left(
        LI+\frac{\sigma_t^2}{\eta}\Sigma^{-1}
        \right)
        M_tA\nabla\Phi_t(x_t)
        \right\rangle.
    \end{align*}
    Note that, since $\widetilde{\eta}=\eta\epsilon$, $\widetilde{\eta} L\le 1$, and
    $\epsilon\le 1$,
    \begin{align*}
        \widetilde{\eta}
        \left(
        LI+\frac{\sigma_t^2}{\eta}\Sigma^{-1}
        \right)
        &=
        \widetilde{\eta} LI+\epsilon\sigma_t^2\Sigma^{-1}\\
        &\preceq
        I+\sigma_t^2\Sigma^{-1}
        =
        M_t^{-1}.
    \end{align*}
    Hence,
    \begin{align*}
        \widetilde{\eta} M_t
        \left(
        LI+\frac{\sigma_t^2}{\eta}\Sigma^{-1}
        \right)
        M_t
        \preceq M_t.
    \end{align*}
    It follows that
    \begin{align*}
        \mathrm{LHS}
        &\le
        -\widetilde{\eta}
        \left\langle
        \nabla\Phi_t(A^\top u_t),
        A^\top M_tA\nabla\Phi_t(x_t)
        \right\rangle\\
        &\quad
        +\frac{\widetilde{\eta}}{2}
        \left\langle
        \nabla\Phi_t(x_t),
        A^\top M_tA\nabla\Phi_t(x_t)
        \right\rangle.
    \end{align*}
    Define
    \[
        \delta_t
        :=
        \nabla\Phi_t(x_t)-\nabla\Phi_t(A^\top u_t).
    \]
    Then
    \begin{align*}
        \mathrm{LHS}
        &\le
        -\widetilde{\eta}
        \left\langle
        \nabla\Phi_t(A^\top u_t),
        A^\top M_tA
