				\end{align}
				Moreover, the following comparison principle holds true: $ Y_i^1\geq Y_i^2$,
				whenever $Y_N^1 \geq Y_N^2$ and $G_j^1(Y_i^2, Z_i^2)\geq G_j^2( Y_i^2, Z_i^2)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:26:40.361607+00:00","domain":"probability theory","id":"claim_3c2ff53531735b33bd856835b6fcec100ba57bd6e87e6c6425c58de1c4dfd4b7","kind":"definition","schema_version":1,"statement":"[Definition 53 (Uniform selection pair) of arXiv:2511.09517, 'From Cannings model to Brownian motion conditioned on local time profile'] Fix a base height $h^*$. For $0\le h\le h^*$, $1\le p\le q_n(h^*)$ and $1\le k\le q_n(h)$, let $(A,\mathcal{V})$ be a pair consisting of
\begin{itemize}
    \item an event $A$ measurable with respect to $\mathcal{G}_{h}^{(p)}\vee \sigma(\Lambda_h)$, and
    \item a random vector $\mathcal{V}$ of $k$ vertices taking values in $\{x^{h}_1,\ldots, x^{h}_{q_n(h)}\}$.
\end{itemize}
We say that $(A,\mathcal{V})$ is a $(p,h,k)$-uniform selection pair if, under $\mathbb{P}_n$,
\[
(\mathcal{V}\mid A)\,\overset{d}{=}\,\{u^{h}_1,\ldots,u^{h}_k\},
\]
that is, conditionally on $A$, the vector $\mathcal{V}$ has the same distribution as a uniformly chosen $k$-tuple of distinct vertices at height $h$. When \(p=q_n(h^*)\), we abbreviate this as an \((h,k)\)-uniform selection pair.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:01:22.646600+00:00","domain":"probability theory","id":"claim_3c37fb9f78ba0d5b68db0c14a84d2481f9aa6506a2b90fb8b9d413e9bf1adaa2","kind":"theorem","schema_version":1,"statement":"[Proposition prop:zero-potential-correction of arXiv:2607.03639, '\vspace{-0.6in}An AI-Assisted Solution to the Signed BAR Conjecture: Uniqueness in the Har'] Assume that the SRBM is a strong Markov process whose transition semigroup is Feller on $C_0(E)$, and that it has stationary probability $\pi_0$. Suppose that there are a locally bounded function $V:E\to[1,\infty)$ and constants $M,\kappa>0$ such that
\begin{equation}
 \|P_t(x,\cdot)-\pi_0\|_{\mathrm{TV}}
 \le M V(x)e^{-\kappa t},
 \qquad x\in E,\ t\ge0.
\end{equation}
Suppose also that
\begin{equation}
 c_i:=\sup_{x\in E}\mathbb E_xY_i(1)<\infty,
 \qquad i=1,\ldots,d.
\end{equation}
Let $\chi\in\mathcal M(E)$ satisfy $\chi(E)=0$ and $\int_E V\,d|\chi|<\infty,$ and let $\zeta_i\in\mathcal M(F_i)$ satisfy
\begin{equation}
 \sum_{i=1}^d\int_{F_i}D_i f\,d\zeta_i
 =\int_E f\,d\chi,
 \qquad f\in C_b^2(E).
\end{equation}
Define
\begin{align}
 \overline\pi&=\int_0^\infty \chi P_t\,dt,
                                                    \\
 \theta_i&=\sum_{n=0}^\infty(\chi P_n)K_i,
                                                    \\
 \overline\nu_i&=\theta_i+\zeta_i.              
\end{align}
Then all measures in (equation eq:ce-pi-potential of the paper)--(equation eq:ce-nu-corrected of the paper) are well defined in total variation and finite. They form a signed BAR tuple for all $f\in C_b^2(E)$, hence also for all $f\in C_c^2(E)$, and $\overline\pi(E)=0.$ If $\chi\ne0$, then $\overline\pi\ne0$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:59:53.171117+00:00","domain":"probability theory","id":"claim_3c3ba265baf0ba4a1e085477c78e3598f34bb3f054f50913a8bf7c36359e4a49","kind":"theorem","schema_version":1,"statement":"[Theorem 46 (Quadratic Mild Supersolutions) of arXiv:2607.03318, 'Continuous Differentiability of the Value Function for Infinite-Dimensional Finite-Horizon'] Let Assumption \ref{ass:coefficients} hold. Assume, moreover, that the unbounded linear operator $A$ satisfies $\langle Ax, x \rangle_H \le \omega \|x\|_H^2$ for some $\omega \in \mathbb{R}$ and all $x \in \mathrm{Dom}(A)$. Let $\phi(x) := \|x\|_H^2$. Then, there exists a constant $C > 0$, such that for any penalization parameter $\varepsilon > 0$ and initial time $t \in [0, T]$, $\phi$ satisfies:
\begin{equation} 

