{"assumptions":[],"created_at":"2026-10-26T20:38:37.405513+00:00","domain":"probability theory","id":"claim_3c48563df4d7389622a2d2aa5beef71a31693578d835d43cb6599366dffa7e2f","kind":"concept","schema_version":1,"statement":"[Lemma 8 (Law of large numbers) of arXiv:2605.15718, 'Mean-field derivation of a two-dimensional signal-dependent parabolic-elliptic Keller-Sege'] Let $(\Omega,\mathcal{F},\pr )$ be a probability space and $(Y_i : \Omega \to \R^d)_{i \in \N}$ a sequence of i.i.d random variables such that the distribution of $Y_i$ has probability density $v$. Moreover let $\Psi : \R^d \to \R$ continuous and bounded. We consider the following subsets:
\begin{align*}
& A^{N,i}_\theta (\Psi ,v):= \bigg\{ \Big|\displaystyle\frac{1}{N}\sum_{j=1}^N  \Psi (Y_i - Y_j) - \Psi \ast v (Y_i)  \Big| \geq \frac{1}{N^\theta} \bigg\} \mbox{ and } A^N_\theta (\Psi ,v) := \bigcup^N_{i=1} A^{N,i}_\theta (\Psi,v).
\end{align*}
For all $m \in \N$ and $\theta \in [0,\frac{1}{2})$ there exists some $C>0$ such that for all $N \in \N$
$$ \pr \big( A^N_\theta (\Psi ,v) \big) \leq N \max_{1 \leq i \leq N} \pr \big( A^{N,i}_\theta (\Psi,v) \big) \leq C N^{2m(\theta -\frac{1}{2})+1} \Vert \Psi \Vert_{L^\infty (\R^d)} .$$ (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:27:14.774500+00:00","domain":"probability theory","id":"claim_3c506c7fbe594eba4fc073993cb5abd00ad8c2d6f0964ea9ccf4c3a9d7bc6b3e","kind":"concept","schema_version":1,"statement":"[Proposition 7 of arXiv:2608.22746, 'Generative Neural Networks for Sinkhorn Distributionally Robust Hypothesis Testing'] Let $\mathbb{P}$ and $\mathbb{Q}$ be probability measures with finite second moments. The strong dual formulation of Sinkhorn discrepancy $\mathcal{S}_{\Reg}(\mathbb{P}, \mathbb{Q})$ is given by 
\begin{equation} \nonumber
    \sup_{f \in L^1(\mathbb{P}), g \in L^1(\mathbb{Q})} \quad \Big\{ \int f(\boldsymbol{x}) \ \diff \mathbb{P}(\boldsymbol{x}) + \int g(\boldsymbol{z}) \ \diff \mathbb{Q} (\boldsymbol{z}) - \Reg \iint \left[\exp \Big (\frac{f(\boldsymbol{x})+g(\boldsymbol{z}) -  c(\boldsymbol{x}, \boldsymbol{z})}{\Reg} \Big)-1 \right] \diff \mathbb{P}(\boldsymbol{x}) \diff \mathbb{Q}(\boldsymbol{z}) \Big\}, 
\end{equation}
Let $f_{\Reg}$ and $g_{\Reg}$ be the solutions of the dual formulation, which is also known as optimal entropic potentials. Then the transport plan 
\begin{equation} \nonumber
    \gamma_{\Reg}(\diff \boldsymbol{x}, \diff \boldsymbol{z}) = \exp\left(\frac{f_{\Reg}(\boldsymbol{x})+g_{\Reg}(\boldsymbol{z}) -  c(\boldsymbol{x}, \boldsymbol{z})}{\Reg}\right) \diff \mathbb{P}(\boldsymbol{x}) \diff \mathbb{Q}(\boldsymbol{z})
\end{equation}
is the unique solution to the Sinkhorn discrepancy, and the optimal entropic potentials satisfy
\begin{subequations}
    \begin{equation}
        \int \exp\left(\frac{f_{\Reg}(\boldsymbol{x})+g_{\Reg}(\boldsymbol{z}) - c(\boldsymbol{x}, \boldsymbol{z})}{\Reg}\right) \diff \mathbb{P}(\boldsymbol{x}) = 1, \quad \forall \boldsymbol{z} \in \Omega, 
    \end{equation}
    \begin{equation}
        \int \exp\left(\frac{f_{\Reg}(\boldsymbol{x})+g_{\Reg}(\boldsymbol{z}) -  c(\boldsymbol{x}, \boldsymbol{z})}{\Reg}\right) \diff \mathbb{Q}(\boldsymbol{z}) = 1, \quad \forall \boldsymbol{x} \in \Omega, 
    \end{equation}
\end{subequations}
for $\mathbb{Q}$-almost every $\boldsymbol{z}$ and $\mathbb{P}$-almost every $\boldsymbol{x}$, respectively. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

