{"assumptions":[],"created_at":"2026-10-27T12:22:01.663299+00:00","domain":"probability theory","id":"claim_3cf13d5846e1c66b41c9b5371d737cd5285cc8bf9d66dd5fe8379ed659993627","kind":"lemma","schema_version":1,"statement":"[Lemma LM1 of arXiv:2604.06012, 'Large fringe trees for random trees with given vertex degrees'] Assume Conditions~(Condition1 of the paper) and (Cond2 of the paper), and that the limit
  distribution $\mathbf{p}$ is nonlattice.
Let $m_\kappa$, $\kappa\geqslant1$, be integers with $1\leqslant m_\kappa\leqslant|{\mathbf{n}_\kappa}|$
such that $m_\kappa\to\infty$ and  $|{\mathbf{n}_\kappa}|-m_\kappa\to\infty$
as \ensuremath{{\kappa\to\infty}}.
Then, as \ensuremath{{\kappa\to\infty}},
\begin{align}
\operatorname{\mathbb E{}} [N_{m_\kappa}({\mathcal T}_{{\mathbf{n}_\kappa}})] 
\sim \frac{|{\mathbf{n}_\kappa}|}
  {\sqrt{2\pi}\sigma_\mathbf{p} (1-\frac{m_\kappa}{|{\mathbf{n}_\kappa}|})\strut^{1/2} m_\kappa^{3/2}}
.\end{align}
Consequently,
\begin{romenumerate}
\par
 \refstepcounter{thmenumerate}\textup{(\roman{thmenumerate})\enspace} 
If\/ $m_\kappa\ll |{\mathbf{n}_\kappa}|^{2/3}$, then $\operatorname{\mathbb E{}} [N_{m_\kappa}({\mathcal T}_{{\mathbf{n}_\kappa}})] \to\infty$.
\par
 \refstepcounter{thmenumerate}\textup{(\roman{thmenumerate})\enspace} 
If\/ $m_\kappa\sim a |{\mathbf{n}_\kappa}|^{2/3}$ for some constant $0<a<\infty$, 
then $\operatorname{\mathbb E{}} [N_{m_\kappa}({\mathcal T}_{{\mathbf{n}_\kappa}})] \to (2\pi\sigma_\mathbf{p}^2 a^3)^{-1/2}$.
\par
 \refstepcounter{thmenumerate}\textup{(\roman{thmenumerate})\enspace} 
If\/ $m_\kappa\gg |{\mathbf{n}_\kappa}|^{2/3}$, then $\operatorname{\mathbb E{}} [N_{m_\kappa}({\mathcal T}_{{\mathbf{n}_\kappa}})] \to0$.
\end{romenumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:42:08.397295+00:00","domain":"probability theory","id":"claim_3cf1d89de226092e5a8a711570fdbbea563ab0150ec06726b3210e6f75214eb8","kind":"concept","schema_version":1,"statement":"[Corollary C: distributional limit of arXiv:2511.11036, 'Analysis of a class of Recursive Distributional Equations Including the Resistance of the '] Assume that $p = 1/2$, $\mathbf{P}\{ f_{+},f_{-} \in \mathcal{S} \} = 1$, and (equation E: decay one of the paper) holds, and let $\{X^{(n)}\}$ be a solution of the RDE (equation E: main RDE of the paper) with an arbitrary initial distribution. 
		\begin{itemize}
			\item[(i)] The sequence $\{ N^{-1/2} X^{(N)}\}$ has the following distributional limit:
				\begin{align*}
					-\frac{ \text{sgn} ( \sigma ) }{ 2 \sqrt{ N } } X^{(N)} \overset{d}{\to} \sqrt{|\sigma|} \text{Beta}(2,1),
				\end{align*}
			where $\sqrt{|\sigma|} \text{Beta}(2,1)$ denotes a $\text{Beta}(2,1)$ random variable dilated by a factor $\sqrt{|\sigma|}$.  In particular, if $\sigma = 0$, then the limit is zero.
			\item[(ii)] Under the stronger assumption (equation E: decay two of the paper), if $\sigma = 0$ and $a > 0$, then $\{ N^{-1/3} X^{(N)} \}$ instead has a nontrivial distributional limit:
				\begin{align*}
					\frac{ 1 }{ (36 a)^{\frac{1}{3}} N^{\frac{1}{3}} } X^{(N)} + \frac{1}{2} \overset{d}{\to} \text{Beta}(2,2)
				\end{align*}
			\item[(iii)] Under (equation E: decay two of the paper), if $\sigma = a = 0$, then $\mathbf{P} \{ f_{+} = f_{-} = 0\} = 1$ and $\{ X^{(n)} \}$ is the constant sequence $X^{(n)} \overset{d}{=} X^{(0)}$.
		\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:05:37.773745+00:00","domain":"probability theory","id":"claim_3cf22b265d7a21b1c3b42975a6cb489bf3ffb76a67dab1759b2b229692e75330","kind":"definition","schema_version":1,"statement":"[Definition def: good_vertex of arXiv:2608.00399, 'The Heavy-tailed Frog Model'] Let $B$ be a finite subset of $\mathbb Z^d$ or $\mathbb{T}^d_L$ and $x \in B$. We say $x$ is a \textbf{good} (or $(B, \lambda, \ell)$-\textbf{good}) vertex in $B$ if
\begin{align*}
    |\widehat{\mathcal{A}}_x^{\lambda, \ell, B}| \ge \frac{|B|}{4}.
\end{align*}
We denote the set of $(B, \lambda, \ell)$-good vertices by $\mathrm{Good}_{B}^{\lambda, \ell}$.","status":"unverified"}

