{"assumptions":[],"created_at":"2026-10-26T19:46:12.282790+00:00","domain":"probability theory","id":"claim_3d4234f97868bef464d884e9919014315bc63f19978a361f9215da9161976885","kind":"lemma","schema_version":1,"statement":"[Lemma 24 of arXiv:2604.22567, 'Sign-balance of random Laplace eigenfunctions'] \begin{enumerate}[i.]

\item Let $r,R >0$ be two numbers so that $r<R$, and $\xi\in \R^{d}$ so that $\|\xi\|=R$. Then, uniformly for $y\in B_{r}(0)\subseteq\R^{d}$, one has
\begin{equation}

d_{2}(\xi,y) = R-\frac{1}{R}\langle \xi,y\rangle + O\Big( \frac{r^{2}}{R}  \Big),
\end{equation}
where $d_{2}(\cdot,\cdot)$ is the standard Euclidean distance in $\R^{d}$.

\item Let $x\in\Mcc$, and $r,\widetilde{r}\in (0,\inj(\Mcc))$ two radii below the injectivity radius of $\Mcc$, so that $\widetilde{r}>2r$. Let
$v\in \Sc^{1}\subseteq \R^{d}$ be a unit vector, and $\xi=\exp_{x}(\widetilde{r}\cdot v)$. Then, uniformly on the ball $w\in B_{r}(0)\subseteq T_{x}(\Mcc)$ in the tangent space, one has
\begin{equation}

d(\xi,\exp_{x}(w)) = \widetilde{r}-\langle w,v\rangle + O\Big(\frac{r^{2}}{\widetilde{r}}  \Big).
\end{equation} 

\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:54:18.299263+00:00","domain":"probability theory","id":"claim_3d477f731d56232e90d90c53bf5d6ada032d12aabd12da4b483535c7d268c44f","kind":"theorem","schema_version":1,"statement":"[Prop prop_iii of arXiv:2608.30382, 'Convergence rates for the RMSprop optimizer with full control of the hyperparameters'] Let $\beta\in[ \nicefrac{1}{2}, 1 ) $,
$ \varepsilon \in [0,\infty) $,
$ i \in \{ 1, 2, \dots, d \} $,
$ n \in {\mathbb N} \backslash \{ 1 \} $,
let $ A_n \in \mathcal F_{ n - 1 } $,
and let $ C_X^{ (3) } , C_v^{ (-3) } \in (0,\infty) $.
Assume that
\bas{
  {\mathbb E}\bigl[
    | X^{(i)}(\theta_{n-1},U_n) |^3
    |
    \mathcal F_{ n - 1 }
  \bigr]
  \le C_X^{ (3) }
\qquad\text{on }A_n
}
and
\bas{

  {\mathbb E}[ \1_{ A_n }( v_{ n - 1 }^{ (i) } )^{ - 3 } ]
  \le C_v^{ ( - 3 ) }
  .
}
The negative-moment assumption implies that $v_{n-1}^{(i)}>0$ almost surely
on $A_n$. If $\varepsilon=0$, the conditional covariances in the conclusion are
therefore evaluated on $A_n$ and extended by zero to $ \Omega \backslash A_n $.
Then one has
\bas{

  {\mathbb E}\Bigl[
    \1_{A_n}\mathrm{cov}((\sqrt{v_n^{(i)}}+\varepsilon)^{-1},
    X^{(i)}(\theta_{n-1},U_n)|\mathcal F_{n-1})^2
  \Bigr]^{1/2}
  \le
  4 C_X^{(3)} (C_v^{(-3)})^{1/2}\,\frac{1-\beta}{1-\beta^{n-1}}.
}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:54:10.976768+00:00","domain":"probability theory","id":"claim_3d47c5112f2e7a79683bf587eac2dac2e96e5c111b98c6b1cd7e14f8d2532abf","kind":"concept","schema_version":1,"statement":"[Proposition 33 (Inequalities at level $p^\dagger$) of arXiv:2606.13648, 'Stochastic dominations for FK percolation and sharp thinning thresholds for the Ising ener'] Take $J \in (\R^+)^E$ and $p^\dagger=p^\dagger(J)=1-e^{-4J}$. Then \begin{itemize}
