{"assumptions":[],"created_at":"2026-10-27T05:50:44.875617+00:00","domain":"probability theory","id":"claim_3d4e6cfe6cb3793710ad23020194f2222ed2973dae715fcd33eda4426c5078ee","kind":"theorem","schema_version":1,"statement":"[Theorem 52 (Multilinear group-dual Wick transfer) of arXiv:2607.16724, 'Algebraic Transfer for Operator-Valued Gaussian Chaoses: Oriented Schatten Profiles and Si'] Assume \eqref{eq:group-growth}, fix $m\ge1$ and $1\le r<\infty$, and
suppose
\begin{equation}

 a>0,\qquad b>0,\qquad a+b>\frac Dr.
\end{equation}
For finitely supported $c_1,\ldots,c_m$, set
\begin{align}

 \mathcal M_m^{a,b}(c_1,\ldots,c_m)
 &:=
 \Lambda^{-a}
 \sum_{x_1,\ldots,x_m\in\Gamma}
 \wick{g_{x_1}\cdots g_{x_m}}
 \left(\prod_{j=1}^mc_{j,x_j}\right)
 \lambda_{x_1\cdots x_m}
 \Lambda^{-b}.
\end{align}
For every $1\le p<\infty$, this assignment extends uniquely to a bounded
$m$-linear map
\[
 \mathcal M_m^{a,b}:
 \ell^2(\Gamma)^m
 \longrightarrow L^p(\Omega;\Sch_r(\ell^2(\Gamma))),
\]
and
\begin{equation}

 \norm{\mathcal M_m^{a,b}(c_1,\ldots,c_m)}_{L^p(\Omega;\Sch_r)}
 \le C_{\Gamma,D,a,b,m,r}(p+r)^{m/2}
      \prod_{j=1}^m\norm{c_j}_{\ell^2}.
\end{equation}
The extensions for different values of $p$ agree as random operators.  Set
$A(\mathbf c):=\prod_{j=1}^m\norm{c_j}_{\ell^2}$.  Moreover, for every
$t\ge1$,
\begin{equation}

 \Prob\!\left(
  \norm{\mathcal M_m^{a,b}(c_1,\ldots,c_m)}_{\Sch_r}
  > \mathrm e\,C_{\Gamma,D,a,b,m,r}(t+r)^{m/2}A(\mathbf c)
 \right)
 \le \mathrm e^{-t}.
\end{equation}
Thus arbitrary finite-support approximations on the fixed isonormal process
converge to the same limit.  In particular, with
\begin{equation}

 T_{m,N}^{a,b}(c)
 :=\Lambda^{-a}\Phi_{m,N}(c)\Lambda^{-b},
\end{equation}
one has
\[
 T_{m,N}^{a,b}(c)\longrightarrow
 T_m^{a,b}(c):=\mathcal M_m^{a,b}(c,\ldots,c)
\quad\text{in }L^p(\Omega;\Sch_r)
\]
for every $c\in\ell^2(\Gamma)$ and every $1\le p<\infty$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:12:20.541503+00:00","domain":"probability theory","id":"claim_3d4fe0936222f0d81d6727fe51f8b2390123beb8c8822ae688f2b023afacf0ab","kind":"concept","schema_version":1,"statement":"[Proposition prop:turning_point of arXiv:2603.27906, 'Marked GUE-corners process in doubly periodic dimer models'] For~$k=1,\dots,\ell$, set~$a_k=\alpha_k\beta_{k-1}^{-1}$ and~$b_k=\alpha_k^{-1}\beta_k$. Then
