	\mathbb{S}  = \mathbb{S}(\omega, N) := \{z = a + \ii b \in \mathbb{C}: \left\lverta\right\rvert \leq \omega^{-1}, N^{-1 + \omega} \leq b \leq \omega^{-1}  \}.
