    \|F\|_{\widetilde{\mathcal{H}}_{\gamma_2}}
    \leq
    \|F\|_{\widetilde{\mathcal{H}}_{\gamma_1}},
    \qquad F\in\widetilde{\mathcal{H}}_{\gamma_1},
    \]
    and $\widetilde{\mathcal{H}}_{\gamma_1}$ is dense in $\widetilde{\mathcal{H}}_{\gamma_2}$.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:25:06.115995+00:00","domain":"probability theory","id":"claim_3db2702a6fadf88bd10df3254912034907e67127d15ee9bb2991aa941a5d12f2","kind":"concept","schema_version":1,"statement":"[Theorem 9 (Finite positive planar rays) of arXiv:2608.22334, 'Recovering Weighted Tangent Geometry from a Single-Scale Score Field'] Let $D=2,d=1$, and suppose $\Lambda$ contains $s\leq K$ distinct positive
rays.  The reconstructed unit-mean shell density $h$ has Fourier modes
\begin{equation}
 h_k=\rho_{|k|}(R)m_k,\qquad
 m_k=\sum_{j=1}^{s}w_je^{-ik\theta_j},\qquad
 \rho_k(R)=\frac{\kappa_k(1,R)}{\kappa_0(1,R)}>0.

