	\begin{align}
		(\nu_{n}(\pi))^2:=&\Var\mathopen{}\mathclose\bgroup\originalleft(\cocc(\pi,\sigma_n)\aftergroup\egroup\originalright)\notag\\
  =&\sum_{i=0}^{n-k}\mathopen{}\mathclose\bgroup\originalleft(p\mathopen{}\mathclose\bgroup\originalleft(\theta_{i+\pi^{-1}(1)},\dots, \theta_{i+\pi^{-1}(k)}\aftergroup\egroup\originalright)-p\mathopen{}\mathclose\bgroup\originalleft(\theta_{i+\pi^{-1}(1)},\dots, \theta_{i+\pi^{-1}(k)}\aftergroup\egroup\originalright)^2\aftergroup\egroup\originalright)\notag\\
