{"assumptions":[],"created_at":"2026-10-26T19:31:20.883220+00:00","domain":"probability theory","id":"claim_3deb464d00ba380ba0cf2f424aa3e8df62c3a33de80095e8a0bb568b4babe167","kind":"definition","schema_version":1,"statement":"[Definition 1 of arXiv:2506.11918, 'Central limit theorems for the Euler characteristic in the Random Connection Model for hig'] [Simplex functions and integral representations] 
Let $K$ be a simplicial complex with $\dim(K)\leq\alpha$ on the vertex set $\{1,\dots,r\}$ for some $r\in\N$.
\begin{enumerate}
\item Define the simplex function of $K$ by
\begin{align*}
f_K: \X^r \rightarrow [0,1], \qquad f_K(x_1,\dots,x_r):= \prod_{\sigma\in K} \; \varphi_{|\sigma|-1} (x_\sigma),
\end{align*}
where $\varphi_{|\sigma|-1} (x_\sigma)$ denotes the value of $\varphi_{|\sigma|-1}$ evaluated at the points $\{ x_i\,|\, i\in \sigma\}$.
\item The integral representation $I_K$ of $K$ (over an observation window $W$) is defined by
\begin{align*}
I_K(W) \,:=\, \int_{W^r} f_K(x_1,\dots,x_r) \;\; \lambda^r \, (\d {(x_1,\dots,x_r)}).
\end{align*}
We call $K$ the simplicial complex associated to $I_K$.
\item For $m,l\in\{1,\dots,\alpha+1\}$ and $\max\{m,l\}\leq r\leq m+l$, we consider the simplicial complex
\begin{align} 
K_{m,l}^r \,:=\, \Big\langle [1,\dots,m], [1,\dots,m+l-r,m+1,\dots,r] \Big\rangle
\end{align}
on the vertex set $\{1,\dots,r\}$, which is generated by a $(m-1)$-simplex and a $(l-1)$-simplex sharing $m+l-r$ vertices.
Moreover, we denote by $\kappa_{m,l}^r$ the simplex function and by $\z m l r$ the integral representation of $K_{m,l}^r$, which means
\begin{align*}
\z m l r (W) \,:=\, \int_{W^r} \kappa_{m,l}^r(x_1,\dots,x_r) \;\; \lambda^r \, (\d {(x_1,\dots,x_r)}).
\end{align*}
Finally, let $\kappa_m:=\kappa_{m+1,m+1}^{m+1}$ be the simplex function of a simplicial complex generated by an $m$-simplex.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:56:17.353476+00:00","domain":"probability theory","id":"claim_3defd2c6e3bc0b6fa8914b55b686fe689bf88a291bfc053edbbe0d562c5be429","kind":"lemma","schema_version":1,"statement":"[Lemma lem.updet.upperbound of arXiv:2605.14149, 'The mean-field limit of online stochastic vector balancing'] The function $\mathcal{U}_p^{\mathrm{det}}$ is continuous on $[0,1) \times \mathcal{P}_p({\mathbb R})$. For each $t \in [0,1]$ and $m \in \mathcal{P}({\mathbb R})$ with bounded support, we have
    \begin{align} 
        \mathcal{U}_p^{\mathrm{det}}(t,m) \leq [m]_{\infty}.
    \end{align}
    Moreover, for each $q > p$, $t \in [0,1)$ and $m \in \mathcal{P}_q({\mathbb R})$, we have
    \begin{align} 
    \mathcal{U}_p^{\mathrm{det}}(t,m) \leq C (1-t)^{-p/(q-p)} \Big(\int_{\mathbb R} |x|^q\,m(dx)\Big)^{1/(q-p)},  
    \end{align}
    where $C=C(p,q)$ is a constant depending only on $p$ and $q$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:09:34.438823+00:00","domain":"probability theory","id":"claim_3df061ca280a6b789f43692f9d97d9bbfe55852f7ac2205e96a075316e5740b1","kind":"lemma","schema_version":1,"statement":"[Lemma lem: QV of arXiv:2505.05921, 'Limit Theorems for step reinforced random walks\\ with regularly varying memory'] {}
    Let $\{S_n\}_{n\geq 0}$ be the SRRW-RVM, with mean zero and unit variance innovation sequence. Then we have:
    \begin{enumerate}
        \item  For $p\in [0, \widehat p)$, the quadratic variation process for each $t\ge0$, satisfies
        \[
        \langle \overline{\boldsymbol{T}} \rangle_{n, {\lfloor nt \rfloor}}
        \to_{L^1} \boldsymbol{\overline{W}}(t) := \frac{1}{( p(\gamma+1)-\gamma )^2}\begin{pmatrix}
        \gamma^2t & \frac{\gamma t^{(1-p)(\gamma+1)}}{1-p}\\
        \frac{\gamma t^{(1-p)(\gamma+1)}}{1-p} & \frac{(\gamma+1)^2t^{2(1-p)(\gamma+1)-1}}{2(1-p)(\gamma+1)-1}
    \end{pmatrix},
        \]
        with $\overline{\boldsymbol{W}}(t)$ positive definite for $t>0$, $\overline{\boldsymbol{W}}(0)=\boldsymbol{0}$. 
        \item  For $p\in(\widehat p, p_c)$, the quadratic variation process for each $t\ge 0$, satisfies
        \[
        \langle \boldsymbol{T} \rangle_{n, {\lfloor nt \rfloor}}
        \to_{L^1}\boldsymbol{W}(t):=\frac{1}{(p(\gamma+1)-\gamma)^2}
        \begin{pmatrix}
        \gamma^2t & -\frac{\gamma t^{(1-p)(\gamma+1)}}{1-p}\\
        -\frac{\gamma t^{(1-p)(\gamma+1)}}{1-p} & \frac{(\gamma+1)^2t^{2(1-p)(\gamma+1)-1}}{2(1-p)(\gamma+1)-1}
    \end{pmatrix},
        \]
        with $\boldsymbol{W}(t)$ positive definite for $t>0$, $\boldsymbol{W}(0)=\boldsymbol{0}$.
        \item   For $p=\widehat p$, the quadratic variation process for each $t\ge 0$, satisfies
        \[
        \langle \widetilde{\boldsymbol{T}} \rangle_{n, {\lfloor nt \rfloor}}
        \to_{L^1} \widetilde{\boldsymbol{W}}(t),\] where $\boldsymbol{\widetilde{W}}(0)=\boldsymbol{0}$, and for $t>0$,$\boldsymbol{\widetilde{W}}(t)$ is a positive definite matrix given by
        \[ \widetilde{\boldsymbol{W}}(t):=t\begin{pmatrix}
        \gamma^2+(\gamma+1-\gamma\log t)^2 & \gamma+1-\gamma\log t\\
        \gamma+1-\gamma\log t & 1
    \end{pmatrix}.
        \]
    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:54:28.055829+00:00","domain":"probability theory","id":"claim_3df2dad0ed5c77775922dfc1e74288aff0361c882369667a1b600e3a27ad6e2f","kind":"concept","schema_version":1,"statement":"[Theorem thm:generic_bound of arXiv:2608.12056, 'Deviation inequalities for U-processes of growing order, with applications to half-space d'] Let $j\in N$ and assume that $\{X_t, t \in T\}$ is a $\psi_{2/j}$ process. Then for any $t_0 \in T$ and integer $p \geq 2$, \begin{multline}

