{"assumptions":[],"created_at":"2026-10-27T10:58:44.402511+00:00","domain":"probability theory","id":"claim_3e0f6b5cd47a9ce3db8cdb9056bff87d4ae0ed3ca8e2b50db03221da6eb0ffbf","kind":"definition","schema_version":1,"statement":"[Definition 1 of arXiv:2609.02842, 'Global Well-posedness and Asymptotic Analysis of a Damped Nonlinear Wave Equation with a C'] Let us fix $p$ as in \eqref{eqn-restriction}. 	Let $T>0$ and let
		\begin{equation*}
			\vartheta_0\in D(\A)\cap\mathcal{M},\ 
			\vartheta_1\in H_0^1(\varOmega)\ \text{ and }\ 
			(\vartheta_0,\vartheta_1)_{L^2(\varOmega)}=0.
		\end{equation*}
		Then a function
		\begin{equation*}
			\vartheta\in C([0,T]; H^1_0(\varOmega)\cap \bM) \cap C_w([0,T]; D(\A)),
		\end{equation*}
		with 
		\begin{equation*}
			\vartheta_t\in C([0,T];L^2(\varOmega))
			\cap C_w([0,T];H_0^1(\varOmega)),
		\end{equation*}
		is called \emph{strong solution} if it satisfies the following:
		\begin{itemize}
			\item $\vartheta_{tt}\in L^\infty(0,T;L^2(\varOmega))$ and	$\N(\vartheta,\vartheta_t)\in L^\infty(0,T;L^2(\varOmega)),$
			where
			\begin{equation*}
				\N(\vartheta,\vartheta_t)=
				-\A\vartheta-|\vartheta|^{p-2}\vartheta-\g \vartheta_t
				+\left(\|\nabla\vartheta\|_{L^2(\varOmega)}^2+\|\vartheta\|_{L^p(\varOmega)}^p-\|\vartheta_t\|_{L^2(\varOmega)}^2\right)\vartheta .
			\end{equation*}
			\item $\vartheta_{tt}=\N(\vartheta,\vartheta_t)  \ \text{ in }\   L^2(\varOmega)\ \text{ for a.e. }\ t\in (0,T).$\vspace{0.2cm}
			\item The initial conditions hold:
			\begin{equation*}
				\vartheta(0)=\vartheta_0\ \text{ in }\ D(\A),\ 
				\vartheta_t(0)=\vartheta_1\ \text{ in }\ H^1_0(\varOmega).
			\end{equation*}
		\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:56:36.587616+00:00","domain":"probability theory","id":"claim_3e0fc4a81195dcf29b984be9535b2290361bce4bbbbabba16473267ee8e78a68","kind":"theorem","schema_version":1,"statement":"[Thm subcor of arXiv:2608.30518, 'Grow-up rates of inhomogeneous semilinear heat equations in the critical dimension'] There exists $\underline{T}>0$ such that
