{"assumptions":[],"created_at":"2026-10-26T19:51:12.745904+00:00","domain":"probability theory","id":"claim_3fd9b196a4cebb1d374b607804b0faee6678dba2edef7319ac733694cb7ce233","kind":"lemma","schema_version":1,"statement":"[Lemma 13 (Averaging principle 1) of arXiv:2605.02499, '2605.02499'] Let $\gs_0 \subseteq [N]$ and let $S\in \varSigma_{\gs_0}$ be a root-type configuration. Let $M_t$ denote the number of interactive neutral events in the quasi-AIG $\As^{-}_{[0,t]}(\gs_0)$ and let $\Gamma^{(i)}\in \{r,b\}^N$ be chosen uniformly across all configurations with exactly $i$ entries equal to $\mathrm{r}$ and $N-i$ equal to $\mathrm{b}$, as in Lemma \ref{pre-duality}. Then, for any $t \ge 0$, we have
\begin{align*}
\Pb\big(\Gamma^{(i)}\in\Ss(\As_{[0,t]}(\gs_0), S)\big)
=\Eb\bigg[
\frac{1}{2^{M_t}}
\sum_{\bs v \in \{\downarrow,\uparrow\}^{M_t}}
\Pb\Big(
\Gamma^{(i)} \in \Ss\big((\As^{-}_{[0,t]}(\gs_0), \bs v ), S\big)
\,\mid\, \sP^-
\Big)
\bigg].
\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:24:45.964107+00:00","domain":"probability theory","id":"claim_3fdce20642f90c6d222dba0b0768d0c4f51b5d9185d29e8933895be3fb0b1e27","kind":"theorem","schema_version":1,"statement":"[Corollary prop: block support of arXiv:2509.11384, 'The Horton-Strahler number of butterfly trees'] Let $\mathcal T_1,\mathcal T_2$ be binary trees each with $m$ nodes. Then 
\begin{equation}
	\operatorname{supp}(\operatorname{HS}(\mathcal T_1 \oplus \mathcal T_2)) =\operatorname{supp}(\operatorname{HS}(\mathcal T_1 \ominus \mathcal T_2))  = \{0,1,\ldots,\floor{\log_2(2m+1)}\}.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:07:56.712360+00:00","domain":"probability theory","id":"claim_3fdffa7709dd313c01b6c58e8760dc6e4c50158e0aaa258b65047fbec2be944c","kind":"concept","schema_version":1,"statement":"[Theorem The:main_result of arXiv:2411.04778, 'Coupling between Brownian motion and random walks on the infinite percolation cluster'] Fix  $d\geqslant 2$ and $\mathfrak{p} \in (\mathfrak{p}_c(d), 1]$. For almost every configuration $\omega\in \Omega$ and $y\in\mathscr{C}_\infty(\omega)$, we can construct a version of VSRW $(S_t)_{t \geqslant 0}$
		and Brownian motion $(\bar{B}_t)_{t \geqslant 0}$ with diffusive constant $\bar{\sigma}$ in the same probability space, both starting from $y$, such that for every $\delta >0$ and for all $T > \mathcal{T}_\delta(y)$, we have
		\begin{align}
			\mathbb{E}^\omega\Big[\sup_{t\in [0,T]} \vert S_t - \bar{B}_t \vert_2 \Big] \leqslant K T^{\frac{1}{3}+\delta},
		\end{align}
		where $K$ is a finite positive constant depending on $d, \mathfrak{p},\delta$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:48:24.303674+00:00","domain":"probability theory","id":"claim_3fe242883f5fa0d6354c3d9160309b771cb6c82eff38d77c81e03a713fca7796","kind":"concept","schema_version":1,"statement":"[Lemma Soft Local Times of arXiv:2605.26869, 'Law of Large Numbers for a random walk on dynamic environments with drift'] There exist constants $0 < \Cl{lower bound for t in sltc}, \Cl[c]{upper bound on t with epsilon in sltc}, \Cl[c]{prob bound for G in sltc}, \Cl{slt exp tightness} < \infty$ such that the following holds. Let $\rho \in (0,K)$ and $\varepsilon \in (0, (K-\rho \wedge \rho \wedge 1)$, and let $H, \ell, t \in \mathbb{N}$ be such that	$\Cr{lower bound for t in sltc}\ell ^2 < t < \frac{H}{2}$ and $(\rho + \varepsilon) \ell \sqrt{\frac{\log t}{t}} < \Cr{upper bound on t with epsilon in sltc} \varepsilon$. Then for all $z\in I_t$, 
		\begin{equation} 
		\begin{split}
			\left( \rho - \frac{\varepsilon}{2} \right) \left(1 + \Cr{slt exp tightness}\ell \sqrt{\frac{\log t}{t}} \right) \leq \mathbb{E}_{\mathbb{Q}} \left[ G_{\eta_0} (z) \right]; \\
			\mathbb{E}_{\mathbb{Q}} \left[ G_{\eta_0} (z) \right] \leq \left( \rho + \frac{\varepsilon}{2} \right) \left(1 + \Cr{slt exp tightness}\ell \sqrt{\frac{\log t}{t}} \right).
		\end{split}
		\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:32:58.301645+00:00","domain":"probability theory","id":"claim_3fe267919c680092f07ca34d3776a947c85af2281577bf0d6ca3c811b8a30db8","kind":"concept","schema_version":1,"statement":"[Theorem thm:HDL_energy of arXiv:2505.10256, 'Stochastic Oscillators out of equilibrium:\\ scaling limits and correlation estimates'] Assume that $ v_0, e_0\in C^\infty_b(\mathbb T)$ and that $e_0$ is positive. 
Let $\kappa=1$ and let $\{ ( v^N_t(x),e^N_t(x))\}_{t\ge 0, x\in\mathbb T_N}$ (resp. $\{ ( v(t,u), e(t,u))\}_{t\ge0 , u\in \mathbb T}$) be the unique solution of (equation eq:discrete_hdl of the paper) (resp. (equation eq:hdl of the paper)) with the following initial conditions: 
\begin{equation}

v^N_0(x) =  v_0(x/N), \quad
e^N_0(x)=e_0(x/N)
\end{equation}
and 
\begin{equation*}
v(0,u) =  v_0(u),\quad
e(0,u) = e_0(u). 
\end{equation*}
Let $\mu_N$ be a product measure defined by (equation eq:product_measure_associated_to_continuous_profile of the paper), and assume further that the sequence of measures $\{\mu_N\}_{N\in\mathbb N}$ satisfies (equation eq:assum_H-1norm of the paper) and (equation eq:assumption_initial_measure_correlation of the paper).
Then, there exists $C=C(T,v_0,e_0)>0$ such that 
\begin{equation}

\sup_{0\leq t\leq T}
\max_{x\in\mathbb T_N} 
\big| e^N_t(x)-e_t(x/N)\big| 
\le C\frac{\log N}{N}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:24:34.397752+00:00","domain":"probability theory","id":"claim_3fe3f8451fee7c549def362afa04de524290575210b0af37d99971dbb79a4916","kind":"lemma","schema_version":1,"statement":"[Lemma 19 of arXiv:2608.31008, 'Stability of gravitational instantons with a bounded Killing vector field'] Let $g$ be nonflat and suppose $K$ is a nonzero bounded Killing
field.  After multiplying $K$ by a nonzero constant,
\begin{equation}
 |\nabla_b^j(K-T)|_b=\mathcal O(r^{-1-j}),\qquad j\geqslant0.
\end{equation}
In particular,
$|\nabla_b^j(V-1)|_b=\mathcal O(r^{-1-j})$ for $j\geqslant0$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:21:52.423685+00:00","domain":"probability theory","id":"claim_3fea6f85b74b6e620983d54ae02237fcd7f2f4de077bb24dc1bd0bbacfb953ac","kind":"concept","schema_version":1,"statement":"[Theorem 146 of arXiv:2601.16377, '2601.16377'] Consider a family of discrete ensembles with $H=1$ parameterized by $\boldsymbol{t} = (\hat{a},\hat{b},\hat{n})$ in some open set of $\amsmathbb{R}^3$, where $[\hat{a},\hat{b}]$ represents the defining segment and $\hat{n}$ the segment filling fraction. We suppose that the weights satisfy Assumption~\ref{Assumptions_analyticity} with integers $\iota^{\pm}$ and complex domain $\amsmathbb{M}$ independent of $\boldsymbol{t}$ while the regular part of the potential $U(z)$ and the parameters $\rho_j^{\pm}$ for $j \in [\iota^{\pm}]$ are twice-continuously differentiable with respect to $\boldsymbol{t}$ for any $z \in \amsmathbb{M}$ --- with partial derivatives up to order $2$ which are holomorphic functions of $z \in \amsmathbb{M}$. Assume that the discrete ensemble for $\boldsymbol{t}^0$ satisfies Assumptions~\ref{Assumptions_Theta}, \ref{Assumptions_basic}, \ref{Assumptions_offcrit}, \ref{Assumptions_analyticity} and that the equilibrium measure has a single band.

Then, there exists a constant $C > 0$ depending only on the constants in the assumptions, such that for any $\varepsilon > 0$ and for any $\boldsymbol{t}$ in the $\frac{1}{C}$-neighborhood of $\boldsymbol{t}^0$ and satisfying the integrality constraints \eqref{integra}, for $\N$ large enough in a way that depends only on $\varepsilon$ and $C$ we have
\begin{equation}

\Big|\log \Z_\N -\big( \I[\boldsymbol{\mu}]\N^2  + \theta \hat n\, \N \log \N + \mathbbm{Rest}_1 \N \big) \Big| \leq  \eps,
\end{equation}
and the absolute values of $\mathbbm{Rest}_1$ and its first and second partial derivatives with respect to $\boldsymbol{t}$ are bounded by $C$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:36:44.552816+00:00","domain":"probability theory","id":"claim_3ff3f070e2a8df03887b6b6cdc39c707d066f5775c0f3f91403974bc51f92dc8","kind":"concept","schema_version":1,"statement":"[Prop 4 (Phase-space constrained limits) of arXiv:2604.02129, 'Realisation of constraints in underdamped Langevin dynamics'] Given $\eps>0$, let $(Q_t,P_t)$ be the solution to~\eqref{eq:abc-slow},\eqref{eq:intro-Phase-Cons-Fast} with corresponding initial datum $(Q^i_0,P^i_0)$ for $i=1,2$.
    \begin{enumerate}[label=(\roman*)]
        \item 
        For any $t\geq 0$
        \begin{align}


             \max\biggl\{\E\Bigl[|Q^{1}_t|^2\Bigr] , \E\Bigl[ |P^{1}_t|^2\Bigr]\biggr\} &\leq C_1 \left(\eps +  e^{- \frac{t}{\eps} C_2} \Bigl(   \bigl|Q^{1}_0\bigr|^2+ \bigl|P^{1}_0\bigr|^2  \Bigr)\right), 
        \end{align}
        where $C_1, C_2>0$ are independent of $\eps$ and $r$. 


        \item Let $(q_t,p_t)\in \R^{2(d-k)}$ with initial data $(q_0,p_0)=(Q^2_0,P^2_0)$ evolve according to~\eqref{eq:limit-gen} with $\hat q=0 \in \R^k$. Recall the definition of the potential $V$ from~\eqref{eq:Valpha} and the parameter $\alpha\geq 0$. In general (i.e. for any $\alpha\geq 0$) we have 
        \begin{align}

            \mathbb{E} \biggl[ \sup_{t\in [0,T]}\left|\begin{pmatrix}
            q_t - Q^{2}_t \\ p_t-P^{2}_t  
            \end{pmatrix} \right|^2 \biggr] \leq 
            \begin{cases}
            C_3 e^{C_4  T} \Bigl( \eps T^2 + \eps T \Bigl( |Q_0^{1}|^2 +  |P_0^{1}|^2 \Bigr)\Bigr) \ \ &\text{if $\alpha=0$,}\\

            \eps C_5 \left( T + |Q^1_0|^2 + |P^1_0|^2 \right) &\text{if $\alpha>0$}.
            \end{cases}
        \end{align}
        In the case when $\alpha>0$ (i.e. $V$ has a quadratic part) and $\eps$ small enough we additionally have the uniform-in-time $L^1$- estimate
        \begin{align}
            \mathbb{E} \biggl[ \sup_{t \geq r}\left|\begin{pmatrix}
            q_t - Q^{2}_t \\ p_t-P^{2}_t  
            \end{pmatrix} \right| \biggr] \leq \sqrt{\eps} C_6  + 

            \eps C_7 e^{- C_8 r}\Bigl( |Q_0^{1}| +  |P_0^{1}| \Bigr)       
            \end{align}
        Here 

        the constants $C_i>0$ for $i\in \{3,\ldots,8\}$ are independent of $\eps>0$ and $T>0$.
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

