 \end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:34:09.926217+00:00","domain":"probability theory","id":"claim_405d0c60df5621691b32dc5a1b8dbdf0f9336b585ec060c4bf7527aacc64536f","kind":"concept","schema_version":1,"statement":"[Theorem 2 of arXiv:2603.27712, 'Bridging Schr\"odinger and Bass: A Semimartingale Optimal Transport Problem with Diffusion'] Let $\mu_0,\mu_T\in\Pc_2(\R^d)$. Then

\vspace{2mm}
\noindent {\rm (i)} ${\rm SBB}=\Vc=\bar\Vc=\Vc_{\rm red}\in[0,\infty)$ at $(\mu_0,\mu_T)$;

\vspace{2mm}
\noindent {\rm (ii)} Under the additional condition $\beta T>1$:
\begin{itemize}

\vspace{-2mm}
\item[{\rm (a)}] The reduced dual problem $\Vc_{\rm red}$ has a solution $\hat\phi\in \Cc^{\rm conv}_{w}$, which induces a solution $\hat\psi:=\mathbf{T}_\beta^+[\hat\phi]\in\bar\Cc^{\rm conc}$ of the dual problem $\bar\Vc$; 

\vspace{-2mm}
\item[{\rm (b)}] The primal problem {\rm SBB} has a solution $\hat\P\in\Pc(\mu_0,\mu_T)$;

\vspace{-2mm}
\item[{\rm (c)}] For all $t<T$, the map
$\msY_t:={\rm id}-\frac1\beta\nabla \mathbf{T}_\beta^+[u^{\hat\phi}_{T-t}]$
is a well-defined one-to-one map, and we denote its inverse by
$\msX_t:=\msY_t^{-1}$. At terminal time $t=T$, $\msY_T$ is understood as
the corresponding set-valued argmin map. Moreover, there exists a probability
measure $\hat\Q$ under which $Y$ is a Schr\"odinger bridge diffusion,

\vspace{-3mm}
\begin{equation}
Y_t = Y_0+\int_0^t \nabla u^{\hat\phi}_{T-s}(Y_s)\,\d s
+W_t^{\hat\Q},
\qquad 0\le t<T,
\end{equation}
\vspace{-3mm}

and the process $X_t:=\msX_t(Y_t)$, $0\le t<T$, admits a continuous
extension to $[0,T]$ satisfying $\hat\P=\Law_{\hat\Q}(X)$.
Equivalently, if $\mathbf R$ denotes the Brownian law with initial distribution
$m_0:=\msY_0\#\mu_0$, then:

\vspace{-3mm}
\begin{equation}
\frac{d\hat\Q}{d\mathbf R}\Big|_{\Fc_t}
= e^{u^{\hat\phi}_{T-t}(Y_t)-u^{\hat\phi}_T(Y_0)}, \qquad 0\le t<T.
\end{equation}

\vspace{-3mm}
\item[{\rm (d)}] There exists a non-zero $\sigma$-finite measure $\nu_0$ such that, setting
$\nu_t=\Nc_t\!*\!\nu_0$ and $m_T:=e^{\hat\phi}\nu_T$, the dual optimiser
$\hat\phi$ is characterized by the SBB system

\vspace{-3mm}
\begin{equation}
\frac{\d\msY_0\#\mu_0}{\d\nu_0} = e^{u^{\hat\phi}_{T}},
\qquad
\mu_T=\msX_T\#m_T.
\end{equation}

\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:44:12.638773+00:00","domain":"probability theory","id":"claim_405fe0f380b30a4e2afcdc816b22ff587eb168ce3290459d80c51f00aba7b6c4","kind":"lemma","schema_version":1,"statement":"[Lemma lem:complex2-Rd of arXiv:2512.04371, 'Constructive Approximation under Carleman's Condition, \\ with Applications to Smoothed An'] For an $r$-strictly sub-exponential distribution $\mu$ on $\RR^d$ and $f\in A_{poly}(\RR^d)$, let $\varphi(\xi) = \cF[r_D\cdot \mu](\xi)$. 

Then we have for any $\xi \in \RR^d$ with $D > r (K\|\xi\|_2)^r$, that 
\begin{align}
  |\varphi(\xi)| \le  A \norm{r}_\mu \, \Big(\frac{er}{D}\Big)^{D/r} (K \|\xi\|_2)^{D}.
\end{align}
In addition, for any $v_1, v_2, \ldots, v_k\in \SS^{d-1}$ with $k \le D$, it holds that 
\begin{align}
\big|  \partial^k \varphi(\xi)[v_1, v_2, \ldots, v_k] \big|&\le \sqrt{A} \, \norm{r}_\mu \kappa_{4}(v_1,v_2,\ldots, v_k) \, \Big(\frac{er}{D-k}\Big)^{(D-k)/r} (2K\|\xi\|_2)^{D-k}, 
\end{align}
where $\kappa_{4}(v_1,v_2,\ldots, v_k) = \Big\|{\Big(\prod_{j=1}^k \dotp{v_j}{x}\Big)^2}\Big\|_\mu^{1/2}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:06:55.288722+00:00","domain":"probability theory","id":"claim_4065391dedf93a87e7c319cdd673d85b2a3baa27640593f02339bb03d923c0f5","kind":"definition","schema_version":1,"statement":"[Defi def:relEnt of arXiv:2602.17579, 'Non-equilibrium functional inequalities for finite Markov chains'] For $\varphi\in \mathcal D_\pi(\ensuremath{\mathbb{Z}})$ we define the \emph{relative entropy} and ($M$-)\emph{Fisher information} 
