 +\norm{\nabla f}_{H^{m-1}}\norm{\nabla g}_\infty\right).

\end{align}
If both $f$ and $g$ belong to $H^m$, the first estimate reduces to
\begin{equation}
 \norm{fg}_{H^m}\le C_m\left(
 \norm f_\infty\norm g_{H^m}+\norm g_\infty\norm f_{H^m}\right).

\end{equation}","status":"unverified"}

