{"assumptions":[],"created_at":"2026-10-27T21:28:49.112440+00:00","domain":"probability theory","id":"claim_4112b4724917011573474037e61e7d009d41e1de03298df75472b13180ffd916","kind":"theorem","schema_version":1,"statement":"[Theorem thm:weighted-nonlinear-wellposedness of arXiv:2608.16119, 'Fully nonlinear parabolic equations under a fixed reference diffusion: weighted \texorpdfs'] Let $\alpha\geq0$ and let $w$ be a regular weight of order $\alpha$.
Assume Assumptions~(ass:reference-diffusion of the paper) and
(ass:lipschitz-driver of the paper), and let $\psi\in H^1(\mu_T)$.  If $\psi$ is not
spatially constant, also assume Assumption~(ass:drift-multiplier of the paper).
Suppose further that
\begin{equation*}
 C_w(X)<\infty,\qquad \delta_{\mathrm{sg}}>0,
\end{equation*}
where the second condition is equivalent to $C_w(X)L_H<1$.
For $\kappa\geq1$, put
\begin{equation*}
 \begin{aligned}
 \operatorname{Lip}_\kappa:={}&e^{\operatorname{osc}_\alpha(w)/2}L_y\kappa^{-1}
 +e^{\operatorname{osc}_\alpha(w)/2}L_z\kappa^{-1/2}+L_H\left(C_{w_\kappa}(X)
 +\frac32\Lambda^2\lambda^{-5/2}M_1(a)
 e^{\operatorname{osc}_\alpha(w)/2}\kappa^{-1/2}\right).
 \end{aligned}
\end{equation*}
By causal monotonicity,
\begin{equation}
 \begin{aligned}
 \operatorname{Lip}_\kappa\leq{}&1-\delta_{\mathrm{sg}}
 +e^{\operatorname{osc}_\alpha(w)/2}\biggl[
 L_y\kappa^{-1}+\left(L_z+\frac32\Lambda^2\lambda^{-5/2}M_1(a)L_H\right)
 \kappa^{-1/2}\biggr].
 \end{aligned}

\end{equation}
Then there exists a unique order-$\alpha$ weighted Sobolev solution $u^*$.
Its source $F^*=F_{u^*}$ is the unique fixed point of $\mathfrak P_\psi$ and
$u^*=\mathcal U(F^*,\psi)$.  For every $\kappa\geq1$ such that
$\operatorname{Lip}_\kappa<1$ and
every $F^0\in L_\alpha^2$,
\begin{equation}
 \left\lVert F^n-F^*\right\rVert_{w_\kappa}
 \leq \operatorname{Lip}_\kappa^n\left\lVert F^0-F^*\right\rVert_{w_\kappa},\qquad n\geq0.

\end{equation}
There exists a constant
$C=C(T,\lambda,\Lambda,M_1(a),\operatorname{osc}_\alpha(w),C_w(X),
\mathbf L_f,\delta_{\mathrm{sg}}^{-1},\Lambda_b)>0$ such that, for
every such $\kappa$,
\begin{equation}
 \left\lVert F^*\right\rVert_{w_\kappa}
 \leq\frac{\left\lVert f_0\right\rVert_{w_\kappa}
       +CT^{\alpha/2}(L_y+L_z+L_H)
          \norm\psi_{H^1(\mu_T)}}{1-\operatorname{Lip}_\kappa}.

\end{equation}
The canonical estimate is
\begin{equation}
 \left\lVert F^*\right\rVert_\alpha+\sum_{j=0}^2\left\lVert D_x^ju^*\right\rVert_\alpha
 \leq C\left(\left\lVert f_0\right\rVert_\alpha
       +T^{\alpha/2}\norm\psi_{H^1(\mu_T)}\right).

\end{equation}
If $\psi$ is spatially constant, $C$ may be chosen without dependence on
$\Lambda_b$.
For every $s\in(0,T)$, the composition admits a continuous version on
$[s,T]$ satisfying
\begin{equation}
 u^*(t,X_t)
 =\mathbb E_t\left[\psi(X_T)+\int_t^TF^*(r,X_r)\,\mathrm d r\right],
 \qquad s\leq t\leq T.

\end{equation}","status":"unverified"}

