{"assumptions":[],"created_at":"2026-10-27T17:18:19.447296+00:00","domain":"probability theory","id":"claim_415427dcff23d09b487a79e8bc11f3df41f425b077af0129f27b25e7ab4cdd52","kind":"definition","schema_version":1,"statement":"[Definition def:Phi-Wishart of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] Denote
\begin{equation}
(\Phi_2)_{xx'} = \delta_{xx'}\sum_{y\in[M]}\bigl(|H_{xy}|^2-\mathbb{E}[|H_{xy}|^2]\bigr),
\quad
(\Phi_3)_{xx'} = -|H_{x x'}|^2\,H_{x x'},
\end{equation}
for $x,x'\in[N]$, and
\begin{equation}
(\Phi_2)_{yy'} = \delta_{yy'}\sum_{x\in[N]}\bigl(|H_{xy}|^2-\mathbb{E}[|H_{xy}|^2]\bigr),
\quad
(\Phi_3)_{yy'} = -|H_{y y'}|^2\,H^*_{y y'},
\end{equation}
for $y,y'\in[M]$.  In addition,
\begin{equation}
(\Phi_A)_{xy}=A_{xy},
\quad
(\Phi_{A^*})_{yx}=(A^*)_{yx}\end{equation}
For an insertion $\alpha \in \{2,3\}$ and $n \ge 0$, define
\begin{equation}
(\underline{\Phi_\alpha V_{n+\alpha}})_{v_0 v_{n+1}}
= \sum_{v_1,\dots,v_n}
\Biggl[\prod_{i=0}^{n-1} \mathbf{1}(v_i \neq v_{i+2}) \Biggr]
(\Phi_\alpha)_{v_0v_1} \,(Y)_{v_1v_2}\,(Y^*)_{v_2v_3}\,(Y)_{v_3v_4} \cdots (Y/Y^*)_{v_n v_{n+1}},
\end{equation}
where the product alternates between $Y$ and $Y^*$, and   $Y = H$ if $v_1 \in [N]$ and $Y = H^*$ if $v_1 \in [M]$.
For $\alpha\in \{A,A^*\}$, we define 
\begin{equation}
    \underline{\Phi_\alpha V_{n+1}}=\Phi_{\alpha}V_n.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:49:06.318383+00:00","domain":"probability theory","id":"claim_4154ec56ffcd0531f4c409d29e1bd6d6c461f139184240f8baf350c1a1ab3de3","kind":"theorem","schema_version":1,"statement":"[Proposition prop:fixeddriver of arXiv:2601.10359, 'An Operator It\^o Formula for Volterra Gaussian Processes:\\ The Intrinsic Bracket via Cau'] Let $M$ be a continuous square-integrable martingale with bracket measure $\mu$ (i.e., $\langle M\rangle_t = \int_0^t d\mu_s$). Let $K_1,K_2$ be two causal Volterra kernels such that the process $X_t := \int_0^t K_1(t,s)\,dM_s$ also satisfies
\begin{equation}
X_t = \int_0^t K_2(t,s)\,dM_s \quad \text{for all } t\in[0,T],\;\text{a.s.}
