{"assumptions":[],"created_at":"2026-10-27T09:15:16.648357+00:00","domain":"probability theory","id":"claim_41b946c8877c83d9c070145b7e9fede53dddeded75f9363bda90b4d242629e58","kind":"lemma","schema_version":1,"statement":"[Lemma 11 of arXiv:2608.30736, 'Stability results for distribution-dependent stochastic Volterra equations'] Let $f \colon [0,T] \times \bR^d \times \mathcal{P}_\eta(\bR^d) \to \bR^e$ be a function such that for all compact sets $\mathcal K \subset \bR^d$, $\bar{\mathcal K}\subset \mathcal{P}_\eta(\bR^d)$ and every $\epsilon >0$ there exists a $\delta >0$ such that
  \begin{equation*}
    |f(t,x,\mu)-f(t,y,\nu)|\leq \epsilon
  \end{equation*}
  for all $t \in [0,T]$, $x,y \in \mathcal K$ satisfying $|x-y| \leq \delta$, and $\mu, \nu \in \bar{\mathcal K}$ with $W_\eta(\mu,\nu)\leq \delta$. Let $(f_k)_{k \in \bN}$ be a sequence of functions such that $f_k \colon [0,T] \times \bR^d \times \mathcal{P}_\eta(\bR^d) \to \bR^e$ and
  \begin{equation*}
    |f(t,x,\mu)|+|f_k(t,x,\mu)|\leq C(1+|x|^2+W_\eta(\mu,\delta_0)^2), \quad x \in \bR^d, \, t \in [0,T], \,\mu \in \mathcal P_\eta(\bR^d),
  \end{equation*}
  for all $k \in \bN$ and for some $C>0$, and $f_k \to f$ locally uniformly.

  Let $K, K_k \colon \Delta_T \to \bR$, $k \in \bN$, be measurable functions and let $K$ be bounded in $L^1([0,T])$ uniformly in the second variable, i.e. $\sup_{t \in [0,T]} \int_0^t |K(s,t)| \dd s \leq M$ for some $M > 0$, and
  \begin{equation*}
    \sup_{t \in [0,T]} \int_0^t |K_k(s,t)-K(s,t)| \dd s \to 0 \quad\text{as } k \to \infty.
  \end{equation*}
  If $(X^k)_{k \in \bN}$ is a sequence of continuous stochastic processes such that $X^k \to X$ in $C([0,T]; \bR^d)$ as $k \to \infty$ $\bP$-a.s. and $(\L(X^k))_{k \in \bN} \subset \mathcal{P}_\eta(C([0,T];\bR^d))$, $\L(X)\in \mathcal{P}_\eta(C([0,T];\bR^d))$ such that $W_\eta(\L(X^k),\L(X)) \to 0$ as $k \to \infty$, then
  \begin{equation*}
    \int_0^{\cdot} K_k(s,\cdot) f_k(s,X^k_s,\L(X^k_s))\dd s \xrightarrow{\bP} \int_0^{\cdot} K(s,\cdot) f(s,X_s,\L(X_s))\dd s
  \end{equation*}
  with respect to $\|\cdot\|_\infty$ as $k \to \infty$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:07:17.279151+00:00","domain":"probability theory","id":"claim_41b9bafdc41193cf4c38bd85cf237c8112fe77d55aaefb0c2f5bca7bbb1c46d5","kind":"concept","schema_version":1,"statement":"[Prop eq:taum of arXiv:2603.21634, 'Individual-based stochastic model with unbounded growth, birth and death rates: a tightnes'] Under the \hyperlink{gen}{general setting}, we almost surely have
