{"assumptions":[],"created_at":"2026-10-27T21:28:49.057442+00:00","domain":"probability theory","id":"claim_41f9c590b6150ca3cf4a84ca180eca8616fb8694b19ab4965b4fcf6bdd62cb6b","kind":"definition","schema_version":1,"statement":"[Definition def:bochner-verification-class of arXiv:2608.16119, 'Fully nonlinear parabolic equations under a fixed reference diffusion: weighted \texorpdfs'] Let $I=(r_0,r_1)$ and let $w$ be a regular weight.  For a compact positive
strip $J=[s,r]\Subset I$, define the following joint Bochner energy:
\begin{align}
 \mathfrak B_{J,w}(q)
 :={}&\int_{J\times\mathbb R^d}w\Bigl(
       |D_t^cq|^2+|\Delta_{\mu,g}q|^2+|\operatorname{Hess}_gq|_g^2
+\bigl(1+|c|_g^2+|\nabla^g\log\varrho|_g^2
          +w^{-1}|\mathscr R_{w,t}|_g\bigr)|q|^2\notag \\
 &+\bigl(1+w^{-1}|\mathscr R_{w,t}|_g\bigr)
          |\nabla^gq|_g^2\Bigr)\,\mathrm d\mathfrak m
 +\sum_{t\in\{s,r\}}\int_{\mathbb R^d}
       \bigl(|q(t)|^2+|\nabla^{g_t}q(t)|_{g_t}^2\bigr)\,\mathrm d\mu_t.

\end{align}

The \emph{Bochner verification class} $\mathfrak C_{\rm B}(I,w)$ consists of
the fields $q=S_IF$, with $F\in L_w^2(I)$, such that
\begin{enumerate}[label=\textup{(\roman*)},leftmargin=2.5em]
\item $q$ vanishes on $(\tau,r_1)\times\mathbb R^d$ for some $\tau<r_1$;
\item $q\in W_{p,\mathrm{loc}}^{1,2}(I\times\mathbb R^d)$ for some $p>d+2$;
\item $\mathfrak B_{J,w}(q)<\infty$ for every compact positive strip
      $J\Subset I$.
\end{enumerate}
The corresponding source class is
\begin{equation*}
 \mathfrak D(I,w)
 :=\{F\in L_w^2(I):S_IF\in\mathfrak C_{\rm B}(I,w)\}.
\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:38:04.518589+00:00","domain":"probability theory","id":"claim_41fcec642d1ec1bab329c3dc70c6de0d5edf09e185c2c0e6af2c51d216b22068","kind":"concept","schema_version":1,"statement":"[Theorem Locality of arXiv:2607.18011, 'From local giants to locality in long-range percolation'] \thlabel{thm:lrp_locality}
    Let $G$ be a transitive graph of polynomial growth with $d \geq 2$, and suppose that $J : V \times V \to \mathbf{R}_+$ is a transitive kernel satisfying $J(x,y) = \Omega(d_G(x,y)^{-d \alpha})$ with $\alpha \in (0, 2)$. 

    Let $(G_n,J_n)_{n \in \mathbf{N}}$ be a sequence of transitive graphs and kernels converging locally to $(G,J)$ with $\liminf_{n \to \infty} \dim(G_n) \geq 2$.

    If $\alpha \leq 1$, or if $\alpha > 1$ and $(J_n)_{n \in \mathbf{N}}$ is uniformly integrable, then 

    \begin{equation}
        \lim_{n \to \infty}
        \beta_c(G_n,J_n) 
        =
        \beta_c(G,J).
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:52:17.367675+00:00","domain":"probability theory","id":"claim_41ffaf18f20b5f683ddfdf38949239faeec19369630a64013d8ccbdebc2691a0","kind":"concept","schema_version":1,"statement":"[Theorem 1 of arXiv:2606.03122, 'Propagation of support for super-Brownian motion with general branching mechanism'] Given a super-Brownian motion $X$ with a branching mechanism $\Psi$ satisfying Condition \ref{con_localize}, for any $\mu\in M_c$, $0<R_1<R$ and $0<t<\dfrac{R_1^2}{d}$, we have
$$
\begin{aligned}
&\mathbb{P}_\mu\left\{X_u\left((S(\mu)^R)^c\right) > 0 \text{ for some } u \leq t\right\} \\
&\quad \leq \mu(1) \cdot u_{R,\Phi_{\rho(\mu)+R}}(R_1) \cdot C(d) \left(\frac{R_1}{\sqrt{t}}\right)^{d-2} \exp\left(-\frac{R_1^2}{2t}\right) \\
&\quad \leq \mu(1) \cdot G_{\Phi_{\rho(\mu)+R}}^{-1}(R-R_1) \cdot C(d) \left(\frac{R_1}{\sqrt{t}}\right)^{d-2} \exp\left(-\frac{R_1^2}{2t}\right),
\end{aligned}
$$
where $C(d)$ is a constant depending only on dimension $d$, and $u_{R,\Phi_{\rho(\mu)+R}}$ denotes the unique radial classical solution of singular boundary value problem \eqref{SBVP} in $B(0,R)$ with $\Phi$ replaced by $\Phi_{\rho(\mu)+R}$. If $\Psi$ satisfies Condition \ref{con_general} with lower bound $\Phi$, then this estimate reduces to the same bound with $u_{R,\Phi_{\rho(\mu)+R}}$ and $G_{\Phi_{\rho(\mu)+R}}^{-1}$ replaced by $u_{R,\Phi}$ and $G_\Phi^{-1}$, respectively. In particular, the spatially constant case is obtained by taking $\Psi(x,u)=\Phi(u)$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

