{"assumptions":[],"created_at":"2026-10-26T19:42:47.772861+00:00","domain":"probability theory","id":"claim_422af0a52ef997ec183f20078c07c54b2de0c7d662bb84be3a2491be0ba564e9","kind":"definition","schema_version":1,"statement":"[Defn 21 (Weak solution in the frame of the free boundary) of arXiv:2604.12797, 'A free boundary problem for the mean-field limit of diffusing particles with nonlinear bou'] Let $(\mu_t)_{t\in[0,T]}$ be a measure flow such that $\mu_t\in \mathcal{M}_{\leq 1}(\R^+)$ and, for $t>0$, $\di \mu_t(x)=u_t(x)\dx$ with $u_t \in C(\R^+)$, where $u$ satisfies \begin{equation}
		\bigl\Vert u_t \bigr\Vert_2^2 \leq \frac{c_0}{\sqrt{t}}\quad \text{and}\quad |u_t(x)|\leq \frac{c_1}{\sqrt{t}}e^{-c_2x^2}, \quad x\in\R^+,\; t\in(0,T],
	\end{equation}
for some constants $c_0,c_1>0$. We say $\mu$ is a weak solution in the frame of the free boundary if
	\begin{align}
		\di \langle\mu_t,\phi\rangle	&=\langle\mu_{t},\tfrac{{1}}{2}\sigma_{A}(t,\cdot)^{2}\partial_{xx}\phi\rangle\dt+\langle\mu_{t}, (b_{A}(t,\cdot)-A^\prime_{t})\partial_{x}\phi\rangle\dt + \di Z^{\mu,\phi}_t,  \\
		 \di Z_t^{\mu, \phi}
		&=    \bigl(\tfrac{1}{2} \partial_x \phi(0) -  \gamma(t, C_t)\phi(0) \bigr) \sigma_A(t, 0)^2 u_t(0)  \dt, 
	\end{align}
	with $\mu_0 = P_0 \circ \theta^{-1}_{a_0}$ and $Z_0^{\mu}=0$, for all $t\in[0,T]$ and $\phi \in C^{\infty}_b(\R)$, where
	\begin{equation}
		A_t=a_0 + \alpha \! \displaystyle \int_{t-\bar{d}}^{t}\varrho(t-s)I_{s} \ds, \;\;
		C_t = \!\int_{t-\bar{d}}^{t}\varrho(t-s)(I_{s}-I_{s-\bar{d}}) \ds, \;\;  I_t= 1- \mu_t(\R^+).
	\end{equation}","status":"unverified"}

