			&\frac{\mathrm{d}^{2\alpha}}{\mathrm{d}t^{2\alpha}}\bar{p}_{\alpha}(m,t)+2\lambda\frac{\mathrm{d}^{\alpha}}{\mathrm{d}t^{\alpha}}\bar{p}_{\alpha}(m,t)=-\lambda^{2}\Big(\bar{p}_{\alpha}(m,t)-\sum_{j=1}^m{\Pr}\{X_1 = j\}\bar{p}_\alpha(m-j,t)\Big), \text{ for $m \ge 1$ }.
