\end{align*}
and
\begin{align}
& \left[V_{1}, V_{i-1}\right]=V_{i},\hskip0.1in  V_{i} \neq \{0\}, \hskip0.1in 2 \leqslant i \leqslant k,
\notag
\\
& [ V_{1}, V_{k} ]=\left\{ 0 \right\}.
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:00:15.219689+00:00","domain":"probability theory","id":"claim_43089062b7210d34eab68f65f88b88e36d1b51f79d118ab0ac38837e36f7c960","kind":"theorem","schema_version":1,"statement":"[Proposition 21 (Sample exchangeability from exchangeable measures) of arXiv:2607.18201, 'Finding Adam in noisy trees'] Let $\mu:\cT^* \to \cP(\cT^*)$ be measurable. Given $(\bt,o)\in\cT^*$, we denote the image of it under $\mu$ as $\mu_{(\bt,o)}$. Fix $r\geq 1$. Conditionally on $((\cT_n(1;E_r),1),\dots,(\cT_n(r;E_r),r))$, let $(\sT_1,\dots,\sT_r)$ be a vector of random trees with law
