{"assumptions":[],"created_at":"2026-10-27T10:07:48.564226+00:00","domain":"probability theory","id":"claim_4348dbf58d909ca8d01dafcf5ca4ad2ebff930d27194ee9a6fef6d04e630642a","kind":"theorem","schema_version":1,"statement":"[Proposition 13 of arXiv:2609.01460, 'On cost-induced Santal\'o-type inequalities \\ in Polish measure spaces'] Let $K \in \mathcal{C}^n$ and let $L \in \mathcal{B}(\R^n)$ be non-empty. Define $M(K,L) = \sup_{x\in K, y\in L} \langle x, y \rangle$. Then,
    \begin{enumerate}
        \item If $L$ is unbounded, then $M(K,L)=\infty$.
        \item If $L$ is bounded, then $0\leq M(K,L)<\infty$ and $L\subseteq M(K,L)K^\circ$. Moreover, one has $M(K,L)=0$ if and only if $L=\{o\}$.
    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:38:25.226010+00:00","domain":"probability theory","id":"claim_434b28e86bd1e01504bacbac13caff2f6a516d39708f68680ce0891e48cf43b1","kind":"concept","schema_version":1,"statement":"[Lemma lemma2-3 of arXiv:2609.00627, 'Global well-posedness of radially symmetric strong solutions to two-dimensional compressib'] Let $\Omega$ be a bounded Lipschitz domain in $\mathbb{R}^2$. Then,  for any $ q>2$, there are positive constants $C_1, C_2$ depending on $q$ and $\Omega$, such that for any functions $\boldsymbol{u},\boldsymbol{v}:\Omega\rightarrow\mathbb{R}^2$ with $\boldsymbol{u}\in H^1(\Omega)$ and $\boldsymbol{v}\in W^{1,q}(\Omega)$,
	\begin{equation}
		\|\boldsymbol{u}\|_{L^q(\Omega)}\leq C_1\|\boldsymbol{u}\|_{L^2(\Omega)}^\frac{2}{q}\|\nabla\boldsymbol{u}\|_{L^2(\Omega)}^{1-\frac{2}{q}}+C_2\|\boldsymbol{u}\|_{L^2(\Omega)}
	\end{equation}
	and
		\begin{equation}
		{\Vert \boldsymbol{v} \Vert}_{L^\infty(\Omega)} \le C_1{\Vert \boldsymbol{v} \Vert}_{L^2(\Omega)}^{\frac{q-2}{2q-2}}{\Vert \nabla \boldsymbol{v} \Vert}_{L^q(\Omega)}^{\frac{q}{2q-2}}+C_2\|\boldsymbol{v}\|_{L^2(\Omega)}. 
	\end{equation}
	Furthermore, if $ \boldsymbol{u}\cdot\boldsymbol{n}|_{\partial \Omega}=\boldsymbol{v}\cdot\boldsymbol{n}|_{\partial \Omega}=0\text{ or } \int_{\Omega} u_i dx=\int_\Omega v_i=0$ with $i=1,2$, then $C_2=0$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:24:59.503895+00:00","domain":"probability theory","id":"claim_434d2803b133b623472ca350b0009c56d904ba2c77866d7b6f7d78a9b41e00cb","kind":"theorem","schema_version":1,"statement":"[Proposition 71 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] Let $Y$ be a continuous $\bbr^{m \times d}$-valued process, and let $Y'$ be a continuous $\bbr^{m \times d \times d}$-valued processes such that $(Y,Y') \in \scrd_X^{2 \alpha}([0,T],\bbr^{m \times d})$ on $N_1^c$. Then the following statements are true:
\begin{enumerate}
\item The $\bbr^m$-valued rough integral
\begin{align*}
\int_0^T Y_s \, d \mathbf{B}^{\text{\rm It\^o}}_s = \lim_{|\Pi| \to 0} \sum_{[u,v] \in \Pi} ( Y_u B_{u,v} + Y_u' \bbb_{u,v}^{\text{\rm It\^o}} )
\end{align*}
exists on $N_1^c$.

\item If $Y$ and $Y'$ are adapted and bounded, then there is a $\bbp$-nullset $N$ with $N_1 \subset N$ such that
\begin{align*}
\int_0^T Y_s \, d \mathbf{B}^{\text{\rm It\^o}}_s = \int_0^T Y_s \, dB_s \quad \text{on $N^c$.}
\end{align*}
\end{enumerate}","status":"unverified"}

