{"assumptions":[],"created_at":"2026-10-26T20:28:53.621022+00:00","domain":"probability theory","id":"claim_4375659c222ba9d46458b7493383bf9191e6979e6ae6b2433e543bbc350efec9","kind":"concept","schema_version":1,"statement":"[Theorem 4 (Asymptotic formulas for intrinsic volumes of \(\mathbb B_p^n\)) of arXiv:2605.11995, 'Intrinsic volumes of \(\ell_p\)-balls and a continuum of Maxwell--Poincar\'e--Borel laws f'] Fix \(1<p<\infty\). The following assertions hold as \(n\to\infty\).

\begin{itemize}
\item[(i)] \emph{Bulk regime.}
Let \(j(n)\in\{0,\dots,n\}\) be such that $\alpha(n) := j(n)/n \to \alpha \in (0,1)$, as $n\to\infty$.
Let \(\theta_{p,\alpha}\in(0,\infty)\) be the unique maximizer of the function \(\Psi_{p,\alpha}\) from Proposition~\ref{prop:maximizer_Phi_p_beta}. Then
\begin{equation}
V_{j(n)}(\mathbb B_p^n)
\sim
\frac{p(p-1)^{n-j(n)-1}\,n\binom{n-1}{j(n)}}{2\pi^{(n-j(n))/2}\,
\Gamma\!\left(\frac{j(n)+p}{p}\right)}
\,
\frac{\mathcal K_p(\theta_{p,\alpha})}{\theta_{p,\alpha}\,\mathcal J_p(\theta_{p,\alpha})}
\,
e^{\,n\Psi_{p,\alpha(n)}(\theta_{p,\alpha(n)})}
\sqrt{\frac{2\pi}{n\,|\Psi_{p,\alpha}''(\theta_{p,\alpha})|}}.
\end{equation}

\item[(ii)] \emph{Left-edge regime.}
Let \(j\in\N\cup\{0\}\) be fixed. Then
\begin{equation}
V_j(\mathbb B_p^n)
\sim
\frac{1}{j!}
\left(
(2\sqrt{\pi})^{1/p}
\left(
\frac{\Gamma\!\left(\frac{1}{2p-2}\right)}{p-1}
\right)^{1-1/p}
\right)^j
n^{\,j(1-1/p)}.
\end{equation}

\item[(iii)] \emph{Right-edge regime.}
Let \(m\in\N\) be fixed. Then
\begin{equation}
V_{n-m}(\mathbb B_p^n)
\sim
\frac{\Gamma\!\left(\frac m2\right)}{2\,\Gamma(m)}
\left(
\frac{p(p-1)\Gamma\!\left(1-\frac1p\right)}
{\pi\,\Gamma\!\left(\frac1p\right)}
\right)^{m/2}
\frac{\left(\frac{2}{p}\Gamma\!\left(\frac1p\right)\right)^n\,n^{m/2}}
{\Gamma\!\left(\frac{n+p-m}{p}\right)}.
\end{equation}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:32:11.130689+00:00","domain":"probability theory","id":"claim_43761109ff4fb5be316dde0e64cae50dac18bd3f7b07b5b5e080895a6948284b","kind":"concept","schema_version":1,"statement":"[Lemma E:dg of arXiv:2510.09818, 'On the Fourier dimension of fractional Brownian graphs'] [LL25]
	Let $H \in (0,1)$.
	Let $0<s_1<\cdots<s_I$ and $a = (a_1,\dots,a_I) \in \mathbb R^I$ with $\sum_{i=1}^I a_i = 0$. Then:
	\begin{enumerate}
	\item[(i)] For any $i \in \{1,\dots, I\}$,
	\begin{align}
		\partial_{s_i} g_a(s) = 2H \sum_{j=1}^{i-1} a_i a_j (s_i-s_j)^{2H-1} - 2H \sum_{j=i+1}^I a_i a_j (s_j-s_i)^{2H-1}.
	\end{align}
	\item[(ii)] For any $i<j$ in $\{1,\dots, I\}$,
	\begin{align}
		\partial_{s_i} \partial_{s_j} g_a(s) = 2H(1-2H) a_i a_j (s_j-s_i)^{2H-2}.
	\end{align}
	\item[(iii)] If $k \ge 3$, then for all $i_1<\cdots<i_k$ in $\{1,\dots, I\}$,
	\begin{align}
		\partial_{s_{i_1}} \cdots \partial_{s_{i_k}} g_a(s) = 0.
	\end{align}
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:52:57.738657+00:00","domain":"probability theory","id":"claim_4377fd4991aef3742e6f9bec7f6e948918144cea286752445eb880b7705ef86d","kind":"lemma","schema_version":1,"statement":"[Lemma 40 of arXiv:2609.02755, 'The Sharp Rate of Probabilistically Strong Convergence to the KPZ Equation'] Let $\tilde{E}, E, F$ be metric spaces. Let $\iota : \tilde{E} \to E$ be a compact embedding. Let $E_{\mathrm{sol}} \subset E$ be open and let $f : E_{\mathrm{sol}} \to F$ be continuous. Suppose that $(X_\lambda)_{\lambda \in \Lambda}$ is a collection of $\tilde{E}$-valued random variables such that:
	\begin{enumerate}
		\item there exist $e \in \tilde{E}$ and $p > 0$ such that $\sup_{\lambda \in \Lambda} \mathbb{E}[ d_{\tilde{E}}(X_\lambda, e)^p ] < \infty$;
		\item for every $\lambda \in \Lambda$, $\iota(X_\lambda) \in E_{\mathrm{sol}}$ almost surely;
		\item every subsequential limit $\mu$ of the laws $(\iota(X_{\lambda}))_{\lambda \in \Lambda}$ satisfies $\mu(E_{\mathrm{sol}}) = 1$.
	\end{enumerate}
	Then for all $y_0 \in F$,
	\begin{equ}
		\limsup_{M \to \infty} \sup_{\lambda \in \Lambda} \mathbb{P}( d_F( f(\iota(X_\lambda)), y_0) > M) = 0\;.
	\end{equ}","status":"unverified"}

