{"assumptions":[],"created_at":"2026-10-26T19:29:52.208242+00:00","domain":"probability theory","id":"claim_437bb1b81451a33e710c009942592ef110d437f16b95506ca639a1eab01430fb","kind":"concept","schema_version":1,"statement":"[Theorem 9 (Asymptotics for $\alpha \to \alpha_b, \tilde{\alpha}_b$) of arXiv:2512.09136, 'On the Green's functions and Martin boundary structure of a planar diffusion in a disconti'] Let $z_0 \in \R^2$ and let $\alpha_0 = \alpha_b$. Assume $x_{max}^+ > x_{max}^-$, i.e., $\alpha_b \in (0,\pi)$ (cases A and D of Figure~\ref{anglesalphab}). Define
\begin{equation}
    K_+^2 = \frac{\Sigma_{22}^+\big(y(\alpha_b) - Y^-(x(\alpha_b))\big)}{4|\sin(\alpha_b)| \left( \Sigma^+_{11}\sin^2(\alpha_b) - 2\Sigma^+_{12} \sin (\alpha_b) \cos (\alpha_b) + \Sigma^+_{22} \cos^2(\alpha_b) \right)}.
\end{equation}
Then:
\begin{itemize}
    \item[$(i)$] If $\alpha > \alpha_b$, then \eqref{cas_1} holds.
    \item[$(ii)$] If $\alpha < \alpha_b$ and $r(\alpha_b - \alpha)^2$ is bounded, then \eqref{cas_1} holds.
    \item[$(iii)$] If $\alpha < \alpha_b$, $r(\alpha - \alpha_b)^2 \to +\infty$, and $\frac{e^{K_+^2 r (\alpha_b - \alpha)^2}}{r(\alpha_b - \alpha)^{3/2}} \to 0$,
    then \eqref{cas_1} holds.
    \item[$(iv)$] If $\alpha < \alpha_b$, $r(\alpha - \alpha_b)^2 \to +\infty$, and
    $\frac{e^{K_+^2 r (\alpha_b - \alpha)^2}}{r(\alpha_b - \alpha)^{3/2}} \to +\infty,$
    then
    \begin{equation}
    g^{z_0}(r\cos(\alpha), r\sin(\alpha))
    \underset{r\to\infty \atop \alpha\to\alpha_b}{\sim}  C_{br} f_0(z_0) \frac{e^{-r(\cos(\alpha)x(\alpha_b) + \sin(\alpha)y(\alpha_b))}}{r^{3/2} (\alpha_b - \alpha)^{3/2}},
    \end{equation}
    where $f_0(z_0) > 0$ is given by \eqref{f(z_0)branch} and $C_{br} = |\sin(\alpha_b)|^{3/2} C_0$ (see \eqref{eq:C_0}).
    \item[$(v)$] If $\alpha < \alpha_b$ (resp. $\alpha > \alpha_b$), $r(\alpha - \alpha_b)^2 \to +\infty$, and
    \[
    \frac{e^{K_+^2 r (\alpha_b - \alpha)^2}}{r(\alpha_b - \alpha)^{3/2}} \to c > 0,
    \]
    then
    \begin{equation}
    g^{z_0}(r\cos(\alpha), r\sin(\alpha))
    \underset{r\to\infty \atop \alpha\to\alpha_b}{\sim} \left( C(\alpha_b) h_{\alpha_b}(z_0) + c\, C_{br} f_0(z_0) \right) \frac{e^{-r(\cos(\alpha)x(\alpha) + \sin(\alpha)y(\alpha))}}{\sqrt{r}},
    \end{equation}
    where $h_{\alpha_b}(z_0)$ is given by \eqref{Harm1}.
\end{itemize}

Now assume that $x_{max}^+ < x_{max}^-$ (cases B and C of Figure~\ref{anglesalphab}). Then, the analogous cases $(i)$ to $(v)$ hold. More precisely, let
\[
K_-^2 = \frac{\Sigma_{22}^- \big(z(\alpha_b) - Z^+(x(\alpha_b))\big)}{4|\sin(\alpha_b)| \left( \Sigma^-_{11} \sin^2(\alpha_b) - 2 \Sigma^-_{12} \sin(\alpha_b) \cos(\alpha_b) + \Sigma^-_{22} \cos^2(\alpha_b) \right)}.
\]
\begin{itemize}
    \item[$(i)$-$(iii)$] In cases $(i)$ to $(iii)$, replace $K_+^2$ by $K_-^2$ and the conditions $\alpha < \alpha_b$ (resp. $\alpha > \alpha_b$) by $\alpha > \alpha_b$ (resp. $\alpha < \alpha_b$). Then, \eqref{cas_1'} holds in these cases.
    \item[$(iv)$-$(v)$] In cases $(iv)$ to $(v)$, replace $K_+^2$ by $K_-^2$ and the condition $\alpha < \alpha_b$ by $\alpha > \alpha_b$. Then, the corresponding asymptotics hold replacing $y(\alpha)$ by $z(\alpha)$. Namely, in case $(iv)$,
    \begin{equation}
    g^{z_0}(r\cos(\alpha), r\sin(\alpha))
    \underset{r\to\infty \atop \alpha\to\alpha_b}{\sim} C_{br} f_0(z_0) \frac{e^{-r(\cos(\alpha) x(\alpha_b) + \sin(\alpha) z(\alpha_b))}}{r^{3/2} |\alpha_b - \alpha|^{3/2}},
    \end{equation}
    where $f_0(z_0) > 0$ is given by \eqref{f(z_0)col}. In case $(v)$,
    \begin{equation}
    g^{z_0}(r\cos(\alpha), r\sin(\alpha))
    \underset{r\to\infty \atop \alpha\to\alpha_b}{\sim} \left( C(\alpha_b) h_{\alpha_b}(z_0) + c\, C_{br} f_0(z_0) \right) \frac{e^{-r(\cos(\alpha) x(\alpha) + \sin(\alpha) z(\alpha))}}{\sqrt{r}},
    \end{equation}
    where $h_{\alpha_b}(z_0)$ is given by \eqref{Harm1'}.
\end{itemize}

The symmetric result holds for $\alpha_0 = \tilde{\alpha}_b$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:28:53.622293+00:00","domain":"probability theory","id":"claim_437cb782a709e4397644ad42e5596ea3b271b905be2e755aeadae3202e45c8a6","kind":"concept","schema_version":1,"statement":"[Proposition 20 (Laplace asymptotics in the left-edge regime) of arXiv:2605.11995, 'Intrinsic volumes of \(\ell_p\)-balls and a continuum of Maxwell--Poincar\'e--Borel laws f'] Fix $1<p<\infty$, an integer $r\ge 1$, and consider complex parameters $\lambda_1,\dots,\lambda_r\in\mathbb C$ satisfying
\begin{equation}
\Re\lambda_s>\max\{-1,1-p\},
\qquad s=1,\dots,r,
\qquad
\Re(\Lambda+j+p)>0,
\end{equation}
where $\Lambda:=\lambda_1+\cdots+\lambda_r$. Fix an integer $j\geq 1$ and recall that for sufficiently large  integer $n$ we defined
\[
I_{n, j}(\lambda_1,\dots,\lambda_r)
:=
\int_{\partial \mathbb B_p^n}
\prod_{j=1}^r |x_j|^{\lambda_j}\,
d\Phi_{j}\bigl(\mathbb B_p^n,x\bigr).
\]
Then the following assertions hold:

\vspace{2mm}
\noindent
(i) Absolute asymptotic: As $n\to\infty$, one has
\[
I_{n,j}(\lambda_1,\dots,\lambda_r)\sim
\frac{
\Gamma\!\left(\frac{2p-1}{2p-2}\right)\,
\Gamma\!\left(\frac1{2p-2}\right)^j
\prod_{s=1}^r \Gamma\!\left(\frac{\lambda_s+p-1}{2p-2}\right)
}{
j!\,(p-1)^j\,\pi^{(r+1)/2}
}
\left(
\frac{\sqrt\pi}{\Gamma\!\left(\frac{2p-1}{2p-2}\right)}
\right)^{\frac{\Lambda+j+p}{p}}
n^{\,j+1-\frac{\Lambda+j+p}{p}}.
\]
In particular, setting $\lambda_1=\ldots= \lambda_r = 0$ gives
\[
I_{n,j}(0,\dots,0)\sim
\frac{
\Gamma\!\left(\frac{2p-1}{2p-2}\right)\,
\Gamma\!\left(\frac1{2p-2}\right)^j
}{
j!\,(p-1)^j\,\sqrt{\pi}
}
\left(
\frac{\sqrt\pi}{\Gamma\!\left(\frac{2p-1}{2p-2}\right)}
\right)^{\frac{j+p}{p}}
n^{\frac{j(p-1)}{p}}.
\]

\vspace{2mm}
\noindent
(ii) Relative asymptotic: As $n\to\infty$, one has
\[
\frac{I_{n,j}(\lambda_1,\dots,\lambda_r)}{I_{n,j}(0,\dots,0)}
\sim
\left(\prod_{s=1}^r
\frac{\Gamma\!\left(\frac{\lambda_s+p-1}{2p-2}\right)}{\sqrt{\pi}}
\right)
\left(
\frac{\sqrt\pi}{\Gamma\!\left(\frac{2p-1}{2p-2}\right)}
\right)^{\frac{\Lambda}{p}}
n^{-\Lambda/p}.
\] (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:48:02.413891+00:00","domain":"probability theory","id":"claim_437fa3c7a4688a736a31a3d069bcb6c9ee4831529f60f3689460aa31e03fc6d9","kind":"theorem","schema_version":1,"statement":"[Prop matching-template of arXiv:2608.26564, 'Real ideal points, Conway spheres, and left-orderable Dehn fillings'] Let $K$ be a family knot with exterior $M$, and let $\lambda = \ell_1\ell_2\ell_3\ell_4$ be its canonical four-longitude decomposition. For every admissible real limiting datum described in Section (sec:twobridge of the paper), this decomposition is in positive parabolic normal form along both associated real half-branches. Moreover, for either half-branch $B$, there is a sign $\sigma_B \in \{\pm 1\}$ such that, for all sufficiently small $u > 0$:
\begin{enumerate}
	\item For a torus-torus datum $(r_{n,j}, r_{m,k})$ $\mathrm{trans}(\widetilde\rho_u(\lambda)) = 2\sigma_B(j-k)$. In particular, height cancellation holds if and only if $j=k$.
	\item For a twist-torus datum whose torus root is $r_{m,k}$, $\mathrm{trans}(\widetilde\rho_u(\lambda)) = -2\sigma_B k$. In particular, height cancellation holds if and only if $k = 0$. 
	\item For the unique twist-twist datum, $\mathrm{trans}(\widetilde\rho_u(\lambda)) = 0$. 
\end{enumerate}","status":"unverified"}

