{"assumptions":[],"created_at":"2026-10-27T22:20:15.718256+00:00","domain":"probability theory","id":"claim_4383c32a612f44f08c2c76f5c88bdbfc5e4b88a018c6e02af5a7d04e49c414e6","kind":"lemma","schema_version":1,"statement":"[Lemma lemma_estimate_total_mass of arXiv:2609.00973, 'The Vlasov-Maxwell point charge system : study of the spherically symmetric case'] Let $M_I, M_O$ be defined as 
    \begin{equation*}
        M_I(t,r):=4\pi^2\iiint \1_{\mathcal{B}_t}\1_{\{\widetilde{R}(\theta,a)\leq r\}}\gamma(t,\theta,a,\ell)\mathrm{d}\theta\mathrm{d}a\mathrm{d}\ell,\quad M_O(t,r):=4\pi^2\iiint \1_{\mathcal{B}_t^c}\1_{\{\widetilde{R}(\theta,a)\leq r\}}\gamma(t,\theta,a,\ell)\mathrm{d}\theta\mathrm{d}a\mathrm{d}\ell.
    \end{equation*}
    For all $t\geq T_0, r>0$, and  $k,\sigma \geq 0$, the enclosed mass $M$ satisfies $M(t,r)=M_I(t,r)+M_O(t,r)$ and 
    \begin{equation}
    \notag
    \begin{array}{rl}
        \displaystyle \frac{M_I(t,r)}{r^k} \lesssim & t^{-k} \left(\|a^{-k}\gamma\|_{L^1} +\| \gamma\|_{L^1} \right),\vspace{3pt}\\
         \displaystyle \frac{M_O(t,r)}{r^k} \lesssim & t^{-k-\sigma}\left(\|a^{-2k-4\sigma}\gamma\|_{L^1}+\|a^{4k+3\sigma}\gamma\|_{L^1}+\|a^{k}\ell^{2k+2\sigma}\gamma\|_{L^1}+\||\theta|^{k+\sigma}(a^{k-\sigma}+a^k)\gamma\|_{L^1}\right).
    \end{array}
    \end{equation}
    In the case $r=\widetilde{R}(\theta,a)$, we can obtain a more specific estimate.
    \begin{equation}
    \notag
    \begin{array}{r@{}l}
        \displaystyle \frac{M(t,\widetilde{R})}{{\widetilde{R}}^k(\widetilde{R}-\frac{1}{a^0})} \lesssim & ~t^{-k} \left(\|a^{-k}\gamma\|_{L^1} +\| a^2\gamma\|_{L^1} \right)\vspace{3pt}\\
         \displaystyle & +~ t^{-k-\sigma}\left(\|(a^{-2k-4\sigma}+a^{4k+3\sigma+2})\gamma\|_{L^1}+\|\ell^{2k+2\sigma}(a^k+a^{k+2})\gamma\|_{L^1}+\||\theta|^{k+\sigma}(a^{k-\sigma}+a^{k+2})\gamma\|_{L^1}\right).
    \end{array}
    \end{equation}","status":"unverified"}

