\supp\widehat g\subset B(0,C2^j).
\]
Define the Peetre maximal function by
\begin{equation*}
\mathcal{P}_{j,N}^Lg(x)
:=
\sup_{y\in\R^d}
\displaystyle\sum_{|\alpha|\le L}\frac{2^{-j|\alpha|}|D^\alpha g(y)|}
{(1+2^j|x-y|)^N}.
\end{equation*}
The following estimate holds:
\begin{equation}

\|\Pmax_{j,N}^Lg\|_{L^p(\R^d)}\lesssim\|g\|_{L^p(\R^d)}.
\end{equation}","status":"unverified"}

