{"assumptions":[],"created_at":"2026-10-27T13:20:07.902544+00:00","domain":"probability theory","id":"claim_454ac19ce30e456043b38993081295a526121e6ee8d299ff8ccf59a26c3d5460","kind":"definition","schema_version":1,"statement":"[Definition def:weightcore of arXiv:2608.23765, '\texorpdfstring{Tight Majorizations and Convergence Rates\\ of Nuclear Norm Minimization I'] Let $\boldsymbol{\sigma} \in \R^{D}$ be a nonincreasing vector of singular values
	(padded by zeros for indices larger than $d$), and let $\varepsilon>0$ be a smoothing parameter.
	The associated \emph{weight operator core matrix}
	$\mathbf{H}_{\boldsymbol{\sigma},\varepsilon} \in \R^{d_1 \times d_2}$ is defined entrywise for $i\in[d_1]$ and $j\in[d_2]$, by one of the following choices:
	\begin{align}
		(\mathbf{H}_{\boldsymbol{\sigma},\varepsilon})_{ij}
		&= [\max(\sigma_i,\varepsilon)]^{-1},
		&& \text{left-sided [Fornasier11]},

		\\
		(\mathbf{H}_{\boldsymbol{\sigma},\varepsilon})_{ij}
		&= [\max(\sigma_j,\varepsilon)]^{-1},
		&& \text{right-sided [mohan_fazel]},

		\\
		(\mathbf{H}_{\boldsymbol{\sigma},\varepsilon})_{ij}
		&= 2[\max(\sigma_i,\varepsilon)+\max(\sigma_j,\varepsilon)]^{-1},
		&& \text{harmonic-mean [Kummerle-JMLR2018]}.

	\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:51:33.318597+00:00","domain":"probability theory","id":"claim_454b3c86fffe57029d0a62189e99753b1e16fcb768c5dee733368d9819d8208e","kind":"definition","schema_version":1,"statement":"[Definition See \cite{CLL_Clefts}*{Definition~3.2} of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] Let $T$ be a small $\infty$-category. A \emph{cleft} is a wide subcategory $i\colon S\hookrightarrow T$ satisfying all of the following conditions:
    \begin{enumerate}
        \item $S$ is left-cancellable, i.e.~for any composable maps $f,g$ in $T$ such that $f$ and $fg$ belong to $S$,  also $g$ belongs to $S$.
        \item Given any $f\colon A\to B$ in $S$ and $g\colon B'\to B$ in $T$, there exists a pullback square in $\PSh(T)$ of the form
        \[
            \begin{tikzcd}
                i_!X\arrow[d]\arrow[dr,pullback]\arrow[r,"i_!f'"] & i_!B'\arrow[d,"g"]\\
                i_!A\arrow[r, "i_!f"'] & i_!B\rlap,
            \end{tikzcd}
        \]
        where $i_!\colon\PSh(S)\to\PSh(T)$ denotes left Kan extension along $i$ and we conflate elements of $S$ and $T$ with their Yoneda image as before.
        \item Given maps $f\colon A\to B$ and $g\colon B\to A$ in $T$ such that $gf=\textup{id}_A$ and $fg$ belongs to $S$, then both $f$ and $g$ belong to $S$.
    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:43:43.163943+00:00","domain":"probability theory","id":"claim_454e2268049823220d6bca1a5f9766ad425a16d20513e90139433a0ccd846e0d","kind":"concept","schema_version":1,"statement":"[Proposition prop: domain markov of arXiv:2506.21466, 'The Markov property for $\varphi^4_3$ on the cylinder'] Let $\varphi_-,\varphi_+ \in S'(\mathbb T^2)$. Let $F^+,F^-:S'(M)\rightarrow \mathbb R$ be bounded functions such that $F^\pm$ is ${\rm Int}(M^\pm)$-measurable, and let $F=F^+ F^-$ be their pointwise product. Then
 \begin{equation}
  \mathbb E_{\mu_{\varphi_-,\varphi_+}}[ F]
  =
\mathbb E_{\tilde\mu^0}\left[  \mathbb E_{\mu^-}[F^-(\varphi^- + H^-(\varphi_-,\varphi^0)) ]\mathbb E_{\mu^+}[F^+(\varphi^+ + H^+(\varphi_+,\varphi^0)) ] \right], 
  \end{equation}
  where $\varphi^{\sigma} \sim \mu^\sigma$ is the Dirichlet GFF on $M^\sigma$ and $\varphi^0 \sim \tilde\mu^0$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:23:58.627328+00:00","domain":"probability theory","id":"claim_454f02b9296857ff73e34bd9915e3ec6aac51c84d76938e1044b237857966558","kind":"theorem","schema_version":1,"statement":"[Corollary 213 ($L^2$ estimates for $\velocityarray$ that lose one derivative) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] Let $1 \leq N \leq \Ntop$,
