{"assumptions":[],"created_at":"2026-10-28T01:10:08.779910+00:00","domain":"probability theory","id":"claim_455004b0ba54a4cb864755d341092fbd38591bf13feb6729e1ef07bb5836351d","kind":"concept","schema_version":1,"statement":"[Lemma lemmaalternativetrap of arXiv:2411.18359, 'Large systems of symmetrized trapped Brownian Bridges and Schr\"odinger processes'] Define 
    \begin{equation}
\widetilde{I}^{\ssup{{\rm sym}}}_{{\mathfrak m},W}(\mu)=\inf_{q\in{\mathcal M }_1^{{\scriptscriptstyle{({\rm s}})}}(\mathbb{R}^d\times\mathbb{R}^d)}\Bigl\{H(q|\overline{q}\otimes{\mathfrak m})+ \widetilde{I}_W^{{\scriptscriptstyle{({q}})}}(\mu)\Bigr\},\qquad \mu\in{\mathcal M }_1({\mathcal C }_\beta),
\end{equation} 
