	\begin{equation}{}
		\bigg\| \frac{1}{k!} \sum\limits_{x_1,\dots,x_k \in \Omega_{\delta}} f(x_1,\dots,x_k) \prod\limits_{j=1}^k \frac{\omega_{x_j}}{V_{\delta}}\bigg\|_p \, \leqslant\, (C_0)^k \big\| \overline{f} \big\|_q \,.
