    \mathcal{G}_+^{\rho} F & =  \sum_{k, \ell \in \mathbb{N}} \delta
    (e_{\ell} \delta (e_k \langle B (\rho e_k, \rho e_{\ell}), \rho D F
    \rangle_{V^{\ast}, V})), \\
    \mathcal{G}_-^{\rho} F & =  2 \sum_{k, \ell \in \mathbb{N}} \delta (e_k
    \langle B (\rho e_k, \rho e_{\ell}), \rho D D_{e_{\ell}} F
