                    \item  {For any {$i \in {\mathbb{Z}}$} and $p \ge 1$, we have 
                        \begin{align}
                            \lim_{n \to \infty} {\mathbb{E}}_{{\mu}}\left[ \left| \frac{{Y}^{i}_{k}\left(n\right)}{n} - v^{\mathrm{eff}}_{k}\left({\mu}\right) \right|^{p} \right] = \lim_{n \to \infty} {\mathbb{E}}_{\nu}\left[ \left| \frac{{Y}^{i}_{k}\left(n\right)}{n} - v^{\mathrm{eff}}_{k}\left({\mu}\right) \right|^{p} \right] =  0.
                        \end{align}}
