      \RightLabel{\scriptsize{$\textsf{M}_\Box$}}
      \UnaryInfC{$\Box \Diamond \Diamond \varphi \to \Box \Diamond \varphi$}

      \RightLabel{\scriptsize{Syll.}}
      \BinaryInfC{$\Diamond \varphi \to \Box \Diamond \varphi$}
      \DisplayProof
    \end{center}
    (3) Follows from the below derivations:
    \begin{center}
      \AxiomC{$ $}
      \RightLabel{\scriptsize{$\textsf{B}_\Diamond$}}
      \UnaryInfC{$\Box \varphi \to \Box \Diamond \Box \varphi$}

