{"assumptions":[],"created_at":"2026-10-27T07:00:46.826350+00:00","domain":"probability theory","id":"claim_4604e123c81bba2d5bd035e0421fdf4586af467dfd0c0b23133a56b65e929bf0","kind":"definition","schema_version":1,"statement":"[Definition 1 of arXiv:2608.13235, 'Mixing Properties of Random Laguerre Tessellations'] Let $\ppp$ be a stationary marked point process on $\rd \times \R$. We say that it is 
\begin{itemize}
    \item[(i)]ergodic, if for all $A,B \in \mathcal{N}(\rd \times \R)$,
\begin{equation*}
\lim_{a \rightarrow \infty} \frac{1}{\lambda^d((-a,a)^d)} \int_{(-a,a)^d} \p(\ppp\in A, T_z(\ppp) \in B) \,\dx z = \p(\ppp \in A)\p(\ppp \in B),
\end{equation*}
    \item[(ii)]mixing, if for any $A, B \in \mathcal{N}(\rd \times \R)$,
\begin{equation*}
    \lim_{\norm{z}\rightarrow \infty} \p(\ppp \in A, T_z(\ppp) \in B) = \p(\ppp \in A) \p(\ppp \in B),
\end{equation*}
    \item[(iii)] $\alpha$-mixing, if for all $0< c < \infty$,
    \begin{equation*}
    \lim_{\Delta \rightarrow \infty}  \alpha_\ppp(c,\infty;\Delta)=0.
    \end{equation*}
\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:48:27.276812+00:00","domain":"probability theory","id":"claim_46067dcaf5d59dd88053adc976ae6fc59d088268fe398276c28ad0bd48e88c94","kind":"concept","schema_version":1,"statement":"[Theorem 1 of arXiv:2604.24664, 'Absolute continuity of Rosenblatt measures'] Let $(B_t)_{t \in [0, T]}$ be an $\FctT$-Wiener process. Let $\phi: [0, T] \times \Omega \to \Rbb$ be an $\FctT$-progressively measurable process such that $\phi \in L^2([0, T])$ almost surely and assume that the process $(Z_t)_{t\in [0,T]}$ defined by
	\begin{equation}

		Z_t = \exp\left( - \int_0^t \phi_s \d{B_s} - \frac12 \int_0^t \phi^2_s \d{s} \right), \quad t \in [0, T],
	\end{equation}
	is an $\FctT$-martingale. Let $\tilde{\Pbb}$ be the probability measure on $(\Omega, \Fcal)$ defined by $\d{\tilde{\Pbb}} = Z_T \d{\Pbb}$. Then the process $(\tilde{B}_t)_{t \in [0, T]}$ defined by
	\[
		\tilde{B}_t = B_t + \int_0^t \phi_s \d{s}, \quad t \in [0, T],
	\]
	is an $\FctT$-Wiener process with respect to $\tilde{\Pbb}$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:45:27.889986+00:00","domain":"probability theory","id":"claim_460755bc563357479b4e89ba5e1a2e2f61e217ae9743d4e3bdabef4a2ad79d56","kind":"concept","schema_version":1,"statement":"[Proposition prop:nonuniform:CLT:crude of arXiv:2607.04047, 'Top Singular Value in Sum-Products of Random Matrices'] There exists some universal constant $a > 0$ such that 
\begin{align*}
    {\mathbb P}( E_1 > x ) 
    \;=&\;
    \Phi^c(x) 
     \,
     \Big( 1 + O\Big( \mfrac{1}{n} + \mfrac{N^{1/2}}{n^{3/2}}  + \mfrac{1+|x|^3}{\sqrt{N}}\Big) \Big)
    \qquad 
    \text{ for } 
    \quad 
    0 \leq x \leq a N^{1/6}
    \;,
    \\
    {\mathbb P}( E_1 < x ) 
    \;=&\;
    \Phi(x) 
     \,
     \Big( 1 + O\Big( \mfrac{1}{n} + \mfrac{N^{1/2}}{n^{3/2}}  + \mfrac{1+|x|^3}{\sqrt{N}}\Big) \Big)
    \qquad 
    \text{ for } 
    \quad 
    - a N^{1/6} \leq x \leq 0
    \;.
\end{align*}
Suppose in addition that $|x| = o(N^{1/6})$ and $N=o(n^3)$. If $x > 0$ with $x = \omega(1)$, then 
\begin{align*}
    {\mathbb P}( E_1 > x ) 
    \;=\; 
    (1+o(1)) \, e^{ - \frac{x^2}{2} + o(x) }
    \;.
\end{align*}
If $x < 0$ with $|x| = \omega(1)$, then
\begin{align*}
    {\mathbb P}( E_1 < x ) 
    \;=\; 
    (1+o(1)) \, e^{ - \frac{x^2}{2} + o(|x|) }
    \;.
\end{align*}
If instead $x=O(1)$, we have 
\begin{align*}
    {\mathbb P}( E_1 > x ) 
    \;=&\;
    \begin{cases}
        \Theta( e^{-x^2/2} ) 
        & 
        \text{ if } x > 0\;,
        \\
        \frac{1}{2} (1 + o(1))
        & 
        \text{ if } x = o(1)\;,
        \\
        1 - \Theta( e^{-x^2/2} ) 
        & 
        \text{ if } x < 0\;.
    \end{cases}
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

