\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:31:14.339506+00:00","domain":"probability theory","id":"claim_463726d0448b13ef153e458f4780af35282846d3b5c00764096611c34cbd4a8c","kind":"lemma","schema_version":1,"statement":"[Lemma Appendix: Girsanov, exceeding probability of arXiv:2606.19207, 'Extrema of cooling branching Brownian motion and related Gaussian fields'] Fix a probability space $(\Omega,\mathcal{F},\mathbb{P})$ carrying a Brownian motion $B$. Let $\sigma\in C^2(\mathbb{R}_+;\mathbb{R}_+)$ and define
	\[
	Y_t:=\int_0^t\sigma(s)\,\text{d} B_s,
	\qquad t\geq 0.
	\]
	Let $c_A>0$ and let $\eta,r\in C^2([0,\infty);\mathbb R)$ be deterministic. Set
	\begin{equation}
		k_r(t):=c_A\sigma(t)-\frac{\eta(t)+r(t)}{c_A},
		\qquad t\geq 0,
	\end{equation}
	and
	\begin{equation}
		A_r(t):=\int_0^t k_r(s)\,\text{d} s.
	\end{equation}
	Fix $T>0$. Then, for any $\lambda>0$ and any interval $I\subset[0,T]$,
	\begin{equation}
		\begin{aligned}
			\mathbb{P}&(\tau_0(A_r+\lambda-Y)\in I)
			\leq
			\exp\{-\frac{k_r(0)}{\sigma(0)^2}\lambda\}\\
			&\times \mathbb{E}^{(\lambda)}\Biggl[
			\exp\Biggl\{
			-\frac{1}{2}c_A^2\tau_0(Y)
			+\int_0^{\tau_0(Y)}
			\Biggl(
			-\Bigl(\frac{k_r}{\sigma^2}\Bigr)'(s)Y_s
			+\frac{\eta(s)+r(s)}{\sigma(s)}
			\Biggr)\,\text{d} s
			\Biggr\}
			\mathds{1}_{\{\tau_0(Y)\in I\}}
			\Biggr].
		\end{aligned}
	\end{equation}
	Here $\mathbb{E}^{(\lambda)}$ denotes expectation for the diffusion $Y_t=\lambda+\int_0^t\sigma(s)\,\text{d} B_s$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:17:33.989208+00:00","domain":"probability theory","id":"claim_46377018450336887791e943a279e9c04b2afea8a8fc78fb93eed74b8e598dff","kind":"lemma","schema_version":1,"statement":"[Lemma 14 of arXiv:2609.03386, 'Twisted Gradient Flow Approach to Vegetation-Rainfall-Bushfire Interactions Model'] There exists a constant $C_7>0$, which depends on the following values:

