{"assumptions":[],"created_at":"2026-10-26T19:32:58.363760+00:00","domain":"probability theory","id":"claim_463a4393ed8b1e6b2306feb6fc0f39eb4d4c0046f0ed8538e6a69a0551da9fb6","kind":"theorem","schema_version":1,"statement":"[Corollary 5 of arXiv:2506.19273, 'A large deviation view of \emph{stationarized} fully lifted blirp interpolation'] Assume the setup of Theorem \ref{thm:thm5} with  sets ${\mathcal X}$ and ${\mathcal Y}$ being such that $\|\x\|_2=\|\y\|_2=1$. Then
 \begin{eqnarray}
\lim_{n\rightarrow\infty}\psi_1(\bar{\p}(t),\bar{\q}(t),\bar{\m}(t),t)
 =
\lim_{n\rightarrow\infty}\psi_1(\bar{\p}(0),\bar{\q}(0),\bar{\m}(0),0)  =  \lim_{n\rightarrow\infty} \psi_1(\bar{\p}(1),\bar{\q}(1),\bar{\m}(1),1),
\end{eqnarray}
 and
\begin{eqnarray}
\psi_1(\bar{\p}(0),\bar{\q}(0),\bar{\m}(0),0) & = & -\frac{\mbox{sign}(s) s \beta^2}{2\sqrt{n}} \sum_{k=1}^{r+1}\Bigg(\Bigg. \bar{\p}_{k-1}(0)\bar{\q}_{k-1}(0)  -\bar{\p}_{k}(0)\bar{\q}_{k}(0)   \Bigg.\Bigg)
\bar{\m}_k(0) \omega(k;p) \nonumber \\
& &  +\psi(\bar{\p}(0),\bar{\q}(0),\bar{\m}(0),0) \nonumber \\
\psi_1(\bar{\p}(1),\bar{\q}(1),\bar{\m}(1),1) & = & -\frac{\mbox{sign}(s) s \beta}{2\sqrt{n}} \sum_{k=1}^{r+1}\Bigg(\Bigg. \bar{\p}_{k-1}(1)\bar{\q}_{k-1}(1)  -\bar{\p}_{k}(1)\bar{\q}_{k}(1)   \Bigg.\Bigg)
\bar{\m}_k(1)  \omega(k;p) \nonumber \\
& &  +\psi(\bar{\p}(1),\bar{\q}(1),\bar{\m}(1),1).
 \end{eqnarray}
 Moreover, let
 \begin{equation}
\psi_S(\p,\q,\m,t)  =  \mE_{G,{\mathcal U}_{r+1}} \frac{1}{p|s|\sqrt{n}\m_r} \log
\lp \mE_{{\mathcal U}_{r}} \lp \dots \lp \mE_{{\mathcal U}_2}\lp\lp
\lp \sum_{i_3=1}^{l} \mE_{{\mathcal U}_1}  Z_{i_3,S}^{\m_1}\rp^p \rp^{\frac{\m_2}{\m_1}}\rp\rp^{\frac{\m_3}{\m_2}} \dots \rp^{\frac{\m_{r}}{\m_{r-1}}}\rp,
\end{equation}
where,  analogously to (\ref{eq:thm3eq1}) and (\ref{eq:thm3eq2}),
\begin{equation}
Z_{i_3,S}  \triangleq  \sum_{i_1=1}^{l}\lp\sum_{i_2=1}^{l}e^{\beta D_{0,S}^{(i_1,i_2,i_3)}} \rp^{s}, \nonumber \\
\end{equation}
with
\begin{eqnarray}
 D_{0,S}^{(i_1,i_2,i_3)}
 & \triangleq &
 \sqrt{t}(\y^{(i_2)})^T
 G\x^{(i_1)}+\sqrt{1-t}\|\x^{(i_2)}\|_2 (\y^{(i_2)})^T\lp\sum_{k=1}^{r+1}b_k\u^{(2,k)}\rp  \nonumber \\
& &
 +\sqrt{1-t}\|\y^{(i_2)}\|_2\lp\sum_{k=1}^{r+1}c_k\h^{(k)}\rp^T\x^{(i)}
 + f_{\bar{\x}^{(i_3)} } (\x^{(i_1)}).
 \end{eqnarray}
Then
\begin{eqnarray}
\lim_{n\rightarrow\infty} \psi_S(\bar{\p}(1),\bar{\q}(1),\bar{\m}(1),1) & = &
 -\lim_{n\rightarrow\infty}\frac{\mbox{sign}(s) s \beta^2}{2\sqrt{n}} \sum_{k=1}^{r+1}\Bigg(\Bigg. \bar{\p}_{k-1}(0)\bar{\q}_{k-1}(0)  -\bar{\p}_{k}(0)\bar{\q}_{k}(0)   \Bigg.\Bigg)
\bar{\m}_k(t) \omega(k;p)
 \nonumber \\
& &  +\lim_{n\rightarrow\infty} \psi_S(\bar{\p}(0),\bar{\q}(0),\bar{\m}(0),0). \nonumber \\
 \end{eqnarray}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:21:45.237815+00:00","domain":"probability theory","id":"claim_463fe32a467b579389d07abf4af5b4736afecb5781f20077022de478f974d145","kind":"definition","schema_version":1,"statement":"[Definition 5 of arXiv:2607.26564, 'Stochastic Scalar Conservation Laws on Moving Hypersurfaces'] We say that a stochastic process $\{ z(t)\}_{t\in[0,T]}$ is a solution to equation \eqref{eq61} if for each $i \in \{1,\cdots, m\}$,
\begin{itemize}
\item[(i)] $z^i \in L^2(\Omega; C([0,T]; L^2(\Gamma_{\cdot}))) \cap L^2(\Omega; L^2([0,T]; H^1(\Gamma_{\cdot})))$.
\item[(ii)] $z^i$ is an ${L}^{2}(\Gamma_{\cdot})$-valued predictable random process with respect to the filtration $ \{ \mathcal{F}_t \} _{t\in[0,T]} $.
\item[(iii)] For any $\varphi \in H^1(Q_T)$, we have $\mathbb{P}$-a.s.
\begin{eqnarray}
& & \int_{\Gamma_t} z^i(t,x)\varphi(t,x)\mathrm{dvol}_{\Gamma_t}(dx)- \int_{\Gamma_0} z^i_0(y)\varphi(0,y)\mathrm{dvol}_{\Gamma_0}(dy) \nonumber\\
& =& \int_0^t\int_{\Gamma_s}z^i(s,x)\overset{\scalebox{0.4}{$\bullet$}}{\varphi}(s,x) \mathrm{dvol}_{\Gamma_s}(dx)ds - \int_0^t\int_{\Gamma_s}R^{ij}(s,x)\underline{D}_{j}\varphi(s,x)\mathrm{dvol}_{\Gamma_s}(dx)ds\nonumber\\
& & + \int_0^t\int_{\Gamma_s}R^{ij}(s,x)\varphi(s,x)(H\nu_j)(s,x)\mathrm{dvol}_{\Gamma_s}(dx)ds +\int_0^t\int_{\Gamma_s} S^i(s,x)\varphi(s,x)\mathrm{dvol}_{\Gamma_s}(dx)ds \nonumber\\
& & +\int_0^t\int_{\Gamma_s} \Upsilon^i(s,x)\varphi(s,x)\mathrm{dvol}_{\Gamma_s}(dx)dB_s\nonumber\\
\end{eqnarray}
for every $t \in [0,T]$.
\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:51:15.031215+00:00","domain":"probability theory","id":"claim_46428cb666071aba0a2add32f2fb1937fb7f997b8e565759d69188dc61941356","kind":"concept","schema_version":1,"statement":"[Lemma Randersimmersion of arXiv:2609.03909, 'Conic Pseudo-Finslerian Mechanical Systems'] Let $R$ be a Randers-Minkowski metric on $\mathbb R^n$ with navigation data $(h, W)$. If $V$ is a subspace, then the induced metric on $V$ is the Randers-Minkowski metric with navigation data $(\tilde h, W^{\top})$ given by
\begin{subequations}
\begin{equation*}
\tilde h := \lambda \, h\vert_{V \times V} \, ,
\end{equation*}
\begin{equation*}
W^{\top} := W - W^{\perp} \, ,
\end{equation*}
\end{subequations}
where $\lambda := \frac{1}{1 - h(W^{\perp}, W^{\perp})}$ and $W^{\perp}$ is the component of $W$ $h$-orthogonal to $V$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

