            \phantom{\,\,\,\,\,\,\,\,\,}\big[\mathcal{N}_{\alpha/2} + \lambda \mathrm{I}\big] u &= f, \quad \mathrm{in }~\overline{D}^c.
        \end{cases}
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:38:23.615037+00:00","domain":"probability theory","id":"claim_464c5b57ef80e682be42cb33c7a9393ce8a9305922acd2221d43afc78bee2d8a","kind":"theorem","schema_version":1,"statement":"[Corollary EHI:c:K1(x)=K1(-x) of arXiv:2511.08956, '\textbf{Towards a characterization of elliptic Harnack inequality for jump processes}'] Let $X$ be an isotropic unimodal L\'{e}vy jump process on $\mathbb{R}^d$ satisfying (equation EHI:e:regularJumps of the paper). Suppose $B(0, r) \Subset D$, and let $h$ be a function that is non-negative everywhere and harmonic on $D$. Suppose $r_0 \geq r/L$ for some $L>1$. For all $x \in B(0, r)$ and $w \in B(0, r)^c$,
    \begin{equation}
