  \exp\left(tx-\frac{t^2}{2}\right)
  =\sum_{q=0}^{\infty}H_q(x)\frac{t^q}{q!},
  \qquad t,x\in\R.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:30:52.735330+00:00","domain":"probability theory","id":"claim_466e478994e38c29033182ab8abbd33d5123c5443cb98f2fdc781ce4ac3b5802","kind":"lemma","schema_version":1,"statement":"[Lemm 11 of arXiv:2506.10213, 'Coupling of forward-backward stochastic differential equations on the Wiener space, and ap'] For arbitrary $0 \leq t < T < \fz$, suppose the FBSDE \eqref{fbsde:equ:general} satisfies all the following conditions:
