{"assumptions":[],"created_at":"2026-10-27T09:19:56.653947+00:00","domain":"probability theory","id":"claim_467160fa12ee04bd4a9bc77f54668d607ebf863c1ada145f3998337bcbd4ed5e","kind":"lemma","schema_version":1,"statement":"[Lemma 4 (When upward jumps are admissible) of arXiv:2608.30859, 'Conservation Laws with Discontinuous Flux:\\ A First Application to Traffic Flow'] Let $u^-<u^+$ and $\theta^-\ne\theta^+$. According to \eqref{eq:LaxCond}, upward jumps are Lax-admissible in the following two situations:
\begin{itemize}
\item $\theta^-=1$, $\theta^+=0$ and $u^* \leq u^+$, where $(u^*,g(u^*))$ denotes the unique point satisfying: 
\begin{equation}
u^*> u^- \quad\mbox{such that}\quad g^\prime(u^*) = \frac{f(u^-)-g(u^*)}{u^--u^*}.
\end{equation}
\item $\theta^-=0$, $\theta^+=1$ and $u^- \leq v^*$, where $(v^*,g(v^*))$ denotes the unique point satisfying:
\begin{equation}
v^* < u^+ \quad\mbox{such that}\quad g^\prime(v^*) = \frac{f(u^+)-g(v^*)}{u^+-v^*}.
\end{equation}
\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:06:42.721090+00:00","domain":"probability theory","id":"claim_46742da3e147e1bba4bd94d1539e7327fabf19271b0fd1ec3b217af1a89f057d","kind":"definition","schema_version":1,"statement":"[Defi finite action of arXiv:2411.04157, 'Stochastic homogenization of dynamical discrete optimal transport'] Let $(\rho,j)\in \mathcal{M}((0,T)\times \mathbb{R}^n;[0,\infty)\times \mathbb{R}^n)$ be a finite Radon measure. We say that $(\rho,j)$ is a \emph{finite action curve} if
    \begin{enumerate}
    \item $(\rho,j)$ solve the continuity equation 
    \begin{align*}
\partial_t\rho+\dive j=0 \text{ in }\mathcal D'((0,T)\times \mathbb{R}^n).
\end{align*}
        \item $j\ll \rho$ and 
        \begin{align*}
            \int_{(0,T)\times \mathbb{R}^n}\left|\frac{dj}{d\rho}\right|^2\, d\rho<\infty;
        \end{align*}
