{"assumptions":[],"created_at":"2026-10-27T18:32:23.642285+00:00","domain":"probability theory","id":"claim_4686431eda624458217f68e7d1febd62194c2150a312b619cb696434cbe41e24","kind":"lemma","schema_version":1,"statement":"[Lemma lem:twoConnect of arXiv:2603.16824, 'Age-dependent random connection models with arc reciprocity: clustering and connectivity'] Let \(\mathscr{D}\) be the directed age-dependent random connection model with parameter \(\beta>0,\delta>1, \gamma\in(0,1)\) and \(\Gamma\geq 0\).  
\begin{enumerate}[(a)]
    \item Assume \(\gamma<\nicefrac{(\delta+\Gamma)}{(\delta+1)}\). Let \(\boldsymbol{x}=(x,t)\) and \(\boldsymbol{y}=(y,s)\) be two given vertices with \(s<t\) that further satisfy \(|x-y|^d\geq \beta s^{-\gamma}t^{\gamma-1}\). Then we have
        \begin{equation}
           \mathbb{P}_{\boldsymbol{x},\boldsymbol{y}}\Big\{\boldsymbol{x} \overset{2}{\underset{\boldsymbol{x},\boldsymbol{y}}{\rightsquigarrow}}\boldsymbol{y}\Big\}\leq \mathbb{E}_{\boldsymbol{x},\boldsymbol{y}}\big[\sharp\{\boldsymbol{z}=(z,u):u> t\text{ and }\boldsymbol{x}\rightsquigarrow\boldsymbol{z}\rightsquigarrow\boldsymbol{y}\}\big] \leq \beta C \; \mathbb{P}_{\boldsymbol{x},\boldsymbol{y}}\{\boldsymbol{x}\rightsquigarrow\boldsymbol{y}\}
        \end{equation}
    as well as
        \begin{equation}
           \mathbb{P}_{\boldsymbol{x},\boldsymbol{y}}\Big\{\boldsymbol{y}\overset{2}{\underset{\boldsymbol{x},\boldsymbol{y}}{\rightsquigarrow}}\boldsymbol{x}\Big\}\leq \mathbb{E}_{\boldsymbol{x},\boldsymbol{y}}\big[\sharp\{\boldsymbol{z}=(z,u):u> t\text{ and }\boldsymbol{y}\rightsquigarrow\boldsymbol{z}\rightsquigarrow\boldsymbol{x}\}\big] \leq \beta C \; \mathbb{P}_{\boldsymbol{x},\boldsymbol{y}}\{\boldsymbol{y}\rightsquigarrow\boldsymbol{x}\},
        \end{equation}
    where in both cases \(C=\tfrac{2^{d\delta+1}\omega_d \delta}{d(\delta-1)(\delta(1-\gamma)+\gamma-\Gamma)}\).
    \item If \(\gamma>\nicefrac{(\delta+\Gamma)}{(\delta+1)}\), we choose the two constants
        \[
            \alpha_1\in\big(1,\tfrac{\gamma-\Gamma}{\delta(1-\gamma)}\big) \text{ and then }\alpha_2\in\big(\alpha_1, \tfrac{\alpha_1(\gamma\delta-1)+\gamma-\Gamma}{\delta-1}\big).
        \]
    Let \(\boldsymbol{x}=(x,t)\) be a given vertex with \(t<\nicefrac{1}{2}\) and define the event 
    \[
        \mathcal{E}(\boldsymbol{x})=\Big\{\exists\boldsymbol{y}=(y,s):s<t^{\alpha_1}, |x-y|^d < t^{-\alpha_2} \text{ and } \boldsymbol{x} \overset{2}{\underset{\boldsymbol{x},\boldsymbol{y}}{\rightsquigarrow}}\boldsymbol{y} \Big\}.
    \]
    For all \(\beta>0\) there exists some \(a>0\) such that
    \begin{equation*}
        \mathbb{P}_{\boldsymbol{x}}\big(\mathcal{E}(\boldsymbol{x})\big) \geq 1-\exp(-t^{-a}).
    \end{equation*}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:48:02.407980+00:00","domain":"probability theory","id":"claim_468e21ecd20f54e0695ca6e66cb13a98a5361ce2c20055418441252d75d2f231","kind":"theorem","schema_version":1,"statement":"[Prop torus-heights of arXiv:2608.26564, 'Real ideal points, Conway spheres, and left-orderable Dehn fillings'] Let $\theta_{n,j} = \frac{(2j+1)\pi}{2n+1}$, and $r=r_{n,j} = 2\cos\theta_{n,j}-2$ be a real root of $P_n$. Then we have
\begin{equation*}
	\rho_r(l_{1,n}^{tor}) = A_r = \begin{pmatrix}1&0 \\r&1\end{pmatrix} \ \ \ \ \ \rho_r(l_{2,n}^{tor}) = -B_r^{4n+2} = -\begin{pmatrix}1&4n+2\\0&1\end{pmatrix}
\end{equation*}
In particular, the central signs are $(+1, -1)$, and the transverse parameters are $(r, 4n+2)$. Let $\widetilde\rho_{n,j}: Q_n^{tor} \to \widetilde{PSL}_2(\mathbb R)$ be the meridian-normalized lift of $\bar\rho_r$, and put $\widetilde\rho_{n,j} = \widetilde{\bar\rho}_{n,j} \circ q_n$. Then
\begin{equation*}
	\mathrm{trans}(\widetilde\rho_{n,j}(l_{1,n}^{tor})) = 0 \ \ \ \ \ \mathrm{trans}(\widetilde\rho_{n,j}(l_{2,n}^{tor})) = 2j+1
\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:34:45.725537+00:00","domain":"probability theory","id":"claim_4693f5f67531963e345defaf245d3b40269d03d5a8cb516ff7ca656f2839d969","kind":"theorem","schema_version":1,"statement":"[Prop Prop-Parabolic-Iteration of arXiv:2609.01964, 'The critical exponent for the two-dimensional semilinear wave equation with strong damping'] Assume that, for some $A_j,B_j>0$ and $\nu_j\in\mathbb R$,
	\begin{align*}
		\mathcal W(\xi,\eta)\geqslant A_j\eta^{-\nu_j}
	\end{align*}
	whenever
	\begin{align}
		\eta\geqslant B_j\ \ \mbox{and}\ \ \eta^2\leqslant\xi\leqslant2\eta^2.
	\end{align}
	Put $q_j:=p\nu_j+p-4$. Then there exist $A_{j+1},B_{j+1}>0$ such that
	\begin{align*}
		\mathcal W(\alpha,\beta)\geqslant A_{j+1}\times
		\begin{cases}
			\beta^{-\frac{q_j}{2}}&\mbox{if}\ \ q_j>0,\\
			\log\beta&\mbox{if}\ \ q_j=0,\\
			\beta^{-q_j}&\mbox{if}\ \ q_j<0,
		\end{cases}
	\end{align*}
	for $(\alpha,\beta)\in\mathcal P_{B_{j+1}}$. In particular, if $q_j>0$, then
	\begin{align}
		\nu_{j+1}=\frac p2\nu_j+\frac{p-4}{2}.
	\end{align}","status":"unverified"}

