{"assumptions":[],"created_at":"2026-10-26T20:46:26.258660+00:00","domain":"probability theory","id":"claim_470c20545baacf870ec176bace5fdb40e247b9398d337b2881886d2e0197e151","kind":"lemma","schema_version":1,"statement":"[Lem 83 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] Set $r_n=n^{\theta},\theta>0$.
  Let $\varepsilon_n>0$ be a sequence satisfying $\varepsilon_n\to 0$ and $n\varepsilon_n\to \infty$.
  Then, for an arbitrary $\delta>0$, we have
  \begin{align*}
    \sup_{x\in \R}\mu_n^{(r_n)}((x-\varepsilon_n,x+\varepsilon_n))\lesssim \varepsilon_n+\varepsilon_n n^{\left(\frac{1+\theta}{\alpha}+\delta\right)(1-\alpha)}+\sqrt{\frac{\varepsilon_n v_n\log n}{n}}+n^{\frac{1+\theta}{\alpha}-1+\delta}\log n,\qquad \bbP\rm{-a.s.}
  \end{align*}
  where
  \begin{align*}
    v_n=
    \begin{dcases}
      n^{\left(\frac{1+\theta}{\alpha}+\delta\right)(2-\alpha)}, & \alpha\in (1,2),\\
      \log n, & \alpha=2,\\
      1, & \alpha>2. 
    \end{dcases}
  \end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:52:57.735763+00:00","domain":"probability theory","id":"claim_470f10dfe954300fb92ca4525c81f5924efdd107183211e641bdd64682427ea8","kind":"lemma","schema_version":1,"statement":"[Lemma 28 of arXiv:2609.02755, 'The Sharp Rate of Probabilistically Strong Convergence to the KPZ Equation'] Let $0 < \gamma < |\fs|$, let $N \geq 0$ be an integer, and let $G$ be a kernel on $\mbR \times \mbR$, smooth away from the origin, satisfying for all multi-indices $|k|_\fs \leq N + 1$
	\begin{equ}
		|D^k G(z)| \lesssim |z|_\fs^{-\gamma - |k|_\fs}\;.
	\end{equ}
	Let $(\varrho_\eps)_{\eps \in (0,1]}$ be a family of functions such that $\|\varrho_\eps\|_{L^1} \lesssim 1$.
	Then the following assertions hold:
	\begin{enumerate}
		\item  If $\|\varrho_\eps\|_{L^\infty} \lesssim \eps^{-|\fs|}$, then for all $z \in \mbR \times \mbR$,
		\begin{equ}
			|G \ast \varrho_\eps(z)| \lesssim \eps^{-\gamma}\;.
		\end{equ}
		\item  If $\varrho_\eps$ is supported in $\{|z|_\fs \leq \eps\}$ and satisfies
		\begin{equ}
			\int_{\mbR \times \mbR} z^k\, \varrho_\eps(z)\, dz = 0 \quad \text{for all } |k|_\fs < N\;,
		\end{equ}
		then for $|z|_\fs > 2\eps$
		\begin{equ}
			|G \ast \varrho_\eps(z)| \lesssim \eps^{N} |z|_\fs^{-\gamma - N}\;. 
		\end{equ}
	\end{enumerate}","status":"unverified"}

