    \js{This is a corollary to (prop:cdtn-proper-zcoup of the paper) too, I think: if (i) and (ii) above are fulfilled, then the condition of (prop:cdtn-proper-zcoup of the paper) is fulfilled too. Indeed, for $y \in \operatorname{spt} \nu \setminus \left\{0\right\}$, if we can find $x \in \operatorname{spt} \mu$ with $\langle{x,y}\rangle>0$, then we can find a small ball around $x$ that is contained in $H_+(y,\epsilon)$ for some small $\epsilon > 0$, and since $H_+(y,\epsilon)$ is a cone, its $\mu$-mass must be infinity because of (ii) above.} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:43:44.249743+00:00","domain":"probability theory","id":"claim_477ca086e80eeb5c3786dd69748c047515dce8273d8945ba37739ead1e1f7bb0","kind":"concept","schema_version":1,"statement":"[Lemma 33 of arXiv:2604.15191, 'Quantitative Stability of Many-Marginal Schr\"odinger Bridge'] For any $k\in\mb N$ and $\alpha\in(0, 1)$, $t\mapsto \psi_t$ is a continuous map from $[0, 1]$ to $\m C^{k+2,\alpha}(\mb T^d)$. As a result, the map $t\mapsto \phi_t$ is also smooth. Moreover, $\dot\psi_t$ satisfies the following uniform elliptic PDE,
\begin{align*}
\nabla\cdot\Big[\rho_0^\mu\big(x - \nabla\psi_t(x)\big) \cof\big(I_d - \nabla^2\psi_t(x)\big) \nabla u(x)\Big] = -\partial_t\rho_t^\mu(x).
\end{align*}
Here, for a positive definite matrix $A$, we let $\cof(A) \coloneqq \det(A)A^{-1}$ be the cofactor matrix of $A$.
\myqed (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:28:53.687135+00:00","domain":"probability theory","id":"claim_477e2786daa3395d13b167321666f4593afb2a9add2299970092a4a7f9767731","kind":"lemma","schema_version":1,"statement":"[Lemma 23 of arXiv:2605.13648, 'Sticky CIR process with potential: invariant measure and exact sampling'] \label[lemma]{lem:density-bound}
Let $\delta \in (1,2)$ and $\alpha=1/h$.  There are $C,h_0>0$, depending only on the model parameters, such that the driftless kernel's one-step probability of landing in a near-boundary layer is bounded uniformly in the starting point,
\begin{equation}
  \sup_{x\ge0} P_x^{G=0}\bigl(u_{T_\alpha}\in(0,\epsilon]\bigr)\ \le\ C\,\epsilon^\delta,
  \qquad 0<\epsilon\le 2\sqrt h,\ \ h\le h_0 .
\end{equation}
Consequently, if $G'\in C_{\mathrm b}([0,\infty))$, then $\mathcal{R}_h\subseteq(0,\|G'\|_\infty h]$ gives the one-step routing bound $\sup_{x\ge0}K_h(x,\mathcal{R}_h)=O(h^\delta)$; and for any stationary distribution $\pi_h$ of $K_h$ (\cref{thm:ula-exists}), stationarity gives $\pi_h(\mathcal{R}_h)\le\sup_{x\ge0}K_h(x,\mathcal{R}_h)=O(h^\delta)$.","status":"unverified"}

