{"assumptions":[],"created_at":"2026-10-26T19:29:00.766201+00:00","domain":"probability theory","id":"claim_47a0c53b243f922cb76ba1a5b9687b05337ee8389ae24b21fab2ec6c26a7e2df","kind":"definition","schema_version":1,"statement":"[Definition 24 of arXiv:2512.04807, 'Existence and uniqueness of the canonical Brownian motion in non-simple conformal loop ens'] Suppose that we have the setup described above, and $\rform{\cdot}{\cdot}{\Gamma} = (\rformres{V}{\cdot}{\cdot}{\Gamma})_{V \in \metregions} = ((\rformres{V}{\cdot}{\cdot}{\Gamma}, \rfdomainres{V}{\Gamma}))_{V \in \metregions}$ is a random family of resistance forms on $\ol{V} \cap \Upsilon_\Gamma$ for $V \in \metregions$, respectively, coupled with~$\Gamma$ (it is not required that they are determined by $\Gamma$). We say that $\rform{\cdot}{\cdot}{\Gamma}$ is a weak \clekp{} resistance form if the following properties are satisfied almost surely.

\begin{enumerate}[(i)]
\item The resistance metric associated with $(\rformres{C}{\cdot}{\cdot}{\Gamma}, \rfdomainres{C}{\Gamma})$ is continuous with respect to $\dpathY$.

\item Let $U \subseteq \C$ be open, simply connected.  The conditional law of the collection $( \rformres{V}{\cdot}{\cdot}{\Gamma})_{V \in \metregions[U]}$ given $\Gamma \setminus \Gamma_{U^*}$ and $(\rformres{V'}{\cdot}{\cdot}{\Gamma})_{V' \in \metregions[\C \setminus \ol{U}]}$ is almost surely measurable with respect to $U^*$.

\item Let $U \subseteq \C$ be open, simply connected. There exists a probability kernel $\mu^{U^*}$ such that for each $z \in \C$, the conditional law of $(\rformres{V}{\cdot}{\cdot}{\Gamma})_{V \in \metregions[U+z]}$ given $(U+z)^*$ is $(T_z)_* \mu^{U^*}(\cdot - z)$ where $T_z \CE(f,f) = \CE(f(\cdot +z),f(\cdot +z))$ denotes translation by $z$.

\item Suppose that $V,V' \in \metregions$, $V \subseteq V'$, such that for every $u \in V' \setminus V$ there is a point $z \in \ol{V}$ that separates $u$ from $V$ in $\ol{V'} \cap \Upsilon_\Gamma$. Let $f\colon \ol{V'} \cap \Upsilon_\Gamma \to \R$ be a continuous function that is constant on each $\dpathY$-connected component of $\ol{V'} \cap \Upsilon_\Gamma \setminus \ol{V}$. Then
\begin{align*}
 & f \in \rfdomainres{V'}{\Gamma} \text{ if and only if } f|_V \in \rfdomainres{V}{\Gamma} \\
 \text{and}\quad & \rformres{V'}{f}{f}{\Gamma} = \rformres{V}{f}{f}{\Gamma} .
\end{align*}

\item Suppose that $V_1,V_2 \in \metregions$ with $\ol{V_1} \cap \ol{V_2} = \{z\}$ (where the closure is taken with respect to $d_{\ol{V}}$, see Section~\ref{subsec:main_results}). Then
 \begin{align*}
  \rfdomainres{V_1 \cup V_2}{\Gamma} &= \{ f : f|_{V_1} \in \rfdomainres{V_1}{\Gamma},\, f|_{V_2} \in \rfdomainres{V_2}{\Gamma} \} \\
  \text{and}\quad
  \rformres{V_1 \cup V_2}{f}{f}{\Gamma} &= \rformres{V_1}{f}{f}{\Gamma} + \rformres{V_2}{f}{f}{\Gamma} .
 \end{align*}

\item Suppose that $V \in \metregions$ consists of a single connected component and let $\CL \in \Gamma$ be a loop contained in $\ol{V}$ and intersecting $\partial V$. Let $a,b \in \CL \cap \partial V$ be distinct, let $V_{a,b}$ (resp.\ $V_{b,a}$) be the collection of components of $V \setminus \CL$ that are connected to the counterclockwise arc of $\partial V$ from $a$ to $b$ (resp.\ from $b$ to $a$) by an admissible path within $V$ (see Figure~\ref{fi:cut_loop}). Then
 \begin{align*}
  \rfdomainres{V}{\Gamma} &= \{ f : f|_{V_{a,b}} \in \rfdomainres{V_{a,b}}{\Gamma},\, f|_{V_{b,a}} \in \rfdomainres{V_{b,a}}{\Gamma} \} \\
  \text{and}\quad
  \rformres{V}{f}{f}{\Gamma} &= \rformres{V_{a,b}}{f}{f}{\Gamma} + \rformres{V_{b,a}}{f}{f}{\Gamma} .
 \end{align*}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:57:20.586138+00:00","domain":"probability theory","id":"claim_47a13cdd32e2e367425b7dfe4a79521b4d55c8e824031974a8ebb9baf87f3001","kind":"lemma","schema_version":1,"statement":"[Lemma le:BF of arXiv:2411.09949, '$W_{\bf d}$-convergence rate of EM schemes for invariant measures of supercritical stable '] Let $\alpha\in(\frac{1}{2},2)$ and $X,\xi$ be two independent random variables with
 $$\mathbb{E}(|X|^{\varsigma}+|\xi|^\varsigma)<\infty,\quad \forall \varsigma\in(0,\alpha).$$
Then for any $\ell\in(0,1)$, there is $C=C(\varsigma,\Theta)>0$ such that

(1) if $\alpha\in(\frac{1}{2},1)$, then for any $\vartheta\in(1-\alpha,\alpha)$ and $\varsigma\in(0,\alpha)$ with $\varsigma+(\gamma\alpha)\wedge \vartheta>1$,
\begin{align}
\mathbb{E}[\left|b(X)\cdot(\nabla f(X+\ell\xi)-\nabla f(X))\right|]\leqslant C\left(\ell^{\gamma\wedge\vartheta}+\ell^{\varsigma\gamma-\frac{\varsigma\gamma\alpha}{\varsigma+(\gamma\alpha)\wedge\vartheta}}\right).
\end{align}

(2) if $\alpha\in[1,2)$, then for any $\vartheta\in(0,1)$ and $\varsigma,\varsigma_1\in(0,1)$ with
$\varsigma+(\gamma\varsigma_1)\wedge\vartheta>\alpha, \
\varsigma_1(1+\vartheta)<\alpha$,
\begin{align}
\mathbb{E}[\left|b(X)\cdot(\nabla f(X+\ell\xi)-\nabla f(X))\right|]\leqslant C\left(\ell^{\gamma\wedge\vartheta}+\ell^{\varsigma\gamma-\frac{\varsigma\gamma\alpha}{\varsigma+(\gamma\varsigma_1)\wedge\vartheta}}\right).
\end{align}
\quad\quad\quad  Specially, if $\alpha\in(1,2)$, (equation ineq3 of the paper) also holds with $\vartheta=1$ and $\varsigma=1$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:09:34.473635+00:00","domain":"probability theory","id":"claim_47a1fe147aed64f3df324e3bd2b6897149f653ac7d305546c55ee341f9f33345","kind":"lemma","schema_version":1,"statement":"[Lemma lem:primitlgamma of arXiv:2505.12187, 'Speeding up quantum Markov processes through lifting'] Let $\mathcal{L}_S$ be given in (equation def:lsbip of the paper) for a primitive QMS generator $\mathcal{L}^A$. Suppose that (asspA2 of the paper) holds. Then, it holds that
\begin{align*}
   \mathcal{F}(\mathcal{L}_S) = \ker(\mathcal{L}^A) \otimes \mathcal{M}_B = {\bf 1}^A  \otimes \mathcal{M}_B\,,
\end{align*}
and 
\begin{equation*}
    \mathcal{F}(\mathcal{L}_\gamma) =  \mathcal{F}(\mathcal{L}_S)\cap \{X \in \mathcal{M}_{AB}\,;\ [H, X] = 0\}\,.
\end{equation*}
    Moreover, suppose that (condeq:php of the paper) holds. Then, 
    \begin{align*}
       \mathcal{F}(\mathcal{L}_\gamma) = {\bf 1}^A  \otimes \left\{X^B \in \mathcal{M}_B\,;\ \left[G_j^B, X^B\right] = 0 \ \text{for all $j \ge 1$}  \right\}\,.
    \end{align*}
    The condition $\dim \mathcal{F}(\mathcal{L}_S) > \dim \mathcal{F}(\mathcal{L}_\gamma)$ is equivalent to that $\{G_j^B\}_{j \ge 1}$ are not all zero.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:40:22.352488+00:00","domain":"probability theory","id":"claim_47a2e0f4fadb98fc485a6cd334119f52e133570f368be325562a08f51b1e1497","kind":"definition","schema_version":1,"statement":"[Definition def:ci of arXiv:2506.03999, 'Large deviations for scaled families of Schr\"odinger bridges with reflection'] An element $\pi \in \Pi (\mu, \nu)$ is called \textit{$(c,\ve)$-cyclically invariant} if $\pi$ is equivalent to $m$ and there is a version of the Radon-Nikodym derivative $d\pi/dm$ such that
\begin{align}

    \prod_{i=1}^k \frac{d \pi }{d m}(x_i, y_i) = \exp \left\{ -\frac{1}{\ve}\left(\sum_{i=1}^k c(x_i, y_i) - c(x_i, y_{i+1})\right) \right\} \prod_{i=1}^k \frac{d \pi}{d m}(x_i, y_{i+1}),    
\end{align}
for all $k \in \bN$, $\{ (x_i, y_i ) \} _{i=1} ^k \subseteq \calX \times \calY$, where $y_{k+1}$ is interpreted as $y_1$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:48:27.276500+00:00","domain":"probability theory","id":"claim_47a38c1308936bd57fbc850224f1e5fd2d8ec45419dbacaeaf5dca64b59d278c","kind":"concept","schema_version":1,"statement":"[Lem 18 of arXiv:2604.24624, 'Limit distributions of the threshold radius for the maximum degree and the associated poin'] Assume that $n, k \in \BN$ and $p \in (0,1)$.
