{"assumptions":[],"created_at":"2026-10-27T22:20:15.718116+00:00","domain":"probability theory","id":"claim_47b98015fe162c1ac8f9b92d0329069035b3fd9da8663101a31f849f26a55f48","kind":"lemma","schema_version":1,"statement":"[Lemma lemma_splitting_different_R_j of arXiv:2609.00973, 'The Vlasov-Maxwell point charge system : study of the spherically symmetric case'] Let $(t,r,\ell)\in [T_0,\infty)\times\R^*_+\times\R_+$ be fixed and 
    \begin{equation}

        A:=F^{-1}(r-\hbar),\qquad \hbar:=\frac{C}{t^4}\frac{r^2}{(r+1+\sqrt{\ell})^2},
    \end{equation}
    where $F^{-1}$ denotes the inverse function of $F(a):=\frac{a^0+\sqrt{m^2+\ell a^2}}{a^2}=\kappa p +p$ and $C>0$ is a constant depending only on $m$.
    We consider the subspaces 
    \begin{equation*}
        \begin{array}{c}
             \displaystyle\mathcal{R}_0:=\{(\theta,a)\in \R\times\R^*_+\,|\, a\leq A\}, \vspace{5pt}\\
              \displaystyle\mathcal{R}_1:=\{(\theta,a)\in \R\times\R^*_+\,|\, a> A,\,\theta< -t\widehat a\},\quad \mathcal{R}_2:=\{(\theta,a)\in \R\times\R^*_+\,|\, a> A,\,\theta> -t\widehat a\}.
        \end{array}
    \end{equation*}
    In $\mathcal{R}_0$, for any fixed $\theta\in\R$, there exists at most one $a:=\aleph(\theta;t,r,\ell)$ solution to (equation equation_curve_R_r of the paper). Moreover, it satisfies 
    \begin{equation}

        |\partial_a\widetilde{R}(\theta,\aleph)|\geq \frac{3m}{4\aleph^3}.
    \end{equation}
    In $\mathcal{R}_1$ (resp. $\mathcal{R}_2$) for each $a>A$, there exists a unique $\theta:=\theta_1(a;t,r,\ell)$ (resp. $\theta:=\theta_2(a;t,r,\ell)$) solution to (equation equation_curve_R_r of the paper). Moreover, we have the following estimates
    \begin{equation}

        \frac{1}{|\partial_\theta\widetilde{R}(\tau_j,a)|}\lesssim t^3 \frac{a^2}{a^0}+t^2\left(a|\theta_j|+\sqrt{\ell}(1+a)+a^{-1}+a\right),\qquad j=1,2.
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:55:18.053167+00:00","domain":"probability theory","id":"claim_47b9fdedb850a0e1fef412239e160ebfbfdec4cf0cd5db69019be1e466a7df29","kind":"lemma","schema_version":1,"statement":"[Lemma 37 of arXiv:2606.16164, 'A Low-Regularity Semigroup Sewing Lemma via Quotient Structures'] Let $0<\sigma<1$, $\beta>0$, and define $N_h:=h^{-\sigma/2}$ for $0<h\le1$.  Then there are constants $C,c>0$ such that for all $x\in H^{\alpha+\beta}$,
\begin{equation}

\norm{P_{>N_h}x}_{H^\alpha}
\le
C h^{\sigma\beta/2}
\norm{x}_{H^{\alpha+\beta}},
\end{equation}
and for all $x\in H^\alpha$,
\begin{equation}

\norm{S_h^{-1}P_{\le N_h}x}_{H^\alpha}
\le
\exp(c h^{1-\sigma})
\norm{x}_{H^\alpha}.
\end{equation}
Here $S_h^{-1}P_{\le N_h}$ is defined spectrally on the finite-dimensional range of $P_{\le N_h}$.","status":"unverified"}

