{"assumptions":[],"created_at":"2026-10-27T18:44:24.712428+00:00","domain":"probability theory","id":"claim_4829c177542e490f781a4a03fea49cbaa813cfe53c67270d26fca85d66dcc1ba","kind":"lemma","schema_version":1,"statement":"[Lemma lem:hankel_clt of arXiv:2604.20215, '\bf Edge Universality for Inhomogeneous Random Matrices II: Markov Chain Comparison and Cr'] For
  a Hankel-profile random matrix  $X_N$ with an $\alpha$-stable profile $f$ as in Definition~(def:alpha_profile of the paper),  let $p_n(x,y)$ be the $n$-step transition probability on $\mathbb{T}_L^d$. Suppose that  $W \ll L$ and   $n (W/L)^\alpha \to \tau$ as $N \to \infty$, the following asymptotics hold.
\begin{enumerate}
    \item[(i)] \textbf{Even steps ($n=2k$):} The transition probability is concentrated around $y = x$,
    \begin{equation}
        p_{2k}(x, y) = \frac{1}{L^d} \theta_\alpha\Big( \frac{y-x}{L}, 2k \big(\frac{W}{L}\big)^\alpha \Big) + O(k e^{-c W^\alpha}).
    \end{equation}
    \item[(ii)] \textbf{Odd steps ($n=2k+1$):} The transition probability is concentrated around $y = x_0 - x$,
    \begin{equation}
        p_{2k+1}(x, y) = \frac{1}{L^d} \theta_\alpha\Big( \frac{y+x-x_0}{L}, (2k+1) \big(\frac{W}{L}\big)^\alpha \Big) + O(k e^{-c W^\alpha}).
    \end{equation}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:51:11.535845+00:00","domain":"probability theory","id":"claim_482bd54f2171bd197150c3bc273cf99bf28e5e0fdc59db5ec4a8171bf3613ee8","kind":"definition","schema_version":1,"statement":"[Definition 4 of arXiv:2609.02610, 'The frame set of the first Hermite function'] A set $\Lambda\subset\R$ is
  \emph{relatively separated} if it contains only a uniformly bounded number
  of points in every interval of length one, i.e.,
  \begin{equation}
    \sup_{t\in\R}\#\bigl(\Lambda\cap[t,t+1]\bigr)<\infty.
  \end{equation}
  For $\delta>0$, the set $\Lambda$ is called
  \emph{$\delta$-separated} if
  \begin{equation}
    |\lambda-\mu|\geq\delta
    \quad\text{whenever }\lambda,\mu\in\Lambda\text{ and }\lambda\neq\mu.
  \end{equation}","status":"unverified"}

