{"assumptions":[],"created_at":"2026-10-27T05:33:17.672927+00:00","domain":"probability theory","id":"claim_484039a2e962212aa9214b3be138165f63c70c9198b778a4eec906c22a24c0a5","kind":"definition","schema_version":1,"statement":"[Definition 17 of arXiv:2607.10725, 'From the Airy line ensemble to the Gaussian free field'] Fix $\ell \geq 1$. In what follows, indices are understood modulo $\ell$; in particular, we identify $\ell+1$ with $1$. Define
\begin{equation}
\calI_T(t_1, x_1; \ldots; t_\ell, x_\ell) = \int_{Tx_1}^\infty \diff y_1 \cdots \int_{Tx_\ell}^\infty \diff y_\ell \prod_{j=1}^\ell \widetilde{K}(T^{1/2} t_j, y_j; T^{1/2} t_{j+1}, y_{j+1}),
\end{equation}
where $\widetilde{K}$ is as in \eqref{Eq.ExtendedAiryKernel}. We also define $\calI(t_1,x_1) = 0$ and for $\ell \geq 2$
\begin{equation}
\calI(t_1, x_1; \ldots; t_\ell, x_\ell) = \frac{1}{(2\pi\im)^\ell} \int_{\overline{\crit(t_1, x_1)}}^{\crit(t_1, x_1)} \diff z_1 \cdots \int_{\overline{\crit(t_\ell, x_\ell)}}^{\crit(t_\ell, x_\ell)} \diff z_\ell \prod_{j=1}^\ell \frac{1}{z_j - z_{j+1}},
\end{equation}
where we recall from \eqref{Eq.RootsOfS} that $\crit(t,x) = t + \im \sqrt{-x}$. Lastly, define 
\begin{equation*}
P(t_1, x_1; \ldots; t_\ell, x_\ell) = \sum_{\substack{\sigma\in S_{\ell}\\ \sigma\textup{ has no fixed points}}}
\sign(\sigma) \prod_{\substack{(i_1\,\cdots\, i_\ell)\\ \textup{cycle of }\sigma}} \calI(t_{i_1},x_{i_1};\ldots;t_{i_\ell},x_{i_\ell}),
\end{equation*}
where the product is taken over cycles in the cycle decomposition of $\sigma$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:39:12.321255+00:00","domain":"probability theory","id":"claim_484091a624e2c265b4c6f9981cb949ebab2b5f58ed50425e32220a6734d70e44","kind":"definition","schema_version":1,"statement":"[Definition def:results:gibbs of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] For $n \in \ensuremath{\mathbb{N}}$, $n > 2$, define the \emph{Gibbs measure} $\theta^n \in \mathcal{P}((\ensuremath{\mathbb{R}}^d)^{V_n})$ by
\begin{equation}
    \theta^n(d\mathbf{x}^{(n)}) := \frac{1}{\mathcal{Z}^n} \exp\bigg( - \frac{1}{2}\sum_{(u, v) \in E_n} Q(x_u, x_v)\bigg)  d\mathbf{x}^{(n)},

\end{equation}
where $Q$ is given by  
\begin{equation}
    Q(x, y) := U(x) + U(y) + 2W(x - y), \quad x, y \in \ensuremath{\mathbb{R}}^d,

\end{equation}
and $\mathcal{Z}^n$ is the associated normalization constant or \emph{partition function}:
\begin{equation}
    \mathcal{Z}^n := \int_{(\ensuremath{\mathbb{R}}^d)^{V_n}} \exp\bigg( - \frac{1}{2}\sum_{(u, v) \in E_n} Q(x_u, x_v)\bigg) d\mathbf{x}^{(n)}.

\end{equation}
Note that if $(U, W)$ satisfy Assumption (as:results:invMeasure of the paper), then $\mathcal{Z}^n$ is finite and $\theta^n$ has finite moments of all orders.","status":"unverified"}

