{"assumptions":[],"created_at":"2026-10-27T08:18:19.223911+00:00","domain":"probability theory","id":"claim_489ab39962fd2690fcc0af9cf4e81f49373efc27ed61ce44b21cbd308411aed5","kind":"definition","schema_version":1,"statement":"[Definition 9 of arXiv:2608.29086, '2608.29086'] [$HOLE(\psi)$]
