{"assumptions":[],"created_at":"2026-10-27T21:49:15.411917+00:00","domain":"probability theory","id":"claim_493837a1ca681295d142b6d7b12735676614bca0eab165ccb7b0e09fefa60fad","kind":"lemma","schema_version":1,"statement":"[Lemma lem:nonlinear_epoch_bootstrap of arXiv:2608.27313, 'A Finite Sample Analysis for Quantile Temporal Difference Learning in Distributional Reinf'] Let $\mu>0$, $r_0>0$, $L_h\ge0$, and let
$\{\alpha_t\}_{t=n}^{N-1}$ be nonincreasing with
$0\le\mu\alpha_t\le1$. Suppose matrices ${\bm{P}}_t$ satisfy
\begin{equation*}
    {\bm{P}}_t\ge\bm0,
    \qquad
    \left\|{{\bm{P}}_t}\right\|_\infty\le1-\mu\alpha_t.
\end{equation*}
Set ${\bm{\Phi}}_{k,k}\coloneq{\bm{I}}$ and, for $r<k$, write
\begin{equation*}
    {\bm{\Phi}}_{r,k}\coloneq{\bm{P}}_{k-1}\cdots{\bm{P}}_r.
\end{equation*}
Suppose, up to the first exit of ${\bm{e}}^{(t)}$ from the $r_0$-ball,
\begin{equation}
    {\bm{e}}^{(t+1)}
    ={\bm{P}}_t{\bm{e}}^{(t)}+{\bm{\zeta}}^{(t+1)}-\alpha_t{\bm{R}}({\bm{e}}^{(t)}),
    \qquad
    \left\|{{\bm{R}}({\bm{e}})}\right\|_\infty\le L_h\left\|{{\bm{e}}}\right\|_\infty^2,
\end{equation}
and, for every $n\le r<k\le N$,
\begin{equation}
    \norm{\sum_{t=r}^{k-1}{\bm{\Phi}}_{t+1,k}{\bm{\zeta}}^{(t+1)}}_\infty
    \le b.
\end{equation}
If
\begin{equation}
    \norm{{\bm{e}}^{(n)}}_\infty\le\frac{r_0}{2},
    \qquad
    \frac{L_hr_0}{\mu}\le\frac1{16},
    \qquad
    b\le\min\left\{\frac{r_0}{16},\frac{\mu}{64L_h}\right\},
\end{equation}
where the second fraction is $+\infty$ if $L_h=0$, then no exit occurs
through time $N$, and
\begin{equation}
    \norm{{\bm{e}}^{(N)}}_\infty
    \le C\left[
    r_0\exp\left\{-\frac{\mu}{C}\sum_{t=n}^{N-1}\alpha_t\right\}
    +b+\frac{L_h}{\mu}b^2\right]
\end{equation}
for a universal constant $C$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:48:25.213614+00:00","domain":"probability theory","id":"claim_493917556030aae831313458d8acdaa9d4ba3c2a216fb5d32da9d5d116982cb1","kind":"lemma","schema_version":1,"statement":"[Lemma lem:countfluc of arXiv:2607.05671, 'Bi-infinite systems of singularly interacting Brownian particles and the KPZ equation'] Let $\{x_i\}_{i \in \mathbb{Z}} \sim \gamma_1$. Fix $T \in [0,\infty)$ and $\theta \in (0,1)$. For $(w,t_0) \in \mathbb{R} \times [0,T]$, let 
\begin{equation}
\Theta(w,t_0, \theta) \equiv \Theta(w,t_0) = \left[ w - \varepsilon^{\frac{1}{4\theta}}, w + \varepsilon^{\frac{1}{4\theta}} \right] \times \left[ t_0, t_0 + \varepsilon \right].
\end{equation}
There exists $\varepsilon_0 \in (0,1)$ and $C_1, C_2, C_3 \in [0,\infty)$ such that for all $\varepsilon \in (0,\varepsilon_0]$, $w \in \mathbb{R}$, $t_0 \in [0,T]$,  
\[
\begin{split}
& \mathbb{P}\left( \sup_{(x,t) \in \Theta(w,t_0)} \left| N_\varepsilon(t,x-\sigma\varepsilon^{-1/4}t) - N_\varepsilon(t_0,w - \sigma\varepsilon^{-1/4}t_0) \right| \geq \ell \right) \\
& \leq C_1 \left( \varepsilon^{-\frac{1}{2} - (\frac{1}{4\theta} \wedge \frac{3}{4})}  + \varepsilon^{-(\frac{1}{4\theta} \wedge \frac{3}{4})} (|w| + 1)\right) \left[ \exp( -C_2 \ell \log( \varepsilon^{\frac{1}{2} - (\frac{1}{4\theta} \wedge \frac{3}{4})} \ell) ) + \exp( - C_2 \ell \log \ell )\right],
\end{split}
\]
for all $\ell \geq \ell_0(\varepsilon) := (C_3\varepsilon^{-\frac{1}{2} + (\frac{1}{4\theta} \wedge \frac{3}{4}})\vee 4$.

Furthermore, for all $r \geq 1$, there exists a $d=d(r)>0$ and $\varepsilon_0 = \varepsilon_0(r)  \in (0,1)$, such that
\begin{equation}
\begin{split}
\sup_{w \in \mathbb{R}} \sup_{\varepsilon \in (0,\varepsilon_0]} \frac{\varepsilon^{-\frac{1}{4}[(\frac{1}{\theta} - 1) \wedge \frac{1}{2}]}}{(|w| + 1)^{d}} \left\| e^{\sigma \varepsilon^{1/4}  \sup_{(x,t) \in \Theta(w,t_0)} \left| N_\varepsilon(t,x-\sigma\varepsilon^{-1/4}t) - N_\varepsilon(t_0,w - \sigma\varepsilon^{-1/4}t_0) \right|} -1 \right\|_r
\end{split}
\end{equation}
 is finite for $t_0 \in [0,T]$.","status":"unverified"}

