{"assumptions":[],"created_at":"2026-10-27T06:48:43.550044+00:00","domain":"probability theory","id":"claim_49d473ca8b4d20b0841f705c1a20d99cedd7b88b9574f9f18c0c081dc8483dc9","kind":"definition","schema_version":1,"statement":"[Definition 1 (Iterative undirected graph process) of arXiv:2608.07239, 'Unified framework for asymptotically uniform iterative construction of generalised random '] Consider the vertex set $V=\{v_1,\ldots,v_n\}$, consider a degree sequence $\d=(d_1,\ldots,d_n)$ of non-negative integers with $2m:=d_1+\ldots+d_n>0$ even, and consider a set $X$ of forbidden edges.
		\begin{itemize}
			\item Start with no edges $E_0=\emptyset$.
			\item For $r=0,\ldots,m-1$, let $d_{i,r}$ denote the degree of vertex $v_i$ in $(V,E_r)$, and consider those pairs of vertices $v_i,v_j\in V$ with $i\neq j$, $d_{i,r}<d_i$, $d_{j,r}<d_j$, and $\{v_i,v_j\}\not\in E_r\cup X$.
			\begin{itemize}
				\item If no such pairs exist, let $E_{r+1}=E_r$.
				\item Otherwise, choose such a pair $v_i,v_j$ at random with probability proportional to $(d_i-d_{i,r})(d_j-d_{j,r})(1-\tfrac{d_id_j}{4m})$, and let $E_{r+1}=E_r\cup\{\{v_i,v_j\}\}$.
			\end{itemize}
			\item Finally, apply rejection sampling to sample $E=E_m$ with $m$ edges.
		\end{itemize}
		This guarantees that $(V,E)$ is a simple undirected graph with degree sequence $\d$ and with no edges from $X$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:58:28.476625+00:00","domain":"probability theory","id":"claim_49d4a28632210f1a9ba70d834ff8d2953b77fb0e105a8f075b8927a448d60abc","kind":"theorem","schema_version":1,"statement":"[Theorem 82 (Oriented Gaussian tensor--Pfaffian spectral transfer) of arXiv:2606.29292, 'Intrinsic Gaussian Tensor Geometry and Random Operator Spectra'] Let $E$ be a separable real Hilbert space and let
$A\in\Sch_2(E)$ be a strongly measurable random skew-adjoint operator.  Let
$(\Xi_{2N})_{N\ge1}$ be jointly realized random exterior forms with
$\Xi_{2N}\in\wedge^{2N}E$.  Assume that there is one event of probability one
on which, simultaneously for all $N\ge1$,
\begin{equation}

 (\alpha_A)^{\wedge N}=\frac{N!}{2^N}\Xi_{2N}.
\end{equation}
Then the following statements hold.

\emph{(i) Exact spectral decoding.}  If $a_1\ge a_2\ge\cdots$ are the positive
skew singular values of $A$, then, on the same event,
\begin{equation}

 e_N(a_1^2,a_2^2,\ldots)=4^{-N}\|\Xi_{2N}\|^2,
 \qquad N\ge1.
\end{equation}
Consequently
\begin{equation}

 \mathscr D_A(z):=\prod_{j\ge1}(1+za_j^2)
 =\sum_{N\ge0}\frac{z^N}{4^N}\|\Xi_{2N}\|^2,
 \qquad
 \det(I+zA^*A)=\mathscr D_A(z)^2.
\end{equation}
In particular, the tower determines the complete multiset of nonzero
positive skew singular values of $A$.  The nonzero spectrum of the
complexification is therefore
$\{\,\pm i a_j:j\ge1,\ a_j>0\,\}$, with the corresponding
multiplicities.

\emph{(ii) Gaussian tensor encoders.}  Fix $2\le\sigma<\infty$ and $\rho>0$.
Either of the following deterministic all-order certificates implies a
weak-Schatten bound.

\emph{(a) Decoupled encoder.}  Suppose that for every $N$ there is
$\mathbf K_{2N}\in\mathfrak T_{2N,\sigma}$, with input space $\C$ and output
space $\wedge^{2N}E$, such that the real-coordinate decoupled evaluator
satisfies
\[
 \Xi_{2N}=\cT_{\mathbf K_{2N}}^{(2N)}.
\]
Set
\begin{equation}

 \mathcal G^{\rm dec}_{\rho,\sigma}
 :=\sup_{N\ge1}N^{1/\rho}
   \|\mathbf K_{2N}\|_{\mathfrak T_{2N,\sigma}}^{1/N}.
\end{equation}
If $\mathcal G^{\rm dec}_{\rho,\sigma}<\infty$, then for every finite $p\ge1$,
\begin{equation}

 \bigl\|\|A\|_{\Sch_{\rho,\infty}}\bigr\|_{L^p}
 \le C_\rho(1+p+\sigma)\mathcal G^{\rm dec}_{\rho,\sigma}.
\end{equation}

\emph{(b) Same-field Wick encoder.}  Suppose instead that one real isonormal
Gaussian process $W$ and kernels
$\mathbf L_{2N}\in\mathfrak W_{2N,\sigma}$ satisfy
\[
 \Xi_{2N}=I_{2N}(\mathbf L_{2N})
 \quad\text{in }L^0(\Omega;\wedge^{2N}E),
\]
where $I_{2N}$ is the common random element furnished by
Proposition~\ref{prop:wick-completion}.  Set
\begin{equation}

 \mathcal G^{\rm W}_{\rho,\sigma}
 :=\sup_{N\ge1}N^{1+1/\rho}
   \|\mathbf L_{2N}\|_{\mathfrak W_{2N,\sigma}}^{1/N}.
\end{equation}
If $\mathcal G^{\rm W}_{\rho,\sigma}<\infty$, then
\begin{equation}

 \bigl\|\|A\|_{\Sch_{\rho,\infty}}\bigr\|_{L^p}
 \le C_\rho(1+p+\sigma)\mathcal G^{\rm W}_{\rho,\sigma},
 \qquad 1\le p<\infty.
\end{equation}
Both estimates are dimension free.

\emph{(iii) Factorial and Fredholm characterizations.}  If $0<\rho<2$, then,
on the probability-one event in \eqref{eq:tensor-pfaffian-compatibility},
\begin{align}
 A\in\Sch_{\rho,\infty}
 &\quad\Longleftrightarrow\quad
 \sup_{N\ge1}
 \left[(N!)^{1/\rho}\|\Xi_{2N}\|\right]^{1/N}<\infty
 \\
 &\quad\Longleftrightarrow\quad
 \sup_{x>0}x^{-\rho/2}\log\mathscr D_A(x)<\infty.

\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:47:53.351973+00:00","domain":"probability theory","id":"claim_49d7197cefc122017bbf99e060e282001bbc5ecbf19cec047d7aabcecf6e1e69","kind":"definition","schema_version":1,"statement":"[Definition 2 of arXiv:2607.15903, 'Uniqueness for nonlinear Fokker-Planck equations with general diffusion terms and their as'] \rm (1) (distributional solution)
Let $d \geqslant 1$ and $T>0$. A function $u \in L_{\text{loc}}^{1}([0,T)\times \mathbb{R}^{d})$ is said to be a distributional solution to NFPE (\ref{1}) with initial condition $u_{0}$ if $a_{ij}(x)\beta(x,u) \in L_{\text{loc}}^{1}([0,T)\times \mathbb{R}^{d})$, $b(x,u)u \in L_{\text{loc}}^{1}([0,T)\times \mathbb{R}^{d};\mathbb{R}^{d})$, and, for all $ \varphi \in C^{\infty}_{0}([0,T)\times \mathbb{R}^{d})$ and $u_{0} \in L^{1}(\mathbb{R}^{d})$,
\begin{equation}
\begin{split}
   \int^{T}_{0} &\int_{\mathbb{R}^{d}} \bigg(u(t,x)\frac{\partial \varphi }{\partial t}(t,x)+\sum\limits_{i,j=1}^{d}a_{ij}(x)\beta(x,u(t,x))D^{2}_{ij}\varphi(t,x)\\+& u(t,x)b(x, u(t,x)) \cdot \nabla \varphi (t,x) \bigg) dxdt +\int_{\mathbb{R}^{d}}u_{0}(x)\varphi(0,x)dx=0.  
\end{split}
\end{equation}
(2) A distributional solution to NFPE (\ref{1}) is called a probability solution to NFPE (\ref{1}) if $u_{0} \in \mathcal{P}(\mathbb{R}^{d})$, and $u(t,\cdot) \in \mathcal{P}(\mathbb{R}^{d})$ for a.e. $t \in (0.T)$. \vspace{0.35em}\\
(3) Let $\mathcal{\tilde P}(\mathbb{R}^{d})$ denote the space of all Borel probability measure on $\mathbb{R}^{d}$. Suppose $ \mathcal{P}_{0} \subset \mathcal{\tilde P}(\mathbb{R}^{d}) $ such that for each $(s, \zeta) \in [0, \infty) \times \mathcal{P}_{0}$, there exists a weakly continuous probability solution $ [s, \infty) \ni t \mapsto \mu_{t}^{s,\zeta} \in \mathcal{P}_{0}$ to NFPE (\ref{1}) with starting time $s \in [0, \infty)$ and initial condition $u_{0}$ renamed as $\zeta$, and $\mu_{t}^{s,\zeta}:=u^{s,\zeta}(t,x)dx$, such that flow property
\begin{equation}
    \mu_{t}^{s, \zeta}=\mu_{t}^{r, \mu_{r}^{s, \zeta}} ,\; \; \forall \; 0 \leqslant s \leqslant r \leqslant t, \;\; \zeta \in \mathcal{P}_{0} \notag
 \end{equation}
holds. Then $ (\mu^{s,\zeta})_{(s,\zeta) \in [0,\infty)\times \mathcal{P}_{0} }$ is called a solution flow of NFPE (\ref{1}) in $ \mathcal{P}_{0} $.","status":"unverified"}

