{"assumptions":[],"created_at":"2026-10-27T14:31:57.826529+00:00","domain":"probability theory","id":"claim_4a00cfbb7e0d60e59303feb404194c9a1281cf5cdb929ec2d3ca8ae0fe0ade04","kind":"concept","schema_version":1,"statement":"[Thma* two and more dimensions of arXiv:2509.19809, 'Exact Limsup Growth of Rarely Visited Sites for One-Dimensional Simple Random Walk'] For $k,n\in{\mathbb N}$, let $Q_k^{(d)}(n)$ denote the number of sites visited exactly $k$ times up to step $n$ in a $d$-dimensional simple random walk $(S_n^{(d)})$ on $\mathbb{Z}^d$. Formally,
$$Q_k^{(d)}(n)=\#\{j:0\le j\le n,\,\xi(S_j^{(d)},n)=k\}.$$
Then for $k\in{\mathbb N}$, we have the following asymptotic results:
\begin{eqnarray*}
&&\lim_{n\to\infty}\dfrac{Q_k^{(2)}(n)\cdot(\log n)^2}{\pi^2n}=1~\quad\quad\quad ~~~ a.s.\\
&&\lim_{n\to\infty}\dfrac{Q_k^{(d)}(n)}{n}=\gamma_d^2(1-\gamma_d)^{k-1}~\quad\quad a.s.~~~~~\mbox{ if }~~d\ge3,
\end{eqnarray*}
where $\gamma_d:= {\mathbb P}\left(S_n^{(d)} \neq S_0^{(d)},\; \forall n\geq 1\right)$, which is the probability that a simple random walk never returns to the starting point. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:41:54.342250+00:00","domain":"probability theory","id":"claim_4a0397475dd2efe2cd6898161fd4c0fa7ec9c67a6ecfbc40bd2de67c198edf27","kind":"lemma","schema_version":1,"statement":"[Lemma lem:apriori of arXiv:2412.01381, 'Ergodicity and mixing for locally monotone stochastic evolution equations'] Assume that Hypotheses~(hyp:hemicont of the paper),~(hyp:coerc of the paper),~(hyp:coerc-g of the paper),~(hyp:monotonicity of the paper), (hyp:monotonicity-g of the paper), (hyp:growth of the paper), (hyp:regularity of the paper) are valid. Let $T>0$ be fixed.
Let $\alpha\ge 2$, $\alpha-2\ge\beta\ge 0$ be as in Hypotheses (hyp:coerc of the paper) and (hyp:monotonicity of the paper).
If $\alpha=\beta+2$, we assume additionally that
\[\|B\|_{L_2(U,H)}^2\le\lambda_3\frac{1}{\alpha}\delta_1 c_0^\alpha,\]
where $\lambda_3$ is as in Hypothesis~(hyp:quant of the paper), and $\delta_1>0$ is as in 
Hypothesis~(hyp:coerc of the paper).
Then for any initial datum $X_0=x$ such that $\exp(\|x\|^{\beta+2}_H)\in L^{1}(\Omega,{\mathcal F}_0,\mathbb{P};H)$, and every $0\le s\le t\le T$, and for any $n\in\mathbb{N}$, the solution $(X_t^{(n),x_n})_{t\in [0,T]}$ to~(equation eq:finitedim0new of the paper) satisfies
\begin{equation}
\begin{split}
&\mathbb{E}\left[\exp\left(\|X_t^{(n),x_n}\|^{\beta+2}_H+\lambda_0\delta_1\frac{\beta+2}{2}\int_s^{t} \|X_r^{(n),x_n}\|^\beta_H \|X_r^{(n),x_n}\|^\alpha_V\,\mathrm{d} r\right)\right]\\
\le&\mathbb{E}\left[\exp\left(\|X_s^{(n),x_n}\|_H^{\beta+2}+(t-s)(c_1+c_2+c_3)\right)\right],
\end{split}
\end{equation}
for every $0\le s\le t\le T$ in the locally monotone case, and similarly with $\mathbb{E}$ replaced by $\tilde{\mathbb{E}}$ in the fully locally monotone case.
Here, $\lambda_0\in (0,1)$ and $c_i\ge 0$, $i=1,2,3$, are as in 
Hypothesis~(hyp:quant of the paper).

In particular, for $x_n:=Q_n x$, where $Q_n$ is defined as in (equation eq:Qn of the paper), and for any $n\in\mathbb{N}$,
\begin{equation}
\begin{split}
&\mathbb{E}\left[\exp\left(\|X_t^{(n),x_n}\|^{\beta+2}_H+\lambda_0\delta_1\frac{\beta+2}{2}\int_0^{t} \|X_r^{(n),x_n}\|^\beta_H \|X_r^{(n),x_n}\|^\alpha_V\,\mathrm{d} r\right)\right]\\
\le&\mathbb{E}\left[\exp\left(\|x_n\|_H^{\beta+2}+t(c_1+c_2+c_3)\right)\right],
\end{split}
\end{equation}
for every $0\le t\le T$ in the locally monotone case, and similarly with $\mathbb{E}$ replaced by $\tilde{\mathbb{E}}$ in the fully locally monotone case.

Furthermore, we obtain,
\begin{equation}
\begin{split}
&\mathbb{E}\left[\|X_t\|^{\beta+2}_H\right]+\lambda_0\delta_1 c_0^\alpha\frac{\beta+2}{2}\mathbb{E}\int_0^{t} \|X_r\|^{\alpha+\beta}_H\,\mathrm{d} r\\
\le&\mathbb{E}\left[\|x\|_H^{\beta+2}\right]+t(c_1+c_2),
\end{split}
\end{equation}
for every $0\le t\le T$, and similarly with $\mathbb{E}$ replaced by $\tilde{\mathbb{E}}$ in the fully locally monotone case.

Also,
\begin{equation}
\begin{split}
&\mathbb{E}\left[\|X_t\|^{2}_H\right]+\delta_1\mathbb{E}\int_0^{t} \|X_r\|^{\alpha}_V\,\mathrm{d} r\\
\le&\mathbb{E}\left[\|x\|_H^{2}\right]+t\|B\|^2_{L_2(U,H)},
\end{split}
\end{equation}
for every $0\le t\le T$, and similarly with $\mathbb{E}$ replaced by $\tilde{\mathbb{E}}$ in the fully locally monotone case.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:20:33.747889+00:00","domain":"probability theory","id":"claim_4a04adbd11226be07b60fdfb412ea532e87b3726b1ebc7c5d7fb51fd7110e428","kind":"concept","schema_version":1,"statement":"[Lem 10 (Generalized pivot regeneration blocks) of arXiv:2607.28865, 'First-Passage Percolation on Spread-out line graphs: Microscopic Regime'] Let
$
    0<\rho_1<\rho_2<\rho_3<\cdots
$
be the generalized pivots, and let $\gk_n$ be as in~\eqref{eq:kappa-def}.  We use the interval edge set $\cE[x,y]$ and the interval environment $\Env[x,y]$ defined in~\eqref{eq:interval-env-notation}, and the block notation~\eqref{eq:block-variable-notation}. Then the following holds.

\begin{enumeratei}
\item \textbf{Generalized pivot renewal-block localization.}
If $\rho_i<\rho_j$ are two generalized pivots, then there
exists a minimum-hop geodesic from $\rho_i$ to $\rho_j$ using only
edges in $\cE[\rho_i,\rho_j]$.  Consequently,
$T(\rho_i,\rho_j)\text{ and }H(\rho_i,\rho_j)
$ are measurable with respect to $\Env[\rho_i,\rho_j]$.

\item \textbf{Renewal-block i.i.d.~structure.}
The block sequence
\begin{align}
    \left\{
        \left(
            \sfP_i,\,
            \Env[\rho_i,\rho_{i+1}]
        \right)
    \right\}_{i\ge1}
\end{align}
is i.i.d.~In particular,
$
    \{(\sfP_i,\sfT_i,\sfH_i)\}_{i\ge1}
$
is i.i.d.

\item \textbf{Geometric domination of the gaps.}
Generalized pivots occur infinitely often almost surely, and if
$
    \fs_{\ell,k}:=(k+1)\ell-1,
$
then
\begin{align}
    \sfP_i
    \preceq
    \fs_{\ell,k}\,\mathrm{Geom}(p_{\mathrm{gen},\ell}),
    \quad i\ge1.
\end{align}
In particular, $\sfP_1$ has finite moments of all orders.  Consequently,
\begin{align}
    \frac{\gk_n}{n}
    \to
    \frac{1}{\E\sfP_1}
    \quad\text{a.s.}
\end{align}

\item \textbf{Deterministic bounds for bounded weights.}
All moments of $\sfT_i$ and $\sfH_i$ are finite, and
\begin{align}
    \left\lceil\frac{\sfP_i}{\ell}\right\rceil
    \le
    \sfH_i
    \le
    \sfT_i
    \le
    2\left\lceil\frac{\sfP_i}{\ell}\right\rceil,
    \qquad
    \sfH_i\le \sfP_i,
    \quad i\ge1.
\end{align}
\end{enumeratei} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

