\P(T_n\equiv 0\pmod m)\le \frac{C \log k}{k}    
$$
where $C$ is the constant from the statement of Lemma~\ref{modlemma}.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:00:46.839961+00:00","domain":"probability theory","id":"claim_4a6f247782e3d149bc555bfbda5ecbac56e9bf2c5becab4b02b2658e827d5a37","kind":"lemma","schema_version":1,"statement":"[Lem 8 of arXiv:2608.13374, 'Nearly Sharp Comparison Results for sliced and max-sliced Wasserstein distances'] Let $\Phi(x) = d(x,\bigcup_{j=1}^m P_j)$ be the distance function and let $0 < \rho < r$. For any collection $\cU = \sbrac{u_i: i\in[m]}\subseteq \mathbb{S}^{d-1}$, there exists a set $\cZ = \sbrac{z_i: i \in [m]} \subseteq B_{1/4}(0)$ such that
