The implicit constant above depends on $\alpha$, $\lambda$, $\Lambda$, $[\mathcal A]_{C^{0,\alpha}_{\rm kin}}$, $[\mathcal B]_{C^{0,\alpha}_{\rm kin}}$, and $[\mathcal C]_{C^{0,\alpha}_{\rm kin}}$.  Recall that $\tilde r = r \left\langle v_0 \right\rangle^{-\nicefrac32}$ and $r = \min\{1,\nicefrac{\sqrt{t_0}}2\}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:29:35.087413+00:00","domain":"probability theory","id":"claim_4b6d18da6643f194e7cd97fcd7b344e2a261823dd80d2a7054581bb7dea4528e","kind":"theorem","schema_version":1,"statement":"[Thm 14 of arXiv:2609.03819, 'Stochastic damped wave and Euler-Bernoulli equations with singular locally H\"older contin'] Assume that hypotheses \ref{H0}, \ref{H1}, \ref{H2b}, \ref{H3} and \eqref{eq:cond-1} hold. For every $n\in\N$, $k\in\{1,\ldots,n\}$, $i\in\{-,+\}$ and $g:[0,T]\times H_n\rightarrow \R$ continuous such that 
\[
\sup_{t\in [0,T]}\norm{g(t,\cdot)}_{C^\theta_b(H_n)}<\infty,
\]
let $\mathfrak c>{\mathfrak c}_0$ and let $u_{n,k}^{(i)}$ be the unique solution to \eqref{Def:Unki} given by Theorem \ref{Thm: soluzione-kolmogorov}.\\
Then, there exists a sequence $\{f_{n,k,h}\}_{h\in\N}\subseteq C^{0,2}_b([0,T]\times H_n)$ such that:
\begin{enumerate}
\item 
$\displaystyle 
\sup_{h\in\N}\sup_{t\in[0,T]}\|f_{n,k,h}(t,\cdot)\|_{C_b^\theta(H_n)}<\infty$ and
\begin{align}
\lim_{h\rightarrow\infty}\norm{f_{n,k,h}(t,\cdot)-\scal{\mathcal{V}_n^*\nabla_x u^{(i)}_{n,k}(t,\cdot)}{C_n(t,\cdot)}_{U}-g(t,\cdot)}_{C_b(H_n)}=0, \qquad t\in[0,T];
\end{align}
\item  for every $h\in\N$, the parabolic equation 
\begin{equation}

\begin{cases}
\frac{\partial}{\partial t}v(t,x)+L_nv(t,x)=-f_{n,k,h}(t,x)-{\mathfrak c}\lambda_{k}^{(i)}v(t,x), & (t,x)\in[0,T)\times H_n, \\[1mm]
 v(T,x)=0, & x\in H_n,
\end{cases}
\end{equation}
has a unique strict solution $u^{(i)}_{n,k,h}\in C^{1,2}_b([0,T]\times H_n)$ given by
\begin{align}
u^{(i)}_{n,k,h}(t,x)=\int_{t}^Te^{{\mathfrak c}(s-t)\lambda_k^{(i)}}(R_n(s-t)f_{n,k,h}(s,\cdot))(x)ds, \qquad (t,x)\in[0,T] \times H_n;
\end{align}
\item for every $t\in [0,T]$ we have
\begin{align}
&\lim_{h\rightarrow \infty}\norm{u^{(i)}_{n,k,h}(t,\cdot)-u^{(i)}_{n,k}(t,\cdot)}_{C^1_{b,\mathcal{V}_n}(H_n)}=0,\\
&\lim_{h\rightarrow \infty}\norm{\mathcal{G}_n^*\nabla u^{(i)}_{n,k,h}(t,\cdot)-\mathcal{G}_n^*\nabla u^{(i)}_{n,k}(t,\cdot)}_{C_{b}(H_n;U)}=0.
\end{align}

\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:23:05.295191+00:00","domain":"probability theory","id":"claim_4b6d641d2943d3c9422730e6b0e0a8c0dc97b9955086b1f24368d5b705c2e59e","kind":"lemma","schema_version":1,"statement":"[Lemma 6 of arXiv:2608.21701, 'Superdiffusivity of random walks on the three-dimensional randomly oriented Manhattan latt'] Fix $i\in[3]$. There exists $C<\infty$ such that, for every $p=(p^1,p^2,p^3)\in\mathbb T^3$ satisfying $\sin(p^i/2)\neq0$, every $\lambda>0$, and every $\kappa\ge1$, we have
