  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:37:28.981301+00:00","domain":"probability theory","id":"claim_4b71cf375bfce16bf3290e4a488821df5c154a0836d6a8991941887af9c5be94","kind":"lemma","schema_version":1,"statement":"[Lem lm:randomhypergraph of arXiv:2412.00610, 'Joint Poisson Convergence of Monochromatic Hyperedges in Multiplex Hypergraphs'] Let $\bm H_n = (H_n^{(1)}, H_n^{(2)})$ be a sequence of random 2-hypermultiplexes, where both $H_n^{(1)}$ and $H_n^{(2)}$ are $r$-uniform, which is independent of the coloring distribution such that the following hold: 
    \begin{align} 
   \bE [ \bm T(\bm H_n) | \bm H_n ] \pto \begin{pmatrix}
  \lambda_1 \\ 
  \lambda_2
  \end{pmatrix} \quad \text{ and } \quad \mathrm{Var}[ \bm T(\bm H_n) | \bm H_n ] \pto \begin{pmatrix}
  \lambda_1 & \lambda_{1, 2} \\ 
  \lambda_{1, 2} & \lambda_2
  \end{pmatrix} , 
    \end{align}
   for constants $\lambda_1, \lambda_2, \lambda_{1,2} \geq 0$, with $\lambda_{1,2} \le \lambda_1$ and $\lambda_{1,2} \le \lambda_2$. 
Then
    $$ \bm T(\bm H_n) = \left(\begin{array}{l}
        T(H_n^{(1)}) \\
        T(H_n^{(2)})
        \end{array}\right) \dto \left(\begin{array}{l}
            Z_1 + Z_{1,2}\\
           Z_2 + Z_{1,2}
            \end{array}\right) : = \bm Z , $$
    where $Z_1 \sim \Pois(\lambda_1 - \lambda_{1,2}), Z_2 \sim \Pois(\lambda_2 - \lambda_{1,2}), Z_{1,2} \sim \Pois(\lambda_{1,2})$ are independent.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:51:15.024132+00:00","domain":"probability theory","id":"claim_4b7380afd92b685e50c04a23b1560da671519f682997a88304267f4f0fd475ec","kind":"concept","schema_version":1,"statement":"[Corollary cor:untied_weak_recovery of arXiv:2609.03858, 'High-Dimensional Learning Dynamics of \\ Attention-Indexed Models'] Suppose that Assumption (assum:untied_initialization of the paper) and the
conditions of Theorem (theo:untied-SGD of the paper) hold. 
\begin{itemize}
\item[\textnormal{(i)}] If
\begin{equation}
\mathsf Q_2g_{12}^\star\neq0,

\end{equation}
then there exist constants \(c>0\) and \(0<T_-<T_+<\infty\), independent of \(d\), such that
\begin{equation}
\lim_{d\to\infty}
\mathbb P\left(\left\lfloor\frac{T_-d}{\alpha_d}\right\rfloor<N_{\rm wr}^{(d)}(c)\le
\left\lceil\frac{T_+d}{\alpha_d}\right\rceil\right)=1.

\end{equation}
Consequently, choosing the largest learning-rate scaling $\alpha_d=\Theta\left(\frac1{d\log d}\right)$ covered by Theorem (theo:untied-SGD of the paper)
gives
\begin{equation}
N_{\rm wr}^{(d)}(c)=\Theta_{\mathbb P}(d^2\log d).

\end{equation}

\item[\textnormal{(ii)}] Let \(\mathcal M_{\mathrm{free}}\) denote the set of moment sequences for which the algebra generated by \(\{M_1,M_1^T,A_1,B_1\}\) is free from the algebra generated by \(\{M_2,M_2^T,A_2,B_2\}\). Suppose that throughout \(\mathcal M_{\mathrm{free}}\),
\begin{equation}
\left[\nabla_{q^{(r)}}\Phi\left(m^\star(q),q^{(1)},q^{(2)}\right)\right]_{12}=0,
\qquad r=1,2.

\end{equation}
Then for every \(c>0\) and every fixed \(T>0\),
\begin{equation}
\lim_{d\to\infty}\mathbb P\left(N_{\mathrm{wr}}^{(d)}(c)\le\left\lfloor\frac{Td}{\alpha_d}\right\rfloor\right)=0.

\end{equation}
Thus, for \(\alpha_d=\Theta((d\log d)^{-1})\), weak recovery does not occur on the \(d^2\log d\) sample scale.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:22:39.762765+00:00","domain":"probability theory","id":"claim_4b73c7e80f7be05a12cdfe03447c299998ef497fb5881cc398552e1a439e549c","kind":"theorem","schema_version":1,"statement":"[Theorem l:7A of arXiv:2508.21658, 'Infinite-dimensional stochastic differential equations for Coulomb random point fields'] \noindent \thetag{i} 
There exists a $ \mum $-symmetric, conservative diffusion $ \oLXm $ properly associated with $(\Emum , \dOmum ) $ on $ \Lmm $ for each $ m \in \zN $. 

\noindent \thetag{ii} 
None of the labeled particles $\oLxX^i$, where $i=1,\ldots,m$, in $\oLXm$ explode or collide with other labeled particles: 
\begin{align}&
P (\oLxX ^i \in C([0,\infty);\Rd ), i=1,\ldots,m ) = 1 
,\\ & 
P (\oLxXti \ne \oLxXtj \text{ for all } t\in [0,\infty ), 1\le i, j \le m , i\ne j ) = 1 
.\end{align} 

\noindent \thetag{iii}
For each $ 1 \le i \le m $,
\begin{align}&
\oLxXti - \oLxXzi
=
\int_0^{ t }
\sigma ( \oLxXui ) \, d B_u^i
+
\int_0^{ t }
\bbb ( \oLXXXi ) \, du
,\\&
\oLxXti - \oLxXzi
=
\half
\Big\{
\int_0^{ t }
\sigma ( \oLxXui ) \, d B_u^i
-
\int_0^{ t }
\sigma ( \oLxXui ) \, d B_u^i \circ r_t
\Big\}
.\end{align}
Here $ r_t $ is the time-reversal operator
defined before \lref{l:61}, and
\begin{align}
\oLXXXi
=
\big(
\oLxXui ,
\sum_{ j \ne i }^{ \infty }
\delta_{ \oLxXuj }
\big)
.\end{align}","status":"unverified"}

