{"assumptions":[],"created_at":"2026-10-26T19:27:08.837349+00:00","domain":"probability theory","id":"claim_4c40014a02a2d6d0bbd7dafbb9d817d8e40a71d8de07f2bd713c1abc4debce4b","kind":"concept","schema_version":1,"statement":"[Proposition 2 ({\cite[Lemma~2.3) of arXiv:2511.09930, 'Martingale dimensions for a class of metric measure spaces'] {Hi10}, see also \cite[Lemma~2.2]{Na85}}]
