{"assumptions":[],"created_at":"2026-10-27T15:38:04.504380+00:00","domain":"probability theory","id":"claim_4c53df1f2494bb784c198e287bae9492a6b77afb7f44400f0fa4746568eb5b82","kind":"theorem","schema_version":1,"statement":"[Proposition prop:swap-op of arXiv:2607.14266, 'The Swapping Mechanism for Interacting Diffusions: Framework, Comparison with Switching, a'] Let $\mu$ be a $\sigma$-finite measure on $\mathbb{R}^{2d}$.
		\begin{enumerate}
			\item[\textup{(i)}] If $\mu\circ\tau=\mu$, then $\mathcal{S}_\gamma$ extends to a
			bounded linear operator on $L^p(\mathbb{R}^{2d},\mu)$ for every $1\le p\le\infty$,
			with $\|\mathcal{S}_\gamma\|_{L^p(\mu)\to L^p(\mu)}\le 2\Gamma$. In particular,
			the dual operator $\mathcal{S}_\gamma^*$ on $L^1(\mathbb{R}^{2d},\mu)$ satisfies
			\begin{equation}
				\mathcal{S}_\gamma^*\rho(z)=\gamma(\tau z)\rho(\tau z)-\gamma(z)\rho(z),
			\end{equation}
			and $\|\mathcal{S}_\gamma^*\|_{L^1\to L^1}\le 2\Gamma$.
			\item[\textup{(ii)}] $\mathcal{S}_\gamma$ is self-adjoint on $L^2(\mu)$ if and only
			if the \emph{detailed-balance} condition holds:
			\begin{equation}
				\gamma(x,y)\,\mu(\mathrm{d} x,\mathrm{d} y)=\gamma(y,x)\,\mu(\mathrm{d} y,\mathrm{d} x).
			\end{equation}
			When $\mu\circ\tau=\mu$, this reduces to $\gamma(x,y)=\gamma(y,x)$,
			$\mu$-a.e.
			\item[\textup{(iii)}] Under (equation eq:detailed-balance of the paper),
			$\langle f,\mathcal{S}_\gamma f\rangle_\mu=-\tfrac12\int\gamma(z)[f(\tau z)-f(z)]^2\mu(\mathrm{d} z)\le 0$.
		\end{enumerate}","status":"unverified"}

