{"assumptions":[],"created_at":"2026-10-27T20:06:06.358960+00:00","domain":"probability theory","id":"claim_4c7d4cc0dac3f2c66b06bb12cfb4fccbf81db770554fe06e4d06d57cfba3dd96","kind":"concept","schema_version":1,"statement":"[Theorem thm:intro-pathological of arXiv:2605.26652, 'Pathological Large Deviations of the KMP Process in Dimension $d\ge 2$'] Let $(\xi^N_t)_{t\in [0,T]}$ be a KMP process on $\mathbb T_N^d$, with initial data $\xi^N_0$ drawn from an equilibrium measure $\nu^N_\rho, \rho\in (0,\infty)$. Then:
\begin{enumerate}[label=(\roman*)]
    \item in dimension $d=1$, for any $t_0\in [0,T]$, there exists a path $\Xi\in \mathcal X$ whose unique continuous-in-time representative $\xi$ admits a smooth density $u_t(x)$ for $t\neq t_0$, such that $\xi_{t_0}$ is singular with respect to the Lebesgue measure, and where \begin{equation}
    	 \inf_{\mathcal U\ni\Xi} \liminf_N \frac1N\log\mathbb{P}\left(\pi^N(\xi^N)\in \mathcal U\right)>-\infty;
    \end{equation} \item in dimension $d=2$, for any sequence $\epsilon_k>0$ and distinct times $t_k\in (0,T), k\ge 1$ which satisfy $\sum_k \epsilon_k^{\gamma}<\infty$ for some $0<\gamma<1$, there exists a path $\Xi\in \mathcal X$ whose unique c{\`a}dl{\`a}g representative $\xi$ satisfies, for each $k$, $$ \|\xi_{t_k}-\xi_{t_k-}\|_{\rm TV}=2\epsilon_k $$ and such that\begin{equation}
    	 \inf_{\mathcal U\ni\Xi} \liminf_N \frac1{N^2}\log\mathbb{P}\left(\pi^N(\xi^N)\in \mathcal U\right)>-\infty;
    \end{equation}
    \item in dimension $d\ge 3$, fix $c,M\in (0,\infty)$. Then there exists $J=J(\rho, c,M)<\infty$ such that, for any relaxed measure $\Xi$ with constant energy $e(\Xi)\le M$ and a lower bound $\Xi(dt,dx)\ge c dt dx$, it holds\begin{equation}
    	 \inf_{\mathcal U\ni \Xi}\liminf_N \frac1{N^d}\log \mathbb{P}\left(\pi^N(\xi^N)\in \mathcal U\right)\ge -J(\rho, c,M).
    \end{equation}\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:25:55.318858+00:00","domain":"probability theory","id":"claim_4c82c5167d6e8b76ea406b20e074352640143b893557a4807233e33e6a8dea8d","kind":"lemma","schema_version":1,"statement":"[Lemma 25 of arXiv:2607.27786, 'Gaussian free field in annulus: \\BPZ equations and crossing probabilities for level lines'] Assume the same setup as in Lemma~\ref{lem::reg_Dirichlet_annular_cro}. The regularized Dirichlet energy and the partition function have the following asymptotic as $r\to\infty$: 
\begin{align} 
	\| \varphicro{n} \|_{\nabla(\A_r),\mathrm{reg}}^2=& \frac{n(n-2) \pi r}{2} -2\pi \sum_{1\le i<j\le n} \left( \log \sin \left( \frac{\beta_{j}-\beta_i}{2} \right) + \log \sin \left( \frac{\alpha_{j}-\alpha_i}{2} \right) \right) \notag\\
	& -2\pi n(n-1)\log 2 +\frac{\pi}{2r}\left(\sum_{j=1}^{n} (\alpha_j-\beta_j) \right)^2+ O(1)\ee^{-r};
\\
\LZcro{n}^{(\ell)}(r; \bs{\alpha}, \bs{\beta})=&\sqrt{2}^{n(n-1)}\LZradial{n}(\bs{\alpha})\LZradial{n}(\bs{\beta})\notag\\
&\times\exp\left(\frac{n(2-n)r}{8}-\frac{1}{8r}\left(\sum_{j=1}^{n}(\alpha_j-\beta_{j})-2n\pi\ell\right)^2+O(1)\ee^{-r}\right);
\end{align}
where $\LZradial{n}$ is defined in~\eqref{eqn::LZunitdisc_def} and the $O(1)$ terms have upper bounds independent of $(\bs{\alpha}, \bs{\beta})$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:42:08.412205+00:00","domain":"probability theory","id":"claim_4c84a32c5c55859f3f3d926ec80e234f476dfdd7b9c1db82c6df86c3be9f117f","kind":"concept","schema_version":1,"statement":"[Prop P: uniqueness PME of arXiv:2511.11036, 'Analysis of a class of Recursive Distributional Equations Including the Resistance of the '] Let $F_{\text{in}} \in CDF(\overline{\mathbb{R}})$ and assume $Q = 0$.  If $\mathcal{F}$ has the form (equation E: porous medium nonlinearity of the paper) for some $m > 1$, then the maximal subsolution $\underline{F}$ and minimal supersolution $\overline{F}$ of (equation E: initial value problem appendix of the paper) are given for $(x,t) \in \mathbb{R} \times (0,+\infty)$ by the formula
		\begin{align} 
			\underline{F}(x,t) = \overline{F}(x,t) = F_{\text{in}}(-\infty) + \int_{-\infty}^{x} \rho(y,t) \, dy,
		\end{align}
	where $\rho \geq 0$ is the unique continuous distributional solution of the initial-value problem
		\begin{align} 
			\left\{ \begin{array}{r l}
				\partial_{t} \rho - \frac{a}{m} \partial_{x}^{2} ( \rho^{m} ) = 0 & \text{in} \, \, \mathbb{R} \times (0,+\infty), \\
				\rho(0) = \partial_{x} F_{\text{in}}.
			\end{array} \right.
		\end{align}


	Furthermore, the following statements hold:
		\begin{itemize}
			\item[(i)] For any $t > 0$, the functions $\underline{F}(\cdot, t)$ and $F_{\text{in}}$ coincide on the set $\{-\infty,+\infty\}$.  
			\item[(ii)] If $\{ F_{\text{in}}^{(n)} \}$ is some sequence in $CDF(\overline{\mathbb{R}})$ converging vaguely to $F_{\text{in}}$, and if $\{ \underline{F}^{(n)} \}$ are the corresponding maximal subsolutions of (equation E: initial value problem appendix of the paper), then, for any compact set $K \subseteq \mathbb{R} \times (0,+\infty)$,
			\begin{align*}
				\lim_{n \to + \infty} \sup \left\{ | \underline{F}^{(n)}(x,t) - \underline{F}(x,t) | \, \mid \, (x,t) \in K \right\} = 0.
			\end{align*}
		\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:51:12.747358+00:00","domain":"probability theory","id":"claim_4c8b6e1dcbdf0638cb910e111efeabb6422635eaf13e2ba181b80a2827d61cbd","kind":"theorem","schema_version":1,"statement":"[Proposition 30 of arXiv:2605.02499, '2605.02499'] Let $\Ls_{Z^{(N)}}$ and $\Ls_Z$ denote the generators of the processes $Z^{(N)}$ and $Z$. Let $\Nb_{0, \Delta} \coloneqq \Nb \cup \{0, \Delta\}$ and let $f:\Nb_{0, \Delta}\to \Rb$ be a bounded function and denote its restriction to $[N]_{0, \Delta}$ by $f{\vert _N}$.
Then, for $k \in \Nb$ and $N \geq k$, we have
