{"assumptions":[],"created_at":"2026-10-27T05:50:44.875761+00:00","domain":"probability theory","id":"claim_4c9c2bdc6d769934a2cdb711e54672b740b540a1538a37d796a6d10f2e46b96f","kind":"theorem","schema_version":1,"statement":"[Corollary 53 (Polynomial weights and quantitative cutoff rates) of arXiv:2607.16724, 'Algebraic Transfer for Operator-Valued Gaussian Chaoses: Oriented Schatten Profiles and Si'] Fix $m\ge1$, $1\le r<\infty$, and $a,b\ge0$ satisfying
\eqref{eq:group-smoothing-range}.  Suppose \eqref{eq:group-growth} holds,
$c_x=\langle x\rangle^{-\sigma}$, and $\sigma>D/2$.  Then, with
$\delta=\sigma-D/2$, for every $1\le p<\infty$,
\begin{equation}

 \norm{T_{m,N}^{a,b}(c)-T_m^{a,b}(c)}_{L^p(\Omega;\Sch_r)}
 \le C_{\Gamma,D,\sigma,a,b,m,r}(p+r)^{m/2}N^{-\delta}.
\end{equation}
For a common realization and every $t\ge1$,
\begin{equation}

 \Prob\!\left(
  \norm{T_{m,N}^{a,b}(c)-T_m^{a,b}(c)}_{\Sch_r}
  >\mathrm e\,C_{\Gamma,D,\sigma,a,b,m,r}
    (t+r)^{m/2}N^{-\delta}
 \right)
 \le\mathrm e^{-t}.
\end{equation}
Consequently,
\begin{equation}

 \norm{T_{m,N}^{a,b}(c)-T_m^{a,b}(c)}_{\Sch_r}
 =O_\omega\!\left(
    N^{-\delta}(\log(e+N))^{m/2}
  \right)
 \qquad\text{almost surely}.
\end{equation}
In particular, this is $O_\omega(N^{-\eta})$ for every
$0<\eta<\delta$.
For the integer Heisenberg group $H_3(\mathbb Z)$ one may take $D=4$;
thus the sufficient range becomes
\begin{equation}

 \sigma>2,\qquad a>0,\qquad b>0,\qquad a+b>\frac4r.
\end{equation}","status":"unverified"}

