{"assumptions":[],"created_at":"2026-10-28T02:16:53.589751+00:00","domain":"probability theory","id":"claim_4d03c2aa077c66a1f4575368e7cc5abd86ad494bb53d4d5c6e1191b989e207f8","kind":"theorem","schema_version":1,"statement":"[Prop upper bound of arXiv:2412.04918, 'On one dimensional weighted Poincar\'e inequalities for Global Sensitivity Analysis'] Given $i \in \{ 1,\ldots, d \}$, assume that the distribution $\mu_i$ of the input variable $X_i$ belongs to $\mathcal{P}(a_i,b_i)$. Let $w_i \in \mathcal{W}(a_i,b_i)$ be a weight function and suppose that $\mu_i$ satisfies the following
weighted Poincar\'e inequality:  for all centered function $g\in H^1(\mu_i,w_i)$,
\begin{equation}

\mathbb{E}\left[g(X_i)^2\right] \leq C_P(\mu_i,w_i) \, \mathbb{E}\left[w_i(X_i)g'(X_i)^2\right] .
\end{equation}
We also assume that $\left( w_i(X_i) \right)^{1/2} \frac{\partial f}{\partial x_i}(X) \in L^2$ where $f(X) \in L^2 $. Then, 
\begin{equation}

      S_i^\mathrm{tot}\leq C_P(\mu_i,w_i) \, \frac{\nu_{i,w_i}}{\mathop{\rm Var}\nolimits(f(X))}.
  \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:15:15.495502+00:00","domain":"probability theory","id":"claim_4d04dcb5b77fc13d7e1f77ff7821583bfbaccbf21eb879f49a6eddf17f71991c","kind":"theorem","schema_version":1,"statement":"[Theorem LR of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] \noindent  Let $C_{1},C_{2}$ be copulas on $[0,1]^{2}$ with
associated joint distributions $P_{i}=F_{C_{i}}$ on $R^{2}$, having
densities $f_{i}$. Assume:

\begin{enumerate}
\item $0<E^{P_{i}}[X_{1}X_{2}]<\infty $ for $i=1,2$;

\item $P_{1}\leq _{\mathrm{lr}}P_{2}$, i.e.\ $\frac{f_{2}}{f_{1}}$ is
coordinatewise non-decreasing.
\end{enumerate}

Then for all $s_{1},s_{2}\in R$, 
\begin{equation}
\frac{E^{F_{C_{1}}}(X_{1}X_{2}1_{\{X_{1}\geq s_{1}\}}1_{\{X_{2}\geq s_{2}\}})
}{E^{F_{C_{1}}}(X_{1}X_{2})}\leq \frac{E^{F_{C_{2}}}(X_{1}X_{2}1_{\{X_{1}
\geq s_{1}\}}1_{\{X_{2}\geq s_{2}\}})}{E^{F_{C_{2}}}(X_{1}X_{2})}.

\end{equation}
Moreover, setting $s_{1}=0$ or $s_{2}=0$ yields the marginal forms
\begin{eqnarray}
\frac{E^{F_{C_{1}}}(X_{1}X_{2}1_{\{X_{1}\geq s\}})}{E^{F_{C_{1}}}(X_{1}X_{2})
} &\leq &\frac{E^{F_{C_{2}}}(X_{1}X_{2}1_{\{X_{1}\geq s\}})}{
E^{F_{C_{2}}}(X_{1}X_{2})}   \\
\frac{E^{F_{C_{1}}}(X_{1}X_{2}1_{\{X_{2}\geq s\}})}{E^{F_{C_{1}}}(X_{1}X_{2})
} &\leq &\frac{E^{F_{C_{2}}}(X_{1}X_{2}1_{\{X_{2}\geq s\}})}{
E^{F_{C_{2}}}(X_{1}X_{2})}.  
\end{eqnarray}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:55:18.064600+00:00","domain":"probability theory","id":"claim_4d08529cdae33a37f6d32038f680097064dedb3a287581942355422de1624ac1","kind":"theorem","schema_version":1,"statement":"[Theorem 23 (Dubins' inequality for infinite time, $T = \infty$) of arXiv:2606.17452, 'Optional Stopping for Superhedging Supermartingales'] Let $\{f_j\}_{j \geq 0}$ be a given real valued non-negative supermartingale sequence and $\rho_k, \tau_k$ given by Definition \ref{upcrossing_stopping_times}  with $T = \infty$ (i.e. the infinite time case). Furthermore, assume that $(L)-a.e.$ holds as well as property $(P)$ (as per Definition \ref{def:Positivity})  then,
