{"assumptions":[],"created_at":"2026-10-27T23:13:49.973431+00:00","domain":"probability theory","id":"claim_4d1508317c501439fe5d244e8b1dea12bfc1fe2753fd7ad40eeaa2a822428de0","kind":"theorem","schema_version":1,"statement":"[Proposition eq:prop1 of arXiv:2411.07157, 'Rough differential equations in the flow approach'] Fix a universal constant $C_R>0$, and define 
\begin{equ}
\Xi \equiv \Xi(\xi, V,{\tt u} ,C_R)
\eqdef
\max \Big(
{\talloblong \omega\xi \talloblong}_{4}, C_R,
\|V\|_{C^9(B_0(C_R+|{\tt u}|))} \Big)\;.
\end{equ}
If there exists constants $C,p\geqslant1$ such that $T=C\Xi^{-p}$, we just write $T = T_{\Xi}$.

There exists $\tilde{T} = \tilde{T}_{\Xi} \in(0,1]$ such that, for any $T \in (0,\tilde{T}]$ and $\eps \in (0,1]$, the map
\begin{equs}
    \Phi:\binom{\theta_{\eps,}}{\tilde{R}_{\eps,}}\mapsto\binom{\Phi^\theta_{\eps,}}{\Phi^{\tilde{R}}_{\eps,}}(\theta_{\eps,},\tilde{R}_{\eps,})\eqdef\binom{-\int_{}^{T}\tilde K_{\nu,}\mathcal{R}^2_{\nu} \dot G_{\nu}  \big(\tilde{F}_{\eps,\nu}[K_{\nu}\theta_{\eps,\nu}]+\tilde{R}_{\eps,\nu}\big)\mathrm{d}\nu}{-\int_0^{}\tilde K_{,\nu}\big(
      \mathrm{D} \tilde{F}_{\eps,\nu}[K_{\nu}\theta_{\eps,\nu},\mathcal{R}_\nu\dot G_\nu \tilde{R}_{\eps,\nu}]+\Tilde{I}_{\eps,\nu}[K_\nu\theta_{\eps,\nu}]\big)
      \mathrm{d}\nu}    
 \end{equs}
is a contraction for the norm 
\begin{equs}    \nnorm{\theta_{\eps,},\tilde{R}_{\eps,}}_T\eqdef 
    \sup_{\mu\in(0,T]}{\| \theta_{\eps,\mu} 
    \|}_{L_{0;T}^\infty}\vee\sup_{\mu\in(0,T]}\mu^{-\delta/2}{\|  \tilde{R}_{\eps,\mu} 
    \|}_{L_{0;T}^\infty}\,.
\end{equs}
In particular, the system (equation eq:sys2 of the paper) has a unique solution, denoted $(\theta_{\eps,},\tilde{R}_{\eps,})$, satisfying the estimate
  \begin{equs}
        \sup_{\mu\in(0,T]}\mu^{-\delta/2}{\| \tilde{R}_{\eps,\mu} 
    \|}_{L^\infty_{0;T}}\leqslant C_R\,.
    \end{equs}
Finally, the solution $(\theta_{\eps,},\tilde{R}_{\eps,})$ is continuous in the data $(\tilde{F}_{\eps,},\Tilde{I}_{\eps,})$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:51:30.071896+00:00","domain":"probability theory","id":"claim_4d15426a990e89328e16780d602140a8401ca7a1c20c696867878d0b96a01b21","kind":"lemma","schema_version":1,"statement":"[Lemma 20 of arXiv:2606.01832, 'MA(1) processes with uniform innovations conditioned to stay positive in the non-expanding'] In the yellow region, it holds with $\lambda=\lambda(\theta,a)$ as given in \eqref{root_yellow_2} that
