\end{align}
\item 
For any $q\geq 1$ and $w=a+\mathrm{i} b$ with $|w|=\OO(n^{2/3})$,
\begin{align}
    \mathbb{E}[|\Delta^{(n)}_t(w)+\OO(n^{-1/3}|w|)|^q]\leq \frac{(Cq)^{2q}}{b^q}, 
