{"assumptions":[],"created_at":"2026-10-27T06:45:05.368549+00:00","domain":"probability theory","id":"claim_4e0fd02850e036bad7832dff006becce5c1b6879f0bdef22dcdb815f32e77df8","kind":"theorem","schema_version":1,"statement":"[Proposition 118 (Common predictable covariance density) of arXiv:2608.04993, '2608.04993'] Let $\Delta_n=T2^{-n}$ and $t_k^n=k\Delta_n$.  Define the
$\mathcal S_2(H)_{\rm sa}$-valued elementary predictable process
\begin{equation}
 \mathfrak a_t^{(n)}
 :=\begin{cases}
 0,&0\le t\le \Delta_n,\\[1mm]
 \Delta_n^{-1}\bigl(Q_{t_k^n}-Q_{t_{k-1}^n}\bigr),
 &t_k^n<t\le t_{k+1}^n,\quad 1\le k<2^n.
 \end{cases}
\end{equation}
Let $\mathscr DQ$ be the total trace-class derivative furnished by
\Cref{prop:canonical-predictable-differentiation}; its approximants are
\eqref{eq:common-covariance-density-approximants}.  Define
\begin{equation}
 \mathfrak a_t
 :=\begin{cases}
 (\mathscr DQ)_t,&(\mathscr DQ)_t\in\mathcal I_\Gamma,\\
 0,&\text{otherwise.}
 \end{cases}
\end{equation}
Then $\mathfrak a$ is a total Borel predictable
$\mathcal I_\Gamma$-valued process.  For every $x\in G_*^\Gamma$, it is a
predictable representative of the canonical derivative class associated with
$Q(x)$ by \Cref{prop:covariance-path-density-isomorphism}.  In particular,
$Q(x)$ is Bochner absolutely continuous in $\mathcal S_1(H)$ and
\begin{equation}
 Q_t(x)=\int_0^t\mathfrak a_r(x)\,\dd r,
 \qquad
 0\preceq\mathfrak a_r(x)\preceq\Gamma
 \quad\text{for a.e. }r.
\end{equation}
Under every $P\in\Mmax$,
\begin{equation}
 \mathfrak a_t=a_t^P
 \qquad \dd t\otimes P\text{-a.e.}
\end{equation}
It is the same density under every law and is unique in the common product
class: for any other such $\widetilde{\mathfrak a}$,
\begin{equation}
 \sup_{P\in\Mmax}
 E^P\int_0^T
 \|\mathfrak a_t-\widetilde{\mathfrak a}_t\|_1\,\dd t=0.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:56:49.287800+00:00","domain":"probability theory","id":"claim_4e1037319ac4db0c57cce5a6d3daa21fe918515e0acf8748815e9a19b9f2f3c2","kind":"theorem","schema_version":1,"statement":"[Theorem 28 of arXiv:2606.22964, 'Signature McKean--Vlasov stochastic differential equations'] Fixed $\varepsilon>0$, let $\mathcal{G}$ and $\widetilde{\mathcal{G}}$ be two functionals as in Hypothesis \ref{hypothesis_B} also continuous over $\widehat{C}^{\alpha,p}_o$, and $\langle\ell,\cdot\rangle$ and $\langle\widetilde{\ell},\cdot\rangle$ be as in Theorem \ref{thm:CuchieroTeichmannGUAT} such that
    \begin{equation*}
        \sup_{t\in[0,T]}\sup_{\widehat{\mathbf{x}}\in \widehat{C}^{\alpha,p}_o} \frac{ \big|\mathcal{G}(\mathbf{x}^{(1)}_{\cdot\wedge t}) -\langle\ell,S(\widehat{\mathbf{x}})_t\rangle\big| }{ \psi(\widehat{\mathbf{x}}_{\cdot\wedge t}) } < \varepsilon;\qquad \sup_{t\in[0,T]}\sup_{\widehat{\mathbf{x}}\in \widehat{C}^{\alpha,p}_o} \frac{ \big|\widetilde{\mathcal{G}}(\mathbf{x}^{(1)}_{\cdot\wedge t}) -\langle\widetilde{\ell},S(\widehat{\mathbf{x}})_t\rangle\big| }{ \psi(\widehat{\mathbf{x}}_{\cdot\wedge t}) } < \widetilde{\varepsilon}.
    \end{equation*}

    Under the assumption of Hypothesis \ref{hypothesis_A}, let us consider the processes $(X,Y)$ being solutions to the equations
    \begin{equation*}
        \begin{aligned}
            &X_t = \eta + \int_0^t b\left(s,X_s,\Big\langle \ell,\mathbb{E}\left[S(\augpr{X})_s\right]\Big\rangle\right)ds
            + \int_0^t\sigma\left(s,X_s,\Big\langle \widetilde{\ell},\mathbb{E}\left[S(\augpr{X})_s\right]\Big\rangle\right)dW_s;\\
            &Y_t = \eta + \int_0^t b\left(s,Y_s,\mathbb{E}\left[\mathcal{G}(Y_{\cdot\wedge s})\right]\right)ds 
            + \int_0^t\sigma\left(s,Y_s,\mathbb{E}\left[\widetilde{\mathcal{G}}(Y_{\cdot\wedge s})\right]\right)dW_s,
        \end{aligned}
    \end{equation*}
    with $t\in[0,T]$. Then there exists $\delta=\delta(\varepsilon)>0$ such that
    \begin{equation*}
        \mathbb{E}\left[\big\lVert Y - X\big\rVert^2_{\infty,T}\right]\leq \delta,
    \end{equation*}
    where
    \begin{equation*}
        \delta=\delta(\varepsilon):= 2TLe^{4TL(1+2(L_\mathcal{G}\vee L_{\widetilde{\mathcal{G}}}))T}e^{2\beta(2T)^\gamma}\left(\varepsilon\vee\widetilde{\varepsilon}\right)^2
    \end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:44:24.740747+00:00","domain":"probability theory","id":"claim_4e11f74e8e047616d38d6497b44e03046b9fec68fefb3b000d89dd17dbee0a62","kind":"lemma","schema_version":1,"statement":"[Lemma erlem of arXiv:2605.01878, '\Large Random trade timing and power-law tails in realized prices'] Let $\mathbb T = \sum_{k=1}^D \mathrm{Erl}(a_k,b_k)$ be a generalized Erlang random variable with distinct rates $0<a_1<\cdots<a_D$, and let $\mathbb A$ be a square matrix with $\tau(\mathbb A)<a_1$. Then
\begin{equation}
E\left[e^{\mathbb A\mathbb T}\right] = \sum_{k=1}^D\sum_{\ell=1}^{b_k} c_{k,\ell}(a_kI-\mathbb A)^{-\ell}.
\end{equation}
Moreover, if $\mathbb A(z)$ is a holomorphic matrix-valued function on an open connected set $\Omega\subset\mathbb C$, and if $a_kI-\mathbb A(z)$ is invertible for at least one $z\in\Omega$ for each $k=1,\ldots,D$, then
\[
\mathcal G(z) := \sum_{k=1}^D\sum_{\ell=1}^{b_k} c_{k,\ell}(a_kI-\mathbb A(z))^{-\ell}
\]
is meromorphic on $\Omega$, and its possible poles occur only at points $z\in\Omega$ where $a_kI-\mathbb A(z)$ is noninvertible for at least one $k$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:37:28.984728+00:00","domain":"probability theory","id":"claim_4e14d7407529abf912cd8a0706060a88863a04fd7581a62076fd6bbcc409cba8","kind":"concept","schema_version":1,"statement":"[Lemma Hardy-Poincare of arXiv:2412.00865, 'On the spectral problem and fractional diffusion limit for Fokker-Planck with(-out) drift '] Let $d\geqslant 1$ and $\alpha_*=\frac{2-d}{2}$. For any $\alpha<0$,  and $\alpha \in (-\infty,0)\setminus \{ \alpha_*\}$ for $d\geqslant 3$, there is a positive constant $\Lambda_{\alpha,d}$ such that
\begin{equation}
\Lambda_{\alpha,d} \int_{\mathbb{R}^d} |f|^2(D+|x|^2)^{\alpha-1}\mathrm{d}x \leqslant \int_{\mathbb{R}^d} |\nabla f|^2 (D+|x|^2)^{\alpha}\mathrm{d}x
\end{equation}
holds for any function $f \in H^1\big((D+|x|^2)^{\alpha}\mathrm{d}x\big)$ and any $D \geqslant 0$, under the additional condition $\int_{\mathbb{R}^d} f (D+|x|^2)^{\alpha-1}\mathrm{d}x = 0$ and $D>0$ if $\alpha<\alpha_*$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:58:09.906272+00:00","domain":"probability theory","id":"claim_4e14dd4201081a442d5671a8300432fb98ac9451617dd2eaccdf346ad4bb3363","kind":"lemma","schema_version":1,"statement":"[Lemma :Self-reduction lemma of arXiv:2607.19658, 'Hitting time mixing for random $k$-cycles'] Let $M \in \mathbb{N}$ and $T \subset [n]$ such that $M \leq |T| = o((\log n)^{3/2})$. Recall that $\gamma_{n,t} = \exp(-kt'/n).$ Then
    \begin{enumerate}
        \item $\mathbf{P}[\mathcal{G}(T)] = (1+(\log n)^{-1/2+o(1)})\mathbf{P}[\mathcal{G}([M])]\gamma_{n,t}^{|T| - M}n^{M-|T|}$,
        \item $\mathbf{P}[\mathcal{F}([M])] =(1+(\log n)^{-1/2+o(1)})\mathbf{P}[\mathcal{G}([M])]\exp(-\gamma_{n,t})$,
        \item $\sum_{T \supseteq [M], |T| \leq o((\log n)^{3/2})} \mathbf{P}[\mathcal{G}(T)] \leq (\log n)^{o(1)}\mathbf{P}[\mathcal{F}([M])]$.
    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:13:31.963917+00:00","domain":"probability theory","id":"claim_4e150c4b2217135c9ec38d33200317ff704487f134ab9e9f2e8dc52553c001a2","kind":"lemma","schema_version":1,"statement":"[Lemma lem:kl-dt-shifted-comp of arXiv:2506.23062, 'Shifted Composition IV\@: \\ Toward Ballistic Acceleration for Log-Concave Sampling'] Under the same assumptions as Theorem~(thm:kl_local_error of the paper), the following bounds hold.
