{"assumptions":[],"created_at":"2026-10-28T00:52:17.596464+00:00","domain":"probability theory","id":"claim_4e68f6da29850aae9502a9b8dd4483ad37b7cc069f281e72f0fdfd64ae8214ec","kind":"concept","schema_version":1,"statement":"[Thm two-sided of arXiv:2411.15724, 'Wasserstein Convergence Rates for Empirical Measures of Random Subsequence of $\{nα\}$'] Let $X_1,X_2,\ldots$ be integer-valued i.i.d. random variables with characteristic function $\varphi$, and let $S_j = \sum_{i = 1}^{j} X_i$. Let $\alpha$ be an irrational number. Suppose that
\begin{enumerate}[(i)]
\item there exists $0 < \beta \leq 2$ such that in an open neighborhood of $0$,\footnote{Throughout the paper $A \asymp B$ means that there exists an absolute constant $C > 0$ such that $C^{-1} B \leq A \leq C B$.}
$$
|1 - \varphi(x)| \asymp |x|^\beta;
$$

\item there exists $\gamma \geq 1$ such that
\begin{align} 
0 < \liminf_{q \rightarrow \infty} q^\gamma \| q \alpha \| < \infty.
\end{align}
\end{enumerate}
Set $\mu_n = \frac{1}{n} \sum_{j = 1}^{n} \delta_{\{ S_j \alpha \}}$, $n \geq 1$. Then for any $1 \leq p < \infty$,
\begin{enumerate}[(1)]
\item if $\beta \gamma < 2$, assume furthermore that $X_1$ is non-constant, then

$$\mathbb E \big[  \mathbb W_p(\mu_n, \mu)  \big] \asymp \frac{1}{\sqrt{n}};$$

\item if $\beta \gamma = 2$, assume furthermore that $X_1$ is non-constant, then there exist $c_1, c_2 > 0$ such that for any $n \in \mathbb N$,

$$\frac{c_1}{\sqrt{n}} \leq \mathbb E \big[  \mathbb W_p(\mu_n, \mu)  \big] \leq \frac{c_2 (\log n)^{1 - \frac{1}{p \vee 2}} }{\sqrt{n}};$$

\item if $\beta \gamma > 2$, then

$$
0 < \limsup_{n \rightarrow \infty} n^{1/(\beta \gamma)} \mathbb E \big[ \mathbb W_p(\mu_n, \mu) \big] < \infty,
$$
\end{enumerate}
where all constants and implied ones depend on $p$ and conditions on $\varphi$ and $\alpha$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:38:23.595060+00:00","domain":"probability theory","id":"claim_4e6905069e16828a801676ce95e7232017a0c578e508215b31c6b973302f3afb","kind":"theorem","schema_version":1,"statement":"[Theorem th4.2 of arXiv:2511.07173, '\bf Mean-field backward stochastic Volterra integral equations: well-posedness and related'] \rm
	Let (ass3.1 of the paper) be in force and $g$ is Lipschitz continuous with respect to  $(\mu,\nu)$ in 1-Wasserstein distance.
	 Let $(Y^{N,i}(\cdot), Z^{N,i,j}(\cdot,\cdot))_{1\leqslant i,j\leqslant N}$, $(\overline{Y}^{i}(\cdot),\overline{Z}^i(\cdot,\cdot))$ be the  unique solutions of   Eq. ((1.3 of the paper)) and  Eq. ((5.2 of the paper)), respectively.
 Then, for any $1<p<2$, there exists a positive constant  $C$  depending only on $L$ and $p$, such that

               \begin{equation*}
                   \begin{aligned}
                     \mathbb{E}\Big[\int_0^T| Y^{N,i}(t)- \overline{Y}^i(t)|^pdt
                       + \int_0^T\(\int_t^T \sum\limits_{j=1}^N|Z^{N,i,j}(t,s)- \delta_{ij}\overline{Z}^i(t,s)|^2ds\)^\frac{p}{2} dt \Big]
                           \leqslant C {\cal Q}(N),
