{"assumptions":[],"created_at":"2026-10-26T20:25:44.955971+00:00","domain":"probability theory","id":"claim_4ee149c7de9f8091efb83895364b44f6fdcd4c235d687a8f93cddada144e70f6","kind":"concept","schema_version":1,"statement":"[Propo 5 (Size-biased and discounted Galton-Watson process with $k$ spines under $\Q^{(k),\bm \theta}_{T,r}$) of arXiv:2605.11264, 'Uniform sampling of multitype continuous-time Bienaym\'e-Galton-Watson trees'] Let $T\in \re_+$, $t\in (0,T)$, $k\in \na$, and $r\in [d]$.
Consider the process $\mathcal{N}=(\mathcal N_t)_{t\in [0,T]}$ with $k$ spines $\bm \varsigma_t=( \varsigma^{(1)}_t,\ldots,  \varsigma^{(k)}_t)$ at time $t$, under $\Q^{(k),\bm \theta}_{T,r}$. 
Then, $\mathcal N$ evolves as follows:
\begin{enumerate}
	\item The process starts at time 0 with one particle carrying all $k$ spines (i.e., $\mathcal{N}_0=\{\emptyset\} $, and $\bm\varsigma_0=(\emptyset,\ldots, \emptyset) $).
	\item A particle carrying $h\in [k]$ spines evolves a subtree forward in time independently of the rest of the process (branching Markov property).
	\item A particle type $i\in [d]$ carrying $h\in [k]$ spines at time $t\in (0,T)$, branches into $\bm \ell\in \z^d_+\setminus\{\bo 0\}$ offspring, and the $h$ spines split into $g_m\in \{0,1,\ldots,\ell_m\}$ different individuals (groups) of type $m\in [d]$, the $q$-th carrying $a_{m,q} \in [h]$ marks, with $\sum_{m\in[d]} \overline{a}_{m}=h$ and $q\in [g_m]$, at rate
	\begin{equation}
		\begin{split}
			& \alpha_i\E_i\left[\bo L^{\floor{\bo g}}\prod_{m=1}^d\E_m\left[e^{-\bm \theta \cdot \bo Z_{T-t}}\right]^{L^{(m)}-g_m}\right]
			\\
			& \hspace{1cm} \times\frac{\bm \ell^{\floor{\bo g}}			\prod_{m=1}^d\E_m\left[e^{-\bm \theta \cdot \bo Z_{T-t}}\right]^{\ell_m-g_m}p_i(\bm{\ell})}{\E_i\left[\bo L^{\floor{\bo g}}\prod_{m=1}^d\E_m\left[e^{-\bm \theta \cdot \bo Z_{T-t}}\right]^{L^{(m)}-g_m}\right]}
			\frac{\prod_{\substack{m\in [d]\\ g_m\neq 0}}\prod_{q=1}^{g_m}\E_m\left[N^{\floor{a_{m,q}}}_{T-t}e^{-\bm \theta \cdot \bo Z_{T-t}}\right]}{\E_i\left[N^{\floor{h}}_{T-t}e^{-\bm \theta\cdot \bo Z_{T-t}}\right]}.
		\end{split}
	\end{equation}In particular, a birth off the spine, that is, all marks follow the same vertex type $j\in [d]$, occurs at rate 
	\begin{equation}
		\begin{split}
			& \alpha_i\E_i\left[L^{(j)}\prod_{m=1}^d\E_m\left[e^{-\bm \theta \cdot \bo Z_{T-t}}\right]^{L^{(m)}-\delta_{m,j}}\right]\\
			&\hspace{4cm}\times\frac{\ell_{j}p_i(\bm{\ell})
			\prod_{m=1}^d\E_m\left[e^{-\bm \theta \cdot \bo Z_{T-t}}\right]^{\ell_m}}{\E_i\left[L^{(j)}\prod_{m=1}^d\E_m\left[e^{-\bm \theta \cdot \bo Z_{T-t}}\right]^{L^{(m)}}\right]}
			\frac{\E_{j}\left[N^{\floor{h}}_{T-t}e^{-\bm \theta \cdot \bo Z_{T-t}}\right]}{\E_i\left[N^{\floor{h}}_{T-t}e^{-\bm \theta\cdot \bo Z_{T-t}}\right]}.
		\end{split}
	\end{equation}
	\item 
