{"assumptions":[],"created_at":"2026-10-27T17:43:53.605436+00:00","domain":"probability theory","id":"claim_4f1bbb4b01c571d156404af74935338fffcc759ad900d82fbc0c3ca4793457a1","kind":"concept","schema_version":1,"statement":"[Proposition prop:disc_grad_rho_eps of arXiv:2512.12902, 'Non-equilibrium fluctuations for the \\stirring process with births and deaths'] For any $T>0$ there exists a finite constant $c$ so that for any solution $\rho_\epsilon$ of (equation eq:linearized of the paper) with $\rho_\epsilon(\cdot,0)$ the following holds. For any $x\in[-N,\dots,N-1]$, any $t\in(0,T]$ and any $\epsilon >0$
\begin{equation}
|\rho_\epsilon(x,t)-\rho_\epsilon(x+1,t)|\leq \min\Big\{1,c\Big(\epsilon\log_+(\epsilon^{-2}t)+\frac{1}{\sqrt {\epsilon^{-2}t}}\Big)\Big\},
\end{equation}
where $\log_+(u)=\max \{\log(u),1\}$. We shall use a weaker version of (equation eq:dir_rho_lin of the paper), namely that
  for any $\zeta>0$ and $\tau>0$ there is $c$ so that
       \begin{equation}

 \sup_{x,y\in \Lambda_N: |x-y|\leq 1}|\rho_\epsilon(x,t)-\rho_\epsilon(y,t)| \le \frac {c}{(\epsilon^{-2}t)^{1/2-\zeta}+1}
\quad \text{{\rm for any} $t\le \tau \log \epsilon^{-1}$}.
                \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:15:36.158343+00:00","domain":"probability theory","id":"claim_4f21bb6eea631528bbb1557aa75df7f8f2ea2787c72e05d40abe937cdc66a41c","kind":"lemma","schema_version":1,"statement":"[Lemma 13 (Commuted elliptic relation) of arXiv:2609.01589, 'Uniform stability of expanding simple waves for Euler--Poisson--Boltzmann: a singular comp'] For $1\le\abs\alpha\le s$, set $A=e^{\phi^a+\psi}$.  Then
\begin{equation}
  \pa^\alpha r=-\eps^2\Delta\pa^\alpha\psi
  +A\pa^\alpha\psi+\mathcal C_\alpha-\pa^\alpha\cR_\phi^a, 
\end{equation}
where
\begin{equation}
  \norm{\mathcal C_\alpha}_{2}
  \le C K_a\norm\psi_{H^{\abs\alpha-1}}
  +C\norm\psi_{H^{s-1}}\norm\psi_{H^s}. 
\end{equation}
In addition,
\begin{align}
 \norm{\nabla\mathcal C_\alpha}_2
 &\le CK_a\norm\psi_{H^{\abs\alpha}}
 +C\norm\psi_{H^s}^2, \\
 \sum_{1\le\abs\alpha\le s}\norm{\pa_t\mathcal C_\alpha}_2
 &\le C(K_a+\norm\psi_{H^s})
 \left(\norm\psi_{H^s}+\norm{\pa_t\psi}_{H^{s-1}}\right).

\end{align}
Thus the time-differentiated relation contains no unweighted top derivative
of $\nabla\psi$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:33:06.538788+00:00","domain":"probability theory","id":"claim_4f25dcccc3e1e651db35f432c2b87822d93f39447cab8583e03117d1a4532775","kind":"concept","schema_version":1,"statement":"[Prop 5 of arXiv:2608.25829, 'Topology of low-dimensional generalized Ricci solitons and string backgrounds'] Let $(M^n, g, H, f)$ be a compact generalized Ricci soliton.  Then $[H] = 0$ if and only if the soliton is trivial.  In particular nontrivial solitons have $b_3 \geq 1$.
\begin{proof}  The argument is implicit in \cite[Proposition 4.2]{ASU3}.  The given form $H$ is closed and satisfies $d^* (e^{-f} H) = 0$.  Thus if $H = db$ we have
\begin{align*}
    \int_M \brs{H}^2 e^{-f} dV_g =&\ \int_M \IP{ b, d^* (e^{-f} H)} dV_g = 0.
\end{align*}    
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:45:07.265214+00:00","domain":"probability theory","id":"claim_4f27311ca6dd6a4bfcad919815765aebba3c2a7016cec1f12907cb3e1939e018","kind":"lemma","schema_version":1,"statement":"[Lemma 14 of arXiv:2604.19924, 'Fluctuation theory for spectrally negative Lévy processes killed by additive functionals'] Let $\nu_1$ and $\nu_2$ be two Radon measures. Consider two solutions $W^{(q)}_{\nu_1}$ and $W^{(q)}_{\nu_2}$ to \eqref{volterra_nu} driven by $\nu_1$ and $\nu_2$, respectively. Then, we have
		\begin{align*}
			W^{(q)}_{\nu_1}(x,y)-W^{(q)}_{\nu_2}(x,y)=\int_{[y,x]}W^{(q)}_{\nu_1}(x,u)W^{(q)}_{\nu_2}(u,y)(\nu_1-\nu_2)(du),\qquad x,y\in\R.
		\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:55:37.869222+00:00","domain":"probability theory","id":"claim_4f2d936e4ae25b82c34ac0508177a017dc09e7c83490d9d78b1a66b14ac0bc1c","kind":"lemma","schema_version":1,"statement":"[Lem genlyapunovh of arXiv:2605.06488, 'Continuous-state branching processes with L\'evy-Khintchine drift-interaction: Laplace dua'] Let $X$ and $Y$ be positive càdlàg strong Markov processes solving respectively the local martingale problems associated to some operators 
\begin{center}$\big(\mathcal{X},\mathcal{D}_\mathcal{X}\big) \text{ and } \big(\mathcal{Y},\mathcal{D}_\mathcal{Y}\big)$  with $\mathcal{D}_{\mathcal{X}}:=\{f: \mathcal{X}f \text{ is well defined}\}$ and similarly for $Y$.\end{center}

Denote by $\sigma_\infty^{+}$ the first hitting time of $\infty$ for $X$ and by $\tau_0^{-}$ the first hitting time of $0$ for $Y$.

\begin{enumerate}
   \item Assume that there exists $h\in \mathcal{D}_{\mathcal{X}}$, positive not identically $0$, such that $\underset{x\rightarrow \infty}{\lim} h(x)=0$ and for some $x_1,\kappa>0$, \[\mathcal{X}h(x)\leq -\kappa,\ x\in (x_1,\infty),\]
then the following holds
\begin{equation}\underset{x\rightarrow \infty}{\lim} \mathbb{P}_{x}(\sigma_\infty^{+}>t)=0 \text{ for all }t>0.\end{equation}
 \item Assume that there exists $h\in \mathcal{D}_{\mathcal{Y}}$, positive not identically $0$, such that $\underset{x\rightarrow 0}{\lim} h(x)=0$ and for some $\epsilon,\kappa>0$, \[\mathcal{Y}h(y)\leq -\kappa, \ y\in (0,\epsilon),\]
then the following holds
\begin{equation}\underset{y\rightarrow 0^+}{\lim} \mathbb{P}^{y}(\tau_0^{-}>t)=0 \text{ for all }t>0.\end{equation}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:45:27.886926+00:00","domain":"probability theory","id":"claim_4f2ed5608e5626af3f6c7e76aa75b5f29e7e5e8c20b7e3d3b6f65553b033f05e","kind":"definition","schema_version":1,"statement":"[Definition def:fixedgenuschain of arXiv:2607.02410, 'Polynomial mixing for polygonal side matchings'] For positive integers $n \geq 2$ and $g \leq n/2$, let $\chorddiagrams{n}{g}$ be the set of all genus $g$ chord diagrams with $n$ chords. The \emph{fixed genus chord swap chain} on $\chorddiagrams{n}{g}$ is the Markov chain obtained by the following transition kernel:
	\begin{equation*}
		P(X,Y) = \begin{cases}
			\frac{1}{4 {n \choose 2}} & Y \text{ is a chord swap of $X$ and has the same genus as $X$} \\
			1 - \sum_{Z \in \chorddiagrams{n}{g} \backslash \{X\}} P(X,Z) & X=Y \, .
		\end{cases}
	\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:45:02.013733+00:00","domain":"probability theory","id":"claim_4f2ef248157caf9b68807305ab7b36add6cb9a29435840bbb54d4754fbbb2891","kind":"lemma","schema_version":1,"statement":"[Lemma LEM:Gauss of arXiv:2512.23957, 'Concentration and fluctuations of sine-Gordon measure around topological multi-soliton man'] There exist sufficiently large $L_0$, $d_0>0$ such that if $L_\varepsilon \ge L_0$ and $\min_{i\neq j} |\xi_i-\xi_j| \ge d_0$, we can define the Gaussian measure  
