{"assumptions":[],"created_at":"2026-10-27T11:50:36.755492+00:00","domain":"probability theory","id":"claim_4f36e63414710b96ab0fbb0d9c89887e1257e80269241bdd4f53ae5f9f4a31e2","kind":"lemma","schema_version":1,"statement":"[Lemma 32 of arXiv:2609.04153, '\vspace*{-3cm}Smooth autonomous fast dynamo action on the three-torus'] Let $P_{u_1},P_{u_2}$ be two smooth, volume-preserving diffeomorphisms on $\TT^2$, and $\tau_{u_1},\tau_{u_2}$ two non-negative smooth functions. Then, there exists $k\in\NN$, and a constant $C>0$ depending only on $P_{u_1}, \tau_{u_1},\|P_{u_1}-P_{u_2}\|_{C^k}, \|P_{u_1}^{-1}-P_{u_2}^{-1}\|_{C^k}$ and $\|\tau_{u_1}-\tau_{u_2}\|_{C^k}$, so that 
\begin{align*}
&\left \|\begin{pmatrix}
DP_{u_1}(P_{u_1}^{-1}) & 0 \\
-D \tau_{u_1}(P_{u_1}^{-1}) & 1
\end{pmatrix} B(P_{u_1}^{-1})- \begin{pmatrix}
DP_{u_2}(P_{u_2}^{-1}) & 0 \\
-D \tau_{u_2}(P_{u_2}^{-1}) & 1
\end{pmatrix} B(P_{u_2}^{-1})\right \|_{\mathcal Y}\\
&\leq C(\|P_{u_1}-P_{u_2}\|^{\delta}_{C^k}+\|\tau_{u_1}-\tau_{u_2}\|_{C^k}+\|P_{u_1}^{-1}-P_{u_2}^{-1}\|^{\delta}_{C^k})\|B\|_{\mathcal X}.
\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:19:42.667220+00:00","domain":"probability theory","id":"claim_4f3786a45eac3848d467a711ac48211a18b7addef109db4d8c4a452169245b1e","kind":"lemma","schema_version":1,"statement":"[Lemma 12 of arXiv:2609.03556, 'An Effective SPDE Model for a Schr\"odinger Equation with a Fluctuating Magnetic Potential'] \label[lemma]{lem:commutator}
    Let $k\geq 0$ and $f\in H^{-k}(\R^d)$ be a complex valued function and $u\in H^{s}(\R^d;\R^d)$ for $s>\frac{d}{2}+k+2$, be a divergence free real vector field. Then
\begin{align*}
    \|u\cdot(I-\Delta)^{-k/2}\nabla f-(I-\Delta)^{-k/2}\left(u\cdot\nabla f\right)\|& \lesssim \|f\|_{H^{-k}}\|u\|_{H^s}.
\end{align*}
    In particular
    \begin{align*}
        |\langle(I-\Delta)^{-k}f,u\cdot\nabla f\rangle+\langle u\cdot\nabla f ,(I-\Delta)^{-k}f\rangle|&\lesssim \|u\|_{H^s}\|f\|_{H^{-k}}^2.
    \end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:56:11.144350+00:00","domain":"probability theory","id":"claim_4f39c713968172a22535e9b29ca4036e16d5ec8b742aed0939becf717f2eab6d","kind":"lemma","schema_version":1,"statement":"[Lemma 11 of arXiv:2608.11071, 'Scaling Laws for Majority-based Opinion Dynamics in the Presence of Stubborn Agents'] Suppose that $N_0^n=N_1^n=\ceil{n\gamma}$ for some $\gamma\in(0,1/2)$. Let $X^n$ and $\bar X^n$ be two chains, each following the rates in~\eqref{eq:uprate}-\eqref{eq:downrate} and started at $x\in \mc S^n$ and $\bar x\in \mc S^n$, respectively. Assume without loss generality that $|x-1/2|\geq |\bar x -1/2|$. Then we have
    \begin{align}
        T_{\text{couple}}^{n}(X^n,\bar X^n) \leq_{st} T_{\text{enter}}^n(r)\nonumber,
    \end{align}
    where $T^n_{\text{couple}}(X^n,\bar X^n)=\inf\{t\geq 0: X^n(t)=\bar X^n(t)\}$ is the first time the two chains meet and
    $T_{\text{enter}}^n(r)=\inf\{t\geq 0: (r-x)(r-X^n(t))\leq 0\}$, as defined before, is the first time the chain $X^n$ crosses $r$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:23:03.039090+00:00","domain":"probability theory","id":"claim_4f3b618890a8c03566f308d6b5117816e901e9fe769d99e817e6d35b91d4fe4d","kind":"concept","schema_version":1,"statement":"[Lemma 15 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] Let 
