{"assumptions":[],"created_at":"2026-10-27T23:01:54.386340+00:00","domain":"probability theory","id":"claim_4f79cc70b96b40a56a366d018f34432d4233616ca11a11a09434707bd10e1378","kind":"concept","schema_version":1,"statement":"[Theorem thm:main of arXiv:2411.02156, 'Martin boundary of a degenerate Reflected Brownian Motion in a wedge'] }$}]
Assume ((drift of the paper)) to ((simple of the paper)). Then, the functions $(h_\alpha)_{\alpha \in [\alpha^*, \alpha^{**}]}$ are harmonic and are given by the following formulae
\begin{itemize}
\item For $\alpha \in (\alpha^{*}, \alpha^{**})$, taking $(a_0, b_0) = (x(\alpha), y(\alpha))$, we have
\begin{equation}
h_{\alpha} : z_0 \longmapsto \sum_{m=-\infty}^{+\infty} \kappa_m(\alpha)e^{z_0\cdot (a_{m}, b_{m})}
\end{equation}

where $\kappa_0(\alpha) = 1$ and
\begin{equation}
\kappa_m(\alpha)=\left\{
    \begin{array}{ll}
        & (-1)^m\left[\prod_{k=0}^{\lfloor \frac{m}{2} \rfloor-1} \frac{\frac{\gamma_1}{\gamma_2}(a_{2k+1}, b_{2k+1})}{\frac{\gamma_1}{\gamma_2}(a_{2k+2}, b_{2k+2})}\right]\frac{\gamma_2(a_0, b_0)}{\gamma_2(a_{m}, b_{m})} \quad\textnormal{if}\; m > 0\\
	& (-1)^m\left[\prod_{k=0}^{\lfloor \frac{-m}{2} \rfloor-1} \frac{\frac{\gamma_2}{\gamma_1}(a_{-2k-1}, b_{-2k-1})}{\frac{\gamma_2}{\gamma_1}(a_{-2k-2}, b_{-2k-2})}\right]  \frac{\gamma_1(a_0, b_0)}{\gamma_1(a_{m}, b_{m})} \quad\textnormal{if}\; m < 0
    \end{array}
\right.
\end{equation}
(with the convention $\Pi_{k=0}^{-1} = 1$).

\item For $\alpha = \alpha^*$,
\begin{itemize}
    \item If $\frac{2}{r_{2} + 1} < \mu_2$, then $\alpha^*= 0$ and $h_{0} : z_0 \longmapsto \partial_\alpha\left[h_\alpha(z_0)\right]_{\alpha=0^+}$.
    \item If $\frac{2}{r_{2} + 1} > \mu_2$, then $\alpha^* > 0$ and taking $(a_0, b_0) = (x(\alpha^*), y(\alpha^*))$,
\begin{equation}
h_{\alpha^*} : z_0\longmapsto e^{z_0\cdot (a_{1}, b_{1})} + \sum_{m=2}^{+\infty}\widehat{\kappa}_m(\alpha^*)e^{z_0\cdot (a_{m}, b_{m})} 
\end{equation}
where 
$$
\widehat{\kappa}_m(\alpha^*)= (-1)^{m+1}\frac{\gamma_1(a_{1}, b_{1})}{\frac{\gamma_1}{\gamma_2}(a_{2}, b_{2})}\left[\prod_{k=1}^{\lfloor \frac{m}{2} \rfloor-1} \frac{\frac{\gamma_1}{\gamma_2}(a_{2k+1}, b_{2k+1})}{\frac{\gamma_1}{\gamma_2}(a_{2k+2}, b_{2k+2}}\right]\frac{1}{\gamma_2(a_{m}, b_{m})}.
$$

\item If $\frac{2}{r_{2} + 1} = \mu_2$, then $\alpha^*= 0$ and taking $(a_0, b_0) = (x(0), y(0))$,
\begin{equation}
h_{0} : z_0 \longmapsto 2e^{z_0\cdot (a_0, b_0)} + \sum_{m=-\infty}^{-1} \kappa_m(\alpha^*)e^{z_0\cdot (a_{m}, b_{m})} + \sum_{m=2}^{+\infty} \tilde\kappa_m(\alpha^*)e^{z_0\cdot (a_{m}, b_{m})}
\end{equation}
where 
$$
\tilde\kappa_m(\alpha^*)= (-1)^{m+1} \frac{\gamma_1(a_{1}, b_{1})}{\frac{\gamma_1}{\gamma_2}(a_{2}, b_{2})}\left[\prod_{k=1}^{\lfloor \frac{m}{2} \rfloor-1} \frac{\frac{\gamma_1}{\gamma_2}(a_{2k+1}, b_{2k+1})}{\frac{\gamma_1}{\gamma_2}(a_{2k+2}, b_{2k+2})}\right]\frac{1}{\gamma_2(a_{m}, b_{m})}.
$$
\end{itemize}
\item For $\alpha = \alpha^{**}$, symmetrical formulae hold replacing $r_1$ by $r_2$, $\mu_1$ by $\mu_2$ and $0$ by $\frac{\pi}{2}$.

\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

