{"assumptions":[],"created_at":"2026-10-26T20:46:26.252105+00:00","domain":"probability theory","id":"claim_4fa5a1ff5c5e2fbb1b7d0635178c243eec2b8bff9860caadf3fdc427805dc510","kind":"definition","schema_version":1,"statement":"[Defn 2 of arXiv:2605.23292, 'Second-order Poincaré inequalities and localization on the Poisson space'] ($BL$-localization of scores in space and in time) Given $\theta >0$, and $\theta' \in (0,1/2]$ the score $\xi$ is said to  $BL(\theta, \theta')$\textbf{-localize on the space-time domain $(X,d,\nu) \times (\R,\mu)$} if there exist families of scores $(\xi^{[r]})_{r>0}$ and $(\xi^{(s)})_{s \in \R}$ and non-increasing functions $\psi :[0,\infty) \rightarrow [0,2]$, with $\psi(0)=2$, and $\phi :\R \rightarrow [0,2]$ such that
\begin{itemize}
    \item   for any locally finite $\chi \in  \mathbf{N}$, and any $z \in X$, $t_z \in \R$ we have for any $r>0$,
    \begin{align}
        &\xi^{[r]}((z,t_{z},M_z),\chi) = \xi^{[r]}((z,t_{z},M_z),\chi \cap (B_r(x) \times \R \times \MM)) \qquad \QQ-\text{a.s.} \\
        \intertext{and for any $s \in \R$}
        &\xi^{(s)}((z,t_{z},M_z),\chi) = \ind{t_{z}<s}\xi^{(s)}((z,t_{z},M_z),\chi \cap \XX \times (-\infty,s) \times \MM) \qquad \QQ-\text{a.s.} ;
    \end{align}
        \item \sloppy for  any $z_1,...,z_4,x,y \in X$, and $t_{z_1},...,t_{z_4},t_{x},t_y \in \R$, and any $\mathcal{A}_i \subseteq \{(z_1,t_{z_1}),...,(z_4,t_{z_4}),(x,t_{x}),(y,t_y)\}$ for $i=1,\hdots,4$, we have for all  $r > 0$
    \begin{equation} 
    d_{BL} \bigg( \big(\xi((z_i,t_{z_i},M_{z_i}),\hat{\mathcal{P}} \cup \hat{\mathcal{A}}_i)\big)_{i=1,...,4},\
    \big(\xi^{[r]}((z_i,t_{z_i},M_{z_i}),\hat{\mathcal{P}} \cup \hat{\mathcal{A}}_i)\big)_{i=1,...,4} \bigg) \leq \psi(r),
    \end{equation}
    and for all $s \in \R$
    \begin{equation}
    d_{BL} \bigg( \big(\xi((z_i,t_{z_i},M_{z_i}),\hat{\mathcal{P}} \cup \hat{\mathcal{A}}_i)\big)_{i=1,...,4},\
    \big(\xi^{(s)}((z_i,t_{z_i},M_{z_i}),\hat{\mathcal{P}} \cup \hat{\mathcal{A}}_i)\big)_{i=1,...,4} \bigg) \leq \phi(s),
    \end{equation}
    \item we have
    \be 
    {\cal I}_{\psi}(\theta) := {\cal I}_{\psi,X}(\theta):= \max \big(1, 
     \sup_{x \in X} \int_{X} \psi \left( \frac{d(x,z)}{2} \right)^\theta \nu(dz)\big) < \infty;
    \ee
    and 
    \be 
     {\cal I}_{\phi}(\theta') := \max \big(1, \int_\R \phi(t) ^{\theta'} \mu(dt)\big) < \infty.
    \ee
\end{itemize}
The collections $(\xi^{[r]})_{0<r<\infty}$ and
$(\xi^{(s)})_{s \in \R}$,
satisfying \eqref{stoppingspace} and \eqref{stoppingtime}, respectively, are said to be families of {\em short-range scores in  space} and {\em short-range scores in  time}, respectively.
Lastly we put for all $p > 0$
\begin{align}
        M^\xi_{p,X} :=  \max\bigg\{ & {1}, \sup_{r \in (0,\infty]} \sup_{\substack{(z,t_z) \in X \times \R \\ \mathcal{A} \subset X \times \R, |\mathcal{A}|\leq p+1}} \E |\xi^{[r]}((z,t_z,M_z),\hat{\P} \cup \hat{\mathcal{A}})|^p,\notag\\
    &\sup_{s \in \R}
   \sup_{\substack{(z,t_z) \in X \times \R \\ \mathcal{A} \subset X \times \R, |\mathcal{A}|\leq p+1}} \E |\xi^{(s)}((z,t_z,M_z),\hat{\P} \cup \hat{\mathcal{A}})|^p \bigg\}, 
\end{align}
where $\xi^{[\infty]}=\xi$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:38:08.415103+00:00","domain":"probability theory","id":"claim_4fa5b160a9cb5e8578bac6a2fe535849a000164370c7f36094389bdb0eaf9586","kind":"theorem","schema_version":1,"statement":"[Proposition prop: derivatives for cylindrical coordinates of arXiv:2609.02073, 'Existence of closed non-planar $p$-elasticae'] Let $\gamma(s) = (r(s), \theta(s), z(s))$. Then $Q=\frac{p^2C}{|J_0|^3}$ and moreover
