{"assumptions":[],"created_at":"2026-10-27T16:22:59.724435+00:00","domain":"probability theory","id":"claim_50868292db06dbf0fc313de479c5c4a866665448bf711161aa2fa27c5b2dcc15","kind":"definition","schema_version":1,"statement":"[Definition def:cip-lip of arXiv:2608.29708, 'Intuitionistic and Constructive Modal Logics for Classical Modal Logicians'] A logic $L$ with a language $\mathscr{L}$ is said to enjoy \emph{Lyndon interpolation property (LIP)}
  if for every $\varphi, \psi \in \mathscr{L}$ such that $\varphi \to \psi \in L$,
  there is $\chi \in \mathscr{L}$ that satisfies the following conditions:
  \begin{enumerate}
    \item $\mathrm{V}^\bullet(\chi) \subseteq \mathrm{V}^\bullet(\varphi) \cap \mathrm{V}^\bullet(\psi)$, for each $\bullet \in \set{+, -}$;
    \item $\set{ \varphi \to \chi, \chi \to \psi } \subseteq L$.
  \end{enumerate}
  A logic $L$ is said to enjoy \emph{Craig interpolation property (CIP)} if it satisfies the above,
  but with the first condition of $\chi$ replaced by $\mathrm{V}(\chi) \subseteq \mathrm{V}(\varphi) \cap \mathrm{V}(\psi)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:37:15.262903+00:00","domain":"probability theory","id":"claim_50873a0373eef3071f03af806b057351f5dd861468f077340255a335609e8863","kind":"lemma","schema_version":1,"statement":"[Lemma 6 (Sparse families: Bernoulli selection) of arXiv:2607.12263, 'Random sets are close to low-discrepancy sets'] Fix \(0 < \delta < 1\). Let \(A_1,\ldots,A_D\) be an \(s\)-sparse family of subsets of $[N]$. Assume that $N$ has the form $N=n2^k$ for some positive integers $n$ and $k$. Let \(S \subset [N]\) be a random subset obtained by selecting each point independently with probability $2^{-k}$. Then there is a randomized algorithm that produces an $n$-element subset $Q\subset [N]$ such that
\begin{equation}
\E \abs{Q\cap S} \ge n(1-\delta)-\sqrt n
\end{equation}
and
\begin{equation}
	\abs*{ \frac{\abs{A_j \cap Q}}{n} - \frac{\abs{A_j}}{N}} 
	\le C\frac{\sqrt{s}}{n}\left(\frac{k}{\delta}+\log(2n)\right)
	\qquad \text{for each } j.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:49:49.203976+00:00","domain":"probability theory","id":"claim_5087e14a5c95dd236cdef47479e5810f167a7e7f8f981b3cd52d181ffcb1564a","kind":"theorem","schema_version":1,"statement":"[Proposition 23 of arXiv:2604.26898, '\bf Stochastic Scaling Limits and Synchronization \\by Noise in Deep Transformer Models'] Let $T > 0$ and step size $\dt = T/L \leq 1$. Let the discrete time points be $t_\ell = \ell \dt$ for $\ell=0, \dots, L$.
    Consider a system of $N$ particles governed by the SDE
    \begin{equ}
        dX^i_t = a(X^i_t, \mathbf{X}_t)\,dt + \sum_{k=1}^\infty \tilde \sigma_k(X^i_t)\, dB^k_t, \qquad X^i_0 = x^i_0,
    \end{equ}
    and its continuous-time Euler-Maruyama interpolation
    \begin{equ}
        \hat X^i_t = x^i_0 + \int_0^t a(\hat X^i_{t_{\ell_s}},\hat{\mathbf X}_{t_{\ell_s}})\,\dd s + \sum_{k=1}^\infty \int_0^t \tilde \sigma_k(\hat X^i_{t_{\ell_s}})\,\dd B_s^k.
    \end{equ}
    Assume that there exist constants $K_2,K_3>0$ such that for all $N\in\mathbb N$ and $x,y\in(\R^d)^N$,
    \begin{align}
        \E[|X_0^i|^2] &< \infty, \\
        \frac1N\sum_{i=1}^N \left(|a(x^i,\mathbf x)-a(y^i,\mathbf y)|^2 + \sum_{k=1}^\infty |\tilde \sigma_k(x^i)-\tilde \sigma_k(y^i)|^2\right)
        &\le K_2 \frac1N\sum_{i=1}^N |x^i-y^i|^2,  \\
        |a(x^i,\mathbf x)|^2 + \sum_{k=1}^\infty |\tilde \sigma_k(x^i)|^2 &\le K_3. 
    \end{align}
    Then
    \begin{equ}
    \E\left[\sup_{0\leq t\leq T}\frac{1}{N}\sum_{i=1}^N |X^i_t - \hat{X}^i_t|^2\right]
    \leq 16 K_2 K_3 (4T+T^2) e^{4 K_2 (4+T) T} \dt.
    \end{equ}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:15:34.546323+00:00","domain":"probability theory","id":"claim_5089be59bc419553b6007533eade3836f8ea9be14d2f88a3cb33463c028a5026","kind":"concept","schema_version":1,"statement":"[Theorem 39 (Contraction at $Q_\ell$) of arXiv:2609.03332, 'Singularity Models of Finite-Time K\"ahler-Ricci Flows'] Let $\widehat{M}$ be the compactification of $(0,\ell) \times P$ such that $Q_0 := N' = N_2 \times \cdots \times N_r$ is adjoined at $\{s = 0\}$, and $Q_\ell := \mathbb{CP}^m \times N'$ is adjoined at $\{s = \ell\}$. Suppose
$T = \min_{k \geq 2}\{T_k^\ell\} < \min\big\{T_F', \min_{k\geq 2}\{T_k^0\}\big\}$.

Let $\mathcal{I}_\infty$ be the subset of $\{2, \cdots, r\}$ such that $i_\infty \in \mathcal{I}_\infty$ if and only if $T_{i_\infty}^\ell = T$. Let $\mathcal{L}_{\mathcal{I}_\infty}$ be the line bundle obtained by restricting the normal bundle $\mathcal{N}_{Q_\ell}$ of $Q_\ell \subset \widehat{M}$ --- the line bundle $L = P \times_{\mathrm{U}(1)} \mathbb{C}$ of Proposition \ref{prop:bolt-closing} --- to $\prod_{i_\infty \in \mathcal{I}_\infty} N_{i_\infty}$; then $c_1 ( \mathcal{L}_{\mathcal{I}_\infty} ) = \sum_{i_\infty \in \mathcal{I}_\infty} q_{i_\infty} a_{i_\infty}$, with each $q_{i_\infty} < 0$.

Let $K_j := (T-t_j)^{-1}$, and fix $\bar{x}' \in Q_\ell$. Consider the rescaled and dilated sequence $g_j(t) = K_j g(t_j + K_j^{-1}t)$ defined on $t \in [-K_j t_j, K_j(T-t_j))$. Then, along a subsequence,
\begin{equation}
\begin{gathered}
\big( \widehat{M}, \; g_j (t), \; \bar{x}' \big) \;\longrightarrow\; \Big( \operatorname{Tot} \big( \mathcal{L}_{\mathcal{I}_\infty} \big) \times \mathbb{C}^{n''} \,, \;\; g_L (t) \oplus g_{\mathbb{C}^{n''}}, \bar{x}'\Big) \,, t \in \big( - \infty, 1 \big).
\end{gathered}
\end{equation}
Here $n'' = m + \sum_{k \geq 2, \, k \not\in \mathcal{I}_\infty} \dim_{\mathbb{C}} N_{k}$, $\operatorname{Tot} ( \mathcal{L}_{\mathcal{I}_\infty} )$ is the total space of the line bundle $\mathcal{L}_{\mathcal{I}_\infty} \to \prod_{i_\infty \in \mathcal{I}_\infty} N_{i_\infty}$, and $g_L$ is a complete gradient shrinking K\"ahler--Ricci soliton of ansatz form on $\operatorname{Tot} ( \mathcal{L}_{\mathcal{I}_\infty} )$ --- the Feldman--Ilmanen--Knopf shrinker in \cite{FIK} when the base is a projective space, and its multi-base generalization by Dancer--Wang in \cite{DW2011} in general. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

