{"assumptions":[],"created_at":"2026-10-27T22:51:15.035465+00:00","domain":"probability theory","id":"claim_50fd482e9643e803c519d11df6c8a8dca1de1e2610083dabf4b93c35654e9b9b","kind":"concept","schema_version":1,"statement":"[Theorem 6ttagu of arXiv:2609.03926, 'Overcolored Partition $k$-tuples Restricted by Parity of the Parts'] {taguchi}}}]
