{"assumptions":[],"created_at":"2026-10-27T14:09:34.454614+00:00","domain":"probability theory","id":"claim_510f6465fca5e4fb4a92b3e2eb60b3c06367affc5e0f17a313d74469d12a7a9c","kind":"concept","schema_version":1,"statement":"[Proposition Moments1 of arXiv:2505.11721, 'Variational principles for Hausdorff and packing dimensions of fractal percolation on self'] \begin{enumerate}  Let $q\in(1,2]$. 
\item Suppose that $\sum_{n\ge 1}\left(\prod_{k=1}^n \phi_{W^{(k)}}(q)\right)^{\frac{1}{q}}<+\infty$. Then, $\lim_{N\to +\infty} \sum_{n=1}^N H(W^{(n)})=+\infty$. Also, for all $v\in \mathcal I^*$, $(Y_n(v))_{n\ge 0}$ converges to $Y(v)$, almost surely and in $L^q$ norm. In particular, $\mathbb{E}\left(Y(v)\right) = 1$. Moreover, there exists  a constant $C=C(\# \mathcal I)> 0$  such that for all  $v\in \mathcal I^*$, $\|Y(v)\|_q\le C \sum_{n=0}^{\infty} \left(\prod_{k=1}^n \phi_{W^{(|v|+k)}}(q) \right)^{\frac{1}{q}} < +\infty$, with the convention that  the empty product at $n=0$ is equal to 1. 

In particular, if $\sup_{n\ge 1} \phi_{W^{(n)}}(q)<1$, then $\sup_{v\in\mathcal{I}^*}(\|Y(v)\|_q)_{v\in\mathcal{I}^*}<+\infty$. 

\item Suppose that  $\sup_{n\ge 1} \phi_{W^{(n)}}(q)<+\infty$ and $\liminf_{N\to +\infty}N^{-1}\sum_{n=1}^N H(W^{(n)})>0$. Then, there exists $\hat q\in (1, q)$ such that 
 $\sum_{n\ge 1}\left(\prod_{k=1}^n \phi_{W^{(k)}}(q')^{\frac{1}{q'}}\right)<+\infty$ for all $q'\in (1,\hat q]$.  

Let  $\epsilon>0$ such that 
\begin{equation}
\sum_{n=1}^NH(W^{(n)})\ge n\epsilon \text{ for all $N$ sufficiently large. }
\end{equation}
Let $N_\epsilon=\min\big \{N\ge 1:\, \forall \, N'\ge N, \sum_{n=1}^{N'}H(W^{(n)})\ge N'\epsilon\big\}$. There exists  $\tilde q\in (1,\hat q]$ such that for $q'\in (1,\tilde q]$, there are constants $C=C(q',\#\mathcal I,\epsilon)\ge 1$ and $c=c(q',\# \mathcal I,\epsilon)>0$ such that for all $N\ge N_\epsilon$,  one has $\widetilde N\le \frac{\log (\#\mathcal{I})}{\epsilon} N$ and for $v\in \mathcal{I}^N$, 
\begin{equation}
B(N,q')\le \mathbb{E}\left((Y(v))^{q'}\right) \le \frac{CN^{q'} e^{cN(q'-1)^2}}{(1-e^{-\frac{(q'-1)}{4q'}\epsilon})^{q'}}B(N,q'),
\end{equation}
where $B(N,q')=\max \Big (1, \exp \big [-(q'-1)\sum_{n=N+1}^{\widetilde N}H(W^{(n)})\big ]\Big )$. 
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

