{"assumptions":[],"created_at":"2026-10-26T19:49:49.210788+00:00","domain":"probability theory","id":"claim_52c7de4a6ba8ee99dd6478b7e6166ba9cef270679b4ed007063c4c94541085ee","kind":"concept","schema_version":1,"statement":"[Lemma 27 of arXiv:2604.27242, 'Statistical Inference for Homogenization Limits Driven by Wiener or Hermite Processes'] Let \(\tau_t K^{\varepsilon}(x) = \varepsilon^{-1/2}g\left(\frac{t-x}{\varepsilon}\right)\) where \(g(s) = e^{-s}\int_0^se^vv^{H-3/2}dv\) be the kernel of the fastened fractional OU process for \(H>1/2\). Then as \(\varepsilon\to 0\) we have 
that \begin{itemize}
    \item If \(s<t\) then as \(\varepsilon\to 0\):
    \begin{equation}
    \int_{-\infty}^{t\wedge s}\tau_tK^{\varepsilon}(x)(s-x)^{H-3/2}dx \sim \varepsilon^{1-H}(t-s)^{2H-2}\beta(H-1/2,2-2H)
    \end{equation}
    \item If \(s>t\) then as \(\varepsilon\to 0\) we have the following decomposition \begin{equation}
\int_{-\infty}^{t\wedge s}\tau_tK^{\varepsilon}(x)(s-x)^{H-3/2}dx = A_t^{<} + A_t^{\varepsilon}
    \end{equation}
    where the first term behaves as \begin{equation}
A_t^{<} \sim \varepsilon^{1-H}(s-t)^{2H-2}\beta(H-1/2,2-2H)
    \end{equation}
and the second term is controlled by
\begin{equation}
A_t^{\varepsilon} \lesssim \varepsilon^{1/2}(s-t)^{H-3/2} 
\end{equation}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:24:34.414384+00:00","domain":"probability theory","id":"claim_52cc2fe3bd2d517d6e5a2414f53185872e903d175d2f38f99b5437a7e6bcb535","kind":"concept","schema_version":1,"statement":"[Proposition 9 ($\alpha$-fractional kernels $1 <\alpha<2$) of arXiv:2608.31099, '\bf On (fake) Stationarity in Stochastic Volterra Equations with Affine Drift and Regular '] Let $\lambda>0$ and let $\alpha\!\in (1,2)$.\\
		\smallskip
		\noindent $(a)$  The $\lambda$-resolvent $R_{\alpha, \lambda}$ satisfies $ R_{\alpha,1}= e_{\alpha}$ and $R_{\alpha, \lambda} = R_{\alpha,1}(\lambda^{1/\alpha}\cdot)$. The function $e_{\alpha}$ and thus $R_{\alpha, \lambda}$ are infinitely differentiable i.e. $\mathcal C^\infty$ on $(0, +\infty)$) with:
		{\small
			\begin{equation}
				\forall k \in \N, \quad e^{(k)}_\alpha(t) = F^{(k)}_\alpha(t) + G^{(k)}_\alpha(t) \quad \text{where}\quad	F^{(k)}_\alpha(t) = \int_0^{+\infty} e^{-tu} H^{(k)}_{\alpha}(u) \, du \;
			\end{equation}
		}
		\begin{equation}
			H^{(k)}_{\alpha}(u) := (-1)^k \frac{\sin(\alpha \pi) }{ \pi } \frac{u^{\alpha - 1 + k}}{u^{2\alpha} + 2u^{\alpha} \cos(\alpha \pi) + 1}\; \text{and} \; G^{(k)}_\alpha(t) = \frac2\alpha e^{t\cos \left( \frac{\pi}{\alpha} \right)} \cos \left[ t \sin \left( \frac{\pi}{\alpha} \right) - \frac{k \pi}{\alpha} \right].
		\end{equation}

		Moreover $R_{\alpha, \lambda}(0)=1$, $R_{\alpha,\lambda}(t) \leq 1 \quad \forall t\geq0$,  $R_{\alpha,\lambda}$ converges  to $0$.

		$R_{\alpha,\lambda}\!\in {\cal L}^{r}(\R_+)$ for every $r>\frac{1}{\alpha}$ and 
		$f_{\alpha, \lambda}:= -R'_{\alpha, \lambda}$ is infinitely differentiable, bounded converges to $0$ and satisfy:
		\[
		\forall\, t>0, \quad f_{\alpha, \lambda} (t):= -R'_{\alpha, \lambda} (t) = \lambda^{\frac{1}{\alpha}}\left(\int_0^{+\infty} e^{-\lambda^{\frac{1}{\alpha}}tu}uH_{\alpha}(u)du - \frac2\alpha e^{t \lambda^{\frac{1}{\alpha}}\cos \left( \frac{\pi}{\alpha} \right)} \cos \left[ t \lambda^{\frac{1}{\alpha}} \sin \left( \frac{\pi}{\alpha} \right) - \frac{\pi}{\alpha} \right]\right).
		\]
		\noindent $(b)$ Moreover, if  $\alpha\!\in (1, 2)$,$f_{\alpha,\lambda} \!\in {\cal L}^{p}(\R_+)$ for every $p \in (0,+\infty] $ and for every $\vartheta\!\in\big(0,\alpha-1\big)$
		\[| f_{\alpha ,\lambda}(t+\delta)-f_{\alpha,\lambda}(t)  | \leq h_{\alpha,\lambda}(t) \delta^{\vartheta} \quad \text{with}\quad  h_{\alpha,\lambda} \in {\cal L}^1(\R_+) \cap {\cal L}^\infty(\R_+) \quad \text{and}\quad h_{\alpha,\lambda}*\varsigma^2_{\alpha,\lambda,c} \in {\cal L}^\infty(\R_+)\] (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:38:37.402245+00:00","domain":"probability theory","id":"claim_52cc8a12915e53fe6088abde3d6f6ab1a76c2660d1f1dbcc684e1618adc73846","kind":"concept","schema_version":1,"statement":"[Theorem 4 of arXiv:2605.15386, 'The non-central gamma sum and difference distributions: exact distribution and asymptotic '] 1. Suppose that $\lambda_1,\lambda_2\not=0$. Then, for $x>0$,
	\begin{align}
	f_{X_1-X_2}(x)&=D_1(x)\int_{0}^{\infty}t^{(\alpha_2-1)/2}(1+t)^{(\alpha_1-1)/2}\exp\bigg(-\bigg(\frac{1}{\beta_1}+\frac{1}{\beta_2}\bigg)xt\bigg)\nonumber\\
	&\quad\times I_{\alpha_1-1}\bigg(2\sqrt{\frac{\lambda_1x(1+t)}{\beta_1}}\bigg)I_{\alpha_2-1}\bigg(2\sqrt{\frac{\lambda_2xt}{\beta_2}}\bigg)\,\mathrm{d}t,\\
	f_{X_1+X_2}(x)&=D_1(x)\int_{0}^{1}t^{(\alpha_2-1)/2}(1-t)^{(\alpha_1-1)/2}\exp\bigg(\bigg(\frac{1}{\beta_1}-\frac{1}{\beta_2}\bigg)xt\bigg)\nonumber\\
	&\quad\times I_{\alpha_1-1}\bigg(2\sqrt{\frac{\lambda_1x(1-t)}{\beta_1}}\bigg)I_{\alpha_2-1}\bigg(2\sqrt{\frac{\lambda_2xt}{\beta_2}}\bigg)\,\mathrm{d}t,
	\end{align}
	where
	\begin{align}
		D_1(x)=\bigg(\frac{\lambda_1}{\beta_1}\bigg)^{(1-\alpha_1)/2}\bigg(\frac{\lambda_2}{\beta_2}\bigg)^{(1-\alpha_2)/2}\beta_1^{-\alpha_1}\beta_2^{-\alpha_2}x^{(\alpha_1+\alpha_2)/2}\mathrm{e}^{-\lambda_1-\lambda_2-x/\beta_1}\nonumber.
	\end{align}
	2. Suppose that $\lambda_1=0$ and $\lambda_2\not=0$. Then, for $x>0$,
	\begin{align}
		f_{X_1-X_2}(x)&=D_2(x)\int_{0}^{\infty}t^{(\alpha_2-1)/2}(1+t)^{\alpha_1-1}\exp\bigg(-\bigg(\frac{1}{\beta_1}+\frac{1}{\beta_2}\bigg)xt\bigg)I_{\alpha_2-1}\bigg(2\sqrt{\frac{\lambda_2xt}{\beta_2}}\bigg)\,\mathrm{d}t,\\
	f_{X_1+X_2}(x)&=D_2(x)\int_{0}^{1}t^{(\alpha_2-1)/2}(1-t)^{\alpha_1-1}\exp\bigg(\bigg(\frac{1}{\beta_1}-\frac{1}{\beta_2}\bigg)xt\bigg)I_{\alpha_2-1}\bigg(2\sqrt{\frac{\lambda_2xt}{\beta_2}}\bigg)\,\mathrm{d}t,\nonumber
	\end{align}
	where 
	\begin{align}
		D_2(x)&=\frac{1}{\Gamma(\alpha_1)}\bigg(\frac{\lambda_2}{\beta_2}\bigg)^{(1-\alpha_2)/2}\beta_1^{-\alpha_1}\beta_2^{-\alpha_2}x^{(2\alpha_1+\alpha_2-1)/2}\mathrm{e}^{-\lambda_2-x/\beta_1}\nonumber.
	\end{align}
	3. Suppose that $\lambda_2=0$ and $\lambda_1\not=0$. Then, for $x>0$,
		\begin{align}
		f_{X_1-X_2}(x)&=D_3(x)\int_{0}^{\infty}t^{\alpha_2-1}(1+t)^{(\alpha_1-1)/2}\exp\bigg(-\bigg(\frac{1}{\beta_1}+\frac{1}{\beta_2}\bigg)xt\bigg)I_{\alpha_1-1}\bigg(2\sqrt{\frac{\lambda_1x(1+t)}{\beta_1}}\bigg)\,\mathrm{d}t,\\
		f_{X_1+X_2}(x)&=D_3(x)\int_{0}^{1}t^{\alpha_2-1}(1-t)^{(\alpha_1-1)/2}\exp\bigg(\bigg(\frac{1}{\beta_1}-\frac{1}{\beta_2}\bigg)xt\bigg)I_{\alpha_1-1}\bigg(2\sqrt{\frac{\lambda_1x(1-t)}{\beta_1}}\bigg)\,\mathrm{d}t,\nonumber
	\end{align}
	where 
	\begin{align}
		D_3(x)&=\frac{1}{\Gamma(\alpha_2)}\bigg(\frac{\lambda_1}{\beta_1}\bigg)^{(1-\alpha_1)/2}\beta_1^{-\alpha_1}\beta_2^{-\alpha_2}x^{(\alpha_1+2\alpha_2-1)/2}\mathrm{e}^{-\lambda_1-x/\beta_1}\nonumber.
	\end{align}
	4. Integral representations for the PDF $f_{X_1-X_2}(x)$ that hold for $x<0$ are obtained by replacing $(x,\alpha_1,\alpha_2,\beta_1,\beta_2,\lambda_1,\lambda_2)$ by $(-x,\alpha_2,\alpha_1,\beta_2,\beta_1,\lambda_2,\lambda_1)$ in formulas (\ref{diffint1}), (\ref{diffint2}) and (\ref{diffint3}). (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

