{"assumptions":[],"created_at":"2026-10-27T11:40:59.404827+00:00","domain":"probability theory","id":"claim_52dae53b9c0b28829b2162d28902aa0da5893f1ca85dde10913641504a96a488","kind":"theorem","schema_version":1,"statement":"[Proposition 35 of arXiv:2609.03976, '2609.03976'] The partial differential equations 
	\begin{flalign*}
		\sum_{i=1}^{n}\partial_{i}g_{i,0,...,0}&=-1,   \\
		\sum_{i=1}^{n}\partial_{i}g_{i,\alpha_{1},...,\alpha_{r}}&=\sum_{i=1}^{n}\sum_{k=1}^{r}\partial_{i}f_{k} \cdot g_{i,\alpha_{1},...,\alpha_{k}-1,...,\alpha_{r}}
	\end{flalign*}
	do not have finite polynomial solutions if and only if there exist polynomials $P_{\alpha_{1},...,\alpha_{r}}$ indexed by $\alpha_{1},...,\alpha_{r} \in \mathbb{Z}_{\ge 0}$ satisfying the following conditions.

	$(1)$ $P_{\alpha_{1},...,\alpha_{r}}$ is homogeneous of degree $d \cdot (\alpha_{1}+...+\alpha_{r})$,

	$(2)$ $P_{0,...,0} \neq 0$,

	$(3)$ $x_{i}P_{\alpha_{1},...,\alpha_{r}}(x)=\sum_{k=1}^{r}\partial_{i}f_{k}(\partial) \cdot P_{\alpha_{1},...,\alpha_{k}+1,...,\alpha_{r}}(x)$, where $\partial_{i}f_{k}(\partial)(1 \le k \le r)$ denotes the differential operator obtained by replacing every $x_{j}$ with the corresponding $\partial_{j}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:27:11.401425+00:00","domain":"probability theory","id":"claim_52dbc3ee8114f6db87c170656300a04d6796fc1e65c64cace4ade5a74fcb0af5","kind":"concept","schema_version":1,"statement":"[Proposition p: uniformity with random field density of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Suppose that $\Phi$ is an invariant complex random measure that is locally absolutely square-integrable. Further, suppose that $Z$ is an invariant $\C$-valued random field on $\R^d$ such that
\begin{equation}
    \int \BE_{0,y}^{|\Phi|}[|Z(y)Z(0)|] \, \alpha_{|\Phi|}(dy) < \infty.
\end{equation}
Then $Z\cdot\Phi$ is locally absolutely square-integrable. Further, if $\Phi$ is nonnegative and $p$-uniform with $p\leq0$ and
\begin{equation}
    \int \big|\BE_{0,y}^{\Phi}[Z(y)\overline{Z(0)}] - |\BE_{0}^{\Phi}[Z(0)]|^2\big| (1+\|y\|)^{p} \, \alpha_{\Phi}(dy) < \infty,
\end{equation}
then $Z\cdot\Phi$ is also $p$-uniform. If $p<0$, beyond $p$-uniformity also transfers. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

