        $$
        \sup_{t \in [0,T]}\|\bm{\psi}_t|_{{\color{NavyBlue}{\mathbf{v}}}}\|_{\sigX[]} \leq C'_{\bm{p}, T, {\color{NavyBlue}{\mathbf{v}}}} \left(\left(1 + \frac{1}{\varepsilon \inf_{t \in [0,T]} |\bm{u}_t^{{\color{NavyBlue}{\mathbf{\varnothing}}}}|}\right)(1 + M_{\bm{p}}(\sigX[])) \exp\left(C_{\bm{p}, T} (1 + M_{\bm{p}}(\sigX[]))^{\deg_{{\color{NavyBlue}{\mathbf{1}}}}(\bm{p})} \right)\right)^{|{\color{NavyBlue}{\mathbf{v}}}|}.
        $$

    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:40:26.992684+00:00","domain":"probability theory","id":"claim_530f9cd1c53f9bcfc23a5cc54ea3505b69f51dd9a2e73eaca9c09262a1cbaa9b","kind":"concept","schema_version":1,"statement":"[Lemma lem-LDPtechnical of arXiv:2604.14318, '\large The free energy of the interacting Bose gas:\\\medskip a variational description \\'] On a Polish space ${\mathcal X }$, assume that an i.i.d.~sequence $(X_z)_{z\in[N]}$ is given  and another sequence $(X_z^{{{\scriptscriptstyle{({N}})}}})_{z\in[N]}$ that satisfies
\begin{equation}
\lim_{N \to\infty}\frac 1N\sum_{z=1}^N \log \mathbb{E}\big[{\operatorname e }^{f(X_z^{{{\scriptscriptstyle{({N}})}}})}\big] =\log\mathbb{E}[{\operatorname e }^{f(X_1)}],\qquad f\in{\mathcal C }_{\rm b}({\mathcal X }).
\end{equation}
Then the empirical measures $\frac 1N\sum_{z=1}^N \delta_{X_z^{{{\scriptscriptstyle{({N}})}}}}$ and $\frac 1N\sum_{z=1}^N \delta_{X_z}$ are exponentially equivalent. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:25:41.598328+00:00","domain":"probability theory","id":"claim_53105727a57938d846bd51932e3534efce680743f04f3f84c95c9f0f9557c27a","kind":"lemma","schema_version":1,"statement":"[Lemma lem:resolventconvergence of arXiv:2608.11603, 'Continuous-time directed polymers to the Critical SHF via moments'] {}
	 Fix $\alpha, \alpha' \in \mathsf{Pair}[\![n]\!]$ with $\alpha \neq \alpha'$. Then, there exists a $\theta_{\star} \in \mathbb{R}$ for which the following holds: for every $\lambda \gtrsim e^{2\theta+ 4\pi\mathfrak{K}} + 1$, there exists $\varepsilon_{0}(\lambda) > 0$ such that for all $\varepsilon < \varepsilon_{0}(\lambda)$, the prelimiting resolvents satisfy the following:
	\begin{subequations}
	\begin{align}
	\normop{\mathcal{G}_{\varepsilon\alpha}(\lambda)}  & \lesssim \lambda^{-\frac{1}{2}} \qquad \qquad \qquad   \text{ and } \qquad \qquad \quad \normop{\mathcal{G}_{\varepsilon\alpha}(\lambda) -\mathcal{G}_{\alpha}(\lambda)} \to 0,    \\ 
	\normop{\mathcal{G}^{\ast}_{\varepsilon \alpha}(\lambda)} & \lesssim \lambda^{-\frac{1}{2}} \qquad \qquad \qquad   \text{ and } \qquad \qquad \quad \normop{\mathcal{G}^{\ast}_{\varepsilon \alpha}(\lambda) -\mathcal{G}^{\ast}_{\alpha}(\lambda)} \to 0,  \\
	\normop{\mathcal{G}_{\varepsilon \alpha\alpha'}(\lambda)} & \lesssim 1 \qquad \qquad \qquad  \quad \, \text{  and } \qquad \qquad \quad \normop{\mathcal{G}_{\varepsilon \alpha\alpha'}(\lambda) -\mathcal{G}_{\alpha\alpha'}(\lambda)} \to 0,  \\
	\normop{\prediag{\theta}{\alpha}(\lambda)} & \lesssim (\log\lambda - \theta )^{-1}  \quad \quad \,   \text{ and } \qquad \qquad \quad \prediag{\theta}{\alpha}(\lambda) -\diag{\theta_{\star}}{\alpha}(\lambda) \to 0 \, \, \text{strongly}\, \, . 
	\end{align}
	\end{subequations}
	Moreover, the series in equation~(equation eqn:prelimiting_resolvent of the paper) converges absolutely in operator norm, and the whole expression converges strongly to the limiting resolvent defined in equation~(equation eqn:limiting_resolvent of the paper).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:51:11.973360+00:00","domain":"probability theory","id":"claim_5312a3293e7d785e777fd86a197f08068c91af77b29d35efe00fd76f83df93ff","kind":"theorem","schema_version":1,"statement":"[Theorem 35 (Kernel support theorem) of arXiv:2608.08756, 'Infinite-Dimensional L\'evy Area and Spectral Ancestry'] For every $r$,
\begin{equation}
 \ker(\operatorname{gr}_r\mathcal R)
 =\operatorname{supp}_L\bigl(\mathfrak K_r(\mathcal R)\bigr)^\perp
 \subseteq G_r^*.

\end{equation}
Consequently, $\mathcal R$ is strict if and only if
\begin{equation}
