{"assumptions":[],"created_at":"2026-10-27T06:45:05.567699+00:00","domain":"probability theory","id":"claim_53e1d24a23db384bf1ec9712e253517fc877a903956f27ef039754cd66fa2fb2","kind":"concept","schema_version":1,"statement":"[Proposition 16 of arXiv:2608.05679, 'Small ball probabilities and Chung's law of the iterated logarithm for Gaussian Volterra p'] Assume that Condition \eqref{eq constant cond} holds. Then  there exists a constant $c_{5,2} > 0$ such that,  for every $0 < t < u$ and $\theta, \eta > 0$,
\begin{equation}
\mathbb{P}\left\{ M(t) \le \theta t^H,\; M(u) \le \eta \right\}
\le 2\varphi(\theta) \exp\left(-c_{5,2} (u-t) u^{\frac{2\alpha + 2\beta}{2\gamma+3}} \eta^{-\frac{2}{2\gamma+3}}\right).
\end{equation}

\begin{proof}
	If $$(u-t) u^{\frac{2\alpha + 2\beta}{2\gamma+3}} \eta^{-\frac{2}{2\gamma+3}} \le 2,$$ then \eqref{onemax} holds with $c_{5,2} = (\log 2)/2$. Hence  it remains to consider the case 
    \begin{align}
	(u-t) u^{\frac{2\alpha + 2\beta}{2\gamma+3}} \eta^{-\frac{2}{2\gamma+3}}  > 2.
    \end{align}
    We divide the remainder of the proof into three steps.


\noindent	\textbf{Step 1.}  Starting from $t_0:=t$,  define  a sequence $\{t_n:\, n\ge 0\}$ recursively by 
	\begin{equation}
		t_n - t_n^{-\frac{\alpha + \beta}{\lambda}} \eta^{\frac{1}{\lambda}} = t_{n-1}.
	\end{equation} 

    The sequence $\{t_n\}$ is strictly increasing and diverges to infinity. Indeed, if $t_n\to L<\infty$, then 
	$$
t_n-t_{n-1}
\longrightarrow
L^{-\frac{\alpha+\beta}{\lambda}}
\eta^{\frac{1}{\lambda}}\neq 
0,
$$
which contradicts the convergence of $\{t_n\}_{n\geq0}$.

    For each integer $k\ge0$,  define  the event
	$$
	A_k := \left\{M(t) \le \theta t^H\right\} \cap \left\{M(t_k) \le \eta\right\}.
	$$
Since $t_0=t<u$ and $t_k\to\infty$ as $k\to\infty$, there exists a unique integer $k_0\geq0$ such that
$$
t_{k_0}\leq u<t_{k_0+1}.
$$

Since $M$ is nondecreasing and $t_{k_0}\leq u$, we have
\begin{equation}
A_{k_0} \supseteq \left\{M(t) \le \theta t^H\right\} \cap \left\{M(u) \le \eta\right\}.
\end{equation}
It remains  to  prove that there  exist constants   $\rho\in(0,1)$ and $c_{5,3}>0$ such that
\begin{equation}
\mathbb{P}\{ A_k \} \le \varphi(\theta)\rho^k, \qquad k\ge 0.
\end{equation}
and  
\begin{equation}
k_0 > c_{5,3}(u-t)u^{\frac{\alpha+\beta}{\lambda}}\eta^{-\frac{1}{\lambda}}.
\end{equation}
     Therefore, combining \eqref{ak0-sup}, \eqref{pak}, and \eqref{k0-bound}, we obtain \eqref{onemax}.

	\textbf{Step 2.} We  prove \eqref{pak} by induction on $k$.  The case $k=0$ follows from  \eqref{Eq:sb31}.  
	For the induction step,  observe that
	\[
	A_{k+1} \subseteq A_k \cap \bigl\{ |X(t_{k+1}) - X(t_k)| \le 2\eta \bigr\}.
	\]
	By \eqref{xt-xs}, we have 
	\begin{align*}
		X(t_{k+1}) - X(t_k) 
		&= \int_0^{t_k} r^\alpha \left( \int_{t_k}^{t_{k+1}} y^\beta (y - r)^\gamma dy \right) dW_r \\
		&\quad + \int_{t_k}^{t_{k+1}} r^\alpha \left( \int_r^{t_{k+1}} y^\beta (y - r)^\gamma dy \right)dW_r\\
		&= :J_1 + J_2.
	\end{align*}

By the lower bound for $I_2$ established in the proof of Lemma~\ref{lem mom} and \eqref{tnn-1}, we get
	$$\operatorname{Var}(J_2) \ge c_{2,1} t_{k+1}^{2\alpha+2\beta}|t_{k+1} - t_k|^{2\gamma+3} = c_{2,1}{\eta^2},$$ 
	which implies that 
\[
\mathbb{P}\{ |J_2| \le 2\eta \} \le \Phi(2/\sqrt{c_{2,1}}) - \Phi(-2/\sqrt{c_{2,1}})=:\rho.
\]
By Anderson's inequality \cite{Anderson55} and the independence of $J_2$ and $\sigma\{W(r): r \le t_k\}$, we obtain
\[
\begin{aligned}
\mathbb{P}\{ A_{k+1} \}
&\le \mathbb{E}\left[ \mathbb{P} \left\{ A_k \cap \{ |J_1+J_2| \leq 2\eta \} \mid \sigma\{W(r): r\le t_k\} \right\} \right] \\
&\le \mathbb{E}\Bigl[ \mathbf{1}_{A_k} \cdot \mathbb{P}\bigl\{ |J_1+J_2|\le 2\eta \mid \sigma\{W(r): r\le t_k\} \bigr\} \Bigr] \\
&\le \mathbb{P}\{ A_k \} \cdot \mathbb{P}\{ |J_2|\le 2\eta \} \\
&\le \mathbb{P}\{ A_k \} \rho.
\end{aligned}
\]
	Thus, \eqref{pak}  follows  by induction. 

\noindent	\textbf{Step 3.}   We now prove \eqref{k0-bound}. 
We first  claim that   
	\begin{equation}
		t_{k_0}=t_{k_0+1}-t_{k_0+1}^{-\frac{\alpha+\beta}{\lambda}}\eta^{\frac 1 \lambda}
		>u-u^{-\frac{\alpha+\beta}{\lambda}}\eta^{\frac 1 \lambda}.
	\end{equation}
    To this end,   define $$f(x):=x-x^{-\frac{\alpha+\beta}{\lambda}}\eta^{\frac1 \lambda}, \ \ x>0.$$  
  If $\alpha+\beta\ge 0$, then $f'(x)>0$ and $f$ is strictly increasing. If $ (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

