{"assumptions":[],"created_at":"2026-10-27T12:48:49.896431+00:00","domain":"probability theory","id":"claim_542e089780225b953c1589d4c8585c89fcc91ecce26c5bd68f5b28b56b60db34","kind":"theorem","schema_version":1,"statement":"[Theo limittheo of arXiv:2510.23430, 'On the Martin boundary for discrete TASEP'] Let $\lambda(n)$ denote the random partition distributed according to $M^{\mathcal A,\mathcal B}_n$. Then $\lambda(n)'_1=\dots=\lambda(n)'_s=n$ almost surely and as $n\to\infty$
\begin{equation}
\left(\frac{\lambda(n)_1-\alpha_1n}{\sqrt{n\alpha_1(1+\alpha_1)}},\dots, \frac{\lambda(n)_k-\alpha_kn}{\sqrt{n\alpha_k(1+\alpha_k)}} \right) \to \mathbf x^{GUE}_{\mathcal A},
\end{equation}
\begin{equation}
\left(\frac{\lambda(n)'_{s+1}-\beta_{s+1}n}{\sqrt{n\beta_{s+1}(1-\beta_{s+1})}},\dots, \frac{\lambda(n)'_l-\beta_ln}{\sqrt{n\beta_l(1-\beta_l)}} \right) \to \mathbf y^{GUE}_{\mathcal B},
\end{equation}
where both convergences are in distribution.\footnote{The convergences (equation limitrows of the paper) and (equation limitcolumns of the paper) are considered separately, we do not claim anything about the joint law.} In particular, in probability, $\frac{\lambda(n)_i}{n}\to \alpha_i$ for $i\in [1,k]$ and $\frac{\lambda(n)'_i}{n}\to \beta_i$ for $i\in [1,l]$.","status":"unverified"}

