{"assumptions":[],"created_at":"2026-10-27T18:40:27.002679+00:00","domain":"probability theory","id":"claim_552a37e8c2db00e64e19c33daecfd83141c70b7123807b90679c9f85575e475e","kind":"theorem","schema_version":1,"statement":"[Proposition prop:tree of arXiv:2604.17253, 'Large Deviations for the Nonlinear Schrödinger Equation with Randomized Quasi-Periodic Ini'] For all $k\geq1$, we have
\[
{c}_k(t,\boldsymbol{n})
=
\sum_{\gamma^{(k)}\in\Gamma^{(k)}}
\sum_{\substack{\spadesuit^{(k)}\in{\mathrm D}^{(k,\gamma^{(k)})}\\
\lambda(\spadesuit^{(k)})=\boldsymbol{n}}}
\mathfrak C^{(k,\gamma^{(k)})}(\spadesuit^{(k)})
\mathfrak I^{(k,\gamma^{(k)})}(t,\spadesuit^{(k)})
\mathfrak F^{(k,\gamma^{(k)})}(\spadesuit^{(k)}),
\]
where for $0\in\Gamma^{(k)}$,
\begin{align*}
\mathfrak C^{(k,0)}(\spadesuit^{(k)})
&={c}(\lambda(\spadesuit^{(k)}))g_{\lambda(\spadesuit^{(k)})},\\
\mathfrak I^{(k,0)}(t,\spadesuit^{(k)})
&=e^{-\mathrm{i} Q(\lambda(\spadesuit^{(k)})) t},\\
\mathfrak F^{(k,0)}(\spadesuit^{(k)})
&=1;
\end{align*}
for $1\in\Gamma^{(1)}$,
\begin{align*}
\mathfrak C^{(1,1)}(\spadesuit^{(1)})
&=\prod_{j=1}^3\{{c}(\boldsymbol{n}^j)g_{\boldsymbol{n}^j}\}^{\ast^{[j-1]}},\\
\mathfrak I^{(1,1)}(t,\spadesuit^{(1)})
&=\int_0^t e^{-\mathrm{i} Q(\lambda(\spadesuit^{(1)}))(t-s)}
\prod_{j=1}^{3}
\left\{e^{-\mathrm{i} Q(\boldsymbol{n}^j) s}\right\}^{\ast^{[j-1]}}
\,\mathrm{d}s,\\
\mathfrak F^{(1,1)}(\spadesuit^{(1)})
&=\mathrm{i}{\varepsilon^\alpha} ;
\end{align*}
and for $\gamma^{(k)}=(\gamma_j^{(k-1)})_{j=1}^3$,
\begin{align*}
\mathfrak C^{(k,\gamma^{(k)})}(\spadesuit^{(k)})
&=\prod_{j=1}^3
\left\{\mathfrak C^{(k-1,\gamma_j^{(k-1)})}(\spadesuit_j^{(k-1)})\right\}^{\ast^{[j-1]}},\\
\mathfrak I^{(k,\gamma^{(k)})}(t,\spadesuit^{(k)})
&=\int_0^t e^{-\mathrm{i} Q(\lambda(\spadesuit^{(k)}))(t-s)}
\prod_{j=1}^3
\left\{\mathfrak I^{(k-1,\gamma_j^{(k-1)})} (s,\spadesuit_j^{(k-1)})\right\}^{\ast^{[j-1]}}
\,\mathrm{d}s,\\
\mathfrak F^{(k,\gamma^{(k)})}(\spadesuit^{(k)})
&=\mathrm{i}{\varepsilon^\alpha} \prod_{j=1}^3
\left\{\mathfrak F^{(k-1,\gamma_j^{(k-1)})}(\spadesuit_j^{(k-1)})\right\}^{\ast^{[j-1]}}.
\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:47:22.251934+00:00","domain":"probability theory","id":"claim_552b3a9d8c775a7d97f24f87b0eb2532f4dfba8867ed6e9f7f025a6cdc714a95","kind":"concept","schema_version":1,"statement":"[Prop 69 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] The following holds if the constant $L$ entering \Cref{yy} is chosen to be sufficiently large. Let the constants $A,B,R$ satisfy
			\begin{eqnarray}

