{"assumptions":[],"created_at":"2026-10-27T21:48:02.404254+00:00","domain":"probability theory","id":"claim_55dd998a3045f36f049fc04f5acabf77b2a6da25a044a96f2392f5135f2f8add","kind":"concept","schema_version":1,"statement":"[Theorem thm:transfer of arXiv:2608.26230, 'Comments on Choiceless Chain Conditions'] {ccc}}]
