{"assumptions":[],"created_at":"2026-10-27T13:49:06.316565+00:00","domain":"probability theory","id":"claim_569f08e5ac7b399ac2450987645a63b6586ba0f9c11ca9ade31fb0f6ed3223a5","kind":"definition","schema_version":1,"statement":"[Definition def:Ito of arXiv:2601.10359, 'An Operator It\^o Formula for Volterra Gaussian Processes:\\ The Intrinsic Bracket via Cau'] A real process $Y = (Y_t)_{t\in[0,T]}$ is called a \emph{$(D,\delta,\Pi)$-It\^o process} if:
\begin{enumerate}[label=(\arabic*)]
\item $t\mapsto Y_t$ is $L^2(\Omega)$-continuous and $Y_t\in\Dom(D)$ for each $t\in[0,T]$.
\item There exists $a\in L^2([0,T]\times\Omega)$ (the \emph{drift}) such that for all $t\in[0,T]$,
\begin{equation}
Y_t = Y_0 + \int_0^t a_s\,ds + \delta(\Pi DY\cdot\mathbf{1}_{[0,t]}),
\end{equation}
where the equality holds in $L^2(\Omega)$.
\item The map $t\mapsto \Pi DY_t$ lies in $L^2([0,T]\times\Omega;\mathcal{H})$.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:43:18.914698+00:00","domain":"probability theory","id":"claim_56a42c4a9c947956511a841253814ce426c35d70f3f6915dddea2444e0f8b431","kind":"concept","schema_version":1,"statement":"[Prop triple hodge formulas 2 of arXiv:2609.02409, 'Membranes and Maps'] Suppose that $\epsilon_1+\epsilon_2+\epsilon_3=0$. Then the following identities hold.
    \begin{enumerate}[label=\textup{(\roman*)}]
        \item \emph{One marking:}
        \begin{equation}

            \mathsf{H}\bigl(z;\epsvec{[3]};\mathrm{i} u\bigr)
            =
            -
            \frac{1}{u^2 z}
            \prod_{i=1}^3 \frac{\gamfct{-z\epsilon_i}{u}}{\epsilon_i} \,.
        \end{equation}

        \item \emph{Two markings:}
        \begin{align}
            \mathsf{H}\bigl(z,\epsilon_1^{-1};\epsvec{[3]};\mathrm{i} u\bigr)
            &=
            -\frac{z}{u^2(\epsilon_1 z + 1)}
            \frac{
                \cS(u\epsilon_2z)\cS(u\epsilon_3z)
            }{
                \cS\bigl(u(\epsilon_1z+1)\bigr)
            }
            \prod_{i=1}^3 \frac{\gamfct{-z\epsilon_i}{u}}{\epsilon_i} \,,

            \\
            \mathsf{H}^{\mathrm{st}}\bigl(z,-z;\epsvec{[3]};\mathrm{i} u\bigr)
            &=
            -\frac{1}{\epsilon_1\epsilon_2\epsilon_3}
            \Psi\left(
                \frac{z^2}{u^2\cS(u)^2}
                \sum_{i=1}^3
                \epsilon_i\cS(2u\epsilon_i z)
            \right) \,.

        \end{align}

        \item \emph{Three markings:}
        \begin{align}
            \mathsf{H}\bigl(z,\epsvec[-1]{[2]};\epsvec{[3]};\mathrm{i} u\bigr)
            &=
            -\frac{z}{u^2\epsilon_1\epsilon_2}
            \cS(u\epsilon_3z)^2
            \prod_{i=1}^3 \frac{\gamfct{-z\epsilon_i}{u}}{\epsilon_i} \,,

            \\
            \mathsf{H}\bigl(z,-z,\epsilon_1^{-1};\epsvec{[3]};\mathrm{i} u\bigr)
            &=
            \frac{z^2}{u^2\epsilon_1^2\epsilon_2\epsilon_3}
            \frac{\cS(u\epsilon_2z)\cS(u\epsilon_3z)}
            {\cS(u\epsilon_1z)\cS(u)} \,.

        \end{align}

        \item \emph{Four markings:}
        \begin{align}
            \mathsf{H}\bigl(z,\epsvec[-1]{[3]};\epsvec{[3]};\mathrm{i} u\bigr)
            &=
            -\frac{z^2}{u\epsilon_1 \epsilon_2 \epsilon_3}
            \cS(u)
            \left(
                \kappa(u)
                +
                \sum_{i=1}^3 \kappa(u\epsilon_i z)
            \right)
            \prod_{i=1}^3
                \cS(u\epsilon_i z)
                \frac{\gamfct{-z\epsilon_i}{u}}{\epsilon_i} \,,

            \\
            \mathsf{H}\bigl(z,-z,\epsvec[-1]{[2]};\epsvec{[3]};\mathrm{i} u\bigr)
            &=
            -\frac{z^2}{u^2\epsilon_1^3\epsilon_2^3}
            \frac{\cS(u\epsilon_3z)^3}{\cS(u\epsilon_1z)\cS(u\epsilon_2z)} \,.

        \end{align}

        \item \emph{Five markings:}
        \begin{equation}

                \mathsf{H}\bigl(z,-z,\epsvec[-1]{[3]};\epsvec{[3]};\mathrm{i} u\bigr)
                =
                \frac{z^4}{\epsilon_1^2\epsilon_2^2\epsilon_3^2}
                \cS(u)
                \prod_{i=1}^3\cS(u\epsilon_i z)
                \left[
                    \left(
                        \sum_{i=1}^3
                        \kappa(u\epsilon_i z)
                    \right)^2
                    - \frac{1}{4}
                \right] \,.
        \end{equation}
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

