{"assumptions":[],"created_at":"2026-10-27T07:12:19.506179+00:00","domain":"probability theory","id":"claim_5745f0fb15e53e4f3552dfc9dc8a6e3c187db9d8178c31d033d3d3113a79ace5","kind":"lemma","schema_version":1,"statement":"[Lemma 41 of arXiv:2608.18075, '2608.18075'] Let $b>2$, $I=[s_0,s_1]$, and
\begin{align*}
 w\in L^p(I;H^b),\qquad 2<p\le\infty,\qquad
 \kappa_p=1-\frac2p,
\end{align*}
where $\kappa_\infty=1$. Let $U_w(t,s)$ be the evolution family
of
\begin{align*}
 \partial_tz=\nu\Delta z+\cS(w_t,z).
\end{align*}
Then:
\begin{enumerate}[label=\textup{(\roman*)}]
\item $U_w(t,s)$ is bounded on $H^q$, $-1\le q\le b$.
On $\{\|w\|_{L^pH^b}\le M\}$ the bound is uniform for
$s_0\le s\le t\le s_1$.
\item If $0<\delta<\kappa_p$, then
\begin{align*}
 U_w(t,s):H^q\longrightarrow H^{q+\delta},
 \qquad -1\le q\le b,
\end{align*}
with norm locally uniform when $t-s$ is bounded away from zero. For
$q=b$, this endpoint estimate into $H^{b+\delta}$ does not require
the coefficient to belong to that stronger space.
\item If $-1\le q<r\le b$, then, for every $\varepsilon>0$,
\begin{align*}
 \sup_{\substack{s_0\le s<t\le s_1\\t-s\ge\varepsilon}}
 \|U_w(t,s)\|_{H^q\to H^r}
 \le C(\nu,b,p,q,r,I,M,\varepsilon).
\end{align*}
In particular, over a time gap bounded below,
\begin{align*}
 U_w(t,s):H^{-1}\to H^\delta,\qquad
 U_w(t,s):H\to H^b
\end{align*}
for every $0<\delta<b$.
\item The exact energy smoothing estimates
\begin{align*}
 \|U_w(t,s)\|_{H\to H^1}
 +\|U_w(t,s)\|_{H^{-1}\to H}
 \le C_{I,M}(t-s)^{-1/2}
\end{align*}
hold for $s<t$. The second map is the transposition extension. The same
conclusions hold for the backward adjoint evolution.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:32:20.673954+00:00","domain":"probability theory","id":"claim_57468ffa711aadd19910db981201969bde3aad727dc6eacfc6eb7ce9e96953fa","kind":"lemma","schema_version":1,"statement":"[Lemma 15 of arXiv:2609.00245, 'Higher-order Gaussian bounds for maximally subelliptic boundary value problems'] \(\forall G\in \LtSpace*[\Cuben{1}][\C^M]\), \(\forall (\xi,\delta)\in \SSetOne\),
