{"assumptions":[],"created_at":"2026-10-27T22:34:45.585211+00:00","domain":"probability theory","id":"claim_5848a50cfa2f9e695b7cf7672fcdb66b6db37712a31d983483d7d82e2f173a18","kind":"definition","schema_version":1,"statement":"[Definition def:AGG-3.1 of arXiv:2609.01776, 'On the Cuspidal Cohomology of Iwahori Congruence Subgroups of $\mathrm{SL}(3, \mathbb{Z})$'] For any subgroup $\Gamma$ in $\mathrm{SL}(n, \mathbb{Z})$, we define $W(\Gamma)$ to be the vector space of functions $f \colon \mathrm{SL}(n, \mathbb{Z}) \to \mathbb{C}$ with compact support modulo $\Gamma$ that satisfy:
    \begin{enumerate}
        \item $f(m \gamma) = f(m)$ for all $\gamma \in \Gamma$;
        \item $f(\sigma_1 m) = -f(m)$;
        \item $f(\sigma_2 m) = (-1)^{n + 1} f(m)$;
        \item $f(m) + f(hm) + f(h^2 m) = 0$;
    \end{enumerate}
    for all $m \in \mathrm{SL}(n, \mathbb{Z})$.","status":"unverified"}

