{"assumptions":[],"created_at":"2026-10-28T00:59:45.429794+00:00","domain":"probability theory","id":"claim_58c16c76659813632a543dcc7358bdad29f3b7c648c8858fb4b4d57563151310","kind":"definition","schema_version":1,"statement":"[Defi app_def_utilityFunc of arXiv:2411.16464, 'Generating social networks with static and dynamic utility-maximization approaches'] For a given $I \in \mathbb{N}^*$, a utility function $U(\alpha, C)$ is an element of $\mathcal{U}_I$, the set of applications $U : \mathcal{R}^{I-1} \times (\mathbb{R}^{*}_{+})^{I-1} \longrightarrow \mathbb{R}$ with $[0 ,1) \subseteq \mathcal{R} \subseteq \mathbb{R}$, and $\mathcal{R}^{I-1}$ convex. Every element $U : (\alpha, C) \longmapsto \mathbb{R}$ of $\mathcal{U}_I$ verifies:
\begin{enumerate}
\item $\forall C \in (\mathbb{R}^{*}_{+})^{I-1}, U(0 , C) = 0 $, and $\frac{\partial U}{\partial \alpha_i}(0 ) > 0 $
\item with $H$ bijective and increasing in its second component,\begin{equation*} \exists \begin{cases}H : \mathbb{R}^{*}_{+} \times \mathcal{R} \longrightarrow \mathbb{R}, \quad H \in \mathscr{C}^1\\ S : \mathcal{R}^{I-1} \longrightarrow \mathbb{R}, \quad S \in \mathscr{C}^1\end{cases} \quad \text{s.t. }\forall i, \frac{\partial U}{\partial \alpha_i} = H(c_i, \alpha_i) + S(\alpha)
\end{equation*}

\item \begin{equation*} \exists \begin{cases}h : \mathbb{R}^{*}_{+} \times \mathcal{R} \longrightarrow \mathbb{R}, \quad h \in \mathscr{C}^0 \\ s : \mathcal{R}^{I-1} \longrightarrow \mathbb{R}, \quad s \in \mathscr{C}^0 \end{cases} \text{ s.t. } \forall j \neq k, \quad \frac{\partial^2 U}{\partial \alpha_j \alpha_k} = s(\alpha), \quad \frac{\partial^2 U}{\partial \alpha_j^2} = h(c_j, \alpha_j) + s(\alpha)\end{equation*}
with $\begin{cases}S(\alpha) = 0  \vee s(\alpha) = 0  \Leftrightarrow \alpha = 0  \\ S(\alpha) = 0  \vee s(\alpha) = 0  \Rightarrow \forall j \leq I-1, h(c_j, \alpha_j) = 0  \wedge H(c_j, \alpha_j) = 0 \\
\forall \mathcal{A} \in \mathcal{R}^{I-1}, \exists \bar s \in \mathbb{R}, \forall a \in \mathscr{S}(\mathcal{A}), S(a) = \bar s \\
\forall \alpha, \forall i, h(\alpha_i, c_i) \leq 0 , s(\alpha) \leq 0 , S(\alpha) \leq 0 \end{cases}$ 
\end{enumerate}","status":"unverified"}

