{"assumptions":[],"created_at":"2026-10-27T10:52:57.717283+00:00","domain":"probability theory","id":"claim_59c45287647bb8ef39fb995dd6773a9ec99b820a21cd42da77c849185fb798d3","kind":"theorem","schema_version":1,"statement":"[Proposition 19 (Deterministic bias, mixed-damping regime) of arXiv:2609.02728, 'Momentum in large-batch training: Polyak enlarges the critical batch size, Nesterov improv'] Under Assumptions~\ref{ass:diagonal-covariance} and~\ref{ass:power-law}, for the mixed-damping regime \(\eta\gtrsim(1-\rho)^2\), the deterministic bias decomposes into $\cS_{\polyak}(k) = \cS_{\mathrm{over}}(k) + \cS_{\mathrm{under}}(k)$, where the overdamped tail satisfies the two-sided bounds:
\begin{equation*}
    \cS_{\mathrm{over}}(k)
    \eqsim
    \begin{cases}
    \left(\frac{(1-\rho)^2}{\eta}\right)^s, &\qquad k\lesssim\frac{1}{1-\rho},\\
    \left(\frac{1-\rho}{\eta k}\right)^s, &\qquad k\gtrsim\frac{1}{1-\rho},
    \end{cases}
\end{equation*}
and $\cS_{\mathrm{under}}(k)$ represents the underdamped transient whose properties are formally established in Lemma~\ref{lem:pol_underdamped_transient_properties}.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:32:18.848756+00:00","domain":"probability theory","id":"claim_59c46136655ed46d47442d4c2a4f6c0b671af36dbd97a3c050ec1d2d6188c3ef","kind":"theorem","schema_version":1,"statement":"[Prop 9 (Maximum principle with two boundaries for \eqref{moving frame-u}) of arXiv:2609.03869, '\bf Sharp asymptotics for a transport model with a nonlocal condition of the Fisher-KPP ty'] For any fixed $t_*>0$ large and for any  continuous and nondecreasing  functions $X^\pm(s)$ defined for $s\ge t_*$ such that $X^-(s)<X^+(s-i_\dagger)$ for all $s\ge t_*$, let $u(t,i,x)$ be a  bounded and continuous  function defined for $t\ge i+t_*$, $i\in[0,i_\dagger)$ and  $X^-(t)-R\le x\le X^+(t)+R$,  such that
	\begin{equation}

		\begin{aligned}
			\left\{\begin{split}
				&	\partial_t u(t,i,x)  + \partial_i u(t,i,x) \le 0,~~~~~~~~~~~~~~~~~~~~~t\ge i+t_*, ~i\in(0,i_\dagger), ~X^-(t)\le x\le X^+(t-i), \\
				&	u(t,0,x)\le \S_0 \int_0^{i_\dagger} \omega(i) e^{-\alpha_*c_* i} \K_* *u(t,i,x)\md i,  ~~~~~~~~~~~~~~~~t\ge i_\dagger+t_*,   ~X^-(t)\le x\le X^+(t).
			\end{split}\right.		
		\end{aligned}
	\end{equation}
	Assume further that $u(t,0,x)\le0$ for $t\in [ t_*,i_\dagger+t_*]$ and $x\in[X^-(t), X^+(t)]$ and that  $u(t,i,x)\le 0$ for $t\ge i+t_*$, $i\in[0,i_\dagger)$ and $x\in[X^-(t)-R,X^-(t)]\cup[X^+(t-i),X^+(t)+R]$,  then $u(t,i,x)\le 0$  for $t\ge i+i_\dagger+t_*$, $i\in[0,i_\dagger)$ and $x\in[X^-(t), X^+(t-i)]$.","status":"unverified"}

