{"assumptions":[],"created_at":"2026-10-27T16:15:54.984415+00:00","domain":"probability theory","id":"claim_59c726ecf5adbbd753f5682b55476ab41b6df4d5a6fa9d3f5e097b2d2c9a23e1","kind":"definition","schema_version":1,"statement":"[Definition def:frame-conditions of arXiv:2608.29708, 'Intuitionistic and Constructive Modal Logics for Classical Modal Logicians'] {bozic_models_1984}}] 
  Let $\mathfrak{F} = (W, \leq, \sqsubset)$ be an f-frame.
  \begin{itemize}
    \item $\mathfrak{F}$ is said to be a \emph{$\Box$-p}\footnote{
            Also known by downward confluence [balbiani_constructive_2021], and forth-down confluence [aguilera_gocalculus_2022].
          } frame
          if $(\leq \cdot \sqsubset) \subseteq (\sqsubset \cdot \leq)$, that is, $\forall x,x',y'\, (x \leq x' \sqsubset y' \mathrel{\Rightarrow} \exists y\,(x \sqsubset y \leq y'))$.
          Let us denote by $\FrameClass{\Box\text{-p}}$ the class of all $\Box$-p frames.
    \item $\mathfrak{F}$ is said to be a \emph{$\Diamond$-p}\footnote{
            Also known by forward confluence [balbiani_constructive_2021], F1 [simpson_proof_1994], forth-up confluence [aguilera_gocalculus_2022], and $\textsf{C}_{\Diamond}$-strong [groot_semantical_2025].
          } frame
          if $(\leq^{-1} \cdot \sqsubset) \subseteq (\sqsubset \cdot \leq^{-1})$, that is, $\forall x,x',y\, (x' \geq x \sqsubset y \mathrel{\Rightarrow} \exists y'\,(x' \sqsubset y' \geq y))$.
          Let us denote by $\FrameClass{\Diamond\text{-p}}$ the class of all $\Diamond$-p frames.
  \end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:02:11.343123+00:00","domain":"probability theory","id":"claim_59c7a1556f07fc08a6ee26711e34476301be70509450ddff22b5f72867ac0098","kind":"definition","schema_version":1,"statement":"[Defn def-boltzmann-right of arXiv:2510.26123, 'Directed distances in bipolar-oriented triangulations:\\ exact exponents and scaling limit'] \leavevmode\par

\begin{itemize}
\item
The \textbf{Boltzmann distribution} on bipolar-oriented triangulations \textbf{with right boundary length} $r\in\mathbbm N$ is the law of the random bipolar-oriented triangulations $M(r)$ such that for each bipolar-oriented triangulation $\mathfrak m$ with $r$ right boundary edges and $n\in\mathbbm N$ total edges, 
\begin{equation}  
\mathbbm P\mathopen{}\mathclose\bgroup\originalleft[ M(r) = \mathfrak m \aftergroup\egroup\originalright] = \frac{3^{-n}}{C_r},  
\end{equation} 
where $C_r > 0$ is a normalizing constant.
\item 
The \textbf{Boltzmann distribution} on bipolar-oriented triangulations \textbf{with right boundary length} $r$ \textbf{and a marked left boundary vertex} is the law of the random pair $(M(r) , z(r))$, where $M(r)$ is a bipolar-oriented triangulation with $r$ right boundary edges and $z(r)$ is a vertex on its left boundary, such that the following is true. For each bipolar-oriented triangulation $\mathfrak m$ with $r$ right boundary edges and $n\in\mathbbm N$ total edges, and each vertex $\mathfrak z$ on its left boundary, 
\begin{equation}  
\mathbbm P\mathopen{}\mathclose\bgroup\originalleft[ (M(r) , z(r))  = (\mathfrak m , \mathfrak z) \aftergroup\egroup\originalright] = \frac{3^{-n}}{\widetilde C_r}, 
\end{equation}  
where $\widetilde C_r > 0$ is a normalizing constant. 
\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:48:02.410294+00:00","domain":"probability theory","id":"claim_59c7f47525d99f81617981de6bad8f5b8b338c7db5cc588890800e401ddc2034","kind":"lemma","schema_version":1,"statement":"[Lemma lma:eigenvalues of arXiv:2608.26564, 'Real ideal points, Conway spheres, and left-orderable Dehn fillings'] There exist real analytic functions $m_+(t), m_-(t)$ near $t = 0$ such that, for $t \neq 0$, they are the two eigenvalues of $\rho_t(\mu)$, and 
\begin{equation*}
	m_+(t) = 1 + \sqrt{Q}t + O(t^2) \ \ \ \ \ m_-(t) = 1 - \sqrt{Q}t + O(t^2)
\end{equation*}
Moreover, define 
\begin{equation*}
	l_+(t) = \frac{I_{\mu\lambda}(t) - m_-(t)I_\lambda(t)}{m_+(t) - m_-(t)} \ \ \ \ \ l_-(t) = \frac{m_+(t)I_\lambda(t) - I_{\mu\lambda}(t)}{m_+(t) - m_-(t)}
\end{equation*}
Then $l_+$ and $l_-$ are meromorphic functions at $t = 0$. For $t \neq 0$, $l_{\pm}(t)$ are the eigenvalues of $\rho_t(\lambda)$ on the $m_{\pm}(t)$-eigenlines of $\rho_t(\mu)$. In particular, we have $l_+(t) + l_-(t) = I_\lambda(t)$ and $l_+(t)l_-(t) = 1$.","status":"unverified"}

