{"assumptions":[],"created_at":"2026-10-26T19:16:49.556809+00:00","domain":"probability theory","id":"claim_5a5c5911a952ae8e79d60d167ae1b34e45a762a471d3959c227caa6f15985cc6","kind":"concept","schema_version":1,"statement":"[Cor 2 ({Gradient flow: Cor.~\ref{c:GF},~\ref{c:MM}}) of arXiv:2509.06869, 'Infinite Interacting Brownian Motions and EVI Gradient Flows'] Let $\mu=\sine_2$ or $\mu=\Airy_2$.    The following hold: 
\begin{enumerate}[{\rm (a)}]

\item  $(${\bf  curves of maximal slope}$)$ The dual semigroup~$\bigl(\mathcal T_t^{\U, \QP}\nu_0\bigr)_{t \ge 0}$ is the unique solution to the $\mssW_{2, \mssd_{\U}}$-gradient flow of $\Ent_{\QP}$ starting at $\nu_0$ in the sense of {\it  curves of maximal slope}. 
Namely, for every $\nu_0 \in \mcP_e(\U)$, the curve $[0, \infty) \ni t \mapsto \nu_t=\mathcal T_t^{\U, \QP} \nu_0$ satisfies the energy equality:
\begin{align} 
\frac{\diff}{\diff t} \Ent_\QP({\nu_t}) = -|\dot\nu_t|^2 = -|{\sf D}_{\mssW_{2, \mssd_{\U}}}^- \Ent_\QP|^2(\nu_t) \quad\text{a.e.~$t>0$} \comma
\end{align}
where $|{\sf D}_{\mssW_{2, \mssd_{\U}}}^- \mcH_\QP|(\nu) := \limsup_{\sigma \to \nu} \frac{(\mcH_\QP(\sigma)-\mcH_\QP(\nu))^-}{\mssW_{2, \mssd_\U}(\sigma, \nu)}$ and $|\dot\nu_t| :=\lim_{s \to t} \frac{\mssW_{2, \mssd_\U}(\nu_s, \nu_t)}{|s-t|}$. 

\item  $(${\bf  minimising movement (JKO) scheme}$)$  The time-marginal $t \mapsto \mathcal T_t^{\U, \QP}\nu_0$ is the unique element of the minimising movement (a.k.a JKO scheme) $\MM(\mcP_{[\nu_0]}(\U), \mssW_{2, \mssd_\U}, \Ent_\QP)$ for every $\nu_0 \in \dom{\Ent_\QP}$ (see Dfn.~\ref{d:MMS} for the precise definition of $\MM$). 
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:31:14.335787+00:00","domain":"probability theory","id":"claim_5a5dcebf0bc2c82ef10092e83f8d3a435a7cb83a20419569da05027dc5746aba","kind":"lemma","schema_version":1,"statement":"[Lemma distinct_indices_inner_factor_bound of arXiv:2606.17425, 'Order statistics for edge eigenvectors of Wigner matrices'] Consider an inner factor $\mathrm{IF}(k, s, \mathcal{I}, \mathcal{J})$ on the form (equation inner_fac_def of the paper). Recall the notation $q_i$ and $q_j$ for $q_{i(\mathcal{J}(s))}$ and $q_{j(\mathcal{J}(s))}$. If $n_1(k,s) \geq 2$ we shall wlog assume that $u_1 = q_i$ and $v_2 = q_j$. Assume that all indices in $\mathcal{I}$ take on pairwise distinct values. Then we have for sufficiently small $\epsilon > 0$ and $N \geq N_0(\epsilon)$ that with probability $\geq 1 - N^{-D}$ for any large $D$, 
	\begin{equation}
		\begin{split}
		& \abs{\mathrm{IF}(k, s, \mathcal{I}, \mathcal{J})} \leq N^{1/3 + 2 \epsilon} B_1 B_2, \\
		& \text{where } B_1 := \begin{cases}
			\Psi & \text{if } d(k, s) = 0, n_1(k, s) = 1, \\
			\Psi(\Psi + \abs{\inner{q_i, v_1}} + \abs{\inner{u_2, q_j}}) & \text{if } d(k, s) = 0, n_1(k, s) \geq 2, \\
			\Psi^{d(k, s)} (\Psi + \abs{\inner{q_i, v_1}}) (\Psi + \abs{\inner{u_2, q_j}}) & \text{if } d(k, s) > 0, n_1(k, s) \geq 2, \\
		\end{cases} \\
		& \text{and } B_2 := \Psi^{\sum_{l=1}^{n_2(k, s)} \max\{1, \hat{d}(k, s, l)\}}.
		\end{split}

	\end{equation}
	 When the indices in $\mathcal{I}$ are allowed to take on the same values, we instead have for any $\epsilon > 0$ and $N \geq N_0 (\epsilon)$ that with probability $\geq 1 - N^{-D}$ for any large $D$, 
	\begin{equation}
		\begin{split}
		& \abs{\mathrm{IF}(k, s, \mathcal{I}, \mathcal{J})} \leq N^{1/3 + 2 \epsilon} B_1 B_2, \\
		& \text{where } B_1 := \begin{cases}
			\Psi & \text{if } n_1(k, s) = 1, \\
			\Psi(\Psi + \abs{\inner{q_i, v_1}} + \abs{\inner{u_2, q_j}}) & \text{if } n_1(k, s) \geq 2, \\
		\end{cases} \\
		& \text{and } B_2 := \Psi^{n_2(k, s)}.
		\end{split}

	\end{equation}","status":"unverified"}

