{"assumptions":[],"created_at":"2026-10-26T20:59:53.169619+00:00","domain":"probability theory","id":"claim_5a689350741d54f1e1d9b265beb7a9f3d73ddf5c25b0d4de31e8e62f219f2377","kind":"definition","schema_version":1,"statement":"[Definition 29 (Mild Solutions Framework) of arXiv:2607.03318, 'Continuous Differentiability of the Value Function for Infinite-Dimensional Finite-Horizon'] \begin{enumerate}[label={(\textit{\roman*})}, leftmargin=*]
\item[]
 \item \emph{Mild Sub-solution:} A mapping $Z \in \mathcal{B}_m([0, T] \times H)$ is a \emph{mild sub-solution} to the parabolic variational inequality if it satisfies $Z(t, x) \le \Phi(t, x)$ on $[0, T) \times H$, $Z(T, x) \le \Psi(x)$ on $H$, and the dynamic sub-harmonicity condition for all $0 \le t \le s \le T$ and $x \in H$:
 \begin{equation} 

        Z(t, x) \le P_{t,s} [Z(s, \cdot)](x) + \int_t^s P_{t,r} [f(r, \cdot)](x) \, \mathrm{d}r.
    \end{equation}
 \item \emph{Exact Mild Solution:} A mapping $V \in \mathcal{B}_m([0, T] \times H)$ is the \emph{exact mild solution} to the variational inequality if it is a mild sub-solution and $Z(t, x) \le V(t, x)$ holds on $[0, T] \times H$ for any other mild sub-solution $Z$.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:37:51.460291+00:00","domain":"probability theory","id":"claim_5a69b38e94caf4de4ff036bcc2a63349a34c560190bd82e55c190cea329d0290","kind":"theorem","schema_version":1,"statement":"[Prop 49 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] Let $(k_j)_{j \in \mathbb{Z} } \subset \mathbb{Z}$ be such $k_j - k_{j-1} >0$, for any $j \in \mathbb{Z}$. Moreover, for any $j \in \mathbb{Z}$ let $F_j: [0, T] \times \Omega \mapsto \mathbb{R}$ be such that, for every $s \in [0, \; T]$, $\supp \big( F_j(s, \cdot) \; \big) \subset \{k_{j-1}+1, \ldots ,  k_j\}$, and $\mathbb{E}_{\nu_{\rho}} \big[ F_j(s, \eta) \big]=0$. Therefore, there exists some universal constant $\kappa$ such that
	\begin{align*}
		\forall t \in [0, T], \quad \mathbb{E}_{\nu_{\rho}} \Bigg[ \sup_{s \in [0,t] } \Bigg(  \int_{0}^s \sum_{j} F_j(r, \; \eta_r^n) \; \dd r \Bigg)^2  \Bigg] \leq  \kappa \int_0^{t}  \sum_{j}   \frac{(k_j - k_{j-1})^{\gamma}}{\Theta(n)} \mathbb{E}_{\nu_{\rho}} \big[ \big\{ F_j(s, \eta) \}^{2} \big] \dd s.
	\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:20:55.704352+00:00","domain":"probability theory","id":"claim_5a69d53eca3860ea4ce7a1e308eae20053811670f2e20296dacaa29b5ac6f889","kind":"concept","schema_version":1,"statement":"[Proposition PROP:error1 of arXiv:2411.07840, 'Central limit theorem for the focusing $Φ^4$-measure in the infinite volume limit'] Let $F$ be a bounded and continuous function. Then, there exist constants $c>0$ such that 
