{"assumptions":[],"created_at":"2026-10-26T20:28:53.744299+00:00","domain":"probability theory","id":"claim_5a6bc9dd629b1385cf26ba6b767ef65f8ed0dde2af70869561073388ff3b8856","kind":"lemma","schema_version":1,"statement":"[Lemma 12 of arXiv:2605.13727, 'Stochastic evolution equations\\ driven by arbitrary cylindrical Lévy processes'] Let $L$ be a cylindrical L\'evy process in $U$, and let $\Psi$ be a predictable, $L_2(U,H)$-valued process that is integrable with respect to $L$. Then the integral process $(Y(t):\, t\in [0,T])$, defined by $Y(t):=\int_{(0,t]} \Psi\,{\rm d}L$, satisfies the following properties: 
	\begin{enumerate}
        \item [{\rm (a)}] Let $V$  be a separable Hilbert space  and $B \in L(H,V)$. Then, for all $0\leq p<q\leq T$ and $S \in \mathcal{F}_{p}$, we have that $\mathbb{1}_S B\Psi$ is $L$-integrable and
        	\begin{equation}
        		\mathbb{1}_{S}B \left(\int_{(p,q]} \Psi(s)\,{\rm d}L(s)\right)=\int_{(p,q]} \mathbb{1}_S B\Psi(s)\,{\rm d}L(s).
        \end{equation}
		\item [{\rm (b)}] Let $\Phi:\Omega\times[0,T]\rightarrow H$ be a uniformly bounded, adapted, càglàd process. Then, for each fixed $t>0$,  it follows that $\langle \Psi^\dagger \Phi, \cdot \rangle$ is $L$-integrable and
		\[\int_{(0,t]} \langle\Phi(s),\cdot\rangle \, {\rm d}Y(s)=\int_{(0,t]} \big\langle \Psi^\dagger(s)\Phi(s),\cdot\big\rangle \, {\rm d}L(s).\]
		\item [{\rm (c)}] For every stopping time $\tau$, we have that $\1_{(0,\tau]}\Psi$ is $L$-integrable and
		\[Y(\tau \wedge T)=\int_{(0,T]} \1_{(0,\tau]}(s)\Psi(s)\,{\rm d}L(s).\]
	\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:57:44.954788+00:00","domain":"probability theory","id":"claim_5a6c70c3726ee59c1ea53f58b208e4fa5324184fd683b24f5fb1c4964aa46b41","kind":"concept","schema_version":1,"statement":"[Proposition 14 of arXiv:2606.25494, 'A functional central limit theorem for kernel gradient flow and infinitesimal gradient boo'] For all measurable bounded $F:[0,1]^p\to \mathbb{R}$, the splitting scheme distribution $Q_{n,F}$ is absolutely continuous with respect to $Q_0 $ with Radon-Nikodym derivative
\begin{equation}
\frac{\rmd Q_{n,F}}{\rmd Q_0}(\xi)= 
\int \prod_{v\in \mathscr{T}_{d-1}}  \frac{\exp(\beta \Delta_n(j_v^1,u_v^1; A_v^\xi))}{K^{-1}\sum_{k=1}^K \exp(\beta \Delta_n(j_v^{k},u_v^{k}; A_v^\xi))} Q_0(\rmd \xi_2)\cdots Q_0(\rmd \xi_K),
\end{equation}
with $\xi_k=(j_v^k,u_v^k)_{v\in\mathscr{T}_{d-1}}$, $2\leq k\leq K$, and for $k=1$, we take $\xi_1=(j_v^1,u_v^1)_{v\in\mathscr{T}_{d-1}}=\xi$.
Note that the Radon-Nikodym derivative~\eqref{eq:RN} is bounded from above by $K^{2^d-1}$.
Similarly, $\frac{\rmd Q_{\infty,F}}{\rmd Q_0}(\xi)$ is obtained by replacing $\P_n$ by $\P$ in the definition of $\Delta_n$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:27:11.401042+00:00","domain":"probability theory","id":"claim_5a6d1e06fbf6967edff7bce59e4848d25f4c3826d87957f9f45a62c05b310c76","kind":"concept","schema_version":1,"statement":"[Theorem of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Let $\mu$ be a random finite measure on $\R^d$. Suppose that $\Phi$ is a locally square-integrable invariant point process that is $\infty$-uniform with radius $\varepsilon>0$, and that $K$ is a transport kernel such that $(K_x^\ast)_{x\in\Phi}$, conditioned on $\Phi$, is a sequence of independent random finite measures distributed like $\mu$. Further, assume that
