{"assumptions":[],"created_at":"2026-10-26T19:36:44.554355+00:00","domain":"probability theory","id":"claim_5ab904e9e5833727d2802061acaa4463929e4b53e004ff5cd4873d677aa72e71","kind":"theorem","schema_version":1,"statement":"[Theorem 6 (Fundamental theorem of the infimal convolution) of arXiv:2604.02312, 'A weak transport approach to the Schrödinger--Bass bridge'] In the setting of \Cref{prop:properties_inf_conv}, assume in addition that $C_{V\Box W}$ is continuous and admits a $p$-growth bound.
    Then, the following hold for every $\mu \in \cP_p(\mathcal X)$ and $\nu\in\cP_p(\mathcal{Z})$:
    \begin{enumerate}[label = (\roman*)]
        \item  \textbf{Primal attainment.} The infimal convolution $V \Box W$ is a standard WOT problem, and the infimum is attained, that is,
        \[
            V\Box W(\mu,\nu) = \min_{\pi \in \cpl(\mu,\nu)} \int_\mathcal{X} C_{V \Box W}(x,\pi_x) \,\mu(\rmd x).
        \]

        \item  \textbf{Strong duality.} $V \Box W$ admits the dual representation
        \begin{align*}
             V \Box W(\mu,\nu)
             &=\sup_{f \in C_{b,p}(\mathcal Z)} \left\{\int_\mathcal{Z} f \, \rmd\nu + \int_\mathcal{X} (-f^{C_W})^{C_V} \,\rmd\mu \right\}.
        \end{align*}
    \end{enumerate}
    If, in addition, $W(\rho,\nu) < +\infty$ for all $\rho \in \cP_p(\mathcal Y)$, then:
    \begin{enumerate}[label = (\roman*),resume*]
        \item  \textbf{Dual attainment.} The dual problem is attained, that is,
        \begin{align*}
             V \Box W(\mu,\nu)
             &= \max_{f \in L^1(\nu)} \left\{\int_\mathcal{Z} f \, \rmd\nu + \int_\mathcal{X} (-f^{C_W})^{C_V} \, \rmd\mu\right\}.
        \end{align*}

        \item  \textbf{Complementary slackness.} Let $\rho^\circ \in \cP_p(\mathcal Y)$ and $f^\circ \in L^1(\nu)$. Then $\rho^\circ$ is optimal for
        \[
            \inf_{\rho \in \cP_p(\mathcal Y)} \bigl\{V(\mu,\rho)+W(\rho,\nu)\bigr\}
        \]
        and $f^\circ$ is optimal for the dual problem in \ref{it:thm.fundamental.3} if and only if
        \begin{equation}
            \begin{aligned}
                V(\mu,\rho^\circ) &= \int_\mathcal{Y} -(f^\circ)^{C_W} \,\rmd\rho^\circ + \int_\mathcal{X} (-(f^\circ)^{C_W})^{C_V} \, \rmd\mu, \\
                W(\rho^\circ,\nu) &= \int_\mathcal{Y} (f^\circ)^{C_W} \, \rmd\rho^\circ + \int_\mathcal{Z} f^\circ \,\rmd\nu.
            \end{aligned}
        \end{equation}
    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:34:20.704670+00:00","domain":"probability theory","id":"claim_5abaabbd7a818b35f8a782ee3e313ef31b960f1df3275b3fe95b776fc8246e40","kind":"theorem","schema_version":1,"statement":"[Corollary 31 of arXiv:2609.02193, 'State-law dynamics of McKean-Vlasov stochastic reaction-diffusion equations on $\mathbb R^'] Assume \textnormal{(A1)-(A5)}, and let $\mu_\epsilon^*$ and $\xi_\epsilon$ be given by Corollary~\ref{Cor2}. Then there exists a unique $\bar u\in H$ such that the constant trajectory $u(t)\equiv\bar u$ is a self-consistent stationary variational solution of \eqref{Eq3} with $\epsilon=0$. If $\delta_{\bar u}$ denotes the Dirac measure at $\bar u$, then, for every $\omega\in\Omega_0$,
	\begin{align}
		\mathcal A^0(\omega)
		=\big\{(\bar u,\delta_{\bar u})\big\},
		\qquad
		\xi_0(\omega)=\bar u,
		\qquad
		\mu_0^*=\delta_{\bar u}.
	\end{align}
	Moreover,
	\begin{align}
		\lim_{\epsilon\to0}
		\|\xi_\epsilon(\omega)-\bar u\|=0,
		\qquad \omega\in\Omega_0,
	\end{align}
	and, for every $\epsilon\in[0,\epsilon_0]$,
	\begin{align}
		\left(
		\mathbb E\|\xi_\epsilon-\bar u\|^2
		\right)^{1/2}
		=
		\mathcal W_2(\mu_\epsilon^*,\delta_{\bar u})
		\leq
		\epsilon
		\Big(
		\frac1{\kappa_0}
		\sum_{j=1}^{m}\|h_j\|^2
		\Big)^{1/2}.
	\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:20:15.483795+00:00","domain":"probability theory","id":"claim_5abc33b62903bdf35fb907ce2cd118ba6df92c44099e86cb9dde68fafa19e379","kind":"lemma","schema_version":1,"statement":"[Lemma 47 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Let $\eta\in (0,1)$ and $b\geq v + 2\lambda + 2\log(2)\pi$.
Then
\begin{multline*}
\int_{D^{2}}
e^{-(b-v-2\lambda)^{2}/(2\log(2)/\pi + 2 G_{D}(z,w))}
\LK_{\eta}(\vert w-z\vert)
\,d^{2}z\,d^{2}w
\\
\leq 
e^{-((2\pi\eta)\wedge 1)(b-v-2\lambda - 2\log(2)/\pi)}
(c_{\eta}\vert D\vert \diam(D)^{2\eta} +
\Vert 1_{D} \Vert_{H^{-\eta}(\C)}^{2}
),
