						\frac{x^{2}}{q}, & \text{if} \, \, 0 \leq x \leq \sqrt{q}, \\
						1, & \text{otherwise.}
					\end{array} \right.
			\end{align*}
	Here the constant $\sigma = - \frac{1}{2} \zeta(2) = - \frac{\pi^{2}}{12}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:55:27.257440+00:00","domain":"probability theory","id":"claim_5ad0d654ade258230fdccc3159e9fd2a3b6d573486ed994e8748f6e284103c20","kind":"concept","schema_version":1,"statement":"[Theorem thm:polyarm of arXiv:2410.23250, 'Strict inequalities for arm exponents in planar percolation'] There exists $c>0$ such that for all $n\geq 10$ we have

