{"assumptions":[],"created_at":"2026-10-27T23:11:09.316479+00:00","domain":"probability theory","id":"claim_5b0fc7fc690c12c054612071b21049454f467b8f86d4ce08b4c8cd7d1d7f988f","kind":"concept","schema_version":1,"statement":"[Lemma sym-path-to-fwick of arXiv:2411.06131, 'Non-Markovian dynamics: the memory-dependent probability density evolution equations'] {ducan2000stochastic}}]
