\end{align*}
and
 \begin{itemize}
\item $ \beta(C) $ only depends on the isotopy class of $ C,$ where two sets $ C,C'$ are in the same isotopy class {if there is a continuous function $ \gamma :[0,1] \times \mathbb R^d\to \mathbb R^d,t\in [0,1]$ such that $ \gamma (0,x) = x$ and $ \gamma(1,C) = C'$, and for each $ t$, $\gamma (t,\cdot )$ is a homeomorphism.}
\item  {there is $ \kappa <\infty $} such that for any Morse representation $ C = \{f\ge u\}$,
 $ | \beta(C) |  {\le \kappa N_{ f,u}} $, where $ N_{ f,u}$ is  the number of critical points of $ f$ over $ C$ above level $u$.
 \end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:48:25.219911+00:00","domain":"probability theory","id":"claim_5cb15ba41ff158a0d27932c6e6d198d420a2d64ba28f0461ebb6d1b42105e23a","kind":"concept","schema_version":1,"statement":"[Proposition prop: 147 of arXiv:2607.05848, 'Mesoscopic eigenvalue statistics for correlated random matrices'] Let $g,\epsilon_{0}$ and $\eta_{0}$ be as in Theorem (thm: 96 of the paper).
Recall the scaled test function $f$ as in (equation eq: 192 of the paper).
Define the quasi-analytic extension of $f$ by
\begin{equation}
	\tilde{f}(x+\mathrm{i}\eta) \coloneqq \chi(\eta)(f(x)+\mathrm{i}\eta f'(x)),
\end{equation}
where $\chi:\mathbb{R}\to[0,1]$ is an even $C_{\text{c}}^{\infty}(\mathbb{R})$ function supported on $[-1,1]$ with $\chi(\eta)=1$ for $|\eta|<1/2$.
Let $M(z)$ be the solution of (equation eq: 197 of the paper).
Introduce the kernel $\mathcal{K}(z,w)$ by setting, for any $z,w\in\mathbb{C}$, 
\begin{equation}
	\mathcal{K}(z,w) \coloneqq \frac{2}{\beta}\Tr_{\textnormal{op}}(\mathcal{C}_{M'M^{-1},I}(1-\mathcal{C}_{M,\widetilde{M}}\mathcal{S})^{-1}\mathcal{C}_{M,\widetilde{M}'}\mathcal{S}(1-\mathcal{C}_{M,\widetilde{M}}\mathcal{S})^{-1}),
\end{equation}
where $M\equiv M(z)$ and $\widetilde{M}\equiv M(w)$.
Then, for any fixed $\lambda\in\mathbb{R}$, we have
\begin{equation*}
	\phi'(\lambda) = - \frac{\lambda\phi(\lambda)}{\pi^{2}}
	\int_{\Omega_{0}}\int_{\Omega_{0}'}
	\frac{\partial\tilde{f}(z)}{\partial\bar{z}}\frac{\partial\tilde{f}(w)}{\partial\bar{w}}\mathcal{K}(z,w)
	\mathrm{d}^{2}w \mathrm{d}^{2}z
	+ O_{\prec}\Big( (1+|\lambda|)^{2}N^{-\epsilon_{0}/2} \Big),
\end{equation*}
where
\begin{equation}
	\Omega_{0} \coloneqq \{z\in\mathbb{C}: |\mathrm{Im}\, z|> N^{-\epsilon_{0}/100}\eta_{0}\}, \quad
	\Omega_{0}' \coloneqq \{z\in\mathbb{C}: |\mathrm{Im}\, z|> 2N^{-\epsilon_{0}/100}\eta_{0}\}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:35:57.166978+00:00","domain":"probability theory","id":"claim_5cb21e34a224f98381c1d2a77ae6f98162e3754f956c2b89a9874962e6ef8894","kind":"concept","schema_version":1,"statement":"[Theorem th:local-eq-general of arXiv:2604.08154, '\small Hydrodynamic limit of the directed exclusion process'] Let $u_0:\mathbb{R}\to [0,1]$ be a measurable function, and let $(\mu_\varepsilon)_\varepsilon$ be a sequence 
of product measures on $\mathbf{X}$ associated to the profile $u_0$, that is, 
there exists $(u^{\varepsilon,x})_{\varepsilon,x}\subset [0,1]$ satisfying
	\begin{equation}
		\mu_\varepsilon(\eta(x)\in \,\cdot\,)= \nu_{u^{\varepsilon,x}}(\eta(x)\in\,\cdot\,)\; \text{,}\;\;\qquad x \in \mathbb{Z}\; \text{,}\;\;
	\end{equation}
	\begin{equation} \int_{K}|u^{\varepsilon,\lfloor x\varepsilon^{-1}\rfloor}-u_0(x)|\,{\rm d}x\xrightarrow{\varepsilon\to 0}0\; \text{,}\;\;\qquad K\subset \mathbb{R}\ \text{compact}\ .
	\end{equation}  
	Then, letting $u(\,\cdot\,,\,\cdot\,):\mathbb{R}\times [0,+\infty)\to [0,1]$ denote the  
	entropy solution to (equation eq:HDL of the paper) with initial condition $u_0$,  
	we have,	 for all $t\ge 0$, 
	\begin{equation}	
		\lim_{\varepsilon\to 0} \tau_{\lfloor x\varepsilon^{-1} \rfloor} \tttonde{\mu_\varepsilon\ensuremath{\mathcal P}_{t\varepsilon^{-1}}}
		= \nu_{u(x,t)}\; \text{,}\;\;\qquad \text{for every continuity point $x\in \mathbb{R}$ of $u(\,\cdot\,,t)$}\; \text{.}
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:21:10.887034+00:00","domain":"probability theory","id":"claim_5cb336ce8615d165aca7244b562bccf22a9ddb1d3fd35066fedac4c7b87c57a0","kind":"concept","schema_version":1,"statement":"[Theorem 9 (Long-range order implies uniqueness) of arXiv:2504.02435, 'Poisson-Voronoi percolation in higher rank'] Let $G$ be a non-compact connected semisimple real Lie group and $(X,d_X)$ be its symmetric space. Then 
