{"assumptions":[],"created_at":"2026-10-26T19:20:33.748358+00:00","domain":"probability theory","id":"claim_5ce27d02969576841d388e5b8411bac817dd7982005eaebd13e1bbac74e0c0e0","kind":"theorem","schema_version":1,"statement":"[Cor 16 (Bounded additive statistics of geodesics) of arXiv:2607.28865, 'First-Passage Percolation on Spread-out line graphs: Microscopic Regime'] Assume that $\ell\ge2$ is fixed and that $\go$ is non-deterministic. Let $\pi_n^\star$ denote the uniquely selected minimum-hop geodesic from $0$ to $n$, and let $\cP$ be the collection of all paths $\pi$ in $(\dZ,\cE^{(\ell)})$. Consider a path statistic $\Phi:\cP \to \dR^d$ that is translation-covariant and additive under concatenation, \ie\
\[
\Phi_{\tau_z\go}(\pi+z)=\Phi_\go(\pi)
\text{ and }\
\Phi(\pi^{(1)}\circ\pi^{(2)}) = \Phi(\pi^{(1)}) + \Phi(\pi^{(2)}).
\]
Assume further that $\norm{\Phi(\pi)} \le C|\pi|$ for some deterministic constant $C<\infty$. For each regeneration block, we define 
 \[
 \Phi_i := \Phi(\pi^\star(\rho_i,\rho_{i+1}))
 \quad 1\le i\le\gk_n-1,
 \quad
 \Phi_n := \Phi(\pi_n^\star),
 \text{ and }\
 \mvmu_\Phi := \E \Phi_1.
 \]
Then the following properties hold:
\begin{enumeratei}
\item  \textbf{Expectation.} The exact expectation satisfies
\begin{equation*}
    \E \Phi_n = n \frac{\mvmu_\Phi}{\mu_{\sfP}} + O(1).
\end{equation*}

\item \textbf{Joint CLT.} In the finite variance passage-time regime (\ie\ $\E\go^2<\infty$ or Condition~\textup{A.\ref{ass:A2}} holds with $\gc>2/\lc$), 
\begin{equation*}
    n^{-1/2}
    \begin{pmatrix}
        T_n - n \mu_{\sfT}/\mu_{\sfP} \\
        H_n - n \mu_{\sfH}/\mu_{\sfP} \\
        \Phi_n - n \mvmu_\Phi/\mu_{\sfP}
    \end{pmatrix}
    \Rightarrow
    \N_{d+2}(\mvzero, \Sigma_{d+2}),
\end{equation*}
where the $(d+2)\times(d+2)$ asymptotic covariance matrix is given by
\begin{equation*}
    \Sigma_{d+2} := \frac{1}{\mu_{\sfP}} \cov\left( \begin{pmatrix} \sfT_1 \\ \sfH_1 \\ \Phi_1 \end{pmatrix} - \frac{\sfP_1}{\mu_{\sfP}} \begin{pmatrix} \mu_{\sfT} \\ \mu_{\sfH} \\ \mvmu_\Phi \end{pmatrix} \right).
\end{equation*}
Due to \textnormal{(i)}, the expectation $\E \Phi_n$ can be used for centering.

\item \textbf{Empirical ratio limits.} Let $\Psi\ge 0$ be another scalar statistic satisfying the same assumptions with $\mvmu_\Psi := \E\Psi_1 > 0$, and let $\Psi_n := \Psi(\pi_n^\star)$. For definiteness, we set the ratio equal to $0$ on the event $\{\Psi_n = 0\}$. As $n\to\infty$, the empirical ratio converges almost surely:
\begin{equation*}
    \frac{\Phi_n}{\Psi_n} \to  \frac{\mvmu_\Phi}{\mvmu_\Psi} \quad \text{a.s.}
\end{equation*}
Moreover, the ratio satisfies the central limit theorem:
\begin{equation*}
    \sqrt{\Psi_n}\left(\frac{\Phi_n}{\Psi_n} - \frac{\mvmu_\Phi}{\mvmu_\Psi}\right) 
    \Rightarrow 
    \N_d\left(\mvzero,\, \frac{1}{\mvmu_\Psi} \cov\left(\Phi_1 - \frac{\mvmu_\Phi}{\mvmu_\Psi}\Psi_1 \right)\right).
\end{equation*}

\item \textbf{Functional CLT.} Let $\mvS_m^\Phi := \sum_{i=1}^m \Phi_i$. In the Skorokhod space $D([0,\infty), \dR^d)$ equipped with the $J_1$ topology, the renewal skeleton process converges to a Brownian motion:
\begin{equation*}
    \left( \frac{1}{\sqrt{n}} \left( \mvS_{\sfN(nt)}^\Phi - nt \frac{\mvmu_\Phi}{\mu_{\sfP}} \right) \right)_{t \ge 0} 
    \Rightarrow 
    \left( B_t^\Phi \right)_{t \ge 0},
\end{equation*}
where $B^\Phi$ is a centered $\dR^d$-valued Brownian motion with covariance function $\cov(B_s^\Phi, B_t^\Phi) = \min\{s,t\} \Sigma_\Phi$ and $\Sigma_\Phi := \frac{1}{\mu_{\sfP}} \cov(\Phi_1 - \frac{\mvmu_\Phi}{\mu_{\sfP}} \sfP_1)$.
\end{enumeratei}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T16:22:59.716345+00:00","domain":"probability theory","id":"claim_5ce48c9db4e24f405e3840ff754ca4a539e270214fc28cee90a981c690b23270","kind":"concept","schema_version":1,"statement":"[Theorem thm:ik-completeness-detailed of arXiv:2608.29708, 'Intuitionistic and Constructive Modal Logics for Classical Modal Logicians'] \begin{equation*}
    \textbf{IK} = \set{ \varphi \in \mathscr{L}_{\Box\Diamond}; \forall \mathfrak{F} \in \FrameClass{\Diamond\text{-p}} \cap \mathscr{F}_{FS2}\,(\mathfrak{F} \vDash^{\text{h}} \varphi) }.
  \end{equation*}
  \begin{proof}
    ($\subseteq$) It suffices to show that $\textsf{FS2}$ is h-valid on any $\Diamond$-p and FS2 frame,
    which is already proven in Proposition (prop:ik-model-validates-cdia-and-fs2 of the paper).

    ($\supseteq$) By Proposition (prop:canonical-model-is-dia-p of the paper) and Truth lemma,
    it suffices to show that $\mathfrak{M}_{\textbf{IK}}^*$ satisfies the FS2 condition.
    Take any $x = (\Gamma_x, \Delta_x)$, $y = (\Gamma_y, \Delta_y)$, and $y' = (\Gamma_y', \Delta_y')$ such that $x \sqsubset^* y \leq^* y'$,
    then $\Box^{-1} \Gamma_x \subseteq \Gamma_y \subseteq \Gamma_y'$
    and $\Diamond^{-1} \Delta_x \subseteq \Delta_y$ by definition.
    \begin{claim*}
      $(\Gamma_x \cup \Diamond \Gamma_y', \Box \Delta_y')$ is $\textbf{IK}$-consistent.
      \begin{subproof}
        Suppose not, then there are finite $A \subseteq \Gamma_x$,
        $B \subseteq \Gamma_y'$,
        and $C \subseteq \Delta_y'$
        such that $\textbf{IK} \vdash \left(\bigwedge A \land \bigwedge \Diamond B \right) \to \bigvee \Box C$, then:
        \begin{center}
          \AxiomC{$\left(\bigwedge A \land \bigwedge \Diamond B \right) \to \bigvee \Box C$}
          \RightLabel{\scriptsize{$\textsf{M}_\Box$, $\textsf{M}_\Diamond$}}
          \UnaryInfC{$\left(\bigwedge A \land \Diamond \bigwedge B \right) \to \Box \bigvee C$}
          \UnaryInfC{$\bigwedge A \to \left(\Diamond \bigwedge B \to \Box \bigvee C \right)$}
          \RightLabel{\scriptsize{$\textsf{FS2}$}}
          \UnaryInfC{$\bigwedge A \to \Box \left(\bigwedge B \to \bigvee C \right)$}
          \DisplayProof
        \end{center}
        Then $\Box \left(\bigwedge B \to \bigvee C\right) \in \Gamma_x$ by $\textbf{IK}$-consistency,
        so $\left(\bigwedge B \to \bigvee C\right) \in \Gamma_y'$ by $\Box^{-1} \Gamma_x \subseteq \Gamma_y'$.
        Here, $\bigwedge B \in \Gamma_y'$ by $B \subseteq \Gamma_y'$,
        then $\bigvee C \in \Gamma_y'$ by the above,
        so there is at least one $\psi \in C$ such that $\psi \in \Gamma_y'$,
        which is a contradiction since $C \subseteq \Delta_y'$.
      \end{subproof}
    \end{claim*}
    Now that $(\Gamma_x \cup \Diamond \Gamma_y', \Box \Delta_y')$ is $\textbf{IK}$-consistent,
    then by Lindenbaum lemma, there is $x' = (\Gamma_x', \Delta_x') \in W_{\textbf{IK}}^*$ such that
    $\Gamma_x \cup \Diamond \Gamma_y' \subseteq \Gamma_x'$ and $\Box \Delta_y' \subseteq \Delta_x'$.
    It is clear that $x \leq^* x'$, so it remains to show that $x' \sqsubset^* y'$.
    Take any $\Box \psi \in \Gamma_x'$, then $\Box \psi \notin \Delta_x'$,
    then $\Box \psi \notin \Box \Delta_y'$, then $\psi \notin \Delta_y'$, so $\psi \in \Gamma_y'$.
    Now take any $\Diamond \varphi \in \Delta_x'$, then $\Diamond \varphi \notin \Gamma_x'$,
    then $\Diamond \varphi \notin \Diamond \Gamma_y'$, then $\varphi \notin \Gamma_y'$, so $\varphi \in \Delta_y'$.
  \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:27:11.425772+00:00","domain":"probability theory","id":"claim_5ce634f7aeff33bb6bcd24a8b4ac43f9fcb366aec92b158765cca79484501e8c","kind":"concept","schema_version":1,"statement":"[Lemma l:condition reduction lebesgue of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Suppose that $f:\R^d\to [0,\infty)$ is measurable, and define $\Psi_f$ by
    \begin{equation}
        \Psi_f(dy) := \bigg(\int f(x)\, |K^\ast|(y, dx)\bigg)\, |\Phi|(dy),\quad y\in\R^d.
    \end{equation}
    Then 
    \begin{equation}
        \BE\bigg[\bigg(\int f(x)\, |\tilde{K}_0|(dx)\bigg)^2\bigg] < \infty
    \end{equation}
    if $\Psi$ is locally absolutely square-integrable. The converse is true if $K$ and $\Phi$ are nonnegative, as then
    \begin{equation}
        \Psi_f(B_1) = \kappa_d\int f(x) \tilde{K}_0(dx).
    \end{equation}
    Moreover, the following statements hold.
    \begin{enumerate}[label=(\roman*)]
        \item If Condition~(c:condition square-integrable general with p of the paper) holds with respect to $p\in[-d, \infty)$ and a strongly log-dominating function $\rho$, then
        \begin{equation}
            \BE\bigg[\bigg(\int \sqrt{\|x\|^{d+\max(p,0)}\rho(\|x\|)+1}\, |\tilde{K}_0|(dx)\bigg)^2\bigg] < \infty.
        \end{equation}
        \item If Condition~(c:condition square-integrable Markov with p of the paper) holds with respect to $p\in[-d, \infty)$, then
        \begin{equation}
            \BE\bigg[\bigg(\int \sqrt{\|x\|^{d+\max(p,0)}+1}\, |\tilde{K}_0|(dx)\bigg)^2\bigg] < \infty.
        \end{equation}
        \item If Condition~(c:condition square-integrable stealthy of the paper) holds with respect to $\varepsilon>0$, then
        \begin{equation}
            \BE\bigg[\bigg(\int e^{\varepsilon\|x\|}\, |\tilde{K}_0|(dx)\bigg)^2\bigg] < \infty.
        \end{equation}
    \end{enumerate}
    \begin{proof}
        Let $f:\R^d\to[0,\infty)$ be measurable. By construction, we have $|\tilde{K}_0|\leq |K||L_0|= \kappa_d^{-1}|K||\I_{B_1}\cdot\Phi|$. Therefore,
        \begin{equation*}
            \int f(x) |\tilde{K}_0|(dx) \leq \kappa_d^{-1}\int_{B_1}\int f(x) |K|(y, dx)\, |\Phi|(dy) = \kappa_d^{-1} \Psi_f(B_1).
        \end{equation*}
        The inequality becomes an equality if $K$ and $\Phi$ are nonnegative. The remaining assertions follow with an appropriate choice of $f$.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:29:52.231097+00:00","domain":"probability theory","id":"claim_5ce6f2a2df4caf3e89b5fbca57d2d5517d51bbe67fc9516cbed9a9697b16acd6","kind":"theorem","schema_version":1,"statement":"[Theorem 40 (Asymptotics strictly inside the dotted pink region) of arXiv:2512.09136, 'On the Green's functions and Martin boundary structure of a planar diffusion in a disconti'] Suppose that $x^* \in (0, \M)$. Let $z_0 \in \R^2$ and $\alpha_0 \in [0,\alpha^*_+)$. Then: 
\begin{equation}
    g^{z_0}(r\cos(\alpha), r\sin(\alpha)) \underset{r\to+\infty\atop \alpha\to \alpha_0, \alpha > 0}{\sim} C^+_{*}f_{*}(z_0) e^{-r(\cos(\alpha)x^* + \sin(\alpha)Y^+(x^*))}
\end{equation}
where \begin{equation}
    f_{*}(a_0,b_0) = \begin{cases}
e^{x^*a_0 + Y^-(x^*)b_0} & \text{if } b_0 \geq 0 \\
e^{x^*a_0 + Z^+(x^*)b_0} & \text{if } b_0 < 0.
\end{cases}
\end{equation}
and 
\begin{equation}
    C^+_{*} = \frac{\gamma(x^*,Y^+(x^*),Z^+(x^*))}{\partial_y\gamma_+(x^*,Y^+(x^*))\frac{d}{dx}\gamma(x,Y^-(x), Z^+(x))\big|_{x=x^*}}.
\end{equation}
The symmetric result holds for angles $\alpha_0 \in (\alpha^*_-, 2\pi].$","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:33:23.315835+00:00","domain":"probability theory","id":"claim_5ce7911b23b95b99ee61574b4a7dc49579e78ad1fecd8473d223c763e8810f33","kind":"concept","schema_version":1,"statement":"[Theorem 4 of arXiv:2506.20411, 'Maximal Counts in the Stopped Occupancy Problem'] Let $b_n$ and $c_n$ be given by \eqref{bt}--\eqref{bc}.
