{"assumptions":[],"created_at":"2026-10-26T19:40:21.313846+00:00","domain":"probability theory","id":"claim_5d31d31a4397d3648a4a3dd3b69f749981775b4a32b8065bbc15013327442604","kind":"concept","schema_version":1,"statement":"[Corollary 3 of arXiv:2604.08623, 'Central limit theorem for the Allen-Cahn equation with supercritical random initial condit'] Under the same notations, we have for any $\eps > 0$, $t>0$ and $x,y\in \mathbb{R}^d$, the estimate
  \begin{equation}
    0\leq D_{y} u_\eps(t,x) \leq p_t * \rho_\eps (x-y).
  \end{equation}
  Consequently, for any $p\geq1$, we get the following bounds on the $p$-th moment of $Du(t,x)$ and 
  $\langle Du(t,\cdot),\phi\rangle$ where $\phi$ is any test function.
  \begin{align*}
    \mathbf{E}\left[ \|D u_\eps(t,x)\|_{\mathcal{H}}^p\right] & \leq \|p_t * \rho_\eps\|_{L^2(\mathbb{R}^d)}^p,\\ 
    \mathbf{E}\left[ \|\langle D u_\eps(t,\cdot),\phi\rangle\|_\mathcal{H}^p\right] 
    & \leq \|p_t * \rho_\eps * |\phi|\|_{L^2(\mathbb{R}^d)}^p.
  \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:51:11.966779+00:00","domain":"probability theory","id":"claim_5d33d2315737f64f1ce911d63ff5221b134d6b3e84e2f2066a795e558fa44229","kind":"theorem","schema_version":1,"statement":"[Theorem 3 (Anchored optional completion) of arXiv:2608.08756, 'Infinite-Dimensional L\'evy Area and Spectral Ancestry'] Assume that the adapted anchor \(A\) has a \(G\)-valued càdlàg modification
\(\bar A\).  For bounded stopping times \(0\le\sigma\le\tau\le T\), set
\begin{equation}
 \bar\Phi_{\sigma,\tau}
 :=\bigl(\alpha_{\tau,\sigma}(\bar A_\sigma)\bigr)^{-1}
    \star\bar A_\tau.

\end{equation}
Then:

\begin{enumerate}[label=\textup{(\roman*)},leftmargin=2.8em]
\item \(\bar\Phi_{\sigma,\tau}\) is \({\mathcal F}_\tau\)-measurable.  For each
fixed deterministic pair \((s,t)\), it agrees almost surely with
\(\Phi_{s,t}\).

\item On one event, simultaneously for all bounded stopping triples
\(\sigma\le\rho\le\tau\),
\begin{equation}
 \bar\Phi_{\sigma,\tau}
 =\alpha_{\tau,\rho}(\bar\Phi_{\sigma,\rho})
  \star\bar\Phi_{\rho,\tau}.

\end{equation}

\item If bounded stopping times
\(\sigma_n\downarrow\sigma\) and \(\tau_n\downarrow\tau\), with
\(\sigma_n\le\tau_n\), then
\begin{equation}
 \bar\Phi_{\sigma_n,\tau_n}\longrightarrow
 \bar\Phi_{\sigma,\tau}
 \qquad\text{almost surely}.

\end{equation}

\item This extension is unique among assignments \(Y_{\sigma,\tau}\) with
the following two properties: for every finite-valued stopping pair,
\(Y_{\sigma,\tau}\) is the pointwise pasting of the perfected deterministic
increments \(\bar\Phi_{s,t}\); and for the right endpoints
\(\sigma^{(n)},\tau^{(n)}\) of the nested dyadic partitions of \([0,T]\),
\(Y_{\sigma^{(n)},\tau^{(n)}}\to Y_{\sigma,\tau}\) in probability.  It is
natural under continuous transport-intertwining homomorphisms.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:21:45.238263+00:00","domain":"probability theory","id":"claim_5d360135140c98480b1c66c375974bd37b25bd5bf8ea1ec00426471e5f1a2d46","kind":"concept","schema_version":1,"statement":"[Lemma 7 of arXiv:2607.26564, 'Stochastic Scalar Conservation Laws on Moving Hypersurfaces'] (It\^{o} formula) Assume that $z$ is a solution to equation \eqref{eq61}. For any $\varrho \in [C^2(Q_T)]^m$, let $\Psi(t,x)= \int_0^t \varrho(s, G(s, G^{-1}(t,x)))dB_s$, $(t,x) \in Q_T$. Then for any $\eta \in C^1(Q_T)$ and $\phi \in C^2(\mathbb{R}^m)$ with bounded second-order partial derivatives, we have $\mathbb{P}$-a.s.
\begin{eqnarray}
& &  \langle \phi(z(t) - \Psi(t)), \eta(t) \rangle_{\Gamma_t} \nonumber\\
&=&  \langle \phi(z_0), \eta(0) \rangle_{\Gamma_0}
      + \int_0^t \langle \big( \phi(z(s) - \Psi(s))- \nabla\phi(z(s) - \Psi(s))\cdot z(s) \big)\nabla_{\Gamma_s}\cdot v(s), \eta(s) \rangle_{\Gamma_s}ds\nonumber\\
   & &+ \int_0^t \langle \phi(z(s) - \Psi(s)), \overset{\scalebox{0.4}{$\bullet$}}{\eta}(s) \rangle_{\Gamma_s}ds
      + \int_0^t \langle \nabla\phi(z(s) -\Psi(s))\cdot (\nabla_{\Gamma_s}\cdot R(s)), \eta(s) \rangle_{\Gamma_s}ds \nonumber\\


   & & + \int_0^t \langle \nabla\phi(z(s) - \Psi(s))\cdot S(s), \eta(s) \rangle_{\Gamma_s}ds
       + \int_0^t \langle \nabla\phi(z(s) - \Psi(s))\cdot \big( \Upsilon(s)- \varrho(s)\big), \eta(s)\rangle_{\Gamma_s}dB_s \nonumber\\

   & & +\frac{1}{2}\int_0^t \langle (\Upsilon(s)-\varrho(s) )^\top \nabla^2\phi(z(s) -\Psi(s))(\Upsilon(s)- \varrho(s)), \eta(s) \rangle_{\Gamma_s}ds,
\end{eqnarray}
for all $t \in [0,T]$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:49:15.474837+00:00","domain":"probability theory","id":"claim_5d3acc94a3b12cbe7974ab7cf68fe66df68c869f64abc38852d01d7cb8a972d5","kind":"definition","schema_version":1,"statement":"[Definition def:g-gl-fib-orth-spc of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] A map $f\colon X\to Y$ in $\cat{$\bm G$-$\textbf{\textup{L}}$-Top}$ is called a \emph{$G$-global fibration} if it is a $G$-global level fibration and for all $H$-representations $V,W$ such that $V$ is faithful the naturality square
    \[
        \begin{tikzcd}
            X(V)\arrow[r]\arrow[d,"f(V)"'] & X(V\oplus W)\arrow[d,"f(V\oplus W)"]\\
            Y(V)\arrow[r] & Y(V\oplus W)
        \end{tikzcd}
    \]
    is a homotopy pullback in the $\mathcal G_{H,G}$-equivariant model structure on $\cat{$\bm{(H\times G)}$-Top}$.

    A $G$-orthogonal space $X$ is called \emph{static} if $X\to1$ is a $G$-global fibration, i.e.\ if the transition map $X(V)\to X(V\oplus W)$ is a $\mathcal G_{H,G}$-weak equivalence for all $V,W$ as above.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:58:09.070614+00:00","domain":"probability theory","id":"claim_5d3ad26b11b6bff632cf4abd0028b679f8cb04c648b5a7dd40082236ec1c52c1","kind":"concept","schema_version":1,"statement":"[Theorem 4 (The lookdown probability space) of arXiv:2606.28174, 'Moment duality and propagation of exchangeability'] Set $\Delta = \{\vect{s}=(s_1,s_2,...):s_1\geq s_2\geq...\geq0,\displaystyle\sum s_l\leq1 \}$  for the infinite-dimensional simplex and $C=\{\vect{i}=(i_1,i_2)\in\mathbb{N}^2,i_1<i_2\}$ for the set of ordered pairs of integers. Denote also by $\vect{p}:=\{p_j\}_{j}$ a probability measure on $\N$ with finite expectation and probability generating function $\Phi$.
There exists a Poisson point process
\[
\Pi \subset \mathbb{R}_+ \times \Delta\times [0,1]^{\N}\times C\times\N^2,
\]
  such that one can construct the following using $\Pi$.

\begin{enumerate}
\item[i)] A family of random mappings $L_t$ that satisfy a lookdown principle for any $t$
and a $\N$-valued branching--coalescing process $\{{A}_t\}_{t}$ with transition rates 
\begin{equation}
\begin{cases} n\to n+j & \text{at rate } np_j \\n\to n-j & \text{at rate } c\binom{n}{2}\mathbb{1}_{j=1}+q_{n,n-j} \\
\end{cases}
\end{equation}
where $j\in \mathbb{N}$ and the array $\{q_{n,m}\}_{n,m}$ for $m=1,2,...,n-1$ provides the transition rates of the block-counting process of a $\Xi$-coalescent.

\item[ii)] A $[0,1]$-valued frequency process $\{W_t\}_{t}$,
   strong solution to the stochastic differential equation
        \begin{align}
           dW_t & = \sqrt{W_t(1-W_t)}dB_t + f(W_t)W_t(1-W_t)dt \notag \\ & \qquad + \int_{\Delta\times[0,1]^{\N}}  \sum_{l\ge1} s_l \left(\mathbb{1}_{\{u_l \leq W_{t^-}\}} - W_{t^-}\right) M(dt, d\vect{s}, d\vect{u}), 
        \end{align}
        where $M$ is the restriction of $\Pi$ to $\R_+\times\Delta\times[0,1]^{\N}$ and $f(x):=c(1-\Phi(x))/(1-x)$ for some constant $c>0$.  
\end{enumerate}
Moreover, the processes $\{W_t\}_{t }$ and $\{{A}_t\}_{t}$ are moment dual {and can be read as forward and backward in time processes on the same graphical construction}. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:33:43.760574+00:00","domain":"probability theory","id":"claim_5d3d18cad2101282aac96f2b98e5275600425f241e5e2c6bacf2743383938d02","kind":"definition","schema_version":1,"statement":"[Defn deft1 of arXiv:2609.02682, 'LDP for tensor forms'] With $\mathcal T_r^{(m)}[W,\phi,{\boldsymbol f}](x)$ as in (equation eq:def_T_general_m of the paper), for all ${\boldsymbol{f}}\in \mathcal{F}_c$,  $m\in[v]$ and $r\in [c]$, taking $\phi \equiv1$ we obtain
\begin{align}
\mathcal T_r^{(m)}[W,1,{\boldsymbol f}](x)
    =\int_{[0,1]^{v-1}} W\left(x, x_2, \ldots, x_v\right) \prod_{a=2}^v d x_a=:\mathcal{V}[W](x),
\end{align}
where we use the fact that ${\boldsymbol{f}}\in \mathcal{F}_c$.
Moreover, defining $\mathbf{1}_r:[c]^v\to\mathbb{R}$ as
\begin{align}
 \mathbf{1}_r(x_1,\ldots,x_v):=\mathbf{1}_{\{x_1=\ldots, x_v=r\}},  
\end{align}
for all $m\in [v]$ we have,
\begin{align}
   \mathcal{T}_r^{(m)}[W,\mathbf{1}_r,{\boldsymbol f}](x)=\int_{[0,1]^{v-1}} W\left(x, x_2, \ldots, x_v\right) \prod_{a=2}^v f_r(x_a)\prod_{a=2}^vd x_a=:\mathcal{V}_r[W,{\boldsymbol{f} }](x). 
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:18:19.216421+00:00","domain":"probability theory","id":"claim_5d3e3ee136a61fb8d16f50ebcc8a8d300a23ff67601f7ebeef34bbec68db0ecd","kind":"definition","schema_version":1,"statement":"[Definition 8 (\cite{Aguiar2010}) of arXiv:2608.29075, 'The 2-Monoidal Structure of Symmetric Sequences'] A \textit{2-monoidal category} is a 5-tuple $(\C,\square,I,\circ,J)$ where $(\C,\square,I)$ and $(\C,\circ,J)$ are monoidal categories with units $I$ and $J$ respectively, along with a transformation (called the interchange law) $$\zeta_{A,B,C,D}: (A \circ B) \square (C \circ D) \rightarrow (A \square C) \circ (B \square D)$$ that is natural in $A,B,C$, and $D$, and three morphisms $$\Delta_I: I \rightarrow I \circ I, \quad \mu_J: J \square J \rightarrow J, \quad \iota_J = \epsilon_I: I \rightarrow J,$$ such that the axioms below are satisfied.

    \textbf{Associativity.} The following diagrams commute.
\begin{equation}
\begin{tikzcd}
	{\Big((A \circ B)\square (C \circ D)\Big) \square (E \circ F)} & {(A \circ B)\square \Big((C \circ D) \square (E \circ F)\Big)} \\
	{\Big((A \square C)\circ (B \square D)\Big) \square (E \circ F)} & {(A \circ B) \square \Big((C \square E) \circ (D \square F)\Big)} \\
	{\Big((A \square C) \square E\Big) \circ \Big((B \square D) \square F\Big)} & {\Big(A \square (C \square E)\Big) \circ \Big(B \square (D \square F)\Big)}
	\arrow["{\scriptscriptstyle a^\square}", from=1-1, to=1-2]
	\arrow["{\scriptscriptstyle \zeta \square (\id \circ \id)}"', from=1-1, to=2-1]
	\arrow["{\scriptscriptstyle (\id \circ \id) \square \zeta}", from=1-2, to=2-2]
	\arrow["{\scriptscriptstyle \zeta}"', from=2-1, to=3-1]
	\arrow["{\scriptscriptstyle \zeta}", from=2-2, to=3-2]
	\arrow["{\scriptscriptstyle a^\square \circ a^\square}"', from=3-1, to=3-2]
\end{tikzcd}\end{equation}

\begin{equation}
\begin{tikzcd}
	{\Big((A \circ B)\circ C\Big) \square \Big((D \circ E) \circ F\Big)} & {\Big(A \circ (B\circ C)\Big) \square \Big(D \circ (E \circ F)\Big)} \\
	{\Big((A \circ B) \square (D \circ E)\Big) \circ (C \square F)} & {(A \square D) \circ \Big((B \circ C) \square (E \circ F)\Big)} \\
	{\Big((A \square D) \circ (B \square E)\Big) \circ (C \square F)} & {(A \square D) \circ \Big((B \square E) \circ (C \square F)\Big)}
	\arrow["{\scriptscriptstyle a^\circ \square a^\circ}", from=1-1, to=1-2]
	\arrow["{\scriptscriptstyle \zeta}"', from=1-1, to=2-1]
	\arrow["{\scriptscriptstyle \zeta}", from=1-2, to=2-2]
	\arrow["{\scriptscriptstyle \zeta \circ (\id \square \id)}"', from=2-1, to=3-1]
	\arrow["{\scriptscriptstyle (\id \square \id) \circ \zeta}", from=2-2, to=3-2]
	\arrow["{\scriptscriptstyle a^\circ}"', from=3-1, to=3-2]
\end{tikzcd}\end{equation}

\textbf{Unitality.} The following diagrams commute.
\begin{equation}
\begin{tikzcd}
	{I \square (A \circ B)} & {(I \circ I)\square(A \circ B)} && {(A \circ B) \square I} & {(A \circ B)\square (I \circ I)} \\
	{A \circ B} & {(I \square A) \circ (I \square B)} && {A \circ B} & {(A \square I) \circ (B \square I)}
	\arrow["{\scriptscriptstyle \Delta_I \square (\id \circ \id)}", from=1-1, to=1-2]
	\arrow["{\scriptscriptstyle \zeta}", from=1-2, to=2-2]
	\arrow["{\scriptscriptstyle (\id \circ \id) \square \Delta_I}", from=1-4, to=1-5]
	\arrow["{\scriptscriptstyle \zeta}", from=1-5, to=2-5]
	\arrow["{\scriptscriptstyle l^\square_{A \circ B}}", from=2-1, to=1-1]
	\arrow["{\scriptscriptstyle l^\square_A \circ l^\square_B}"', from=2-1, to=2-2]
	\arrow["{\scriptscriptstyle r^\square_{A \circ B}}", from=2-4, to=1-4]
	\arrow["{\scriptscriptstyle r^\square_A \circ r^\square_B}"', from=2-4, to=2-5]
\end{tikzcd}\end{equation}

\begin{equation}
\begin{tikzcd}
	{J \circ (A \square B)} & {(J \square J) \circ (A \square B)} && {(A \square B)\circ J} & {(A \square B) \circ (J \square J)} \\
	{A \square B} & {(J \circ A) \square (J \circ B)} && {A \square B} & { (A \circ J) \square (B \circ J)}
	\arrow["{\scriptscriptstyle \mu_J \circ (\id \square \id)}"', from=1-2, to=1-1]
	\arrow["{\scriptscriptstyle (\id \square \id) \circ \mu_J}"', from=1-5, to=1-4]
	\arrow["{\scriptscriptstyle l^\circ_{A \square B}}", from=2-1, to=1-1]
	\arrow["{\scriptscriptstyle l^\circ_A \square l^\circ_B}"', from=2-1, to=2-2]
	\arrow["{\scriptscriptstyle \zeta}"', from=2-2, to=1-2]
	\arrow["{\scriptscriptstyle r^\circ_{A \square B}}"","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:57:07.184108+00:00","domain":"probability theory","id":"claim_5d3f86e48aae48f9888316d4f3792e8defb26c69d4bc2228e16651af312a3cc5","kind":"concept","schema_version":1,"statement":"[Theorem thm:DimConnComp of arXiv:2508.08150, 'Recent Progress on Fractal Percolation'] {BromanCamiaJoostenMeester_DimConnectedComponent} }]
For any $d\geq 2$, $N\geq 2$ and $p\geq p_d(N)$, almost surely
\begin{equation*}
	\dim_{\mathrm{B}}  F^c = \dim_{\mathrm{B}}  F =\dim_{\mathrm{H}}  F.
