{"assumptions":[],"created_at":"2026-10-26T20:58:53.185105+00:00","domain":"probability theory","id":"claim_5d6e00b172f5054c979cbb33ba65ff8d354c4ec370fe69a0da3fdca99b9e65cd","kind":"concept","schema_version":1,"statement":"[Cor 9 of arXiv:2606.30349, 'Attenuated Poisson Dirichlet approximations for divisibility configurations'] Define
