		\begin{equation}
			\mathbb{Q}(\lambda_*\le\lambda)\le C_*\exp\bigl(-c_* (\log(1/\lambda))^\sigma\bigr)\qquad\text{for every }\lambda\in(0,1]\, .
		\end{equation}","status":"unverified"}

