$$
In particular,
$$
\#\{u\in\mathcal T^n: G_{k_n}(\mathcal T^n_u)=1\}
\quad \mathop{\longrightarrow}^{(\P)}_{n \rightarrow \infty} \quad \infty.
$$
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:25:40.047251+00:00","domain":"probability theory","id":"claim_5dea2444484891ad767567da295c041d4539a393c6755b47aa42a55c2dc064eb","kind":"theorem","schema_version":1,"statement":"[Prop 15 of arXiv:2510.24562, 'Hard wall repulsion for the discrete Gaussian free field in random environment on $\mathbb'] For $\bbQ$-a.e.\ $\omega\in\Omega_{\lambda,\Lambda}$
