{"assumptions":[],"created_at":"2026-10-27T12:17:13.063448+00:00","domain":"probability theory","id":"claim_5dedd758baf88982f7904678568891643f643a555640873e2189330dc55fad89","kind":"lemma","schema_version":1,"statement":"[Lem Dbaseint2 of arXiv:2508.04954, 'Conditional exponential directed last passage percolation under a one-point upper large de'] For $\mathbf{n}=(n_1, n_2, n_3)\in {\mathbb N}^3$ and $L>0$, 
\begin{equation*}
    \mathsf{Q}^{(\mathbf{n})}_{L} 
    = (-1)^{|\mathbf{n}|}  \sum_{i=0 \vee (2n_2-n_1+1)}^{2n_2} \sum_{j=0 \vee (2n_3-n_2+1)}^{2n_3}  
    \left[ \oint_{>1}  \frac{(z_1+1)^{n_1-n_{2}-1}}{z_1^{n_{2}-i+1}} \frac{\mathrm{d} z_1}{2\pi \mathrm{i}} \right]  
    \left[ \oint_{>1} \frac{(z_2+1)^{n_2-n_{3}-1}}{z_2^{n_{3}-j+1}} \frac{\mathrm{d} z_2}{2\pi \mathrm{i}} \right]
    \alpha_{ij} 
\end{equation*}
where $\alpha_{ij}$ is a sum of $\binom{2n_2}{i}\binom{2n_3}{j}$ terms,  each of the form $\mathrm I^{{\boldsymbol \sigma}}_{{\boldsymbol \tau}}$ with ${\boldsymbol \sigma}, {\boldsymbol \tau}\in \mathcal S_{\mb{n}}$ specified by
\begin{equation} 
    {\boldsymbol \sigma}= 3^{n_{31}} 2^{n_{21}} 1^{n_1} 2^{n_{22}} 3^{n_{32}}, 
    \qquad     {\boldsymbol \tau} = 3^{n_{31}'} 2^{n'_{21}} 1^{n_1} 2^{n_{22}'} 3^{n_{32}'} 
\end{equation}
for $n_{21}, n_{22}, n_{31}, n_{32},n_{21}', n_{22}', n_{31}', n_{32}'\in {\mathbb N}_0$ subject to the constraints  
\begin{equation*} \begin{split}
	n_{21}+n_{22}=n_{21}'+n_{22}'=n_2, \quad 
	n_{31}+n_{32}= n_{31}'+n_{32}'= n_3, \quad
	n_{22} + n'_{22} = i, \quad
	n_{32} + n_{32}' = j.
\end{split} \end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:28:34.924017+00:00","domain":"probability theory","id":"claim_5deef2fc1d5255719031ae16b43ec84e9700bb6620e51e36cd805e67b3b1413c","kind":"lemma","schema_version":1,"statement":"[Lemma lemma_revise_B1 of arXiv:2412.05706, 'Quasi-multiplicativity and regularity for metric graph Gaussian free fields'] For any $x\in \mathbb{Z}^d$ and disjoint $A,D\subset \widetilde{\mathbb{Z}}^d\setminus \widetilde{B}_x(2)$,
