{"assumptions":[],"created_at":"2026-10-27T17:43:53.645974+00:00","domain":"probability theory","id":"claim_5e6cf83535ec83ecb7b22c40c8bada06201bf81eb40df91538f12219104997d8","kind":"theorem","schema_version":1,"statement":"[Corollary cor:useful-bound of arXiv:2512.17747, 'On exponentially height-penalized random trees'] Let $\alpha\in\mathbb R$ be a real number and $B,\Gamma$ be two continuous functions.
    Define the function
    \begin{align*}
        F_t(x,y)=\frac{t^\alpha}{B(x)}\exp\left(-\frac{t}{\Gamma(y)}\right)\,.
    \end{align*}
    Assume that $B,\Gamma$ are strictly positive on $(0,a_+]$ and that there exists $C_\beta,C_\gamma>0$ and $\beta,\gamma>0$ such that $B(x)\sim C_\beta x^\beta$ and $\Gamma(x)\sim C_\gamma x^\gamma$ when $x\rightarrow0$.
    Then, for any $\epsilon=\epsilon(t)$ converging to $0$ as $t$ diverges and $\Tilde{a}_+=\Tilde{a}_+(t)\leq a_+$, there exists $k=k(t)$ an integer depending on $t$ and a sequence of increasing values $(a_0\leq\ldots\leq a_k)$ (implicitly depending on $t$) such that $a_0=\epsilon$, $a_k=\Tilde{a}_+$, and satisfying
    \begin{align*}
        \lim_{t\rightarrow\infty}\sum_{i=1}^kF_t(a_{i-1},a_i)=0\,.
    \end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:46:36.162220+00:00","domain":"probability theory","id":"claim_5e6d5881990f2fc74580ea693da58cd5fdf53cbd0bfc6fb123ce46ec9ad1ffcd","kind":"theorem","schema_version":1,"statement":"[Prop Prop_TotallyReal=>UniformlyFredholm of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] Let $({\mathbf{B}},f,{\mathbf{V}})$ be a family of local residue conditions such that
  for every $b \in {\mathbf{B}}$, $x \in Z_b$, and $v \in T_xZ_b {\backslash}\set{0}$
  \begin{equation*}
    {\mathbf{V}}_{(b,x)} \oplus J_{{\mathbf{p}}_b}\gamma(v) {\mathbf{V}}_{(b,x)} = \check S_{{\mathbf{p}}_b,x}.
  \end{equation*}
  Denote by $({\mathbf{B}},f,{\mathbf{R}})$ the corresponding family of residue conditions.
  If ${\mathfrak a} \mskip0.5mu\colon\thinspace f^*\mathbf{F} \to f^*\mathbf{F}$ is a map of tame Fréchet bundles of order zero,
  then
  \begin{equation*}
    {\mathbf{D}}_{\mathbf{R}} + {\mathfrak a} \mskip0.5mu\colon\thinspace \mathbf{E}_{\mathbf{R}} \to f^*\mathbf{F}
  \end{equation*}
  is uniformly Fredholm.
  Moreover,
  for every $b_0 \in {\mathbf{B}}$
  the maps $\pi \mskip0.5mu\colon\thinspace \mathbf{E}_{\mathbf{R}}|_\mathscr{U} \to \mathrm{Def}$ and $\iota \mskip0.5mu\colon\thinspace \mathrm{Ob} \hookrightarrow f^*\mathbf{F}|_\mathscr{U}$ in (Def_LinearUniformlyFredholm of the paper) can be chosen such that there is a compact subset $K \subseteq X$ such that for every
  $b \in \mathscr{U}$
  the following hold:
  \begin{enumerate}
  \item
    $K \subseteq X{\backslash} Z_b$;
  \item
    if $\phi \in \mathbf{E}_{{\mathbf{R}},b}$ has $\supp(\phi) \cap K = \varnothing$, then $\pi(\phi) = 0$; and
  \item  
    $\supp(\iota(o)) \subseteq K$ for every $o \in \mathrm{Ob}_b$.
  \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:37:09.015836+00:00","domain":"probability theory","id":"claim_5e6e35fa53c013ed01c4b0744305f879b23c2837dedff0514fa83386613c5c08","kind":"concept","schema_version":1,"statement":"[Lemma lem:fibre_difference of arXiv:2609.01697, 'Unique ergodicity of projective cocycles over the 2D stochastic Navier--Stokes equations'] Let $w^1, w^2 \in C([0,T]; \mathcal{H}) \cap L^2([0,T]; H^1)$ be two base paths and let $\pi^1, \pi^2 \in C([0,T]; \mathbb{S}) \cap L^2([0,T]; H^1)$ solve the projective equation~(equation eq:proj-spde of the paper) over $w^1$ and over $w^2$ respectively. Then:
  \begin{enumerate}[label=(\roman*)]
    \item For $i \in \{1,2\}$ the Dirichlet quotient of $\pi^i$ obeys
      \begin{equation}
        \frac{\mathrm{\,d}}{\mathrm{\,d} t} \|\pi^i_t\|_{H^1}^2
        \ \leqslant\ C \|w^i_t\|_{H^1}^2  \|\pi^i_t\|_{H^1}^2   ,
      \end{equation}
      and consequently
      \begin{equation}
        \sup_{t \leqslant T} \|\pi^i_t\|_{H^1}^2
        \ \leqslant\  \|\pi^i_0\|_{H^1}^2 
        \exp\Bigl( C \int_0^T \|w^i_r\|_{H^1}^2 \mathrm{\,d} r \Bigr) .
      \end{equation}
    \item Write $\tilde w \overset{\mathrm{\scriptscriptstyle def}}{=} w^1 - w^2$ and $\tilde\pi \overset{\mathrm{\scriptscriptstyle def}}{=} \pi^1 - \pi^2$. Then
      \begin{equation}
        \frac{\mathrm{\,d}}{\mathrm{\,d} t} \|\tilde\pi_t\|^2 + \|\nabla \tilde\pi_t\|^2
        \ \leqslant\ C\bigl( \Gamma^1_t + \Gamma^2_t \bigr) \|\tilde\pi_t\|^2
        + C \|\pi^2_t\|_{H^1}^2 \|\tilde w_t\|^2 + C \|\tilde w_t\|_{H^1}^2 ,
      \end{equation}
      with $\Gamma^i$ the quantity~(equation eq:gamma_r of the paper) computed on $(w^i, \pi^i)$, and, with $A_T \overset{\mathrm{\scriptscriptstyle def}}{=} C\int_0^T \bigl( \Gamma^1_r + \Gamma^2_r \bigr) \mathrm{\,d} r$,
      \begin{equation}
        \sup_{t \leqslant T} \|\tilde\pi_t\|^2 + \int_0^T \|\nabla \tilde\pi_r\|^2 \mathrm{\,d} r
        \ \leqslant\ 2 e^{A_T} \Bigl( \|\tilde\pi_0\|^2
          + C \int_0^T \bigl( \|\pi^2_r\|_{H^1}^2 \|\tilde w_r\|^2
        + \|\tilde w_r\|_{H^1}^2 \bigr) \mathrm{\,d} r \Bigr) .
      \end{equation}
  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T16:45:10.089287+00:00","domain":"probability theory","id":"claim_5e6e8bacba93101d8f94a4707b0a3041e3a3217e472eb00d8228ce093b9f2fc2","kind":"concept","schema_version":1,"statement":"[Theorem thm.speis of arXiv:2504.19553, 'Extremal Ising Gibbs States on Lobachevsky lattices'] Let ${\rm IC}_G$ be the isoperimetric constant of the {connected, transitive and locally finite graph $G$}. If the following sparsity condition holds
