	\infty \quad & \text{ otherwise,}
\end{cases}
\end{equation} 
so that{\hypersetup{linkcolor=black}\footnote{The choice to write the measure relative to $\d\l_2 \otimes \d\l_2$ rather than $\d\l \otimes \d\l$ is arbitrary for now but will be useful later on.}}
\[
	(\d\l \otimes \d\l)(\vp,\vp') = \exp( -\I(\vpp,\vpm)) (\d\l_2 \otimes \d\l_2)(\vpp,\vpm).
\]","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:00:22.777397+00:00","domain":"probability theory","id":"claim_5e74151bc3604bb46e924672e00e7cff3a4afb4b2002dc8ac0752964451ea6a3","kind":"theorem","schema_version":1,"statement":"[Corollary of arXiv:2411.01467, 'Conformal covariance of connection probabilities \\ in the 2D critical FK-Ising model'] Assume the same setup as in Theorem~(thm::cvg_proba of the paper). Consider the critical Ising model on $\Omega^a$ with free\footnote{The boundary condition here is not essential. We can change to, for instance, $\oplus$ boundary condition or alternating $\oplus/{\mathrm{free}}$ boundary conditions.} boundary condition and denote by $\mathbb{E}^a_{\Omega}$ the corresponding expectation. Then 
	\begin{equation*}
		\langle \sigma_{z_1}\ldots\sigma_{z_n}\rangle_{\Omega}:=\lim_{a\to 0}a^{-\frac{n}{8}} \times \mathbb{E}^a_{\Omega}\left[\sigma_{z_1^a}\ldots\sigma_{z_n^a}\right]
	\end{equation*}
	exists and belongs to $[0,\infty)$. The limit equals $0$ if and only if $n$ is odd. Moreover, $\langle \sigma_{z_1}\cdots\sigma_{z_n}\rangle_{\Omega}$ satisfies the same conformal covariance property as in~(equation eqn::conformal_covariance of the paper).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:04:41.052323+00:00","domain":"probability theory","id":"claim_5e74b39f8b601ee831bd6678965c525a844d3acdea30ed077bce1a1ed458017c","kind":"definition","schema_version":1,"statement":"[Definition Corner-flip dynamics of arXiv:2412.04032, 'Cutoff for the mixing time of the Facilitated Exclusion Process'] For $\zeta \in \Omega_{K,P}$ and $k \in \mathbb{T}_K$, define $\zeta^k$ the configuration with a flip at $k$ such that 
\begin{equation}
    \begin{cases}
        \zeta^k_l =\zeta_l \quad \forall \, l \neq k\\
        \zeta^k_k = \zeta_{k+1} + \zeta_{k-1} - \zeta_k.
    \end{cases} 
    \end{equation}
    Then, the corner-flip dynamics on $\Omega_{K,P}$ is the Markov chain such that for all $k$, $\zeta$ goes to $\zeta^k$ at rate 1 and other transitions are not possible.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:46:26.250704+00:00","domain":"probability theory","id":"claim_5e763b8128b104d3de1e932990f2a1a27d7ce290a4512ac489e46859d75758ad","kind":"concept","schema_version":1,"statement":"[Lemma 4 of arXiv:2605.22760, 'Extremes of Gaussian fields with a product term in the variance'] Assume \ref{ass:variance}--\ref{ass:nondegenerate}, and let \(M>0\).  For every \(\varepsilon>0\), there exists \(\delta>0\) such that, as \(u\to\infty\),
\begin{align}
&\PP\left\{\sup_{\bft\in[0,\delta]^2}X(\bft)>u\right\}
\notag\\
&\quad\le
(1+\varepsilon)\Psi(u)
\biggl[
\calH_\alpha(M)^2
+2\frac{\calH_\alpha(M)^2}{M}u^{2/\alpha}
       \int_0^\delta e^{-(1-\varepsilon)u^2x^\beta}\dd x
\notag\\
&\hspace{7.5em}
+\frac{\calH_\alpha(M)^2}{M^2}u^{4/\alpha}
       \int_0^\delta\int_0^\delta e^{-(1-\varepsilon)u^2V(x,y)}\dd x\dd y
\biggr].
\end{align}
Furthermore, define
\[
        I_\delta(u)=\int_0^\delta\int_0^\delta e^{-u^2V(x,y)}\dd x\dd y .
\]
If \(R_u\to\infty\) and \(R_uq_u=o(u^{-2/\beta})\), then for some function \(\eta(M)\downarrow0\) as \(M\to\infty\),
\begin{align}
&\PP\left\{\sup_{\bft\in[0,\delta]^2}X(\bft)>u\right\}
\notag\\
&\quad\ge
(1-\varepsilon)\frac{\calH_\alpha(M)^2}{M^2}u^{4/\alpha}
\Psi(u)
\int_{R_uq_u}^\delta\int_{R_uq_u}^\delta
      e^{-(1+\varepsilon)u^2V(x,y)}\dd x\dd y
\notag\\
&\hspace{2.5em}
-\eta(M)\Psi(u)u^{4/\alpha}
\int_0^\delta\int_0^\delta e^{-(1-\varepsilon)u^2V(x,y)}\dd x\dd y
+o\left(\Psi(u)u^{4/\alpha}I_\delta(u)\right).
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:51:11.642364+00:00","domain":"probability theory","id":"claim_5e776a2488609d1c15e9961c717fa8339d7e16dc67ca0cfdab3be73181a9359c","kind":"concept","schema_version":1,"statement":"[Theorem 3 of arXiv:2605.31471, 'Convergence Rates of Continuous-Time Random Walks to Time-Fractional Diffusions with Unbou'] Under Assumption \ref{asm:heavy-tail}, the following estimate holds
