{"assumptions":[],"created_at":"2026-10-27T20:53:00.822636+00:00","domain":"probability theory","id":"claim_5e7966d455432b896971a0e8e1cc6d02937bfaf3a18289853ecac8bf3e16c1e2","kind":"definition","schema_version":1,"statement":"[Definition Def: elementary differential trees of arXiv:2607.18635, 'Remainders of generalised Taylor expansions and a priori bounds for rough differential equ'] For $\sigma\in C^\infty(\mathbb{R}^n,\mathbb{R}^n\otimes (\mathbb{R}^d)^\ast)$ we inductively define the \emph{elementary differential} $\Upsilon:{\mathcal T}\to C( \mathbb{R}^n;\mathbb{R}^n)$ by imposing that, for all $z\in\mathbb{R}^n$, 
		$[\Upsilon_{\bullet_j}(z)]^i:=\sigma^i_k(z)$, $i=1,\ldots,n$, $j=1,\ldots,d$, and, for all $\tau_1,\ldots, \tau_k\in{\mathcal T}$,
		\begin{align}
			&[\Upsilon_{[\tau_1\cdots \tau_k]_j}(z)]^i:=\sum_{i_1,\ldots,i_k=1}^n \frac{\partial^k\sigma^i_j(z)}{\partial z_{i_1}
				\cdots \partial z_{i_k}} \, [\Upsilon_{\tau_1}(z)]^{i_1}\cdots [\Upsilon_{\tau_k}(z)]^{i_k}\,.
		\end{align}
		We extend it to a map $\Upsilon:{\mathcal F}\to C( \mathbb{R}^n;\mathbb{R}^n)$ as a morphism with respect to the forest product such that $\Upsilon_\one=1$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:30:52.740546+00:00","domain":"probability theory","id":"claim_5e7ce19686e9d0ee7c3e6084237a289d1ac0f2ee552b8d979633e648c4eab895","kind":"theorem","schema_version":1,"statement":"[Corollary 26 of arXiv:2506.10494, 'Geometric Jensen-Shannon Divergence Between Gaussian Measures On Hilbert Space'] Let $S,T \in \SymHS(\Hcal)_{< I}$. Let
	$\mu = \Ncal(0,Q)$, $Q = C_0^{1/2}(I-S)C_0^{1/2}$, $\nu = \Ncal(0,R)$, $R = C_0^{1/2}(I-T)C_0^{1/2}$.
	Then 
	\begin{align}

		&\left\la \log\left\{{\frac{d\mu}{d\mu_0}(x)}\right\}, \log\left\{{\frac{d\nu}{d\mu_0}(x)}\right\}\right\ra_{\Lcal^2(\Hcal,\mu_0)} =  \frac{1}{2}\la S(I-S)^{-1}, T(I-T)^{-1}\ra_{\HS}
		\nonumber
		\\
		& \quad \quad \quad \quad \quad \quad + \frac{1}{4}\log\dettwo[(I-S)^{-1}]\log\dettwo[(I-T)^{-1}].
		\\
		&\left\| \log\left\{{\frac{d\mu}{d\mu_0}(x)}\right\}\right\|^2_{\Lcal^2(\Hcal,\mu_0)}=
		\frac{1}{2}||S(I-S)^{-1}||^2_{\HS}
		+ \frac{1}{4}(\log\dettwo[(I-S)^{-1}])^2.
		\\
		&\left\| \log\left\{{\frac{d\mu}{d\mu_0}(x)}\right\}- \log\left\{{\frac{d\nu}{d\mu_0}(x)}\right\}\right\|^2_{\Lcal^2(\Hcal,\mu_0)}=
		\frac{1}{2}||S(I-S)^{-1}-T(I-T)^{-1}||^2_{\HS}
		\nonumber
		\\
		& \quad \quad \quad \quad \quad \quad + \frac{1}{4}(\log\dettwo[(I-S)^{-1}] - \log\dettwo[(I-T)^{-1}])^2.

	\end{align}
	Furthermore,
	\begin{align}

		&\left\| \log\left\{{\frac{d\mu}{d\mu_0}(x)}\right\}- \log\left\{{\frac{d\nu}{d\mu_0}(x)}\right\}\right\|^2_{\Lcal^2(\Hcal,\mu_0)}

		\\
		&\leq \left(\frac{1}{2} + \frac{1}{4}[||S||_{\HS} + ||T||_{\HS} + ||ST||_{\HS}]^2\right)||(I-S)^{-1}||^2||(I-T)^{-1}||^2||S-T||^2_{\HS}.
		\nonumber
	\end{align}","status":"unverified"}

